window.AKS=[{"secs":[{"c":"Mở đầu","t":"Bàn tay trong bóng tối","p":["Có một giọng nói ở nơi không có ánh sáng.","@cg:bg_0_babel","Nó không vang lên từ đâu cả. Nó chỉ ở đó, như thể đã chờ sẵn từ rất lâu, kiên nhẫn như mặt nước đọng.","“À, là ngươi.”","“Đã lâu lắm rồi chúng ta mới gặp lại nhau. Suốt quãng thời gian ấy, ngươi cứ chênh vênh bên mép vực.”","@cg:bg_0_am","“Ngươi có thể quên mình là ai. Chỉ cần nhớ được tên mình thôi, thế là đủ.”","Một quãng lặng. Rồi giọng nói lại tiếp, lần này gấp gáp hơn, như người tiễn khách đã đến giờ phải đóng cửa.","“Đến lúc rồi. Đừng nán lại đây lâu. Ngươi vẫn chưa phải khách của ta, và lẽ ra ngươi cũng không nên có mặt ở chốn này.”","@cg:avg_0_2","“Cô bé ấy vẫn cần ngươi.”","“Ngày hai mươi ba tháng Mười hai. Có lẽ ngươi không còn nhớ ngày ấy có ý nghĩa gì với mình. Và chính điều đó sẽ đẩy ngươi vào hiểm cảnh.”","@cg:avg_0_1","“…Không. Ngươi phải cố mà nhớ.”","","Những âm thanh khác tràn vào, vỡ vụn như sóng radio chập chờn.","“…ý thức…”","“Tuần hoàn đã phục hồi… sinh hiệu ổn định… đã bơm dung dịch liệt tim…”","“Thân nhiệt thấp… tiêm Hexamethasone hai mươi cc, ngay…”","“Kẹp cầm máu!”","“…Tình trạng ổn định… bắt đầu cắt bỏ… cẩn thận rung thất…”","Và giữa những mệnh lệnh khô khốc ấy, có một tiếng thì thầm rất khẽ, khẽ đến mức gần như không thuộc về căn phòng.","“…Xin lỗi. Vì lại bắt người phải chịu khổ thêm lần nữa.”","Rồi một giọng khác, trong trẻo và run rẩy, gọi mãi một cái tên.","“Doctor… Đưa tay đây! Nắm lấy tay em…! Nắm lấy tay em đi!!”","Trong bóng tối, có ai đó đã nắm lấy."],"bg":"bg_indoor_1","cast":[["Amiya","op:char_002_amiya"]]},{"c":"Mở đầu","t":"Kẻ không tên tỉnh giấc","p":["“Y tá, Doctor sao rồi? Vừa nãy… vừa nãy bọn em còn nắm tay nhau mà… Sao Doctor vẫn chưa tỉnh…?”","“Amiya! Đừng hoảng, bình tĩnh lại đã!”","Cô bé tên Amiya giật mình, lí nhí xin lỗi. Người nhân viên y tế thở dài, giọng vừa trách vừa thương.","“Hễ cứ dính đến Doctor là em lại rối hết cả lên. Nhưng Amiya này… nếu điều tồi tệ nhất xảy ra, em sẽ làm gì?”","“…Em đã chuẩn bị tinh thần rồi. Chúng ta sẽ tiếp tục làm theo kế hoạch.”","Câu trả lời bình tĩnh đến lạ, bình tĩnh theo kiểu của người đã tự nhủ điều ấy hàng trăm lần trước gương. Người y tá im lặng một lúc, rồi cúi xuống kiểm tra thêm lần nữa: nhịp thở hơi nông, huyết áp bình thường, không có gì đáng lo.","Và đúng lúc ấy, đôi mắt dưới lớp mũ trùm khẽ mở.","Ánh sáng đầu tiên chói như kim châm. Thế giới là một mảng trần nhà xám bạc, những ống dẫn chằng chịt, mùi thuốc sát trùng, và một gương mặt cô bé đang cúi sát xuống. Đôi tai thỏ dài rủ xuống hai bên, đôi mắt xanh lục mở to như không tin nổi.","“Amiya, thành công rồi! Doctor tỉnh rồi!”","“Doctor…?” Cô bé nghẹn lại. “Em mừng quá… Doctor…”","“Ấy, cẩn thận! Đừng cử động vội. Cơ thể vẫn chưa thích nghi được đâu.”","Doctor không cử động. Không phải vì nghe lời, mà vì không biết phải cử động để làm gì. Trong đầu chỉ có một khoảng trắng, trơn nhẵn như mặt kính, không một vết xước, không một ký ức nào để bám vào.","“Cô… là ai?”","Câu hỏi bật ra khàn đặc. Gương mặt cô bé thoáng cứng lại, chỉ trong một khắc rất ngắn, rồi lại dịu xuống.","“Là em đây, Doctor. Em là Amiya. Bọn em đến để cứu Doctor.”","“…Còn tôi… là ai?”","“Doctor là người của Rhodes Island, giống như bọn em…” Amiya ngừng lại, như đang chọn từng chữ. “…và là cộng sự của em. Doctor là người quan trọng nhất đối với em.”","Cô bé nhìn Doctor thật lâu, và Doctor hiểu, bằng một thứ trực giác không cần đến ký ức, rằng cô bé đang chờ một dấu hiệu, chỉ một cái nhíu mày hay một ánh mắt nhận ra. Nhưng chẳng có gì cả.","“Em hiểu,” Amiya nói khẽ. “Em biết chuyện này quá sức với Doctor lúc này. Em không mong Doctor nhớ lại ngay, cũng không đòi Doctor phải tin em ngay.”","Cô bé cố mỉm cười.","“Có lẽ nhiều thứ đã thay đổi so với trước kia, kể cả em. Nhưng Doctor sẽ luôn là người quan trọng nhất với em. Dù có chuyện gì xảy ra, điều đó sẽ không bao giờ thay đổi. Cho nên… xin Doctor hãy cho em thêm một chút thời gian. Dù chỉ một chút thôi cũng được.”","Bọn em đã hy sinh quá nhiều chỉ để tìm được Doctor. Câu ấy cô bé không nói ra, nhưng nó lơ lửng trong không khí, nặng trĩu.","“Đây là đâu…?” Doctor hỏi.","“Ở đây an toàn—”","@cg:avg_0_3","Câu trả lời bị cắt ngang bởi tiếng va đập dữ dội từ ngoài hành lang."],"bg":"bg_indoor_1","cast":[["Amiya","op:char_002_amiya"],["Heavily-Armed Man","npc:char_013_riop"]]},{"c":"Mở đầu","t":"Mệnh lệnh đầu tiên","p":["Một người đàn ông mang giáp nặng lao vào, hơi thở dồn dập.","“Amiya, có chuyện rồi! Có kẻ đột nhập cơ sở! Nhìn cách ăn mặc… không giống lính Ursus!”","Sau lưng anh ta, bóng người đeo mặt nạ trắng đã tràn qua cửa. Không một lời cảnh báo, không một yêu sách. Chỉ có vũ khí giương lên.","“Mọi người cẩn thận! Tìm chỗ nấp, bảo vệ Doctor!” Amiya hét lên, rồi khựng lại khi nhìn rõ đồng phục của đối phương. “Trang phục này… là Reunion Movement sao? Nhưng sao có thể…”","Người lính gác nghiến răng. “Chết tiệt… bọn chúng nhắm vào Doctor à?!”","“Không… lẽ ra không ai khác biết Doctor đang ở đây.” Amiya quay sang. “Liên lạc được với Kal’tsit không?”","“Không hiểu sao thiết bị không hoạt động!”","“…Có kẻ đã cắt đứt liên lạc của chúng ta.” Đôi tai thỏ của cô bé dựng lên, căng như dây đàn. “Kal’tsit không thể chỉ huy trận này như kế hoạch nữa rồi.”","Rồi Amiya làm một điều khiến người y tá sững sờ: cô bé quay lại, nhìn thẳng vào Doctor vẫn còn ngồi trên giường bệnh.","“Doctor. Em mong… Doctor có thể nắm quyền chỉ huy.”","“Như vậy có liều quá không? Doctor vừa mới tỉnh lại…”","“Em muốn thử.” Giọng Amiya không run nữa. “Dù không còn ký ức, Doctor đã từng chiến đấu cùng bọn em. Bọn em đã cùng nhau đi qua biết bao nhiêu chuyện. Em tin Doctor làm được.”","Ở đâu đó rất sâu, rất xa, như vọng lại từ một đời khác, có những giọng nói lạ mà quen: <i>Cảm ơn người đã luôn dẫn dắt chúng tôi… Tôi biết người sẽ dẫn chúng tôi đến chiến thắng.</i>","“Em biết đòi hỏi này đột ngột và ích kỷ lắm,” Amiya nói. “Nhưng xin Doctor, hãy giúp bọn em. Bọn em sẽ hỗ trợ Doctor!”","Doctor nhìn những bóng mặt nạ trắng đang tiến lại gần, nhìn cô bé thỏ đứng chắn phía trước, nhìn những con người xa lạ đang chờ một mệnh lệnh. Không có ký ức nào để dựa vào. Nhưng có một thứ khác, lạnh và rõ ràng như những đường kẻ trên bàn cờ, bắt đầu hiện lên trong đầu: khoảng cách, góc bắn, điểm nghẽn, thứ tự.","“Đẩy lùi chúng trước đã.”","Amiya mỉm cười. Lần đầu tiên kể từ lúc Doctor mở mắt, nụ cười ấy không gượng gạo.","“Em không muốn kéo Doctor vào chuyện này. Nhưng ngay lúc này, bọn em cần trí tuệ của Doctor hơn bao giờ hết. Em hy vọng giữa trận chiến, một phần nào đó trong Doctor sẽ thức tỉnh.” Cô bé hít một hơi. “Dù Doctor có nghi ngờ chính mình… em vẫn tin Doctor.”","“Xin hãy chỉ huy… Rhodes Island!”"],"bg":"bg_indoor_1","cast":[["Dobermann","npc:char_130_doberm_ex"],["Amiya","op:char_002_amiya"]]},{"c":"Mở đầu","t":"Chào mừng trở về","p":["Trận chiến kết thúc nhanh hơn bất cứ ai tưởng.","“Tên cuối cùng!” Người lính gác hạ khiên, thở hắt ra. “Mục tiêu đã bị hạ. Địch đang rút lui! Mệnh lệnh của Doctor hoàn hảo đúng như Amiya nói. Yên tâm thật!”","@cg:avg_map_1","“Thấy chưa, cũng không đến nỗi nào, đúng không Doctor?” Amiya nói, giọng nhẹ hẳn. “So với những gì Doctor từng trải qua, chuyện này chỉ như đi dạo thôi.”","Một tên Reunion gục dưới đất vẫn cố ngóc đầu lên, ho sặc sụa. “Các người… không phải người Ursus… Bọn ta sẽ không để các người cản đường!”","Hắn với tay về phía vũ khí, nhưng một bóng người đã ập đến trước.","“Đừng hòng!”","“Huấn luyện viên!”","Người phụ nữ tóc ngắn, đôi tai nhọn dựng đứng của giống Perro, trừng mắt nhìn người lính gác vừa lơ là. “Còn đứng ngẩn ra đó làm gì? Suýt nữa thì mất mạng rồi! Nhanh, về đội hình!”","“Rõ!”","“Dobermann! Chị đến rồi!” Amiya reo lên.","Dobermann, đội trưởng Đội tác chiến E1 của Rhodes Island, không có thời gian cho những lời chào hỏi. Đội của cô cũng vừa bị Reunion tập kích, và cô đã chạy thẳng tới đây ngay khi có thể.","“Một tổ chức toàn người Infected,” cô nói, giọng như nhai sỏi. “Tôi vẫn luôn thấy bọn họ hơi cực đoan. Giờ thì dùng đến bạo lực, mà lại ngay trong một thành phố Ursus? Đúng là tự tìm đường chết. Tình hình từ giờ chỉ có loạn hơn thôi. Amiya, chúng ta phải rời khỏi Chernobog ngay.”","Rồi ánh mắt sắc lẹm của cô dừng lại trên người khoác áo trùm đầu đứng cạnh Amiya.","@cg:bg_2_call","“…Còn đây là Doctor?”","“Vâng. Nhưng mà… Dobermann, Doctor đang không được ổn lắm.” Amiya ngập ngừng. “Nói ngắn gọn thì… Doctor bị mất trí nhớ.”","“Mất trí nhớ?” Dobermann nhíu mày. “Vậy giờ tính sao? Chẳng phải cô định chuyển giao quyền lãnh đạo cho—”","“Doctor vẫn còn khả năng chỉ huy. Ít nhất, em đã xác nhận điều đó qua trận vừa rồi.”","Một quãng lặng dài.","“Tôi không thể dễ dàng tin một người lạ,” Dobermann nói. “Nhưng tôi tin cô, Amiya.”","Cô quay sang Doctor, giọng đều đều như đọc lệnh.","“Doctor, chắc người không biết tôi là ai, nhưng người biết Amiya. Tôi là Dobermann, đội trưởng Đội tác chiến E1. Chúng tôi sẽ hộ tống người rời khỏi Chernobog, thành phố Ursus mà ta đang đứng, để trở về Rhodes Island. Ta đang ở một cơ sở bỏ hoang trong thành phố, giờ phải đi về phía tây.”","“Vì mất liên lạc với Kal’tsit,” Amiya giải thích thêm, “em và Dobermann sẽ dẫn các đội riêng đến điểm hẹn ở phía tây, rồi mới xác nhận tín hiệu rút lui. Nếu mọi việc đúng kế hoạch.”","“Được như vậy thì tốt.” Dobermann nhìn lên bầu trời qua ô cửa vỡ. “Hôm nay là cơ hội cuối cùng để đưa người ra khỏi đây, Doctor. Nhưng… tôi có linh cảm chẳng lành.”","Đúng lúc ấy, người y tá hớt hải chạy tới, tay cầm thiết bị liên lạc. “A-Amiya! Có cuộc gọi từ Rhodes Island!”","“Liên lạc thông rồi sao? Là bác sĩ Kal’tsit…?”","“Rất tiếc, không hẳn.” Một giọng nói điềm tĩnh, không mang cảm xúc, vang lên từ thiết bị. “Hệ thống Yêu cầu Kết nối Thần kinh Khẩn cấp đã được kích hoạt. Phía Rhodes Island cũng phát hiện nhiễu, chỉ có thể kết nối một phần mạng thần kinh. Hiện chưa thể liên lạc với Kal’tsit, người vẫn chưa trở về Rhodes Island. Đã xác nhận các vị an toàn. Nhiệm vụ của tôi hoàn tất.”","“PRTS…?” Amiya thốt lên.","Dobermann lầm bầm một câu chửi thề. PRTS vẫn đều đều: “Nếu không cần kết nối với Rhodes Island, liên lạc sẽ ngắt trong giây lát. Thành thật xin lỗi vì đã làm gián đoạn bữa tiệc của các vị.”","“Khoan, khoan đã! Đừng ngắt, tôi còn cần cậu giúp!” Amiya vội nói, rồi quay sang Doctor. “PRTS cũng là một… cộng sự của chúng ta. Nó sẽ chỉ cho Doctor phải làm gì tiếp theo. Em sẽ kết nối lại Doctor với hệ thống dự phòng của Rhodes Island. Như vậy, chúng ta sẽ có lợi thế trong chiến đấu. Sẽ khác với ra lệnh bằng lời, có thể hơi khó quen, nhưng một khi đã thạo, cả chiến dịch sẽ trơn tru hơn nhiều.”","Cô bé nhìn Doctor, và lần này giọng nói của cô bé thật khẽ.","“…Xin Doctor hãy tin em. Như ngày trước.”","“Yêu cầu xác minh danh tính,” PRTS nói. “Chọn phương thức xác minh.”","“Doctor, nói gì đó đi ạ.”","Doctor không nói gì. Chỉ đưa tay chạm vào giao diện.","“Tôi không rõ vì sao người không lên tiếng, nhưng thao tác chạm vào giao diện là đủ—” PRTS ngừng một nhịp rất ngắn. “—Đã khớp vân tay. Xác minh hoàn tất. Cấp độ bảo mật: 8.”","“Chào mừng trở về, Doctor.”"],"bg":"bg_indoor_1","cast":[["Amiya","op:char_002_amiya"],["Dobermann","npc:char_130_doberm_ex"]]},{"c":"0-1","t":"Sụp đổ","p":["Chernobog đang cháy.","@cg:avg_2_2","Không phải một đám cháy, mà là hàng chục, hàng trăm đốm lửa rải rác khắp các dãy phố, như thể thành phố đã bị ai đó vung tay rắc than hồng lên. Khói đen cuộn lên những mái nhà, quyện với một thứ mây sẫm màu đang đặc dần trên nền trời.","“Sao lại thế này…” Dobermann khựng lại ở đầu ngõ. “Rốt cuộc… chuyện quái gì đang xảy ra?”","Ngoài kia, những bóng mặt nạ trắng đang lùng sục từng căn nhà.","“Lục soát hết! Tao muốn từng phòng một bị lật tung lên!”","“Buông tôi ra…! Không! Các người không được…”","“Giờ mới chống cự à? Muộn rồi, lũ Cherno bẩn thỉu!”","Một người đàn ông bị đè xuống đất, gào lên với vợ: “Chạy đi! Đừng lo cho anh… Cứu… con chúng ta…!” Một đứa trẻ khóc gọi mẹ. Ở cuối phố, lính gác Ursus đang co cụm lại, khiên chắn run lên dưới mưa tên.","“Kệ dân thường! Giữ phòng tuyến trước đã! Lũ mặt nạ kéo đến đông quá!”","“Viện binh đâu?! Bọn ta sắp bị tràn qua rồi…”","Amiya đứng chết lặng. “Sao… Sao Reunion lại làm như vậy…?”","“Sau ngần ấy năm, lũ sói đội lốt cừu cuối cùng cũng nhe nanh,” Dobermann đáp.","“Người Infected… họ đang tấn công quân Ursus,” người y tá thì thào.","“Nhưng sao lại thế?” Một lính gác của Rhodes Island hỏi. “Thách thức chính quyền Ursus kiểu này chẳng khác nào tự sát!”","“Không. Nhìn mức độ dữ dội của đợt tấn công đi. Đây là một chiến dịch có kế hoạch.” Dobermann đảo mắt khắp các ngả đường. “Cái nơi chúng ta cứu Doctor ra lẽ ra là tối mật, vậy mà bọn chúng vẫn lọt vào được. Rất có thể đợt tấn công của Reunion đã lan ra toàn bộ Chernobog.”","“Suỵt!” Amiya ra hiệu. Mọi người nép sát vào tường.","Hai tên Reunion đi ngang qua đầu hẻm.","“Tìm thấy con Cherno nào chạy trốn chưa?”","“Vẫn đang tìm!”","“Tốt. Đừng để sót đứa nào. Lũ súc vật máu lạnh ấy… tao sẽ bắt chúng trả giá cho những gì chúng đã làm với gia đình tao!”","Người y tá bịt chặt miệng, nhưng một tiếng ho vẫn bật ra.","“Cái gì thế?”","Tim tất cả như ngừng đập. Nhưng ánh mắt tên Reunion không hướng về phía họ. Hắn đã thấy một người khác: một phụ nữ ôm con, nấp trong con hẻm bên kia đường.","“Đằng này! Tao tìm thấy rồi!”","Người mẹ thét lên, quỳ sụp xuống. “Tôi xin lỗi! Tôi xin lỗi!! Làm ơn, ít nhất hãy tha cho con tôi!”","Tên Reunion đứng im, vũ khí trong tay.","“…Chúng ta phải ngăn chuyện này lại, ngay bây giờ,” Amiya nói.","“Amiya…”","“Em biết rủi ro, huấn luyện viên Dobermann.” Giọng cô bé bình tĩnh, nhưng hai bàn tay đã siết lại. “Chỉ là chúng ta không có thời gian ngồi chờ Reunion tự giải tán. Không ai biết tình trạng này sẽ kéo dài bao lâu. Cách tốt nhất là hạ địch rồi lập tức di chuyển. Chị thấy có đúng không?”","Dobermann nhìn cô bé rất lâu. Rồi gật đầu.","“Hiểu rồi. Tôi sẽ theo lệnh cô.” Cô quay sang các đội. “Tất cả nghe đây. Ta có yếu tố bất ngờ, đám Reunion này chưa biết chúng ta ở đây. Nhớ kỹ: quyết đoán! Hạ gọn, hạ nhanh.” Rồi cô nhìn Doctor. “Doctor, tập hợp đội của người đi. Đến lúc người chứng minh bản thân rồi. Chúng ta không còn thời gian để do dự.”","@cg:avg_1_3","“Chuyện nhỏ,” Doctor đáp. “Để tôi lo.”","Dobermann bật ra một tiếng cười ngắn, khô khốc. “Hah. Amiya, trông cả vào cô đấy.”","“Rõ.” Amiya bước lên, và đọc to câu nói mà ai trong Rhodes Island cũng thuộc lòng:","“‘Lặng im khi xung đột có thể tránh, nhưng chiến đấu đến cùng khi không còn lối thoát!’ Tín điều của Rhodes Island… chưa bao giờ thay đổi!”","","Khi tên Reunion cuối cùng gục xuống, hắn vẫn kịp lẩm bẩm: “Các người… không phải người Ursus…”","“Có vẻ chúng không kịp báo cho đồng bọn,” Dobermann nói, rồi quay sang Doctor. Một thoáng ngập ngừng hiếm hoi. “…Làm tốt lắm, Doctor. Có lẽ tôi nên đánh giá năng lực của người khách quan hơn.”","Amiya đã chạy về phía người mẹ đang co rúm trong góc tường.","“Chị không sao chứ?”","“Hả? À… cảm ơn em…” Người phụ nữ ngẩng lên, rồi khựng lại khi nhìn thấy thứ gì đó trên tay Amiya. Những tinh thể đen nhánh, bóng như thủy tinh, nhô lên dưới lớp da. “Em… em cũng là Infected?”","Bà ta giật lùi, ôm chặt đứa con. “Em muốn gì?! Đừng làm hại con tôi… Tôi van em, đừng làm hại chúng tôi…”","Amiya đứng im một lúc.","“…Hãy tìm chỗ nào an toàn mà trốn đi,” cô bé nói.","Người phụ nữ vừa khóc vừa lùi xa, miệng vẫn lặp đi lặp lại những lời van xin. Amiya quay lại với nhóm, cố giữ giọng bình thường: “Mọi người đã nghỉ đủ chưa?”","“Tại sao bà ấy lại sợ em?” Doctor hỏi.","Amiya im lặng. Rồi cô bé khẽ cười, buồn bã.","“Doctor… ngày trước Doctor cũng từng hỏi em một câu tương tự.”","“…Vì em là người Infected. Em, Dobermann, và phần lớn thành viên Rhodes Island đều vậy. Kể cả những người Reunion chúng ta vừa đánh. Bọn em đã mắc phải một căn bệnh khủng khiếp, thứ khiến phần lớn mọi người khiếp sợ…”","“Oripathy,” Dobermann tiếp lời. “Những ai mắc Oripathy bị gọi là ‘Infected’.”","“Ursus xưa nay luôn đối xử khắc nghiệt với người Infected,” cô nói tiếp. “Mà nói thật, nơi nào chẳng thế? Chỉ là Ursus đặc biệt máu lạnh. Dân thường được dạy phải sợ người Infected qua tuyên truyền. Khi người Infected bị săn lùng, chẳng ai chớp mắt, có kẻ còn reo hò. Cho nên Reunion mới chọn nơi này.”","“Nhưng lần này,” Amiya nói, “không còn đơn giản là một cuộc biểu tình nữa.”","“Chúng bắt đầu dùng bạo lực quy mô lớn. Khi Ursus dẹp xong cuộc bạo loạn này, người Infected ở Chernobog sẽ chỉ còn phải chịu tàn nhẫn hơn.” Dobermann liếc sang Doctor. “Ngược lại, có người ở đây, biết đâu tình hình của Rhodes Island sẽ khá hơn.”","“Chuyện này cũng liên quan đến tôi sao?”","“Cả Kal’tsit và Amiya đều nói người là một nhà nghiên cứu Oripathy hàng đầu. Nhưng với cái trí nhớ thế này, tôi nghi người có còn dùng được vào việc gì không.”","“Huấn luyện viên! Chị nói quá đáng quá!” Amiya phụng phịu.","“…Có lẽ người sẽ nắm lại được lý thuyết sau một thời gian ôn tập, giống như đã học lại cách chỉ huy?” Dobermann nhún vai. “Dù sao người cũng là chỉ huy chiến trường của chúng tôi. Thú thật, tôi chưa bao giờ nghĩ một bác sĩ thần kinh học lại có thể là một nhà chiến thuật bậc thầy. Nhưng gặp người rồi, tôi phần nào hiểu được. Bản thân Rhodes Island cũng giống lĩnh vực của người lắm.”","Cách đó vài bước, người y tá đang đuổi theo một lính gác.","“Này! Đứng lại! Đến giờ tiêm rồi!”","“Hả? Tôi bảo là tôi khỏe mà! Tôi chưa cần điều trị!”","“Anh phải tiêm định kỳ để làm chậm triệu chứng! Chẳng phải anh vừa kêu chóng mặt sao? Lỡ ra trận lại có chuyện thì sao? Vì sự an toàn của mọi người, anh cũng phải giữ gìn sức khỏe chứ! Đứng lại! Tôi tiêm cho anh đây!”","“Áaa!”","Dobermann nhìn cảnh ấy, khóe miệng giật nhẹ.","“…Đó là việc Rhodes Island làm. Chúng tôi tìm cách chữa Oripathy, đồng thời giải quyết những vấn đề xoay quanh người Infected.”","“Đúng vậy,” Amiya nói. “Chỉ nghiên cứu, hay chỉ giải quyết xung đột thôi thì chưa đủ. Chúng ta phải giải quyết mọi vấn đề liên quan đến người Infected. Chỉ có như vậy, Rhodes Island mới có thể trao cho tất cả người Infected một cơ hội sống sót…”","“Chúng tôi hiểu họ hơn ai hết, vì chúng tôi cũng là người Infected,” Dobermann nói. “Dù là ai, dù phải trả giá thế nào, Rhodes Island vẫn tìm cách chấm dứt sự lan tràn của thù hận và bệnh tật. Doctor, có lẽ đó cũng sẽ là sứ mệnh của người. Ít ra, tôi mong là vậy.”","“Tôi cần thêm thời gian để suy nghĩ.”","“Chúng tôi sẽ cho người đủ thời gian để thấm dần mọi chuyện. Nhưng thời gian dành cho chúng tôi thì ít ỏi lắm.” Dobermann vỗ tay. “Tập hợp! Đi thôi! Trên đường đến điểm hẹn, chuyện gì cũng có thể xảy ra!”","Khi đoàn người bắt đầu di chuyển, Dobermann hạ giọng, chỉ đủ cho Amiya nghe.","“Amiya… tình hình Chernobog đã rất phức tạp. Ta không thể tạo thêm áp lực cho đội cứu hộ. Nhưng mà…”","“Chúng ta… còn bao nhiêu thời gian?”","“Ba tiếng.” Dobermann nhìn lên bầu trời. “Ba tiếng nữa, cả thành phố này sẽ bị Catastrophe nuốt chửng. Sau đó, mọi thứ sẽ chấm dứt.”","","Ở một nơi rất cao, trên nóc một tòa nhà đổ nát, có ai đó đã dõi theo tất cả.","“…Phát hiện vài biến số chưa rõ. Báo cho những người khác. Bám theo chúng.”"],"bg":"bg_cher_1","cast":[["Dobermann","npc:char_130_doberm_ex"],["Amiya","op:char_002_amiya"]]},{"c":"0-2","t":"Bảo hộ","p":["Càng đi sâu, Chernobog càng giống một cơn ác mộng.","@cg:bg_0_tv","Những vụ nổ, bạo loạn, hỏa hoạn, giao tranh trên từng con phố. Dobermann nhìn quanh, giọng nặng trĩu: “Chuyện này vượt xa dự đoán của tôi. Chernobog đã hoàn toàn rơi vào hỗn loạn rồi sao?”","Trên một màn hình lớn còn sót lại ở góc quảng trường, một người dẫn chương trình mặc vest chỉnh tề đang mỉm cười.","“…Nhờ phản ứng nhanh chóng và sự phối hợp nhịp nhàng của Quân cảnh Chernobog, tình hình về cơ bản đã được kiểm soát. Hiện Quân cảnh đã bao vây những kẻ côn đồ chiếm giữ Đại lộ Vaschuk. Như quý vị có thể thấy, bạo lực vô nghĩa này sắp chấm dứt. Xin đừng hoảng loạn. Hãy ở yên trong nhà, và chờ đón thêm một chiến thắng nữa của Chernobog… Nguyện vinh quang Ursus phù hộ Hoàng đế và thần dân của Người!”","Cách màn hình chưa đầy hai dãy phố, phòng tuyến Ursus đang vỡ vụn.","“Chết tiệt… bọn chúng kiếm đâu ra thứ trang bị và vũ khí đó?!”","“Đừng sợ!” Viên đội trưởng Ursus gầm lên. “Hèn nhát mặc giáp thì vẫn là hèn nhát! Chúng chỉ là một lũ côn đồ chưa qua huấn luyện! Chúng ta từng hạ những lực lượng đông gấp ba lần! Làm lại lần nữa là trận này xong!”","“Bớt nói nhảm đi, lũ cặn bã Chernobog!” Một tên Reunion gào lại.","“Lũ rác rưởi chúng mày nghĩ có thể chống lại chúng tao sao? Lưu đày và lao động khổ sai còn quá tốt cho giống chúng mày. Lẽ ra phải xử tử hết ngay khi bắt được!”","Câu nói ấy như đổ thêm dầu vào lửa. Đám mặt nạ trắng ào lên lần nữa. Một lính Ursus lùi lại, ho sặc sụa. “Tôi… tôi không trụ nổi nữa…!”","“Đứa nào quay lưng bỏ chạy sẽ bị xử bắn tại chỗ! Vì Hoàng đế! Giữ vững vị trí!”","Một lính gác Rhodes Island nhổm dậy, nhưng Dobermann giữ chặt vai anh ta. “Ở yên! Chưa được lộ diện!”","“Quân Ursus… đang bị Reunion áp đảo sao?” Amiya thì thầm.","“Những gì chúng phát trên truyền hình chẳng dính dáng gì đến sự thật,” Dobermann nói. “Đến nước này mà chính quyền Chernobog vẫn còn diễn kịch. Nhưng tình hình của ta cũng tệ đi. Đừng mong lẻn ra ngoài được nữa.”","“Đường sá thì hỏng, lại thêm chốt chặn của địch… Chúng ta không thể dùng xe được nữa.”","“Đúng. Đội cứu hộ phải đủ đông để dọn sạch bất kỳ tên Reunion nào chắn đường. Chia nhỏ ra nữa thì chỉ có chết.”","Một lính gác nhìn trận đánh, giọng không giấu được sự kinh ngạc. “Quân Ursus trang bị tốt thật, nhưng Reunion… Reunion rõ ràng áp đảo về quân số và sĩ khí!”","“Khác hẳn lần đầu chúng ta trinh sát Chernobog,” Dobermann nói. “Khi lẻn vào, số lượng, sự bố trí và trạng thái của lính gác và quân đội ở đây kỳ lạ lắm. Khi ấy chúng ta không hiểu tại sao. Tôi không có bằng chứng, nhưng nếu Reunion đã đủ mạnh để mở một chiến dịch quy mô thế này… thì tôi chỉ có thể nói, may mà kẻ bị bao vây là đám lính kia chứ không phải chúng ta.”","“Doctor, nhanh tập hợp các đội!” Amiya bỗng nói gấp. “Trinh sát phát hiện quân Reunion. Chúng sắp chạm trán đội cứu hộ của ta!”","Một tên Reunion vừa rẽ qua góc phố, sững lại. “Hả? Sao lại có lực lượng vũ trang ở đây?!”","“Tất cả các đội, chuẩn bị chiến đấu!” Dobermann quát. “Đừng cho chúng cơ hội phản công!”","","Trận đánh vừa dứt thì viên đội trưởng Ursus đã tiến tới, mũi giáo chĩa thẳng.","“Các người là ai? Tại sao lại ở Chernobog vào lúc này?! Gián điệp à?!”","Dobermann siết chặt vũ khí. Nếu danh tính bị lộ, nếu chính quyền Ursus bắt đầu để mắt đến Rhodes Island, hậu quả sẽ không thể lường hết được. Nếu buộc phải ra tay…","“Thưa ông.” Amiya bước lên.","“…Một con bé?” Viên đội trưởng nheo mắt. “Mày… là Infected? Đứng yên đó! Bỏ vũ khí xuống!”","“Thưa ông, hẳn ông cũng hiểu chúng ta có chung một kẻ thù.”","Một làn khói mỏng bắt đầu len lỏi giữa các dãy nhà. Dobermann nhận ra nó trước. “Khói? Từ đâu ra…? Defender! Chúng tấn công!”","Và từ trong màn sương ấy, một bóng người bước ra.","Cô ta đeo mặt nạ, khoác áo choàng đen của Reunion, bước đi nhẹ như không chạm đất. Không cần nhìn rõ, ai cũng cảm thấy cô ta hoàn toàn khác với lũ côn đồ ban nãy.","“Hừ. Định chạy à? Các người nghĩ mình đi đâu được?” Giọng cô ta lạnh tanh. “Đi. Xé xác chúng.”","@cg:avg_1_1","“Đến cả thuộc hạ của ả cũng được huấn luyện bài bản,” Dobermann gằn giọng. “Ả là thủ lĩnh của Reunion sao?”","“Sương mù càng lúc càng dày… Chúng định dùng nó để đánh úp.” Amiya quay sang viên đội trưởng. “Thưa ông, chúng ta phải sơ tán ngay! Nếu chúng cắt được đường lui thì tất cả sẽ…”","Viên đội trưởng nhìn cô bé, nhìn những tinh thể đen trên tay cô bé.","“Cút đi, Infected.”","Amiya im lặng.","“Ta được giao giữ con phố này,” ông ta nói. “Thỏ con, ta không quan tâm vì sao chúng mày đến đây hay định làm gì. Nếu chúng mày định phá hoại thành phố của ta, thì nhớ rằng sẽ có người truy đuổi chúng mày. Cơn thịnh nộ của Ursus không bao giờ dứt. Còn nếu không, thì chuyện ở đây chẳng liên quan đến chúng mày.” Ông ta quay lưng về phía họ, đối diện màn sương. “Người Ursus nào cũng biết không bao giờ được quay lưng với kẻ thù. Giờ thì biến! Ta không có thời gian lo cho chúng mày.”","Amiya đứng đó thêm một nhịp. Rồi cúi đầu thật khẽ.","“…Cảm ơn ông.”","“Nhanh lên! Đến điểm hẹn thứ nhất!” Dobermann hô. “Tất cả các đội, di chuyển!”","Khi bóng Rhodes Island khuất dần sau góc phố, viên đội trưởng Ursus giương giáo về phía màn sương.","“Lại đây, lũ Infected bẩn thỉu! Chỉ có thế thôi à? Định đứng đó nhìn bọn ta mãi sao?”","Từ trong sương, giọng người phụ nữ đeo mặt nạ vọng ra, không cao không thấp.","“Tất cả người Chernobog… đều phải chết.”"],"bg":"bg_cher_1","cast":[["Dobermann","npc:char_130_doberm_ex"],["Ursus Captain",null],["Amiya","op:char_002_amiya"],["TV Host",null]]},{"c":"0-4","t":"Hỗn chiến","p":["“Ace!”","Người đàn ông cao lớn mang khiên đứng giữa con phố tan hoang, như thể ông ta đã đứng đó chờ từ lâu. “Có vẻ các cậu vẫn còn sống cả.”","“Đây đâu phải điểm hẹn,” Dobermann nói. “Sao anh lại ở đây một mình?”","Chưa kịp nghe câu trả lời, tiếng hò hét đã vang lên từ cuối phố. “Bọn chúng là đám trốn từ khu trung tâm! Đừng để chúng thoát!”","“Chậc, cứ bám riết lấy ta mãi! Đội E2, chuẩn bị chặn đánh—”","“Dobermann, đừng nóng vội. Rút lui là ưu tiên hàng đầu.” Ace quay sang. “Amiya, Doctor! Nhanh lên!”","Rồi ông ta nhìn Doctor, nở một nụ cười điềm đạm, như gặp lại một người quen cũ sau chuyến đi xa. “Doctor, xin hãy ra lệnh. Như những ngày xưa.”","Doctor nhìn ông ta, không biết phải đáp gì.","“Ừm, Ace…” Amiya lên tiếng. “Thật ra có chuyện ngoài ý muốn. Doctor… bị mất trí nhớ.”","“…Ra vậy.”","“Em xin lỗi, Ace… So với trước, nhiều thứ đã khác rồi.”","“Thế à? Cô không cần xin lỗi tôi.” Ace hỏi thẳng vào điều quan trọng nhất: “Khả năng chỉ huy của Doctor có bị ảnh hưởng không?”","“…Vẫn sắc bén như trước. Những quyết định của Doctor vẫn tuyệt đối đáng tin. Em có thể hứa điều đó.”","“Tốt lắm. Vậy tôi sẽ theo lệnh Doctor.” Ace nói, giọng nhẹ như không. “Những gì đã mất có thể tìm lại. Còn lúc này, ta có một vấn đề cấp bách hơn.”","“Nói xong chưa?” Dobermann gầm lên. “Tôi đi đập vài cái sọ đây!”","Đám Reunion đã ào tới. “Đi! Thả con thú trong các ngươi ra, cho chúng nếm nanh vuốt!”","“Doctor! Ace! Địch ngay trước mặt!”","“Nắm lấy thời cơ, phá vỡ kế hoạch của địch,” Doctor nói.","“Rõ.” Ace giơ tay. “Đội E3! Yểm trợ Dobermann!”","Từ những mái nhà và ngõ hẻm hai bên, các thành viên Đội E3 đồng loạt lao ra. Đám Reunion bị kẹp giữa hai gọng kìm.","“Phục kích?!”","“Đội E3 vẫn ẩn nấp suốt từ nãy…” Dobermann bật cười. “Ra vậy, các anh chờ chúng tôi đến để kẹp địch.”","“Khi liên lạc bị phá sóng, các đội nên hoạt động quanh điểm hẹn,” Ace nói, vừa dùng khiên gạt một nhát chém. “Như vậy, dù tôi hay trinh sát có mệnh hệ gì, chiến dịch lớn vẫn có thể tiếp tục. Đó là quyết định của tôi.”","“Tức là anh để đội ở lại điểm hẹn rồi một mình đến đây.”","“Dù sao, vô hiệu hóa mối đe dọa quanh điểm hẹn là mục tiêu hàng đầu. Đương nhiên, ưu tiên đi kiểm tra tình hình các cậu là một rủi ro lớn. Tôi không thể đem cả đội ra mạo hiểm. Lý do các đội tồn tại là để tăng hiệu quả chiến thuật, không phải ngược lại.”","“Hah. Để dọn xong Reunion rồi bàn tiếp!”","“Amiya, đến lượt cô.”","“Rõ! Em sẽ yểm trợ bằng Arts!”","Ace nhìn Doctor một lần cuối trước khi lao vào trận, ánh mắt ấm áp lạ lùng.","“Cuối cùng thì… Doctor, xin hãy chỉ huy Rhodes Island.”"],"bg":"bg_cher_5","cast":[["Ace","npc:char_014_riope"],["Dobermann","npc:char_130_doberm_ex"],["Amiya","op:char_002_amiya"]]},{"c":"0-6","t":"Tập kích","p":["Khi trận đánh kết thúc, không ai lên tiếng ngay.","Dưới chân họ là xác của những sinh vật lạ, những con thú đã bị Originium ăn mòn, da thịt mọc đầy tinh thể. Chúng đã lao vào đội hình Rhodes Island như những con thú dữ, nhưng có điều gì đó trong cách chúng chiến đấu khiến người ta rợn gáy.","“Lũ khốn bệnh hoạn!” Dobermann rít lên. “Không thể tin được chúng lại…”","“Reunion đã nô dịch những con thú bị nhiễm bệnh để làm quân lính…” Amiya nói.","“Không, không đơn giản thế đâu.” Dobermann nhìn xuống một cái xác. “Tôi cảm nhận được. Chúng không phải thú vật bình thường. Thật ra… chúng giống chúng ta hơn…”","Không ai dám hỏi thêm. Một lính gác khẽ hỏi Ace: “Đội trưởng… chúng ta nên làm gì?”","“Cho chúng một kết thúc nhân từ,” Ace nói.","Rồi ông ta quay sang Dobermann. “Trận chiến kết thúc rồi. Catastrophe đã treo lơ lửng trên đầu, có thể giáng xuống bất cứ lúc nào. Ngay cả Chernobog cũng sẽ thành đống đổ nát dưới tác động trực tiếp của nó.”","“Reunion đang lợi dụng điều đó để gieo rắc thêm hỗn loạn,” Amiya nói.","“Dobermann, chúng ta hết thời gian rồi. Ta có thể qua mặt Reunion hay lẩn tránh Ursus, nhưng trước một Catastrophe, ta hoàn toàn bất lực.”","Dobermann im lặng một lúc. “Đủ rồi. Đi thôi. Dù kế hoạch của Reunion có liều lĩnh đến đâu, điều quan trọng nhất với chúng ta…”","“…là sự an toàn của mọi người,” Amiya tiếp lời.","“Đúng vậy.”","“Những kẻ cầm đầu Reunion có thể xem sự kiện này là một điềm báo, thậm chí là một phương tiện,” Amiya nói. “Nhưng với em, nó chỉ có nghĩa là từ giờ chúng ta sẽ gặp nguy hiểm hơn.”","“Chọn đúng lúc này để kích động hỗn loạn…” Ace lắc đầu. “Reunion hoặc là điên, hoặc là ác.”","“Có lẽ là cả hai,” Dobermann đáp."],"bg":"bg_cher_5","cast":[["Dobermann","npc:char_130_doberm_ex"],["Ace","npc:char_014_riope"],["Amiya","op:char_002_amiya"]]},{"c":"0-7","t":"Lây nhiễm","p":["Bầu trời mỗi lúc một tối.","“Như thể mây đang đè xuống đường chân trời vậy…” Amiya ngước nhìn. “Không khí vẫn còn trong, nhưng mây đen không trôi. Cảm giác như mọi áp lực đang bị nén lại vào một điểm. Đến cả gió cũng ngừng thổi…”","“Không nghi ngờ gì nữa. Một Catastrophe sắp giáng xuống thành phố này,” Dobermann nói. “Nhìn cảnh này thì Chernobog đã hoàn toàn tê liệt vì các đợt tấn công của Reunion. Nhưng muốn vô hiệu hóa một nomadic city, phải chuẩn bị từ nhiều tuần trước. Liệu Reunion còn làm gì khác từ khi ấy…?”","“Hơi khó tin,” Ace nói. “Với những gì ta thấy, Reunion hiện tại không có đủ kỷ luật để âm thầm thâu tóm cả một thành phố. Phần lớn bọn chúng vẫn lang thang ngoài đường, trả thù người Chernobog.”","“Toàn là đánh nhau, giết chóc, đốt phá vô nghĩa,” Amiya nói.","“Khi Catastrophe giáng xuống, ngay cả Chernobog bất khả xâm phạm cũng sẽ vỡ vụn, biến thành phế tích đầy Originium,” Dobermann nói. “Nếu chúng muốn danh vọng hay của cải, Reunion chắc chắn sẽ thất bại.”","“Dù chuỗi chỉ huy của Ursus đã tan hoang, em vẫn nghi Reunion có đủ sức đối đầu với quân đội của họ,” Amiya nói. “Tại sao quân đội Ursus vẫn chưa phản công?”","“Theo kinh nghiệm của tôi, khi bạo loạn nổ ra, quân đội thường dẹp được ngay. Nhưng chúng ta vừa tận mắt thấy lính Ursus bị áp đảo…” Dobermann nhíu mày. “Ả thủ lĩnh đeo mặt nạ kia có thể hơn hẳn đám còn lại, nhưng không đời nào một mình ả phá hủy được cả thành phố. Trừ khi…”","“Trừ khi sao?”","“Tôi đã đi qua nhiều trận chiến. Tôi từng gặp không ít kẻ hành xử giống ả. Với chúng, binh lính chỉ là những con tốt, xài xong thì vứt. Dùng khi cần, bỏ mặc khi không cần, vì chi phí huấn luyện và nuôi quân quá cao.”","“Tức là không có quân thường trực?” Ace hỏi.","“Đúng vậy. Phần lớn thời gian, chỉ cần cho chúng ăn một chút thù hận hay sợ hãi. Muốn chúng phát cuồng… chỉ cần đẩy nhẹ một cái.”","“Vậy… người Infected nào cũng có thể gia nhập Reunion chỉ bằng cách khoác đồng phục và đeo huy hiệu?” một lính gác hỏi.","“Đúng. Điều đó giải thích vì sao quân số của chúng vô tận.” Giọng Dobermann trầm xuống. “Có quá nhiều người Infected bị áp bức, tuyệt vọng muốn được cất tiếng. Dù giải pháp Reunion đưa ra mong manh đến đâu, chỉ cần họ thấy ánh sáng cuối đường hầm, họ sẽ sẵn lòng hiến dâng mạng sống để theo đuổi nó, kể cả khi phải nhảy vào biển lửa.”","Cô quay sang Doctor.","“Doctor. Bọn họ không giống chúng ta. Dù tôi chưa hoàn toàn tin người, ít nhất tôi tin năng lực của người. Và khác hẳn với người, loại thủ lĩnh kia không phải chỉ huy. Kẻ sẵn sàng giẫm đạp lên cả kẻ thù lẫn đồng đội… không, phải gọi là ‘tay sai’. Có lẽ còn chẳng phải tay sai. Với Reunion, đám côn đồ ấy chỉ là những con tốt. Đó không phải người lãnh đạo, mà là bạo chúa.”","“Dù kẻ thù là ai, chúng ta cũng sẽ hoàn thành nhiệm vụ,” Ace nói. “Có người từng dạy tôi và đồng đội rằng: ‘Gặp tốt thì bắt tốt, gặp thành thì phá thành, gặp vương miện thì lật đổ vương miện.’”","Ông ta dừng bước. “Doctor, phía trước có quân nhẹ của địch đồn trú.”","“Chúng phát hiện ta chưa?” Amiya hỏi.","“Chưa. Nhưng ta không tránh được. Đây là đường ngắn nhất, đi vòng sẽ mất thời gian mà ta không có.”","“Vậy khỏi bàn,” Dobermann rút vũ khí. “Côn đồ hay con tốt, chỉ cần dọn sạch khỏi đường đi là được!”","","Theo lộ trình, họ sắp đến thị trấn trung tâm của Nam Chernobog. Băng qua công viên này là tới điểm hẹn, nơi Nearl và Đội E4 lẽ ra đang chờ.","“Nhưng…” một lính gác lên tiếng, giọng run run. “Nếu Nearl bị tấn công thì sao? Nếu họ muốn báo cho ta mà không được vì liên lạc bị phá sóng… ta phải làm sao?”","“Chúng ta sẽ đến xem tình hình,” Amiya nói.","“Đừng suy đoán khi chưa tận mắt thấy,” Ace nói thêm. “Để nỗi hoang tưởng lấn át chẳng ích gì.”","Dobermann thở dài khẽ. Mất liên lạc khiến nỗi bất an lan khắp hàng ngũ nhanh hơn cô tưởng. Nhất là khi Catastrophe đang treo trên đầu. “Phải tăng tốc thôi.”","Amiya đột ngột dừng lại. “Sương mù này… lẽ nào—Cẩn thận!!”","Từ trong màn sương dày đặc, giọng nói lạnh tanh ban nãy lại vang lên.","“Giết chúng.”","Mưa tên trút xuống. Phía sau lưng Rhodes Island, quân Reunion đã chặn kín đường lui. Trinh sát của đội đã bị tách khỏi đoàn từ lúc nào không biết.","“Rhodes Island…” Người phụ nữ đeo mặt nạ bước ra từ màn sương. “Bắt được các ngươi rồi. Lần này, ta sẽ nghiền xương các ngươi thành bụi!”","“Sniper, chặn bước tiến của chúng! Defender, giữ phòng tuyến, chuẩn bị đẩy lên! Ace, chuẩn bị—”","“Khoan, khoan đã nào—”","Một giọng nói khác chen vào, trong trẻo và vui vẻ đến mức lạc lõng giữa chiến trường.","“Tôi vừa thanh trừng xong Pháo đài Đông Nam, nghe tin là chạy ngay đến đây đấy. Đây là bãi săn của tôi, Crownslayer.”","Người phụ nữ đeo mặt nạ, Crownslayer, quay lại. “…Ngươi đến đây làm gì?”","“Chẳng phải đến lúc cô giao bọn chúng lại cho tôi rồi sao?”"],"bg":"bg_cher_5","cast":[["Dobermann","npc:char_130_doberm_ex"],["Amiya","op:char_002_amiya"],["Ace","npc:char_014_riope"]]},{"c":"0-8","t":"Săn đuổi","p":["“…Mephisto?”","Kẻ vừa xuất hiện là một thiếu niên tóc trắng, gương mặt thanh tú với nụ cười như vẽ. Cậu ta đứng trên một bệ cao, nhìn xuống như khán giả trên khán đài.","“Cô đâu có lý do gì để phản đối, phải không? Chỉ vài con côn trùng bay quá gần ánh đèn thôi mà, đáng để cô bận tâm sao?” Mephisto nghiêng đầu. “Quân của tôi đã nhận được thông tin của cô. Phần việc của cô xong rồi. Việc còn lại là về nhà thôi. Dù sao cô cũng chỉ phụ trách khu năng lượng trung tâm và vùng lân cận… Chẳng phải cô còn có chỗ khác phải đến sao?”","“Đừng làm chuyện thừa thãi…!”","Một quãng lặng căng thẳng.","“Được. Tùy ngươi.” Crownslayer quay lưng. “Ta rất mong được thấy ngươi thất bại. Đi thôi.”","Một phần quân Reunion rút theo cô ta. Amiya nhìn theo, không hiểu nổi. “Một trong những thủ lĩnh của địch… vừa dẫn một phần quân rời đi sao?”","“Chúng định làm gì?” Dobermann nói. “Dù gì đi nữa cũng không được lơ là. Quân địch vẫn đông hơn ta nhiều lần!”","“Chà chà.” Mephisto cúi người như diễn viên chào khán giả. “Cho phép tôi thay mặt Crownslayer xin lỗi vì sự thô lỗ của cô ấy. Các vị cứ gọi tôi là Mephisto.”","“Reunion rốt cuộc muốn gì?”","“Ồ, chẳng có gì đặc biệt. Nói thật, tôi chẳng ngại để các vị đi đâu. Các vị vốn đâu phải mục tiêu của chúng tôi.” Mephisto mỉm cười. “Có điều, tôi đã có vinh hạnh được xem các vị chiến đấu. Chiến thuật cũng như cách bố trí nhân sự của các vị… thú vị lắm.”","“Thú vị?” Người y tá thốt lên. “Ngươi thấy cảnh tàn sát của chiến trường là… thú vị?”","“Rhodes Island… tôi đã đọc về các vị. Ban đầu tôi tưởng chỉ là một công ty bình thường. Nhưng xem ra tham vọng của các vị đã vươn quá xa khỏi mấy ống nghiệm rồi nhỉ? Để các vị cứ thế đi ra thì chán chết, đúng không? Tôi muốn một cuộc so tài nho nhỏ. Một nghi thức, có thể nói vậy.”","“Bọn ta không có thời gian lãng phí với một thằng nhóc hợm hĩnh.” Dobermann hạ giọng: <i>Amiya, chuẩn bị. Có thể phải dùng sức phá vây. Tôi sẽ thu hút sự chú ý của nó.</i>","“…Vừa rồi là gì thế?” Mephisto nheo mắt. “Cô ra hiệu cho ai vậy?”","“Không phải việc của mày, nhóc.”","“Thôi nào, chúng ta đều là dân chuyên nghiệp cả. Phép lịch sự tối thiểu đâu rồi?”","“Nếu không có loại người như mày, tôi đâu phải suốt ngày mài giũa cái tài chửi bới!”","<i>Amiya, sao rồi?</i>","<i>Dobermann… mọi lối thoát đều đã bị quân của hắn chặn hết!</i>","<i>Sao có thể?! Làm sao hắn làm được trong vài phút—</i>","“Thế này thì không được rồi.” Nụ cười của Mephisto vẫn còn đó, nhưng giọng cậu ta đã đổi khác. “Tôi đã thành tâm mời mọc vậy mà… các vị chỉ nghĩ đến chuyện… chạy trốn thôi sao?!”","Rồi cậu ta lại tươi cười như chưa có gì. “Thật ra, tôi sẽ để các vị an toàn rời khỏi bãi săn của tôi, chỉ cần các vị thắng. Trước đó, bạn bè tôi ở đây sẽ cứ cố giết các vị. Không chết là các vị thắng! Luật đơn giản đấy chứ?”","“Tại sao ngươi làm thế?” Amiya kêu lên. “Catastrophe sắp đến! Nếu không rời khỏi Chernobog, tất cả mọi người sẽ—”","“Cô nói gì vậy… Catastrophe… mới chính là thời khắc đẹp nhất để ăn mừng chứ.”","“Ngươi bệnh hoạn…”","“Những vị khách quý của tôi, tôi hân hạnh mời các vị tham gia trò chơi này.”","Đám Reunion quanh cậu ta bắt đầu gầm gừ, ánh mắt sau lớp mặt nạ trở nên đục ngầu, như bị thứ gì đó điều khiển. “Giết… Giết!! Giết hết… chúng!!”","“À phải rồi, phải rồi,” Mephisto nói thêm, như chợt nhớ ra. “Thật ra chúng tôi biết rõ các vị đã làm gì ở khu trung tâm.”","Amiya cứng người.","“Người đeo mặt nạ mà các vị giải cứu… khiến tôi tò mò lắm, lắm lắm. Crownslayer thì chỉ để tâm các vị sẽ làm gì tiếp, đi đâu tiếp. Nhưng tôi thì khác. Điều tôi quan tâm là…”","Ánh mắt cậu ta dừng lại trên Doctor.","“Ngươi rốt cuộc là thứ gì? Từ đâu đến? Phải, chính ngươi đấy. Kẻ đang nhìn ta lúc này… Ngươi hơi khác với chúng ta. Cái thiết bị trong cơ sở ấy, thứ đã giữ được mạng sống của ngươi, là gì vậy? Ta tò mò lắm, lắm lắm.” Mephisto dang tay. “Thấy chưa, ta đâu phải người máu lạnh. Vậy thế này nhé, các vị khách quý của Rhodes Island, tặng người này cho ta làm quà, được không? Kết thúc trò chơi sớm thì tiếc thật, nhưng ít ra ta sẽ thả những người còn lại. Thế nào?”","Amiya không trả lời. Cô bé bước lên một bước, đứng chắn hẳn trước mặt Doctor.","“Doctor… đứng sau em!!”"],"bg":"bg_cher_5","cast":[["Mephisto","npc:char_1507_Mephisto_1"],["Dobermann","npc:char_130_doberm_ex"],["Amiya","op:char_002_amiya"],["Crownslayer","npc:char_1502_crowns"]]},{"c":"0-9","t":"Nearl","p":["Trận đánh trở thành một cối xay thịt.","“Không đủ… Cứ thế này chúng sẽ siết vòng vây lại mất!” Amiya hét.","“Tôi đã tìm ra điểm yếu trên phòng tuyến của chúng, nhưng không có viện binh, chỉ cầm chân thôi đã dốc hết sức!”","Trên bệ cao, Mephisto đang chỉ huy như một kỳ thủ trước bàn cờ.","“Tốt, tốt! Phải thế chứ! Tiếp theo, F3, E5!” Đám Reunion tràn lên đúng hai hướng ấy. “Xuất sắc! Giờ thì B4, B5!” Một mũi tiến công vòng sang cánh. “Tiếp! H2, H6!” Phòng tuyến Rhodes Island lõm vào. “Đúng rồi, cho ta xem các ngươi giãy giụa nào! Caster, vào C7. Bắt quân Xe của chúng!”","“Hắn chỉ huy quân như vậy thật sao?” Amiya kinh hãi. “Sao hắn có thể ra lệnh chính xác thế chỉ bằng cách hô nước cờ? Cũng là đám côn đồ vô tổ chức ấy, vậy mà dưới tay hắn lại thành một đạo quân…!”","“Ngược lại, nếu áp chế được hắn, chúng sẽ rối loạn!” Dobermann đáp. “Đừng cho chúng một kẽ hở nào! Chết tiệt, ta sắp hết thời gian rồi!”","“Giờ thì tắt lịm đi,” Mephisto cười, “như ngọn đèn trước giông bão!”","Amiya cắn môi. Có cách nào lật ngược thế cờ không, bất cứ cách nào? Cứ thế này, mọi người sẽ… Doctor sẽ…","“Gaaaaaahh!!!”","Một tên Reunion bay vút lên trời. Rồi tên thứ hai. Rồi cả một hàng.","“Cái gì?!” Mephisto đứng bật dậy. “Chuyện gì thế? Sao người lại bị hất văng lên không trung? Cái… cái quái gì thế kia?”","Một bóng người mặc giáp bạc, tay cầm khiên và chùy, đang xé toạc đội hình Reunion như con thuyền rẽ sóng. Mái tóc vàng của cô tung bay, giọng nói vang như tiếng chuông.","“Các cậu đến chậm thật đấy. Tôi còn kịp sơ tán xong dân thường cơ mà. Tránh đường!”","“Chị Nearl!!” Amiya reo lên.","“Tôi đây. Mừng là cô vẫn an toàn, Amiya. Đi thôi.”","“May quá, chị được điều đi chiến dịch này,” Dobermann thở phào.","“Bắn pháo hiệu là quyết định sáng suốt. Có vẻ mọi người vất vả lắm.” Nearl, Đội trưởng Đội E4, quay sang người khoác áo trùm đầu và mỉm cười. “…Người hẳn là Doctor, đúng không?”","Cô nghiêng mình chào, khiên vẫn chắn trước ngực.","“Hiệp sĩ Ánh Sáng, Nearl, xin được phục vụ. Cỗ xe của người đã đến.”"],"bg":"bg_cher_5","cast":[["Amiya","op:char_002_amiya"],["Mephisto","npc:char_1507_Mephisto_1"],["Dobermann","npc:char_130_doberm_ex"],["Nearl","op:char_148_nearl"]]},{"c":"0-10","t":"Thế khó","p":["“Người đàn bà này là thế nào vậy…” Mephisto lẩm bẩm.","Nearl ngẩng đầu, nhìn thẳng lên bệ cao. “…Ngươi kia. Khi Reunion chiếm các cứ điểm quân sự của Chernobog, chúng vận hành như một cỗ máy được tra dầu kỹ. Nhưng người của ngươi thì hành xử như lũ côn đồ mất trí. Tàn sát vô nghĩa, đốt phá thành phố, săn lùng người vô tội… Tất cả chỉ để thỏa mãn sự tàn bạo của chính ngươi, đúng không?”","Mephisto không đáp.","“Kẻ thấp hèn đến mức bày ra những tội ác vô nghĩa vào lúc này… không thể nào là kẻ vạch ra kế hoạch đánh sập cả một thành phố. Có lẽ cấp trên ra lệnh cho ngươi gây hỗn loạn, nhưng ngươi đã chiều theo sự trụy lạc và thô thiển của mình.”","Nụ cười trên môi Mephisto tắt hẳn.","“…Faust,” cậu ta nói khẽ. “Ta muốn ả bị bắn xuyên qua miệng.”","Không ai thấy phát bắn đến từ đâu. Chỉ có một tiếng xé gió, rồi tiếng kim loại va vào kim loại vang như sấm. Nearl lảo đảo lùi một bước, ho ra máu.","“Nearl!”","“Sniper của chúng… thật quá đáng!” Dobermann nghiến răng. “Nếu Nearl trúng thêm phát nữa, cô ấy sẽ không thể tự vệ được nữa!”","“Nearl, chị phải lùi lại!”","“Không được… Hắn quá mạnh. Tôi không thể để hắn bắn vào đội hình của ta. Tôi phải chặn những đòn đó!”","“Ả chặn được nỏ liên hoàn của Faust… chỉ bằng một tấm khiên?!” Mephisto gần như hét lên. “Không thể tin được… Không thể nào! Bắn nữa!! Thổi tung ả thành từng mảnh!”","Lần này phát bắn đến từ một hướng khác.","“Cái gì… từ bên phải?!”","“Không xong! Nhanh, né—”","“Đừng hòng!” Ace lao tới. “Sniper, ngắm! Mục tiêu bệ cao phía nam. Bắn!”","Loạt tên của Đội E3 trút xuống. Mephisto nghiến răng: “Cái gì?! Sao các ngươi dám… Sao các ngươi dám!”","“Trúng hắn chưa?” Amiya hỏi.","“Tôi nghi lắm,” Ace đáp. “Cùng lắm chỉ gây được chút áp lực. Tiếc là ta không có thời gian mổ xẻ chiến thuật của địch.”","“Hắn cơ động cao, hỏa lực mạnh. Càng kéo dài, ta càng khó chặn được những phát bắn đó!”","“Không thể cho hắn thời gian bố trí lại!” Nearl hét. “Amiya, hành động đi, trong khi Sniper của Đội E3 cầm chân hắn!”","“Rõ! Sniper Đội E1, theo em, áp chế quân Reunion! Đội E2, dồn toàn bộ hỏa lực phá phòng tuyến của chúng!”","Trên bệ cao, Mephisto bấu chặt lan can, giọng cậu ta vỡ ra thành những tiếng rít.","“Lũ sâu bọ bẩn thỉu… Sao các ngươi không ngoan ngoãn nằm xuống mà chết đi? Sao ta không thể kết liễu tất cả các ngươi ngay tại đây? …Ta muốn giết… từng… đứa… một…”","“Nearl, cơ hội đây! Nhanh!”","“Toàn bộ Đội E4, chúng ta sẽ xuyên thủng đội hình của chúng! Quét sạch mọi thứ trên đường trong một đòn!” Nearl giương khiên. “Xông lên!!”","“Bắn! Bắn đi! Đừng để ả lại gần…” Tên Reunion còn chưa dứt lời thì đã sững sờ. “Hả…? Cái gì?! Vừa nãy ả còn cách hai mươi mét…”","“Muốn đối đầu với một hiệp sĩ Kazimierz,” Nearl nói, khi tấm khiên của cô đã ập đến ngay trước mặt hắn, “thì về luyện thêm vài chục năm nữa đi.”","“Dobermann! Theo tôi!”","“Rõ!”"],"bg":"bg_cher_5","cast":[["Nearl","op:char_148_nearl"],["Mephisto","npc:char_1507_Mephisto_1"],["Amiya","op:char_002_amiya"],["Ace","npc:char_014_riope"],["Dobermann","npc:char_130_doberm_ex"],["Faust","npc:char_1508_Faust_1"]]},{"c":"0-11","t":"Phá vòng vây","p":["“Trinh sát xong. Xác nhận lực lượng truy đuổi đã bị tiêu diệt,” Dobermann báo cáo. “Ta đã phá được vòng vây. Sắp đến rìa ngoài Chernobog rồi.”","“Dù số địch hạ hôm nay chỉ là một phần nhỏ trong toàn bộ lực lượng,” Ace nói, “ít nhất lúc này ta đã an toàn.”","“Cảm ơn anh vì chuyện ban nãy,” Nearl nói với Ace. “Tôi nợ anh.”","“Đừng nói vậy. Tôi đâu có tư cách đòi Hiệp sĩ Ánh Sáng trả ơn. Mà, nói về tên sniper đó đi, Nearl.”","“Được. Gác lại sức hủy diệt của cây nỏ ấy… tôi nghĩ hắn có thể đã dựng sẵn nhiều tháp nỏ, cùng những thiết bị tự động bắn khác. Tôi bị nhắm từ nhiều hướng khác nhau, nhưng chỉ thấy một sniper.”","“Tôi cũng có cảm giác đó,” Ace nói. “Phát thứ nhất và thứ hai nổ gần như cùng lúc, nhưng có độ trễ rõ ràng. Chúng không bắn ra từ cùng một cây nỏ. Ít nhất, khi ta bắn trả, ta không nhắm vào cùng một sniper.”","“Anh nhận ra điều gì sao?”","“Tôi không dám chắc. Nếu kẻ địch di chuyển nhanh đến mức… gần như có mặt ở nhiều nơi cùng lúc thì sao?”","“Không ai có thể di chuyển nhanh như thế. Tôi còn không tưởng tượng nổi.” Nearl lắc đầu. “Không thể xem thường mức độ nguy hiểm của Reunion.”","“Chính thằng nhóc độc địa đó đã ra lệnh cho sniper nhắm vào chị,” Dobermann nói. “Lúc tấn công bọn tôi, hắn còn chẳng gọi đến sniper…”","“Có vẻ cái tính cách ghê tởm ấy được chống lưng bằng sức mạnh thật sự.”","“Nhưng dù nổi giận, hắn vẫn chưa từng tự mình tấn công ta,” Ace nhận xét.","“Hoặc năng lực chiến đấu của hắn kém, hoặc hắn chưa muốn để lộ thực lực,” Dobermann nói. “Chỉ riêng cách hắn chỉ huy thôi… đã khiến tôi rất nghi ngờ. Hắn điều khiển quân như điều khiển con rối.”","“Dù sao, ta đã ra khỏi vùng hắn kiểm soát rồi,” Nearl nói.","Amiya bước tới, cúi đầu thật sâu. “Chị Nearl… cảm ơn chị. Nếu chị không đến kịp, bọn em đã gặp nguy to rồi.”","“Tôi chỉ làm theo kế hoạch đã thống nhất thôi,” Nearl đáp. “Chính cô là người dặn tôi và Ace điều chỉnh tùy theo tình hình. Cô đã tự giải quyết vấn đề của mình.”","Cô nhìn về phía thành phố đang bốc khói sau lưng.","“Trên đường tới đây, tôi đã thấy những tội ác của Reunion, và tôi cũng hoài nghi về sức mạnh của chúng. Nếu tôi dừng lại giao chiến thì sao? Nếu tôi giúp Ursus chống Reunion thì sao? Nếu tôi cứ ở lại điểm hẹn chờ các cô đến thì sao? …Nếu người ra quyết định là tôi, không biết kết cục còn tệ đến mức nào. Tôi không giỏi tính trước nhiều bước. Cách duy nhất tôi biết để đạt được điều mình muốn là tiếp tục chiến đấu.” Nearl đặt tay lên vai Amiya. “Amiya, tôi chỉ làm tròn bổn phận. Nhưng cô có khả năng chấm dứt khủng hoảng. Chiến thắng này là của cô. Hãy tự tin hơn vào bản thân.”","“Chị Nearl…”","Nearl khẽ cười, rồi nhìn sang Doctor. “Người đứng cạnh cô hẳn là Doctor.”","“Vâng. Nhưng mà…”","“Cứ gặp ai là Amiya lại phải kể lại chuyện Doctor mất trí nhớ,” Dobermann lầm bầm. “Phiền thật.”","“Doctor,” Nearl nói, giọng dịu dàng. “Một người bạn của tôi cũng mất trí nhớ. Tôi chắc hai người sẽ hợp nhau lắm. Dù sao, người hẳn hiểu sống trong hiện tại quý giá đến nhường nào.”","“Vâng…!” Amiya gật đầu thật mạnh.","“Đi thôi mọi người. Chúng ta còn phải hộ tống Doctor về Rhodes Island.”","","Ở nơi đoàn người vừa rời đi, giữa đống đổ nát, một bóng người mang cây nỏ khổng lồ trên vai lặng lẽ bước tới bên Mephisto.","“Xin lỗi… Tôi thất bại rồi.”","“Không, đừng xin lỗi. Là lỗi của ta. Ta đã mất bình tĩnh.” Giọng Mephisto bỗng dịu dàng đến lạ, như một người anh nói với em. “Cậu giúp ta theo dõi Rhodes Island được không? Ta sẽ báo tình hình cho Talulah trước. Giờ này cô ấy hẳn đã chiếm được tháp chỉ huy trung tâm của Chernobog rồi. …Cô ấy sẽ quyết định số phận của lũ côn trùng ấy.”","“…Rõ.”","“Cẩn thận nhé. Sự an toàn của cậu là quan trọng nhất, nhớ chưa?”","“…Tôi sẽ cẩn thận.”","Faust biến mất vào bóng tối. Mephisto đứng một mình giữa phế tích, dang tay đón lấy bầu trời đang sẫm lại thành màu máu.","“…Xem như nhiệm vụ của ta cũng hoàn thành. Đi thôi, các đồng chí. Hãy cùng tiến lên, chào đón kỷ nguyên mới của chúng ta!!”"],"bg":"bg_cher_1","cast":[["Nearl","op:char_148_nearl"],["Ace","npc:char_014_riope"],["Mephisto","npc:char_1507_Mephisto_1"],["Dobermann","npc:char_130_doberm_ex"],["Amiya","op:char_002_amiya"],["Faust","npc:char_1508_Faust_1"]]}],"id":"main_0","no":"Chương 0","title":"Thời khắc tà ác · Phần 1","en":"Evil Time, Part 1","sum":"Doctor tỉnh dậy không còn ký ức giữa lòng Chernobog. Reunion trỗi dậy, Catastrophe sắp giáng xuống, và Rhodes Island phải đưa Doctor ra khỏi thành phố trước khi quá muộn."},{"secs":[{"c":"1-1","t":"Hòn đảo cô lập","p":["“Tôi có cảm giác trời đang tối đi, hay chỉ mình tôi thấy vậy?” một lính gác hỏi.","@cg:avg_9_2","“…Giá mà chỉ mình cậu thấy,” Dobermann đáp. “Chúng ta vốn chẳng có nhiều thời gian.”","Đám mây trên đầu không còn là một vệt sương đen mơ hồ như trước nữa. Nó đã có hình hài, những đường viền sắc lẹm như vết dao trên nền trời. Dobermann nhìn nó, cau mày như nhìn một kẻ thù không thể với tới.","“Tôi không thích cảm giác nhìn nó thành hình trên đầu mình. Điềm gở. Tệ hơn nữa, đám Reunion có thể đang rình rập ở mọi ngóc ngách. Mà nói thế có khi còn là dè dặt.”","“Đúng ra phải nói là chúng đang mở tiệc ngoài phố mới phải,” Nearl góp lời.","“Gần như phố nào cũng toàn tàn phá, bạo lực, cướp bóc,” người y tá càu nhàu. “Xe cộ, nhà cửa bị đốt. Vậy mà lũ côn đồ ấy lại thấy đây là thời tiết đẹp để đi dã ngoại!”","“Nếu bây giờ chúng đi dã ngoại,” Nearl nghiêm túc đáp, “thì Catastrophe sẽ là kẻ đánh chén xương cốt của chúng. Điều đó chứng tỏ phần lớn thành viên Reunion chỉ là những kẻ ngu muội bị kích động đến phát cuồng.”","Một quãng lặng ngắn.","“…Phì,” Amiya bật cười.","“Ừm, thật ra họ đâu có đi dã ngoại thật…” người y tá lí nhí. “Tôi chỉ muốn than vãn chút thôi. Chị không cần nghiêm túc đến thế đâu…”","Nearl chớp mắt. “…Ồ, cô không nói thật à? Khoan, cô đang cố pha trò sao? Hừm… Xin lỗi, tôi không giỏi mấy chuyện này lắm…”","“Không sao ạ… Chỉ là… nhịn cười khó quá…” Người y tá đỏ mặt. “Xin lỗi… vì đã đùa vào lúc nghiêm trọng thế này…”","“Không sao đâu,” Amiya nói, đôi tai thỏ khẽ rung. “Rhodes Island được lập ra đâu phải để ai cũng giữ bộ mặt nghiêm nghị. Bọn mình vẫn luôn mong mọi người đều có thể mỉm cười.”","“A-Amiya…”","“Đừng bận tâm nhé!”","Dobermann lắc đầu, nhưng khóe môi cô dịu đi một chút. “Dù sao thì, giúp một tay trinh sát đi. Tôi sẽ lặng lẽ xử lý tên địch ở hướng bốn giờ. Mong là nội tạng bệnh tật của chúng không phát nổ hay bị gài làm còi báo động.”","“Chúng tôi sẽ vòng qua, xử lý đám đông ở phía bên kia công sự,” Ace nói. “Hỗn loạn thế này, thêm chút tiếng ồn cũng chẳng ai để ý.”","“Được. Xuất phát!”","","<i>Thời gian: Không rõ. Thời tiết: Không rõ. Tầm nhìn: Kém.</i><br><i>Chernobog. Vị trí Đội tác chiến E0.</i><br><i>Chiến dịch giải cứu Doctor, giai đoạn 3.</i>","“A!” Người y tá dừng lại trước một tòa nhà đổ nát. “Phòng khám này… Amiya, chẳng phải chúng ta từng đến đây rồi sao?”","“Đúng vậy…” Amiya nhìn những ô cửa vỡ, những tấm biển cháy sém. “Nhưng sao nó lại… thành ra thế này?”","“Bị bỏ hoang hoàn toàn rồi… Trông như bị Reunion tấn công.”","“Đây chẳng phải Azazel, phòng khám dành cho người Infected sao?” một lính gác hỏi. Giọng anh ta nhuốm một nỗi bực bội cũ. “Dù có trong tay cả mạng lưới tình báo ngầm của Chernobog, họ vẫn từ chối hợp tác với ta. Hồi đó cũng chẳng rõ họ dính dáng gì với Reunion. Giá mà họ cho ta chút thông tin, dù chỉ một gợi ý thôi, thì giờ này ta đã ra khỏi đây rồi. Họ tự chuốc lấy kết cục này!”","“Đó không phải toàn bộ câu chuyện…” Amiya nói khẽ.","“Amiya, cô có mặt trong buổi đàm phán mà, phải không? Cái thái độ lạnh lùng kiêu ngạo của họ thật khiến tôi phát cáu…”","“Không thể trách họ được,” Ace nói.","@cg:bg_0_ori","“Đội trưởng…”","“Người Infected rất khó tin ai. Đã chịu đựng bao nhiêu khổ cực, ai có thể trách họ trở nên chai sạn và cố chấp?”","“Em hiểu vì sao họ làm vậy… và em có thể tha thứ cho họ,” Amiya nói. “Người không biết tự bảo vệ mình rất dễ bị kẻ khác làm tổn thương. Hơn nữa, người Infected nhiều khi còn không tin được nhau. Không phải ai cũng chịu nổi những rủi ro mà chúng ta gánh…”","“Phòng khám cho người Infected?” Doctor hỏi.","Amiya quay lại, gật đầu. “Azazel… là một phòng khám chợ đen chỉ phục vụ người Infected. Với địa vị xã hội của người Infected, họ không thể công khai lộ diện. Có những người Infected không muốn bị tống vào khu cách ly, nên lẩn trốn khắp thành phố, chỉ cố sống sót qua ngày. Azazel tồn tại là vì những người ấy.” Cô bé nhìn bức tường đen muội khói. “…Hẳn là họ đã từ chối đề nghị của Reunion.”","Cô bé im lặng một lúc, rồi tiếp tục, như thể đây là bài học Doctor cần được dạy lại từ đầu.","“Doctor, em từng nói tất cả bọn em đều mang bệnh, đúng không? Căn bệnh này sẽ cướp đi mạng sống của bọn em, nhưng nó cũng ban cho bọn em những năng lực phi thường. Ví dụ, em có thể dùng Originium Arts mà không cần đến trượng phép. Nhưng căn bệnh này không chỉ hủy hoại cơ thể. Nó còn hủy hoại mọi cơ hội để sống một cuộc đời bình thường. Hay nói đúng hơn, chính ‘xã hội văn minh’ đã tước đi mọi thứ của bọn em.”","“Và Chernobog là ngọn hải đăng sáng chói của thứ ‘văn minh’ ấy. Sợ hãi, căm ghét, lưu đày, thanh trừng người Infected…”","“Và đây là cách nó kết thúc,” Nearl nói.","“Chỉ có điều,” Amiya nói, “có bao nhiêu người Infected thực sự được chọn giữa chúng ta, Reunion hay một tổ chức nào khác? Phần lớn họ đơn giản là mất trắng mọi thứ. Có lẽ phòng khám này là một nơi ấm áp mà vài người trong số họ có thể gọi là nhà…”","“Oripathy không có thuốc chữa. Ít nhất là lúc này, người Infected chỉ có thể chết trong tuyệt vọng. Và thi thể của họ… lại trở thành nguồn lây nhiễm mới. Với năng lực dị thường và căn bệnh lây lan chết người… người Infected là những kẻ bị căm ghét nhất trên hành tinh này.”","Cô bé nhìn Doctor, đôi mắt xanh lục không chút oán trách.","“Doctor, có lẽ chỉ nghe em giải thích qua loa thì Doctor chưa hiểu hết được. Nhưng khi tận mắt thấy hậu quả của những vấn đề này… Doctor sẽ hiểu. Doctor sẽ thấy hiện thực khắc nghiệt bao quanh người Infected.”","“Rhodes Island chủ trương bình đẳng cho tất cả, còn Reunion thì cuồng tín lấy người Infected làm trung tâm,” Dobermann nói. “Nhưng những tổ chức như chúng ta hiếm lắm. Tôi hiểu vì sao cậu giận, nhưng thật khó mà không cảm thông với phòng khám nhỏ này.”","Người lính gác cúi đầu. “…Tôi hiểu rồi. Có lẽ họ thật sự đã phải đối mặt với một cơn khủng hoảng vượt quá sức mình…”","“Dù sao,” Dobermann nói, “hãy để cơn giận ở lại đây, cùng với phòng khám này.”","“Rhodes Island có rất nhiều người tốt,” Amiya nói. “Dù sợ hãi và thù địch có thể tạo ra khoảng cách giữa người với người, em tin mọi hiểu lầm đều sẽ được hóa giải, miễn là chúng ta là một gia đình.” Cô bé nhìn lại tòa nhà đổ nát lần cuối. “Có lẽ… Rhodes Island cũng chỉ là một Azazel khác thôi?”","“Amiya…”","“Đi thôi, Doctor.”"],"bg":"bg_cher_1","cast":[["Amiya","op:char_002_amiya"],["Dobermann","npc:char_130_doberm_ex"],["Nearl","op:char_148_nearl"],["Ace","npc:char_014_riope"]]},{"c":"1-3","t":"Lao đi","p":["“Chúng ta còn chưa đầy một tiếng. Không thể đi vòng được nữa,” Dobermann nói. “Càng phí thời gian, càng dễ bị kẹt trong Catastrophe. Phải cắt thẳng qua khu vực này. Nhưng với quân số như ta, không thể che giấu hành tung được nữa. Đi qua những con phố hẹp, nguy cơ bị phục kích rất cao…”","“Kế hoạch là gì?” Nearl hỏi.","“Chẳng có nhiều lựa chọn…” Dobermann quay sang. “Doctor, người đánh giá thế nào?”","“Địch cần thời gian để tập hợp lại,” Doctor nói.","Như thể câu nói ấy là một mồi lửa, Dobermann và Nearl lập tức nối tiếp nhau, như hai người đã quen phối hợp từ lâu.","“Từng tên Reunion không phải đối thủ của ta. Nhưng phần lớn thời gian, chúng cố áp đảo bằng quân số.”","“Nếu ta tận dụng tốc độ, liên tục ép lên mà tránh giao tranh lớn…”","“Có vẻ chúng chưa dựng công sự nào.”","“Nếu ta xuyên qua được tuyến chặn của chúng…”","“Trông thì chúng đông hơn, nhưng đội hình lỏng lẻo không cản nổi ta. Qua các trận vừa rồi, tôi thấy cách liên lạc của Reunion cực kỳ thô sơ.”","“Nếu ta làm thật nhanh, đến khi chúng tập hợp được để chặn ta…”","“…thì ta đã đi xa từ lâu rồi.”","“Nghe được đấy,” Nearl gật đầu. “Ta sẽ xông vào, phá đội hình, phá hủy hỏa điểm, rồi rút thật nhanh. Dobermann, chị đang thử tôi đấy à?”","“Đối phó mối đe dọa trông thấy được thì dễ hơn nhiều so với bị kẹt giữa hai làn đạn,” Dobermann đáp, rồi liếc sang Amiya. “Tôi đoán đây là lệnh của Doctor, phải không Amiya?”","“Tình hình đã rõ. Em tin vào quyết định của Doctor…”","“…Niềm tin không dễ xây dựng chỉ sau một trận đánh,” Dobermann nói. “Tôi đánh giá cao Doctor, Amiya ạ. Nhưng đừng lơ là. Học hỏi trí tuệ của Doctor thì không có gì sai, nhưng nhớ rằng trên đời này, cô không thể hoàn toàn dựa dẫm vào ai.”","“…Em biết.”","Dobermann quay sang Doctor, giọng hạ xuống.","“Đừng hiểu lầm, Doctor. Tôi không cố làm khó người. Nhưng tôi mong người hiểu, Amiya vẫn cần học hỏi và trưởng thành. Nếu người ở vị trí của tôi, người cũng sẽ không để cô ấy dựa dẫm vào ai khác. Có điều, xin người biết rằng tôi đã công nhận năng lực chỉ huy của người.”","“…Cảm ơn.”","“Cũng không cần khách sáo vậy đâu. Giờ ta là chiến hữu rồi. Ít nhất trên chiến trường, tôi đã giao phó mạng sống của mình cho người.” Dobermann quay đi. “Thôi, không tán gẫu nữa. Nhanh lên.”","“Đúng vậy,” Nearl nói. “Kazimierz có câu: ‘Cái chết sẽ đuổi kịp kẻ dừng chân nghỉ ngơi.’”","","“Xông lên—!!”","Nearl lao vào tuyến chặn như một mũi giáo bạc. Đám Reunion còn chưa kịp quay đầu đã bị hất văng. “Hả? Kẻ nào đó?!”","“Nhìn đi đâu đấy? Đỡ này!” Dobermann vung roi.","“Quân Reunion đang tập hợp lại phía sau ta… chúng chuẩn bị tấn công!”","“Chúng không theo kịp ta đâu! Cứ xông tới!” Nearl hét. “Lũ côn đồ tầm thường này… không cản nổi chúng ta!”","“Sắp ra khỏi vùng Reunion kiểm soát rồi! Đừng dừng lại!!”"],"bg":"bg_cher_1","cast":[["Dobermann","npc:char_130_doberm_ex"],["Nearl","op:char_148_nearl"]]},{"c":"1-4","t":"Điềm báo","p":["“Phù… Cuối cùng cũng cắt đuôi được chúng.”","“Giữ tốc độ này, ta sẽ sớm ra khỏi khu trung tâm và đến lối thoát phía nam,” Ace nói.","Tiếng ồn ào và hỗn loạn mỗi lúc một lớn. Dobermann đoán đó là dân Chernobog đang cố sơ tán khỏi thành phố, va phải quân Reunion. Vài khu đã trống không. Những người không kịp chạy thì đang bị Reunion chặn lại.","Họ đi qua một quảng trường. Ace dừng lại, nhìn những cột đá đổ, những bồn hoa cháy đen.","“Nơi này từng là một quảng trường tráng lệ, rộng mênh mông. Giờ… chỉ còn là phế tích. Thành phố này đã hành hạ người Infected. Kết thúc theo cách này, gần như là một bài thơ.”","“Gần như…” Dobermann liếc ông ta. “Anh có vẻ đa cảm nhỉ.”","“Có lẽ, đã từng có lúc…”","“Trời còn tối hơn nữa,” Amiya nói. “Đến không khí cũng có mùi… như thứ gì đang cháy.”","Một tiếng thét vọng lại từ xa.","“Các người làm gì vậy?! …Aaaargh!!”","“Dân thường?” Ace quay phắt lại.","“Tôi không nghe thấy gì nữa,” Dobermann nói. “Khoảng cách này không thể biết họ là ai.”","“…Reunion đang tấn công họ…!” Amiya bước lên một bước.","“Ở đây ta không tận dụng được địa hình,” Ace nói, giọng trầm. “Ta không đủ sức cứu tất cả. Mạng sống rất quý giá, Amiya. Từng mạng một.”","Amiya đứng sững. Cô bé hiểu câu nói ấy có hai nghĩa: mạng sống của những người dân kia, và mạng sống của những người đang đứng quanh cô bé.","“Dù sao,” Dobermann nói, “ta đã đến quá muộn rồi. Huống chi, chính ta cũng đang gặp rắc rối.”","Từ các ngả đường dẫn vào quảng trường, những bóng mặt nạ trắng đang tràn ra.","“…Giết hết chúng.”","“Hôm nay đúng là không được nghỉ ngơi lấy một chút,” Nearl thở dài, giương khiên. “Một lượng lớn quân Reunion đang tràn qua các lối ra!”","“Chuẩn bị đánh mở đường!”"],"bg":"bg_cher_1","cast":[["Dobermann","npc:char_130_doberm_ex"],["Ace","npc:char_014_riope"],["Amiya","op:char_002_amiya"],["Nearl","op:char_148_nearl"]]},{"c":"1-6","t":"Catastrophe","p":["Ở một nơi khác, Mephisto đang thì thầm vào thiết bị liên lạc.","“Đúng vậy. Chúng không biết Faust đang bám theo. Tôi nhận được tin từ một trinh sát của cậu ấy. Rhodes Island đang bị kẹt quanh vành đai khu trung tâm. Dù chỉ là côn trùng, chúng vẫn có thể lợi dụng hỗn loạn của Catastrophe để trốn thoát. Với hiểu biết của chúng về tình hình Chernobog, chúng có thể cản trở kế hoạch của ta. …Ít nhất, diệt trừ chúng cũng chẳng hại gì.”","Đầu dây bên kia im lặng.","","“Lũ khốn Chernobog! Tại chúng mày, tất cả là tại chúng mày… mà người Infected chúng tao mới thành ra thế này!”","“Cút!” Dobermann quật ngã tên Reunion. “Lũ người này cứ như đang chờ chết vậy!!”","“Sao Reunion lại hoàn toàn phát cuồng thế này?” Nearl hét qua tiếng binh khí. “Sao chúng lại dồn nhiều quân ra đây vào lúc này?!”","“Vô lý! Chẳng có lý do gì để chúng tử thủ nơi này như vậy!”","“Operator Rhodes Island, giữ vững! Đẩy lùi Reunion, mở đường thoát!”","Trên một mái nhà cao, có một người phụ nữ đứng lặng nhìn xuống quảng trường. Bên cạnh cô ta là Crownslayer.","“Vậy đó là ‘Rhodes Island’ mà ta nghe nói bấy lâu sao?” Người phụ nữ khẽ cười. “Anh dũng thật.”","Dưới quảng trường, một hòn đá nhỏ rơi xuống, lăn lóc trên nền gạch.","“…Hả? Đá rơi? Vào lúc này?”","“Đừng dừng lại! Giữ phòng tuyến!”","“Có gì đó không ổn… Đá đang rơi từ các tòa nhà…”","Rồi một tên Reunion bắt đầu cười, tiếng cười cao vút như kẻ mất trí. “Đến rồi! Đến rồi! Ahaha… sự cứu rỗi đã đến với chúng ta! Ngày phán xét đã đến!”","Hắn chưa kịp dứt lời thì một khối đá khổng lồ đã giáng xuống. Rồi một khối nữa. Tiếng va đập nặng nề, rồi im bặt.","“Chúng… bị thứ gì đó đè bẹp?” Dobermann lẩm bẩm. “Là các người tấn công à? Hay chúng…”","“Dobermann! Nhìn kìa, bầu trời…!”","Tất cả ngẩng lên.","Bầu trời đã nhuộm một màu đỏ thẫm như máu. Mây đen cuồn cuộn sôi sục, những vệt lửa lăn trong lòng chúng như than hồng trong lò. Và từ đó, những tảng đá, những khối tinh thể Originium khổng lồ, bắt đầu rơi xuống.","“Mây đen sôi sục, cuộn trào trong biển lửa…” Nearl thì thầm, như đọc một câu kinh.","“Đừng hoảng!” Ace quát.","“Giữ tỉnh táo!”","@cg:avg_9_3","“Chúng ta vẫn có thể sống sót nếu hành động dứt khoát!”","Trên mái nhà, người phụ nữ cất giọng, tiếp lời câu thơ của Nearl, như thể cô ta đã đọc nó cả nghìn lần.","@cg:avg_9_1","“…Nỗi kinh hoàng tước đi tiếng nói của chúng sinh, đất đai chìm vào lặng câm. Khối Originium khổng lồ cúi đầu… rồi đổ xuống bóng tử thần cháy sém.”","“Talulah,” Crownslayer gọi. “Bước tiếp theo là gì?”","Talulah, thủ lĩnh của Reunion, nhìn xuống những bóng người nhỏ bé đang chống chọi giữa quảng trường.","“…Có lẽ chúng sẽ sống sót qua được Catastrophe.” Cô ta quay lưng. “Dọn sạch những kẻ còn sót.”","“Rõ.”","@bg:bg_cher_4","“Dù tôi đoán Reunion sẽ lợi dụng Catastrophe để trả thù,” Dobermann nói, mắt không rời bầu trời, “tôi không ngờ chúng dùng nó để hủy diệt hoàn toàn Chernobog… Đây không giống trả thù, mà giống một bản tuyên ngôn hơn. Kiểu như… ‘Kỷ nguyên của người Infected’ hay gì đó?”","“Aaaahh…” Người y tá run rẩy. “Cả bầu trời… đang sụp xuống…”","“Cẩn thận!!”","“Tỉnh táo lên!” Amiya kéo cô ấy lại. “Bảo vệ y tá, đưa cô ấy đến chỗ an toàn ngay!”","“Rõ!”","“Tất cả operator, tìm chỗ nấp!” Ace hét.","“Tất cả các đội, chuẩn bị…” Amiya nhìn lên bầu trời đỏ rực, và lần đầu tiên, giọng cô bé run lên. “…vượt qua Catastrophe!”"],"bg":"bg_cher_0","cast":[["Dobermann","npc:char_130_doberm_ex"],["Nearl","op:char_148_nearl"],["Mephisto","npc:char_1507_Mephisto_1"],["Crownslayer","npc:char_1502_crowns"],["Amiya","op:char_002_amiya"],["Talulah","npc:avg_npc_078"]]},{"c":"1-7","t":"Bạo chúa","p":["“Chuẩn bị va chạm!! Tản ra—!!!”","Thế giới vỡ vụn.","Những khối Originium rơi xuống như mưa thiên thạch, mỗi khối to bằng cả một chiếc xe, cắm phập vào mặt đất rồi nổ tung thành những mảnh tinh thể sắc như dao. Các tòa nhà đổ sập như những lâu đài cát. Bụi và khói bốc lên che kín bầu trời.","“Rơi nhiều quá… Cứ thế này, mọi tòa nhà trong thành phố sẽ bị phá hủy hết!”","“Phải di chuyển!” Ace hét. “Bám chặt!!”","Xung quanh họ, quân Reunion cũng đang chịu chung số phận. Tiếng gào thét vang lên khắp nơi.","“Aaaaagh!! Nó rơi xuống… Nó rơi xuống!”","“Trời sập rồi!”","“Đau quá…! Tay tôi… tay tôi! Tay tôi đâu rồi…”","“Không, không!! Tôi không muốn chết…!”","“Defender!” Nearl ra lệnh. “Bảo vệ Caster!!” Rồi cô khựng lại. “…Tiếng gì thế?!”","“Một khối lớn vừa đánh sập tòa nhà bên kia đường! Nằm xuống!!”","Người y tá đứng chết trân giữa đường, ngước nhìn bóng tối đang đổ ập xuống mình.","“…Đừng đứng đó… Y tá! Cẩn thận!”","“Không xong… Y tá, chạy đi!”","Doctor không nghĩ. Có lẽ không có thời gian để nghĩ. Chỉ có hai bàn tay đẩy mạnh, một cơ thể lao về phía trước.","“Aaaahh! …Hả, D-Doctor?”","“Doctor đẩy y tá ra ngoài? Vậy chẳng phải… Doctor…?!”","“Không, Doctor!!”","“Doctor!!” Nearl đã lao đi trước khi ai kịp hét. “Nằm xuống, Doctor!”","Tấm khiên giương lên. Khối đá giáng xuống. Tiếng va chạm vang như sấm nổ, chấn động đến mức mặt đất lún xuống quanh chân Nearl.","“Chị ấy kịp rồi!”","“Chị ấy làm được… Chị ấy cứu được Doctor!”","Nearl ho ra máu, hai tay vẫn giữ chặt khiên. “Ổn rồi! Tôi vẫn cầm được khiên…! Nhảy đi, Doctor! Nhảy!”","Doctor nhảy. Ngay sau đó, Nearl cũng lăn khỏi chỗ vừa đứng, đúng lúc một khối đá thứ hai đập xuống.","“Doctor, Doctor…” Amiya chạy tới, hai tay run rẩy sờ khắp áo choàng của Doctor. “Doctor có… có bị thương không?”","“Tôi không sao. Cảm ơn cô đã cứu tôi, Nearl.”","“Sao người… sao người có thể tự lao vào nguy hiểm như thế!” Nearl gần như quát lên, lần đầu tiên mất bình tĩnh. “Ít nhất phải đưa tôi theo để tôi bảo vệ người chứ! Tôi không thể để người bị tổn thương… Nhất là ngay trước mắt tôi!”","“Mọi người đều còn an toàn, thật may mắn lắm…!” Amiya nói, nhưng trong lòng cô bé là những câu hỏi khác. <i>Chuyện này còn kéo dài bao lâu? Chúng ta còn sống được bao lâu nữa?</i>","Dần dần, những tiếng va đập thưa đi.","“Đá rơi ít hơn rồi sao?” Amiya ngẩng lên. “Vậy là ta đã vượt qua đợt va chạm đầu tiên…”","“Nhưng vẫn phải cẩn thận,” Dobermann nói. “Không ai biết Catastrophe này sẽ kéo dài bao lâu. Ít nhất… ta không chết giữa lòng nó. Ta may mắn mới lọt qua được.”","“Mọi người sao rồi?”","“Có vẻ toàn bộ operator đều qua được…! Vài người bị thương nhẹ, nhưng trong hoàn cảnh này, ta may lắm rồi! Chúng ta… chúng ta làm được rồi!”","Giữa đống đổ nát, một tên Reunion bò dậy, máu chảy ròng ròng trên mặt nạ. Hắn nhìn quanh, ngơ ngác. Rồi ánh mắt hắn dừng lại trên đồng phục Rhodes Island.","“…Hả? Hả… Ahh!! Rhodes Island!”","“…Cái gì?”","Hắn lao tới, vũ khí giương cao. Rồi một tên nữa, rồi thêm nhiều tên khác, từ những đống gạch vụn, lảo đảo như những bóng ma.","“Chúng vẫn còn định tấn công ta sao?!”","“Rhodes Island! Quay lại đây…!”","“Lũ các ngươi bị làm sao vậy!” Dobermann gầm lên. “Chúng điên hết rồi.”","“Chúng không coi trọng mạng sống của mình chút nào sao?!” Nearl kêu lên.","“Dobermann…”","“Không còn cách nào khác,” Dobermann nói. “Áp chế chúng trước, rồi lập tức di chuyển!”","@bg:bg_cher_7","“Hộc… hộc…”","“Ta qua được rồi…!” Nearl nói, giọng vỡ ra vì mệt. “Không chỉ cắt đuôi được Reunion… mà Catastrophe cũng đang yếu đi rõ rệt! Nhưng tình hình vẫn rất tệ. Mọi người, tiếp tục cẩn thận!”","Đường phố đã bị vùi dưới gạch đá. Những tòa nhà sụp đổ chắn kín mọi ngả. Dobermann nhìn những vết tinh thể đen lan dần trên tường như rêu mốc. “Originium đã bắt đầu di căn rồi sao…? Gần đến nơi rồi, vậy mà mọi thứ đều chắn đường! Nếu ta chỉ cần…”","“Chúng đến rồi,” Ace nói.","“Cái gì đến? Reunion? Chúng đuổi kịp ta rồi sao?!”","“Không chỉ đuổi kịp…” Dobermann nhìn quanh, và giọng cô lạc đi. “Chúng…”","“…Ở khắp mọi nơi,” Nearl nói.","Từ quảng trường, từ những con phố, từ các tòa nhà và cả những đống phế tích, quân Reunion đang hiện ra. Không phải vài chục, không phải vài trăm. Mà là một biển mặt nạ trắng, trải dài đến tận chân trời.","“Nhìn quân số kia đi. Hah…” Dobermann cười khan. “Thảo nào chúng chẳng hề sợ Catastrophe, trừ những kẻ xấu số bị đè bẹp. Cứ cho là Catastrophe đã quét sạch một nửa quân số của chúng… thì ở đây vẫn còn đủ người để giết chúng ta cả chục lần.”","“Đừng dừng lại!” Nearl hét. “Ta sẽ tiếp tục đi về hướng đường lui! Dừng lại ở khoảng trống này là chết chắc! Ít nhất phải đến được lối ra quảng trường rồi mới tập hợp!”","“Chị Nearl…”","“Phải đánh thôi. Phá được phòng tuyến của chúng, ta sẽ lẻn ra trong hỗn loạn.”","“Chị chắc nó sẽ hiệu quả chứ?”","“Cơ hội rất mong manh, nhưng ta không còn lựa chọn. Có điều… Dù chúng đông gấp mười lần, nếu chỉ là một lũ côn đồ, ta vẫn có cơ hội! Bình tĩnh! Chuẩn bị chiến đấu! Đội hình phòng ngự!”","Nhưng quân Reunion không tấn công.","“Chúng… dừng lại rồi!”","Cả biển người đứng im lặng như tượng. Không một tiếng hò hét, không một bước chân. Rồi đội hình rẽ ra.","“Chỉ có một kẻ địch đang tiến về phòng tuyến của ta!”","“Sao người đó lại đi về phía ta một mình…?”","“Phái sứ giả sao? Tôi không nghĩ vậy…”","Người phụ nữ bước đi chậm rãi giữa lối đi mà cả nghìn người đã mở ra cho cô ta. Mái tóc dài, áo choàng phủ kín, một thanh kiếm bên hông. Cô ta không đeo mặt nạ. Gương mặt điềm tĩnh, gần như dịu dàng.","“Cô ta…” Amiya lẩm bẩm. “Theo tình báo, cô ta là…”","“Mùi của cô ta có gì đó lạ lắm,” Nearl nói khẽ. “Tôi không nói rõ được, nhưng… đó là mùi thép và lưu huỳnh. Như có thứ gì đang cháy. Nếu đó thật sự là lửa, thì…”","“Tất cả operator… cảnh giác tối đa.” Giọng Amiya khô khốc. “…Người đó là…”","“Kẻ thống trị Reunion…” Dobermann nói.","“…Talulah.”","Talulah dừng bước, cách phòng tuyến Rhodes Island vài chục mét. Cô ta không nói gì. Chỉ nhìn.","Và Nearl, Hiệp sĩ Ánh Sáng của Kazimierz, người chưa bao giờ biết lùi bước, cảm thấy hai bàn tay mình lạnh toát dưới lớp găng.","“Tôi đoán…” cô nói, “ngọn lửa của cô ta đủ mạnh để nuốt chửng cả Terra.”"],"bg":"bg_cher_10","cast":[["Nearl","op:char_148_nearl"],["Dobermann","npc:char_130_doberm_ex"],["Amiya","op:char_002_amiya"],["Ace","npc:char_014_riope"]]},{"c":"1-8","t":"Quyết tâm","p":["“Amiya, đưa Doctor đi.” Nearl không quay đầu. “…Đi ngay!”","“Không! Em không bỏ chị lại đâu…”","“Cô cũng cảm nhận được, phải không? Cô ta… Nếu cô không đi, cả đội cứu hộ sẽ chết ở đây! Talulah đó là một con quái vật sống! Amiya!”","“Chỉ cần chúng ta đứng cùng nhau thì sẽ ổn thôi!”","“Thế còn Doctor thì sao? Cô có thể đảm bảo an toàn cho Doctor không?”","Amiya không trả lời được.","“Đội E4, chúng ta sẽ ở lại cầm chân! Phải đảm bảo Amiya, Doctor và đội y tế thoát ra an toàn!”","“Không,” Ace nói. “Đội của tôi sẽ lo việc này.”","“Ace! Hãy lý trí đi, giờ không phải lúc tranh cãi!”","“Tôi đang lý trí.”","“Anh cũng thấy mà, mọi thứ quanh cô ta đang tan chảy!”","“Em sẽ không để mọi người ở lại chiến đấu một mình!” Amiya hét lên. “Rhodes Island… sẽ không bỏ rơi mọi người!”","“Amiya, thời gian là vàng bạc! Cô phải trốn đi!” Dobermann quát.","“…Cô nên tin tôi,” Ace nói.","“Em không thể nhìn Rhodes Island hy sinh bất cứ ai!”","“Nghĩ đến mục tiêu của chúng ta đi! Nghĩ xem chúng ta đến đây để làm gì!”","“Giờ không phải lúc nói chuyện đó!”","Talulah đưa một tay lên.","“…? Hơi nóng… đang tụ lại trong tay cô ta?” Nearl nheo mắt.","“Cô ta đang… bẻ cong không gian quanh mình sao?” một lính gác thì thào.","“Không, đó là… không khí bị đốt nóng quá mức quanh cô ta!”","“Cẩn thận! Cô ta chuẩn bị dùng Arts…” Amiya hét lên khi thấy Nearl đã lao về phía trước. “Không… Không được! Chị Nearl!! Quay lại ngay!! Đó không phải… Chị sẽ bị giết nếu—”","“…Im lặng,” Talulah nói.","Một làn sóng nóng quét qua. Nearl bị hất văng, ngã vật xuống, bộ giáp bạc cháy đen, bốc khói.","“Nearl!”","“Khụ… Lùi lại! Đừng lo cho tôi… Chỉ hơi… ấm một chút thôi…”","“Chị nói gì vậy… đừng lo?” Dobermann gào lên. “Trên người chị không còn một mảnh giáp nào nguyên vẹn, mà chị bảo tôi đừng lo?! Không được đánh với cô ta nữa!”","“Tôi đã bảo… lùi lại!”","“Nearl! Đồ cứng đầu…!”","Talulah khẽ nghiêng đầu. “…Hửm?”","“Nằm xuống!” Ace kéo cả hai người ngã sấp. Ngay trên đầu họ, một thứ gì đó vô hình lướt qua, và bức tường phía sau tan chảy như sáp nến.","“Khụ khụ… Lại gì nữa đây!”","“…Lửa vô hình vừa quét qua đầu ta,” Ace nói. “Lùi lại. Cả khu này đang tan chảy… Đừng hy sinh vô ích!”","Nearl nhìn bức tường đã hóa thành dòng đá nóng chảy, và lần đầu tiên trong đời, cô thực sự không biết mình đang đối mặt với thứ gì.","“Rốt cuộc tôi đang chiến đấu với con quái vật nào vậy?”","“Phải cắt ngang việc thi triển của cô ta bằng cách nào đó…” Ace giơ tay. “Sniper, ngắm vào địch!”","Talulah nhìn những mũi tên đang chĩa về phía mình, không hề nao núng.","“Sự kháng cự sẽ mang hy vọng đến với vùng đất này,” cô ta nói. “Nhưng kháng cự… sẽ không thay đổi được số phận của các ngươi.”","“Bắn!!”","Những mũi tên bay đi. Và chúng biến mất. Không cháy, không gãy. Chỉ đơn giản là biến mất giữa không trung, như chưa từng tồn tại.","“Chernobog đã được giải phóng,” Talulah nói, như thể không có gì vừa xảy ra. “Công việc của chúng ta ở đây đã xong, và nhóm của các ngươi tỏ ra khá thú vị. Nhưng các ngươi chỉ đáng đến thế thôi. Các ngươi đã chọn sai rồi.”","“Rhodes Island, lẽ ra các ngươi phải đứng vững về phía người Infected.”","Quanh cô ta, nền quảng trường bắt đầu cháy sém.","“Chuyện gì… đang xảy ra vậy?” người y tá thở hổn hển. “Sao cả quảng trường… đang bị thiêu đốt? Vừa rồi… đã xảy ra chuyện gì…? Tôi… tôi không thở được… nóng quá…”","“Đá, đinh, tên…” một lính gác lẩm bẩm. “Biến mất hết rồi. Chỉ trong một nhịp tim… mọi vật quanh cô ta đều tan thành hư vô… Đến tro cũng không còn…”","“Các ngươi có sự kiên cường của những người giải phóng,” Talulah nói.","“Amiya,” Nearl gọi, giọng khàn đặc. “Cô biết phải làm gì rồi đấy. Phải có ai đó… ngăn cô ta lại.”","“…Nhưng ta chán rồi,” Talulah nói.","“Amiya!!”","@cg:avg_11_1","“Đây là cái giá các ngươi phải trả vì đã tàn sát đồng loại Infected của mình.” Talulah nâng tay lên lần nữa. “Ta sẽ ban cho các ngươi một kết cục mà ta khá ưa thích. …Biến mất đi.”","“Chết tiệt!!” Dobermann gào lên. “Chạy… nhanh lên!! Nhiệt lượng đó, quy mô đó… Không, không! Bảo vệ Amiya và Doctor! Nhanh!!”","“Không kịp đâu…!” Nearl bật dậy. “Tôi sẽ chặn nó!!!”","Ngọn lửa ập tới.","Rồi dừng lại.","“…Hả???” Người y tá mở mắt. “A-Amiya?”","Amiya đứng giữa ngọn lửa và mọi người, hai tay dang rộng. Quanh cô bé, một thứ ánh sáng đen sẫm như mực trào dâng, cuộn lại thành một bức tường, chặn đứng biển lửa.","“Ngươi sẽ không làm hại họ,” Amiya nói. “Ta sẽ không bao giờ… cho phép ngươi làm điều đó!”","Talulah nhướng mày. “—Ồ?”","“Nghh… Ta phải… bảo vệ mọi người…!”","@cg:bg_1_reflect","“Amiya đang chặn Arts của địch… một mình…?” Dobermann không tin vào mắt mình.","“Không được… Sức mạnh đó quá khủng khiếp!” Nearl hét. “Ngay cả Amiya cũng không… Cô bé sẽ không trụ được lâu đâu!”","“Amiya!”","“Đừng lo… Đừng lo cho em… Em chịu được…! Em muốn… em phải… bảo vệ mọi người!”","“Hắc chất… đang phong ấn Arts của địch trong quảng trường…”","“Nghh… Argh… Ughh!”","“B-bức chắn của cô bé đang bốc cháy!”","“Amiya, dừng lại!! Chiếc nhẫn của cô sẽ—!”","“Em không quan tâm… dù cho…” Amiya nghiến răng, máu rỉ ra nơi khóe môi. “Doctor, em xin lỗi… Dù điều này có mang đến tai họa, dù em có…! Em không muốn mất đi… người quan trọng nhất của em… thêm một lần nào nữa…”","“Heh…” Talulah mỉm cười, lần đầu tiên. “Rất tốt.”","“Aghh… Aaaaaahhh…!!”","“Amiya! Chết tiệt… Ta sắp mất cô bé rồi…!” Nearl đứng dậy, giương khiên lên cao.","“Chị làm gì vậy?”","“Phá Arts của con rồng cái đó!”","“Chị…”","“…‘Hỡi Ánh Sáng của Kazimierz, Hiệp sĩ Ánh Sáng xin dâng hiến thân mình cho Người…’”","“Doctor! Đi đi! Chúng tôi sẽ giúp Amiya, nhưng người phải…”","Talulah khựng lại. Một thoáng, chỉ một thoáng thôi, gương mặt cô ta lộ vẻ ngạc nhiên.","“Aaaaaaaaghhh!! …Cái gì…?”","Có một bàn tay lớn đặt lên vai Amiya.","“Đủ rồi, Amiya,” Ace nói.","Cô bé quay lại. Ace đứng đó, tấm khiên giương lên, chắn trước bức tường đen đang vỡ dần.","“Cô đã làm rất tốt. Để chúng tôi chia sẻ gánh nặng với cô.”","“Em…”","“Dobermann, đưa cô bé đi. Hẹn gặp lại sau.”","“…Ace…”","“Ace… Không… Ace…!” Amiya vùng vẫy khi Dobermann bế xốc cô bé lên. “Hứa với em… là anh sẽ…”","Ace không đáp lời cô bé. Ông ta quay sang Doctor, ánh mắt bình thản lạ lùng, như ánh mắt của người đã chọn xong con đường từ lâu.","“Xin lỗi, Doctor. Có lẽ người không nhớ tôi. Nhưng tôi nhớ người, và tôi biết người là người như thế nào.”","“…Sẽ có một ngày, người và Amiya cùng nhau đối mặt với vùng đất tàn khốc này. Vì vậy… người phải trân trọng cô bé, Doctor.”","Ông ta quay lưng, đối diện biển lửa và người phụ nữ đứng giữa nó. Những thành viên Đội E3 lặng lẽ bước lên, đứng thành hàng sau lưng ông ta. Không ai được lệnh. Không ai cần được lệnh.","“Đi thôi.”","“Thượng lộ bình an.”"],"bg":"bg_cher_7","cast":[["Nearl","op:char_148_nearl"],["Amiya","op:char_002_amiya"],["Ace","npc:char_014_riope"],["Talulah","npc:avg_npc_078"],["Dobermann","npc:char_130_doberm_ex"]]},{"c":"1-10","t":"Tàn dư","p":["“Ta đã phá được vòng vây của Reunion!”","@cg:avg_11_2","“Nhưng… họ…” Nearl ngoái lại nhìn quảng trường đỏ rực sau lưng, giọng vỡ vụn. “…Tôi… Aaaagh…”","“Suỵt…” Dobermann giữ chặt vai cô. “…Đừng để Amiya nghe thấy.”","“Amiya vẫn giữ được tỉnh táo suốt mọi chuyện! Con bé trưởng thành hơn chúng ta tưởng nhiều…!”","“Dù vậy, cũng không được để con bé nghe thấy! Ta không thể đè thêm gánh nặng lên con bé. Con bé đã… gánh cả thế giới trên vai rồi.” Dobermann nghiến răng. “…Ta không thể để nỗ lực của họ thành vô ích! Họ đã chọn điều tối thượng để chúng ta được sống. Ta phải đáp lại… bằng cách đảm bảo Amiya và Doctor trở về an toàn.”","Nearl im lặng rất lâu. “…Đúng vậy.”","“Giờ không phải lúc nản lòng. Là Hiệp sĩ Ánh Sáng, chẳng phải chị luôn phải là ngọn đèn hy vọng của chúng tôi, dù chuyện gì xảy ra sao?”","“…Tôi không còn chắc nữa. Nhưng tôi sẽ làm phần việc của mình.” Nearl đứng thẳng dậy. “Tập hợp! Đừng lơ là! Ta sắp đến nơi rồi!”","Dobermann nhìn theo bóng lưng cô, rồi thở dài, rất khẽ.","“Những người bảo tôi đừng lo… chẳng ai trong số họ quay về cả.”","","Amiya tỉnh dậy trên lưng Doctor.","“…Ưm…? Doctor…? Chuyện gì đã xảy ra…?”","Cô bé vùng vẫy một chút. “X-xin để em xuống… Em không sao, em tự đi được… Em chỉ… ngất đi một lúc thôi… nhưng em ổn mà.” Đôi chân chạm đất, chênh vênh. “…Chúng ta thoát ra được rồi sao? Còn Ace và mọi người…?”","Doctor không trả lời.","Amiya nhìn Doctor một lúc lâu. Rồi cô bé cười, một nụ cười rất nhỏ.","“Em hiểu rồi. Không sao đâu. Em chắc Ace sẽ ổn thôi. Ai ở Rhodes Island cũng đều rất mạnh mà.”","“Sắp đến lối ra phía nam rồi. Ra khỏi Chernobog là chúng ta sẽ…” Giọng cô bé nhỏ dần. “Chúng ta sẽ… được…”","“…Doctor… Em dựa vào Doctor một chút… được không… Chỉ… một chút thôi…”","Doctor để cô bé tựa vào vai mình. Cô bé nhẹ bẫng, nhẹ hơn nhiều so với sức nặng cô bé đang mang.","@bg:bg_cher_2","Giữa quảng trường giờ đã thành biển lửa, Talulah đứng lặng.","“…Phiền phức thật.”","Bên cạnh cô ta, Mephisto nhìn quanh, gương mặt thiên thần lần đầu tiên tái nhợt.","“Sao gã đó… làm được chuyện này… Nửa thành phố cháy thành tro, cả quảng trường biến thành biển lửa… Thép nóng chảy rồi đông lại… Vậy mà sao gã vẫn… đứng vững mà chiến đấu được?”","Một giọng nói khác, trầm và nặng như đá, vang lên từ phía sau. “Gã chiến đấu đến hơi thở cuối cùng… Đáng nể.”","“Ta sẽ ghi nhớ điều này,” Talulah nói, mắt nhìn về phía nam, nơi bóng dáng đoàn người đã khuất. “…Rhodes Island.”"],"bg":"bg_light","cast":[["Amiya","op:char_002_amiya"],["Dobermann","npc:char_130_doberm_ex"],["Nearl","op:char_148_nearl"],["Talulah","npc:avg_npc_078"],["Mephisto","npc:char_1507_Mephisto_1"]]},{"c":"1-12","t":"Chiến thắng cay đắng","p":["<i>Thời gian: Không rõ. Thời tiết: Không rõ. Tầm nhìn: Kém.</i><br><i>Chernobog. Vị trí Đội tác chiến E0.</i><br><i>Chiến dịch giải cứu Doctor, giai đoạn rút lui cuối cùng.</i>","“Chết tiệt! Đã đến được lối ra rồi mà…!”","Chắn ngang cổng thành phía nam là một nhóm Reunion, và đứng đầu là một người phụ nữ tóc bạc, đôi sừng nhỏ cong cong trên đầu, tay tung hứng một khối thuốc nổ như trái táo.","“Các người tưởng chúng tôi sẽ để các người ung dung bước ra khỏi Chernobog thật à? Chẳng phải đã đến lúc có ai đó đánh thức các người khỏi giấc mộng giữa ban ngày rồi sao?”","“Liên lạc đã khôi phục, tôi đã báo cho O.P.D., họ sẽ sớm đến hội quân!” Dobermann nói gấp. “Nhưng cái thứ chết tiệt này…”","“Cẩn thận, cô ta đang cầm thuốc nổ!” Nearl cảnh báo.","“Tôi vẫn không liên lạc được với đội trinh sát!”","Amiya bước lên. “…Rốt cuộc cô là ai?”","“Tôi không mong cô biết tôi là ai…” Người phụ nữ nheo mắt, nụ cười kéo dài đến mang tai. “Nhưng tôi biết người đứng cạnh cô.”","“Reunion… vẫn muốn tiếp tục đánh với chúng tôi sao?”","“Này, này, đừng như vậy chứ. Tôi chẳng ưa gì con rồng cái Talulah ấy. Tôi cũng không hợp với cái việc giữ cổng này. Làm cả ngày rồi còn phải chạy đến đây, phiền chết đi được. Vậy vì sự hợp tác trong tương lai, sao ta không chào hỏi nhau chút đã nhỉ?” Cô ta cúi chào kiểu cách. “Cứ gọi tôi là… W.”","“Tôi đã chờ rất lâu để được gặp người đứng cạnh cô.” W nhìn thẳng vào Doctor. “Doctor… Tôi có vài câu hỏi nho nhỏ muốn hỏi người. Phiền mọi người cho bọn tôi chút… không gian riêng được không?”","“Đừng phí lời,” Nearl nói.","“Đừng vội thế chứ. Tôi có tin các người sẽ thích nghe đấy. Thật ra, bọn tôi vừa gặp vài gã khá lanh lợi… Giỏi lắm, mặc đồ y hệt các người. Đủ để qua mặt Ursus, nhưng tôi nhìn thấu cái mánh nhỏ đó ngay~”","“Có phải là đội trinh sát không?” Amiya thở phào. “May quá… họ an toàn…”","“Thỏ con, cô là thủ lĩnh của bọn họ à?”","Amiya giật mình.","“Tôi tò mò lắm. Cô có sức hút gì mà khiến họ hào hứng hiến dâng mạng sống cho cô, không chút hối tiếc thế?”","“Cô… nói gì vậy…?”","“Cô nghe rõ rồi đấy. Chẳng ai trong số họ… sẽ quay về với cô nữa đâu.” W nghiêng đầu, cười. “Này, cô… Cô thật sự đáng để họ đánh đổi mạng sống sao?”","Amiya không nói gì. Hai bàn tay cô bé run lên.","“Mục đích của cô khi làm thế này là gì, W?” Doctor hỏi.","“Tôi chưa nói xong mà.” W không thèm nhìn Doctor. Cô ta chỉ nhìn Amiya, chờ đợi, như một đứa trẻ chọc gậy vào tổ kiến. “Amiya… Tôi làm cô giận rồi à?”","“…Cô đã đi quá xa rồi.”","“Tốt, tốt… Thế mới phải chứ.” W dang tay. “Lại đây.”","“W của Reunion Movement, cô đã đi quá xa rồi!” Giọng Amiya vang lên, và lần đầu tiên, trong đó có một thứ sắc lạnh như lưỡi dao. “Mạng sống nào cũng quý giá, từng mạng một… Đó là điều cô không bao giờ được phép làm vấy bẩn!”","“Doctor!!”","“Rhodes Island, chuẩn bị chiến đấu!”","“Hehe…”","","Trận đánh kết thúc khi W nhảy lùi khỏi vòng giao tranh, phủi bụi trên áo như thể vừa đi dạo về.","“Ahh… Cảm giác hoài niệm quá!” Cô ta nhìn Amiya. “Amiya, phải không nhỉ?”","Rồi cô ta khựng lại. Một thoáng im lặng, như đang lục lọi trong ký ức. Rồi W bật cười, tiếng cười lanh lảnh.","“A, ahaha! Ra vậy… Ra là thế. Tôi nhớ ra rồi, Amiya.”","“…Cái gì?”","“Tôi lấy được thứ mình cần rồi. Các người đi được rồi đấy. Xùy.”","“Cô…!”","“W…?” Một tên Reunion ngơ ngác.","“…Gì, lũ các người muốn ở lại đây chết à? Tôi thì sao cũng được. Các người cứ tự nhiên.”","Tên Reunion im lặng, rồi quay sang đồng bọn. “Rút. Để chúng đi. Lệnh của Talulah.”","“Thôi bỏ đi. Kéo dài quá thì chán lắm. Tôi ghét chán, đơn giản vậy thôi.” W quay lưng, vẫy tay. “Có điều, tôi rất mong được gặp lại cô, Amiya. Và cả… người đó nữa. Lần sau, tôi sẽ nghe sự thật từ chính miệng người, Doctor. Bái bai~”","“Cái gì… Sao… cô ta lại làm vậy?” Amiya nhìn theo.","“Reunion… rút rồi,” Dobermann nói. “Ta đã lỡ giờ hẹn từ lâu. Lập tức rút về Rhodes Island.”","“…Em sẽ hộ tống các operator ở phía sau,” Amiya nói.","“Amiya…” Nearl bước tới.","“Em không sao.”","Nearl nhìn cô bé, rồi lặng lẽ gật đầu. “…Được rồi.”","“Đi đi, Amiya,” Dobermann nói.","@bg:bg_cher_7","Ở quảng trường phía sau, giữa đống tro tàn còn âm ỉ cháy, có hai bóng người.","“…Đội trưởng…?” Người lính gác mở mắt. “Những người khác đâu…?”","“Nearl và mọi người đã thoát ra cùng Amiya và Doctor,” Ace nói. “Những người ở lại… đều đi cả rồi. Chỉ còn hai chúng ta.”","“…Cái gì…” Người lính gác run lên. “Tôi nhớ ra rồi… Con quái vật đó… Talulah… một mình cô ta… Cô ta hất văng Guard của ta như đồ chơi xếp hình… Cắt xuyên qua Defender như cắt bơ… Catastrophe…! Cô ta là Catastrophe hiện thân… Không thì sao có thể biến cả đội ta thành tro chỉ trong một khoảnh khắc… Tôi tận mắt thấy mà vẫn không… không thể tin được… Những tiếng thét… Aagh… Gaaah…”","“Tỉnh lại đi!”","“Tôi xin lỗi… Tôi không biết phải…”","“Bình tĩnh. Tôi đã sơ cứu cho cậu rồi.”","“…Đội trưởng… tay của anh… sao vậy…?”","“Ít ra tôi vẫn còn một tay dùng được.”","“Đội trưởng… anh đi đi. Tôi chắc anh sẽ phá vây được mà.”","“Chúng ta chỉ cầm chân được cô ta vài phút.” Ace đứng dậy, cầm lấy tấm khiên đã méo mó bằng bàn tay còn lại. “Chừng nào Doctor và Amiya chưa an toàn, tôi chưa thể đi. Tôi phải ngăn con quái vật đó trước đã.”","“Đội trưởng… Tôi cũng…”","“Cái giá cho mạng sống của cậu… là cánh tay của tôi.” Ace nhìn xuống người đồng đội. “Nếu cậu sống thêm được dù chỉ một phút nữa, nó cũng đáng.”","“…”","“Tôi sẽ quay lại ngay. Giữ gìn nhé.”","Ace bước đi, về phía biển lửa. Người lính gác nhìn theo bóng lưng ấy, nước mắt chảy dài trên gò má đen nhẻm.","“Đội trưởng… Tôi xin lỗi… vì tôi vô dụng quá… Amiya… Tôi chắc cô sẽ… biến giấc mơ của mọi người thành…”","","Trên con đường phía nam, Amiya bỗng dừng bước.","“…Amiya? …Amiya?”","“A, hả?”","“Sao vậy?” người y tá hỏi.","“K-không có gì… Chỉ là tự nhiên em thấy…” Amiya đặt tay lên ngực, như thể có thứ gì vừa vỡ ra trong đó. “…Đau buồn…”","Người y tá sụt sịt, rồi òa khóc.","“…Đừng khóc,” Amiya nói khẽ. “Ít nhất… là lúc này. Có người từng nói với em… Nước mắt nên để dành cho khi chiến tranh kết thúc. Giờ… chưa phải lúc.”","Cô bé cầm tay người y tá, kéo đi.","“Đi thôi… Chúng ta về nhà.”"],"bg":"bg_cher_3","cast":[["Amiya","op:char_002_amiya"],["W","npc:avg_npc_046"],["Ace","npc:char_014_riope"],["Dobermann","npc:char_130_doberm_ex"],["Nearl","op:char_148_nearl"]]}],"id":"main_1","no":"Chương 1","title":"Thời khắc tà ác · Phần 2","en":"Evil Time, Part 2","sum":"Catastrophe giáng xuống Chernobog. Giữa quảng trường rực lửa, Rhodes Island đối mặt kẻ đứng đầu Reunion, và phải trả một cái giá không bao giờ quên để Doctor được trở về."},{"secs":[{"c":"2-1","t":"Hướng về Lungmen","p":["<i>5:57 sáng. Nhiều mây. Tầm nhìn 17 km.</i><br><i>Sa mạc, cách ngoại ô Lungmen 4 km.</i><br><i>4 ngày sau chiến dịch giải cứu ở Chernobog.</i>","“Chào buổi sáng, Doctor. Người đã ngủ được 99999—”","@cg:bg_2_call","“—9999 giờ.”","Giọng PRTS đều đều vang lên trong căn phòng nhỏ trên con tàu Rhodes Island, không chút cảm xúc, nhưng Doctor ngờ rằng có một chút gì đó giống như trêu chọc trong cách nó ngắt câu.","“Dù việc người ngại rời giường không phải là không có lý do, sự hiện diện của người đang được cần gấp tại phòng chỉ huy tác chiến. Ngoài ra, đây là lời khuyên y tế từ bác sĩ Kal’tsit: Xin hãy mở cửa sổ để duy trì nguồn không khí trong lành, và dành thời gian lên boong tàu để duy trì mức Vitamin D khỏe mạnh.”","Phòng chỉ huy tác chiến sáng đèn từ sớm. Amiya quay lại khi nghe tiếng cửa mở, đôi tai thỏ vểnh lên.","“A, Doctor! Chào buổi sáng ạ.”","“Doctor đến rồi,” Dobermann gật đầu.","“Doctor thấy đỡ hơn chưa ạ? Hôm qua trông Doctor vẫn còn đau, đi lại cũng khó khăn.”","“Tôi khỏe hẳn rồi. Còn em?”","“Hôm nay em hoàn toàn ổn, tràn đầy năng lượng luôn!” Amiya cười, nụ cười tươi tắn như chưa từng có Chernobog. Nhưng Doctor đã học được cách nhìn kỹ hơn: quầng thâm dưới mắt cô bé, những ngón tay vô thức xoay chiếc nhẫn trên tay. “Dù sao, chúng ta vẫn còn những nhiệm vụ khác phải lo. Chuẩn bị càng sớm càng tốt. Doctor nên làm quen với việc phải chuyển trạng thái thật nhanh ở đây.”","“Doctor,” Dobermann nói. “Dù chúng ta tổn thất nặng nề ở Chernobog, chúng ta đã thu được nhiều thông tin về Reunion, và quan trọng hơn, đưa được người ra an toàn. Dựa trên cuộc đàm phán hôm qua, nomadic city gần nhất là Lungmen đã đề nghị một hiệp ước hợp tác và đồng ý trao đổi thông tin. Chúng tôi có vài bằng chứng cho thấy Reunion có thể đang nhắm đến Lungmen tiếp theo. Phải chờ bác sĩ Kal’tsit cho phép mới lấy được phần còn lại của thông tin. Cô ấy vẫn đang ở trong Lungmen.”","“Lungmen cho phép chúng ta tạm thời đóng trại gần thành phố,” Amiya nói tiếp. “Họ cũng đồng ý bồi thường một phần tổn thất và chi phí trong chiến dịch. Đổi lại, Rhodes Island phải giúp phòng thủ vùng ngoại ô. Nhưng lý do em gọi Doctor sớm thế này là vì…”","“Để tôi giải thích, Amiya.” Dobermann gõ lên bản đồ. “Đêm qua, chúng tôi phát hiện thêm một đợt người sống sót từ Chernobog đang tiến về Lungmen. Dự kiến họ sẽ đến vào buổi chiều. Ta sẽ bảo vệ ngoại ô Quận 5 như mấy ngày qua. Chỉ là lần này, có thể có nhiều thành viên Reunion trà trộn trong đoàn. Tình hình khác đi, nên trước khi bắt đầu chiến dịch, cần bàn với người vài chiến thuật mới.”","“Dù sao, Doctor, hôm nay có nhiều việc lắm, nên…” Amiya nắm chặt tay. “Cùng cố gắng nhé!”","“Cả hai hoàn tất chuẩn bị chiến đấu đi,” Dobermann nói. “Doctor, khi đã phân xong đội hình, hãy báo cho các operator để họ có thời gian chuẩn bị. Mười lăm phút sau khi diễn tập xong, ta xuất phát.” Cô ngừng lại. “À, lần này nhớ đừng đến muộn.”","@bg:bg_0_rhodes3","<i>10:14 tối. Trời quang. Tầm nhìn 19 km.</i><br><i>Lungmen, Quận 5. Khu kiểm dịch.</i>","“Thưa sếp. Họ đến rồi.”","Loa phát thanh vang vọng khắp khu kiểm dịch, giọng nữ đều đặn lặp đi lặp lại.","“Xin chú ý… Do ảnh hưởng của Catastrophe, mọi chuyến bay tại Lungmen đã bị tạm dừng. Tất cả lối vào Quận 5 sẽ đóng cửa sau hai giờ nữa. Cảm ơn quý vị đã hợp tác trong quá trình kiểm tra Oripathy. Nếu phát hiện bất kỳ người Infected chưa đăng ký nào, xin báo ngay cho cảnh sát gần nhất. L.G.D. sẽ tạm giữ họ theo ‘Luật Xử lý Khẩn cấp’. Xin chú ý…”","“Đúng như lời đồn…” Amiya lẩm bẩm. Cô bé kéo mũ áo khoác thấp xuống một chút, che đôi tai. “Đi thôi, Doctor.”","Ở cuối hàng rào kiểm dịch, một người phụ nữ đang đứng chờ. Mái tóc xanh lam buộc gọn, đôi sừng rồng nhỏ, đồng phục L.G.D. phẳng phiu không một nếp nhăn. Thanh kiếm đeo bên hông cô ta trông như chưa từng rời khỏi vị trí ấy.","“Rhodes Island hẹn gặp L.G.D. lúc mười giờ,” cô ta nói, không cần chào. “Giờ là mười giờ mười bốn. Các người đến muộn mười bốn phút, nghĩa là các người đã lãng phí mười bốn phút của tôi.”","“…Em xin lỗi, cô Ch’en. Bọn em vừa phát hiện Reunion có mặt ở đây…”","“Không sao, tôi biết rồi. Nhưng đó không phải điều quan trọng lúc này.” Ánh mắt Ch’en lướt qua Doctor, sắc như lưỡi dao. “…Còn đây là ai?”","“Doctor là cố vấn của Rhodes Island. Bác sĩ Kal’tsit chắc đã báo với cô rồi.”","“Hừm…” Ch’en quan sát Doctor thêm một nhịp, như đang ghi nhớ một hồ sơ. “Mọi người đã đến đủ, giờ tôi cần các người đi theo tôi đến…”","“Cô Ch’en! Khẩn cấp! Mấy người Infected đó… họ không…”","“Đừng hoảng!” Ch’en quay phắt lại. “Đội Một, chờ lệnh! Sniper, vào vị trí!”","Ở hàng rào kiểm dịch, một nhóm người đang giằng co với các nhân viên L.G.D.","“Buông tôi ra!! Sao các người bắt tôi?! Chúng tôi không làm gì sai cả!!!”","“Vài người Infected… không chịu bị đưa đi… Chúng tôi…”","“Tôi thấy rồi.” Ch’en nhìn cảnh ấy, gương mặt không đổi. “Thôi. Bắt hết.”","Amiya khẽ giật mình.","“Giải tán đám đông ngay. Mở cổng sau ba mươi phút, khi xong quy trình xét duyệt. Ngoài ra, đẩy tuyến kiểm dịch lên thêm bốn mươi mét.” Ch’en quay lại. “Ngoài cô và Doctor, những người còn lại của Rhodes Island ở lại đây hỗ trợ an ninh biên giới. Hai người đi với tôi. Nếu nhóm các người không xử lý nổi việc vặt này, tôi sẽ không giao nhiệm vụ nào cho các người. PC94172, sắp xếp việc cho những người này. Tôi không muốn thấy thêm rắc rối nào tối nay.”","“Rõ, thưa sếp!”","Amiya nhìn Doctor, khẽ thì thầm: “Cô Ch’en đúng là khó tính thật… còn nghiêm hơn em tưởng…”","Doctor chỉ gật đầu.","@bg:bg_lungmen_station","Tòa nhà mà Ch’en dẫn họ đến cao vút lên nền trời đêm, kính và thép lấp lánh ánh đèn như một ngọn tháp bằng pha lê.","“Ô-cao quá!” Amiya ngửa cổ lên, rồi bắt gặp ánh mắt của Ch’en, vội cúi xuống. “X-xin lỗi…”","“…Rhodes Island không nghi ngờ gì là có năng lực,” Ch’en nói.","“Ồ… Cảm ơn cô đã khen.”","“Tuy nhiên,” Ch’en tiếp, “sau sự kiện Chernobog, một làn sóng người tị nạn khổng lồ đã đổ về Lungmen. Người Infected hẳn đã biết bước vào Lungmen sẽ có hậu quả gì.”","“Tôi xin nhắc lại một lần nữa.”","Một giọng nói khác vang lên từ cửa thang máy, điềm tĩnh và lạnh như mặt hồ mùa đông.","“Lungmen chính là Chernobog tiếp theo.”","“Bác sĩ Kal’tsit…!”","Người phụ nữ ấy đứng ở cuối hành lang, áo choàng trắng và mái tóc xám nhạt, đôi tai dài của giống Feline. Đôi mắt màu lục nhạt của cô ta nhìn Amiya một thoáng, rồi lướt qua Doctor, nhanh đến mức không ai kịp đọc được biểu cảm trong đó.","“Đại diện của Rhodes Island đã gặp Trưởng quan Wei,” Ch’en nói. “Xin chờ ở đây. Tôi sẽ báo sau.”","Khi Ch’en đi khuất, Amiya thở hắt ra. “Phù… cô ấy khó nói chuyện thật đấy. Doctor, từ đây trở đi, bác sĩ Kal’tsit sẽ lo phần đàm phán. Xin Doctor hãy tin tưởng cô ấy.”"],"bg":"bg_bridge","cast":[["Amiya","op:char_002_amiya"],["Ch'en","op:char_010_chen"],["Dobermann","npc:char_130_doberm_ex"],["Broadcast",null],["L.G.D. Agent","npc:char_015_lmg"]]},{"c":"2-2","t":"Khẩu chiến","p":["“Mời vào.”","Căn phòng rộng, ốp gỗ tối màu, cửa kính nhìn xuống cả thành phố lấp lánh. Sau bàn làm việc là một người đàn ông trung niên, râu cắt tỉa gọn gàng, đôi mắt hiền hòa của người quen mỉm cười trong những cuộc thương lượng mà người khác không bao giờ thắng. Wei Yenwu, Trưởng quan của Lungmen.","“Bác sĩ Kal’tsit!” Amiya gọi.","Kal’tsit quay lại. “Amiya…” Rồi ánh mắt cô ta dừng lại trên Doctor. Một quãng lặng rất ngắn. “…Người đến rồi.”","Doctor không biết phải đáp gì.","“E hèm.” Ch’en lên tiếng. “Trưởng quan Wei, hai đại diện khác của Rhodes Island cũng đã đến.”","@cg:bg_0_tv","“À, tuyệt lắm. Mời ngồi. Cô Kal’tsit đang trình bày tình hình cho tôi.”","“Vậy cho phép tôi tiếp tục,” Kal’tsit nói. “Ông Wei, tôi tin ông đã nắm rõ tình hình. Hiện mạng lưới thông tin của Lungmen thu thập được nhiều thông tin về Reunion Movement. Thật tốt là ông nhận ra tầm quan trọng của chúng. Nhưng chừng đó chưa đủ. Lungmen vẫn thiếu những thông tin then chốt.”","Ch’en im lặng, nhưng hai bàn tay cô ta siết lại sau lưng.","“Tôi tin L.G.D. biết rất rõ rằng việc kiểm dịch đơn thuần này không đủ để ngăn Reunion. Reunion sẽ không ngoan ngoãn đi qua trạm kiểm tra, cũng không chờ chính quyền chủ động ra tay. Vì vậy… nếu không có sự hỗ trợ của Rhodes Island, Lungmen sẽ chịu tổn thất nặng nề trước Reunion, nếu các vị cứ tiếp tục áp dụng cùng một chiến lược với người Infected.”","“Xin lỗi đã ngắt lời,” Ch’en nói. “L.G.D. hiểu hệ thống phòng thủ của Lungmen hơn Rhodes Island. Chúng tôi đã chuẩn bị để đối phó khả năng Reunion thâm nhập. Tuy nhiên, chúng tôi không có nghĩa vụ phải cung cấp cho các người thông tin mật về hoạt động của mình.”","Wei Yenwu vẫn mỉm cười. “…Cô Kal’tsit, xin cứ tiếp tục.”","“Đúng là đến nay Lungmen đã thành công trong việc đối phó với người Infected không vũ trang. Nhưng các vị chưa từng đối mặt với một cuộc bạo loạn có tổ chức ở quy mô này. Điều đó có thể dẫn đến những tổn thất không cần thiết.” Kal’tsit ngừng lại. “Theo kinh nghiệm của chúng tôi… chỉ có người Infected mới đối phó được người Infected.”","“Theo tôi hiểu, Rhodes Island có chuyên môn đặc biệt trong việc đối phó Reunion?”","@cg:bg_0_rhodes2","“Chúng tôi có kinh nghiệm, nhưng tôi không gọi đó là chuyên môn.”","“Ồ…? Tôi nghe nói Rhodes Island đã có mặt trong sự kiện Chernobog, và thu được nhiều tin tình báo về Reunion.”","“Dù ông nghe điều đó từ đâu,” Kal’tsit đáp, không chút dao động, “ở giai đoạn này, thông tin đó không nằm trong danh mục trao đổi. Nó chỉ là một phần trong lý lịch của chúng tôi, một tư cách cho phép chúng tôi được nói chuyện với ông, ông Wei.”","“Có trao đổi thông tin hay không là do Lungmen quyết định. Nếu Rhodes Island không cung cấp được ngay cả mức thông tin này…” Wei Yenwu khẽ cười. “Hah. Vậy thì chúng tôi chẳng có cơ sở nào để tin vào năng lực của các vị.”","“Ông Wei, xin lỗi nếu lời tôi chưa đủ rõ. Điều tôi muốn nhấn mạnh là… lý do duy nhất Rhodes Island có được thông tin này, là vì chúng tôi đủ mạnh để giành lấy nó.”","“Dù sao đi nữa,” Ch’en nói, “Lungmen không thể tùy tiện tin một nhóm người Infected khác.”","Kal’tsit quay sang cô ta, và lần đầu tiên, giọng cô ta mang theo một tia mỉa mai lạnh lẽo.","“Cô Ch’en, nếu cô tin rằng trừng phạt người Infected quan trọng hơn an ninh thực sự của Lungmen… thì tôi sẽ lập tức tự nộp mình theo luật địa phương của các vị. Rồi tôi sẽ ngồi trong ngục thở dài, nhìn Reunion thiêu rụi thành phố của các vị.”","“Lần này, Lungmen không có lựa chọn.”","“Thiện ý của cô không bị bỏ qua, dù cô thô lỗ,” Ch’en đáp, mắt không chớp. “Nhưng chúng tôi cũng không phải hội từ thiện cho những kẻ vận động hành lang vô dụng.”","“Cô Ch’en,” Wei Yenwu gọi.","“Trưởng quan Wei, tôi cho rằng để người ngoài can dự vào chuyện cơ mật của Lungmen là không thích hợp.”","“Bình tĩnh, cô Ch’en. Họ vẫn là khách của chúng ta.” Ông ta ngừng lại. “…Khách của tôi.”","Một quãng lặng nặng nề.","“…Được thôi,” Ch’en nói. “Chừng nào họ chưa vi phạm luật, tôi sẽ dung thứ họ, thưa ông.”","“À, xin lỗi, tôi vừa nhớ ra…” Wei Yenwu gõ nhẹ ngón tay lên bàn. “Phải rồi. Hừm… Có một điều tôi quan tâm. Năng lực của các vị. Theo tôi hiểu, Rhodes Island cũng đang hỗ trợ trấn áp người Infected quanh đây? Cô Ch’en, dựa trên thông tin tốt nhất của cô, cô đánh giá năng lực chiến đấu của Rhodes Island thế nào?”","“…Cho phép tôi mô tả những gì tôi đã chứng kiến trong các chiến dịch của Rhodes Island,” Ch’en nói. “Chi tiết như sau…”","","“…Báo cáo về các hoạt động tác chiến của Rhodes Island xin kết thúc tại đây.”","“Và đánh giá của cô?”","“Không có mấy lý do để nghi ngờ sức mạnh của họ. Tuy nhiên, Trưởng quan Wei, xét đến thân phận của họ, tôi cho rằng về mặt chiến lược… L.G.D. hoàn toàn đủ khả năng đảm đương công việc này.”","“Về chống tội phạm và ngăn thâm nhập, L.G.D. là quá đủ,” Wei Yenwu gật gù. “Rhodes Island có thể mang đến nhiều hơn. Tuy nhiên… trong những thứ Rhodes Island yêu cầu, có một ‘món’ mà dựa trên những gì được đưa ra, chúng tôi không muốn trao đổi. Sự hợp tác phòng thủ tạm thời mà các vị cung cấp còn xa mới tương xứng. Như hiện tại, ‘giá chào’ của các vị hơi cao. Cô Kal’tsit, cô Amiya, mong hai vị hiểu cho.”","“Ông Wei, phòng thủ tạm thời sẽ không đủ,” Kal’tsit nói. “Có rất nhiều điều về Reunion mà ông chưa biết. Dựa trên dữ liệu chúng tôi thu thập khi chiến đấu với chúng, nếu không có biện pháp chủ động, Reunion sẽ chiếm được Lungmen trong vòng hai tuần.”","“…Vô lý. Không có bằng chứng nào cho—”","“Cô Ch’en, cô có muốn biết lý do thật sự khiến Chernobog sụp đổ chỉ trong một đêm không?”","Ch’en im bặt.","“Xin hãy nói rõ,” Wei Yenwu nói.","“Amiya.”","“A… Vâng.” Amiya đứng thẳng lưng. “Rhodes Island không chỉ có mặt trong sự kiện Chernobog… Bọn em còn bị kẹt trong Catastrophe, và đã sống sót.”","“Ấn tượng, ấn tượng. Không phải ngày nào tôi cũng gặp người đủ điên để sống sót ra khỏi một Catastrophe. Cô Amiya, xin cứ tiếp tục, tôi đang nghe.”","“…Bọn em đã chiến đấu với thủ lĩnh của Reunion.”","Ch’en không nhúc nhích. Nhưng Doctor, đứng ngay cạnh, thấy rõ những ngón tay cô ta vừa siết lại đến trắng bệch.","“Hửm? Tên cô ta là gì nhỉ? Tôi không nhớ rõ lắm…”","“Talulah,” Doctor nói.","“À, phải rồi, Talulah.” Wei Yenwu quay sang. “Cô Ch’en, cô nghĩ sao?”","Một quãng lặng dài.","“…Tôi… Tôi biết,” Ch’en nói.","“…Đó là những gì đã xảy ra với Rhodes Island ở Chernobog,” Amiya tiếp tục. “Dù Reunion đã giành được Chernobog từ tay Ursus, muốn bành trướng, chúng phải giải quyết tình trạng thiếu tài nguyên. Lungmen sẽ là bàn đạp tiếp theo của chúng. Các vị có thể đẩy lùi chúng một thời gian, nhưng nếu không chủ động xử lý tình hình, các đợt tấn công sẽ không dừng lại. Hơn nữa… còn một yếu tố chưa biết: chúng ta vẫn chưa rõ Ursus sẽ phản ứng thế nào sau khi mất Chernobog…”","“Hahaha… Nói hay lắm, cô gái trẻ.” Wei Yenwu vỗ tay nhẹ. “Do mối đe dọa nghiêm trọng này và nhân lực có hạn của L.G.D., tôi không phản đối việc xem xét thỏa thuận tạm thời theo các điều khoản đã nêu. Nhưng điều tôi nói trước đó vẫn còn nguyên…”","“…Giá chào của Rhodes Island vẫn quá cao?” Kal’tsit hỏi.","“Đúng vậy. Để Lungmen được bồi đắp xứng đáng, tôi có hai điều kiện rất đơn giản. Thứ nhất, Rhodes Island sẽ giúp L.G.D. trấn áp mối đe dọa Reunion. Bao gồm xác định các mối đe dọa trong nội thành Lungmen cũng như những gì liên quan đến hậu quả từ Chernobog. Đồng thời đánh giá mức độ thâm nhập của người Infected vào Lungmen. Tôi mong các vị chia sẻ mọi thông tin có thể hữu ích.”","“Còn điều kiện thứ hai?”","“Tôi sẽ nói điều kiện thứ hai sau khi các vị đã đáp ứng điều kiện thứ nhất.” Ông ta mỉm cười. “Đương nhiên, tôi sẽ không đòi hỏi gì ngoài phạm vi chuyên môn của Rhodes Island.”","“Tôi chưa hiểu lắm. Ông Wei có thể nói rõ hơn?”","“Nói thế nào nhỉ… Nếu Reunion gây ra thiệt hại vượt quá ước tính của Rhodes Island… tôi mong các vị giúp L.G.D. xử lý tình hình, có thể bao gồm cả công tác hậu thảm họa. Đương nhiên, không có gì vượt quá khả năng của các vị. Đại khái là vậy.” Ông ta dang tay. “Tôi không thể nói nhiều hơn vào lúc này. Nhưng đừng quên, Rhodes Island không có lựa chọn. Nếu các vị không chấp nhận điều kiện của chúng tôi, mọi điều khoản đã bàn, cũng như các yêu cầu của các vị, sẽ…”","Kal’tsit quay sang. “Amiya?”","“Bác sĩ Kal’tsit…” Amiya hít một hơi, rồi bước lên. “Ông Wei, em muốn bổ sung một điều khoản vào thỏa thuận: ‘Mọi cách diễn giải các điều khoản phải được cả hai bên đồng thuận.’ Điều này có được chấp nhận không ạ?”","Wei Yenwu nhìn cô bé, và lần đầu tiên, nụ cười của ông ta có chút thật lòng.","“Ồ… Dĩ nhiên rồi. Tôi thấy được sự tôn trọng của cô dành cho Lungmen, cô Amiya. Cô Ch’en, cô có phản đối gì không?”","“…Tôi chấp nhận chiến dịch này.”","“Hah. Có vẻ cô Ch’en giờ cũng có mục tiêu riêng rồi.” Ông ta đứng dậy. “Dù sao, xin chúc mừng. Các vị đã giành được lòng tin của Lungmen. Cô Ch’en sẽ chịu trách nhiệm sắp xếp cho các vị. Tuy nhiên, xin lưu ý người Infected không được tự do đi lại trong thành phố, vì điều đó có thể gây hoảng loạn. Tôi mong các vị tuân theo mệnh lệnh của L.G.D. khi thi hành nhiệm vụ. Đặc biệt là mệnh lệnh của cô Ch’en. Lungmen sẽ mở cửa cho Rhodes Island, chừng nào hành động của các vị còn đồng nhất với chúng tôi.”","","“Phù… Ugh…!” Ra khỏi phòng, Amiya gần như ngã dựa vào tường. “Người đàn ông đó khó đối phó quá… Ông ấy nói năng có bài bản quá, cảm giác như chẳng gì lay chuyển được ông ấy…”","“Amiya, rồi em sẽ phải tự học cách đối phó với những người như vậy,” Kal’tsit nói. Rồi giọng cô ta dịu đi một chút, rất ít thôi. “Nhưng cuối cùng, em đã làm rất tốt.”","“Ehehe…”","“Nhân tiện…” Kal’tsit quay sang Doctor. Cô ta nhìn rất lâu. “…Người…”","“Hân hạnh được gặp, bác sĩ Kal’tsit,” Doctor nói.","Kal’tsit im lặng. Một sự im lặng có trọng lượng, như mặt nước trước khi vỡ.","“Bác sĩ Kal’tsit, xin đừng làm khó Doctor…” Amiya khẽ nói.","Kal’tsit hít vào một hơi thật sâu, sắc lẹm. Rồi thở ra, rất chậm.","“Haah… Tôi mong những hy sinh của chúng ta… không phải là vô ích.”","Cô ta nhìn Doctor thêm một lần nữa, và lần này, có thứ gì đó rất cũ, rất mệt mỏi, nằm sâu trong đôi mắt màu lục nhạt.","“Chào Doctor. Mừng người trở về.”"],"bg":"bg_lungmen_o","cast":[["Wei Yenwu","npc:char_2005_weiyw_1"],["Kal'tsit","op:char_003_kalts"],["Ch'en","op:char_010_chen"],["Amiya","op:char_002_amiya"]]},{"c":"2-3","t":"Suy đoán vô tội","p":["Ở một góc khu ổ chuột Lungmen, nơi những mái tôn chồng lên nhau như vảy cá và ánh đèn neon không bao giờ chiếu tới, một cô gái tóc trắng đang quỳ trước một nhóm trẻ con.","“Nhanh, trốn đi! Chị… chị phải đi rồi. Cầm lấy này… cái này cho các em. Đây là bùa hộ mệnh. Mẹ chị dạy chị làm nó… Còn đây là cái chị tự làm.” Cô gái đặt vào tay đứa bé nhất một con búp bê nhỏ bằng vải vụn. “Khi tự tay làm những con búp bê này, em có thể giữ cho những người mình thương được an toàn.”","“Vâng, chị Misha, bọn em sẽ giữ gìn cẩn thận!”","“Tốt, tốt. Giờ thì đi trốn đi! Đừng gây tiếng động nhé.”","Bọn trẻ chạy biến vào những ngõ hẻm. Cô gái tên Misha đứng dậy, nhìn quanh, rồi cũng biến mất về phía ngược lại.","Chỉ một lát sau, những tiếng bước chân nặng nề đã vang lên.","“Chúng đi đâu rồi?! Đuổi theo! Xem lũ Infected đó chạy được bao xa! …Hửm? Ồ, xem chúng ta có gì đây?”","","“Theo dữ liệu của Exusiai, mục tiêu nhiệm vụ của chúng ta hẳn đang ở đâu đó quanh đây…” Amiya nhìn bản đồ trên tay, rồi nhìn mê cung những mái nhà, cầu thang sắt, dây điện chằng chịt phía trước. “Argh, địa hình ở đây phức tạp thật. Nếu tự làm một mình, nhiệm vụ này hẳn sẽ phiền phức lắm. May mà em đã liên lạc với Penguin Logistics từ trước…”","Cô bé khựng lại. “…Ai đó?”","Ở đầu ngõ, vài tên du côn đang túm cổ một đứa trẻ.","“Đồ xấu xa! Lũ người xấu! Buông tôi ra! Buông… ra…!”","“Nói! Con bé đó chạy đi đâu?”","“Đừng giả ngu!”","“Chị ơi! Chị ơi! Chị ở đâu…! Cứu với… Chị Misha! Chị Misha, cứu em!!”","Amiya bước ra khỏi bóng tối.","“…Các anh nên đi ngay đi, nếu biết điều.”","“…Hả?! Đứa quái nào đây…? Trông mày không phải dân ở đây! Mày không sợ bọn tao à…”","“Nếu không thì…” Amiya giơ một tay lên.","Một luồng sáng đen bùng lên. Tên du côn gần nhất bị hất văng vào tường.","“Gaaah!! C-cái gì vậy? Arts! C-con nhỏ dùng Arts?! Aaaargh! Tránh xa tao ra!”","“…Đừng bao giờ bắt nạt người không có khả năng tự vệ nữa.”","“Aaaagh! Quái vật!”","Đám du côn chạy tán loạn. Amiya đứng im, nhìn theo.","“Heh… Quái vật, hả?”","Rồi cô bé quay lại, giọng dịu hẳn, cúi xuống những đứa trẻ đang nấp sau thùng rác. “Không sao rồi. Các em ra đi. Ở đây nguy hiểm lắm. Mau tìm chỗ nào an toàn đi nhé.”","“Cảm ơn chị!”","“Giữ gìn nhé!”","Một người phụ nữ tóc vàng, đôi tai cáo vểnh, thanh kiếm đeo hờ hững bên hông, bước tới. “Amiya, chuyện gì vậy?”","“Hừm, vừa nãy em thấy một người Infected, có lẽ chưa đăng ký…”","“Từ Ursus à?” Franka hỏi.","“Vâng. Cô ấy đang chạy sâu vào khu ổ chuột. Franka, tập hợp các operator gần đây.”","“Ok.”","“Càng vào sâu khu ổ chuột, tình hình càng bất ổn…” Amiya nhìn quanh. “Dân thường, tội phạm, người tị nạn, tất cả lẫn lộn với nhau. Chúng ta phải chuẩn bị kỹ.”","Một cô gái khác, đôi sừng nhỏ và chiếc đuôi dài của giống Vouivre, khiên lớn trên tay, chạm vào tai nghe. “Amiya, có liên lạc đến. Chờ một chút.” Liskarm lắng nghe. “…Đúng vậy. Amiya, là L.G.D.”","“Cô Ch’en ạ?”","“Phải.” Liskarm tiếp tục nghe máy. “…Đúng thế. Chúng tôi đã tìm thấy một số người Infected chưa đăng ký. …Vâng. …Cái gì? …Chúng tôi phải tìm một cô gái Ursus, tóc trắng ngắn, cao khoảng 145 cm, tên là Misha?”","Amiya giật mình. “Đó là…?”","“…Rõ.” Liskarm hạ máy. “Amiya, cô Ch’en muốn chúng ta lập tức tìm người Infected vừa mô tả. Khi tìm thấy, phải giao ngay cho L.G.D.”","“Cho em nói chuyện với cô ấy được không?” Amiya cầm lấy máy. “A lô, a lô… Cô Ch’en, cô nghe em nói không?”","“Tôi nghe.”","“Em có thể xác nhận tính hiệu lực của mệnh lệnh đó không ạ?”","“Hiệu lực một trăm phần trăm, áp dụng ngay lập tức.”","Tút. Tút.","“…Cô ấy cúp máy luôn rồi…”","“Cô Ch’en đó, tính khí hơi nóng nảy nhỉ,” Franka nhún vai.","“Vậy đây sẽ là nhiệm vụ của chúng ta lúc này…”","“Amiya, tôi vừa nhận thêm tin từ mấy Defender,” Liskarm nói. “Họ gặp vài kẻ công khai thù địch với operator Rhodes Island. Và những kẻ tấn công đó không phải người thường, họ là… người Infected.”","Amiya im lặng một nhịp. Rồi cô bé bắt đầu ra lệnh, giọng gọn gàng như một người chỉ huy thực thụ.","“…Cho các Defender rút về phía chúng ta. Đội trinh sát! Mục tiêu là một cô gái Ursus tóc trắng ngắn, cao 145 cm. Nhớ ẩn nấp, và giữ an toàn! Các operator khác, theo trưởng nhóm, tản ra.”","“Franka, tấn công trực diện,” Doctor nói.","Franka nhướng mày, rồi cười. “Này… Không tệ đâu. Liskarm, người này khá lắm đấy.”","“…Doctor là chỉ huy chiến thuật của chúng ta,” Liskarm đáp, giọng nghiêm khắc. “Cô nên nghiêm túc hơn.”","“Bắt đầu thôi,” Amiya nói. Rồi cô bé khẽ thêm, như tự nói với mình: “Vậy là… Rhodes Island lại phải chiến đấu với người Infected nữa…”","@bg:bg_indoor_2","Misha nép vào một góc tối giữa hai bức tường, ôm lấy đầu gối.","“Phù… Trốn ở đây chắc sẽ không bị tìm thấy… Nhưng mình không thể quay về với lũ trẻ được nữa rồi. Mong là chúng không sao… Haizz… Tại sao chứ…”","Một bóng người đổ xuống.","“…! Ai đó?”","“…Chị là chị Misha phải không ạ?”","Misha bật dậy, lùi sát vào tường. Trước mặt cô là một cô bé có đôi tai thỏ, cùng hai người phụ nữ mang vũ khí.","“Em xin lỗi, chị Misha. Mong là em không làm chị sợ… Đây là đồng nghiệp của em, Franka và Liskarm.”","“Chào nhé,” Franka vẫy tay.","“Chào cô,” Liskarm gật đầu.","“Bọn em đến từ Rhodes Island Pharmaceuticals. Là một tổ chức được lập ra để phục vụ người Infected, ít nhất thì… bọn em mong có thể giúp được chị. Nên bọn em muốn nói chuyện với chị một chút.”","“Nói chuyện?”","“Vâng. Nhưng đây không phải chỗ thích hợp… Lúc này, ưu tiên hàng đầu của bọn em là giữ cho chị an toàn. Tạm thời bọn em sẽ bảo vệ chị, chị cứ yên tâm.”","“Em… đang nói gì vậy…” Misha lùi thêm, móng tay giương lên. “Các người chỉ định bắt tôi rồi nhốt lại thôi, phải không?! Tránh xa tôi ra! Móng vuốt của tôi sắc lắm…! Nếu không muốn bị thương thì…”","“…Phì,” Franka bật cười.","“Cô cười gì chứ…”","“Nếu bọn tôi định bắt cô thật, thì đã chẳng cho cô cơ hội chống cự đâu.”","“Chị Misha, bọn em thật sự muốn giúp chị, nên…”","“Tôi không tin các người…” Giọng Misha run lên. “Lungmen đối xử với người Infected còn tệ hơn với tội phạm! Tại sao… Tại sao các người lại cất công đi giúp người Infected?”","Amiya im lặng. Rồi cô bé tháo găng tay, chìa bàn tay ra. Dưới ánh sáng lờ mờ, những tinh thể Originium đen bóng nhô lên trên mu bàn tay nhỏ.","“—Chị Misha, nhìn này…”","“Em… làm gì vậy… Tay của em… Em cũng là… người Infected?”","“Đúng vậy. Em cũng giống chị.” Amiya đeo găng lại. “Khu ổ chuột này có rất nhiều người Infected. Những đứa trẻ chị bỏ lại lúc nãy… chúng đã tin chị. Chị Misha, chị đã khiến chúng gặp nguy hiểm rồi.”","“…Em định dùng lũ trẻ để đe dọa tôi sao?”","“Không, em sẽ không làm vậy. Nhưng đã có người bắt đầu làm đúng như thế rồi. Bọn em vừa đuổi đi một nhóm du côn đang tra hỏi lũ trẻ.”","Misha sững người.","“Lungmen cũng đang lùng sục người Infected. Nếu Lungmen tìm thấy chị trước, có lẽ đã quá muộn rồi. Bọn em muốn kéo đám bạo loạn ra khỏi lũ trẻ bằng cách khiến chúng chú ý đến chị… Nhìn từ góc độ khác, bọn em cũng có thể giữ cho chị khỏi bị hại.”","“…Em có biết tại sao chúng đuổi theo tôi không? Em có lý do gì… để làm tất cả những chuyện này vì tôi?”","“Thật ra bọn em cũng không biết vì sao có người Infected nhắm vào chị… Nhưng bọn em quan tâm đến sự an toàn của người vô tội, kể cả chị. Ít nhất, đây là cách tốt nhất lúc này. Em mong chị có thể tin bọn em.” Amiya đưa tay ra. “Chị có cho phép bọn em đưa chị rời khỏi đây trước không?”","Misha nhìn bàn tay ấy rất lâu.","“…Được rồi… Đi thôi. Dù sao thì tôi cũng chẳng có lựa chọn nào, phải không?”","“Em không nói vậy đâu… Nhưng ít nhất, cảm ơn chị… chị Misha!”"],"bg":"bg_lungmen_b","cast":[["Amiya","op:char_002_amiya"],["Misha","npc:char_012_misa_1"],["Liskarm","op:char_107_liskam"],["Rioter",null],["Franka","op:char_106_franka"],["Children",null],["Child",null]]},{"c":"2-4","t":"Penguin Logistics","p":["“—Báo cáo xin kết thúc, cô Ch’en.”","“Đã rõ. L.G.D. sẽ bảo vệ điểm hẹn và chờ các người hộ tống mục tiêu đến.”","“Rõ.” Amiya trải tấm bản đồ đội trinh sát vừa vẽ. “Chúng ta sẽ rời khu ổ chuột bằng đường ngắn nhất.” Cô bé hạ giọng. “(Cô Ch’en còn chỉ thị gì khác không ạ?)”","“Chỉ cần nhanh lên. Chúng tôi không có nhiều thời gian. Hết.” Ở đầu dây bên kia, tiếng Ch’en quát vọng lại: “Vào đội hình! Đừng lề mề!!”","Tút.","“…Phù, cô ấy lại cúp máy rồi…”","“Nói cách khác,” Franka nói, “giờ ta phải chạy việc vặt cho cô ta à?”","“Dù sao bọn mình cũng là người tìm ra mục tiêu…”","“L.G.D. chưa từng cung cấp thông tin chi tiết nào về mục tiêu,” Liskarm nói, nhíu mày. “Đáng lẽ ta đang hợp tác, vậy mà họ đột nhiên bảo người ta tìm thấy có công dụng quan trọng với họ. Có cả đống thông tin then chốt mà ta không được biết.”","“(…Em không ngạc nhiên chuyện L.G.D. giữ bí mật với chúng ta.)”","“Tại sao?”","“Chẳng phải cô thông minh lắm sao?” Franka nói. “Rhodes Island biết quá nhiều thì có lợi gì?”","“Tôi chỉ biết là biết quá ít thì không có lợi cho nhiệm vụ.” Liskarm thở ra. “Dù sao, phải hộ tống Misha đến điểm hẹn trước đã.”","“Hừm, đi đường nào đây…” Amiya mỉm cười. “Lại phải nhờ họ một lần nữa rồi.”","“Ai?”","“Penguin Logistics.”","“Yo, Rhodes Island~” Một giọng nói vui vẻ vang lên qua bộ đàm. “Nhiệm vụ sắp xong chưa? Thấy dịch vụ của bọn tôi thế nào?”","“Biết ngay mà…” Franka thở dài.","“Này, đừng thế chứ~ Có chuyện gì không vui à? Hay gặp ai mình không ưa?”","“Ừ, cô đấy.”","“Không cần như vậy,” Liskarm nói. “Không có tin tình báo của Penguin Logistics, ta đã không khoanh vùng được khu tìm kiếm… cũng không dễ dàng có được thông tin về dân số Infected ở Lungmen như vậy.”","“Cảm ơn cô đã khen nhé! Cô rõ là có con mắt tinh tường đấy.”","“Exusiai, bọn mình cần cậu tìm một lộ trình tương đối an toàn,” Amiya nói.","“Vậy tôi vào thẳng vấn đề luôn. Hừm… Chẳng có đường nào tốt cả. A, chọn đường này! Ờ, nhìn bản đồ này nhé. Từ trung tâm khu ổ chuột, đi về phía bắc ba dãy nhà, rồi theo con đường này quay ngược về phía nam đến lối ra. Đây chắc là đường an toàn nhất. Có điều, dọc đường chắc vẫn đủ kẻ địch để tổ chức vài buổi karaoke đấy.”","“Kẻ địch?”","“Có vẻ Reunion đã thâm nhập Lungmen rồi,” Liskarm nói. “Cô Exusiai, tôi có thể giả định cô đã nắm được sự phân bố của địch?”","“Ừm hửm!”","“Vậy chúng đang di chuyển thế nào?”","“Đang tiến thẳng về phía các cô đấy!”","Một quãng lặng.","“…Ta bị bao vây rồi,” Liskarm nói.","“Ưu tiên hàng đầu là đưa Misha ra an toàn,” Amiya nói ngay. “Franka, trông cậy vào chị chặn đợt phục kích của địch.”","“Dễ thôi.”","“Liskarm, chia đội Defender, yểm trợ hai bên. Chị sẽ lo bảo vệ Misha.”","“Không vấn đề.”","“À phải rồi,” Exusiai nói thêm, như thể vừa nhớ ra, “các cô có biết là còn vài Caster địch nữa không?”","“…Nghh…” Amiya day trán, rồi quay sang Doctor. “Doctor, xin hãy ở gần em. Doctor cứ tiếp tục chỉ huy các đội, em sẽ chuyển lệnh. …Vậy thử đi theo con đường an toàn nhất này xem.”","","“Sạch rồi!” Franka rút kiếm ra khỏi một tên Reunion. “Cô nói đúng… Đám này có chuẩn bị đấy! Mọi người cũng nhanh chân lên!”","Misha thở dốc chạy theo sau. “Hộc… Rốt cuộc các người là ai vậy… hộc…”","“Mọi người, xin đi nhanh hơn!”","“Amiya, ta đang bị truy đuổi từ phía sau,” Liskarm nói. “Có thời gian phản công không?”","“Lúc này thì không… Tốt hơn là cắt đuôi chúng, tránh giao tranh không cần thiết…”","“Bỏ qua chuyện an toàn đi,” Liskarm nói vào bộ đàm. “Tôi cần một con đường ra khỏi khu ổ chuột đến chỗ cô Ch’en nhanh nhất có thể. Reunion đã bám theo rồi. Càng phải đi xa, ta càng gặp nguy!”","“Dễ thôi,” Exusiai đáp. “Tôi có một con đường mà địch không bao giờ nghĩ tới.”","“Cô đã có sẵn trong đầu rồi à?”","“Đương nhiên~ Nhưng tôi phải tự đi xem trước xem thông tin có đáng tin không đã.”","“Cố nhanh lên.”","“Rõ~ Tôi đi tí rồi về! Nếu cần gì, liên lạc với nhân viên Penguin Logistics khác nhé!”","Trong lúc chờ, Misha bước chậm lại bên cạnh Amiya.","“…Tôi hỏi được không… chúng ta đang đi đâu vậy?”","“Bọn mình đi gặp L.G.D. Họ sẽ bảo vệ chị.”","“…Hả? …L.G.D.?”","“Nhiệm vụ hiện tại của bọn em là hộ tống chị an toàn đến L.G.D., và họ sẽ bảo vệ chị.”","Misha dừng hẳn lại.","“…Tôi suýt nữa đã tin… rằng các người thật sự đến để cứu tôi.”","“Không, bọn em thật sự…” Amiya vội nói. “Kế hoạch ban đầu của bọn em là đề nghị Lungmen giao một số người Infected cho bọn em… Nhưng sau khi nghe báo cáo, L.G.D. đột nhiên yêu cầu bọn em chuyển giao chị cho họ. Hơn nữa… ở Lungmen, chị sẽ an toàn nhất dưới sự bảo vệ của họ. Nếu bọn em không hành động ngay, chị sẽ gặp nguy hiểm lớn. Nhiều người Infected truy đuổi chị đều đã đeo huy hiệu Reunion…”","“Tôi không biết gì về cái ‘Reunion’ mà em nói, nhưng… tôi biết L.G.D. Tôi đã thấy cách họ đối xử với người Infected. Nếu ngay từ đầu các người muốn bắt tôi, thì cứ nói thẳng ra.”","“Em xin lỗi… Nhưng đó thật sự không phải ý định của bọn em. Em biết vẫn còn những hiểu lầm cần giải quyết.” Amiya nhìn thẳng vào mắt Misha. “Nhưng dù chị nghĩ bọn em tệ đến đâu… xin chị, cố chịu đựng bọn em thêm một chút. Sự an toàn của chị quan trọng hơn cảm xúc của chị lúc này. Có cơ hội, em sẽ giải thích mọi chuyện. Dù sao… cũng còn những điều mà chính em cũng muốn biết…”","Misha không nói gì nữa."],"bg":"bg_indoor_2","cast":[["Amiya","op:char_002_amiya"],["Liskarm","op:char_107_liskam"],["Exusiai","op:char_103_angel"],["Franka","op:char_106_franka"],["Misha","npc:char_012_misa_1"],["Ch'en","op:char_010_chen"]]},{"c":"2-5","t":"Vật rơi","p":["Ở một ngã tư vắng, một người phụ nữ tóc đen, đôi tai sói, ngậm một que kẹo Pocky, đang ngồi trên thùng hàng.","“…Rhodes Island đúng là thong thả quá.” Texas nhìn về cuối phố. “Ồ…?”","Một toán Reunion đang chạy tới. “Sắp đến điểm chặn rồi! Nhanh lên! Đằng sau theo sát vào!”","“Chậc, cuối cùng cũng đến… Mình vừa mới dỡ đồ ra xong.” Texas đứng dậy, rút kiếm. “Phí thật.”","“Này, mấy người đeo mặt nạ đằng kia.”","“Ai đó?! Mày muốn gì?”","“Tất cả các người, lên hết đi. Tôi đang vội.”","","“Amiya, Texas của Penguin Logistics về rồi,” Franka báo.","“A… may quá!”","“Tôi có tin mới,” Texas nói ngắn gọn. “Tôi vừa xử lý vài gã tự gọi mình là ‘Reunion’. Nhưng còn nhiều tên nữa đang đến. Reunion đã thôi ẩn nấp, bắt đầu di chuyển theo nhóm.”","“Đúng như em lo…” Amiya cắn môi. “Reunion đã thâm nhập Lungmen qua khu ổ chuột… Và mục tiêu của chúng… cũng giống chúng ta. Nếu không, chẳng có lý do gì để chúng truy đuổi Rhodes Island.”","“Cô Misha đang mang những bí mật mà chỉ Lungmen và Reunion biết,” Liskarm nói. “Chúng ta đang ở thế bất lợi.”","“Tình hình không ổn lắm,” Franka đồng ý. “Lát nữa tôi phải véo gương mặt xinh xắn của cô sĩ quan kia một cái để hỏi cho ra lẽ mới được.”","“…Còn gì nữa không?” Texas hỏi. “Nếu không, tôi dẫn đường. Exusiai đã xác nhận lối thoát. Giờ tôi đưa các người đi.”","“Franka, tập hợp các đội. Chúng ta—”","“Chúng ta… nên tìm chỗ nấp trước đã,” Franka cắt ngang, tay đã đặt lên chuôi kiếm. “Reunion đến rồi.”","“Đằng này! Đừng để chúng chạy!”","“Chẳng có gì phiền hơn rắc rối cứ bám riết sau đuôi,” Franka lầm bầm.","Amiya nhìn đội hình địch, và mắt cô bé mở to. “…Có gì đó không đúng. Không…! Chúng… có người chỉ huy!”","Giữa đám Reunion, một người đàn ông cao lớn bước ra. Mặt nạ trắng che kín mặt, trên tay là một cây trượng phép kiêm súng phóng lựu khổng lồ.","“Skullshatterer, chúng ở ngay đây. Phải, chính là cô ta!”","“Caster, lên! Xé xác chúng!”","“Chúng nghiêm túc thật…” Liskarm giương khiên. “Cẩn thận! Địch triển khai nhiều Caster! Chuẩn bị đối sách thích hợp!”","“Thứ chúng muốn là…” Amiya quay phắt lại. “…Misha!”","Misha đứng sững. Người đàn ông tên Skullshatterer đang nhìn cô. Chỉ nhìn cô thôi, như thể giữa trận chiến hỗn loạn này, ngoài cô ra chẳng có ai khác tồn tại.","“Aa… Ai… ai vậy…”","@cg:bg_1_firstcontact","“…Cuối cùng…” Skullshatterer nói, giọng khàn đặc sau lớp mặt nạ. “Tôi… Cuối cùng tôi… đã tìm thấy cô.”","“Anh là ai…?!”","","“Amiya! Nhanh lên!”","“Chị Misha! Xin hãy đi theo bọn em!”","“…Sao… có thể như vậy…” Misha vẫn ngoái lại.","“Lối này, nhanh!” Texas dẫn đầu.","“Khu này sạch rồi! Cẩn thận, chúng vẫn đuổi theo!”","Misha chạy, nhưng mắt vẫn dán vào những bóng mặt nạ trắng phía sau. “…Họ cũng là…?”","“Vâng…” Amiya nói. “Reunion… Họ cũng là… người Infected.”","“…Tại sao? Tại sao người Infected lại đánh nhau…”","","Phía sau, Skullshatterer đứng yên giữa đường.","“Skullshatterer… Anh… để chúng đi sao?” một tên Reunion hỏi.","“Đừng lo… Chúng không chạy được đâu.” Hắn nhìn về hướng bóng tóc trắng vừa biến mất. “Nhưng cuối cùng tôi đã tìm thấy cô ấy— Không, không… Cuối cùng cô ấy đã… đến với tôi…”","","“Đến nơi rồi,” Texas nói.","“…Cô nghiêm túc đấy à?” Franka nhìn lên.","“Ký hiệu nói vậy.”","“Nhưng… con đường này dẫn lên trên mà? Thế thì giúp gì được ta?”","“Amiya, Amiya! Trên này, đúng rồi, lên đây!” Exusiai thò đầu ra từ một ban công tầng ba, vẫy tay. Mái tóc đỏ rực, vầng hào quang Sankta lơ lửng trên đầu.","“—Exusiai! Cậu chắc chứ…?”","“Tin tôi đi, tôi không làm hỏng đâu~ Tôi thuộc đường sá Lungmen như lòng bàn tay!”","“Lên thôi,” Texas nói.","“Thế chẳng phải… là ngồi chờ địch bao vây sao?” Franka hỏi.","“Nếu các cô không nhanh lên mà để Reunion tìm thấy, thì có thể lắm!”","“Chậc… Chờ đã, mọi người lên trước đi… Tôi đi hàn cửa lối vào để Reunion không vào được.”","Trên cầu thang sắt, Amiya chỉ vào một hình vẽ nhỏ. “Có logo chim cánh cụt ở cầu thang này. Đây phải không?”","“Đúng rồi. Đi thẳng, rẽ trái, rồi leo cầu thang lên.”","“Vậy là sẽ vào trong tòa nhà… Chẳng phải chúng ta định đi xuống dưới lòng đất sao?”","“Không, không, tôi chỉ nói là đi lên tầng thôi mà.”","“…Lên tầng?” Liskarm nhíu mày. “Cô chắc… cô ta đáng tin chứ?”","“‘Chỉ cần đến được đích, đường nào cũng đi được,’” Texas đáp. “Đó là một trong những phương châm của Penguin Logistics. Cứ thử dịch vụ của bọn tôi một lần. Cô sẽ thích thôi.”","Họ leo. Và leo. Và leo.","“Hộc… hộc…” Amiya thở không ra hơi. “Xin lỗi, chị Misha… Em không biết là…”","Misha không đáp, chỉ bám chặt tay vịn.","Texas dừng lại ở chiếu nghỉ, quay xuống nhìn người khoác áo trùm đầu đang lê bước phía sau.","“Này, người kia. Người là Doctor của Rhodes Island à?” Cô ta nhai rôm rốp que Pocky. “Có vẻ người không thích leo cầu thang lắm.”"],"bg":"bg_indoor_2","cast":[["Texas","op:char_102_texas"],["Amiya","op:char_002_amiya"],["Franka","op:char_106_franka"],["Misha","npc:char_012_misa_1"],["Skullshatterer","npc:char_1500_skulsr"],["Liskarm","op:char_107_liskam"],["Exusiai","op:char_103_angel"]]},{"c":"2-6","t":"Bám chặt","p":["“Đến rồi.”","“—?! Chúng ta phải lên tận sân thượng sao?” Amiya đẩy cánh cửa. “…Cửa này khóa rồi.”","“Lùi lại, tôi sẽ phá nó—” Liskarm giơ tay, tia lửa điện lóe lên.","“…Không cần,” Texas nói. “Đạp là được.”","Rầm. Cánh cửa bật tung.","Liskarm đứng im, tay vẫn giơ lên.","“Liskarm, cô nên học hỏi cô ấy đấy,” Franka nói.","“Tôi có cách làm của tôi. Có vấn đề gì à?!”","Gió đêm Lungmen thổi tung mái tóc của Amiya. Trước mặt họ là một biển mái nhà, những tầng thượng nối tiếp nhau trải dài trong ánh đèn neon.","“Phía trước có một sân thượng nữa…” Amiya lẩm bẩm. “Em nghĩ em bắt đầu hiểu rồi…”","“Amiya, đằng kia! Từ chỗ đó các cô có thể nhảy sang!”","“‘Đằng kia’ là đâu… Cậu bảo bọn mình— Nhảy từ mái nhà này sang mái nhà khác?”","“Chuẩn rồi~! Ai mà ngờ được chứ? Thấy chưa, chắc ăn tuyệt đối! Lungmen là một nơi tuyệt vời với rất nhiều bí mật—”","“Đừng hòng thoát!”","Từ sân thượng bên cạnh, những bóng Reunion vụt lên, lưng đeo những bộ máy phản lực thô sơ khạc khói.","“…Hả? Chuyện gì thế?!”","“Exusiai, địch xuất hiện bất ngờ…” Amiya lùi lại.","“Tôi đã chặn lối vào rồi mà, sao lại…” Franka nghiến răng.","“Có lẽ chúng đến từ các tòa nhà lân cận… Trông như chúng mang một loại máy phản lực thô sơ, nhưng thế là đủ dùng. Nếu chúng lẻn được qua những chỗ ta không phòng thủ được, ta sẽ ở thế bất lợi…”","“Chậc… Chờ tí, tôi đến giúp ngay.”","“Đừng lâu quá đấy, thiên thần hộ mệnh bé nhỏ của tôi,” Franka nói.","“Defender, vào đội hình! Nhanh!” Liskarm hô.","“…Tôi vào đây,” Texas nói, và lao đi.","“Mọi người, bảo vệ Vanguard!”","","Khi tên Reunion cuối cùng rơi khỏi mép mái nhà, Exusiai mới đáp xuống, khẩu súng vẫn còn bốc khói.","“…Tôi tưởng ta đã thống nhất là màn xuất hiện hoành tráng thuộc về tôi chứ.”","“Cô chậm quá,” Texas nói.","“Quan trọng là mọi người đều an toàn,” Amiya nói. “Chúng ta nên đi thôi. Từ tòa nhà này, ta sẽ đi xuống về phía đông. Reunion sẽ không biết ta ở đâu.”","“Chúng ta… an toàn rồi sao?” Misha hỏi khẽ.","“Vâng… Tạm thời.” Amiya nhìn kỹ cô gái. “Sắc mặt chị không tốt lắm…”","“Tôi… hơi chóng mặt… Không sao đâu.”","“Chị Misha, chị đến Lungmen bao lâu rồi?”","“Khoảng… một tuần.”","“Mới một tuần…?”","“Ừm… Nhiều người lạ xuất hiện trong thành phố… rồi sau đó…” Misha nhắm mắt lại, như đang cố nhớ. “Tôi không rõ chuyện gì đã xảy ra… Mọi người bắt đầu bỏ chạy, nên tôi cũng…”","“Là Reunion… Reunion đã tấn công Chernobog.”","“Tôi không biết.”","“Trước đó… chị đã bị nhiễm bệnh chưa?”","“Tôi… tôi không biết… Nhưng mấy ngày gần đây, những thứ này… bắt đầu mọc trên chân tôi. Tôi…”","Misha lảo đảo.","“…Chị Misha? Chị Misha?!” Amiya đỡ lấy cô gái vừa ngã quỵ. “Y tế! Đội y tế đâu rồi?!”"],"bg":"bg_lungmen_b","cast":[["Amiya","op:char_002_amiya"],["Misha","npc:char_012_misa_1"],["Exusiai","op:char_103_angel"],["Texas","op:char_102_texas"],["Liskarm","op:char_107_liskam"],["Franka","op:char_106_franka"]]},{"c":"2-7","t":"Chuyện y tế công cộng","p":["“Nngh…” Misha rên khẽ, mồ hôi đầm đìa trên trán.","“Cô ấy bị sao vậy…?” Exusiai lo lắng hỏi.","“Đây là triệu chứng cấp tính của Oripathy!” Amiya nói, tay vẫn đặt trên trán Misha. “Nhưng mới chỉ có một tuần thôi mà…!”","“Oripathy cũng có dạng cấp tính sao?” Liskarm hỏi, rồi quay sang. “Franka, cô thuộc loại nào?”","“Gì, cô lo cho tôi à?”","“Amiya, nếu Franka qua đời, tôi mong Rhodes Island sẽ hỏa táng cô ấy.”","“Này! Ác quá đấy, Liskarm!”","“Chính cô là người suốt ngày dọa lây bệnh sang tôi!”","“A… Ahaha…!” Amiya bật cười dù đang lo, rồi nghiêm mặt lại. “Phân biệt dạng cấp tính và mãn tính là một chủ đề khá phức tạp. Nhưng tình trạng của chị Misha rất nguy hiểm. Nếu không làm gì, nó sẽ nhanh chóng đe dọa tính mạng. Chúng ta chỉ có thể sơ cứu khẩn cấp… nhưng phải kiểm soát triệu chứng của chị ấy càng sớm càng tốt. Phải nói rõ với Lungmen. Sau chuyện này, chúng ta phải đưa chị Misha về Rhodes Island. Đây là một phần trách nhiệm của chúng ta.”","“Ừm…” Exusiai ngập ngừng. “Cô ấy… sắp nổ tung à?”","Bốp.","“Á! Đau! Sao lại đánh tôi…”","“Cẩn thận lời nói,” Texas nói.","“Nếu một ngày tôi sắp nổ tung,” Franka cười tươi, “tôi nhất định sẽ bò đến chỗ cô.”","“Tôi xin lỗi! Cô Franka, xin tha thứ cho mọi lỗi lầm của tôi!”","“Phì…”","“Chuyển cô ấy đến chỗ an toàn trước đã,” Liskarm nói. “Mà, có vẻ phía sau đang có chuyện.”","Ở con hẻm bên dưới, một nhóm người Infected đang bị Reunion dồn vào góc.","“Các người làm gì vậy?! Cút ra!!”","“Chúng ta đều là người Infected cả, đừng bắt bọn tao dùng bạo lực! Tránh đường!”","“Các người đã phá nhà của bọn tôi, giờ còn định lôi L.G.D. đến đây?! Đừng hòng!!”","“Mày…! Đồ ngu dốt, tránh ra!!”","Một tiếng thét, rồi tiếng đổ vỡ.","“(Ta có can thiệp không?)” Franka thì thầm. “(Có vẻ ta đã cắt đuôi được chúng. Nhưng nếu can thiệp bây giờ, ta sẽ bị lộ.)”","“(Việc này có cản trở nhiệm vụ không? Nếu có, hậu quả nghiêm trọng đến mức nào?)” Liskarm hỏi.","“(Đương nhiên là có cản trở, nhưng… sẽ không nghiêm trọng đến thế, đúng không?)”","“Vậy thì làm thôi,” Amiya nói. “Sứ mệnh dứt khoát của Rhodes Island là cứu người Infected, chừng nào tình hình còn cho phép.”","“Ừm, tốt lắm.” Franka cười. “Tôi biết đi theo cô là quyết định đúng mà.”","“Ý chị là sao, chị Franka?”","“Đừng lo, đừng lo! Tôi chỉ đang khen cô thôi!”","“Chắc cô ấy nghĩ mình hợp với cô lắm,” Liskarm nói.","“Sao cô hiểu tôi rõ thế?”","“Chắc vì cô phiền quá?”","“Ugh…” Amiya day trán.","“Đến lúc dạy cho lũ côn đồ này một bài học rồi,” Franka nói.","“Vâng. Cẩn thận những kẻ địch có thể nhảy giữa các tòa nhà. Ngoài ra, nhớ bảo vệ người dân Infected của Lungmen!”","“Yêu cầu nhiều quá đấy,” Texas nói. “—Nhưng, để tôi lo.”","“Được, đi thôi!” Exusiai nạp đạn. “Doctor, nhớ dẫn dắt tôi với Texas thật tốt nhé!”","","“Cảm ơn… Cảm ơn các cô nhiều lắm…”","“Ở đây không an toàn. Các vị nên nhanh chóng rời đi,” Amiya nói.","“Rời đi…? Đi đâu được chứ… Nơi này từng là chỗ bọn tôi có thể gọi là nhà… Nhưng giờ nó tan nát cả rồi…”","“Em xin lỗi…”","“Không phải lỗi của cô… Không phải…”","Exusiai nhìn theo những bóng người lặng lẽ thu dọn đống đổ nát. “Tôi không ngờ Reunion, kẻ tự xưng là cứu tinh của người Infected, lại đi tấn công người Infected khác. Đó mới gọi là truyền thông tệ hại.”","“Đợt thâm nhập của Reunion không tự nhiên mà có,” Texas nói. “Tôi chắc có nhiều người Infected ở đây đã chọn đi theo Reunion.”","“Ugh… Họ thà tin Reunion hơn Rhodes Island—”","“Rhodes Island không đưa ra những lời hứa suông,” Franka nói, giọng hiếm hoi trở nên nghiêm túc. “Có rất nhiều người Infected sẵn sàng chấp nhận bất cứ thứ gì Reunion đưa ra, kể cả khi đó chỉ là ảo ảnh. Ít người nhìn thấu được ảo ảnh. Và trong số những người nhìn thấu, phần lớn vẫn sẵn sàng đánh đổi mọi thứ chỉ để lấy tia hy vọng mờ nhạt ấy. Ai lại chọn tin cô thỏ con của chúng ta, người quá tốt bụng để lừa dối người khác chứ?”","Amiya cúi đầu.","“Tôi tin cô ấy.”","“…Chị Misha?”","Misha đang cố ngồi dậy, một tay bám vào tường. “Nnh…”","“Cẩn thận! Chị chưa được cử động đâu!”","“Tôi chỉ hơi chóng mặt thôi… Đừng lo.” Misha nhìn quanh. “Reunion… vẫn còn đuổi theo chúng ta sao? Tôi không biết họ muốn gì ở tôi… Nhưng… Đi thôi…” Cô ngẩng lên. “Amiya.”","Amiya nhìn cô gái thật lâu. Rồi gật đầu.","“Em hiểu rồi. Chúng ta đi ngay. Sắp ra khỏi khu ổ chuột và gặp L.G.D. rồi. Cảm ơn chị, chị Misha.”","“Không… Tôi… mới là người nên cảm ơn em.”"],"bg":"bg_lungmen_b","cast":[["Amiya","op:char_002_amiya"],["Franka","op:char_106_franka"],["Misha","npc:char_012_misa_1"],["Exusiai","op:char_103_angel"],["Liskarm","op:char_107_liskam"],["Texas","op:char_102_texas"]]},{"c":"2-8","t":"Không hứa hẹn","p":["“Franka, Liskarm, để ý xung quanh. Em sẽ đưa chị Misha đến chỗ cô Ch’en.”","Ch’en đứng chờ ở điểm hẹn, tay khoanh trước ngực.","“Lại muộn nữa. Lungmen không muốn thêm rủi ro an ninh nào.”","“Cô Ch’en, đội hộ tống của bọn em bị Reunion tấn công nhiều lần. Thực ra, lúc này chúng vẫn còn quanh đây. Ở đây không an toàn. Xin hãy đưa chị Misha đi càng sớm càng tốt.”","Ch’en nhìn Misha. “Cô là Misha?”","“Là tôi…”","“Từ giờ, cô sẽ tuân theo sự sắp xếp của L.G.D. PC94172, cậu phụ trách cô gái này.”","“Đi với tôi.”","“Amiya…” Misha ngoái lại.","“Không sao đâu.” Amiya mỉm cười, rồi quay sang Ch’en. “Cô Ch’en, em không biết Lungmen cần chị ấy để làm gì… Nhưng em mong cô có thể đảm bảo an toàn cho chị ấy.”","“Chúng tôi vẫn đối xử với người Infected rất tử tế.”","“Em hiểu… Nhưng sức khỏe chị Misha không tốt. Bọn em mong sau chuyện này, Lungmen sẽ cho phép chị ấy đến sống ở Rhodes Island.”","Ch’en im lặng một lúc. “…Tôi sẽ gửi đơn lên Trưởng quan Wei. Lungmen sẽ chuyển cô ấy sang Rhodes Island nếu cô ấy vượt qua kiểm tra mà không có vấn đề gì khác. …Nếu không có vấn đề gì. Sẽ không mất nhiều thời gian đâu.”","“Em hiểu rồi.” Amiya quay sang Misha. “…Chúng ta tạm chia tay nhé, chị Misha. Rhodes Island chào đón chị.”","Misha nhìn cô bé. “Amiya, trong lúc tôi đi, xin hãy bảo vệ lũ trẻ trong khu ổ chuột.”","“Hả? …À, đúng rồi. Không vấn đề gì, em hứa!” Amiya ngập ngừng, rồi thêm: “Còn nữa, chị Misha…”","“Hửm?”","“Lần sau, chị dạy em… làm búp bê được không?”","Misha nhìn cô bé thỏ, và lần đầu tiên kể từ khi họ gặp nhau, cô bật cười, một tiếng cười rất khẽ.","“…Hehe. Ừm, được chứ.”","","“Vậy là nhiệm vụ xong rồi à?” Franka hỏi khi bóng xe L.G.D. đã khuất.","“Rhodes Island càng bị lôi vào chuyện này, càng bị trói tay,” Texas nói.","“Nhưng Lungmen vẫn giữ rất nhiều bí mật với chúng ta,” Franka nói.","“Lungmen có vẻ chẳng bận tâm đến chúng ta lắm…” Liskarm nói, mắt nhìn về phía những mái nhà xa. “Nhưng với Reunion thì ngược lại.” Cô ta khựng lại. “…Amiya. Địch muốn tấn công khu vực chúng ta đang đứng.”","“Dù đã nghe nói rồi, nhưng kiến trúc Lungmen đúng là phức tạp thật!” Franka nhìn quanh. “Cả con phố này thực ra được xây trên các mái nhà… và điều đó đang cho kẻ địch một lợi thế khổng lồ!”","“Reunion lại tấn công nữa…!” Amiya nắm chặt tay. “Chúng đuổi theo ta tận đến đây sao?! Tại sao chúng… lại muốn chị Misha đến thế?”","","“Phù…” Franka tra kiếm vào vỏ. “Đội hộ tống của L.G.D. đã rời đi an toàn. Nhưng… có vẻ kẻ địch không có ý định để chúng ta đi.”","“Chừng nào chúng chưa biết chị Misha đã đi cùng L.G.D., chúng sẽ tiếp tục dồn sức vào chúng ta,” Amiya nói. “Chị Misha sẽ an toàn hơn theo cách này.”","“Giờ nghĩ lại, tại sao cả Reunion và Lungmen đều muốn con bé này?” Liskarm hỏi.","“Em không dám chắc. Có nhiều khả năng lắm. Em đoán… hoặc chị ấy, hoặc điều gì đó chị ấy biết, đủ quan trọng để quyết định sự an nguy của Lungmen.”","“Điều gì đó?”","“Vâng, có lẽ là tin tình báo hay thông tin gì đó… Nên cả Lungmen và Reunion đều muốn có chị ấy.”","“Một cuộc giành giật nguy hiểm…” Liskarm nói.","“Và không ai trong chúng ta có thể đứng ngoài. Không phải chúng ta, không phải chị Misha, cũng không phải L.G.D.”","“Mong là ta không bị kẹt giữa làn đạn,” Franka nói. “Chẳng biết gì cả, mà lại phải lo hết mọi thứ…”","“Em… em cũng không chắc lắm…” Amiya nhìn về hướng xe L.G.D. đã đi. “Nhưng về phía cô Ch’en… Em có linh cảm… mọi chuyện sẽ không kết thúc suôn sẻ như vậy đâu.”","“Amiya, còn việc gì cho bọn tôi không?” Exusiai hỏi. “Có cần hộ tống các cô về Rhodes Island không?”","“Không cần đâu, cảm ơn cậu. Giờ không còn gì cản trở khi chiến đấu nữa, bọn mình sẽ ổn thôi.”","“Vậy bọn tôi về chờ lệnh tiếp theo,” Texas nói.","“Vâng. Sắp tới, mong mọi người tiếp tục theo dõi động tĩnh của Reunion trong Lungmen. Dù đã giao chị Misha cho L.G.D., việc Reunion có mặt ở đây… vẫn khiến em bất an.”","“Dễ thôi~ Bọn tôi đi đây~”","Amiya quay sang các operator. “Mọi người, chúng ta không biết còn bao nhiêu thành viên Reunion đang ẩn nấp. Luôn sẵn sàng và cảnh giác. Tiếp theo, ta sẽ tiếp tục di chuyển trong các tòa nhà cao tầng này. Nếu cần, có thể dùng cả sân thượng. Như vậy, ta sẽ có lợi thế địa hình thay vì phải đánh nhau ngoài đường. Nếu cần, ta sẽ dụ chúng vào khu vực ta kiểm soát!”","“Rõ!”","","Trên nóc một tòa nhà cao nhất khu, nơi gió thổi lồng lộng, Crownslayer quỳ một gối.","“Talulah. Mọi chuẩn bị đã hoàn tất.”","Talulah đứng ở mép mái, nhìn xuống thành phố lấp lánh như một tấm thảm sao.","“…Đến lúc ra tay rồi.”","Crownslayer ngập ngừng.","“—Nói đi,” Talulah nói, không quay lại.","“Tấn công Lungmen thực sự có mục đích chiến lược. Nếu ta kiểm soát được Lungmen, Reunion sẽ có lợi thế lớn. Đương nhiên, rủi ro cũng rất cao.” Crownslayer ngẩng lên. “…Tại sao cô lại bận tâm với ý tưởng này đến thế?”","Talulah im lặng rất lâu.","“Cô thấy công trình đằng kia không?”","“Tôi thấy.”","“Đó là biểu tượng của Lungmen… Nó cũng là…” Talulah ngừng lại. “Ta không trở lại đây chỉ để đòi lại mọi thứ đã bị cướp khỏi người Infected. Ta còn muốn… bắt hắn phải trả giá.”","Gió thổi tung mái tóc cô ta. Và rồi cô ta mỉm cười, một nụ cười kỳ lạ, như không phải dành cho Crownslayer mà dành cho một ai đó khác, ở rất xa hoặc rất gần.","“Trên hết… Cô không thấy rằng… mọi chuyện đang trở nên rất thú vị sao? Cô có đồng ý không… Talulah?”"],"bg":"bg_lungmen_b","cast":[["Amiya","op:char_002_amiya"],["Franka","op:char_106_franka"],["Talulah","npc:avg_npc_078"],["Ch'en","op:char_010_chen"],["Misha","npc:char_012_misa_1"],["Crownslayer","npc:char_1502_crowns"],["Liskarm","op:char_107_liskam"],["Exusiai","op:char_103_angel"]]},{"c":"2-9","t":"Căn phòng tối","p":["“…Sao ở đây lại có nhiều Reunion thế này?!” Liskarm giương khiên đỡ một loạt tên.","“Có mỗi tôi thấy chúng kéo đến mỗi lúc một đông sao?” Franka hỏi, hạ thêm một tên.","“Không. Rõ ràng chúng còn viện binh nữa.”","“Chết tiệt… Còn chưa kịp trả thù cho họ…!” Amiya nghiến răng.","“Chúng tìm thấy ta trước rồi,” Liskarm nói. “Franka, nhìn kìa. Ở lối ra phía đông, tôi nghĩ là Caster của Reunion đang nấp đằng đó.”","“Còn nhiều tên đang tiến từ lối giữa và từ các tòa nhà hai bên… Chúng định lẻn tới, giả vờ như chưa phát hiện ra ta. Nhưng chúng ta đang ở trên mái nhà. Dù chúng gửi bao nhiêu quân, chỉ cần bị hất xuống là xong đời. Một đợt tấn công lộ liễu thế này, tôi thấy như chúng đang xúc phạm trí thông minh của tôi vậy.”","“Reunion đang mở cuộc tổng tấn công sao? Tất cả operator, tập hợp!”","“Khoan, tôi nghĩ tôi vừa thấy…” Franka nheo mắt. “Chẳng phải đó là tên chỉ huy Reunion ta gặp lúc nãy sao?”","Skullshatterer bước ra giữa mái nhà, cây trượng-súng trên vai.","“…Rhodes Island. Các người đã giao cô ấy cho Lungmen rồi sao?”","Amiya không trả lời ngay. Cô bé thì thầm với Franka: “(Phải cầm chân quân Reunion trước! Khi nào chúng sợ không dám tấn công nữa thì ta mới tìm đường xuống! Tạm thời phải dàn rộng chiến trường ra!)”","“(Hiểu rồi. Đánh rồi chạy nhé!)”","“Chuyện đó thì liên quan gì đến anh?” Amiya hỏi lại.","“…Các người dám!” Skullshatterer gầm lên. Hắn im lặng một nhịp, rồi giơ cao vũ khí. “Các đồng chí, tấn côôông!”","","“Đây là đợt truy đuổi cuối cùng!”","“…Aaargh!”","“Sạch rồi! Xác nhận bên này an toàn!” Liskarm báo.","“Tên chỉ huy địch đâu?” Franka hỏi.","“…Không có trong đội chủ lực.”","“Kẻ địch đang ẩn nấp… Ta đang bị theo dõi.” Franka nhìn quanh. “Chúng định bào mòn ta đến khi có cơ hội hoàn hảo để ra đòn sao?”","“Reunion chẳng xa lạ gì với đánh lén,” Amiya nói. “Bọn mình đã học được bài học cay đắng ấy ở Chernobog. Rút nhanh thôi…”","“Tôi không đảm bảo được an toàn của đường thoát,” Liskarm nói. “Nếu chúng bắt đầu phá các tòa nhà xung quanh để chặn đường, ta sẽ gặp nguy.”","“Nhanh, xem còn đường nào khác. Càng kín đáo càng tốt!”","“Amiya, thử cầu thang ở hướng bốn giờ đi xuống?”","“Đường đó khó đi đấy,” Franka nói.","“Aaargh! Rhodes Island!”","“Phục kích! Cẩn thận!”","Từ một tầng thượng xa hơn, Skullshatterer nhìn xuống. “Tiếp tục truy đuổi. Đừng cho chúng một chút không gian để thở.”","@bg:bg_lungmen_r","Trong một căn phòng tối của L.G.D., Misha ngồi bên chiếc bàn sắt, hai tay đặt trên đầu gối. Ch’en đứng tựa vào tường đối diện.","“Thưa cô…” Misha lên tiếng. “Vẫn còn vài đứa trẻ Infected… trong khu ổ chuột. Nếu có thể… tôi mong cô có thể chăm sóc chúng…”","“Nhiệm vụ của chúng tôi là bảo vệ Lungmen,” Ch’en nói. “Người Infected không được coi là công dân Lungmen.”","Misha cúi đầu.","Ch’en im lặng một lúc. Rồi cô ta nói tiếp, giọng vẫn khô khốc, nhưng chậm hơn.","“…Tuy nhiên, dù là công dân hay không, người Infected vẫn thuộc về Lungmen. Tôi không có nghĩa vụ phải hứa hẹn gì với cô, nhưng tôi sẽ làm tròn bổn phận của mình. Dù sao thì…”","“Họ nói họ từng…”","“Đó là việc chúng tôi vẫn luôn làm.”","Misha ngẩng lên. Ch’en không nhìn cô.","“…Cảm ơn cô…”","“…Cô có biết tại sao chúng tôi tìm cô không?”","“…Tôi không chắc. Tôi không nghĩ ra lý do nào khiến các người cần tôi. Nhưng tôi có cảm giác… chuyện này không phải vì tôi…” Misha nhìn xuống đôi tay mình. “…Mà là vì cha mẹ tôi.”","“…Đúng vậy,” Ch’en nói. “Cha cô là nhà khoa học nổi tiếng nhất Chernobog. Đồng thời cũng là một trong những nhân vật chính trị quan trọng nhất ở đó. Có lẽ, có điều gì đó cô biết…” Cô ta ngừng lại. “Nhưng kể cả không phải vậy… chúng tôi cũng không thể để cô rơi vào tay Reunion.”","","Bên ngoài, trên một cột ăng-ten cao chót vót, một bóng người tóc bạc đang ngồi vắt vẻo, đung đưa chân.","“Hehe. Tìm thấy các người rồi, L.G.D.” W thì thầm, mắt dõi theo đoàn xe bên dưới. “Đừng để bụng nhé… Nhưng tôi đang có trong tay một kịch bản rất thú vị. Để mọi thứ hấp dẫn hơn, tôi cần tất cả các người cùng tham gia.”","Cô ta đứng dậy, một khối thuốc nổ trong tay.","“Giờ thì, bắt đầu thôi.”"],"bg":"bg_lungmen_b","cast":[["Ch'en","op:char_010_chen"],["Franka","op:char_106_franka"],["Amiya","op:char_002_amiya"],["Misha","npc:char_012_misa_1"],["Liskarm","op:char_107_liskam"],["Skullshatterer","npc:char_1500_skulsr"],["W","npc:avg_npc_046"]]},{"c":"2-10","t":"Vô phương cứu chữa","p":["“Liskarm, cô giữ được phòng tuyến không?”","“Bên này ổn! Franka, cẩn thận địch đánh vào sườn!”","“Chúng cứ kéo đến mãi…!”","“Các ngươi không có cửa phá được phòng tuyến của bọn ta đâu! Ta sẽ nghiền nát…” Tên Reunion khựng lại. “Gưh?! A-aaaagh! C-cái gì thế kia?!”","“Kiếm thermite đấy,” Franka nói, lưỡi kiếm đỏ rực trong tay. “Chém thì có tính là nghiền nát không nhỉ? Phiền ghê… Y tế! Có người bị thương ở đây! Cẩn thận khi di chuyển họ!”","“Tôi lo!”","“Amiya! Bên đó thế nào rồi?”","“Tôi nghĩ ta có chút vấn đề ở đây,” Liskarm nói.","“Franka…” giọng Amiya vang qua bộ đàm. “Tên chỉ huy địch… vừa xuất hiện ngay trước mặt em và Liskarm!”","Skullshatterer đứng chắn giữa con đường duy nhất.","“…Các người còn định trốn đi đâu nữa? Các người không thoát được bọn ta đâu, Rhodes Island. Ta sẽ nghiền các người thành bụi… đến xương cũng không còn. Lũ phản bội các người… đã quay lưng với người Infected!”","“Ồ~ Cuối cùng gã này cũng chịu lộ mặt,” Franka nói qua bộ đàm. “Nghe cũng chẳng ấn tượng lắm.”","“Amiya, có vẻ ta—”","“Á, ngõ cụt!” Franka hét lên ở đầu dây bên kia. “Mình chạy xa quá rồi à?!”","“Franka cũng đang gặp vấn đề…” Liskarm thở ra. “Reunion đã dồn ta vào góc.”","Amiya im lặng.","“Ta phải đánh thôi,” Liskarm nói. “Tôi thấy… ta hoàn toàn đủ sức đối đầu với chúng. Chỉ cần nghiêm túc hơn một chút…”","“Liskarm, cô chẳng hiểu gì cả,” Franka nói. “Dù ta thể hiện sức mạnh đến mức nào, ta cũng không thể để L.G.D. cảm thấy bị đe dọa.”","“Nhưng ta không thể ngồi yên để chúng giẫm lên ta! Defender, giữ vững!”","Skullshatterer chĩa vũ khí về phía Amiya.","“Một thủ lĩnh của Rhodes Island, hả… Ngươi là người Infected, nhưng vẫn giúp Lungmen tàn sát người Infected khác! Trên tay ngươi dính máu của biết bao đồng chí của ta! Đứng lên đối mặt với ta!”","Amiya ngẩng đầu. Đôi mắt xanh lục rực lên.","“…Reunion… Chính các người là kẻ khơi mào thù hận, đau đớn và bạo lực… Chính các người đã bắt đầu tất cả ở Chernobog!!”","","“Nngh…” Skullshatterer quỳ một gối, cây trượng cắm xuống mái tôn.","“Ugh… Gahh…” Amiya cũng lảo đảo, thở dốc.","“Skullshatterer, anh không sao chứ?!” Một tên Reunion chạy tới.","“Chậc… Lũ phiền phức!”","“Skullshatterer, W vừa báo là bên cô ấy xong việc rồi! Cô ấy đã đoạt được mục tiêu!”","“W… thắng rồi?”","“Đúng vậy, cuộc tập kích diễn ra rất suôn sẻ! Chúng ta cũng rút chứ?”","Skullshatterer im lặng một lúc. “…Báo tín hiệu cho Talulah.”","“Rõ!”","“…Chúng ta rút.” Hắn đứng dậy, nhìn Amiya qua lớp mặt nạ. “Hừ. Lũ hèn nhát Rhodes Island… Lần sau gặp lại… sẽ là ngày hành quyết các người.”","Đám Reunion rút đi nhanh như khi chúng đến.","“Reunion… đang rút lui?” Amiya ngơ ngác.","“Chúng rút rất nhanh,” Franka nói qua bộ đàm. “Kế hoạch của chúng hẳn đã thay đổi. Nói to thế mà chạy cũng nhanh ghê.”","Amiya đứng im giữa mái nhà.","“…Có gì đó… không đúng.”","“Ý cô là…” Liskarm hỏi.","“Ngay từ đầu, chúng ta không phải mục tiêu của chúng,” Doctor nói.","Amiya quay phắt lại, mặt tái mét. “…! Chúng chỉ ở đây để cầm chân chúng ta…? Nếu vậy thì… Không xong rồi, L.G.D. gặp nguy rồi! …Chúng ta phải đi giúp cô Ch’en ngay! Franka, gọi đội trinh sát về ngay lập tức! Liskarm, thử liên lạc với cô Ch’en!”","","Ở một ngã tư cách đó vài cây số, đoàn xe L.G.D. đang bốc cháy.","“Đội Tác chiến Đặc biệt đâu? Viện binh của họ lẽ ra phải đến rồi chứ!” Ch’en quát vào bộ đàm, thanh kiếm đã rút khỏi vỏ.","“Chúng tôi vừa được báo họ bị Reunion cầm chân…!”","“Sao có thể? Reunion chỉ là một lũ côn đồ vô kỷ luật!”","“…Và họ chỉ đối mặt với… một kẻ địch duy nhất…”","Ch’en đứng im giữa khói lửa.","“…Trừ khi…”"],"bg":"bg_lungmen_r","cast":[["Amiya","op:char_002_amiya"],["Skullshatterer","npc:char_1500_skulsr"],["Franka","op:char_106_franka"],["Liskarm","op:char_107_liskam"],["Ch'en","op:char_010_chen"]]}],"id":"main_2","no":"Chương 2","title":"Những trái tim chia lìa","en":"Separated Hearts","sum":"Rhodes Island đến Lungmen, ký một thỏa thuận đầy toan tính với Wei Yenwu. Nhiệm vụ đầu tiên: tìm một cô gái Ursus tên Misha giữa khu ổ chuột, trước khi Reunion tìm thấy cô ấy."},{"secs":[{"c":"3-1","t":"Gặp gỡ","p":["Khi Rhodes Island đến nơi, ngã tư chỉ còn là đống sắt vụn cháy đen. Những chiếc xe L.G.D. lật nghiêng, kính vỡ vương khắp mặt đường. Ch’en đứng giữa đống đổ nát, áo khoác rách một bên vai, thanh kiếm vẫn còn trên tay.","“Có vẻ các người cũng vất vả,” cô ta nói.","“Cô Ch’en, chuyện gì đã xảy ra?”","“Chúng tôi bị Reunion phục kích. Bị dồn vào một đợt tấn công dữ dội mà không có viện binh. Chúng dễ dàng đánh tan lực lượng của chúng tôi.”","“Còn chị Misha…?”","“Bị một ả mặc đồ đỏ bắt đi.” Ch’en siết chặt chuôi kiếm. “Lẽ ra tôi phải…”","Amiya chờ cô ta nói tiếp. Nhưng Ch’en chỉ lắc đầu. “Không có gì.”","Amiya im lặng một lúc. Rồi cô bé bước lên một bước.","“Cô Ch’en, tại sao chị Misha lại đặc biệt đến vậy? Nếu cô cứ giấu bọn em, việc hợp tác sẽ ngày càng khó khăn hơn.”","“Tôi không có nghĩa vụ phải nói cho các người.”","“Nhưng Rhodes Island có nghĩa vụ phải hiểu mục tiêu và chuẩn bị chiến lược phù hợp,” Amiya đáp, giọng không lớn nhưng rõ ràng từng chữ. “Đương nhiên, bọn em sẽ tiếp tục làm theo chỉ thị của L.G.D. trong các chiến dịch… Nhưng khi phải dùng người Infected để chiến đấu với người Infected khác, bọn em cần mọi thông tin có thể có. Cô có thông tin, nhưng không có cách dùng nó hiệu quả để giảm tổn thất. Ngược lại, bọn em có khả năng ngăn Reunion, nhưng lại không biết chúng muốn gì.”","Ch’en nhìn cô bé rất lâu.","“…Vừa rồi, cô nói nghe hơi giống tay bác sĩ kia đấy.”","“V-vậy sao ạ…” Amiya hơi đỏ mặt, nhưng không lùi bước. “Em nghĩ… đây là điều quan trọng như nhau với cả hai bên.”","“Tôi hiểu rồi.”","“Nếu là vì cô cần xin phép Trưởng quan Wei…”","“Khi điều tra Misha,” Ch’en cắt ngang, “thông tin nổi bật nhất là cha cô ấy là một trong những người có ảnh hưởng nhất Chernobog.”","“Cha của chị Misha?”","“Đương nhiên, chúng tôi không biết Misha biết bao nhiêu về Chernobog. Cô ấy có thể không biết gì, hoặc biết tất cả. Không ai biết… ngoài cô ấy. Chúng tôi cũng không biết cô ấy có thể nắm giữ loại thông tin gì. Vì các người đã dự đoán Lungmen sẽ là mục tiêu tiếp theo của Reunion, rõ ràng chúng tôi phải ngăn Reunion lợi dụng Chernobog. Vì thế, không thể để chúng có được Misha. Chúng tôi biết có người phù hợp với mô tả của cô ấy đã lánh nạn ở Lungmen… nhưng cho đến khi các người thực sự tìm thấy cô ấy, chúng tôi không thể xác minh thông tin đó.”","“Nếu vậy thì không thể lãng phí thêm thời gian nữa,” Amiya nói. “Chúng ta phải ngăn Reunion và giải cứu chị Misha trước khi chúng đưa được chị ấy về Chernobog! Rhodes Island, chuẩn bị xuất phát!”","“Truy tìm cô ấy là trách nhiệm của L.G.D.,” Ch’en nói. “…Và để Reunion bắt được cô ấy là sự thất trách của chúng tôi. Thay vì mở chiến dịch chung, tôi cần Rhodes Island tiêu diệt các mối đe dọa khác của Reunion. Đây là mệnh lệnh.”","Amiya cắn môi. “…Rõ.”","“Đừng làm tôi thất vọng.”","","Ở những con phố gần đó, Ch’en tự mình dẫn L.G.D. càn quét.","“K-không! Đ-đừng đánh tôi…”","“Lẽ ra mày phải nghĩ kỹ trước khi bước vào Lungmen!” Ch’en quật ngã tên Reunion. “Bắt hết lại!” Cô ta nhìn quanh, nghiến răng. “Chúng không ở cùng nhóm Infected này. Chết tiệt… Nhóm này cũng không… Khốn kiếp thật…”","“Chúng… rút đi nhanh quá…” một nhân viên L.G.D. nói.","“Có vẻ Reunion cũng có hệ thống cấp bậc. Chúng chỉ để lại đám tép riu để câu thêm thời gian.” Ch’en nhìn về phía chân trời. “Một người duy nhất mà cầm chân được viện binh của ta… Rốt cuộc chúng là ai…”","“Thưa sếp! Có toán Reunion còn sót ở đằng kia!”","“Theo tôi!”","“…! Cẩn thận, cô Ch’en! Phục kích!”","“Đ-đi chết đi!”","“Đừng cản đường ta—!”","“Cô Ch’en, chúng ta vẫn đang ở trên đất Lungmen! Các cơ sở xung quanh vẫn còn dùng được, xin cô đừng gây thiệt hại quá nhiều!”","“Im đi!”","“Ít nhất đừng chém mấy tòa nhà này thành từng mảnh!”","“C-con mụ này… Khó đối phó quá!”","“…Khó đối phó?” Ch’en dừng lại, đôi mắt đỏ rực lóe lên như than hồng. “Lũ Infected ngu xuẩn… Các ngươi nghĩ bọn ta sẽ để lũ rác rưởi các ngươi biến Lungmen thành nhà xí riêng sao?! L.G.D., tấn công!”","","“Thưa sếp…”","“Nói.”","@cg:avg_21_1","“Phần lớn quân Reunion đã rút.”","“Cô Ch’en, bên bọn em cũng xong rồi,” Amiya báo.","“Chậc…” Ch’en quay sang một nhân viên. “Những nghi phạm Reunion bắt được mấy hôm trước… đã khai thác được gì chưa?”","Trong phòng thẩm vấn, một người Infected đeo mặt nạ ngồi im như tượng.","“Cái nỏ này trông quen không?”","Im lặng.","“Mày giương được nó, phải không? Cấu tạo của đạn thế nào? Hoạt động ra sao? Mày làm gì trong khu ổ chuột? Mày làm gì ở Lungmen?”","Im lặng.","“…Không có gì,” nhân viên L.G.D. báo cáo. “Chúng không nói một lời. Hoặc có lẽ… chúng chẳng biết gì cả. Giống như những thành viên Reunion khác ta đã hạ, chúng có lẽ chỉ là những con rối biết vâng lời.”","“…Bắt chúng nói,” Ch’en nói. “Dùng mọi biện pháp cần thiết. Tôi muốn biết về các đội của chúng, ban lãnh đạo, chiến lược, chúng từ đâu đến và định làm gì… Moi hết những gì có thể. Tôi muốn mọi thứ. Báo lại cho tôi ngay, dù có vẻ vụn vặt đến đâu.”","“Rõ!”","“L.G.D. đã từng bắt được thành viên Reunion trước đây chưa ạ?” Amiya hỏi.","“Không thể nói chắc. Cuối cùng thì, cũng chỉ là phỏng đoán.” Ch’en quay đi. “Nối máy cho tôi với Hoshiguma! Đội Tác chiến Đặc biệt thế nào rồi? Vẫn bị một người Infected duy nhất áp đảo sao?”","“Có vẻ Reunion bên đó cũng đã rút. Thanh tra Hoshiguma lo ngại có bẫy nên đang loại trừ mọi rủi ro…”","“Hừ… Chỉ một người…” Ch’en nghiến răng. “Chúng nghĩ chúng là ai mà đến rồi đi như vậy?!”","Cô ta im lặng một lúc, rồi quay sang Amiya.","“Cô hẳn đã biết nhiệm vụ tiếp theo là gì rồi, Amiya.”","“Bọn em sẽ đưa chị Misha về?”","“Đúng. Đây sẽ là chiến dịch chung. L.G.D. dẫn đầu, Rhodes Island phụ trách trinh sát và tấn công. Nhiệm vụ của các người hoàn thành khi chặn được đường rút của Reunion.”","“Rõ.”","“Nếu đi tìm địch… chẳng phải ta cũng có nguy cơ bị phát hiện sao?” Franka hỏi. “Lúc này đội trinh sát của ta cũng không đủ hỗ trợ. Không tự làm được đâu.”","“Việc này nên để dân chuyên nghiệp,” Amiya mỉm cười. “Franka, giúp em liên lạc với Penguin Logistics. Bọn mình sẽ cần Exusiai và Texas giúp thêm lần nữa.”"],"bg":"bg_wild_m","cast":[["Ch'en","op:char_010_chen"],["Amiya","op:char_002_amiya"],["L.G.D. Agent","npc:char_015_lmg"],["Franka","op:char_106_franka"]]},{"c":"3-2","t":"Ký ức","p":["“Cũng đến lúc cô xuất hiện rồi, Hoshiguma.”","Người phụ nữ bước tới cao lớn đến mức phải cúi đầu khi qua cửa. Một chiếc sừng Oni duy nhất mọc trên trán, chiếc khiên trên lưng to như một cánh cửa thép. Hoshiguma, thanh tra Đội Tác chiến Đặc biệt của L.G.D.","“Xin lỗi. Chúng tôi bị cầm chân khá lâu.”","“Có bị thương không?”","“Không. Nhưng chúng tôi bị sốc vì người Infected đó quá mạnh. Đội Tác chiến Đặc biệt đã điều nhiều thành viên đi tăng cường phòng thủ Lungmen. Tôi phải mang theo những người còn lại.”","“…Cả đội cô thật sự bị một kẻ địch duy nhất cầm chân sao?”","“Tôi cũng không tin cho đến khi tận mắt thấy cô ta. Người đó… thật sự mạnh đến vậy.” Hoshiguma nhíu mày, như đang nhớ lại điều gì kỳ lạ. “Hơn nữa, cô ta có vẻ hơi… lơ đãng?”","Rồi cô ta nhìn sang nhóm người đứng cạnh Ch’en. “Mà này, những người đứng cạnh cô… là Rhodes Island à?”","“Cô Ch’en, chị ấy là…” Amiya hỏi.","“Hoshiguma, tinh nhuệ của Đội Tác chiến Đặc biệt.”","“Vậy ra đây là Rhodes Island mà tôi nghe nói bấy lâu?” Hoshiguma cúi xuống nhìn Amiya, cao hơn cô bé gần gấp đôi. “Hừm, nhỏ quá. Em cũng là người của Rhodes Island à?”","“Cô ấy là thủ lĩnh của họ,” Ch’en nói.","“Ừm, cô Ch’en…”","“Ồ…” Hoshiguma nhướng mày. “Thôi, bỏ qua chuyện vặt. Có ý tưởng gì về bước tiếp theo không?”","“Hai đặc vụ của bọn em đã xác định được vị trí của bọn bắt cóc,” Amiya nói. “Họ đang theo dấu Reunion và có thể chỉ đường cho chúng ta.”","“Không tệ.” Hoshiguma quay sang Ch’en. “Ch’en, tôi hiểu vì sao họ được cô khen rồi. Những người này làm việc nghiêm túc lắm.”","“Cô Ch’en… khen bọn em sao?” Amiya ngạc nhiên.","“Hừ.” Ch’en quay mặt đi. “Hoshiguma, tập hợp các đội. Đến lúc xuất phát rồi. Dẫn đường đi, Rhodes Island.”","“Rõ. Đúng như dự đoán, Reunion đã để lại vài toán quân rải rác. Chúng sẽ phục kích trên đường ta đi…”","“Không vấn đề,” Hoshiguma nói.","“Vâng, chỉ cần di chuyển thận trọng, ta sẽ giành được thế chủ động.”","“Được!” Hoshiguma đập nắm đấm vào lòng bàn tay. “Để tôi xem các người đánh đấm thế nào, Rhodes Island!”","@bg:bg_wild_a","Trong một khu mỏ bỏ hoang cách Lungmen hàng chục cây số, những ngọn đèn dầu leo lét chiếu sáng các đường hầm. Misha ngồi bó gối trong một góc. Một người đàn ông Reunion bước tới, ngồi xuống bên cạnh.","“Vậy cô là Misha à? Chào cô. Tôi nghe Skullshatterer kể nhiều về cô lắm. Giờ mới được gặp.”","“…Anh cũng là… người Infected?”","“Đúng vậy.”","“Tại sao anh… gia nhập Reunion?”","“Tại sao à?” Người đàn ông im lặng một lúc lâu. “…Vợ tôi, con tôi… đều bị người Chernobog giết. Dưới thời Ursus, người Infected bị đối xử còn tệ hơn gia súc. Chernobog bị hủy diệt…? Không, không. Như thế còn là quá nhẹ. Cô có biết bàn tay chúng đã nhuốm bao nhiêu máu không?!” Giọng anh ta vỡ ra. “Misha… Chúng tôi bị sợ hãi, bị bóc lột, bị sỉ nhục, bị ngược đãi… Chỉ vì chúng tôi là người Infected. Không vì lý do nào khác.”","Misha không biết phải nói gì.","“X-xin lỗi, tôi hơi kích động. Quên những gì tôi vừa nói đi.”","“Ivan, đến giúp chăm sóc người bị thương đi.”","“Đến ngay.”","Skullshatterer bước vào, ngồi xuống chỗ Ivan vừa rời đi. Hắn không tháo mặt nạ.","“Chúng ta chỉ dùng khu mỏ bỏ hoang này làm căn cứ tạm thời, đến khi tổ chức lại và tập hợp xong. Khi thời cơ đến, chúng ta sẽ trở về Chernobog.”","Misha nhìn hắn. Nhìn đôi tay đầy vết sẹo, dáng ngồi hơi khom, cái cách hắn nghiêng đầu khi nói. Và môi cô bất giác mấp máy một cái tên.","“…Al—”","“Không.” Hắn cắt ngang. “Tôi đã vứt bỏ cái tên đó từ lâu rồi.”","“Tại sao…?”","“Người đó đã chết. Cứ gọi tôi là Skullshatterer.” Hắn ngừng lại. “Cô… sợ sao?”","“Skull… shatterer? …Tại sao?”","“À… Rồi cô sẽ sớm hiểu thôi.” Hắn nhìn xuống những người Infected đang băng bó cho nhau ở cuối đường hầm. “Khi biết cô trở thành người tị nạn ở Lungmen, mọi người đều tình nguyện đi cứu cô. Chúng tôi cũng đã kết nạp được nhiều thành viên mới ở đó.”","“Nhưng… các anh đang làm hại người khác. Tôi không muốn… làm như vậy… Tại sao người Infected lại đánh nhau…”","“Ăn miếng trả miếng, đó là lẽ đương nhiên. Ursus có câu: ‘Hãy đón người thân như đón mùa xuân ấm áp… Còn kẻ thù thì hãy đón bằng…’”","Hắn bỏ lửng câu nói. Im lặng rất lâu.","“Sao vậy?” Misha hỏi khẽ.","“…Cô có biết không? Không… Không, cô không biết đâu.” Giọng hắn trở nên xa xăm, như vọng về từ một cơn ác mộng chưa bao giờ dứt. “Khi chúng đến bắt tôi, chúng lôi tôi ra khỏi nhà… Tôi thấy mẹ. Bà nắm lấy tay tôi…”","“Sao vậy?”","“Cô cũng thấy mà.”","“…Không…”","“Chắc chắn cô đã thấy—” Hắn siết chặt hai nắm tay. “Chúng đánh bà không chút thương xót, nhưng bà vẫn không buông tay tôi… Bà để lại một vệt máu dài trên tuyết khi bị chúng kéo đi. Nếu Reunion khi ấy… Nếu người Infected khi ấy có thể… Giá mà—! Nếu họ đến sớm hơn, chuyện đó đã không xảy ra! Chúng ta đã không phải chịu khổ nhiều đến thế!”","“Tôi… Tôi đã không đủ can đảm để…” Misha bật khóc. “Tôi… Aaaahh…”","“Misha…” Skullshatterer đặt tay lên vai cô, rất nhẹ, như sợ làm vỡ thứ gì. “Không sao đâu… Rồi mọi chuyện sẽ ổn thôi. Tôi không trách cô. Khi ấy… ai có thể đủ can đảm chứ? Nhưng giờ, Reunion đã cho tôi lòng can đảm ấy.”","“Al—” Misha nghẹn lại, rồi sửa. “Skullshatterer…”","“Có tin chúng tôi hay không là do cô. Dù tin, có gia nhập chúng tôi hay không cũng là do cô. Nhưng cô là người Infected. Reunion… nhất định sẽ chiến đấu đến cùng để người Infected được tự do.”","“Nhưng… các anh đã hủy diệt Chernobog. Cùng với vô số người vô tội—”","“…Vô tội?” Skullshatterer bật cười, tiếng cười khô khốc như đá vỡ. “Hah. Ai vô tội chứ? Khi Chernobog thi hành lệnh cách ly, có ai trong số họ lên tiếng phản đối không? Khi Ursus đẩy chúng tôi đến chết trong hầm mỏ và những vùng đất băng giá, có ai trong số họ làm gì không? Đã có ai trong số họ từng đứng lên vì chúng tôi chưa?!”","“Tôi không biết…”","“…Reunion có hai thủ lĩnh đã chiến đấu chống lại Ursus từ rất lâu. Họ nói ở Ursus cũng có những người đứng lên chống chính quyền vì người Infected. Nhưng những người ấy không ở Chernobog. Chernobog lạnh lùng nhắm mắt làm ngơ khi chúng tôi chết… Không, chúng còn cười khi nhìn chúng tôi chết!!” Hắn đập tay xuống nền đá. “Chernobog… đáng bị hủy diệt!”","“Tôi đã gặp những người khác giúp đỡ người Infected… Họ…”","“Rhodes Island?” Giọng hắn lạnh đi. “Dù là người Infected, chúng vẫn giúp Lungmen và làm hại chúng tôi, phải không? Chúng đã giết đồng chí của tôi, tàn sát anh em của tôi, phải không?”","“Không…”","“Cô không nhìn thấy sự thật. Nhưng giờ hẳn cô đã rõ…” Hắn ngừng lại, cúi đầu. “…Xin lỗi, tôi để cơn giận lấn át.”","“Không sao… Tôi…” Misha lau nước mắt. “Tôi hiểu cảm giác của anh… Anh hẳn đã phải chịu khổ biết bao nhiêu… suốt ngần ấy thời gian…”","“Ai cũng đã trải qua nhiều chuyện. Nhưng lúc này, ít ra chúng tôi có hy vọng. Talulah… Cô ấy là người đã đứng ra dẫn dắt người Infected, lãnh đạo cuộc chiến chống lại sự tàn nhẫn của thế giới này. Reunion là hy vọng duy nhất của chúng tôi.”","“Tôi hiểu rồi… Các anh đã chịu khổ nhiều quá… Nếu Reunion thật sự có thể bảo vệ tất cả họ…”","“Đương nhiên.” Skullshatterer nhìn cô, và giọng hắn dịu xuống đến mức gần như là một lời hứa của trẻ con. “Giống như Reunion sẽ bảo vệ mọi người… tôi sẽ bảo vệ cô. Tôi sẽ không để ai làm hại cô nữa.”","“Skullshatterer…”","","Trên một vách đá nhìn xuống lối vào khu mỏ, Exusiai nằm sấp, ống nhòm áp vào mắt.","“Ồ, tìm thấy rồi—! Có vẻ chúng tổn thất khá nặng. May mà tôi chưa về trụ sở công ty… Không thì phải đi vòng cả quãng xa cho nhiệm vụ này rồi…”","“Thử dự đoán đường rút của chúng,” Texas nói. “Gửi mọi lộ trình khả dĩ cùng phương vị cho Amiya.”","“Xong ngay đây!”","“Hừ. Không thể cho Reunion thời gian tập hợp lại.”","“Hừmmm, để xem… chỗ này… như thế này… vậy là xong!”","“Xong chưa, Exusiai?”","“Cô cần gì? Ta làm thế nào đây?”","Texas đứng dậy, rút cả hai thanh kiếm.","“Khởi động chút đã. Bắt đầu với lính gác của chúng.”"],"bg":"bg_wild_m","cast":[["Skullshatterer","npc:char_1500_skulsr"],["Misha","npc:char_012_misa_1"],["Hoshiguma","op:char_136_hsguma"],["Ch'en","op:char_010_chen"],["Amiya","op:char_002_amiya"],["Texas","op:char_102_texas"],["Exusiai","op:char_103_angel"]]},{"c":"3-3","t":"Rối ren","p":["“Chết tiệt…! Chỉ có hai đứa thôi! Lao vào đi! Sợ cái gì chứ?!”","“Bọn ta mất hơn hai mươi người rồi! Hai con quỷ đó không phải người thường…!”","“Coi chừng bên phải!” Exusiai hét.","“Giúp một tay,” Texas nói.","“Ép ả lại! Tao sẽ kết liễu ả!”","“Tôi không có thời gian đối phó gã đang lao vào tôi.”","“Lần sau cô nợ tôi một chầu nhé?”","“Được, nhanh lên.”","“Ok!” Exusiai nhảy lên một tảng đá, khẩu súng xoay một vòng trong tay. “Này, anh Reunion ơi? Viên đạn này là quà của tôi tặng anh. Nhận lấy với lòng biết ơn nhé~”","“Đạn? Cái quái gì…” Tên Reunion gục xuống.","“Hehe, xử lý giúp cô rồi đó~”","“Cảm ơn nhiều.”","“M-mày là quái vật! Kiếm… kiếm của ả…!”","Texas nghiêng đầu. “—Thường thì tôi thích dùng hai thanh hơn.”","Trận đánh kết thúc trong vài nhịp thở.","“Vậy là hết rồi. Vừa nãy ta ăn ý quá còn gì!”","“…Có lẽ vậy.”","“Đứng lại!” Một toán Reunion lớn đang ào ra từ cửa mỏ.","“Quân chủ lực đến rồi,” Texas nói. “Có vẻ ta gây ồn hơi nhiều, thu hút sự chú ý của chúng.”","“Aaaaah!!! Các người…!! Sao có thể… Các người đã làm gì?!”","“A, đừng để bụng nhé,” Exusiai nói, nạp đạn. “Nhưng bọn tôi đang có hợp đồng mà, biết không? Làm nghề vận chuyển thì không có gì quan trọng hơn hoàn thành hợp đồng!”","“Bên trái cô.”","“Hả? Ơ— hả?” Exusiai cúi xuống đúng lúc một lưỡi kiếm sượt qua đầu. Texas đã đứng chắn trước cô. “C-cảm ơn.”","“Vậy giờ cô che bên phải cho tôi. Chạy thôi. Ta phải di chuyển.”","","“Exusiai, bọn mình đang đến gần vị trí của cậu!”","“Bọn tôi đã thu hút toàn bộ sự chú ý của địch. Phần còn lại trông vào các cô!”","“Hai người giữ an toàn nhé! Franka, chị đến nơi chưa?”","“Ổn cả,” Franka báo.","“Liskarm và các Defender khác đã vào vị trí,” Liskarm nói.","“Mọi người, xin hãy cảnh giác. Sniper địch có thể dùng địa hình để ẩn nấp. Chú ý vị trí của mình, ưu tiên nhắm vào sniper địch. Tiếp theo… chúng ta chuẩn bị tấn công.” Amiya ngừng lại. “…Nhưng đừng quá tay. Không được để mục tiêu gặp nguy hiểm.”","","Sâu trong khu mỏ, Skullshatterer đặt cây súng phóng lựu vào tay Misha.","“Nhìn này. Đây là cò súng. Nạp đạn như thế này… Nhắm vào kẻ địch, rồi bóp cò. Đạn sẽ bắn ra… Sau đó tập trung, nắm chặt tay cầm. Tập trung… và truyền Arts vào. Viên đạn sẽ phát nổ.”","“Tôi không biết mình có làm được không…”","“Tôi biết cô làm được. Chúng ta có nhiều điểm chung lắm. Tôi cảm nhận được điều đó trong cô. Cứ hình dung nó trong đầu… Đây, cầm lấy mảnh Originium này.”","Misha nắm lấy mảnh tinh thể. “Nnh…”","“Tập trung.”","Một quãng lặng. Rồi đôi mắt Misha mở to. “…Lòng bàn tay tôi… nóng lên.”","“Đúng rồi!” Skullshatterer bật dậy, giọng run lên vì một niềm vui gần như điên dại. “Tôi biết mà, tôi biết mà… Phải rồi, Misha, cô đúng là… Haha, ahaha… Cô đúng là…”","Hắn không nói hết câu. Một tên Reunion lao vào.","“…Phải đi thôi! Skullshatterer, nhanh lên! Không giữ được căn cứ nữa rồi!”","“Chuyện gì?!”","“Rhodes Island đang tấn công! Chúng đang tràn vào!”","Skullshatterer đứng im. Bàn tay hắn siết lại. “…Lũ khốn đó… Đừng hoảng. Tập hợp lại, chuẩn bị phản công!”","“Skullshatterer…” Misha níu tay hắn. “Tôi chắc… Rhodes Island sẽ…”","“Sẽ gì? Cô muốn tôi ngồi nói chuyện với Rhodes Island à?”","“Họ, họ chắc chắn đang cố giúp người Infected.”","“Chúng đã giết biết bao đồng chí của tôi… Cô thật sự muốn tôi nói chuyện với chúng sao? Tất cả đồng chí của tôi… họ cũng là người Infected! Rhodes Island, lũ tự xưng là cứu tinh của người Infected ấy… đã làm gì để giúp đồng chí của tôi? Chúng đã nói gì với cô mà khiến cô mù quáng đến vậy?!”","“Tôi không biết…”","“Xin lỗi…” Hắn hít một hơi. “Tôi quá xúc động. Nhưng có một điều chắc chắn… Sau ngần ấy thời gian, Reunion cuối cùng đã mang đến một tia hy vọng cho người Infected… Vậy mà Rhodes Island, dù là người Infected, lại chọn làm hại chúng tôi, tàn sát chúng tôi! Chúng không phải kẻ phản bội thì là gì?! Có gì để nói với lũ phản bội chứ?!”","“Vậy người Infected sinh ra là để mãi giết lẫn nhau sao?”","Câu hỏi khiến hắn khựng lại.","“…Vậy tôi phải làm gì đây… Chẳng lẽ cứ đứng nhìn đồng chí của mình chết?”","Misha không trả lời được.","“Đừng lo. Chúng tôi sẽ bảo vệ cô. Nhưng cô cũng phải tự bảo vệ mình… Đừng để bị kéo vào trận chiến. Xin hãy cẩn thận…”","“Hứa với tôi… anh sẽ quay lại…” Misha nắm chặt tay hắn. “Tôi vừa mới tìm lại được anh…”","“Ừ. Tôi sẽ quay lại đón cô. Rồi chúng ta sẽ cùng nhau về nhà…”","“…Ừm.”","","Ở lối hầm phía trước, W đang ngồi vắt chân trên một thùng thuốc nổ, gặm táo.","“Chào. Vậy là rốt cuộc anh cũng cần tôi giúp à?”","“Đúng vậy,” Skullshatterer nói. “Thật ra… tình hình hơi khác so với những gì Talulah nói. Kẻ địch mạnh hơn chúng ta tưởng. Vì thế… cô phải bảo vệ Misha.”","“Tôi đâu có nghĩa vụ phải làm vậy.”","“Cô có.”","“Thôi được, thôi được.” W vứt lõi táo. “Có điều, chỉ bảo vệ Misha thì chưa đủ đâu, nhỉ? Nếu anh thất bại, chúng vẫn sẽ đuổi kịp chúng ta thôi.”","“…Cô định làm gì?”","“Skullshatterer, anh không nhớ tôi đã nói gì trước đây sao?”","“…Tôi nhớ. Chúng ta có thể lật ngược thế cờ nếu hạ được mục tiêu đó.” Hắn ngừng lại. “Doctor…”","“Thấy chưa, anh có chú ý nghe mà. Chỉ cần hạ chỉ huy của chúng là được. Dễ đúng không?” W cười, giơ ngón tay làm hình khẩu súng. “Cái người trùm mũ lúc nào cũng đứng cạnh con bé thỏ ấy. Người chỉ huy các chiến dịch tác chiến của Rhodes Island. Nếu anh giết được người đó… Bùm! Thế là bộ não của chúng tiêu tùng. Mọi chuyện sau đó sẽ dễ ợt~”","Cô ta đứng dậy, phủi tay.","“Ta không còn nhiều quân, cũng sắp hết lựa chọn rồi. Gần lối vào mỏ có một chỗ rất hợp để phục kích. Caster của tôi sẽ yểm trợ cho anh… Anh biết phải làm gì rồi, đúng không? Tôi sẽ dùng quân của mình dụ chúng đến đó. Đừng bỏ lỡ cơ hội này nhé~”","“Tôi hiểu.” Skullshatterer quay đi. “…Chăm sóc Misha giúp tôi.”","“Chắc chắn rồi~”","Khi bóng hắn khuất sau khúc quanh, nụ cười trên môi W tắt dần.","“Hừm… Dù sao thì, chúc may mắn.”"],"bg":"bg_wild_a","cast":[["Skullshatterer","npc:char_1500_skulsr"],["W","npc:avg_npc_046"],["Exusiai","op:char_103_angel"],["Misha","npc:char_012_misa_1"],["Texas","op:char_102_texas"],["Amiya","op:char_002_amiya"]]},{"c":"3-4","t":"Rạn vỡ","p":["“Vậy, cô thấy Penguin Logistics thế nào, Amiya? Bọn tôi giỏi lắm phải không?”","“Vâng, các cậu tuyệt lắm!”","“W-woaaah!” Exusiai đỏ mặt. “Được một cô bé khen thấy ngại ghê!”","“Cẩn thận lời nói,” Texas nhắc. “Cô ấy là khách hàng.”","“Úi, xin lỗi nha!”","“Không sao đâu. Bọn mình mới là người phải cảm ơn các cậu!”","“Vậy là đã hội quân với Rhodes Island,” Texas nói. “Tiếp theo thế nào?”","“Có lẽ em cần L.G.D. quyết định trước rồi mới đóng góp ý kiến.”","“Vậy à… Tôi sẽ nhờ họ qua đây xem.”","Hoshiguma đến, đứng trên một mỏm đá nhìn xuống vùng hoang mạc trải dài trước cửa mỏ.","“Địa hình này… Reunion hẳn đã cố ý dụ ta đến đây.”","“Chỉ toàn cát với đá trên vùng hoang mạc này,” Franka nói. “Đủ mọi yếu tố cho một màn đấu súng kiểu phim ảnh. Chỉ còn thiếu mỗi kẻ địch thôi nhỉ?”","“Hoshiguma, ở lại đây yểm trợ Rhodes Island,” Ch’en nói.","“Hửm? Được thôi.”","“Tôi sẽ đưa L.G.D. đổi vị trí. Nếu cứ giằng co thế này, ta sẽ không kiểm soát được đường rút của Reunion.”","“Rõ. Cô cũng cẩn thận.”","Một cơn gió mạnh quét qua, cuốn theo cát bụi mù mịt.","“—Woaah, gió mạnh thật đấy,” Exusiai che mắt. “Ugh… Tầm nhìn kém quá, tôi gần như không thấy gì phía trước…”","“Đừng đi xa nữa,” Franka nói. “Reunion có thể chờ ta sa bẫy rồi mới tấn công lần nữa.”","“Không thể để điều đó xảy ra,” Liskarm nói.","“Thế này nhé, Amiya. Liskarm và tôi sẽ giành quyền kiểm soát các điểm cao quanh đây và trinh sát địch. Cho đến khi bọn tôi báo, cô cứ ở yên vị trí này. Chỉ cần đừng lao ra dù có vẻ trận đánh đang ác liệt, Amiya.”","“Em biết. Em sẽ tự phán đoán.”","“Doctor, người cũng để mắt đến cô bé nhé!”","“Bọn tôi sẽ giữ liên lạc,” Liskarm nói.","","“Phế tích trống không. Điểm cao hiện không có người phòng thủ,” Franka báo qua bộ đàm. “Lạ thật, Reunion không có chỉ huy à?”","“Chị Franka, có gì không ổn sao?”","“Chỗ này lẽ ra dễ thủ khó công. Không đời nào Reunion lại không bố trí phục kích…”","“Chết đi, lũ phản bội!”","“Chậc… Chẳng có chút danh dự nào.”","“…Chị Franka!! Đằng sau!!” Amiya hét vào bộ đàm. “Em thấy quân Reunion đang leo lên từ phế tích gần đó!”","Một tia sáng đỏ lóe lên. Tên Reunion gục xuống, ngơ ngác. “Khụ… Tôi không thấy… kiếm của ả?! Sao… có thể…”","“Haha! Mấy người tưởng phục kích tôi từ chỗ đó là được à? Không thấy mình đang xem thường tôi sao?”","“…Blacksteel…! Rút! Nhanh lên!”","“Tôi còn tưởng trên này phải có nhiều lính Reunion lắm. Đi nhón chân suốt từ nãy,” Franka lắc đầu. “Hóa ra chỉ là một lũ hèn nhát. Thất vọng ghê.”","“Cô thất vọng vì chuyện đó á?!” Liskarm kêu lên. “Quan trọng hơn, ta phải đuổi theo! Đừng để chúng dễ dàng thoát được! Amiya, cô nghĩ sao?”","“Em nghĩ… tốt nhất đừng mạo hiểm! Để Penguin Logistics ổn định tình hình trước rồi ta mới quyết định bước tiếp theo. Exusiai, cậu ưu tiên chiếm điểm cao được không?”","“Chắc chắn rồi! Tôi đang đến!”","“Tốt, tiếp tục gây áp lực lên địch. Đừng để Reunion phản công!”","Texas nheo mắt nhìn qua màn cát. “…Reunion đang cố tập hợp lại sau khi lùi một chút. Chúng… đang mang thứ gì đó ra!”","Từ lòng khu mỏ, một bóng hình khổng lồ bước ra. Cao gấp đôi người thường, toàn thân bọc trong lớp giáp nặng nề, mỗi bước chân làm mặt đất rung chuyển.","“…Cẩn thận,” Amiya nói khẽ. “Thứ đó… không phải côn đồ bình thường! Em không ngờ Reunion lại hợp tác với…”","“Lẽ nào đó là…” Franka nói.","“Hợp tác với ai?” Liskarm hỏi. Rồi cô ta nhìn kỹ hơn. “…Cô nói đúng, tên lính Reunion này trông khác hẳn…”","“Lẽ nào…” Amiya hạ giọng. “(Liskarm, ta đang hợp tác với L.G.D.… Có lẽ giờ không phải lúc bàn chuyện nhạy cảm!)”","“(À, hiểu rồi.)”","“(Lần sau em sẽ nói giả thuyết của em!)”","Texas ngáp dài.","“Mọi người, xin hãy chuẩn bị!” Amiya giơ tay. “Đây… có thể là một trận đánh rất khó khăn!”","","“…Cái quái gì vậy…” Liskarm thở dốc, nhìn cái xác khổng lồ gục giữa cát. “Ngần ấy công sức, chỉ cho một toán Reunion…”","“Và một gã to xác,” Franka nói, ngồi phịch xuống đá. “Đó mới là phần đỉnh điểm. Đối phó với gã thôi mà tôi kiệt sức luôn!”","“Không thể nào,” Hoshiguma nói, nhìn quanh. “Sao ngần ấy người Infected lại biến mất nhanh vậy? Gã khổng lồ đó chỉ là nghi binh thôi sao?”","“Reunion đã sơ tán hoàn toàn khu vực này trong thời gian ngắn như vậy sao?” Amiya lẩm bẩm. “Không… Cô Ch’en lẽ ra đã chặn đường rút của chúng rồi…”","“Tôi không thấy điểm mốc đã định,” Franka nói, đứng dậy, mắt quét khắp vùng hoang mạc. “Có gì đó… không đúng. Cỏ dại, phế tích, đụn cát… Toàn là những chỗ có thể phục kích… Nhưng tôi không thấy gì cả. Không tiếng bước chân, không tiếng quần áo cọ vào cây cỏ, không mùi thuốc nổ… Tôi không hiểu chuyện gì đang xảy ra! Penguin Logistics, tỉnh dậy làm việc đi! Chuyện này không ổn chút nào!”","“Suỵt!” Hoshiguma giơ tay. “Tiếng gì vậy…?”","Exusiai nằm áp tai xuống đất. Một giây. Hai giây.","“…Hả? Từ… dưới lòng đất?!” Cô bật dậy. “Amiya! Tiếng động phát ra từ dưới lòng đất!”","Mặt đất dưới chân Doctor nứt toác.","“Doctor!! Nằm xuống, ngay!!!”","Hoshiguma lao tới, chiếc khiên khổng lồ cắm phập xuống cát. Từ khe nứt, Skullshatterer bật lên, nòng súng phóng lựu chĩa thẳng vào nơi Doctor vừa đứng. Viên đạn nổ tung trên mặt khiên.","“Lũ này… thật sự không từ thủ đoạn nào!” Hoshiguma gầm lên.","“…?!” Skullshatterer lùi lại. “Sao… cô chặn được?”","“‘Hannya’ của tôi không phải thứ mày xuyên qua được.”","“Để xem… đã…” Hắn nắm chặt cây trượng. Lớp mặt nạ của hắn bắt đầu ánh lên màu đỏ.","“…!” Franka hét lên. “Nhiệt độ đang tăng vọt!! Hắn định cho nổ cả cây trượng sao? Doctor! Chạy đi! Ở khoảng cách đó, người sẽ—”","@cg:bg_1_lastattack","“Người sẽ—”","“Kết thúc rồi!” Skullshatterer lao tới.","@cg:bg_1_reflect","“Không… Khôôông—!” Amiya hét lên. “Không được—— Ta sẽ không để ngươi làm hại Doctor——!!”","@cg:bg_1_underattack","@cg:bg_1_lastbreath","Một luồng sáng đen bùng lên.","Rồi tất cả im lặng.","Khi cát bụi lắng xuống, Skullshatterer đang quỳ giữa một hố sâu, máu chảy ra từ dưới lớp mặt nạ đã nứt. Amiya đứng trước mặt hắn, bàn tay vẫn còn giơ lên, những sợi sáng đen còn quấn quanh ngón tay như khói.","“Khụ khụ…” Hắn ngẩng lên. “Ngươi… mạnh thật… Nhưng… nhìn ngươi xem… Ngươi mạnh như vậy… Khụ… Đau quá… Dù có sức mạnh như thế… ngươi vẫn… máu lạnh… nhìn đồng loại Infected của mình… Ta không thể… tha thứ… Ta không thể tha thứ cho loại người như ngươi…”","Hắn đổ gục xuống cát.","Ở rất xa, trên một mỏm đá mà không ai để ý, có một cô gái tóc trắng đang đứng, hai tay bịt chặt miệng.","“…Không… Đừng…!”"],"bg":"bg_wild_a","cast":[["Franka","op:char_106_franka"],["Amiya","op:char_002_amiya"],["Hoshiguma","op:char_136_hsguma"],["Skullshatterer","npc:char_1500_skulsr"],["Liskarm","op:char_107_liskam"],["Exusiai","op:char_103_angel"],["Texas","op:char_102_texas"],["Ch'en","op:char_010_chen"]]},{"c":"3-5","t":"Cuộc gọi","p":["“Doctor…” Amiya đứng im giữa hố cát, giọng nhỏ như sợi chỉ. “Em… Em không cố ý… Em…”","“Sương mù đã tan,” Hoshiguma bước tới. “Ta nhận được liên lạc từ L.G.D. Họ phát hiện thêm động tĩnh của Reunion. Hiện đang truy đuổi một kẻ địch, được mô tả là nữ, tóc trắng—” Cô ta khựng lại khi thấy gương mặt Amiya. “Amiya, Ch’en nói cô ấy muốn cô… …Trông cô không ổn lắm.”","“Để tôi lo,” Doctor nói.","Hoshiguma nhìn Doctor một lúc, rồi gật đầu. “Được… Tôi giao cô bé cho người, Doctor. Tốt nhất là đi trong vòng năm phút.”","Khi Hoshiguma đi khỏi, Amiya vẫn không ngẩng đầu lên.","“Doctor…”","“Amiya, không phải lỗi của em.”","“Hả…? Em…” Cô bé nhìn lên, rồi lại cúi xuống. “Doctor… không phải em sợ đâu… Đương nhiên là em sợ… sợ mất Doctor thêm lần nữa… Cho nên…” Cô bé nắm chặt hai tay. “Em chỉ… không cố ý… Em… Em không biết nữa…”","“Em không biết có nên nói điều này không, nhưng… nó không nên… chỉ biết làm tổn thương người khác. Em không muốn Doctor nhìn thấy em như thế này, ở khoảng cách gần như vậy…” Giọng cô bé vỡ ra. “…Em đã lấy đi mạng sống của một người.”","“Em không hối hận. Không, ý em là… Em sẽ luôn dùng sức mạnh của mình vì Doctor. Dù người đó mang gánh nặng gì, em không hối hận vì đã giết anh ta. Nhưng… lẽ ra phải có cách tốt hơn. Anh ta chết vì… em không tìm ra được cách đó. Và điều đó… đang gặm nhấm em từ bên trong.”","Cô bé nhìn xuống đôi bàn tay mình, những ngón tay vẫn còn run.","“Em không muốn… Em không muốn Doctor thấy mặt này của em. Dù em luôn nói về việc giải thoát người Infected khỏi đau khổ… Vậy mà vào lúc quan trọng nhất, em lại phải tự thuyết phục mình, hết lần này đến lần khác, rằng lấy đi mạng sống của một người Infected khác là chính đáng.” Cô bé cười, một nụ cười méo mó. “Em thật đáng thương.”","“Amiya, ít nhất em đã bảo vệ tôi.”","Amiya im lặng rất lâu.","“…Đó là bổn phận của em,” cô bé nói cuối cùng. “Em hiểu rồi. Em chưa bao giờ tin rằng mọi thứ đều đã được định đoạt bởi số phận. Nhưng dù có chuyện gì xảy ra… dù em có trở thành thế nào… Em sẽ luôn bảo vệ Doctor.”","Cô bé ngẩng lên, đôi mắt xanh lục đã khô.","“Em hứa.”","","Ở bìa khu mỏ, những thành viên Reunion còn sót lại đang tập hợp, chuẩn bị rút lui. Rồi một người dừng lại.","“Không! Các anh đi trước đi! Tôi phải… Tôi phải đưa Skullshatterer về!”","“Anh điên rồi à? Thế là tự sát… Nếu anh đi, chúng ta cùng đi!”","“Được!”","“Tôi không thể để anh ấy ở lại ngoài đó một mình…”","“Vậy thì đi thôi!”","Từ chỗ đứng của L.G.D., Hoshiguma nhìn thấy cảnh tượng không thể hiểu nổi: đám Reunion vừa rút lui bỗng quay ngược lại, lao thẳng vào trận địa.","“Tại sao… Tại sao Reunion… lại quay lại? Chúng đang làm gì vậy…?!”","“Chị Hoshiguma! Lùi lại!” Amiya hét.","“L.G.D., đừng hoảng! Chuẩn bị đón địch!”","“Yểm hộ! Yểm hộ cho tôi!”","“Ả đàn bà đó… Không thể nào… Không qua được khiên của ả!”","“Nhanh! Vòng qua, trước khi chúng kịp phản ứng… Ta phải đến chỗ Skullshatterer… và đưa anh ấy… Đưa anh ấy về nhà!!”","“Rhodes Island! Chúng đổi mục tiêu rồi, cẩn thận!”","“Không xong!” Amiya hét. “Chị Hoshiguma! Bên phải chị!”","“Hả…?” Một vụ nổ ập vào sườn Hoshiguma. Chiếc khiên kịp xoay lại, nhưng lực nổ đẩy lùi cô ta mấy bước.","“Hehe, chặn được à? Hơi thú vị đấy…” W đáp xuống một tảng đá, tung hứng hai khối thuốc nổ.","“Nổ? Lại phục kích nữa sao?!”","“Không chỉ vậy đâu~ Tôi muốn cô ngoan ngoãn đứng yên đây. Đừng nghĩ đến chuyện quay lại, được không?”","“Chậc… Mày từ đâu chui ra vậy?!” Thêm một loạt nổ. “Lại thuốc nổ nữa…! Amiya! Tôi đang bị Reunion oanh tạc! Quân của chúng đang tiến về phía các cô!”","“Hừm, cái khiên của cô cứng thật đấy.” W nhún vai. “Có vẻ tôi tự chuốc lấy chút rắc rối rồi… Thôi kệ, coi như giúp Reunion một việc nhỏ. Cho tôi xem gì đó thú vị đi. Đừng làm tôi thất vọng nhé~”","“Đó là ‘W’ mà ta gặp ở Chernobog!” Amiya nói. “Lẽ nào cô ta… đã cắt đuôi được cô Ch’en?! Cẩn thận đợt tấn công của địch! Phải giúp chị Hoshiguma ngay! Còn nhiều kẻ địch đang ẩn nấp gần đây! Không làm chúng lộ diện thì ta không giành được ưu thế! Doctor! Xin hãy chỉ huy các đội, cầm chân đợt tấn công của địch!”","","“Lùi lại! Mọi người, tập hợp!” Amiya hô. “Để chúng đi! Cứ thế này địch sẽ cắt rời các đội của ta! Không thể để chuyện đó xảy ra, phòng khi có thêm viện binh… Quân Reunion này… không nhắm vào chúng ta! Ưu tiên hàng đầu là giữ an toàn cho operator! Sniper, ngừng bắn quân Reunion đang chạy trốn! Tập trung giúp chị Hoshiguma trước!”","Những bóng Reunion lướt qua họ, không thèm nhìn, lao thẳng về phía hố cát nơi Skullshatterer nằm. Họ nhấc thân hình to lớn ấy lên vai, rồi chạy ngược vào lòng khu mỏ.","“Phiền chết đi được!” Hoshiguma gầm lên, vung khiên chắn một loạt nổ nữa.","“Không tệ, không tệ. Cô thật sự đỡ được hết đòn của tôi~ Nhưng còn chịu được bao lâu nữa?”","“Còn tùy mày sống được bao lâu!” Hoshiguma hét lên. “—Ch’en! Nhanh lên!”","“Bao vây ả đàn bà đó!”","Đội L.G.D. ập đến từ ba phía, mũi súng và lưỡi kiếm chĩa vào W.","“Ồ, L.G.D. đến chơi à?”","“Hạ vũ khí xuống!”","“Lại gặp nhau rồi, quý cô~”","“Lần này mày không ăn nói mà thoát được đâu,” Ch’en nói, giọng lạnh như băng. “Những gì mày đã làm với Lungmen… tao sẽ trả lại mày gấp đôi.”","“Ôi chao, đáng sợ quá~ Nhưng hôm nay tôi không đến để chơi với cô.” W quay sang. “Amiya, bắt lấy~”","Một vật nhỏ bay vèo tới. Amiya đỡ lấy theo phản xạ. “Em? Đây là… một chiếc điện thoại?”","“Đúng rồi đó. Có người muốn nói chuyện với cô~”","“…?!”","“Dù sao, nhiệm vụ của tôi thế là xong. À, suýt quên, tôi cũng có quà cho cô đấy, quý cô. Hẹn gặp lại~”","“Cẩn thận!”","“…Bom tầm gần…?! Không, là lựu đạn choáng!” Amiya nhắm mắt lại. “Đừng để cô ta lừa…”","Một tia sáng trắng nổ tung. Khi mắt mọi người hồi lại, W đã biến mất.","“…Muộn rồi,” Ch’en nói. “Ả đi mất rồi. Chạy nhanh thật. Chỉ cần một khoảnh khắc phân tâm là ả lách qua được vòng vây. Mà cô nên cẩn thận với thứ đang cầm. Nếu lại là bom…”","“Cái này… có vẻ chỉ là điện thoại bình thường…” Amiya nhìn màn hình. Cuộc gọi đang kết nối. Cô bé áp nó lên tai. “Ngoại trừ… lẽ nào…”","“…A lô?”","@cg:bg_1_call","","“Có phải là…” Một giọng nói quen thuộc, nhưng khàn đặc, như đã khóc rất lâu. “Amiya…?”","“Chị Misha! Chị ở đâu?! Em…”","“Amiya…”","Đằng sau giọng Misha là những âm thanh khác. Tiếng người la hét, tiếng khóc, tiếng bước chân hỗn loạn trên nền đá.","“…Ưu tiên… cứu người bị thương nặng!! Cần truyền máu ở đây!! Nhanh lên!!”","“…Chết tiệt… Tại sao… Chúng ta đều là người Infected mà… Rhodes Island… tại sao họ lại làm thế với chúng ta…?!”","“…Ngay từ đầu chúng ta đã bị bỏ rơi rồi!! Không còn lối thoát… không còn gì cả…!”","“Đừng chết! Đừng bỏ em!! Chúng ta đã hứa… Chúng ta đã hứa sẽ cùng nhau về nhà…!”","“…Anh ơi… xin đừng…”","“Em có nghe thấy giọng của họ không…?” Misha hỏi.","Amiya đứng chết lặng. “…Người Infected của… Reunion?”","“Tôi nhớ ra rồi. Không, tôi chưa bao giờ quên. Tôi chỉ… không muốn nhớ…” Giọng Misha đều đều, như đang đọc một bản án. “Đúng vậy. Chính Reunion đã phá hủy nhà tôi. Cả cha tôi nữa… Nhưng… chúng tôi tự chuốc lấy.”","“Năm ấy, tôi nhìn em trai tôi bị lôi đi ngay trước mắt… Em ấy gọi tôi, khóc gọi tên tôi, nhưng tôi quay mặt đi… và trốn vào phòng.”","“Khi em ấy tìm thấy tôi lần nữa… Em ấy đã hy sinh biết bao nhiêu thứ. Dù em ấy vẫn yêu thương tôi, tôi lại sợ, và tôi bỏ chạy… Nhưng giờ tôi đã hiểu. Mọi điều em ấy làm… chỉ là để những kẻ áp bức nếm thử nỗi đau mà người Infected phải chịu mỗi ngày. Và giờ, tôi cũng là một trong số họ.”","“…Đã đến lúc tôi chuộc lại tội lỗi của mình.”","“Chị Misha, đừng hấp tấp!” Amiya hét lên. “Dù trước kia chị đã đối xử với người Infected thế nào, chị vẫn luôn có thể thay đổi—”","“Vô ích thôi. Tôi thay đổi được gì chứ? Vì tôi… là một trong những kẻ đã nhắm mắt làm ngơ… Sau khi trở thành người Infected, cuối cùng tôi… mới nhìn thấy rõ. Cách người bình thường đối xử với người Infected… cũng là cách người Infected sẽ đối xử với người bình thường. Vì họ đáng bị như thế.”","“Không…”","“Tất cả những chuyện này… chẳng qua là cỏ dại của cái ác mọc lên từ những hạt giống tàn nhẫn mà tôi đã gieo… Sự giày vò này là quả báo của tôi.” Giọng Misha bỗng vỡ ra, run rẩy. “Nhưng tại sao… Tại sao? Tại sao chuyện đó lại xảy ra với em ấy, dù em ấy chẳng làm gì sai?! Tội duy nhất của em ấy là đột nhiên bị nhiễm bệnh… Em ấy còn nhỏ lắm… Em ấy mới vừa bắt đầu nhờ tôi giúp làm bài tập về nhà! Giá mà tôi… Giá mà khi ấy tôi đã bảo vệ em ấy…”","“Chị Misha! Xin chị bình tĩnh lại! Chị không làm hại người vô tội nào! Không có gì là lỗi của chị cả!”","“Ngay từ đầu, ai là người vô tội?!”","Amiya không trả lời được.","“Thứ duy nhất sai… là cái nhãn người ta dán lên người Infected… Nếu đây là vòng tròn báo thù lẫn nhau… thì nói tôi nghe, ai là kẻ đã khởi động bi kịch này…?! Nếu Ursus chưa bao giờ đối xử với người Infected như quái vật… thì ai có lý do gì để căm ghét Ursus đến thế?! Ai đã định đoạt rằng người Infected phải chịu khổ như vậy?!”","“Chị Misha…” Amiya nhắm mắt lại. “Skullshatterer đã chết rồi. Chị có thể trở về với bọn em. Em hứa, bọn em sẽ…”","Đầu dây bên kia im lặng rất lâu.","“…Amiya… tôi đã tìm thấy câu trả lời rồi… Tôi là người Infected. Tôi đứng về phía người Infected.”","“Đừng…”","“Đúng vậy, Amiya. Em cũng là người Infected… Vậy nên em hẳn phải hiểu.”","“Đúng vậy. Em cũng giống chị… giống như mọi người ở Rhodes Island. Bọn em đều hiểu cảm giác của chị…” Amiya nắm chặt chiếc điện thoại. “Nhưng chị Misha, dù chị chấp nhận thân phận của mình, điều đó sẽ không thay đổi con người chị! Xin chị chờ em! Em sẽ đến tìm chị!”","“Đừng đến.”","“…Chị Misha! Chị ở đâu—”","“Em nói đúng, Amiya. Em hoàn toàn đúng… Tôi chỉ đang cảm thấy tội lỗi. Tội lỗi… vì tôi quá yếu đuối. Nhưng tôi đã quyết định rồi. Dù chỉ là một bước… thì đó cũng là bước tôi phải đi.” Giọng Misha nhỏ dần. “Tôi xin lỗi, Amiya. Tôi xin lỗi nhiều lắm… Là người Infected… nghĩa là một phần của Reunion. Chúng tôi, rốt cuộc, chỉ có vậy thôi…”","“Tạm biệt…”","“Chị Misha? Chị Misha?! Chị Misha!!”","Chỉ còn tiếng tút kéo dài."],"bg":"bg_wild_a","cast":[["Amiya","op:char_002_amiya"],["Misha","npc:char_012_misa_1"],["Hoshiguma","op:char_136_hsguma"],["W","npc:avg_npc_046"],["Ch'en","op:char_010_chen"]]},{"c":"3-6","t":"Quyết định","p":["Amiya đứng đó, chiếc điện thoại vẫn áp trên tai, rất lâu sau khi cuộc gọi đã kết thúc.","“Mất tập trung trên chiến trường là nguy hiểm,” Ch’en nói.","“Em xin lỗi… Em chỉ… không hiểu nổi…”","“Reunion đã cố thủ trong một khu mỏ bỏ hoang. Ả W cũng đã chạy vào trong.” Ch’en nhìn cô bé một lúc. “…Tôi có thể cho cô chút không gian nếu cô cần ở một mình. Nhưng L.G.D. không có thời gian để lãng phí. Hoshiguma, tập hợp mọi người.”","<i>Chị Misha…</i>","Amiya hít một hơi thật sâu, rồi ngẩng lên. “Cô Ch’en—em có một mối lo.”","“Mối lo?”","“W là bậc thầy chất nổ. Rất có khả năng cô ta đã gài bẫy trên chiến trường. Em lo… ta sẽ chịu thương vong nặng nề nếu đối đầu trực diện. Em đề nghị Rhodes Island lẻn vào khu mỏ trong khi lực lượng của cô lập vòng vây. Bọn em sẽ đẩy quân Reunion ra, cô có thể bắt giữ chúng ngay… Còn những kẻ không chịu đầu hàng, bọn em sẽ xử lý theo cách của mình.”","“Cô tự tin đến đâu khi đối mặt với ả đàn bà đó?”","“Em không chắc… Nhưng bọn em có thể gánh rủi ro đó. Bọn em đã đánh với cô ta nhiều lần rồi. Ít nhất bọn em hiểu phần nào lối đánh của cô ta. Có những rủi ro… mà L.G.D. không thể gánh nổi.”","“Chúng ta cũng không thể đánh mất mục tiêu nhiệm vụ.”","Amiya im lặng.","“PC94172, đưa quân bao vây khu mỏ!” Ch’en ra lệnh. “Hoshiguma, chọn vài người đi cùng cô. Mỗi chúng ta dẫn một đội, tiến vào cùng Rhodes Island. Hoshiguma, cô và Rhodes Island tách ra, kẹp chúng từ hai phía. Phá hủy căn cứ tác chiến, đánh tan phòng tuyến của chúng. Tôi lo các hỏa điểm. Vì Lungmen, chúng ta phải…” Cô ta ngừng lại một nhịp rất ngắn. “…đưa Misha về.”","“…Rõ. Em sẽ tập hợp các operator.”","“Ch’en, có một nhóm nhỏ Reunion đang ra ngoài theo rìa khu mỏ,” Hoshiguma báo. “Chúng di chuyển khá nhanh. Tôi đi trước, không thì có thể mất dấu.”","“Nhanh lên. Đừng để chúng thoát.”","“A, chị Hoshiguma, xin chờ một chút. Khi chúng phục kích ta lúc nãy, chúng giấu vài Caster trong đội hình. Em đề nghị chị mang theo hai operator của bọn em, Franka và Liskarm. Họ có nhiều kinh nghiệm đánh Caster.”","“Không vấn đề.”","“Được rồi, bắt đầu thôi nhỉ?” Franka vươn vai.","“Còn cô thì sao, Amiya?” Liskarm hỏi. “Bác sĩ Kal’tsit dặn chúng tôi phải…”","“Penguin Logistics yểm trợ em, em sẽ ổn thôi.”","“Nghe được đấy,” Hoshiguma gật đầu.","“Tôi không thể nhấn mạnh đủ,” Ch’en nói, “nhưng đừng quá cứng đầu. Lùi lại nếu tình hình quá khó khăn. Amiya?”","“Em biết.” Amiya nhìn về phía cửa mỏ tối om. “Chúng ta không còn nhiều thời gian. Lần này không giống Chernobog… Lần này, đến lượt chúng ta ngăn chặn Reunion!”","","Sâu trong lòng mỏ, những người Reunion vây quanh một thân hình nằm bất động.","“Không… Không thể nào! Không thể nào…! S-sao lại như thế này?! Skullshatterer, Skullshatterer!”","“K-không được để Misha thấy cảnh này…”","“Ai biết sơ cứu không? Mau đến đây!”","“Chết tiệt, sao Mephisto lại từ chối đến? Hắn đang làm gì vậy?! Cứ nói về cái ‘kế hoạch khác’ nào đó… Thế là sao chứ?! Nếu hắn ở đây, ta đã cứu được biết bao người rồi!”","“Đừng trông chờ vào gã đó,” W nói, tựa lưng vào vách hầm. “Hắn chẳng quan tâm đến đồng đội đâu. Đừng tự trách mình vì những chuyện ngoài tầm kiểm soát.”","“Cảm ơn đã yểm trợ bọn tôi, W… Ít ra, bọn tôi đã đưa được anh ấy về.”","“Nếu muốn cảm ơn tôi thì làm bằng hành động ấy.”","“Đương nhiên. Bọn tôi sẽ yểm trợ cô rút lui… Nhưng tôi có một yêu cầu— Xin hứa sẽ chăm sóc Misha.”","“Đương nhiên rồi. Dù sao thì…”","“Tôi vẫn còn có ích với các người, đúng không?”","Misha bước ra từ bóng tối. Gương mặt cô không còn nước mắt. Chỉ có một sự bình thản đáng sợ.","“Bọn tôi…”","“Xin để tôi ở một mình với Skullshatterer một lúc. Tôi sẽ… chăm sóc anh ấy.”","“Nhưng…” Người Reunion nhìn cô, rồi nhìn W. “…Được thôi. W, đó là lời hứa. Một lời hứa cô phải giữ.”","“Biết rồi, biết rồi~”","Những người Reunion lặng lẽ rời đi. Chỉ còn lại Misha, W, và thân hình bất động trên nền đá.","“Tôi vừa nói rồi đấy—” Misha nói, không nhìn W. “Để tôi ở một mình với anh ấy.”","“Nhưng cô nên đi đi,” W nói. “Lungmen và Rhodes Island sẽ xông vào đây bất cứ lúc nào. Chắc người ở đây cũng sẽ chết hết. Ôi chao, thật là khó xử. Misha, vì cô mà thêm biết bao người phải chết… Đáng thương thật.”","“Cô thật sự khiến tôi phát bực đấy, W. Cô sẽ không lấy được gì từ tôi đâu.”","“Woaahh, đáng sợ ghê~” W cười. “Cô biết không, con bé thỏ đó có vẻ rất quan tâm đến cô~ Nhưng cô Ch’en kia thì khác. Cô ta sẽ không nương tay với ai đâu. Có thể cô ta sẽ tha mạng cho cô, vì cô ta cần cô… Nhưng cô đã thấy đủ nhiều ở Ursus để biết chuyện gì xảy ra sau đó, đúng không?”","Misha im lặng.","“Nếu đi với tôi bây giờ thì vẫn chưa muộn. Có điều… cô vẫn sẽ phải nhìn những người bạn Reunion của chúng ta hy sinh… Tôi đoán đó là số phận của họ thôi. Những sinh vật đáng thương.” W ngừng lại. “À, phải rồi. Dù cô đã thấy hết những gì xảy ra… Cô biết đấy, ahh, nói sao nhỉ… Tôi thật sự không còn sức kéo Skullshatterer về Chernobog đâu…”","“Im đi!”","“Tôi chỉ nói sự thật thôi. Dù sao, tình hình ở đây cũng vô vọng rồi~ Khi nào tỉnh táo lại thì báo tôi nhé, được không?”","W bỏ đi. Misha quỳ xuống bên cạnh người em trai, chạm tay vào lớp mặt nạ nứt vỡ.","“Không… Tôi thề sẽ… đưa Skullshatterer sống lại.”","Cô nhìn những người Infected đang băng bó cho nhau ở cuối đường hầm, những gương mặt trẻ măng lấm lem bụi than, những đôi tay run rẩy siết chặt vũ khí.","“Skullshatterer chưa chết… Skullshatterer không thể chết. Nếu anh ấy ở đây, anh ấy sẽ bảo vệ chúng ta… tất cả chúng ta. Tôi biết… đây là điều anh ấy sẽ làm.”","“Mọi người đều giống tôi. Chúng tôi đều là người Infected. Tôi cũng là… một trong số họ. Chúng tôi không còn nơi nào để đi… Mọi người… cần được bảo vệ.”","Cô cởi chiếc mặt nạ khỏi gương mặt em trai. Nó vẫn còn ấm.","“Đây…”","“…là di sản của Skullshatterer.”"],"bg":"bg_wild_a","cast":[["Amiya","op:char_002_amiya"],["W","npc:avg_npc_046"],["Misha","npc:char_012_misa_1"],["Ch'en","op:char_010_chen"],["Hoshiguma","op:char_136_hsguma"]]},{"c":"3-7","t":"Gầm thét","p":["“Đã phá được tuyến phòng thủ thứ nhất!” Franka hét.","“Caster đâu hết rồi?! Chỉ có một kẻ địch ở mũi nhọn thôi mà… Sao chúng cứ đứng nhìn ả xé xác chúng ta?! Nhanh, nhanh! Hạ ả đi!”","“Franka! Cô ra khỏi tầm rồi! Tôi không… yểm trợ cô từ đây được!”","“Trông tôi liều lĩnh thế à?”","“Coi chừng hướng bốn giờ!”","“Liskarm, đến lượt cô ra mắt rồi! Ngoan nào, chặn mấy đòn tầm xa của địch giúp tôi nhé?”","“Chậc…”","“Nhanh! Nhanh lên! Tập trung hạ đứa cầm kiếm trước!” Một loạt tên trút xuống. “Trúng chưa—? …Hả?”","Hoshiguma đứng chắn trước Franka, chiếc khiên hứng trọn cơn mưa tên như hứng mưa phùn.","“Đừng hòng. Thế mà gọi là tấn công à, hay các người chỉ đang ném que với đá?”","“Woah!! Đ-đứa này từ đâu ra vậy?!”","“Nợ chị một lần nhé, đội trưởng!” Franka cười.","“Không có gì. Nhưng Franka, nhiệm vụ của cô là đánh nghi binh. Vậy mà cô đánh thẳng đến tận đây. Giờ trên đầu cô treo một tấm bia to tướng. Không sao à?”","“Không sao hết, dù gì tôi cũng có một cộng sự đáng tin mà!”","“Ugh… Gahh…” Liskarm chạy tới, thở không ra hơi. “Franka! Cô xông lên xa quá rồi!”","“Thấy chưa? Cô ấy đuổi kịp rồi.”","“Tôi không quen mấy chuyện này…! Sao cô lại bắt tôi lao đầu vào địch thế? Tôi không hiểu!”","“…Hả?” Hoshiguma nhìn hai người, ngơ ngác.","“Chết tiệt… L.G.D. và Rhodes Island đang hợp tác! Không thể giữ chỗ này được… Không thể do dự nữa. Được ăn cả ngã về không. Mọi người, xông lêêên!”","“Địch đang lao thẳng vào ta!” Liskarm hét.","“Chếêt đi!”","“Nếu các người định chống cự, các người không cho tôi lựa chọn nào khác,” Hoshiguma nói. “Đừng để bụng.”","Một cú đập khiên. Tên Reunion bay ngược ra sau, đập vào vách đá.","“Chị… mạnh thật đấy,” Liskarm nói.","“Gan chúng to thật khi dám tấn công như thế… Tôi thấy tội cho hắn. Chúng nên xin lỗi tất cả những người đã ngã xuống dưới tay chúng.”","“Thanh tra!” Amiya chạy tới.","“Mừng là mọi người đều ổn.”","“Ta đã đánh sập cánh sườn của chúng! Bước tiếp theo là tổng tấn công.”","“Được thôi.”","“Mọi chuyện có vẻ suôn sẻ,” Texas nói.","“Có lẽ sẽ không kéo dài lâu đâu. Địch đã đặt nhiều chướng ngại, và chúng ẩn nấp rất giỏi. Amiya, chuẩn bị cho một trận khó. Doctor, nhớ trinh sát kỹ và bảo vệ các đội!”","“Đương nhiên!” Amiya quay về phía các operator. “Mọi người, cùng đi cứu chị Misha nào!”","","“Đừng để chúng qua!! W chắc đã thoát cùng Misha rồi…! Không thể để—”","“Tránh đường! Muốn chết à?!” Hoshiguma càn qua như một cỗ xe tăng.","“Ô-ồ…” Franka nhìn theo. “Lối đánh dã man đó làm tôi nhớ đến một người ở Rhodes Island. Họ có nhiều điểm chung ghê, nhỉ?”","“Franka, đừng đứng đó! Làm gì đi chứ!”","“Rồi, rồi.”","“Hah, có vẻ mọi lời đồn về Thanh tra của Lungmen đều là thật…” Exusiai huýt sáo.","“Tập trung,” Texas nói.","“Này, tôi đâu chỉ…” Pằng! “…ngồi nhìn người khác đâu!” Một Caster Reunion gục xuống trên tầng hai. “Thấy mấy toán địch trên tầng hai không? Tôi phát hiện trước đấy!”","“Giỏi lắm.”","“Hehe.”","“…Đi thôi. Không thể để khách hàng tự xử lý một mình.”","“Chị Franka, tìm thấy chị Misha chưa?” Amiya hỏi.","“Không thấy đâu cả. W có lẽ… đã đưa cô ấy đi rồi… Chậc… Cô không thấy là hơi nhanh quá sao…”","Một tiếng nổ dội lại từ sâu trong hầm.","“…? Gì vậy… nổ à? Chị Franka, tập hợp đội. Phải hỗ trợ L.G.D.!”","“Rhodes Island, cẩn thận!” Một nhân viên L.G.D. lảo đảo chạy ra. “K-kẻ địch này… Họ…”","“Chuyện gì vậy…? Nói đi!”","@cg:bg_1_back","“Kẻ địch…”","Amiya nhìn qua vai anh ta. Và cô bé đứng sững.","“…Cái gì?! Đó là…? S-sao có thể…?!”","Ch’en cũng đã thấy. “…Cái gì? Chậc… Đây là trò lừa gì vậy?”","Giữa đường hầm, trong ánh đèn dầu chập chờn, một bóng người mang mặt nạ Skullshatterer đang đứng. Cây súng phóng lựu trong tay. Áo choàng Reunion phủ kín vai. Nhỏ hơn một chút. Gầy hơn một chút. Nhưng chiếc mặt nạ thì không lẫn vào đâu được.","“Một phép màu! Một phép màu!” Quân Reunion đồng loạt reo hò. “Chúng ta được ban phép màu!! Là anh sao…? Thật là anh rồi!! …Anh ấy không sao!! A-anh ấy khỏe lại rồi! Skullshatterer vẫn còn sống!! Skullshatterer! Thật là anh rồi!! Hoan hô!!”","Amiya không nghe thấy gì nữa.","“…Lẽ nào…” cô bé thì thầm. “…Không…”","“Đừng đứng đó! Tìm chỗ nấp!” Ch’en quát. Cô ta nhìn đám Reunion đang phát cuồng. “Sĩ khí của Reunion tăng vọt từ khi thủ lĩnh của chúng xuất hiện trở lại. Giờ trấn áp chúng sẽ khó hơn.”","“…Skullshatterer, tình hình nguy cấp lắm,” một người Reunion nói với bóng đeo mặt nạ. “Nhưng ít ra… anh đã trở về với chúng tôi. Tôi nhẹ nhõm quá… mừng quá… Misha chắc cũng đã thoát ra ngoài rồi. Giờ chúng ta có thể chiến đấu mà không còn gì hối tiếc!”","Bóng người đeo mặt nạ im lặng một lúc.","“…Tôi sẽ ở lại đây cầm chân chúng,” giọng nói sau lớp mặt nạ vang lên, khàn đặc, như cố tình hạ thấp. “Các anh đi đi. Tôi sẽ bảo vệ tất cả mọi người…”","“Anh nói gì vậy, Skullshatterer… Chẳng phải anh đã hứa ta sẽ cùng nhau trở về Ursus sao? Chúng ta còn phải dạy chúng một bài học!”","“…Giữ gìn nhé. Đừng chết.”","“…Không… Không thể nào…” Amiya lùi lại một bước.","“Nhanh lên, di chuyển đi!” Ch’en ra lệnh. “Hoshiguma, liên lạc ngay với lực lượng L.G.D. đóng bên ngoài! Ta đã vô hiệu hóa phần lớn bẫy và phục kích. Thủ lĩnh địch W và mục tiêu vẫn mất tích. Ngay bây giờ, chúng ta đổi mục tiêu nhiệm vụ! Tất cả các đội, tiến vào, tiêu diệt Reunion!”","“Tại sao…” Amiya thì thầm. “…Tại sao lại thành ra thế này… Không…”"],"bg":"bg_wild_a","cast":[["Amiya","op:char_002_amiya"],["Hoshiguma","op:char_136_hsguma"],["Franka","op:char_106_franka"],["Liskarm","op:char_107_liskam"],["Ch'en","op:char_010_chen"],["Skullshatterer","npc:char_1500_skulsr"],["Texas","op:char_102_texas"],["Exusiai","op:char_103_angel"]]},{"c":"3-8","t":"Hoàng hôn","p":["“Ugh! Chúng vẫn đang phản công! Skullshatterer! Chỉ cần đẩy lùi được chúng, chiến thắng sẽ thuộc về chúng ta!”","“Phải…” Bóng người đeo mặt nạ giương súng. “Lúc này… chúng ta không còn lựa chọn nào ngoài chiến đấu.”","“Lũ này… lì thật!” Hoshiguma đỡ đòn, lùi lại.","“Gaah-! Chết tiệt, cái khiên của mày… C-cô ta là người của L.G.D…!”","“Hạ vũ khí đầu hàng vẫn chưa muộn đâu,” Hoshiguma nói. “Trừ khi các người muốn chết vô ích ở đây.”","“Mày nghĩ bọn tao sẽ tin mày sao? Đồ dối trá! Ursus… chúng cũng từng nói y như vậy. Nhưng chúng hành quyết những người Infected ấy, từng người một… Tao đã nằm dưới đống xác người bị giết, nín thở để sống sót.”","Hoshiguma im lặng.","“Chẳng có cái đáy nào mà loại người như mày không chịu xuống… chỉ để tiêu diệt bọn tao. Chẳng phải mày chỉ đang cố gom bọn tao lại để giết cho nhanh sao? Được thôi. Vậy là mày đã chọn rồi.”","“Anh bạn to xác, không nói được với họ đâu,” Franka nói, giọng nhẹ đi. “Họ sẽ không nghe lý lẽ. Họ còn chẳng phân biệt được tốt với xấu, Lungmen với Ursus. Ở nơi đó… Không, ở nhiều nơi lắm… Giữa người nhiễm bệnh và người không nhiễm bệnh, chỉ còn tồn tại thù hận.”","“Có vẻ vì thế mà… mọi đường giao tiếp đều đã đứt,” Hoshiguma nói. “Dù có một con đường khác ngay trước mắt.”","“Một con đường khác?” Bóng người đeo mặt nạ cất tiếng. “Chúng tôi… còn có thể làm gì chứ? Và các người thì làm được gì?”","“Đừng phí thời gian nghe lời dối trá của chúng nữa! Skullshatterer, cùng nhau tiêu diệt chúng đi!”","Một loạt nổ dội vang vách hầm.","“Nổ?”","“Hắn định bao vây ta từ nhiều hướng!”","“Sườn ta sẽ sụp nếu không giành được thế chủ động…” Ch’en nói. “Chuẩn bị phản công!”","“Skullshatterer! Tôi sẽ yểm trợ anh! Cứ giết chúng là trận đánh kết thúc! Skullshatterer…!”","“Tôi phải trở về… cùng tất cả mọi người…” Bóng người đeo mặt nạ thì thầm. “Tôi phải…!!”","Nó lao về phía trước.","“Ta không còn nhiều thời gian!” Ch’en nói. “Hoshiguma.”","“Tôi sẵn sàng.”","“Hành động thận trọng. Đừng để địch thấy chút dấu hiệu yếu thế nào.”","“Tôi sẽ không cho chúng một kẽ hở nào!”","“Cẩn thận, địch đang xông lên!”","“Amiya! Tránh xa kẻ địch ra…!” Franka hét.","Nhưng Amiya không tránh. Cô bé đứng đó, nhìn chiếc mặt nạ đang lao về phía mình, nhìn mái tóc trắng thấp thoáng dưới mép mũ trùm.","“Đ-đó là…” Cô bé quay sang Doctor, đôi mắt cầu cứu. “Em… Doctor… Doctor, em phải làm sao…”","“Em biết mình phải làm gì, Amiya.”","“Nhưng em không muốn… Em xin lỗi, Doctor… Em…”","Bóng người đeo mặt nạ dừng lại cách cô bé vài bước. Cây súng hạ xuống một chút.","“A-…”","“Amiya…?”","“Tại sao…” Nước mắt lăn dài trên má Amiya. “Chị… Tại sao chị lại trở thành thế này…”","“Amiya…” Giọng nói sau lớp mặt nạ không còn cố hạ thấp nữa. “Tôi đoán đây là số phận của chúng ta từ đầu.”","“Amiya! Em làm gì vậy? Nhanh lên…” Ch’en quát. Rồi cô ta nhìn Amiya, nhìn bàn tay cô bé run rẩy không thể giơ lên.","“…Chậc…”","“Cô Ch’en? Em…”","“Đủ rồi.” Ch’en bước lên, đứng chắn trước Amiya. Thanh kiếm trong tay cô ta hạ thấp, mũi chĩa xuống đất. “Đã đến lúc… kết thúc chuyện này.”","“Cô Ch’en…”","“Có một điều tôi phải nói với em.” Ch’en không quay lại. “Từ giờ trở đi, tốt nhất em nên đối xử với tất cả người Infected như nhau… …như kẻ thù.”","@cg:bg_0_coma","Amiya đứng chết lặng.","“Đời là bất công,” Ch’en nói. “Nếu muốn căm ghét ai, thì hãy căm ghét tôi.”","Cô ta giơ kiếm lên.","“L.G.D.! Tấn công!”","","Khi tất cả đã kết thúc, đường hầm chìm vào một sự im lặng nặng nề như đá.","“Amiya.” Ch’en đứng trước mặt cô bé, trên tay là một chiếc mặt nạ trắng nứt vỡ. “…Kết thúc rồi.”","Amiya không trả lời.","“Con người luôn có cách vượt quá sự mong đợi của em,” Ch’en nói. “Nhất là khi nói đến người Infected. Quyền lực sinh ra điên loạn, dục vọng sinh ra trụy lạc. Chúng là những khối u, gặm mòn mọi điều tốt đẹp trên thế giới này.”","Cô ta nhìn chiếc mặt nạ trong tay.","“Tôi không nghĩ chiếc mặt nạ này có ý nghĩa gì đặc biệt với em.”","“Em nghĩ…”","“Nếu em muốn giữ nó, tôi không ngăn em.” Ch’en đặt chiếc mặt nạ vào tay Amiya. “Chỉ cần biết rằng, một ngày nào đó, căn phòng của em sẽ đầy những chiếc mặt nạ như thế này. Mọi người đều phải gánh chịu hậu quả cho những lựa chọn của mình… Infected hay không cũng vậy.”","Amiya nhìn xuống chiếc mặt nạ. Bên trong nó, vướng vào quai đeo, có một sợi tóc trắng ngắn.","“…Em xin lỗi… Cô Ch’en, em…”","“Nghe này, Amiya. Những người này… Reunion, nếu họ sẵn lòng nghe em, thì em có thể làm mọi điều trong khả năng để giúp họ. Nhưng nếu họ đã quyết định từ bỏ tiếng nói của lý trí và hiến dâng đời mình cho sự điên cuồng… Em không nên do dự nữa.”","Ch’en im lặng một lúc. Khi cô ta nói tiếp, giọng cô ta thấp hơn, như không phải nói với Amiya, mà với chính mình.","“…Cô ấy không làm điều gì ác. Chúng ta hôm nay cũng chẳng chấm dứt được điều ác nào ở đây. Chuyện này xảy ra chỉ vì một lựa chọn cô ấy đã đưa ra. Không ai có quyền ngăn cô ấy, và không ai có quyền trách cô ấy.”","“Nhưng em…” Amiya siết chặt chiếc mặt nạ. “Em không biết… Em luôn cảm thấy chúng ta có bổn phận giúp đỡ những người cần giúp. Nhưng tại sao… mọi chuyện lại phải kết thúc thế này…? Tại sao chị ấy phải một mình gánh chịu hậu quả này… Những gì Rhodes Island đang làm có thật sự đúng không?”","“…Khi một người mắc Oripathy, mạng sống của cô ấy không còn là của riêng cô ấy nữa,” Ch’en nói. “Có lẽ qua đôi mắt của Rhodes Island, những người lầm đường vẫn có thể được cứu chuộc… Nhưng với tôi, và với L.G.D., không phải vậy. Nếu cần thiết, chúng tôi có thể phải…”","“Em chỉ muốn phá vỡ cái vòng luẩn quẩn không bao giờ dứt này…” Amiya nói. “Dù chỉ từng chút một… Nhưng… nếu mọi thứ rốt cuộc đều kết thúc thế này, thì em chỉ có thể…”","“Amiya.” Ch’en nhìn cô bé. “…Em đang nghi ngờ chính mình sao?”","“Em… Em không biết… Người Infected dường như luôn bị định sẵn phải chết, hoặc dưới tay kẻ thù, hoặc do chính mình gây ra. Bi kịch này sẽ chỉ lặp đi lặp lại, mãi mãi. Trong vòng xoáy thù hận ác nghiệt này, ngoài việc loại bỏ chính Oripathy, chỉ có một cách để người Infected lấy lại hy vọng…” Amiya ngẩng lên. “…Đó là vứt bỏ những xiềng xích gai góc này, và chấm dứt chính thù hận.”","“Amiya…” Ch’en nhìn cô bé thật lâu. “Lòng nhân từ có cái giá mà không phải ai cũng trả nổi. Rhodes Island không thể trở thành L.G.D., cũng không thể làm những gì L.G.D. làm. Chọn số lượng người Infected mà các người sẵn lòng chấp nhận, hay chọn cứu bao nhiêu người bằng những phương pháp nhân từ của các người… Đó là những điều chỉ Rhodes Island làm được. Hay đúng hơn… Đó là những điều chỉ Rhodes Island sẵn lòng làm. Nhưng tôi không thể làm những điều ấy… Và nhất là… L.G.D. thì không.”","Cô ta nhìn chiếc mặt nạ trong tay Amiya.","“Ít nhất… em cũng sẽ tưởng nhớ cậu ta, không chỉ những đồng chí của cậu ta. …Nếu căn phòng của em sẽ đầy những chiếc mặt nạ, thì cứ để vậy đi. Nhớ rằng, đây là chuyện của em, không phải của ai khác.” Ch’en quay đi. “Cô ‘thủ lĩnh’ nhỏ của Rhodes Island… Nếu em đã sẵn sàng gánh vác gánh nặng này… thì hãy đưa ra quyết định, và chấp nhận hậu quả.”","Amiya ôm chặt chiếc mặt nạ vào ngực.","“…Cảm ơn cô… Cô Ch’en…”","Ch’en không quay lại. “L.G.D. sẽ dọn dẹp hiện trường rồi kết thúc. Sau đó, tôi sẽ liên lạc với cô bác sĩ kia.”","Amiya đứng thêm một lúc. Rồi cô bé quay sang người khoác áo trùm đầu vẫn lặng lẽ đứng bên cạnh mình suốt từ đầu đến cuối.","“Doctor, đi thôi.”","","Trên một vách núi cao nhìn xuống khu mỏ, nơi ánh hoàng hôn nhuộm đỏ cả vùng hoang mạc, W ngồi một mình, đung đưa chân.","“Chậc… Số phận con người lúc nào cũng có cách đan vào nhau thật kỳ lạ. Chúng giao nhau, va vào nhau. Ngay cả một đại kiện tướng cũng có thể bị chiếu tướng bởi những diễn biến bất ngờ.”","Cô ta đứng dậy, nhìn về phía Lungmen xa xa, nơi những ngọn tháp kính đang bắt đầu lên đèn.","“Nhưng cuối cùng, mọi chuyện vẫn ổn cả. Vì ít nhất… tôi có thể mong chờ những gì tương lai đang đợi chúng ta.” Một nụ cười. “Heh.”"],"bg":"bg_wild_a","cast":[["Ch'en","op:char_010_chen"],["Amiya","op:char_002_amiya"],["Skullshatterer","npc:char_1500_skulsr"],["Hoshiguma","op:char_136_hsguma"],["Franka","op:char_106_franka"],["W","npc:avg_npc_046"]]}],"id":"main_3","no":"Chương 3","title":"Cú sốc buốt nhói","en":"Stinging Shock","sum":"Misha bị Reunion bắt đi. Rhodes Island và L.G.D. truy đuổi đến một khu mỏ bỏ hoang, nơi Amiya phải đối diện với câu hỏi đau đớn nhất: người Infected có buộc phải giết lẫn nhau không?"},{"secs":[{"c":"4-1","t":"An ủi","p":["<i>8:36 tối. Mưa. Tầm nhìn 12 km.</i><br><i>Rhodes Island.</i>","“Mừng em về.”","Amiya đứng ở cửa phòng y tế, áo khoác còn ướt nước mưa, chiếc mặt nạ trắng nứt vỡ vẫn được ôm chặt trước ngực. Cô bé chỉ khẽ gật đầu.","Kal’tsit nhìn cô bé một lúc. “Tôi đã nghe đội trinh sát kể lại rồi. Amiya, cho tôi xem tay em.”","“Không cần đâu, bác sĩ Kal’tsit…”","“Amiya.”","Chỉ một tiếng gọi, không cao giọng, không ra lệnh. Amiya cắn môi, rồi chậm chạp tháo găng tay, đưa hai bàn tay ra. Kal’tsit cúi xuống, xoay nhẹ từng ngón, nhìn thật kỹ những chiếc nhẫn trên tay cô bé.","“Trông ổn. Nhẫn chưa nứt, cũng chưa đổi màu. Nhưng lần sau có thể sẽ khác.” Kal’tsit buông tay cô bé ra. “Nghe cho kỹ đây, Amiya. Hãy cẩn thận hơn một chút.”","“Bác sĩ Kal’tsit, em…” Amiya mở miệng, rồi lại thôi. “…Em cần nghỉ một chút.”","“Đi đi.”","Khi cánh cửa khép lại sau lưng Amiya, Kal’tsit quay sang Doctor. Đôi mắt màu lục nhạt lạnh như mặt kính.","“Đừng bao giờ để Amiya lâm vào nguy hiểm đến mức này nữa. Người cũng phải chịu trách nhiệm cho những gì đã xảy ra.” Cô ta ngừng lại. “Hồi người mới quay về Rhodes Island, con bé cũng trông giống thế này. Những cảm xúc ấy chưa bao giờ thực sự rời khỏi Amiya. Điều này phải thay đổi.”","“…Doctor, người nên ở bên con bé. Đừng làm hỏng chuyện.”","","Cốc, cốc.","“Cửa mở đấy ạ.” Amiya ngồi trên mép giường, ngước lên. “…Doctor?”","Cô bé nhìn gương mặt dưới mũ trùm một lúc, rồi khẽ cười.","“Lo lắng ạ? Em sao? …Doctor nhìn thấu em rồi, hehe… Em tưởng mình giấu giỏi lắm chứ. Vâng, em hơi lo một chút… chỉ một chút thôi. Em quen làm thế này rồi. Dù sao em cũng không thể kéo chân mọi người thêm nữa. Phải không Doctor?”","Doctor không trả lời. Amiya cũng thôi cười.","“…Em không hiểu,” cô bé nói khẽ. “Doctor… em không hiểu.”","Doctor vẫn im lặng, để cô bé nói tiếp.","“Không, em… em biết chúng ta đang cố làm gì. Em cũng biết… có những hy sinh là không tránh khỏi. Nhưng em… điều em không biết là… tại sao em cứ phải nhìn từng người một biến mất ngay trước mắt… dù họ có thể được cứu? Chúng ta đã ở gần đến thế… Có lẽ chỉ cần thêm một chút nữa thôi…” Hai bàn tay cô bé siết lấy mép chăn. “Em biết mình có bổn phận… và em sẽ tiếp tục bước tiếp… Nhưng lúc này… em chỉ thấy mệt quá.”","“Amiya…”","“Doctor cho em ở một mình một lúc nhé.” Cô bé cúi đầu. “Cảm ơn Doctor.”","@bg:bg_rhodesroom","Sáng hôm sau, Amiya chào Doctor ở hành lang như mọi ngày, nụ cười đã trở lại đúng chỗ của nó.","“Chào buổi sáng, Doctor. Ơ, bác sĩ Kal’tsit cũng ở đây ạ?”","“Amiya. Tôi có một nhiệm vụ khá gấp, cần vài người giúp,” Kal’tsit nói. “Một thành phố bỏ hoang vừa được phát hiện không xa Lungmen. Tôi đoán đó là một trong những thành phố hình thành sau sự kiện Chernobog. Ta phải thăm dò thành phố đó, tìm thêm thông tin và tìm người sống sót. Nếu tình hình nghiêm trọng, ví dụ Reunion đang ẩn náu ở đó, các chiến dịch sau này của ta có thể bị ảnh hưởng nặng. Đây là đề xuất cụ thể. Có thời gian thì xem qua.”","“Em hiểu rồi.”","“Còn một việc nữa. Franka gửi báo cáo, nói họ phải về Blacksteel. Về tình hình khu ổ chuột Lungmen, Penguin Logistics muốn gặp em ở đó để bàn vài thông tin. Có vài chi tiết nhạy cảm, nên em đi trực tiếp thì tốt hơn.”","“Em biết rồi. Em đi ngay.” Amiya quay sang. “Doctor, đi thôi—”","“Tôi còn vài chuyện cần bàn với Doctor.”","“…Em nghe cùng được không ạ?”","“Không được.”","“Em bịt tai lại cũng được…”","“Không được. Em đi đi.”","“Ưm…” Amiya xụ mặt, rồi quay lại nói thêm một câu trước khi đi: “Bác sĩ Kal’tsit không được bắt nạt Doctor đâu đấy.”","“Tôi sẽ không.”","Khi tiếng bước chân của Amiya đã xa, Kal’tsit quay lại, khoanh tay.","“…Người. Đến chuyện cơ bản như thế mà người cũng không làm được.” Cô ta thở dài. “Thôi bỏ đi, tôi đã đoán trước rồi. Amiya là một đứa trẻ cực kỳ kiên cường. Nhưng nếu con bé cứ phải gồng mình lên để mạnh mẽ, sẽ có ngày áp lực khiến nó gãy vụn. Đừng để chuyện đó xảy ra. Lần sau, người nên có ích hơn một chút.”","Cô ta nhíu mày. “—? Cái mặt đó là sao?”","“Xin lỗi, nhưng nhẫn của Amiya… nghĩa là sao?”","“Nó liên quan đến tình trạng sức khỏe của con bé,” Kal’tsit đáp. “Nếu Amiya tham gia một trận chiến dữ dội, người phải kiểm tra nhẫn của con bé ngay sau đó. Thấy thay đổi gì, dù nhỏ nhất, cũng phải báo cho tôi. Tạm thời, người chỉ được biết đến đó thôi.”","Cô ta quay đi, rồi như chợt nhớ ra. “À phải. Hai ngày nữa người phải xuống trung tâm y tế khám sức khỏe. Đừng quên. …Người đi được rồi. Liskarm đang chờ bên ngoài để hộ tống người.”","@bg:bg_ri_1","<i>6:03 chiều. Nhiều mây. Tầm nhìn 19 km.</i><br><i>Sa mạc gần Lungmen. Cơ sở số 14.</i>","“…Đã đến đích. Không phát hiện bất thường nào khác. Báo cáo hết.” Meteorite hạ thiết bị liên lạc, quay sang cô gái đi cạnh. “Frostleaf, sao suốt đường cô cứ nhíu mày thế?”","“Tôi chỉ hơi lo cho nhóm của Amiya,” Frostleaf đáp. Cô gái nhỏ người, đôi tai cáo dựng lên, thanh rìu dài vác trên vai trông nặng hơn cả người cầm nó.","“Họ đã về Rhodes Island an toàn rồi. Nearl và Dobermann cũng rời Lungmen từ tuần trước để làm nhiệm vụ tiếp theo. Phải điều cả hai người ấy đi cùng thì chắc nhiệm vụ khó lắm. Blacksteel và Penguin Logistics thì đều có việc riêng.”","“À, chị Liskarm và chị Franka…” Cô gái thứ ba, Jessica, ôm chặt khẩu súng trước ngực, giọng nhỏ xíu. “Em… em mừng là họ an toàn…”","“Cô cũng phải cố gắng như họ đấy,” Meteorite nói. “Khi Franka gửi cô sang chỗ tôi, cô ấy khen cô nhiều lắm.”","“T-thật ạ…?”","“Giá mà cô bớt nhút nhát đi, cô ấy nói vậy.”","“Uuu…”","“…Này, đừng có làm như sắp khóc đến nơi thế! Chẳng phải cô cũng là thành viên Blacksteel sao…?”","“Em… em không… khóc…”","Meteorite thở dài, rồi nghiêm giọng. “Dù sao, tiếp tục nhiệm vụ. Việc tiếp theo là phối hợp với các đội trinh sát khác, thăm dò toàn bộ thành phố này. Ngoài tìm người sống sót, còn phải đánh giá tình hình. Gặp người Infected thù địch thì xử lý nhanh. Nhiệm vụ này không quá nguy hiểm, nhưng vẫn nên thận trọng. Nếu Reunion có dính dáng, ta rút ngay và báo cáo bác sĩ Kal’tsit.”","“Vâng, vâng!”","“Rõ.”","“Việc còn lại của chúng ta… là tập trung vào công việc.”","@bg:bg_cher_3","<i>6:12 chiều. Nhiều mây. Tầm nhìn 19 km.</i><br><i>Rhodes Island. Hai ngày sau khi phát hiện “Cơ sở số 14”.</i>","Ở boong tàu, Amiya đang đứng giữa một nhóm người quen.","“A… Doctor đến rồi.”","“Đúng lúc lắm, Doctor,” Texas nói.","“Việc của bọn tôi ở đây xong rồi. Có lẽ một thời gian nữa mới gặp lại~” Exusiai vẫy tay.","“Đi luôn rồi sao?” Doctor hỏi.","“Chẳng mấy chốc là gặp lại thôi,” Liskarm đáp.","“Không lâu nữa bọn tôi lại về túc trực ở Rhodes Island,” Franka nháy mắt. “Đừng nhớ tôi quá nhé.”","“Còn bọn tôi thì không có lý do nghe nghiêm túc như vậy đâu. Phải không, Texas?” Exusiai cười toe. “Penguin Logistics… sắp được nghỉ phép!”","“Khoan đã…”","“Chỉ có một ngày quý giá thôi… Nhưng mà—”","“…Xin lỗi,” Texas ngắt lời. “Giờ không phải lúc thích hợp để nói chuyện đó.”","“Không sao đâu…” Amiya nói. “Ai cũng cần nghỉ ngơi mà.”","“…Câu đó tôi mới là người nên nói với cô.”","“Hả…?”","“Đúng rồi, đúng rồi. Amiya, cô bé, cô mới là người cần nghỉ ngơi đấy!”","“Ở Rhodes Island còn nhiều việc phải lo lắm…”","“Tôi hiểu, nhưng đừng tự tạo áp lực cho mình quá, Amiya,” Liskarm nói.","“Ý chí có mạnh đến đâu, mệt quá thì cơ thể cũng không theo kịp đâu,” Franka thêm. “Đừng có ốm đấy. Mọi người trông cả vào cô!”","“Em… Mọi người lúc nào cũng chăm sóc em.”","“Bọn tôi cũng được truyền cảm hứng từ cách cô chiến đấu,” Texas nói. “Chừng đó là đủ rồi.”","“Nhân tiện đến đây, tôi tranh thủ khám sức khỏe miễn phí rồi mới về,” Exusiai nói.","“Dù sao việc ở đây cũng gần xong. Tiếp theo là…” Franka quay sang. “Amiya, Doctor.”","“Em đang nghe ạ.”","Franka và Exusiai nhìn nhau, rồi đồng thanh, giơ nắm tay lên trời:","“Cố lên nào~! Vui lên đi!”","“Ơ… hả?”","“Báo cáo xong, bọn tôi sẽ quay lại ngay,” Liskarm nói.","“Dù thế nào, cuộc sống vẫn phải tiếp tục,” Texas nói. “Amiya, giữ gìn nhé.”","“Mọi người… Em…” Amiya cúi đầu, rồi ngẩng lên, mắt sáng lên một chút. “…Em sẽ giữ gìn. Mọi người cũng vậy nhé. Hẹn gặp lại.”","Khi họ đã đi khỏi, cô bé quay sang Doctor.","“Doctor, em phải đến khu ổ chuột ngoại ô Lungmen thêm lần nữa. Em có thể giúp được gì đó.”","“Amiya, tôi đi cùng em nhé?”","“Doctor đừng lo. Một thành viên khác của Rhodes Island, Projekt Red, sẽ đến Lungmen cùng em. Chị ấy giỏi lắm! Có chị ấy ở đó, Doctor không cần lo cho em đâu.”"],"bg":"bg_ri_1","cast":[["Amiya","op:char_002_amiya"],["Kal'tsit","op:char_003_kalts"],["Meteorite","op:char_219_meteo"],["Texas","op:char_102_texas"],["Jessica","npc:char_259_Jessica_1"],["Exusiai","op:char_103_angel"],["Franka","op:char_106_franka"],["Liskarm","op:char_107_liskam"]]},{"c":"4-2","t":"Dạo bước dưới mưa","p":["“C-còn hai tên địch! Chúng đang chạy về tòa nhà phía đông chúng ta—”","“Tôi đã khóa mục tiêu rồi.” Meteorite nheo mắt qua ống ngắm. Mũi tên nổ rời dây nỏ. Một tiếng nổ xa xa, rồi im lặng. “Trúng hồng tâm.”","“Có ồn quá không?” Frostleaf hỏi.","“Khắp thành phố đầy tiếng nổ. Tôi không nghĩ chúng để ý đâu. Cô báo cho bác sĩ Kal’tsit chưa?”","“Tôi gọi trước khi trận đánh bắt đầu. Có bằng chứng cho thấy Reunion đang hoạt động trong thành phố này. Tôi chưa cúp máy. Có nên di chuyển kín đáo hơn không?”","“Tên Reunion vừa nãy có vẻ đang dùng Arts loại dò tìm. Phải ra tay trước để không lộ vị trí. Ít nhất, không thể cho các toán Reunion thời gian liên lạc với nhau.”","“Phù… Cuối cùng cũng xong…” Jessica thở hắt ra.","“Frostleaf, đánh giá tình hình đi.”","“Rõ. Đây, cầm thiết bị liên lạc giúp tôi.”","“Được. Jessica, đừng lơ là vội.”","“Em biết… Em biết mà!”","“Rồi, rồi. Tôi không nhắc nữa.” Meteorite áp thiết bị lên tai. “Bác sĩ Kal’tsit, cô nghe rõ không?”","“Lúc nào cũng nghe rõ,” giọng Kal’tsit vang lên. “Đúng là chưa thể lơ là được đâu. Jessica, có thể có kẻ địch sau lưng em.”","“Uwaaah!”","Jessica quay phắt lại. Một tên Reunion đang đứng ngay sau cô, vũ khí giơ cao, rồi đổ gục xuống, máu đông cứng trên vết thương.","“S-sao chúng… vào được sau lưng tôi…”","“…Ểểể??”","“Nếu tôi tấn công được từ phía sau ngươi, nghĩa là ngươi quá chậm.” Frostleaf lắc nhẹ lưỡi rìu, những tinh thể băng rơi lách tách. “Tạm thời bọn tôi ổn, bác sĩ Kal’tsit. Tôi đã hạ địch rồi.”","“Cô nhanh thật đấy…” Meteorite nhìn cô gái. “Tôi còn không thấy cô qua đó rồi quay về từ lúc nào.”","“—Thật ra, tôi chưa hề rời khỏi đây.”","Meteorite im lặng.","“Projekt Red đã liên lạc với tôi,” Kal’tsit nói tiếp. “Quân Reunion ẩn nấp ở Lungmen chưa có dấu hiệu hoạt động. Giai đoạn này, tốt nhất đừng chọc vào tổ ong. Nhân tiện, theo tin từ các đội trinh sát khác, có thể có một lực lượng Reunion đáng kể trong sa mạc.”","“Nói cách khác, chúng tôi là đội trúng số độc đắc à?” Meteorite nhăn mặt. “Áp lực thật. Dù sao chúng tôi cũng chỉ là đội trinh sát.”","“Nếu vậy thì… ta đã hạ được hai toán Reunion rồi…” Jessica nói.","“Cô có chắc chắn tuyệt đối về phe của toán địch ta giao chiến đầu tiên không, Jessica?”","“Vâng, không thể sai được. Em đã kiểm tra lại hai lần trước khi nhờ chị bắn.”","“…Lỗi của tôi. Lúc đó tôi đang bận tính đường đạn.”","“Quân số của địch thì sao?” Kal’tsit hỏi.","“Chưa rõ con số chính xác. Frostleaf, bên đó thế nào?”","Frostleaf không trả lời. Cô đứng im trước một bức tường đổ nát, bàn tay đặt lên mặt đá.","“Sao vậy…?”","“Đi xem đi,” Kal’tsit nói. “Có vấn đề gì thì báo ngay.”","Meteorite và Jessica bước tới. “Chuyện gì thế?”","“…Hai người không cảm thấy sao?” Frostleaf hỏi.","“Hả? Cảm thấy gì…”","“Nhiệt độ.”","“Chị nhắc mới để ý… hình như lạnh hơn thật…”","“…Đúng vậy,” Meteorite nói. “Chênh ít nhất năm độ so với nhiệt độ bên ngoài.”","“Sao thời tiết đang đẹp… lại đột ngột đổi được…”","“Nhìn lên đi. Thời tiết không đổi.” Frostleaf gõ nhẹ lên tường. “Không phải do thời tiết. Nó đến từ đây. Lại sờ thử xem. Những bức tường này đã bị hút hết nhiệt.”","“…Không thể nào?!”","“Trước khi chúng ta đến, có lẽ hiệu ứng hút nhiệt đã tan dần. Nó đang trở lại nhiệt độ cũ.” Frostleaf rút tay về. “Nhưng tại sao? Ai lại để lại thứ như thế này?”","“…Ở vùng này chỉ có Reunion hoạt động.”","“Reunion? Họ… làm được chuyện như thế này sao?”","“Người Infected…” Frostleaf nhìn bức tường phủ một lớp sương mỏng. “Tôi từng nghe một truyền thuyết. Về một sinh vật gọi là ‘yeti’.”","Meteorite thở dài. “…Tôi có cảm giác… chuyện này sẽ rắc rối lắm đây…”","@bg:bg_cher_6","Ở khu ổ chuột Lungmen, trời mưa.","Amiya đi một mình giữa những con hẻm ướt sũng, mũ áo trùm kín đầu. Cô bé không mang ô. Cô bé cũng chẳng để ý mình đang đi đâu.","“A…! Cẩn thận!”","Một đứa bé chạy sầm vào cô bé. “Ui!”","“X-xin lỗi, em không cố ý…”","“Không sao đâu. Em lễ phép lắm.”","“Ehehe…” Đứa bé ngước lên. “Chị ơi, chị làm gì ở đây vậy? Trời còn mưa mà. Chị không vào nhà à?”","“À, ừm… Chị chỉ… đi dạo thôi.” Amiya nhìn đứa bé. “Em đang tìm người giúp à?”","“Ồ! Sao chị biết?!”","“Không nói đâu~ Bí mật.”","“Ơ… thôi cũng được!” Đứa bé nhìn cô bé từ đầu đến chân. “Chị ơi, chị nghĩ… Hừm, chắc không được đâu. Chị hơi lùn…”","“Này, em không được nói vậy chứ! Em còn lùn hơn chị!”","“Ồ!” Đứa bé cười khúc khích. “T-thì mình thử xem… Chị giúp em nhấc tấm ván kia được không? Cùng làm nhé! Dưới cái giá sắt đó có một cái máy hát. Em muốn mang nó về nhà.”","“Được.”","“Một… hai… ba! Cùng nào!”","Tấm ván nhấc lên. Dưới đó là một chiếc máy hát đĩa cũ, loa kèn méo mó, tay đĩa gãy một nửa.","“Woa, chị khỏe thật đấy! Cảm ơn chị!”","“Nhưng… cái máy hát này hỏng rồi.”","“Không sao! Nó hỏng từ trước rồi. Nhưng một ngày nào đó em sẽ sửa được. Em sưu tầm nhiều đĩa lắm, nhưng chưa nghe cái nào bao giờ…” Đứa bé ôm chặt chiếc máy hát. “…Nhưng một ngày nào đó, em sẽ mở cho mọi người cùng nghe!”","Amiya nhìn đứa bé rất lâu.","<i>Một điều khó khăn đến thế, mà nói ra nhẹ nhàng như vậy…</i>","<i>…Mình làm tất cả những chuyện này để làm gì… Mình còn làm được gì cơ chứ…</i>","“Chị ơi, chị không sợ em à?”","“…Sợ gì cơ?”","“Em là người Infected mà!”","“Haha… Chị cũng vậy.”","“Hả?! Tiếc ghê. Chị xinh thế cơ mà…!”","Amiya im lặng một nhịp, rồi cúi xuống, nói thật chậm. “Là người Infected thì chẳng có gì sai cả. Dù khỏe mạnh hay nhiễm bệnh… nếu em là người tốt, điều đó sẽ không bao giờ thay đổi.”","“Hả…? Em không hiểu…”","Một tiếng ọt ọt vang lên từ bụng đứa bé.","“…Em đói à?”","“…Vâng…”","“…Đây, cầm lấy. Chị chỉ có chừng này thôi.”","“Woa! Cảm ơn chị!” Đứa bé ôm lấy gói bánh, rồi ngước lên. “Mà… chị đến đây làm gì vậy?”","“Chị…” Amiya ngập ngừng. “Là vì… chị đã hứa với một người.”","“Tạm biệt chị!!”","“Ừ, tạm biệt!”","Đứa bé chạy đi, ôm chiếc máy hát vỡ như ôm một báu vật. Amiya đứng nhìn theo cho đến khi nó khuất sau góc hẻm.","<i>Kể cả một đứa trẻ như thế… rồi cuối cùng cũng sẽ…</i>","Mưa rơi nặng hạt hơn. Và giữa tiếng mưa, có một giọng nói khác vang lên trong đầu cô bé. Không phải giọng của cô bé. Trầm hơn. Lạnh hơn. Rất cũ.","<i>Những kẻ bị tước đoạt danh tính. Người Infected. Các ngươi đã mất quyền tự gọi mình là người từ lâu rồi.</i>","“Mình làm được gì? Mình còn… làm được gì nữa…? Tại sao… mình không thể bảo vệ những người quanh mình…”","<i>Ngươi không thể.</i>","“Không… Mình…”","<i>Đói khát… Ngược đãi… Cái chết… Đó là tất cả những gì chờ đợi người Infected.</i>","“Không, không phải vậy… Chừng nào Rhodes Island còn chiến đấu vì người Infected…”","<i>Ngươi chỉ là một trong số ít kẻ may mắn.</i>","“Không… Tất cả chúng ta đã cùng nhau chiến đấu vì một mục tiêu chung.”","@cg:avg_31_1","<i>Thế giới này đã trở nên lạnh lẽo và tàn nhẫn rồi.</i>","“Không, chưa đâu… Người Infected chưa thể gục ngã trước tuyệt vọng được…”","<i>Ngươi. Hãy để cơn thịnh nộ nuốt chửng ngươi. Chỉ khi đó…</i>","“Mình…” Amiya ôm lấy đầu. “Không… Mình sẽ không… Mình đã hứa… Mình đã hứa với chị ấy…!”","@cg:avg_31_2","Giọng nói tắt lịm. Chỉ còn tiếng mưa.","“…Hả?”","Ở cuối con hẻm, dưới một mái hiên tôn thủng lỗ chỗ, có một bé gái đang đứng trước một người phụ nữ cao lớn, chìa ra một vật nhỏ.","“Có một chị từng nói với em là những con búp bê này sẽ không linh nghiệm nếu không tự tay làm. Nên em tặng chị cái này!”","<i>Giọng nói đó…?</i> Amiya nheo mắt nhìn qua màn mưa. <i>Bóng dáng đó… là cô Ch’en sao?</i>","Bé gái nói thêm gì đó, nhưng tiếng mưa nuốt mất. Người phụ nữ cúi xuống, nhận lấy con búp bê vải. Rồi cô ta đứng im rất lâu, hai bàn tay ôm con búp bê như ôm một thứ gì đó dễ vỡ.","Rồi cô ta ngẩng lên, và nhìn thấy Amiya.","“…!”","@cg:avg_31_4","“Cô Ch’en…”","Ch’en không nói gì. Amiya cũng không nói gì. Mưa rơi giữa hai người như một bức màn.","“Cô Ch’en, cô làm gì ở đây vậy? Em tưởng cô…”","“Không phải việc của cô.” Ch’en nhét con búp bê vào túi áo, quay lưng. “Đây là chuyện của Lungmen. Tôi sẽ tự lo.”","Amiya đứng nhìn theo bóng lưng ấy biến mất vào màn mưa.","@cg:avg_31_3","<i>Cô Ch’en… Đây là lần đầu tiên… em thấy ánh mắt đó của cô.</i>"],"bg":"bg_cher_2","cast":[["Amiya","op:char_002_amiya"],["Meteorite","op:char_219_meteo"],["Child",null],["Frostleaf","op:char_193_frostl"],["Jessica","npc:char_259_Jessica_1"],["Kal'tsit","op:char_003_kalts"],["Little Girl","op:char_002_amiya"],["Ch'en","op:char_010_chen"]]},{"c":"4-3","t":"Cái lạnh nhân tạo","p":["“Tôi hiểu rồi. Được, giữ liên lạc. Có tin gì thì báo tôi. Cứ bấm nút thứ ba. Ừm.” Kal’tsit hạ máy, quay lại. “…Hửm? Doctor? Amiya đâu?”","“Em ấy đến khu ổ chuột rồi.”","“…Người để con bé đi một mình thật à.” Kal’tsit thở ra. “…Thôi, ít ra cũng có người bảo vệ con bé. Mà người có đi theo chắc cũng chẳng làm được gì. Lần này tôi bỏ qua.” Cô ta nheo mắt. “Người cũng tự về đây à? À, Penguin Logistics. Người cũng phải cẩn thận hơn đi. Không phải lúc nào ta cũng có người dẫn đường đáng tin ở địa phương đâu.”","Cô ta ngừng lại một lúc.","“Doctor… Amiya sẽ không ở Lungmen lâu, con bé còn nhiệm vụ khác. Người sẽ phải đối mặt với con bé lần nữa. …Nếu là người, tôi sẽ nhớ nói với con bé những điều mà trước kia tôi không nói được.”","","“A, Doctor?” Amiya đứng ở cửa, tóc vẫn còn ướt. “Doctor chờ em suốt từ nãy sao… Xin lỗi đã để Doctor chờ.”","Cô bé nghiêng đầu khi thấy Doctor nhìn mình. “Hửm? Sắc mặt em khác lúc đi ạ? …Có vài chuyện đã xảy ra.”","Cô bé ngồi xuống bên cạnh Doctor, nhìn ra ô cửa kính, nơi những ngọn tháp Lungmen mờ ảo trong mưa.","“Em có cảm giác… có lẽ cô Ch’en có cách nhìn riêng của cô ấy. Dù lời cô ấy nói rất gay gắt, và cô ấy đã làm những chuyện em không chấp nhận được… Có lẽ… khoảng cách giữa chúng em không lớn đến thế. Cô ấy có trách nhiệm của mình.” Cô bé khẽ mỉm cười. “À… Giờ em hiểu rồi… Cô ấy cũng có gánh nặng riêng phải mang. Có lẽ em cũng…”","“Amiya, em cũng có rất nhiều trách nhiệm.”","“Vậy sao… Em… chỉ là không có lựa chọn nào khác thôi.”","“Ít nhất em đã đi đến cùng với lựa chọn của mình.”","“…Có lẽ tất cả những hậu quả này là kết quả của sự cố chấp của em.” Amiya lắc đầu. “Doctor, không cần… cố an ủi em đâu. Thật ra, em biết rõ điều này mà. Nhưng điều em không biết… là chúng ta phải đi tiếp bao lâu nữa thì thế giới này mới bắt đầu thay đổi.”","“Nhưng điều em chắc chắn biết… là em sẽ không bỏ cuộc. Em sẽ luôn gánh lấy hậu quả cho những hành động của mình, vì… em đã chọn con đường này.”","Cô bé quay sang Doctor.","“Doctor… Doctor sẽ… ở bên em chứ? Dù… cảm giác tội lỗi này sẽ mãi theo em… Nỗi hối tiếc vì không thể đưa mọi người cùng đi. Nỗi hối tiếc vì không cứu được bạn bè… Nhưng em phải đối mặt với hiện thực. Cùng với mọi người ở Rhodes Island…”","Thiết bị liên lạc của cô bé rung lên.","“Hửm? Tin nhắn từ bác sĩ Kal’tsit… Bác sĩ Kal’tsit? Có chuyện gì ạ?”","“Amiya, tôi vừa nhận liên lạc từ vài đội trinh sát. Tình hình đã xấu đi.”","“Vâng, em đến ngay.”","@bg:bg_lungmen_m","Ở thành phố bỏ hoang, ba người của đội trinh sát đang nằm im sau một bức tường đổ.","“Đi tiếp!…” Tiếng một tên Reunion vọng lại.","“Chuyện gì vậy…?” Jessica thì thầm.","“(Đừng phát ra tiếng!)” Frostleaf bịt miệng cô lại.","“(Nnnh—)”","“(Chúng còn ở đó không?)”","“(Vẫn còn…!)” Meteorite hé mắt qua khe gạch. “(Chúng có vẻ đang tìm thứ gì đó… Một tên đang đi về phía ta! Phải nấp đi!)”","Tiếng bước chân dừng lại ngay bên kia bức tường. Một quãng lặng dài như vô tận.","“…Chắc mình tưởng tượng.”","Tiếng bước chân xa dần.","“(Cô bắn trúng hắn được không?)” Frostleaf hỏi.","“(Xa quá… Tiếng nổ ngừng ngay khi chúng xuất hiện… Chúng tản ra quá rộng. Không thể hạ cả ba cùng lúc. Hơn nữa, cách chúng di chuyển chẳng giống đám côn đồ đường phố chút nào.)”","“(Các toán Reunion khác có vẻ không mặc đồ dày như thế,)” Jessica thì thầm.","“(Đúng vậy. Như cô thấy đấy, phải cực kỳ cẩn thận. Nếu có tên nào sống sót gọi viện binh, ta sẽ gặp nguy to. Hơn nữa, tôi thấy một người mặc đồ Caster đằng kia, có vẻ đang thử nghiệm thứ gì đó. Nếu họ cũng dùng được Arts dò tìm… chỉ cần một viên đạn ta bắn ra là có thể bị phát hiện.)”","“(Tức là ta bị trói tay. Ba chọi ba, mà cảm giác như bị bao vây,)” Frostleaf nói.","“(Tình hình không ổn. Tôi ghét cái cảm giác này lắm. Đáng lẽ ta là thợ săn, vậy mà lại bị con mồi lớn hơn dồn đến phải trốn chui trốn lủi.)” Meteorite nheo mắt. “(Khoan, chúng có vẻ đang liên lạc với ai đó…)”","“(Tôi không nghe được chúng nói gì. Tôi lại gần hơn.)”","“(Đừng. Giờ quá liều. Yên tĩnh quá. Ta chưa biết mình đang đối mặt với loại người Infected nào… Nếu có kẻ thính tai, ta sẽ gặp rắc rối.)” Meteorite im một lúc. “(…Chúng đang chờ gì vậy? Có gì đó… không ổn. Lẽ nào… Jessica, cô cũng cảm thấy…?)”","“(V-vâng… Em cũng… Nhiệt độ lại giảm nữa rồi… Lạnh… quá…)”","“(Lẽ nào là chúng gây ra…?!)” Meteorite quay sang, rồi khựng lại. “(…! Jessica, sao cô lại cắn ngón tay—)”","“(Để răng không va lập cập gây tiếng động,)” Frostleaf giải thích. “(Tôi nghĩ chưa cần đến mức đó, nhưng đúng là một đứa trẻ chăm chỉ.)”","“(Với tôi, cô cũng chỉ là một đứa trẻ thôi.)”","“(…Hah. Còn lâu.)”","Một lúc sau, hơi ấm dần trở lại. Meteorite nhổm dậy. “…Ấm lên rồi. Ba tên Reunion kia cũng đi rồi. Chúng đang thử chức năng của thứ gì đó sao…? Xuất hiện không một tiếng động, chỉ để lại vệt lạnh buốt sau lưng… Đúng là giống những con ‘yeti’ trong truyền thuyết.”","“Có lẽ tôi đoán đúng,” Frostleaf nói. “Chúng có thể chính là yeti.”","Cô bước tới một bức tường khác, cúi xuống. “…Tìm thấy rồi. Đây là một bức tường nữa bị băng ảnh hưởng. Nhưng nhìn này…”","“Có một khối Originium đen cắm ở góc tường?” Meteorite nói. “Thảo nào. Đợt lạnh hẳn tỏa ra từ đây.”","“Có những hoa văn rõ ràng trên tường. Khối Originium này là tâm điểm của tất cả.” Frostleaf đứng dậy. “…Hồi tôi còn làm lính đánh thuê, có một lời đồn lan truyền. Ở vùng tây bắc, người Infected đang đánh du kích chống Ursus. Trong số đó có một con quái vật khổng lồ. Lời đồn nói không gì cản được bước tiến của nó. Khiên bị bóp nát, vũ khí bị bẻ gãy. Nơi nào con quái vật đi qua, chỉ còn lại một vùng lãnh nguyên cằn cỗi, không sự sống.”","“Và trong lực lượng du kích ấy, có một đội…” Giọng cô trầm xuống. “Họ như chính cái lạnh của mùa đông. Người ta nói đất đóng băng dưới chân họ. Nhà cửa sụp đổ, hóa thành những hạt tuyết trôi dạt trên chiến trường trống trải. Những chiến hào nơi lính Ursus đồn trú trở thành nấm mồ băng giá của chúng.”","“Ý cô là…”","“Phải. Tôi nghĩ đây chính là truyền thuyết đó… ‘Biệt đội Yeti’.” Frostleaf quay đi. “Đi tiếp thôi. Tôi có cảm giác ta sắp tìm thấy căn cứ Reunion.”","“Ugh…” Jessica nhăn mặt.","“Sao vậy?”","“Hai chị cũng ngửi thấy chứ… mùi gì đó đang cháy?”"],"bg":"bg_ri_1","cast":[["Amiya","op:char_002_amiya"],["Meteorite","op:char_219_meteo"],["Frostleaf","op:char_193_frostl"],["Kal'tsit","op:char_003_kalts"],["Jessica","npc:char_259_Jessica_1"]]},{"c":"4-4","t":"Thần kinh thép","p":["“Mong là không để cô chờ lâu. Cuộc họp của L.G.D. kéo dài hơn dự kiến.”","“Cô đừng bận tâm, cô Ch’en.” Amiya nhìn người phụ nữ trước mặt. <i>Cô ấy trông như chưa có chuyện gì xảy ra…</i>","“Tình hình thế nào?”","“Đội trinh sát đã gửi về vài thông tin. Em đã xem qua và chọn ra vài điều có thể cô quan tâm. A, thanh tra Hoshiguma…”","“Đừng để ý tôi. Tôi chỉ ngồi nghe thôi.” Hoshiguma vẫy tay, ngồi phịch xuống chiếc ghế quá nhỏ so với cô ta.","“Tiếp tục đi, Amiya. Không sao đâu.”","“Vâng. Bọn em đã có manh mối từ vài người Infected… Đội trinh sát đã xác nhận có nhiều sào huyệt Reunion trong khu dân cư Lungmen. Một số toán Reunion đã lên kế hoạch tấn công hệ thống phòng thủ của Lungmen. Bọn em còn tìm thấy một kênh thâm nhập mà Reunion đang dùng.”","“Hah. Ngạo mạn thật,” Ch’en nói. “Chúng có vẻ đang xem thường L.G.D. Còn phế tích Chernobog thì sao?”","“Rhodes Island đã cử nhiều đội trinh sát đến đó. Dù phần lớn cư dân đã đi hết, bọn em vẫn thấy nhiều thành viên Reunion hoạt động. Một đội còn chạm trán quân Reunion hơn ba lần. Tuy nhiên, với thông tin hiện có, bọn em chưa thể kết luận động tĩnh ở thành phố đó có liên quan đến chiến dịch lớn hơn của Reunion… Nhưng em đề nghị chọn thành phố này làm một mục tiêu tác chiến quan trọng trong thời gian tới.”","“…Hiểu rồi. Hoshiguma, lấy giúp tôi tập biểu mẫu. Ngăn kéo thứ ba bên trái bàn tôi.”","“Ngay bây giờ á? Được thôi.”","Khi Hoshiguma đã ra ngoài, Ch’en nói: “Tiếp tục.”","“Vâng, tóm lại… Rhodes Island đề nghị một chiến dịch chung để tiêu diệt hoàn toàn lực lượng Reunion còn lại trong Lungmen.”","“Không được.”","Amiya chớp mắt. “…Dạ? Cô Ch’en…?”","“Tôi nói, không. L.G.D. sẽ không cho phép.” Ch’en nhìn thẳng vào cô bé. “Cô… là người Infected. Nếu cô tiếp tục làm nhiệm vụ trong khu ổ chuột, cô sẽ chỉ gây thêm hỗn loạn. Đây là quyết định của chúng tôi.”","“Nhưng—”","Thiết bị liên lạc của Amiya reo lên. “A, xin lỗi, em phải nghe máy… Amiya đây.”","“L-là Amiya phải không?” Một giọng nói thì thào, đứt quãng.","“…! Jessica?”","“Vâng, Jessica đây…”","“Em đang làm nhiệm vụ ẩn nấp à? Chị gần như không nghe thấy em…”","“Bọn em tìm thấy chúng ở phế tích thành phố… Thủ lĩnh của Reunion… Có… hai người.”","“Cái gì?!”","","Giữa quảng trường của thành phố bỏ hoang, hai bóng người đang đứng đối diện nhau.","“Vậy là cô cụp đuôi chạy về đây à?” Mephisto nói, nụ cười như rắn.","“Tôi đâu phải chó lai như cậu với đồng loại hèn mọn của cậu,” W đáp.","“…Nếu không phải vì cô đã hoàn thành nhiệm vụ, ta đã thêm hai vết sẹo lên cái mặt bẩn thỉu của cô rồi.”","“Chẳng phải cậu mất hết tay chân trong vụ nổ đó sao? Bắt một đứa nhóc như cậu dùng miệng trang điểm cho tôi thì tội nghiệp quá.”","“Phì.”","“Nhưng tạm gác chuyện này lại đi… Chẳng có lợi cho ai cả.”","“Ta thừa nhận điều đó.” Mephisto nghiêng đầu. “Vậy, chúng đã cắn câu chưa?”","“Chắc chắn rồi. Chỉ còn xem lão cầm cờ kia có mang được hàng thật về không thôi.” W cười. “Nhân tiện, cậu sợ lão già đó lắm, phải không?”","“Ta đang không vui đâu.”","“Ôi chao, xin lỗi nhé. Nhưng đó là trước khi ta bắt được mẻ lớn thôi, đúng không? Tạm gác bất đồng đi được chứ?”","“Chậc. Được thôi.” Mephisto quay lại, nhìn thẳng vào một đống đổ nát cách đó vài chục mét. “Ta sẽ xử lý lũ cá con trước. Rhodes Island, ta biết các ngươi ở đó. …Không thể trốn khỏi ta đâu.”","“Jessica, đừng!” Meteorite rít lên. “Có thể là bẫy…!”","Nhưng Jessica đã đứng bật dậy, súng giương lên, hai tay run lẩy bẩy. “Hắn phát hiện ra ta rồi! Ta phải… Nếu hạ được thủ lĩnh địch… Ta phải…!”","“Hừ. Đúng là có thật.” Mephisto bật cười. “Mèo con từ đâu ra thế~? Đừng có coi chỗ này là sân chơi của mình chứ. Này, các ngươi.”","“Rõ!!”","“Trước khi được thưởng thức con mồi béo bở nhất… cứ tự nhiên dùng món khai vị đi.”","“Ồồồ… Ồồồồ!!”","“Chậc…!” Frostleaf giương rìu.","@bg:bg_cher_2","“Hộc… Chết tiệt…” Frostleaf chống rìu xuống đất.","“Cuối cùng cũng… hạ được chúng…” Jessica thở dốc.","Meteorite nhìn quanh. “…Không. Chưa đâu.”","“Bột gì đang rơi xuống vậy…?”","Một lớp bụi lấp lánh như phấn hoa rơi từ trên cao xuống, phủ lên những thân thể Reunion nằm la liệt. Rồi chúng bắt đầu cử động.","“Nngh… Gưh…”","“Uaaagh!”","“Đau quá… Đau quáaaaa…”","“Aaagh… Aaaargh! Ngứa quá! Ngứa quá!!”","“Graaah?!! Rhodes… Rhodes Island! Kẻ thù… Kẻ thù!!”","“C-cái gì…! C-chuyện gì vậy…” Jessica lùi lại. “Những kẻ ta vừa hạ… đang đứng dậy…?”","“Gì? Xong rồi à?” Mephisto ngáp. “Ta còn chưa làm gì cả.”","“Có ánh sáng… phát ra từ cây trượng của hắn…?” Frostleaf nheo mắt.","“Và… còn nhiều viện binh nữa đang đến…”","“Khốn kiếp…!” Meteorite giương nỏ. “Giờ tôi chỉ còn cầu loạt bắn này giết được thủ lĩnh địch…!”","“Đừng,” Frostleaf nói.","“Haha… Ở vị trí đó mà các ngươi còn có thời gian họp bàn chiến lược à?” Mephisto cười. “Tự tin quá nhỉ.”","“Hừ. Phát bắn này sẽ dạy cho mày một bài học…”","“Không, Meteorite. Đừng.”","“Chậc…! Tại sao?!”","“Ta phải rút lui.” Frostleaf nhìn quanh, đôi tai cáo rung lên. “Tôi cảm nhận được… Là bọn họ. Bọn họ đến rồi.”","“Ồ? Không bắn à?” Mephisto quay lưng. “Tiếc thật. Ngươi biết đấy, sẽ không có cơ hội nào khác đâu.”","“Hắn bỏ đi sao? Nhưng—”","“Meteorite! Nhắm vào tòa nhà đang sụp phía tây, ngay! Ít nhất làm địch phân tâm để câu thời gian!”","“…Chỉ còn cách này thôi! Tôi làm đây!”","“Jessica, bắt đầu chạy đi.”","“Hả?”","“…Biệt đội Yeti đến rồi.”","“Khoan đã…” Jessica rùng mình. Hơi thở cô bốc thành khói trắng. “L-lạnh quá…”","“…Đi thôi,” Frostleaf nói. “Ngay.”","“…Jessica. Cô ấy nói đúng. Ta phải ra khỏi đây…!”","Frostleaf vừa chạy vừa áp thiết bị liên lạc lên tai. “Amiya, nghe rõ không? A lô? A lô?”","“Cứ đi đi! Tôi yểm hộ!” Meteorite hét.","“Nghe này, Amiya. …Đừng đến. Phế tích này là…”"],"bg":"bg_lungmen_m","cast":[["Amiya","op:char_002_amiya"],["Mephisto","npc:char_1507_Mephisto_1"],["Frostleaf","op:char_193_frostl"],["Ch'en","op:char_010_chen"],["Jessica","npc:char_259_Jessica_1"],["Meteorite","op:char_219_meteo"],["W","npc:avg_npc_046"]]},{"c":"4-5","t":"Bộ máy quan liêu","p":["“Frostleaf? Frostleaf?!” Amiya hét vào máy. “Chuyện gì vậy…”","Một giọng khác chen vào, rè rè. “Amiya! Đây là Đội trinh sát 2… Bọn tôi đang rút lui! Nhưng địch… Reunion…”","Tín hiệu tắt.","“Lại mất nữa? Đội trinh sát 3! Có nghe không? Đội trinh sát 3!”","Im lặng.","Ch’en đứng khoanh tay, không nói gì.","“Amiya,” giọng Kal’tsit vang lên.","“Bác sĩ Kal’tsit! Là em! Cô có nhận được—”","“Tôi đã liên tục theo dõi họ từ đài chỉ huy. Tôi cần em hỏi viên sĩ quan đứng cạnh em một câu. Hỏi cô ta…” Kal’tsit ngừng một nhịp. “‘Lungmen định giả ngu đến bao giờ?’”","“Tôi sẽ coi như không nghe thấy câu đó,” Ch’en nói. “Nhưng đúng là chúng ta không có thời gian để lãng phí.”","Hoshiguma bước vào, tay cầm tập biểu mẫu. “Chuyện gì vậy? Tôi vừa đi lấy giấy tờ, về đã thấy hai người mặt nghiêm trọng thế này. …Nhiệm vụ mới à?”","“Đúng vậy.”","“Mọi người… Chuẩn bị trang bị đi. Đến lúc xuất phát rồi.” Amiya quay sang Ch’en, đứng thẳng lưng. “Cô Ch’en, em chính thức đề nghị L.G.D. hỗ trợ Rhodes Island trong nhiệm vụ giải cứu này. Có thể chúng ta đang đối mặt với tổng hành dinh tạm thời mới của Reunion… Hơn nữa, em tin các đội trinh sát của bọn em vẫn đang chiến đấu ngoài đó, dù ta không thấy họ…”","Ch’en im lặng.","“Đến nước này… bọn em không còn lựa chọn nào khác. Cô Ch’en, nếu cô từ chối… Rhodes Island sẽ tự hành động. Việc này không vi phạm bất kỳ điều khoản hợp tác nào.”","“Đương nhiên là chúng tôi sẽ đến.”","Amiya sững lại. “…Vậy sao…”","“Chuyện nhỏ thôi,” Ch’en nói. “Nhưng tôi không chắc đội của chúng tôi vào được phế tích. Phải tùy cơ ứng biến. Nếu tình hình cho phép, chúng tôi chắc chắn sẽ giúp. Tuy nhiên, ưu tiên hàng đầu vẫn là tiêu diệt Reunion.”","“Thế… thế là đủ với bọn em rồi.” Amiya cúi đầu. “…Thay mặt Rhodes Island, cảm ơn cô. Em biết Lungmen vẫn xem bọn em là người Infected…”","“Xin lỗi, tôi có bổn phận của tôi.” Ch’en quay sang thiết bị liên lạc. “Nghe rõ chứ, bác sĩ? Chúng tôi sẽ hội quân với Rhodes Island.”","“Amiya, cẩn thận,” Kal’tsit nói. “Đây không phải việc đơn giản. À, tôi đã ghép được vài mảnh thông tin. Rhodes Island đã cử các đội cứu hộ đi hỗ trợ những đội trinh sát khác. Nhưng đội của Meteorite ở quá xa, ta không với tới được. Đến lượt em.”","“Chỉ còn đội của Meteorite… Em hiểu rồi. Em sẽ đi tìm họ.”","“Tôi sẽ gửi tọa độ sau. Nhớ kỹ, an toàn là ưu tiên hàng đầu.”","“Rõ.”","“Vậy, khi nào xuất phát?” Hoshiguma hỏi.","“Ngay bây giờ.”","“Tôi đi chuẩn bị. Báo cho các thành viên L.G.D. khác đi.”","“Được. Amiya, mười phút nữa ta xuất phát từ đây.”","“Vâng.” Amiya nhìn ra ô cửa, về phía sa mạc mờ mịt. <i>Mọi người… xin hãy bình an…</i>"],"bg":"bg_lungmen_m","cast":[["Amiya","op:char_002_amiya"],["Ch'en","op:char_010_chen"],["Kal'tsit","op:char_003_kalts"],["Hoshiguma","op:char_136_hsguma"]]},{"c":"4-6","t":"Ngu muội","p":["“Đến rồi.” Amiya nhìn quanh. “…Nơi này u ám quá.”","Thành phố bỏ hoang nằm im lìm giữa sa mạc như xác một con thú khổng lồ. Những tòa nhà đổ nghiêng, những đại lộ phủ đầy cát, những khối Originium đen bóng nhô lên từ mặt đường như những chiếc răng gãy.","“Tin tức có nhắc gì đến nơi này không?” Ch’en hỏi.","“Không có,” Hoshiguma đáp. “Nhìn thế này thì Ursus đã quyết định bỏ mặc nơi này.”","“Một thành phố bị bỏ hoang, hả… Nếu thành phố này đã thành cứ điểm của Reunion, nó sẽ chỉ gây thêm ngày càng nhiều rắc rối cho Lungmen.”","“Nó quá gần Lungmen,” Hoshiguma nói. “Nếu Skullshatterer nhận lệnh từ nơi này, ta không thể làm ngơ được. Nhưng mà… rốt cuộc chuyện gì đã xảy ra với phần này của Chernobog? Sau khi trúng Catastrophe, nó không thể nào di chuyển xa đến thế. Sao nó lại xuất hiện ở đây?”","“Theo dữ liệu quan sát bọn em thu thập… chuyện này xảy ra sau Catastrophe,” Amiya nói. “Nghĩa là phân khu này chỉ bị phá hủy sau khi đã đến được đây.”","“Hah. Có vẻ Rhodes Island có vài Catastrophe Messenger giỏi đấy,” Hoshiguma nói. “Thận trọng là tốt. Suốt đường đến đây ta bị đám côn đồ vô tổ chức phục kích… Như kền kền lượn trên đầu, tìm xác thối giữa phế tích. Nổi da gà.”","“Em đã xác nhận tọa độ. Ta phải đi sâu hơn nữa— Nhưng nhìn địa hình thì không thể di chuyển toàn bộ lực lượng cùng lúc được.”","“Ta đang đến gần khu vực dày đặc Originium rồi sao?”","Trên một mái nhà cao phía xa, có một bóng người đứng nhìn xuống. Mái tóc dài, áo choàng phủ kín. Người đó nhìn Ch’en một thoáng, rất ngắn.","<i>Ta không ngờ em lại ở đây.</i>","“Ch’en, cô nghĩ sao…” Hoshiguma quay sang. “Ch’en?”","Ch’en đứng như hóa đá, mắt dán vào mái nhà đã trống không.","“Sao lại…”","“…! Ch’en, cô đi đâu vậy?!”","Ch’en đã lao đi, không một lời.","“Chết tiệt, cô ấy chạy mất rồi! Đó là ai vậy…”","“…Em cũng không nhìn rõ!” Amiya nói. “Nhưng bóng dáng đó trông giống như… Ta phải đuổi theo cô ấy…”","“Đứng lại!”","Một toán Reunion chặn ngang đường. Đứng đầu là một gã cao lớn, trang bị khác hẳn đám côn đồ thường.","“Đúng lúc thật…!” Hoshiguma giương khiên. “Gã đó không phải tay sai bình thường… Và… mấy con sên Originium từ đâu bò ra thế kia?”","“Những sinh vật đó… trông như sắp phát nổ!”","“Doctor! Đảm bảo các operator cẩn thận tối đa!!”","","“Đã hạ được quân Reunion!”","“Hừ. Chỉ là chướng ngại vật mà lì thật.” Hoshiguma nhìn quanh. “…Không thấy Ch’en đâu.”","“Rắc rối to rồi…”","“Cô ấy cũng không trả lời máy! Chậc… Cái tính này của cô ấy chưa bao giờ thay đổi. L.G.D.! Tất cả, chuẩn bị theo tôi—”","“Không, thanh tra Hoshiguma,” Amiya nói. “Chị nên để bọn em lo. Ta đang đến gần khu dày đặc Originium do Catastrophe để lại… Nếu đi xa hơn, người khỏe mạnh có nguy cơ nhiễm Oripathy. Hậu quả quá nghiêm trọng. Hơn nữa, là người Infected…”","“Hah. Với vóc dáng bé xíu của cô, cố đọc diễn văn nghiêm túc trông dễ thương ghê.”","Amiya đứng sững. “…Ơ? Hả?!”","“Hahaha, tôi chỉ trêu cô thôi.” Hoshiguma vỗ nhẹ lên đầu cô bé. “Nhưng cô không cần thuyết phục tôi. Tôi hiểu nỗi lo của cô.” Cô ta quay lại, giọng vang như sấm. “L.G.D.! Chúng ta sẽ là tấm khiên của Rhodes Island! Chặn lối vào, không cho một tên Reunion nào ra vào! Để các chuyên gia lo vấn đề này!”","“Thanh tra…”","“Ôi, cứ gọi tôi là Hoshiguma.” Cô ta nhìn Amiya, nụ cười tắt dần, chỉ còn lại sự nghiêm túc. “Đi đi. Xin hãy chăm sóc Ch’en. Nhớ đưa cô ấy về nguyên vẹn.”","“Em sẽ làm, chị Hoshiguma…! Em thề sẽ đưa cô Ch’en về an toàn…!”","“Các cô cũng nhớ giữ an toàn đấy.”","“Vâng!” Amiya quay sang Doctor. “Doctor, xin hãy theo em. Rhodes Island, đi thôi!”","<i>Chờ em, cô Ch’en… Frostleaf, Meteorite, Jessica… Mọi người phải cố lên!</i>","","Ở Rhodes Island, đội y tế vừa đưa về một đội trinh sát.","“Bọn tôi đã đưa về được đội trinh sát liên lạc sau cùng. Tình trạng… rất tệ…”","Kal’tsit cúi xuống bên chiếc cáng. Người operator nằm đó, da tím tái, những ngón tay đen sạm.","“Đỏ da, hạ thân nhiệt, hoại tử…” Cô ta nhíu mày. “Chuyện gì đang xảy ra vậy?”","“Ngh…”","“Bị tê cóng hoàn toàn…?”"],"bg":"bg_cher_2","cast":[["Hoshiguma","op:char_136_hsguma"],["Amiya","op:char_002_amiya"],["Ch'en","op:char_010_chen"],["Kal'tsit","op:char_003_kalts"]]},{"c":"4-7","t":"Cùng có lợi","p":["“Nơi này… đầy xác Reunion.”","Amiya dừng lại bên một thân hình nằm sấp. Máu từ vết thương đã đông cứng thành băng, nhưng những phần khác trên cơ thể vẫn nguyên vẹn.","“Đây là kỹ thuật của Frostleaf. …Đống đổ nát đằng kia trông như do chất nổ gây ra. Có lẽ là Meteorite.” Cô bé nắm chặt tay. <i>Frostleaf… Jessica… Meteorite… Em chắc họ vẫn còn sống…</i>","“Amiya, tất cả các đội cứu hộ đã về đến Rhodes Island,” Kal’tsit báo. “Ta đã đưa về mọi đội trinh sát, trừ đội của Meteorite. Không mất operator nào trong nhiệm vụ này, nhưng… tất cả đều bị tê cóng ở các mức độ khác nhau. Em phải lưu ý điều này.”","“…Tê cóng?”","“Mọi đội trinh sát đều quan sát thấy một nhóm Reunion đặc biệt lang thang trong thành phố. Không giống đám lính Reunion liều mạng ta quen đối phó, nhóm này có lối chiến đấu riêng. Cẩn thận.”","“Em… Em hiểu rồi.”","“Doctor, tôi nói rõ chưa?”","“Tôi hiểu.”","“Tốt. Tôi cũng có việc phải làm. Amiya, dù Doctor có giúp ích đến đâu, em cũng không thể quá dựa dẫm vào một người.” Kal’tsit ngừng lại. “Và chú ý nhẫn.”","“Em biết.”","Khi cuộc gọi kết thúc, Amiya quay sang Doctor, cười khẽ. “Thật ra bác sĩ Kal’tsit lo cho Doctor nhiều lắm.”","Rồi nụ cười tắt. Từ những ngả đường xung quanh, bóng mặt nạ trắng đã hiện ra.","“Trước khi ta kịp nhận ra… thú dữ đã nhe nanh.”","“Đường lui của ta bị cắt rồi…”","“Vâng… Chúng sẽ làm mọi cách để ta không thoát được. Nhưng ta không đến đây để chạy trốn. Rhodes Island sẽ xuyên thủng hàng ngũ của chúng. Ta sẽ cứu đội của Meteorite!”","","Ở đài chỉ huy Rhodes Island, Kal’tsit bật một kênh liên lạc khác.","“Projekt Red, nghe rõ không? À, ừ. Đúng vậy. Tôi sẽ gặp cô ở lối vào phía đông khu ổ chuột. Ừm. Chỉ hai chúng ta thôi.” Cô ta khoác áo choàng lên vai. “Không sao đâu. Chỉ hai chúng ta là quá đủ để đối đầu với Reunion rồi.”","","“Phải đánh qua bao nhiêu Reunion mới đến được điểm quan sát này…” Amiya thở dốc, rồi khựng lại. “Hả…? Đó là… cô Ch’en? Cô Ch’en!”","Giữa một khoảng sân rộng, Ch’en đứng một mình, thanh kiếm nhỏ máu. Xung quanh cô ta là xác Reunion nằm la liệt.","<i>Sao lại có nhiều xác thế này… Ngần ấy lính Reunion… cô Ch’en một mình làm hết sao?!</i>","Ch’en quay lại. “…! Là cô…”","Cô ta tra kiếm vào vỏ, giọng khàn đặc. “Tôi mất kiểm soát. Xin lỗi… Có lẽ tôi đã sa vào bẫy của địch…”","“Không… Không sao, ta vẫn đúng kế hoạch ban đầu. Chỉ là…” Amiya ngập ngừng. “Người xuất hiện lúc nãy… có phải là Talulah không?”","Ch’en im lặng.","“…Không. Giờ chuyện đó không quan trọng. Linh cảm của tôi sai rồi. Nơi này trông chẳng giống chỗ người đó sẽ ở.” Cô ta đứng thẳng dậy. “Nhiệm vụ vẫn là ưu tiên hàng đầu. …Không có tôi, L.G.D. sẽ khó thực hiện nhiệm vụ tìm kiếm này. Nhất là trong tình hình này… Nó phức tạp hơn tôi tưởng nhiều. Như thế này, một mình đi tiếp là quá liều lĩnh.”","“Cô Ch’en, bọn em cũng mong cô quay về L.G.D. ngay. Lượng lớn Originium còn sót lại từ Catastrophe ở đây rất có hại cho người không nhiễm bệnh. Dù cô đã mang thuốc từ trước, nó cũng không trụ được lâu…”","“Còn cô thì sao?”","“Nhiệm vụ của bọn em là bảo vệ Lungmen và loại bỏ mối đe dọa— Nhưng lý do quan trọng nhất bọn em đến đây là để cứu operator của mình. Rhodes Island không quay lưng với ai cả. Vì vậy, bọn em sẽ tiếp tục chiến đấu.”","Ch’en nhìn cô bé một lúc. “…Tôi sẽ đưa đội của mình nhập với đội cô… nếu tình hình cho phép.”","“Tuyệt quá. Cô Ch’en! Rhodes Island có thể cử một đội hộ tống cô…”","“Không cần.”","Ch’en đi khuất. Amiya nhìn theo, khẽ thở dài. “…Cô Ch’en tự trọng cao thật nhỉ?”","Cô bé quay sang Doctor. “Hửm? Doctor? Đừng lo… Em biết… Rhodes Island lại phải chiến đấu một mình nữa rồi. Nhưng giờ chưa phải lúc buồn đâu. Đi thôi, Jessica và mọi người vẫn đang chờ chúng ta.”"],"bg":"bg_cher_2","cast":[["Amiya","op:char_002_amiya"],["Kal'tsit","op:char_003_kalts"],["Ch'en","op:char_010_chen"]]},{"c":"4-8","t":"Rối loạn căng thẳng cấp tính","p":["“Hửm…? Đây là đâu…” Amiya nhìn quanh. “Ta đang đến gần tọa độ Frostleaf gửi, nhưng… mùi gì kinh khủng vậy. Là mùi thứ gì đó đang cháy…? Reunion đã dẫn ta đến đâu thế này?”","Một luồng sáng lóe lên từ cửa sổ một tòa nhà.","“Chậc! Cẩn thận đánh lén!”","“Tôi… tôi trượt rồi?!” Tên Caster Reunion kêu lên.","“Đừng lo. Ở đây ta an toàn!” tên đồng bọn nói.","“Gưh…”","“S-sao vậy?”","“Gưh… ưrgh… aah…” Tên Caster đổ gục, một lưỡi băng mỏng cắm sau gáy.","“Hắn không trả lời ngươi được nữa đâu,” một giọng nói vang lên từ bóng tối.","“C-cái gì?!”","“Từ tòa nhà đó!” Amiya quay phắt lại. “Khoan, đó là… Frostleaf! Frostleaf, là chị phải không?”","“Đúng vậy. Tôi đã xử lý địch rồi.” Frostleaf bước ra, loạng choạng. “Xin lỗi đã làm cô lo, Amiya. Ugh…”","“Chị bị thương à? Y tế, nhanh lên!” Amiya đỡ lấy cô. “Không thể nào… Sao người chị lại tê cóng hết thế này? Đã xảy ra chuyện gì…”","“Đừng lo, nhẹ thôi. Meteorite và Jessica vẫn ở quảng trường chính. Tạm thời họ an toàn, nhưng khó nói được bao lâu. Tôi đã dụ địch đi, nên Reunion chưa tìm thấy họ.”","“Địch?”","“Chúng ta chưa bị lộ, nên chưa cần lo. Nhưng hắn sắp đến rồi…”","Giọng Mephisto vang vọng khắp các dãy phố, như phát qua loa.","“Cáo con, trốn ở đâu thế? Mau ra đây. Trò trốn tìm của ta sắp kết thúc rồi. Cứ mỗi phút ngươi còn trốn, ta sẽ bẻ thêm một ngón tay của bạn ngươi— Ngươi vẫn định chạy nữa à?”","<i>Mephisto…!</i> Amiya siết chặt nắm tay.","“(Hắn đang dọa thôi. Đừng mắc câu,)” Frostleaf thì thầm.","“(Hắn định làm gì vậy…)”","“Reunion đang di chuyển.”","“Thằng nhóc đó…! Ta phải liên lạc với Meteorite…” Amiya bấm máy. “…Hả? Sao không gọi được? Ta rõ ràng đã qua khỏi vùng ô nhiễm rồi mà…”","“Haizz…” Frostleaf đưa thiết bị của mình ra. “Nhìn này.”","“Thiết bị liên lạc của chị…? …!” Amiya sững sờ. “Nó… đóng băng rồi? Bị sương giá… làm hỏng?”","“Mephisto chẳng là gì cả,” Frostleaf nói. “Có một thứ đang lang thang trong thành phố này… đáng sợ hơn nhiều.”","“Đáng sợ hơn?”","“Yeti. Nếu đụng phải họ, ta sẽ gặp rắc rối lớn.”","“Yeti? Chị nói Biệt đội Yeti sao? Rốt cuộc họ là…?”","“Giờ tôi không có thời gian giải thích. Nhưng chính họ… gây ra nhiệt độ sụt giảm đột ngột, và cả những vết thương của các đội trinh sát. Có vẻ đội này đã lập lãnh địa riêng trong thành phố.”","Amiya ngước nhìn bầu trời. “Trời tối dần rồi. Đây là cơ hội tốt… Ta sẽ băng qua khoảng trống này dễ hơn. Cứu Meteorite và Jessica trước đã.”","“Tôi dẫn đường.”","Họ băng qua quảng trường trong bóng tối chạng vạng. Ở giữa quảng trường có những hình thù kỳ lạ dựng thành hàng, đen sẫm, méo mó.","“Thứ gì ở giữa quảng trường vậy? Em không nhìn rõ… Là… tượng sao? Hình dạng lạ quá… Và mùi này khiến em buồn nôn…”","Frostleaf không trả lời ngay. “…Lối này. Đừng tách ra.” Cô ngừng lại. “Đừng nhìn những thứ đó…”","Rồi cô dừng hẳn. “—Có khách. Hạ chúng trước khi chúng phát hiện ra ta.”","","Một mũi nỏ chĩa ra từ sau đống gạch vụn.","“Tôi biết là cô ở sau đó. Đừng bắn,” Frostleaf nói. “Xem tôi dẫn ai đến này.”","“Meteorite, là bọn em đây!”","“Ai? Đó là… Amiya?!” Meteorite đứng bật dậy. “Amiya! Amiya, cô đến thật rồi! Gặp lại cô mừng quá…”","Rồi gương mặt chị ta tối sầm lại. “…Nhưng cô không nên đến. Toàn bộ chuyện này là một cái bẫy lớn. Không đáng để cô đến cứu bọn tôi. Đây là quyết định sai lầm…!”","“Trách cô ấy bây giờ chẳng ích gì,” Frostleaf nói. “Hơn nữa, dù tất cả mọi người nghĩ cô không cứu được, Amiya vẫn sẽ không bỏ rơi cô.”","“Tôi không trách cô ấy! Chỉ là…” Meteorite thở ra. “Chậc. Xin lỗi, Amiya.”","“Không sao đâu. Em chỉ mừng là mọi người vẫn an toàn.” Amiya nhìn quanh. “Nhưng… Jessica sao rồi?”","Jessica ngồi co ro trong góc, hai tay ôm gối, đôi mắt mở to nhìn vào khoảng không.","“Cô ấy… vẫn còn sốc,” Meteorite nói khẽ. “Lúc đầu tôi định chờ cô ấy khá lên, nhưng… Có vẻ cô ấy đã bị… chấn động tâm lý.”","“Jessica, em có sao không?”","Không có tiếng trả lời.","Amiya quỳ xuống trước mặt Jessica. “Đây là tất cả những gì em làm được… Frostleaf, giúp em. Đặt tay Jessica lên cánh tay em, và giữ chặt ngón tay của cô ấy.”","“…Được.”","“Tốt.” Amiya nhắm mắt lại. Một luồng sáng đen mờ nhạt tỏa ra từ những ngón tay cô bé, len lỏi vào tay Jessica.","Rồi cô bé giật nảy người. “…!!”","“Amiya!”","“Em không sao! Chỉ là… Nnh…” Nước mắt rỉ ra nơi khóe mắt Amiya. “Nỗi buồn sâu thẳm quá… Hơi mơ hồ, nhưng…”","Trong một nơi rất sâu, nơi không ai khác nghe thấy, có một giọng nói đang gọi.","<i>Jessica!! Không sao rồi… Em phải mạnh mẽ lên, Jessica…!</i>","Jessica chớp mắt. “…? …Amiya…?”","“Chị ở đây.”","“Amiya… Amiya…” Jessica òa khóc, ôm chầm lấy cô bé.","“Ngoan nào… Mọi chuyện sẽ ổn thôi.”","“Jessica… Cô ổn chứ…?” Meteorite hỏi.","“Amiya… Em đã… Em xin lỗi… Em không nghĩ… Em không nghĩ là…” Jessica nấc lên. “Những… những thứ đó… Auugh…”","“Không sao rồi… Chị hiểu cảm giác đó mà. Phải, chị cũng từng trải qua… Muốn chạy, mà chân không nhấc lên được… Muốn hét, mà không thốt ra tiếng… Chị hiểu những gì em đã trải qua, Jessica… Chị cũng từng như vậy.”","Amiya lau nước mắt cho cô gái.","“Thử đứng dậy xem. Em không cần sợ nữa… Vì giờ chúng ta ở cùng nhau rồi. Em không cô đơn. Bọn chị sẽ luôn ở bên em. Cùng về Rhodes Island nhé. Chị Franka và chị Liskarm đang chờ em đấy.”","Jessica nhìn cô bé thật lâu. Rồi gật đầu, thật mạnh. “…Vâng!”","Frostleaf nhìn Amiya, ánh mắt khác hẳn. “Amiya… Cô… vừa làm gì vậy…”","Amiya đặt một ngón tay lên môi. “Suỵt… Giữ bí mật với bác sĩ Kal’tsit nhé.”"],"bg":"bg_cher_2","cast":[["Amiya","op:char_002_amiya"],["Frostleaf","op:char_193_frostl"],["Meteorite","op:char_219_meteo"],["Jessica","npc:char_259_Jessica_1"],["Mephisto","npc:char_1507_Mephisto_1"]]},{"c":"4-9","t":"Xấu xa đến tận xương","p":["“Meteorite…” Amiya hạ giọng. “Rốt cuộc Jessica đã nhìn thấy gì…? Chị có ở cùng cô ấy không?”","“…Tốt nhất cô đừng biết,” Meteorite đáp. “Nó không liên quan đến chiến dịch… nên giờ đừng bận tâm.”","“Còn định trốn đến bao giờ, lũ sâu bọ Rhodes Island?!”","Giọng Mephisto vang lên, gần hơn lần trước.","<i>(…! Mephisto! Hắn tìm thấy ta rồi sao?)</i>","“(Đừng phát ra tiếng. Chưa đâu. Lại là trò của hắn thôi,)” Frostleaf thì thầm.","“Ôi, vẫn chưa muốn ra à?” Mephisto cười. “Đừng tưởng ta không thấy viện binh của các ngươi đến. Thôi kệ. Ta có thứ muốn cho các ngươi xem. Chắc chắn các ngươi sẽ thích.”","Giọng cậu ta trở nên mơ màng, như một diễn viên đang đọc độc thoại.","“Giờ nhìn lại… Ngay từ đầu chúng ta đã định chiếm Chernobog… Chúng ta đã chờ lâu lắm, lâu lắm… và cuối cùng thời khắc của chúng ta đã đến… Khoảnh khắc chúng ta trả thù Ursus! Trả thù những kẻ đã ngược đãi người Infected chúng ta!”","@cg:bg_0_guard","“Nhưng còn những kẻ ở thành phố phụ này thì sao? Chúng bỏ chạy. Phản ứng khá nhanh đấy. Chạy trước khi chúng ta kịp ra tay. Tự tách mình ra, rồi chạy nhanh nhất có thể— Nhưng chúng mong chạy đến đâu? Đồng chí của chúng ta đã thâm nhập mọi quận từ lâu, chờ đợi cơ hội. Cuối cùng, chúng ta đuổi kịp chúng, và ban cho chúng hình phạt xứng đáng.”","“Những kẻ hèn nhát, những kẻ gây tội ác ấy, chúng ta nên làm gì với chúng? Đơn giản thôi — chúng ta biến chúng thành tấm gương! Một lời tuyên bố rằng mọi bất công với người Infected sẽ bị thanh trừng… Phải, đó là biểu tượng của Reunion Movement… Hãy để chúng biến thành những hình nộm kinh hoàng, từng kẻ một!”","“Ngươi, đốt hình nộm gần đó đi! Hãy để ánh sáng xuất hiện!”","“Rõ!”","“Đến đây, thắp sáng cả thành phố này! Để Rhodes Island thấy chuyện gì xảy ra với những kẻ áp bức hèn nhát!”","“(—Đừng!)” Meteorite rít lên.","Doctor đã đưa tay ra trước khi kịp nghĩ, che kín đôi mắt Amiya.","“Doctor…?!”","“Đừng nhìn!”","Ngọn lửa bùng lên giữa quảng trường. Và những hình thù kỳ lạ mà Amiya nhìn thấy lúc chạng vạng, những bức “tượng” méo mó, bắt đầu cháy.","Frostleaf đứng im, gương mặt trắng bệch. “…Một địa ngục rực lửa của ác ý và điên loạn…”","Amiya đứng im dưới bàn tay của Doctor một lúc lâu.","“…Doctor, buông em ra. Em không sao.” Giọng cô bé bình thản đến lạ. “…Không, Doctor phải để em nhìn. Một ngày nào đó, em phải bắt hắn chịu trách nhiệm cho những gì hắn đã làm. Hơn nữa, trước kia em từng…”","Doctor buông tay.","Amiya nhìn. Và cô bé không quay mặt đi.","@cg:avg_40_1","“Tại sao… Tại sao…” Jessica run rẩy.","“Jessica, bình tĩnh.” Meteorite nghiến răng. “—Thằng khốn đó!”","“…Quá tàn ác…” Frostleaf thì thầm.","“Mùi thịt cháy…” Amiya nói khẽ.","“Định trốn đến bao giờ đây, cô thỏ Chernobog thân yêu của ta?” Mephisto cười. “Ta thấy đám tạp nham của ngươi lén lút quanh đây, tưởng các ngươi định làm gì đó. Hóa ra chỉ đến xem kịch… Chán thật. Mà có vẻ ngươi dẫn theo cả một đoàn nhỉ?”","Amiya bước ra khỏi chỗ nấp.","“Ngươi làm tất cả chuyện này sao?”","“Đương nhiên rồi~” Mephisto dang tay. “Không dùng chút chiến thuật khủng bố thì làm sao giảm thiểu tổn thất được? Biến mười phần trăm này thành tấm gương… thì chín mươi phần trăm còn lại sẽ ngoan ngoãn xếp hàng. Thế này, các ngươi thấy đấy, có thể coi là cách tốt nhất để cứu người.”","Amiya im lặng rất lâu.","“…Doctor,” cô bé nói, không quay đầu. “Em không còn là em của ngày trước nữa. Dù Doctor có thể không nhớ… Phải… Hồi đó, em rụt rè, yếu đuối, dễ sợ hãi… Không có Doctor, em không thể bước tiếp… Có lẽ bây giờ em trông cũng vẫn như vậy.”","“Nhưng khác biệt là, giờ em đã thấy quá đủ bi kịch rồi. Em không muốn thấy chuyện như thế này xảy ra thêm lần nào nữa. …Nhưng sẽ chẳng có gì thay đổi nếu em không đối mặt với hiện thực!”","Cô bé tháo găng tay ra. Những chiếc nhẫn trên ngón tay bắt đầu tỏa sáng.","“Dù sao, em phải tự nhắc mình. Em không thể lùi bước… Em phải tiếp tục chiến đấu!”","","“Frostleaf, cẩn thận! Đừng xông lên xa thế!”","“Tôi biết mình đang làm gì!”","“Aaah! Aaaagghhh!”","“Ả chém xuyên qua khiên bằng một lưỡi khí lạnh sao? C-cái gì?!”","“Cút!”","“Amiya! Frostleaf đã phá vỡ đội hình địch, đang lao thẳng về phía chỉ huy của chúng!”","“Sniper, Caster, yểm trợ Frostleaf!”","“Ồ…?” Mephisto nheo mắt nhìn cô gái đang lao về phía mình. “Và ngươi muốn gì, cáo con?”","“Tao muốn mày gào thét và van xin,” Frostleaf nói, giọng lạnh hơn cả lưỡi rìu trong tay. “Tao muốn mày trả giá… bằng mạng sống.”","“Tránh đường!” Amiya hét.","Những sợi sáng đen quất ra từ tay cô bé. Đám Reunion chắn đường bị hất văng.","“B-Black Arts… N-nhanh, chạy đi! Tôi không muốn thành như tay sai của Mephisto…!”","“Mephisto, bọn ta sẽ không để ngươi thoát!”","“Heh. Lẽ ra ta phải đoán đám tay chân này không đủ để cản các ngươi.”","“Ngươi sẽ phải trả giá cho những gì ngươi đã làm, đồ bệnh hoạn!”","“Mày không thoát được đâu,” Frostleaf nói, chỉ còn cách Mephisto vài bước.","“Cáo con, ngươi đến gần hơi quá rồi đấy.”","“Vì tao là kẻ sẽ lấy mạng mày. Những kẻ không tôn trọng sự thiêng liêng của sự sống… không xứng đáng có sự sống.”","“Hehhh…” Mephisto mỉm cười. “Vậy sao.”","Frostleaf khựng lại. “?! Cái gì… Chân tôi…?”","Chân cô đã bị đóng băng dính chặt xuống mặt đất. Lớp băng đen bóng đang bò dần lên đầu gối.","“Amiya! Quân Reunion xuất hiện từ mọi hướng!” Meteorite hét. “Dù không đông lắm… …Không xong rồi, là Biệt đội Yeti… Họ… đến đủ cả rồi!”","“Được rồi, ta cần giới thiệu với các ngươi một người bạn mới.” Mephisto cúi chào như người dẫn chương trình. “E hèm~ Tiếp theo, xin một tràng pháo tay cho ngôi sao thật sự của buổi diễn… Cơn ác mộng của lãnh nguyên tây bắc, chủ nhân của Yeti… Cô… Frost… Novaaaaaaa!”","“Cô ấy sẽ đóng băng từng thớ thịt, từng giọt máu của các ngươi… Từng. Chút. Một!”","Từ màn sương lạnh buốt, một người phụ nữ bước ra. Mái tóc trắng như tuyết, đôi tai dài trắng muốt, chiếc áo choàng phủ một lớp sương giá. Mỗi bước chân của cô ta để lại một vệt băng trên nền đá. Và theo sau cô ta, những bóng người mặc áo giáp dày lặng lẽ tản ra, như những bóng ma của mùa đông.","“…Ta phải ra khỏi đây…!” Amiya lẩm bẩm.","@cg:avg_40_2","FrostNova không nhìn Rhodes Island. Cô ta nhìn Mephisto.","“Mephisto… Lẽ ra ta phải để ngươi chết cóng từ từ trên lãnh nguyên, đồ tâm thần.”","“Ôi chao, đáng sợ quá, đáng sợ quá~ Nhưng Rhodes Island đang ở ngay trước mặt ta kìa.”","“Frostleaf…” Amiya gọi. “Lùi lại.”","Frostleaf nhìn xuống đôi chân đã đóng băng đến tận đầu gối. Rồi cô ngẩng lên, mỉm cười.","“Amiya, đưa họ đi.”","“Em không đồng ý! Người đó… người đó là…!”","“Cô ta… đang tiến về phía tôi. Ta không thắng được đâu.” Frostleaf thở ra một làn khói trắng. “Hah… Dù tôi muốn sống thêm một chút… Tôi mừng là đã có cơ hội gặp tất cả mọi người. Nhanh lên.”","“Frostleaf?!”","“Nhanh lên!”","FrostNova dừng lại trước mặt Frostleaf, nhìn xuống cô gái nhỏ đang bị băng giá giam giữ.","“Đừng lo, Rhodes Island. Ta sẽ cho các ngươi một cái chết không đau đớn.”"],"bg":"bg_cher_2","cast":[["Mephisto","npc:char_1507_Mephisto_1"],["Amiya","op:char_002_amiya"],["Frostleaf","op:char_193_frostl"],["Meteorite","op:char_219_meteo"],["FrostNova","npc:char_1505_frstar_1"]]},{"c":"4-10","t":"Ngọn lửa tàn","p":["“Nhiệt độ… đang giảm mạnh?” Jessica run rẩy. “Băng đang hình thành trên mặt đất… Lạnh quá… Không thể tin được… cả hình nộm đang cháy cũng đóng băng rồi…! Lửa tắt hết… Mây đen phủ kín bầu trời… Aaahh…!”","@cg:avg_40_2","“Đừng hoảng!” Amiya quát. “Jessica, operator Blacksteel!”","Jessica giật mình, rồi đứng thẳng dậy. “…Vâng!”","“Giữ vị trí!”","“Rõ!”","“Frostleaf, cô làm gì vậy?!” Meteorite hét.","Quanh Frostleaf, không khí đang xoáy lại. Hơi lạnh từ khắp quảng trường cuộn về phía cô, hút vào thân thể nhỏ bé ấy.","“Cô ấy… đang hút hết nhiệt quanh mình!” Amiya kêu lên. “Em không biết cô ấy có thể ảnh hưởng đến một vùng rộng như vậy!”","“Heh… Chủ nhân của Yeti…” Frostleaf cười khẽ, môi đã tím tái. “Tôi chưa từng gặp… ai có thân nhiệt thấp hơn tôi.”","“Frostleaf!”","“Meteorite… Nói thật, tôi định… đánh lạc hướng cô ta… câu chút thời gian cho mọi người… Nhưng… cơ thể tôi… đóng băng hoàn toàn rồi. Tôi không… nhấc chân lên được nữa.”","“Frostleaf!!”","“Amiya, đưa họ đi, đánh mở đường ra khỏi đây. Chưa đầy một phút nữa, chỉ huy địch… sẽ đóng băng cả quảng trường này. Đừng để tôi chết vô ích.”","“Amiya… Ta không thể… Tôi sẽ không bỏ cô ấy lại!” Meteorite gào lên.","“Em hiểu,” Amiya nói. “Em sẽ không bỏ Frostleaf lại. Em sẽ không… bỏ lại bất kỳ ai!”","Cô bé quay sang, giọng dứt khoát như một mệnh lệnh. “Em sẽ cầm chân các đội địch. Meteorite… trông cả vào chị đưa Frostleaf về!!”","“Rõ!”","“Doctor! Xin hãy chỉ huy các đội!”","“Đã sẵn sàng!”","","Frostleaf nhìn người phụ nữ tóc trắng đứng trước mặt.","“…Giờ nghĩ lại… tôi mới dùng Arts này có một lần.” Cô thì thầm. “‘Nơi nào có máu…’”","“Hah,” FrostNova nói. “Vậy ngươi muốn dùng băng của ngươi… để chống lại băng của ta sao?”","“Nnh…!”","“Làm sao ngươi làm được khi lưỡi ngươi còn không cử động nổi?”","“Ngươi…”","FrostNova quay lại, giơ tay. “Biệt đội Yeti, tản ra.”","“Rõ.”","“Các anh em của ta… Lùa chúng ra, và đóng băng máu của chúng.”","“Đã hiểu.”","Amiya bước lên phía trước, hai tay mở rộng. Giọng cô bé vang lên, trầm và xa lạ, như không phải giọng của một đứa trẻ.","“‘…Tâm trí ngươi không giấu được gì trước ta.’”","“Thần chú?” Một thành viên Yeti nheo mắt. “Thỏ của Rhodes Island… Những đường đen…? Cái quái gì vậy? C-cái loại Arts gì thế— K-khoan, sao thứ đó… lại len qua được bức chắn của ta?! Đừng—”","“…Aaaaaghh!!!! C-cơ thể tôi! Nó đang cháy…! Nó đang cháy!”","“Meteorite!”","“Tôi biết!” Meteorite lao về phía Frostleaf. “Xin cô, tiếp tục đánh lạc hướng chúng!”","“K-k-không… lạnh quá…!”","“Nnngh… đau quá!”","“…Gaah… Không, đừng nữa…”","FrostNova quay phắt lại, nhìn những đồng đội đang quằn quại dưới những sợi sáng đen. “…! Nhanh! Đừng để chúng làm hại đồng chí của ta thêm nữa!”","“Rõ!”","Cô ta nhìn Amiya, ánh mắt thay đổi. “Originium Arts của ngươi… rất đáng gờm.”","Frostleaf vẫn cố giơ lưỡi rìu lên. “Nnh… aagh… Chết tiệt… Tránh xa… tao ra…”","“Ta sẽ không cho ngươi cơ hội dùng Arts đâu, cô bé.” FrostNova đặt một tay lên trán Frostleaf, nhẹ như vuốt tóc một đứa trẻ. “Giờ, nhắm mắt lại và ngủ đi. Ta sẽ sớm giải thoát ngươi khỏi đau đớn.”","“Mụ phù thủy này…!” Meteorite gầm lên.","FrostNova ngẩng lên, nhìn thẳng vào Amiya.","“…Ta đoán ngươi là Amiya.”","Amiya đứng sững.","“…Ta thích ánh mắt của ngươi. Đó là ánh mắt của một chiến binh.” FrostNova ngừng lại. “Ta xin lỗi…”","“Tại sao cô lại…”","FrostNova bắt đầu hát.","Giai điệu ấy rất khẽ, rất chậm, như một bài hát ru. Và theo từng nốt nhạc, tuyết bắt đầu rơi.","“…Tuyết rơi sao?” Amiya ngước lên.","<i>“Ngủ đi, các con của ta. Ngủ đi. Búp bê nhím và gấu bông…”</i>","“Giai điệu kỳ lạ này…” Meteorite nói. “…Cô ta đang thi triển Arts!”","<i>“Lặng lẽ chìm vào bóng đen… Những con rối và búp bê vỡ nát của ta…”</i>","Giữa không trung, những mảnh băng đen hiện ra từ hư vô, xoay tròn, rồi chậm rãi rơi xuống.","“Thêm nhiều mảnh băng đen đang xuất hiện từ không khí?!” Amiya hét.","“Những mảnh băng đang rơi xuống đất!” Jessica kêu lên.","“Chết tiệt, mặt đất đóng băng ở mọi nơi mảnh băng rơi xuống…? Băng đen… Nó đang lan ra…?!”","“Tinh thể băng đang ăn mòn mọi thứ xung quanh ta!” Amiya quay sang. “Đừng để cô ta hát hết bài!!”","“Rhodes Island, dốc toàn lực!”","","“Khụ khụ…” Frostleaf ho ra những tinh thể băng.","“Meteorite! Ta đã đẩy lùi được Biệt đội Yeti!” Amiya hét, rồi khựng lại. “Nhưng…”","FrostNova vẫn đứng giữa quảng trường, áo choàng tung bay trong gió lạnh.","“Có vẻ ta đã đánh giá thấp các ngươi, Rhodes Island. Có lẽ ta đã nương tay hơi nhiều.”","<i>Mình không còn cảm thấy ngón tay nữa… Chết tiệt…</i> Amiya nhìn quanh. “…Chuyện gì vậy…? Dòng khí lạnh… vẫn đang tụ quanh cô ta?”","“Lần này… các ngươi sẽ không may mắn như vậy đâu.”","“…?! Không xong rồi…! Cô ta định hút toàn bộ băng quanh ta rồi giải phóng cùng lúc sao?!”","FrostNova lại cất tiếng hát. Lần này, giai điệu không còn dịu dàng nữa.","“…Cô ta sẽ hút hết nhiệt khỏi cơ thể chúng ta! Arts này ở một quy mô hoàn toàn khác so với lúc nãy…!”","“Hãy để mọi thứ kết thúc,” FrostNova nói. “Hãy để cơn giận của các ngươi được chôn vùi dưới lớp sương thuần khiết nhất.”","“…Nnngh…!”","Rồi giai điệu ngắt quãng.","“…?!” FrostNova nhíu mày. “Có thứ gì đó… đang ngăn hơi lạnh tụ lại…”","“…Gah…” Frostleaf, đôi chân vẫn bị băng giam giữ, đã giơ được lưỡi rìu lên, cắm nó thẳng vào dòng khí lạnh đang xoáy.","“Là ngươi làm sao?”","“Chẳng phải tao đã nói rồi sao… Tao sẽ không để mày… lại gần thêm nữa…!”","“…Ngươi dùng Arts của chính mình để làm nhiễu dòng lạnh của ta sao?” FrostNova nhìn cô gái nhỏ, và có một thứ gì đó rất giống sự dịu dàng thoáng qua trong mắt cô ta. “…Đứa trẻ ngoan.”","“Frostleaf dùng lưỡi rìu cắt đứt dòng khí lạnh…!” Amiya kêu lên. “Nhưng, nhưng… với tình trạng đó, cô ấy không trụ được lâu! Lưỡi rìu… sắp gãy rồi!”","“…Thế là quá đủ,” Meteorite nói. “Đây là cơ hội cuối cùng! Amiya… chính là lúc này! Yểm trợ tôi!”","“Cẩn thận!”","“Rõ!”","“Bắt đầu bắn — áp chế động tĩnh của Reunion! Meteorite, đi!”","“Đang đến…!”","“Cái gì?! Địch… đang lao về phía ta? Không, ả… ả đang lao thẳng về phía FrostNova?!”","“Đừng hòng! Bắn!”","“Agh…!” Meteorite lảo đảo.","“Meteorite!!”","“Đừng lo, không trúng trực diện!”","“Ả… ả vẫn chạy được?! Chết tiệt! Đã bảo rồi! Mày sẽ không bao giờ đến được chỗ Yeti đâu! Tiếp tục bắn! Đừng cho ả kẽ hở!”","“…Không xong!” Một mũi tên cắm vào vai Meteorite. “Gaah…!”","“Khônggg!! Chị ấy… chị ấy trúng tên rồi… Không thể nào…” Jessica gào lên.","“…Chỉ là vết xước thôi!” Meteorite vẫn chạy. “Muốn cản tôi thì phải giỏi hơn thế!!”","<i>Thêm nữa… Mình phải làm thêm nữa…</i> Amiya nhìn quanh. Và cô bé thấy FrostNova khẽ ho.","“Khụ khụ…”","“…!” <i>Dòng khí lạnh… vừa dao động một thoáng?</i> Amiya nhắm mắt lại, cảm nhận. <i>Khoan đã… Dòng khí đó đến từ đâu… —! Mình biết cảm giác này…! Lẽ nào…?!</i>","“Mình phải thử thôi! Mình phải bắn trúng nó…! Mọi người, tin em!”","Một luồng sáng đen xé toạc không khí, đánh thẳng vào một bức tường đổ nát ở rìa quảng trường. Một khối Originium đen cắm trong góc tường vỡ tan thành bụi.","“…? Thủ lĩnh Rhodes Island… Ả dùng Arts phá vỡ khối Originium ta cài sao? Mờ mịt quá…”","“Em biết mà! FrostNova tạo ra dòng khí lạnh bằng cách cài Originium!” Amiya hét. “Meteorite!! Cơ hội của chị đây!”","“Frostleaf…” Meteorite nghiến răng, lao qua những mảnh băng đang vỡ vụn. “Tôi… Tôi hứa sẽ cứu cô!! Vậy nên, chờ tôi… Làm ơn chờ tôi!”","","“Tỉnh dậy!”","“Nnh…?”","“Tôi bắt được cô rồi! Lên đây! Nhanh! Bám chặt lấy tôi!”","“Ai…” Frostleaf mở mắt, mơ hồ. “Meteo…rite?”","“Ai cho cô đóng vai anh hùng hả?!” Meteorite hét, một tay bế xốc cô gái lên, tay kia đập vỡ lớp băng cuối cùng quanh chân cô. “Cô nghĩ tôi có thể ngồi yên nhìn cô chết sao?”","“Thả tôi xuống… Tôi đâu phải… thú cưng…”","“Tôi sẽ không buông cô ra đâu! Amiya! Jessica!!”","“…Được!” Jessica hét. “Mọi người, ra khỏi đây thôi!”","“Meteorite, đưa Frostleaf đi trước. Em sẽ yểm trợ đường rút!”","“Hiểu rồi!”","Meteorite chạy, Frostleaf trên tay, máu từ vai nhỏ thành vệt dài trên tuyết.","“Hộc… Hộc… Frostleaf… cố lên…! Đừng chết… cô không được chết!!”","“Đừng lo… cô không dễ tống khứ tôi vậy đâu…”","“Trời ạ, cả cô lẫn Amiya! Sao cả hai lại như thế chứ?! Mạnh đến đâu đi nữa… thì cả hai cũng chỉ là trẻ con thôi!”","“Cô vẫn còn coi tôi là trẻ con…?” Frostleaf cười khẽ. “…Nếu đánh đổi mạng sống để cứu được tất cả mọi người, tôi nghĩ đó là một vụ làm ăn khá hời.”","“Cô… Nhớ lời tôi đấy! Nếu cô còn dám làm chuyện như thế này lần nữa… Nếu cô còn dám… Tôi sẽ…”","“Haizz… Xin lỗi.” Frostleaf tựa đầu vào vai chị ta. “Chạy đi, Meteorite. Đừng… ngoái lại…!”","","“Nhanh lên! Đi đi!!” Amiya hét. “Sơ tán khỏi khu vực này ngay! Bảo vệ y tế và người bị thương! Sniper…! Nhắm vào những hình nộm kia. Tiếp tục bắn!! Phá vỡ đội hình của chúng! Đánh sập cả tòa nhà để che đường rút!”","Những tiếng nổ liên tiếp vang lên. Một tòa nhà đổ sập, cuốn theo những đám bụi khổng lồ.","“Khụ khụ… Tiếng nổ làm khói mù dày thêm…! Cơ hội đây! Di chuyển!! Mọi người, rút khỏi quảng trường!!”","","Khi bụi lắng xuống, quảng trường đã trống không. FrostNova đứng một mình giữa những hình nộm đã tắt lửa.","“Vậy là… chúng thoát rồi.” Cô ta ho, những tinh thể băng rơi khỏi môi. “Khụ… Khụ…”","Cô ta không quay đầu lại. “Ông đứng xem bao lâu rồi?”","Từ bóng tối sau lưng cô ta, một giọng nói trầm và nặng như đá vang lên. “Chỉ vài phút. Những chiến binh đó đáng được ca ngợi.”","“Chậc.”","@cg:avg_40_3","“Cẩn thận. Cơ thể cô không được tốt lắm.”","“…Ta không cần ông nhắc.” FrostNova quay lưng. “Ông cứ làm việc của ông đi, lão già. Ta sẽ đuổi theo Rhodes Island. Phải loại bỏ chúng trước. Chỉ khi đó, chúng ta mới có thể… tiến đến Lungmen.”","Bóng người khổng lồ phía sau không đáp.","","“Phù… Haah…” Amiya dừng lại, chống tay lên đầu gối. “Sắp đến điểm rút rồi. Doctor, chúng ta…”","“…Amiya!!” Meteorite hét lên, tay giơ cao thiết bị liên lạc. “Cuối cùng cũng liên lạc được với L.G.D.!! Là liên lạc khẩn cấp!!”","“Cô Ch’en!!”","“Nghe… đây…” Giọng Ch’en đứt quãng, lẫn tiếng nổ phía sau.","“Cô Ch’en? Cô có nghe rõ em không?”","“…Lungmen…”","@cg:avg_40_4","“…Chuyện gì vậy?!”","“…Tôi đã an toàn. Nhưng…” Một quãng lặng dài. “…Reunion đã chiếm một cơ sở quan trọng của chúng tôi, và đang cưỡng ép mở một lối đi giữa khu ổ chuột và nội thành.”","“Amiya…”","“Lungmen… đang gặp nguy.”","@cg:item_tll","@bg:bg_cher_3","Ở một nơi rất xa, Mephisto đang nói vào thiết bị liên lạc, giọng ngọt như mật.","“W đã dụ được Lungmen và Rhodes Island vào đúng bẫy của chúng ta. Đúng vậy. Chúng sẽ không thoát được đâu. Faust và Crownslayer đã phá vỡ phòng tuyến của chúng ở một điểm. Như cô nói, đây sẽ là lối mở để chúng ta tràn vào Lungmen. Chúng ta sẽ đặt phục kích ở mọi góc phố. Con đường đến Lungmen sẽ đỏ thẫm máu tươi.”","“À phải, lão cầm cờ kia cũng sắp quay về Chernobog rồi. Chiến thắng đã nằm chắc trong tay chúng ta.” Cậu ta ngừng lại. “Cô còn mệnh lệnh nào khác cho tôi không, Talulah?”","Đầu dây bên kia im lặng một lúc.","“Thời khắc đã đến…” giọng Talulah vang lên. “…để biến thành phố mục ruỗng này thành tro tàn.”"],"bg":"bg_cher_6","cast":[["Amiya","op:char_002_amiya"],["FrostNova","npc:char_1505_frstar_1"],["Meteorite","op:char_219_meteo"],["Frostleaf","op:char_193_frostl"],["Jessica","npc:char_259_Jessica_1"],["Ch'en","op:char_010_chen"],["Mephisto","npc:char_1507_Mephisto_1"],["Talulah","npc:avg_npc_078"]]}],"id":"main_4","no":"Chương 4","title":"Chạy giữa lửa cháy","en":"Burning Run","sum":"Một nomadic city bỏ hoang xuất hiện gần Lungmen. Đội trinh sát của Rhodes Island lạc vào lãnh địa của Mephisto và Biệt đội Yeti, còn Amiya phải học cách bước tiếp với nỗi day dứt sau cái chết của Misha."},{"secs":[{"c":"5-1","t":"Vòng luẩn quẩn thù hận","p":["Có những giọng nói vang lên trong giấc mơ, rời rạc như những mảnh kính vỡ.","<i>“Từ giờ chúng ta là bạn nhé. Mấy người lớn đó sẽ không bắt nạt được chúng ta nữa đâu!”</i>","<i>“Đừng sợ. Từ giờ, dù có chuyện gì, mình cũng sẽ giúp cậu.”</i>","<i>“Nếu mình gặp chuyện gì, cậu cũng phải giúp mình đấy! Bạn bè là thế mà!”</i>","<i>“Hehe, chúng ta sẽ luôn ở bên nhau, phải không?”</i>","Rồi một giọng khác, già hơn, lạnh hơn, như vọng ra từ một căn phòng không có cửa sổ.","<i>“Ngươi còn nhớ mình đã làm gì khi lão công tước kia cướp con bé đi không? Ngươi thật sự có thể làm mọi thứ vì Lungmen sao? Giờ thì, Wei Yenwu, lần này ngươi định hy sinh thứ gì, hay hy sinh ai?”</i>","“Nngh… Ugh…”","“Này, tỉnh dậy đi!”","“Cứu cô ấy…”","“Sĩ quan Ch’en, tỉnh dậy!”","@cg:avg_5_1_swire","“…Để tôi qua! Để tôi…”","“Puk gaai, tôi không có thời gian cho chuyện này đâu!”","Ào.","“Hnnf!” Ch’en bật dậy, nước lạnh chảy ròng ròng trên mặt. “Khụ khụ…”","“Tỉnh rồi à?”","“Ack… Cái gì…” Ch’en nhìn quanh, đầu óc vẫn còn quay cuồng. “Hoshiguma, nhanh lên! Reunion—”","Cô ta khựng lại.","Trước mặt cô ta không phải Hoshiguma, mà là một cô gái tóc vàng óng, đôi tai mèo dựng đứng, tay cầm một chiếc cốc rỗng, nhìn xuống với vẻ mặt như vừa đổ nước lên một con mèo hoang.","“Mơ mộng xong chưa? Trời đất, trông cô thảm hại quá.”","“Sao cô lại ở đây? Đội của tôi đâu?”","“Nếu tôi nói họ chết hết trong lúc làm nhiệm vụ thì sao?”","“Nếu cô ngứa đòn thì xếp hàng sau Reunion đi.”","“Thấy cái lưỡi cô vẫn sắc như xưa. Sao lúc đánh nhau lại không được như thế nhỉ?”","“Chuyện gì ở đây thế này?” Hoshiguma bước vào, tay bưng khay nước. “Tôi vừa đi một lát mà hai người đã sắp xé xác nhau rồi? Cô Swire, bớt mỉa mai cô ấy một chút thì có chết ai đâu?”","“Hừ,” Swire quay mặt đi.","“Cả cô nữa, Ch’en, cô vừa mới tỉnh…” Hoshiguma nheo mắt. “Khoan, sao trông cô như vừa đánh nhau với xe tưới nước vậy?”","“Hỏi cô ta ấy.”","“Cô gái trẻ, cái cốc rỗng này làm gì ở đây? Tôi nhớ là đã rót cho mỗi người một cốc.”","“Cô ta nói mê,” Swire đáp tỉnh bơ.","“Trời ạ…”","“Đây là đâu?” Ch’en hỏi.","“Một khoang tàu của Rhodes Island,” Hoshiguma nói.","“Sĩ quan Ch’en, cô và đội của cô đã rút về Lungmen khoảng bốn mươi lăm phút trước,” Swire nói, khoanh tay. “Cô có thể nghĩ mình xóa dấu vết giỏi lắm, nhưng Reunion thì không nghĩ vậy.”","","<i>7:55 sáng. Nhiều mây.</i><br><i>Khoang số 7 của Rhodes Island, Lok Tai Chau, cảng Lungmen.</i>","“Tôi đã hợp tác với Rhodes Island để dọn sạch đám Reunion chặn đường các cô,” Swire tiếp tục. “Đội của cô cũng gần như không sao. Hehe~ Cuối cùng cô cũng về được Lungmen. Đúng lúc tưởng mọi thứ đã yên ổn, cô lại hứng trọn một vụ nổ và bất tỉnh.”","“…Thật sao?”","“Cô đang hỏi là có thật cô để người ta đánh lén như vậy không, hay hỏi có thật cô trúng thuốc nổ mà chỉ bị ngất thôi?”","“Thôi, đừng trêu tôi nữa. Tình hình Lungmen giờ thế nào?”","“Tệ hại hết chỗ nói. Muốn biết thì tự đọc báo cáo đi.” Swire ném tập giấy lên giường. “Dù chuyện gì đã xảy ra trước đó, sự thật là cuộc phản công của chúng ta bị chậm lại đáng kể vì cô. Giờ Đội Tác chiến Đặc biệt đang tập hợp phần còn lại của đội cô, rồi sẽ hội quân với phần còn lại của L.G.D. và Rhodes Island.”","“Vậy là ta sẽ đánh thẳng vào trung tâm thành phố,” Hoshiguma nói. “Chiến tranh cơ động, hả? Nghe có vẻ hứa hẹn. Nhưng chiến lược đó nhằm mục đích gì?”","“Phá hủy mọi điểm tập kết của Reunion. Chúng ta sẽ tận dụng tối đa lợi thế các cô tạo ra.”","“Nói cách khác, là bao vây.”","“Đúng vậy. Phải nắm lấy cơ hội khi Reunion vẫn đang cố đặt chân vững.”","“Nhưng làm vậy sẽ ép tàn quân của chúng hội tụ nhanh hơn,” Ch’en nói. “Cô không đảm bảo được sẽ cầm chân chúng cho đến khi L.G.D. tập hợp lại, càng không đảm bảo được sẽ dọn sạch hết tàn quân Reunion. Chúng tôi không cần ‘lợi thế’ nào của cô, tôi cũng không cần nghe cô giảng giải chiến lược.”","“Cô không có quyền lên tiếng, Ch’en,” Swire đáp, giọng bỗng sắc lại. “Dù cô là đội trưởng Đội Tác chiến Đặc biệt và có quyền tự chủ nhất định trong thời chiến, cô cũng không thể chối bỏ hết trách nhiệm.”","“Nghe giọng cô thì cô đang thách thức tôi. Tôi sẽ tiếp cô, nhưng không phải bây giờ. Mỗi người có lệnh riêng. Điều duy nhất quan trọng là làm tròn việc của mình.”","“Ch’en, L.G.D. đã thất thủ, Reunion đã chiếm Trụ sở L.G.D. Đây là lỗi của cô.” Swire nhìn thẳng vào mắt cô ta. “Tại sao cô không có mặt khi Lungmen cần cô?”","Ch’en không trả lời.","“Đó cũng là mệnh lệnh à?” Swire hỏi. “Nếu cô không lơ là bổn phận, Lungmen đã không thất thủ. Tôi xấu hổ vì cô, Ch’en. Cô nên từ chức ngay, và để tôi tiếp quản Đội Tác chiến Đặc biệt.”"],"bg":"bg_corridor","cast":[["Ch'en","op:char_010_chen"],["Swire","op:char_308_swire"],["Hoshiguma","op:char_136_hsguma"]]},{"c":"5-2","t":"Không thể nói thành lời","p":["“Swire, cô không có thẩm quyền đưa ra yêu cầu như vậy.”","“Này,” Hoshiguma lên tiếng.","“Kể cả gác chuyện thù cũ sang một bên, tôi không nghĩ cô đủ sức gánh trách nhiệm này,” Ch’en nói. “Lẽ ra cô có thể tuyên bố: ‘Trưởng quan Wei Yenwu đã ra lệnh cho người đứng đầu tác chiến đương nhiệm của L.G.D. từ chức và chuyển giao toàn bộ trách nhiệm cho Tổng Thanh tra Swire.’ Cô làm được không? Có mệnh lệnh nào như vậy không?”","“Chậc… Đừng gọi tôi như thế.”","“Nếu không làm được thì lo việc của cô đi. Chẳng có gì tốt đẹp khi cô ôm lấy củ khoai nóng này đâu, ‘Cô S’.”","“Phải nói bao nhiêu lần nữa, đó không phải họ của tôi? Nghe đây, Swire chỉ là mật danh thôi. Không thì gọi tôi là Beatrix Schwire, hiểu chưa?”","“Tôi chẳng quan tâm cô tự gọi mình là gì. Đằng nào cũng chẳng ai phân biệt được.”","“Này…” Hoshiguma lại lên tiếng, lần này yếu ớt hơn.","“Tôi không có tâm trạng chơi với cô. Đi chỗ khác tìm việc mà làm đi, nhóc.”","“Ch’en… cô đúng là đồ cặn bã.”","“Còn cô thì cứ việc tự nhét nó vào chỗ của cô.”","“Tôi đi đây, Hoshiguma.” Swire quay lưng, đuôi vẫy giận dữ. “Khuyên chị nên xích con bò sát điên này lại. Đừng chạy đến tìm tôi nếu nó chết dưới mương đâu đó.”","“Ờ, xin lỗi nhé, cô gái nhỏ. Cả hai đều nóng tính thật. Dù cô nói vậy, chúng tôi vẫn biết ơn sự giúp đỡ của cô.”","“Không bao giờ nữa. Tôi muốn thấy cô ta chảy máu.”","Cánh cửa đóng sầm lại. Ch’en nhìn theo, rồi khẽ nhíu mày.","“Lưng cô ta bị sao vậy? Trông như vết thương mới.”","“Lúc cõng cô đến chỗ nấp, một Caster Reunion đã cho nổ tung bức tường chỉ cách sau lưng cô ấy vài mét,” Hoshiguma nói. “Cô nên đối xử tốt với cô ấy hơn một chút. Tôi chắc là thỉnh thoảng thôi làm kẻ thù không đội trời chung cũng chẳng chết ai.”","Ch’en im lặng một lúc. “…Tôi biết.”","","Cốc cốc.","“Tôi vào được không, cô Ch’en của Lungmen?” Một operator Rhodes Island ló đầu vào.","“Vào đi. Cô ấy không phiền đâu. Xin lỗi đã để cậu chờ,” Hoshiguma nói.","“Không có gì đâu ạ. Rất vui được gặp cô, cô Ch’en. Ừm… Cô có thể bàn với Rhodes Island về nhiệm vụ bây giờ không? Bọn tôi đã tập hợp vài đội trên boong, sẵn sàng bắt đầu nhiệm vụ cùng cô bất cứ lúc nào.” Anh ta ngập ngừng. “Xin lỗi vì đã nghe lỏm cuộc nói chuyện ban nãy của cô với cô thanh tra tóc vàng… Bọn tôi hiểu L.G.D. đã chịu tổn thất nặng. Tuy nhiên, cô có thể tin rằng bọn tôi sẽ làm mọi thứ trong khả năng để giúp.”","“Tôi sẽ đến ngay,” Ch’en nói. “…Giờ không phải lúc nói chuyện đó.”","Khi operator đã ra ngoài, cô ta quay sang Hoshiguma. “Đừng lo, Hoshiguma. Cô cũng biết Swire đang cố ổn định tình hình mà.”","“Cả hai người đều quá nóng.”","“Tôi chỉ nói thẳng với cô ta thôi. Thương vong của Lungmen rất nặng, và đó là ‘sự thật’ mà họ cần ‘biết’.”","“Đừng nói vậy. Không giống cô chút nào.”","“Là vì Lungmen.”","“Như thế lại càng không giống cô,” Hoshiguma nói. “Cô là thanh tra cấp cao, một sĩ quan cao cấp, không phải chính trị gia. Cô chưa bao giờ hợp với mấy trò vặt này.”","“Đúng vậy, đây không phải việc một thanh tra đúng nghĩa nên làm. Nhưng tôi không có lựa chọn.”","Hoshiguma nhìn cô ta một lúc lâu. “…Cô chỉ là làm việc quá sức, cần một kỳ nghỉ thật dài thôi.”","“Có lẽ.” Ch’en bật cười khẽ. “Heh… Tôi từng nghĩ đến chuyện đó. Hoshiguma, tôi cần một kỳ nghỉ thật, thật dài.”","“Được thôi, sau khi xong chuyện này. Đừng chết ngoài đó. Ochre, hay Spring City? Hay Floria County? Thời gian đi đến Ochre đủ để ta nghỉ thêm một kỳ nữa. Hoặc ta về Victoria thăm mấy đồng nghiệp cũ…”","“Tôi muốn đi thăm quê của cô.”","“Đừng phí công. Chẳng thú vị bằng một góc Lungmen đâu.”","“Haha.”","Thiết bị liên lạc của Ch’en rung lên. Cô ta nhìn màn hình, và nụ cười tắt hẳn. “…Kênh bí mật.”","@cg:bg_5_2_call","“Vậy tôi ra ngoài nhé.”","“Cảm ơn.” Khi cửa đã đóng, Ch’en áp máy lên tai. “Nói đi, tôi nghe.”","“Cô Ch’en… bọn Infected đó, Reunion… chúng ở khắp nơi…” Một giọng đàn ông thều thào.","“XR02? Anh đang ở đâu?”","“Nhà kho Muk Wo. Tôi trúng vài mũi tên, chắc không trụ được lâu nữa. Đây là bẫy… Đừng đến cho đến khi chúng đi rồi. Tôi sẽ giữ tin tình báo trên người. Chúng không tìm được đâu.”","“Mật danh XR02, cố lên. L.G.D. sẽ đến ngay lập tức. Tin tình báo anh đang giữ rất cấp bách, và chúng tôi phải có nó ngay.”","“Tôi không chắc, cô Ch’en, tôi không muốn cản trở nhiệm vụ của cô.”","“XR02, anh không được phép chết. Anh phải sống.”","“…Tôi không cãi lại cô được, cô Ch’en. Cô nhớ cẩn thận. Khoan, có thứ gì đó đang di chuyển—”","Rè rè rè.","“XR02? XR02!”","Im lặng.","Ch’en hạ máy, đứng im một lúc. Rồi cô ta mở cửa. “Hoshiguma? Tập hợp đội của cô. Đến lúc đi rồi.”","@bg:bg_uptown_1","“Cô Ch’en, cô đi ngay bây giờ sao?” Operator Rhodes Island chạy theo.","“Lực lượng tác chiến còn lại của Rhodes Island thế nào?”","“Đây không phải thông tin bọn tôi có thể tiết lộ, cô Ch’en. Nhiệm vụ của bọn tôi là hỗ trợ L.G.D. tác chiến, nhưng không trực tiếp chịu sự chỉ huy của cô.”","“Tôi đâu có yêu cầu điều đó.”","“X-xin lỗi, tôi nói nhiều quá.”","“Không sao. Tôi chỉ tò mò về tình hình Rhodes Island, xem có vấn đề an ninh nào cần L.G.D. giúp không.”","“Sau nhiều lần bị bọn tôi đánh bại, Reunion gần như đã từ bỏ việc xâm nhập Rhodes Island. Xét từ nhiều góc độ, tình hình Lungmen tệ hơn nhiều so với những gì bọn tôi phải đối phó.” Anh ta ngập ngừng. “Xin lỗi, mong là tôi không thất lễ…”","“Tức là các cậu không cần chúng tôi giúp.”","“Đúng vậy.”","“Vậy thì tạm thời, L.G.D. cần các cậu giúp một việc nhỏ. Reunion đã chặn con đường chính dẫn ra bến cảng. Chúng tôi cần các cậu mở một lối. Thời gian của L.G.D. không còn nhiều, nên phải làm thật nhanh.”","“Theo hợp đồng, bọn tôi sẵn lòng, thưa cô.”","“Tốt. Theo tôi!”","","“Trước khi đối đầu trực diện, tôi không ngờ Reunion lại yếu thế,” operator nói sau trận đánh. “Xét những gì chúng làm ở Chernobog và mọi rắc rối chúng gây cho các đội của bọn tôi, tôi tưởng chúng phải mạnh khủng khiếp. Nhưng theo những gì tôi thấy, thông tin trong buổi họp nhiệm vụ là đúng. Đó thật sự là toàn bộ hỏa lực Reunion có thể huy động. Thứ duy nhất làm nhiệm vụ này phức tạp là ta không biết chúng đang âm mưu gì.”","“Đừng lơ là,” Ch’en nói. “Sức mạnh lớn nhất của Reunion là làm những điều cậu không ngờ tới. Thâm nhập, đánh úp, lợi dụng những năng lực chưa biết của thành viên… đó là những chiến thuật chúng giỏi nhất. Ta vẫn chưa biết chúng còn giấu những quân bài nào.”","“Tôi biết, xét việc chúng hạ được những thành phố lớn mạnh như Chernobog và Lungmen. Quân số thật của chúng có thể vượt xa tưởng tượng.” Anh ta ngừng lại. “Nhân tiện, cô Ch’en, chẳng phải L.G.D. đi cùng Amiya điều tra thành phố phụ của Chernobog sao? Sao họ vẫn chưa về?”","Ch’en im lặng một nhịp. “Tôi xin lỗi…”","<i>Ch’en…</i> Hoshiguma nhìn cô ta.","“Chúng tôi bị tách khỏi đội của Amiya. Không thể hội quân, và vì tình hình khẩn cấp, chúng tôi phải quay về.”","“Ý cô là cô và L.G.D. đã bỏ Amiya và Doctor lại đó sao?”","“Đúng vậy…”","“Nói cách khác, họ đang mất tích?” Giọng anh ta run lên. “Tại sao… cô Ch’en… Không… Cô không nên làm thế… Dù là L.G.D., cô cũng không nên bỏ rơi đối tác của mình.”","“Đây là lỗi của tôi. Nhiệm vụ của tôi là ưu tiên an toàn của Lungmen. Tôi đã quyết định tuân theo nó.”","“Lỗi của ai thì có khác gì đâu…? Thôi, sĩ quan, nói thêm cũng vô ích.” Anh ta lùi lại một bước. “Lẽ ra tôi phải biết. Đúng rồi, tôi biết quá rõ cô nhìn người Infected chúng tôi thế nào.”","“Tôi không có ý đó…”","“Cô cần bao nhiêu operator? Có thể sẽ có người sẵn lòng giúp cô, nhưng tôi không phải một trong số đó. Bọn tôi cũng có nhiệm vụ riêng. Giúp Lungmen đánh bại Reunion có thể là một trong số đó… Nhưng bọn tôi sẽ tự làm. Nhớ lấy mã nhận diện của bọn tôi, thưa cô. Cố đừng bắn nhầm đồng minh, dù bọn tôi là người Infected.”","“…Tôi hiểu,” Ch’en nói. “Nếu có ai sẵn lòng tham gia nhiệm vụ này cùng L.G.D., cậu có thể báo cho tôi. …Không cần miễn cưỡng.”","Khi anh ta đã đi, Hoshiguma lên tiếng. “Màn kịch với Swire lúc nãy… chẳng phải cô làm vậy để lấy thiện cảm của Rhodes Island sao? Vậy sao giờ lại đối xử với người của họ như thế?”","“Cô nhầm rồi, Hoshiguma. Tôi không có ý định đó.”","“Có lẽ. Tôi muốn thấy cô thẳng thắn hơn. Trông cô giờ nhẹ nhõm hơn nhiều đấy.” Hoshiguma thở dài. “Nói thật, nếu ở vị trí cậu ta, tôi cũng sẽ giận. Cứ mừng là các chiến binh của Rhodes Island khá dễ tính đi. Nói thế nào nhỉ… Dù là khẩn cấp, ngay cả tôi cũng không hiểu… Tại sao cô lại dứt khoát bỏ đội của Amiya như vậy?”","“Có quá nhiều ẩn số. Địa hình khiến L.G.D. khó chiến đấu, và ta không có cách nào đánh giá năng lực tác chiến của Reunion. Tôi không thể để các đội gánh những rủi ro không thể chấp nhận.”","“Tôi không tin.”","“Hoshiguma… kế hoạch của chúng ta đã được vạch sẵn.”","“Lệnh là lệnh, và tôi sẽ tuân theo. Nhưng tôi nên được nghe trực tiếp từ cô, chứ không phải chờ Swire nói cho biết.”","“Chưa đủ điều kiện, chi tiết vẫn là cơ mật.”","“Vậy là lệnh từ ông Wei.”","“Cô cứ tự do suy đoán.”","“Đến giờ tôi vẫn không biết mục tiêu của cô là gì. Ở Lungmen có rất ít người đủ quyền lực để khiến L.G.D. làm đến mức này. Đó là khả năng duy nhất.” Hoshiguma nhìn ra ô cửa. “Tôi trân trọng những gì ông Wei đã làm. Nhưng tôi sẽ không bao giờ kính trọng ông ta, và chuyện hôm nay chỉ là một trong những lý do.”","“Tất cả đều cần thiết.”","“Đó chỉ là cái cớ của cô thôi.” Hoshiguma thở dài. “Ch’en, hoặc cô đang nghĩ quá nhiều, hoặc cô còn không thuyết phục nổi chính mình.”","“Có lẽ vậy.” Ch’en quay sang một nhân viên. “Gọi Swire cho tôi.”","","“A lô?”","“Chúng tôi đã rời Rhodes Island, Swire. Cô có thể bắt đầu.”","“Chắc lúc nãy quát tôi sướng lắm nhỉ?”","“Chúng ta không hợp nhau, nhưng không đến mức đó. Tôi chỉ phóng đại thôi.”","“Tôi thì không đâu. Tôi thích lắm.”","“Cô đúng là đồ…”","“Rồi, rồi. Mà lạ thật, chúng ta chẳng biết gì về nhiệm vụ của nhau. Còn nữa, tôi vừa nghe nói, sao cô không muốn Rhodes Island can thiệp? Đây là một kiểu chuộc lỗi à?”","“Tôi tin vào năng lực của Rhodes Island, cũng tin vào Amiya và Doctor,” Ch’en nói. “Nhưng chính vì thế tôi không muốn họ dính vào. Họ sẽ chỉ thêm một ẩn số nữa. Nhất là người tên Kal’tsit. Tôi đảm bảo với cô, bà ta sẽ không tuân theo kế hoạch của chúng ta.”","“Tôi chưa gặp người đó bao giờ.”","“Cô không cần gặp. Bà ta hơi giống ông nội cô, chỉ là không đeo máy thở.”","“Hả.”","“Tập trung vào việc của mình đi. Trước đó, tôi còn phải tìm một người.”","“Tùy cô. Miễn là đừng đến muộn.”","“Hoshiguma, đi thôi.”","“Đi đâu?”","“Nhà kho Muk Wo.”"],"bg":"bg_corridor","cast":[["Ch'en","op:char_010_chen"],["Hoshiguma","op:char_136_hsguma"],["Swire","op:char_308_swire"]]},{"c":"5-3","t":"Lòng can đảm và cái chết","p":["<i>11:11 sáng. Mưa phùn.</i><br><i>Bên ngoài nhà kho Muk Wo, Sam Cheong Chai, trung tâm Lungmen.</i>","“Trinh sát gần xong rồi,” Hoshiguma nói. “Điểm quan sát đủ kín, và quanh nhà kho không có ai.”","“Trông như một công trường bỏ hoang, vật liệu xây dựng chất đống. Có dấu vết thứ gì đó bị kéo lê. Reunion chắc đã đặt phục kích ở đây.”","“Ch’en, Phal là người cung cấp tin của cô à?”","Ch’en im lặng một nhịp. “…Phải. Cô nghe lỏm à?”","“Tôi đã cố hết sức để không nghe. Tôi quen anh ta lâu lắm rồi, hơn mười năm. Không đời nào tôi không nhận ra giọng anh ta.” Hoshiguma nhìn về phía nhà kho. “Cô biến anh ta thành người cung cấp tin từ khi nào? Anh ta nhiễm bệnh hơn một năm trước. Khi ấy anh ta biến mất khỏi quán rượu của mình, bỏ lại những chiếc ly ngày nào cũng lau chùi, giờ phủ đầy bụi.”","“Có lẽ còn trước cả khi đó.”","“Ít nhất cô cũng nên nói với tôi.”","“Trời sắp mưa rồi. Bắt đầu thôi, lùa địch ra khỏi chỗ phục kích.”","“Haizz…” Hoshiguma đứng dậy. “Ta đến muộn rồi. Anh ta sắp mất hết máu. Tôi sẽ thu hút hỏa lực của Reunion. Những người còn lại nắm lấy cơ hội bao vây chúng, kết thúc trận đánh thật nhanh.”","“Quá nguy hiểm.”","“Nhưng đó là cách thắng nhanh nhất. Lần này cô cứ tin tôi.”","“Tôi luôn tin cô.” Ch’en quay sang các nhân viên. “Làm theo hướng dẫn của Hoshiguma. Nhanh lên.”","“Rõ!”","“Tôi sẵn sàng, Hoshiguma.”","“Thế mới phải chứ. Tôi sẽ lùa chúng ra khỏi chỗ phục kích. Cho tôi ba phút.”","“Một mình làm hết trong ba phút? Liều quá rồi! Chỉ cần thấy cô có dấu hiệu cần giúp, chúng tôi sẽ tấn công.”","“Không, chỉ cần cho tôi ba phút.” Hoshiguma nhấc chiếc khiên khổng lồ lên vai. “…Tôi chỉ cần chừng đó thôi.”","","“Sao mọi người bỏ chạy hết vậy?!”","“Dùng Arts tấn công ả! Đừng chạy nữa!!”","“D-dừng lại! Ả, ả đang đến đây! Chặn ả lại! Những người khác đâu hết rồi?! Tại sao…”","“Ngươi là kẻ cuối cùng,” Hoshiguma nói.","Tên Reunion ngã ngồi xuống đất, lùi lại bằng hai tay. “Aaaaah…! Quỷ dữ… A-ai đó cứu tôi với…”","“…Ngươi định ngăn ta bằng cách này sao?”","“Không, tôi… Không…”","“Ngươi định ngăn ta… bằng cách này sao?”","“Tha cho tôi! Làm ơn!”","“Ngươi còn không xứng làm mồi cho Hannya của ta.”","“Khôngggg!!”","Ở điểm quan sát, các nhân viên L.G.D. nhìn nhau.","“Trời đất… Bọn ta còn chưa kịp tấn công.”","“Một mình chị ấy hạ hết Reunion, chỉ trong hai phút rưỡi.”","“Đúng là quỷ dữ thật.”","“Mừng là các cậu không gặp cô ấy năm năm trước đi,” Ch’en nói. “Đã lâu lắm rồi tôi mới thấy cô ấy đánh như vậy. Còn tàn quân?”","“Các đội đã bắt hết rồi ạ. …Cô Ch’en, thanh tra Hoshiguma có vẻ đang vẫy cô.”","“Y tế, theo tôi!”","","“Hoshiguma, cô còn hỏi bọn Reunion đó những gì?”","“Tôi hỏi chúng nhà kho có gài bẫy không.”","“Nếu cả nhà kho được nối với thuốc nổ…”","“Thì ta sẽ ném chúng vào, từng tên một.”","“Thế nào?”","“Chẳng có gì. Phal chạy đến đây sau khi bị phục kích. Reunion vốn đóng quân quanh đây.” Hoshiguma đặt tay lên cánh cửa sắt. “Ch’en, kéo bên phải. Tôi lo bên trái.”","“…Có vẻ bị kẹt, không nhúc nhích. Để tôi cắt một lỗ trước.”","“Không cần, tôi xé luôn cho nhanh.”","ẦM!","“Mở rồi!” Ch’en lao vào bóng tối. “XR02, cho tôi biết vị trí của anh! XR02! …! XR02!”","Từ thiết bị liên lạc, một giọng nói yếu ớt vang lên. “Cô Ch’en… Tôi nghe thấy đánh nhau bên ngoài. Cửa nhà kho… bị phá rồi. Có thể là Reunion. Tôi sẽ tự lo…”","“Dừng lại, là tôi! Đừng cúp máy!”","“Là cô à, cô Ch’en? May quá… Tôi… ở tận phía cuối.”","Ch’en tìm thấy anh ta sau một đống thùng gỗ. Một người đàn ông trung niên, quần áo đẫm máu, ba mũi tên còn cắm trên người. Đôi mắt anh ta bị băng một mảnh vải bẩn.","@cg:bg_5_3end1","“Vết thương đó… mắt anh bị sao vậy?”","“Tôi không cẩn thận, trúng Arts. Đừng bận tâm, giờ chẳng còn quan trọng nữa. Cái này… khụ… cho cô.”","“Y tế, cầm máu cho anh ta!”","“Không… Cô Ch’en, không cần đâu. Tôi đã chấp nhận rồi…”","“Đừng nói nữa!”","“Thật mà. Cô thấy tôi trúng bao nhiêu phát rồi không? Tôi mù rồi, không muốn cử động nữa. Đau đủ rồi. Tôi mệt lắm.” Anh ta dúi một mảnh giấy nhàu nát vào tay cô ta. “Cầm lấy đi, cô Ch’en… S249TA, F106.”","“49. Tôi đã nhớ vị trí.”","“Chi tiết ở trên giấy. Tin về việc Reunion thâm nhập không được gửi cho các thủ lĩnh khác, mà chỉ cho một bên… Chắc chắn có lý do. Cô phải điều tra, càng sớm càng tốt.”","“Tôi sẽ làm.”","“Khụ… Không dễ gì tôi lấy được nó đâu… Mà, cô Ch’en, tôi không ngờ mọi chuyện lại kết thúc thế này. Dù cuối cùng tôi cũng đóng góp được gì đó, tôi không nghĩ sẽ là theo cách này…”","“Không ai trong chúng ta nghĩ vậy. Nhờ lòng dũng cảm của anh, giờ ta có cơ hội ngăn chặn kẻ thù.”","“Haha… khụ… Tôi chưa bao giờ thích Lungmen, và Lungmen cũng chưa bao giờ thích tôi. Nhưng giờ, cuối cùng tôi cũng làm được gì đó cho Lungmen. Không tệ với một kẻ vô công rồi nghề như tôi, nhỉ…”","“Anh tự gọi một trong Tam Đại của Chung Shui là kẻ vô công rồi nghề sao?”","“So với cô, so với Bà Quỷ, tôi chẳng là gì cả.” Anh ta im lặng một lúc. “…Cô Ch’en, Bà Quỷ thế nào rồi? Cô ấy vẫn làm thanh tra chứ?”","“Vẫn vậy. Cô ấy là cộng sự của tôi lâu lắm rồi.”","“Cô Ch’en, Bà Quỷ… quá thẳng thắn và trung thực. Trong băng không ai… khụ… dám thách thức cô ấy. Nhưng cô ấy không phải đối thủ của những đại gia Lungmen. Xin cô để mắt đến cô ấy. Đừng để ai coi thường cô ấy. Tôi sẽ không để lũ tài phiệt kiêu ngạo đó sỉ nhục cô ấy vì xuất thân của cô ấy! Đây là ân huệ duy nhất tôi xin cô. Chỉ một thôi… khụ khụ…”","“Đừng lo chuyện đó. Hoshiguma rất mạnh. Không ai làm tổn thương được cô ấy.”","“Mạnh đến đâu, ai cũng có giới hạn.”","“Cả L.G.D. đứng về phía cô ấy.”","“Tốt, vậy thì yên tâm rồi. Bà Quỷ, cô Ch’en, giờ tôi không còn gì hối tiếc nữa.” Anh ta lần tay trong không khí. “Cô Ch’en, cô còn ở đây không?”","“Tôi ở đây.”","“Tôi có phải người tốt không?”","“Vài năm trước thì hơi khó nói. Nhưng giờ, chắc chắn là phải. Lungmen tự hào vì có những công dân như anh.”","“Hahaha… khụ… Haha… một người Infected thảm hại mà có thể là công dân tốt sao?”","“Một số người ở Lungmen đúng là ám ảnh với Oripathy, nhưng tốt hơn anh nên hỏi thẳng Lungmen.”","“Hỏi thế nào được? Một thành phố sẽ trả lời tôi sao?”","“Heh. Tôi sẽ trả lời thay nó.” Ch’en nắm lấy bàn tay đầy máu của anh ta. “Và nó nói: ‘Tôi không bận tâm.’ Phal, anh đã luôn, và sẽ mãi là một trong những người giỏi nhất của Lungmen.”","“Cảm ơn cô, cô Ch’en. Cảm ơn cô nhiều lắm.” Anh ta mỉm cười. “Cô Ch’en, có hai điều tôi muốn cô chuyển lời cho Bà Quỷ.”","“Anh nên tự nói với cô ấy.”","“Ý cô là sao? Cô đang nói là…” Anh ta khựng lại. “…Đại ca?”","“Là tôi đây,” Hoshiguma nói. Cô ta đã quỳ xuống bên cạnh anh ta từ lúc nào, đôi tay to lớn đỡ lấy lưng anh ta. “Tôi ở ngay đây.”","“Cô Ch’en, lẽ ra cô phải nói với tôi sớm hơn chứ.”","“Cô ấy chọn không lên tiếng,” Ch’en nói.","“Đại ca, tôi làm tốt chứ?”","“Chưa đủ tốt. Phải sống để thấy mọi chuyện đến cùng thì mới gọi là làm tốt.”","@cg:bg_5_3end2","“Chết tiệt, haha… Được đại ca cõng trên lưng thì tôi dùng hết vận may rồi.”","“Có muốn đi đâu không? Cậu chưa bao giờ chịu nói cho tôi biết mình từ đâu đến.”","“Ở đây, Lungmen. Thật ra tôi chưa từng đến thành phố nào khác. Nếu được, cứ chôn tôi ở chỗ cũ.”","“Hang ổ à? Nhưng… chỗ đó giờ tan hoang rồi, bỏ hoang từ lâu. Nói thật, tôi không chắc phải dọn dẹp thế nào.”","“Không sao. Chỉ cần… được ở cùng những người khác.”","“Tôi sẽ làm.”","“Đại ca… Dù bọn tôi lúc nào cũng sợ chị, bọn tôi cũng luôn… cổ vũ cho chị.” Giọng anh ta nhỏ dần. “Bọn tôi luôn… cổ vũ…”","Hoshiguma cúi đầu, rất lâu.","“Tôi cũng vậy.”"],"bg":"bg_uptown_2","cast":[["Ch'en","op:char_010_chen"],["Informant","npc:avg_npc_013"],["Hoshiguma","op:char_136_hsguma"],["L.G.D. Agent","npc:char_015_lmg"]]},{"c":"5-4","t":"Nhà không người","p":["“Hoshiguma?”","“Hả?”","“Trông cô không ổn.”","“Tôi không sao, chỉ đang suy nghĩ thôi.”","“…Tôi không ngờ anh ta lại bị cuốn vào chuyện này.”","“Đừng lo, cô biết tôi mà. Chuyện qua rồi, hay như người Lungmen hay nói, đó là số phận.”","“Người Viễn Đông tin vào số phận sao?”","“Trải qua ngần ấy chuyện, trước kia không tin thì giờ cũng phải chấp nhận.” Hoshiguma lắc đầu, như muốn rũ bỏ điều gì đó. “Tin tình báo có chính xác không?”","“Không nghi ngờ gì. Đây là vị trí trong tin tình báo.”","Họ nằm trên một mái nhà, nhìn xuống một dãy biệt thự sang trọng ở khu nhà giàu.","“Đám Reunion lảng vảng kia… là mục tiêu của ta à? Nhìn thì chúng chưa biết ta đã bao vây chúng hoàn toàn. Có vẻ chúng đang xây gì đó quanh cả dãy nhà.”","“Nếu tôi không nhầm, đây là một trong những trung tâm kết nối các căn cứ của Reunion. Nếu phá hủy cơ sở liên lạc ở đây, ta có thể giáng một đòn chí mạng vào lực lượng của chúng trong khu vực này. Như vậy ta sẽ tiến thêm một bước để giành lại Trụ sở L.G.D.”","“Cô quyết đi.”","“Ngoài ra, tôi cứ nghĩ mãi về chi tiết trong bản tin.”","“Ý cô là đoạn nói mục tiêu của Reunion không chỉ là xây căn cứ tiền tuyến?”","“Đúng vậy. ‘Địch đang bí mật tìm kiếm một mục tiêu có giá trị cực cao. Cần xác định hành động của chúng trước.’”","“Chúng làm gì ở khu nhà giàu? Chúng muốn tìm mục tiêu giá trị cao nào ở đây?”","“Tôi cũng thấy hơi đáng ngờ. Theo kế hoạch trước đó, mọi tòa nhà ở đây lẽ ra đã được sơ tán. Nếu Reunion định bắt cóc một đại gia nào đó, chúng sẽ không tìm thấy ở đây.”","“Khi nào ta ra tay? Trinh sát có vẻ không phải sở trường của Reunion, nên ta có thể đột kích bất cứ lúc nào.”","“Có lẽ chúng quen làm thợ săn rồi, không quen làm con mồi.”","“Giờ đến lượt chúng làm con mồi, chúng sẽ bị săn gọn trong chớp mắt.” Hoshiguma nheo mắt. “Tạm thời cứ quan sát kỹ đã. Ưu tiên là tìm ra mục tiêu của chúng, không phải giao chiến.”","“Xông vào tiêu diệt thì dễ, nhưng muốn biết chúng tìm gì thì cần kiên nhẫn.”","“Hiểu.” Hoshiguma bỗng nhổm dậy. “Khoan! Ch’en, chúng sắp phá cửa căn nhà kia à?”","“Mục tiêu đã được xác nhận rồi sao? Tập hợp, nhanh!”","“Để giảm thiểu thương vong dân thường, hả?”","“Đương nhiên! Sniper, ngắm!”","“…! Là quân đội Lungmen! Rút lui! Ta phải liên lạc với…”","“Sniper! Bắn hạ tên đang cầm thiết bị vô tuyến! Ngăn cuộc truyền tin đó lại!”","“Lẽ ra chúng phải giữ căn cứ, sao lại chạy khỏi ta? Chúng đang âm mưu gì đó!”","“Để xem các ngươi chạy được bao xa!”","","“Đã bắt hết thành viên Reunion. Không ai biết gì về chỉ thị cụ thể…” Hoshiguma ngừng lại. “Ch’en? Cô đang nhìn gì mà say sưa thế?”","Ch’en đứng trước cánh cổng sắt của một tòa biệt thự lớn, mắt nhìn lên tấm biển tên phố đã bạc màu.","“Đây chẳng phải từng là đường Đại Học sao?”","“Hửm? Có vẻ vậy. Sau này mới đổi tên.”","“Tôi nghĩ đây từng là nhà tôi…”","“Chẳng phải căn hộ của cô ở Tai Bo sao?”","“Đây là dinh thự của dòng họ cha ruột tôi. Có vẻ đã được sửa sang lại. Lâu quá rồi, tôi gần như không nhận ra nữa.”","@cg:avg_5_4_door","“Cô sống ở đây trước khi sang Victoria du học à?” Hoshiguma nhìn tòa nhà đồ sộ. “Dù tôi từng nghe cả cô và ông Wei đều sinh ra trong giới quý tộc Yan, thấy một dinh thự lớn thế này vẫn ngạc nhiên lắm.”","“Quý tộc? Họ thì phải, nhưng tôi thì không.”","“Nhưng dinh thự của cô ở đây… Gọi là gì nhỉ?”","“Hừm, gọi là Dinh thự họ Ch’en cũng được…” Ch’en rút kiếm. “Vào đi.”","Một đường kiếm. Ổ khóa rơi xuống.","“Hả? Ô kìa, chẳng phải nhà của cô sao? Sao lại chém cửa?”","“Tôi quên mang chìa khóa. Hơn nữa, Reunion cũng vừa đục một lỗ ở tường bên. Chúng có thể đã gây thiệt hại ngoài dự kiến.”","“Thế cũng không có nghĩa là— Thôi bỏ đi. Cô nói sao thì vậy.”","“Không cần cởi giày.”","“Cô nghiêm túc đấy à? Ch’en, nói thật với tôi, cô có ghét ông già nhà cô không?”","“Ông ta không xứng làm cha tôi.”","“Được rồi.” Hoshiguma đi theo cô ta qua những hành lang phủ bụi. “Nếu tôi nhớ không nhầm, cô gia nhập L.G.D. ngay sau khi tốt nghiệp ở Victoria và trở về Lungmen.”","“Khi đó tôi ở ký túc xá.”","“Vậy là sau đó cô chưa bao giờ quay lại đây.”","“Tôi chẳng còn vương vấn gì với nơi này.”","“Người hay nói câu đó thường còn nhiều điều chất chứa trong lòng lắm.” Hoshiguma nhìn quanh. “Mà, cô có ý tưởng gì về cái mục tiêu giá trị cao kia không? …Ch’en?”","Ch’en đã dừng lại trước một cánh cửa nhỏ ở cuối hành lang tầng hai. Cô ta đứng im, không trả lời.","“…Lại chìm vào thế giới riêng rồi.” Hoshiguma thở dài. “Ch’en, tôi chờ ở cửa nhé. Sẵn sàng đi thì gọi tôi.”","@bg:bg_home","Căn phòng nhỏ. Một chiếc giường đơn được trải phẳng phiu. Một giá đồ chơi xếp ngay ngắn đến đáng sợ. Trên tường, một tờ giấy dán đã ố vàng.","<i>Xếp đồ chơi gọn gàng.</i><br><i>Không được ra ngoài.</i><br><i>Không được nói chuyện với ai khi chưa được phép.</i><br><i>Không được nhìn vào mắt người lớn khi chưa được phép.</i>","Ch’en đứng giữa căn phòng rất lâu.","“…Ông thật sự giữ căn phòng này sạch sẽ suốt ngần ấy năm.” Cô ta khẽ cười, không chút vui vẻ. “Hừ. Hào phóng thật, còn dọn sẵn giường cho tôi. Hay đây là một kiểu nguyền rủa vì ông nghĩ tôi mang xui xẻo?”","Cô ta lục ngăn kéo bàn. “Khoan, tấm ảnh… Phải rồi, tấm ảnh…”","Có những câu nói vọng về từ rất xa, từ những năm tháng cô ta đã cố quên.","<i>Con sẽ không nhận được chút tình thương nào từ ta, không một chút nào.</i>","<i>Xin lỗi. Ta xin lỗi, nhưng ta không chịu nổi con. Chỉ nhìn thấy con thôi ta đã muốn lột da tay mình ra.</i>","<i>Ta không thể chịu đựng được bất kỳ ai trong các người. Ta quá ích kỷ, nhưng ta không thể sống như thế này nữa.</i>","<i>Một ngày nào đó, tất cả các người sẽ hiểu. Nếu các người ghét ta, thì cứ việc. Vì ta cũng ghét các người. Và đó là điều nên thế.</i>","“Đây rồi.”","@cg:avg_5_photo","Một tấm ảnh nhỏ, mép đã quăn, màu đã phai. Hai cô bé đứng cạnh nhau, nắm tay nhau cười rạng rỡ trước ống kính.","“Một tấm ảnh từ lâu lắm rồi… Tôi tưởng nó mất rồi.” Ch’en nhìn tấm ảnh, rồi đôi mắt cô ta mở to. “Khoan, không… lẽ nào đây là thứ chúng đang tìm? Chuyện gì đang xảy ra vậy? Tại sao chúng lại muốn thứ này? Cô cũng mất trí rồi sao?”","Cô ta nói với tấm ảnh, như nói với một người đang đứng trước mặt.","“Tôi chắc chắn sẽ giúp cô, nhưng cô đang nghĩ gì vậy? Sao lại ở đây, sao lại là lúc này?” Một quãng lặng. “À… Mình còn mong gì nữa chứ. Đương nhiên là cô sẽ không trả lời tôi.”","","“A, cuối cùng cũng sẵn sàng đi rồi à?”","“Đi thôi.”","“Có manh mối gì không? Hay cô muốn chơi với mấy cuộn len thêm chút nữa?”","“Không ngờ cô vẫn còn tâm trạng đùa.”","“Tôi nghĩ tâm trạng của cô chỉ khá hơn lúc nãy một chút xíu thôi.”","“Như cô nói đấy. Có lẽ tôi đúng là nghĩ hơi nhiều.” Ch’en cất tấm ảnh vào túi áo ngực, ngay cạnh con búp bê vải. “Theo báo cáo, Reunion đang rải rác khắp khu vực này, và các lực lượng ta triển khai trước đó đang lùa chúng ra ngoài.”","“Tốt. Việc của ta dễ hơn rồi, và ta đang tiến gần mục tiêu.” Cô ta quay sang các nhân viên. “L.G.D., vào đội hình, xuất phát! Ta sẽ giành lại Lungmen!”"],"bg":"bg_uptown_2","cast":[["Ch'en","op:char_010_chen"],["Hoshiguma","op:char_136_hsguma"]]},{"c":"5-6","t":"Tập kích bất ngờ","p":["“Có gì đó không ổn,” một Caster Reunion lẩm bẩm.","“Lại gì nữa? Bệnh tái phát à?”","“Chuyện này khác hẳn Chernobog. Dù tổn thất lớn, khi ta giành chiến thắng ở Chernobog, ta còn thấy kẻ thù vùng vẫy và tay sai của chúng tháo chạy. Nhưng Lungmen sao cứ trống rỗng thế nào ấy?”","“Không thể nào đâu nhỉ?”","“Nghĩ mà xem, đây lẽ ra là Paci Plaza, đúng không? Một trung tâm thương mại lớn, bao nhiêu cửa hàng, sao lại trống trơn? Hơn nữa, tôi đã nhìn quanh rồi, chẳng có thứ gì giá trị cả! Mọi thứ đã bị lấy đi hết!”","“Chẳng phải Patriot đã cấm…”","“Không phải ý đó. Mephisto thì chẳng quan tâm ta làm gì, nhưng đó không phải vấn đề. Ý tôi là, cứ như có ai đó đã giấu hết mọi thứ khỏi chúng ta.”","“Cậu tưởng tượng thôi. Lungmen chẳng làm gì được ta đâu! Ta đột nhiên xuất hiện từ mọi ngóc ngách, và thế là, sẽ y như lần ở Chernobog. Lần này ta không phá tan thành phố, mà chiếm lấy nó. Nó sẽ thành thành phố của chúng ta!”","“Cậu có biết không? Paci Plaza là căn cứ gần Trụ sở L.G.D. nhất. Tiếp tế từ đây sẽ nhanh và tiện. Tất cả lực lượng Reunion quanh thành phố sẽ tập trung về Trụ sở L.G.D., rồi tỏa ra chiếm toàn thành phố. Ta biết các đội ở quận này được bố trí thế nào… Nhưng các quận khác thì sao? Tôi biết nhiều đội lẽ ra đang trên đường tới, nhưng khá nhiều đội đã mất tích không dấu vết.”","“Mất tích… ý cậu là sao?”","“Lạ lắm. Liên lạc vẫn thông, nhưng không có hồi âm. Ta không có cách nào liên lạc được với họ.”","“Và chẳng mấy chốc, cũng sẽ không ai liên lạc được với các người nữa.”","“Cái gì! Ai đó?!”","“Ngoài cửa sổ! Chúng ở ngoài cửa sổ!”","Kính vỡ tung. Hoshiguma đu từ trên mái xuống, chiếc khiên đập nát cả khung cửa.","“Địch! Ta bị địch tấn công! L.G.D.… Là L.G.D.!”","“Hah! Tin đi là vừa!”","“Chết tiệt! Ả đu từ mái nhà xuống phá cửa sổ sao? Đánh! Di chuyển! Ta đông hơn, chỉ cần tàn sát chúng là được!”","“Đưa tôi bộ đàm,” Ch’en nói.","“Vâng!”","“Nghe đây, L.G.D.! Nghiền nát Reunion cùng với công sự của chúng!”","Một giọng nói thét lên trong bộ đàm. “Cái quái gì vậy?! Paci Plaza là tài sản của gia đình tôi! Sao cô dám—”","“Xin lỗi, cô gái nhỏ, Reunion vẫn đang phản kháng. Phải ưu tiên vô hiệu hóa chúng trước rồi mới nghĩ đến…”","“Cô nói gì?! Đồ vô dụng—!!”","“L.G.D.! Tấn công!”","“Trời ạ… Haizz…” Hoshiguma lắc đầu. “Cố cẩn thận một chút. Dù sao đây cũng là tài sản của dân mình. Họ không chuyển cây đàn piano kia đi, chắc vì nặng quá. Riêng nó đã đáng giá 1,8 triệu LMD. Cô gái nhỏ khoe với tôi đấy, nên cố cẩn thận.”","“Mày không thoát được đâu!”","“Tìm chỗ nấp! Nhanh! Nấp sau cây đàn piano kia!”","Một loạt Arts nổ tung. Cây đàn piano vỡ thành từng mảnh.","“Úi.”","“Chúng phá tan chỗ nấp của ta rồi! Đổi vị trí!”","“1,8 triệu… đi tong như vậy đấy.”","Một tên Reunion lao đến thiết bị liên lạc, hét vào micro. “Các đồng chí, các đồng chí! Nghe kỹ đây! Ta đã chiếm Paci Plaza làm căn cứ mới và dựng xong phòng tuyến. Nhưng L.G.D. đột nhiên tấn công từ mái nhà! Chúng đang tiêu hao quân ta! Báo động!! Chủ lực L.G.D. đang ở Paci Plaza! Tôi nhắc lại, Paci Plaza!”","“Xong chưa?”","“Từ khi nào mày—”","“Báo cáo xong rồi thì nhiệm vụ của ngươi cũng xong,” Ch’en nói. Cô ta không giơ kiếm. “Nhiệm vụ là để mọi lực lượng Reunion ở Lungmen biết rằng chúng ta ở đây. Chúng ta sẽ chờ chúng, chờ chúng đuổi theo và gặp L.G.D. trong trận chiến sinh tử. L.G.D.! Tiếp tục bắn! Đừng dừng lại!”","","“Dễ hơn tôi tưởng,” Hoshiguma nói sau trận đánh. “Càng khiến tôi tò mò chuyện gì đã xảy ra ở Chernobog.”","“Có lẽ cũng giống như ở đây, chỉ là gốc rễ ăn sâu hơn và ngọn lửa cháy dữ dội hơn. Đừng lơ là.”","“Cô biết là tôi hiếm khi nhắm mắt khi ngủ mà.” Hoshiguma nhìn quanh những cửa hàng đổ nát. “Ugh. Tôi đã cố kết thúc trận đánh càng sớm càng tốt, mà vẫn làm hỏng bao nhiêu cửa hàng. Sợ là ông Wei lại phải chi trả nữa, nhất là khi ông ấy vốn chẳng ưa gì gia đình cô gái nhỏ.” Cô ta dừng trước một tủ kính vỡ. “Này, pha lê Swarovski. Ch’en, chẳng phải đây là nhãn hiệu cô thích sao?”","“Không hẳn. Mặt dây chuyền thì đẹp, nhưng hoa tai thì không đẹp lắm.” Ch’en chạm vào thiết bị liên lạc. “Đội B1, Ch’en đây. Chặn lối vào phía tây, hạ tất cả cửa an ninh.”","“Hiếm khi thấy cô đeo hoa tai.”","“Thì vì công việc nên tôi hay mặc đồng phục. Mấy bộ đồ ít ỏi tôi có thì đang bám mạng nhện trong tủ.”","Một nhân viên L.G.D. chạy tới. “Thưa thanh tra Hoshiguma! Đây là sơ đồ tầng L3 của Paci Plaza Đông sau khi Reunion sửa đổi. Xin chị xem qua!”","“Tốt lắm. Tiếp tục điều tra, cố tận dụng địa hình. Sau đó ta sẽ tìm đường tốt nhất để vượt qua vòng phong tỏa của Reunion từ đây. Không có thông tin của cậu thì không xong.”","“Rõ!”","“Quần áo, hả…” Hoshiguma quay lại. “Khó tưởng tượng cô là người tiêu tiền vào mấy thứ đó.”","“Chẳng phải cô cũng thế với cả đống mô tô của cô sao? Thỉnh thoảng muốn trông xinh đẹp vì chính mình thì có gì sai? Công việc chiếm phần lớn thời gian của tôi, nhưng nó không phải cả cuộc đời tôi.”","“Tôi sẽ tin cô hơn nếu cô không xuất hiện sớm mỗi sáng như đồng hồ, lại còn nhận thêm giờ làm đủ để dọa chết bất kỳ ai.” Hoshiguma bật cười, rồi giọng cô ta chậm lại. “Tôi đoán chỉ có thể nói là với cảnh sát như chúng ta, cuộc sống cũng tạm chấp nhận được. Đôi khi tôi tự hỏi, những người Infected như Amiya… Họ có cơ hội đi mua sắm không? Mua vài món trang sức mình thích, hay ăn món mình yêu?”","“Có lẽ một ngày nào đó. Nhưng ngày đó chưa đến.” Ch’en lại chạm vào thiết bị. “C3, Ch’en đây. Dọn sạch tầng một, đẩy lên từ từ. An toàn là trên hết.”","“Tôi đoán vậy. Mảnh đất này thật bất công. Phal chết, còn tôi được sống tiếp.” Hoshiguma nhìn xuống đôi tay mình. “Họ chết cả rồi, chỉ có tôi được sống.” Cô ta ngẩng lên. “Ch’en. Tin tình báo đó có thật sự đáng giá không?”","“Nó phải đáng giá.”","Ở tầng dưới, một Caster Reunion bò ra từ đống đổ nát, máu chảy ròng ròng. <i>Lũ khốn… Ít nhất tao cũng sẽ chôn chúng mày cùng tao…!</i>","“Cô Ch’en! Chạy đi!!” Một nhân viên L.G.D. hét qua bộ đàm. “Chúng tôi phát hiện một lượng lớn thuốc nổ ở tầng ba! Ngay dưới chỗ cô đang đứng!!”","“L.G.D., chuẩn bị gặp đấng tạo hóa đi!”","“…!”","“Ch’en! Lại đây! Nấp sau khiên của tôi!!”","@cg:avg_5_5_fall_front","“Hả? Dưới chân tôi?”","“Ch’en!!”"],"bg":"bg_emporium","cast":[["Hoshiguma","op:char_136_hsguma"],["Ch'en","op:char_010_chen"],["L.G.D. Agent","npc:char_015_lmg"]]},{"c":"5-7","t":"Sống và chết","p":["“Ugh…”","“Lần thứ ba trong ngày rồi đấy, Người đẹp ngủ trong rừng.”","Ch’en mở mắt. Xung quanh tối om, bụi mù mịt. Ngay trên đầu cô ta, Hoshiguma đang quỳ một gối, chiếc khiên giương lên đỡ lấy cả một khối bê tông khổng lồ.","“Tôi ngất bao lâu?”","“Chục giây gì đó.”","“…Hoshiguma, tránh ra. Để tôi chém đống đổ nát này.”","“Xin lỗi, không được. Tôi mà cử động là cả hai ta tiêu. Để tôi lo.”","“Vai cô.”","“Không sao.”","“…Cô không trụ được lâu nữa đâu! Cô đang đỡ cả hai tầng gạch đá trên khiên!”","“Không cần trụ lâu nữa. Chỉ cần đến khi cô tỉnh thôi… Ngồi xuống, chuẩn bị lao ra.”","Ch’en im lặng, cúi người xuống.","“Dù nặng đến đâu…” Hoshiguma nghiến răng, những mạch máu nổi lên trên cổ. “…chỉ cần lật được nó đi… thì cũng chẳng nặng chút nào!! AAAAAGH!!”","Khối bê tông lật nghiêng, đổ sầm sang bên. Ch’en lao ra, kéo Hoshiguma theo.","“Cô…”","“Gaaah, aagh… Ngh… Cảm giác như mất luôn cái vai chỉ để đẩy một cái.”","“Cô lại cứu tôi nữa rồi.”","“Có gì lạ đâu? Lần thứ mấy rồi? Và đừng nói câu đó với tôi nghiêm túc thế… nghe mà nổi da gà.” Hoshiguma ngồi phịch xuống. “Để tôi nghỉ một chút. Cảm giác như gãy hết xương rồi… Có lẽ đến lượt cô để tôi chợp mắt một lát.”","“…Khốn kiếp, sao chúng còn sống sót được sau chừng ấy?!” Một toán Reunion xuất hiện ở cuối hành lang.","“Được thôi, nhưng kẻ địch không để cô nghỉ đâu,” Ch’en nói.","“Kẻ ác không được nghỉ ngơi, hả.” Hoshiguma chống tay đứng dậy. “Có vẻ cố một chút thì tôi vẫn đứng được. Cô nên đi tổ chức lại các đội, nhanh lên. Đừng phí thêm thời gian với chúng, đó là điều chúng muốn.”","“Tôi không nghĩ hạ hết chúng trước thì đã muộn.”","“Sao cô không đi xem ai bị thương trước?”","“Và để cô một mình đối mặt Reunion với ngần ấy vết thương?”","“Ch’en. Cô nghĩ mình đang làm gì vậy?” Giọng Hoshiguma cứng lại. “Hai năm trước ở Hua Shui, cô đuổi theo một tên thủ lĩnh cướp. Chân tôi bị thương, nhưng cô tin tôi và để tôi chiến đấu một mình. Cô còn nhớ không?”","“Tôi mất bao lâu để bắt được hắn?”","“Ba tiếng. Khi đó cô đã tin tôi.”","“Và tôi vẫn tin.” Ch’en rút kiếm, quay về phía đám Reunion. “Này, Reunion! Ta sẽ tiếp tất cả các ngươi!”","“Chết tiệt… Ả đang coi thường bọn ta!”","“Tôi vẫn đánh được. Sao cô lại ở lại?” Hoshiguma gắt. “Sao cô không dẫn các đội đi giành lại Trụ sở L.G.D.? Cô quên nhiệm vụ chính rồi à? Giống hệt ba năm trước, và đó là trách nhiệm chỉ mình cô gánh được! Lúc ở nhà kho Muk Wo cô cũng làm thế này. Cô trở nên do dự từ khi nào vậy? Ch’en!”","@cg:avg_5_5_chen","“Tôi không thấy có vấn đề gì khi bảo vệ đồng nghiệp khỏi lũ bạo loạn này.”","“Cô thay đổi rồi. Trước kia cô cứng rắn hơn nhiều.”","“Bỏ cô lại đây? Đương nhiên tôi làm được. Trước kia tôi chỉ nhìn vào rủi ro và lợi ích, nhưng giờ, đúng như cô nói…” Ch’en ngừng lại. “Sau những gì tôi đã làm với Amiya, tôi cũng… day dứt.”","“Các ngươi sẽ nếm cơn thịnh nộ của người Infected! Tấn công!”","Ch’en gạt một nhát chém, rồi nói tiếp, không quay đầu lại.","“Có lẽ tôi đã thay đổi thật. Theo thời gian, tôi bớt oán hận Lungmen, và đã có thể đặt niềm tin vào nhiều người hơn. Cô không còn chỉ là thanh tra Hoshiguma nữa. Cô là bạn tôi, và là cộng sự của tôi. Tấm khiên của cô đã bảo vệ tôi suốt ngần ấy thời gian, nên thỉnh thoảng, cô nên để tôi làm tấm khiên của cô.”","Hoshiguma nhìn bóng lưng ấy một lúc lâu.","“Phù. Nói hết những câu đó mà cô không đỏ mặt chút nào à?”","“Câm cái mồm lại.”","“Hahaha.” Hoshiguma ngồi xuống, tựa lưng vào tường. “Được rồi, được rồi. Vậy thì, Ch’en, tôi giao cho cô đấy.”","","“Y tế, Paci Plaza Nam cũ, lối ra số 12. Một người bị thương, một thanh tra cấp cao của L.G.D. Đến nhanh lên.” Ch’en hạ máy. “Cầm máu được chưa?”","“Cô biết tôi rồi mà. Vết thương khép lại rồi, nhưng một thời gian tôi sẽ không nhấc nổi khiên.” Hoshiguma nhìn quanh. “Các đồng nghiệp thế nào?”","“Chỉ có hai chúng ta ngã. Tôi coi đó là một chiến thắng nhỏ.”","“Cô thật sự không mang tôi theo à? Chỉ huy của Reunion có thể đang ẩn trong Trụ sở L.G.D. Sẽ là một trận đánh tàn khốc.”","“Tôi biết. Nhưng xét tình trạng của cô, thế là tốt nhất. Cô không đồng ý sao?”","“Nghe cô nói vậy hơi nhói một chút, nhưng không sao. Tôi hiểu mà.” Hoshiguma nhìn cô ta. “Nhớ cẩn thận ngoài đó. Nhìn kiểu gì thì Reunion cũng yếu hơn ta tưởng. Vậy mà chúng vẫn chiếm được Chernobog. Còn nữa, cô có một điểm yếu. Tôi không thể nhấn mạnh đủ, nhưng đừng bao giờ để suy nghĩ nuốt chửng mình. Không bao giờ. Đừng ám ảnh với một điều gì đó mà bỏ qua những khả năng khác. Ngoài đó chẳng có gì đáng để lao vào chiến đấu, ngoại trừ việc cô tiếp tục được sống.”","“Tôi coi đây là lời khuyên của cô. Tôi sẽ ghi nhớ.” Ch’en đứng dậy. “Mau khỏe lại đi. Tôi sẽ chờ cô quay lại sau khi xong nhiệm vụ này.”","“Tôi sẽ bảo vệ đội y tế. Cô đi đi.”","“Ừ.”","","Bộ đàm rè rè, những bản báo cáo nối tiếp nhau.","“…Reunion đã qua Causeway Bell. Báo cáo từ AU7: Reunion cũng đang tập hợp ở Ha Wan. Tôi nhắc lại, Reunion đang tập hợp. Đây là báo cáo nhiệm vụ của AU7. Đội AO3 đã tiêu diệt lực lượng Reunion ở Front Bay theo kế hoạch. Đang đẩy tàn quân về phía Trụ sở L.G.D. Mọi kẻ địch trước Scorpio Palace đã bị tiêu diệt. Đang rút về đại lộ Charles để đến điểm tập kết. Đây là báo cáo của Đội AL1, hết. …Đó là cập nhật về động tĩnh của Reunion và tiến độ của từng đội. Hết.”","“Đã rõ,” Ch’en nói. “Tiếp tục chiến dịch. Mục tiêu của chúng ta là dồn toàn bộ lực lượng Reunion vào khu vực đã định. Nếu phát hiện những nhóm nhỏ còn sót ở các quận khác, được phép tiêu diệt. Cố dụ chúng ra nếu có thể. Tập trung tránh thương vong. Ta cần giữ sức.”","“Rõ, thưa cô.”","Ch’en thở ra. Rồi thiết bị lại rung. “Hửm? Cuộc gọi khác?”","“A lô, a lô? Ah Ch’en đấy à? Cô còn đó không?”","“Cô gọi tôi là gì?!”","“Ah Ch’en. Cô tiêu rồi! Cô chết chắc vì chuyện ở Paci Plaza. Tôi tự tai nghe thấy — chính cô ra lệnh!”","“Cô chỉ muốn nói thế thôi à?”","“Này, sao cô lại từ chối sự giúp đỡ của Rhodes Island? Vì cô thấy có lỗi à?”","“Tôi không nhớ cô là nhà tâm lý học đấy.”","“Đừng lo, tôi sẽ giúp cô bù đắp.”","“Bù đắp?”","“Hehe, chưa nói được. Nhưng mà cô tiêu rồi vì những gì cô đã làm!”","“Nhân tiện, cô còn nhớ quán ăn ở Sheung Wan không?”","“Hả? Quán nào? Mà quán nào thì giờ cũng đóng cửa hết rồi! Khoan… cô đang đánh trống lảng à?!”","“Quán có bánh sandwich bít tết ngon tuyệt ấy.”","“Hả? Ồ… Ồồ! Tôi nhớ ra rồi! Cái quán có bánh burger bít tết to bằng hai bàn tay đặt cạnh nhau!”","“Đúng quán đó.”","“Hồi đi tuần tôi hay ghé đó lắm… Nằm xuống! Ai cho mày đứng dậy?!”","“Aaah!!” Một tiếng hét vọng lại từ phía Swire.","“Quán đó tên gì nhỉ? Goodie Foodie?”","“Nghe đúng đấy.”","“A ha, giờ thì tôi hiểu rồi. Cô định mời tôi ăn, phải không? Nhưng sao không đi chỗ nào sang hơn một chút?”","“Định nghĩa ‘sang’ của cô khác tôi nhiều lắm.”","“Thôi nào, tôi trả tiền cũng được.”","“Cô S, cô nghĩ tôi là loại người đó thật à?”","“Cô có muốn thử gọi tôi như thế lần nữa không?”","“Xin lỗi, tôi cắn phải lưỡi.”","“Rõ ràng cô cố tình!”","Ch’en im lặng một nhịp, rồi giọng cô ta trầm xuống. “Swire, tôi vừa nghĩ… Nếu lần này không làm tốt hơn, ta sẽ không dám nhìn mặt người dân địa phương. Việc làm ăn của chúng ta phụ thuộc vào Lungmen, và Lungmen cũng phụ thuộc vào họ.”","“Nếu cô nghĩ vậy thì bớt nói nhảm đi. Hạ Reunion càng sớm, cô càng sớm mời tôi bữa sáng muộn.”","“Có vẻ bên cô cũng đánh nhau ác lắm?”","“À, không sao. Tôi lo được.” Tiếng hét vọng lại: “Nhanh! Chúng sắp chạy mất rồi!” “Phiền quá! Này, nhanh lên! Bọn tôi không có cả ngày đâu!” Swire quay lại máy. “Ah Ch’en! Tôi muốn một cái burger bít tết, cà chua, trứng!”","“Không vấn đề.” Ch’en ngừng lại. “Xin lỗi vì lần đó vô tình nhốt cô trong két sắt.”","“Cô gọi đó là vô tình á?! Tôi biết cô cố ý! Thôi kệ, sáng nay tạt nước vào cô sướng lắm, coi như huề.” Một quãng lặng. “Này, Ah Ch’en.”","“Hửm?”","“An toàn là trên hết. Đừng vứt mạng sống vì những gì ngay trước mắt. Nhớ rằng có rất nhiều người đang trông cậy vào cô.”","“Hừ, vậy sao. Cảm ơn lời khuyên.”","“Giờ cô đang đứng trước quán ăn đó, nghĩa là sắp đến Trụ sở L.G.D. rồi, phải không?”","“Đúng vậy.”","“Chúc may mắn.”","@bg:bg_building_3","<i>7:40 tối. Nhiều mây.</i><br><i>Cách Trụ sở L.G.D. 670 m về phía đông, phố Upper Factor, Thượng Lungmen.</i>","“Cô Ch’en, Đội Cơ động số Bốn báo cáo.”","“Làm tốt lắm.” Ch’en nhìn những gương mặt trước mặt. Mệt mỏi, lấm lem, nhưng không ai cúi đầu. “Tất cả những người tập hợp ở đây đều là tinh hoa. Ngay lúc này, nhiều đồng nghiệp của chúng ta vẫn đang chiến đấu ngoài kia. Nhưng chúng ta có nhiệm vụ riêng.”","Cô ta quay lại, chỉ về tòa nhà cao tầng sừng sững cuối phố.","“Tòa nhà trước mặt chúng ta từng là biểu tượng an toàn của Lungmen. Hiện thân của luật pháp và trật tự, trái tim của L.G.D. Nhưng giờ, nó đã rơi vào tay Reunion, bị vấy bẩn bởi âm mưu và chiến tranh.”","@cg:bg_5_6_police","“Một số người có thể xem đây chỉ là một công việc. Một số có thể buồn, số khác có thể giận dữ. Dù các cậu cảm thấy thế nào, chúng ta là L.G.D. Chúng ta không phải kẻ bạo loạn, cũng không phải tội phạm. Chúng ta sẽ giành lại trụ sở, không nhất thiết vì danh dự hay công lý. Chúng ta làm vì chúng ta là L.G.D., và chúng ta sẽ lấy lại những gì thuộc về mình. Đó là lý do duy nhất ta cần.”","“Đừng để Lungmen phải lo lắng cho chúng ta. Rõ chưa?! Phục tùng, cần mẫn, kiên trì!”","“Đến lúc rồi. Hãy quét sạch đến tên Reunion cuối cùng khỏi Trụ sở L.G.D.!”","“Rõ, thưa cô!”","“Đi thôi.”"],"bg":"bg_emporium","cast":[["Ch'en","op:char_010_chen"],["Hoshiguma","op:char_136_hsguma"],["Swire","op:char_308_swire"]]},{"c":"5-9","t":"Quỷ dữ","p":["<i>11:20 đêm. Nhiều mây.</i><br><i>Bên ngoài Phòng Xuất nhập cảnh, tầng 2 Trụ sở L.G.D., Thượng Lungmen.</i>","“Cô Ch’en, có gì đó không ổn,” một nhân viên L.G.D. thì thầm. “Cô không thấy lạ khi ta vào trụ sở dễ dàng thế này sao? Bên ngoài có bao nhiêu quân Reunion, ta đã chuẩn bị tinh thần cho một trận khó, nhưng chúng cứ như đang mộng du. Theo trinh sát, trang bị của chúng hư hỏng gần như không dùng được. Chúng không có vẻ đã đánh nhiều trận, mức độ sẵn sàng thì… Tôi thấy rợn người.”","“Tôi cũng để ý rồi. Chúng còn không biết ta ở đây. Ít ra lúc này chúng không phải mối đe dọa.” Ch’en nhìn quanh hành lang tối om. “Làm theo kế hoạch. Tiếp theo, các đội phi tác chiến sẽ trinh sát sự phân bố của Reunion ở từng tầng, thử khởi động lại hệ thống an ninh đã bị vô hiệu hóa. Ngoài ra, phải sẵn sàng chống một cuộc bao vây có thể xảy ra từ Reunion. Phải trụ đến khi kế hoạch được thực hiện trơn tru. Tập trung kiểm soát tình hình bên trong.”","“Theo nguồn tin, trung tâm chỉ huy tạm thời của Reunion ở trên sân thượng.”","“Sân thượng? Loại thủ lĩnh nào lại đặt trung tâm chỉ huy trên mái nhà? Hừm… rất có khả năng là bẫy.”","“Nhưng ta không có lựa chọn, đúng không thưa cô?”","“Đúng vậy. Giành lại sân thượng sẽ như thắp lên ngọn đèn hiệu của Lungmen. Ta sẽ để Reunion chứng kiến khoảnh khắc Trụ sở L.G.D. trở về tay chúng ta. Ta nên dẫn tất cả chúng đến đây. Chuẩn bị đi, còn vài tiếng nữa. Cho đội trinh sát và công binh đi trước. Các đội chiến đấu còn chút thời gian nghỉ ngơi trước khi chiến dịch chính bắt đầu. Đừng bỏ phí dù một cơ hội nhỏ nhất để tạo lợi thế. Hãy chờ đợi kẻ địch chiến đấu đến chết.”","“Cô Ch’en, tòa nhà này có gì đó không ổn,” nhân viên kia nói tiếp, giọng nhỏ hơn. “Cho tôi phỏng đoán trước. Càng gần tầng trên, ta có thể gặp kháng cự. Có thể có địch đóng trên mái. Nhưng các tầng dưới hoàn toàn trống. Chỉ đến tầng sáu mới bắt đầu có địch, và dù số lượng tăng lên, chúng chẳng gây nguy hiểm gì. Vừa rồi, một thành viên trong đội tôi báo là thấy vài tên Reunion đi xuống một hành lang, nhưng chúng biến mất trong chớp mắt. Một người khác bảo nghe thấy tiếng thì thầm, nhưng đến xem thì chẳng có gì. Đó là tất cả những gì bọn tôi tìm được. Nhưng tôi vẫn thấy có gì đó sai sai.”","Ch’en im lặng một lúc.","“Đi trước đã. Tôi không có thời gian cho mấy chuyện ma quỷ vô lý của cậu. Dù có gì bất thường, tôi sẽ xử lý sau khi xong việc.”","“Rõ, thưa cô!”","“Đi đường thoát hiểm này. Dù ít dùng, giờ nó sẽ có ích. Cầu thang này dẫn thẳng lên sân thượng. Các cậu kiểm soát tầng trên cùng, dùng lợi thế tầm nhìn yểm trợ tôi. Tôi sẽ lên thẳng sân thượng, ổn định tình hình rồi hội quân với các cậu.”","“Cô Ch’en, cô thật sự đi một mình sao? Dù tình hình thế nào, tôi chắc bọn tôi giúp được.”","“Tôi hoàn toàn tin vào năng lực của các cậu. Tuy nhiên, trong trận sắp tới tôi có thể phải dốc toàn lực. Điều tốt nhất các cậu có thể làm để giúp tôi là dọn sạch Reunion khỏi cả tòa nhà này, để tôi không phải lo gì khác.”","“Vậy bọn tôi sẽ không cản đường cô, cô Ch’en. Lungmen trông cậy vào cô.”","“Sai rồi. Lungmen trông cậy vào chúng ta.”","“Rõ!”","“Nhanh lên!”","","@cg:avg_5_7_1","Gió đêm thổi lồng lộng trên sân thượng. Giữa những ăng-ten và đường ống, một thiếu niên tóc trắng đang đứng chờ, như một diễn viên chờ người diễn cùng bước ra sân khấu.","“Chào buổi tối, quý cô. Một mình lao thẳng vào bẫy của ta. Ta nên gọi cô là dũng cảm, hay chỉ là ngu ngốc?”","“Ngươi không còn đường chạy đâu, chỉ huy Reunion.”","“Vậy sao? Theo góc nhìn của ta, quý cô, chính cô mới là người không còn đường chạy. Các đồng chí của ta sẽ nuốt chửng cô.”","“Nói thì dễ. Cho ta xem ngươi có gì đi.” Ch’en rút kiếm. “Lẽ ra ngươi không bao giờ nên đặt chân đến đây, Reunion!”","","“Khụ khụ…” Mephisto lảo đảo lùi lại.","“Ngươi không phải đối thủ của ta!”","“Cô một mình đánh bại hết các đồng chí của ta sao? Có lẽ ta phải đánh giá lại năng lực của cô, quý cô.”","“Đủ rồi.”","“Không, còn xa lắm. Faust, rung cây cho cô ta xem.”","“Đã hiểu.”","“…!” Ch’en quay phắt lại. “Những người trên mái, nằm xuống!”","Một mũi nỏ nổ tung ngay sau lưng cô ta. Một nhân viên L.G.D. hét lên, ngã lăn.","“Sniper của Reunion…” <i>Mình đã chuẩn bị cả cho đòn tầm xa, vậy mà sao hắn mang được hỏa lực lớn đến thế…?</i> “Từng đó không cứu được mạng ngươi đâu. Ngươi sẽ chết trước khi sniper của ngươi bắn trúng ta.” Rồi cô ta khựng lại, nhìn kỹ bóng người mang nỏ khổng lồ trên một bệ cao. “…Khoan. Ngươi từng bị L.G.D. bắt phải không?”","@cg:avg_5_shot","Faust không trả lời.","“Bọn các người đã gây cho cậu ấy rất nhiều đau khổ,” Mephisto nói. “Nhưng chẳng là gì so với những gì Ursus làm với chúng ta. Cậu ấy cố tình bắn trượt đấy, quý cô. Lần này bọn ta tha mạng cho cô, cứ coi như một cử chỉ tử tế. Ngay lúc này, mầm mống bất ổn đã được gieo trong L.G.D. Chính sự mục nát và lơ là của tổ chức các người đã cho cậu ấy cơ hội hợp tác với bọn ta.”","“…Lũ cặn bã Reunion, các ngươi chẳng biết gì về thế giới này.”","“Cô đang cố nói điều gì sâu sắc à?”","“Ngươi nghĩ Faust được Reunion giải cứu sao?”","“Khi đó trong L.G.D. có nhiều người Infected.”","“Hai mươi mốt.”","Mephisto im lặng.","“Ngươi nghĩ ít nhất bốn người trong số đó sẽ đứng về phía Reunion sao? Nhưng ngay cả bốn người đó cũng do ta sắp đặt. Sau khi họ liên lạc với các ngươi, các ngươi đã nhốt một người lại, phải không?”","“Thông minh lắm, quý cô. Cô ta chạy mất rồi.”","“Ngươi vẫn chưa nhận ra tình cảnh của mình sao?”","“Đương nhiên là ta nhận ra rồi. Đội của ta bị nghiền nát, chỉ còn mình ta. Lực lượng của ta lang thang bên ngoài yếu đến tuyệt vọng, các đồng chí của ta gần như mất hết ý chí chiến đấu. Đó là điều cô muốn nghe ta nói sao?”","“Xem ra ngươi không kiêu ngạo đến thế.”","“Vậy thì…” Mephisto giơ cây trượng lên. “Đến đây, các hộ vệ của ta. Đứng dậy.”","Những thân thể Reunion nằm la liệt trên sân thượng bắt đầu co giật.","“Ugh… argh… Ooaarrrggh!!!”","“Ngươi đã làm gì?!” Ch’en lùi lại. “Những mảnh Originium trên người chúng… đang lớn lên?”","“Originium sẽ xuyên qua cơ thể chúng và trở thành hình hài mới,” Mephisto nói, giọng dịu dàng như một người cha. “Hãy nhìn đi, sĩ quan. Đây là các hộ vệ của ta, những hộ vệ bất tử của ta.”","“GRAAAAAAGHHH!!”","“Hãy nhận lấy tất cả, đàn chiên của ta, các đồng chí của ta…” Mephisto thổi nhẹ vào lòng bàn tay. Một làn bụi lấp lánh bay ra, rải xuống khắp sân thượng.","“Bột…?”","@cg:avg_5_7_shining","“Các đồng chí của ta cần được chữa lành. Họ cần ta.”","“Arts? Tất cả các đội, cảnh giác! Chỉ huy địch đang thi triển Arts diện rộng bằng một loại bột!”","“Đừng lo, quý cô. Chuyện này không liên quan đến cô, vì cô không phải đồng chí của ta.”","Những tiếng rên rỉ biến thành những tiếng gầm. Rồi những tiếng gầm biến thành thứ âm thanh không còn là tiếng người nữa.","“Ugh… Aagghh—”","“…Unghh… Nnngh!”","“Nghhhaaahghh…”","“…Máu!! Máu!! Aaaargh!!! Aaaaaggh!!!”","“Im lặng nào,” Mephisto nói.","Tất cả im bặt.","“Cô Ch’en, tình hình tệ lắm…” bộ đàm rè rè. “Tất cả những tên Reunion đã bị hạ bắt đầu biến thành những quái vật khổng lồ sau khi tiếp xúc với thứ bột đó! Chúng bắt đầu tấn công lại, và đang từ từ tiến về phòng tuyến của ta!”","“Bao nhiêu tên đã biến đổi?”","“Tất cả!”","“…!”","“Chúng là đàn chiên của ta, cũng là anh em của ta,” Mephisto nói. “G7, G6.”","“…Urgh.”","“Ngươi…”","“Chúng sẽ không bao giờ gục ngã, vì ta sẽ lấy đi mọi nỗi đau của chúng.”","“Ngươi chỉ đang điều khiển chúng như rối. Sao ngươi có thể gọi chúng là anh em?”","“Ta chẳng thấy khác biệt gì giữa hai điều đó. Vì lợi ích lớn hơn, chúng ta sẵn sàng trở thành bất cứ thứ gì.”","“Nếu đó là cái ngươi gọi là lợi ích lớn hơn… thì có vẻ ngươi là kẻ duy nhất ta cần loại bỏ.”","“Cô có mục đích, và ý chí để thực hiện nó. Ta khá bị cô cuốn hút đấy, quý cô.”","“Tập trung hỏa lực! Nhanh! Nhắm vào chỉ huy địch!”","Một loạt nổ dội vào bức tường thịt của những hộ vệ. Khi khói tan, chúng vẫn đứng đó.","“Chúng vừa đỡ vụ nổ bằng thịt… mà hoàn toàn không hề hấn gì?! Hỏa lực đó… lẽ ra đủ phá thủng một lớp tường thành gia cố!”","“Đừng phí công,” Mephisto nói. “Vết thương sẽ lành. Da thịt sẽ cứng lại. Sự sống sẽ trở về. Vũ khí của các ngươi không làm hại được hộ vệ của ta. Dù sao, ta đã chuẩn bị chúng đặc biệt cho cô. Đứng dậy, các đồng chí. Đừng để ai xen vào cuộc trò chuyện của bọn ta.”","“Cô Ch’en, Reunion tấn công hết đợt này đến đợt khác! Không thể đánh bại chúng bằng cách thông thường! Chết tiệt, chúng không biết đau sao?! Các đội khác cũng vậy! Quân Reunion bên ngoài cũng bắt đầu di chuyển, liên tục lao vào trụ sở, cố tấn công các cơ sở an ninh!”","“Ưu tiên xử lý kẻ địch gần mình nhất!”","“Tránh ra! …Cô Ch’en, những thứ này hoàn toàn không có cảm giác! Chúng đã bao vây hoàn toàn Trụ sở L.G.D.! Bọn tôi bị buộc phải đánh cận chiến! Không thể hỗ trợ cô được!”","“Tự bảo trọng.”","“Rõ!”","“Uy nghi quá, phải không?” Mephisto ngắm nhìn đàn quái vật của mình. “Sau bao nhiêu trận chiến, tâm trí chúng có vẻ đã tan rã, nhưng cơ thể vẫn khỏe mạnh cường tráng. Sức mạnh thuần túy có vẻ bù đắp được phần nào cho những sai lầm trong quyết định. Ít ra ta có nhiều thời gian để từ từ nói chuyện. Ta muốn có một cuộc trò chuyện bổ ích với cô, quý cô, về những điều không liên quan đến trận chiến này.”","“Không cần.” Ch’en lao tới. “Ta sẽ giết ngươi ngay bây giờ.”","“Cô nhanh thật!”","Một mũi nỏ xé gió bay tới. Ch’en vung kiếm, gạt nó sang bên trong một tia lửa.","“Nhưng chưa đủ nhanh.”","“Ả gạt được phát bắn của ta bằng lưỡi kiếm?” Faust nheo mắt.","Một hộ vệ khổng lồ chắn ngang đường. <i>Thằng nhóc tóc đen đó đọc chuyển động của mình rất giỏi. Chậc… Có vẻ kế hoạch của chúng là quấy rối mình bằng sniper, rồi đoán trước chuyển động và chặn đường mình.</i>","“Xin lỗi, quý cô. Ta gần như đoán được mọi nước đi của cô. Chỉ cần chặn cô một chút là được. Như vậy cô sẽ không bao giờ thu hẹp được khoảng cách. Vậy cô thích loại nào? Tên nhọn, mũi nổ, hay chông nặng?”","Ch’en đứng im một lúc.","“Xem ra ngươi thật sự đã chuẩn bị kỹ. Nhưng khi một kỳ thủ chuẩn bị xong, hắn luôn giả định đối thủ sẽ cầm quân màu kia.”","<i>Khoan đã, sao bột của ta vẫn còn bám trên người cô ta…?</i> Mephisto nheo mắt. <i>Ra vậy, ta hiểu rồi…</i>","“Ta không giỏi lý thuyết như ngươi, nhưng ta chỉ đơn giản là chuẩn bị cho mọi thứ.” Ch’en giơ kiếm lên. “Bàn cờ của ngươi không chứa nổi ta đâu, nhóc. Ta không phải quân cờ. Ta là lưỡi kiếm của Lungmen.”","“Hừm… Ranh giới giữa dũng cảm và ngu ngốc thật mong manh. Hay cô định rút ra con át chủ bài nào đó? Nếu ta nhớ không nhầm, ta chưa từng thấy cô dùng thanh kiếm kia trong chiến đấu.” Mephisto nhìn thanh kiếm thứ hai đeo bên hông Ch’en, chuôi đỏ thẫm, vỏ được buộc kín. “Chắc nó không chỉ để trang trí đâu nhỉ?”","“Hah. Thanh kiếm này không phải để rút ra trước loại như ngươi. Dù thế nào ngươi cũng không xứng đáng. Tuy nhiên, ngươi phải trả giá cho tội ác của mình, cho những gì ngươi đã làm với người dân vô tội của Lungmen và Chernobog.”","Cô ta đặt tay lên chuôi kiếm.","“Ngay tại đây, ngay lúc này.”","@bg:bg_rooftop","Có một ký ức, rất cũ.","<i>“Thứ này giờ thuộc về cô,”</i> Wei Yenwu nói, đặt thanh kiếm lên bàn.","<i>“Tôi không cần.”</i>","<i>“Vậy cứ coi như cho mượn.”</i>","<i>“Ông không sợ sao?”</i>","<i>“Sợ gì? Sợ cô quay lưng với ta à?”</i>","<i>“Phải.”</i>","<i>“Không, ta không sợ.”</i>","<i>“Tại sao?”</i>","<i>“Vì ta không sợ chết.”</i> Ông ta mỉm cười. <i>“Đây không phải vũ khí bình thường. Rồi cô sẽ dần hiểu. Đừng lãng phí sức mạnh của nó vào chuyện vặt. Kiếm đồ long chỉ được rút ra trước một kẻ thù xứng đáng. Rút thanh kiếm này ra trước ai, hoàn toàn do cô quyết định.”</i>","<i>…Thanh kiếm này vẫn đang ngủ,</i> Ch’en nghĩ, những ngón tay siết chặt quanh chuôi kiếm lạnh ngắt. <i>Đến nước này mà mày vẫn không chịu rời vỏ… Nhưng ngay lúc này, Chi Xiao, mày phải uống máu chúng!</i>"],"bg":"bg_indoor_3","cast":[["Ch'en","op:char_010_chen"],["Mephisto","npc:char_1507_Mephisto_1"],["L.G.D. Agent","npc:char_015_lmg"],["Wei Yenwu","npc:char_2005_weiyw_1"],["Faust","npc:char_1508_Faust_1"]]},{"c":"5-10","t":"Bóng tối trước bình minh","p":["“Đến lượt cô đi,” Mephisto nói. “Nếu cô giết được ta ở đây, toàn bộ lực lượng của ta sẽ sụp đổ. Thật đáng tiếc nếu cô còn từ chối nói chuyện với ta. Xin mời, đến giết ta đi, nếu cô làm được.”","“Cô Ch’en!” bộ đàm hét lên. “Đòn tấn công của địch quá áp đảo! Không thể kéo dài thêm được nữa!”","“Tình hình rất đơn giản, chỉ một trong hai ta sống sót,” Mephisto nói. “Ta hứa sẽ nói lời trăng trối thật ngắn, quý cô, miễn là cô khiến ta phải nói ra.”","“Ngươi nghĩ mình là kẻ tử vì đạo sao?” Ch’en nói. “Chết rồi sẽ chẳng ai nhớ đến ngươi. Chết và được tôn trọng là hai chuyện hoàn toàn khác nhau. Điều quan trọng là những gì ngươi làm khi còn sống, không phải ngươi chết thế nào.”","“Đương nhiên ta chẳng mong gì hơn được chơi với những đối thủ xứng đáng, rồi chết một cái chết xứng đáng. Nhưng ta không nghĩ cô giúp ta thỏa nguyện được. Cô sẽ chịu một thất bại thảm hại, quý cô. Giờ đến lượt ta chỉ ra tình cảnh của cô.”","“Sự tự tin của ngươi được xây trên sự sụp đổ của Chernobog. Nhưng đây không phải Chernobog, cũng không phải vùng đất tàn nhẫn Ursus. Lungmen hùng mạnh sẽ không rơi vào tay lũ cặn bã như ngươi.”","“Nói hay lắm. Faust.”","“Tôi biết.”","“GROOAAAAAR!!”","Ch’en vung kiếm. Không phải một nhát chém, mà là một luồng đỏ rực bùng lên từ lưỡi kiếm, quét ngang qua hàng hộ vệ như một ngọn sóng lửa.","“Đó là một nhát chém? K-không, không thể nào! Lẽ nào… là Arts?!”","“Lùi lại,” Faust nói, kéo Mephisto ra sau.","“Cái gì… Sao có thể…”","Một hộ vệ quỵ xuống, cổ bị cắt gần đứt. Nó rên rỉ, một âm thanh như tiếng khóc.","“Đừng sợ!” Mephisto vội nói. “Nó không làm hại được ngươi đâu. Không cần sợ.”","Tiếng rên tắt dần.","“Phù…” Ch’en thở ra. <i>Hắn ở quá xa. Thu hẹp khoảng cách sẽ chỉ ngày càng khó. Kéo dài thì mình bất lợi.</i>","“Kỹ năng của cô thật đáng gờm,” Mephisto nói. “Cô dùng Arts kích nổ trước đòn của Faust, phá vỡ đội hình của ta. Lưỡi kiếm của cô còn cắt qua cổ hộ vệ của ta, suýt chạm đến ta. Nếu ta để cô tiến thêm vài bước, cô đã chém ta làm đôi. Đến cả Faust cũng không ngăn được cô.”","“Lần sau ngươi sẽ không may mắn như vậy đâu.”","“Tiếc là sẽ không có lần sau. Bí mật của cô đã bị lộ, quý cô. Cô biết câu đấy, đừng bao giờ dùng cùng một mánh hai lần. Một khi bí mật bị lộ, khán giả sẽ không bị lừa nữa. Khoảng cách giữa chúng ta xa hơn tầm Arts của cô, phải không?”","“Sân thượng chỉ rộng có vậy. Ngươi chẳng còn nhiều chỗ để lùi.”","“Cô còn tiến gần được bao nhiêu? Faust, cho cô ta thấy Arts thật sự là gì.”","“Ta biết vị trí của ngươi quá rõ. Một sniper đã lộ diện chẳng gây được…”","Hai mũi nỏ đến cùng lúc. Một từ bệ cao của Faust. Một từ hướng ba giờ, nơi không có ai cả.","Ch’en gạt được cả hai. Nhưng cô ta lùi lại một bước.","“Cô thật phi thường, cô Ch’en,” Mephisto nói. “Cô có thể chém đứt mọi phát bắn nhắm vào mình sao? Giống như lúc nãy, ta gần như không nhìn thấy chuyển động của cô.”","Ch’en im lặng. Rồi cô ta nói, mắt vẫn nhìn về hướng ba giờ trống trải. “Sniper, ta vừa bị ngươi và một kẻ từ hướng ba giờ tấn công cùng lúc. Nhưng ở hướng đó chẳng có ai. Ta không nghĩ ngươi là loại Caster đó.”","“Cô không cần đoán đâu, sĩ quan. Cô sẽ không đoán ra được.”","“Chậc.”","“Giờ thì, cô gạt được bao nhiêu phát nữa? Mười? Bốn mươi? Một trăm? Nhưng còn mảnh vỡ thì sao? Sóng nổ? Còn Arts bên trong? Cô có chặn được hết không?”","“Nói nhảm.”","“Vậy thì tiếp tục!” Mephisto dang tay. “Sĩ quan, ta biết cô là gì. Originium Arts của ta chỉ có tác dụng với người Infected.”","“Ta không quan tâm.”","“Cô không biết rằng cô chỉ sẽ trở thành con tốt của hắn, bị vứt bỏ khi đã hết giá trị sao?”","“Câu đó ta trả lại cho ngươi.”","“Bọn ta sẽ cho cô một cơ hội. Lungmen thì không.”","“Cô Ch’en, sợ là bọn tôi phải lui xuống tầng dưới! Không chống nổi đòn tấn công dữ dội của địch!”","@cg:avg_5_7_chen_2","<i>Chậc… Mình vừa định di chuyển là sniper sẽ tấn công từ mọi hướng. Rốt cuộc hắn làm thế nào vậy…? Mình có thể vô hiệu hóa đòn tầm xa của hắn, nhưng nếu để hắn tiếp tục bào mòn, mình sẽ không trụ được lâu. Phải giành chiến thắng trong một khoảnh khắc quyết định duy nhất…!</i>","“Ta không quan tâm ngươi nói gì. Ta không có thời gian nghe ngươi lải nhải.”","Ở bệ cao, Faust nheo mắt. <i>Tôi thấy một luồng sáng đỏ đang tụ quanh cô ta. Cô ta sắp dùng Arts.</i> “Mephisto, theo kế hoạch, nếu tôi bắn bây giờ, cô ta sẽ phải dừng thi triển, không thì sẽ chết trong vụ nổ.”","“Nhưng chẳng phải đây là cơ hội tốt nhất để bẻ gãy tinh thần cô ta sao? Giữ lửa, cứ quan sát cô ta trước đã.”","“Ta sẽ bỏ lỡ cơ hội.”","“Mục tiêu chiến lược lớn hơn quan trọng hơn chiến thuật cụ thể để đạt được nó, Faust.”","Faust không nói gì nữa.","","Ch’en nhắm mắt lại. Và trong bóng tối sau mí mắt, có những giọng nói khác.","<i>“Đi với mình! Đừng ở lại đây nữa!”</i>","<i>“Cậu không muốn rời khỏi đây sao? Hãy đi thật xa, thật xa khỏi những người này, khỏi nơi này!”</i>","<i>“Cậu thật sự không biết sao? Ông ta là lý do khiến tất cả người lớn đối xử với chúng ta như vậy! Tất cả là lỗi của ông ta!”</i>","<i>“……”</i>","<i>“Mình ghét thành phố đáng nguyền rủa này. Mình ghét ông ta. Đừng bắt mình phải ghét cả cậu nữa.”</i>","Ch’en mở mắt.","“Chi Xiao—”","Lưỡi kiếm đỏ thẫm bắt đầu trượt ra khỏi vỏ.","@cg:avg_5_7_chen","“—Rời vỏ!”","“Hộ vệ, xếp hàng! Chặn cô ta lại!” Mephisto hét.","“EEEEAAAAAARRRGHH!!”","Rồi thanh kiếm khựng lại. Như bị một bàn tay vô hình giữ chặt, nó đứng im ở nửa chừng, ánh đỏ chập chờn rồi tắt ngấm.","“Ugh…!” <i>K-không! Mình mất kiểm soát Chi Xiao sao? Sao lại đúng lúc này?!</i>","“Arts của cô ta ngắt quãng. Thi triển thất bại,” Faust nói.","“Faust, ngay.”","“Hiệu lệnh, bắn.”","“Chết tiệt… Tản ra!”","Hàng chục mũi nỏ trút xuống cùng lúc. Ch’en vung thanh kiếm còn lại, một luồng đỏ bùng nổ từ lưỡi kiếm, hất văng phần lớn chúng. Nhưng không phải tất cả. Một vụ nổ hất cô ta ngã sấp xuống sàn bê tông.","“Một thứ vũ khí đáng sợ thật,” Mephisto nói, bước tới. “Chỉ riêng sự phát tán của Arts đã đủ chặn hết những mũi nỏ, còn hạ được ba hộ vệ của ta. Nhưng cô vẫn trúng sóng nổ, phải không?”","“Ugh… Gahh…” <i>Một xương sườn, không, hai cái gãy rồi? Mình chịu được. Nhưng hỏa lực này… Không thể chịu thêm một đợt nữa…</i>","“Đúng như thủ lĩnh của bọn ta nói,” Mephisto mỉm cười. “Quý cô, không phải cô không muốn giết ta. Mà là cô không thể rút thanh kiếm đó ra.”","“Ngươi nói gì? Ai nói với ngươi điều đó?”","“Cô hẳn biết cái tên này, cô Ch’en. Như cô nói, thanh kiếm này không phải để dùng với người như ta. Sự liều lĩnh của cô đã phá vỡ cơ chế vốn có của nó. Nếu bọn ta nắm lấy cơ hội tấn công khi cô không phòng bị, cô đã thành tro bụi rồi. Cô ấy đã biết hết mọi điểm yếu của cô.”","“Ngươi phí lời rồi.”","“Bọn ta sẽ phá hủy thế giới như nó đang tồn tại. Nếu để sự mục nát tràn lan, cả thế giới sẽ thối rữa. Chỉ bằng cách cắt bỏ tất cả, những thành phố rỉ sét này mới có thể phá xiềng xích và tái sinh.”","@cg:avg_5_7_moph","“GRAAAAAAGHHH!!”","“Tránh đường.” Ch’en chống kiếm đứng dậy.","“Đến đây, cô Ch’en. Chẳng phải cô cũng rất thất vọng về Lungmen sao?”","Ch’en im lặng.","“Thủ lĩnh của bọn ta đang chờ cô. Chẳng có lý do gì cô phải cúi đầu trước Lungmen, phải không?”","“Ta có bổn phận của ta.”","“Điều đó chẳng liên quan gì đến chuyện cô đứng về phía nào. Trong khi cô cứ nói mãi về những ‘bổn phận’ tầm thường ấy, cô biết rõ đồng bào của chúng ta đang bị đối xử ra sao. Chỉ cần cô ra hiệu, ta sẽ ngừng tấn công ngay. Đến đây, gia nhập bọn ta. Hãy cùng nhau hướng tới lợi ích lớn hơn.”","Ch’en nhổ một ngụm máu xuống sàn.","“Ngụm máu này là dấu hiệu duy nhất ta có cho ngươi. Reunion có thể có mục tiêu cao cả gì khi thuê một kẻ hèn hạ như ngươi? Đừng nói nhảm với ta nữa!”","“Vậy là thế à. Nếu cô không tin ta, thì đó là thiệt thòi của cô.” Mephisto quay đi. “Cô có thể dùng những giây phút cuối cùng để giãy giụa tùy thích. Người bảo hộ của ta và những mũi nỏ của cậu ấy sẽ cho cô thấy sức mạnh thật sự của người Infected. Cô chỉ có một mình, còn bọn ta đoàn kết và mạnh mẽ. Cái chết của cô sẽ rất xứng đáng.”","“Để dành những lời thối rữa đó cho đến khi ngươi chết đi.”","“Hoặc, cô có thể cưỡng ép kích hoạt Originium Arts trong thanh kiếm đó. Chuyện khủng khiếp sẽ xảy ra, phải không? Ta để cô tự quyết định số phận của mình.”","“Ngươi nghĩ mình sẽ có một cái chết anh hùng sao?” Ch’en lại đặt tay lên chuôi Chi Xiao. Lần này, những ngón tay cô ta không run. “Nghe đây, nhóc. Khi một người chết đi, chẳng còn lại gì cả. Nếu ta phải hy sinh bản thân để giết ngươi… ta sẽ làm, dù nó chẳng đáng.”","“Hừ. Vậy là ta chẳng còn gì để nói nữa. Vĩnh biệt, cô Ch’en. Faust.”","“Hiệu lệnh, b—”","“Chậc…”","@cg:avg_5_8_sky","“Cô không cần làm đến mức đó đâu, cô Ch’en!”","Một giọng nói vang lên từ trên trời.","“…?”","“Cái gì thế?” Mephisto ngẩng lên.","Một cỗ máy lạ lùng đang lơ lửng trên đầu họ, cánh quạt gầm rú. Không phải trực thăng. Một thứ gì đó lớn hơn, kỳ lạ hơn.","“Blaze, nhảy!”","“Chú ý tư thế tiếp đất! Đừng rời khỏi luồng nhiệt của tôi!”","“Cái gì vậy? Có người đang nhảy xuống?!” một nhân viên L.G.D. hét.","Hai bóng người rơi từ trên trời xuống. Một người phụ nữ tóc trắng, đôi tai mèo, tay cầm một chiếc cưa máy khổng lồ đang rực lửa. Và trong vòng tay cô ta, một cô bé có đôi tai thỏ, hai tay giơ lên, những sợi sáng đen đã cuộn quanh ngón tay.","“‘Khi nỗi kinh hoàng dâng lên, đôi mắt nàng hóa mù…’”","“Chết tiệt, Rhodes Island? Từ trên trời?!” Mephisto lùi lại. “Những đường đen này… Khoan, là ngươi sao…”","“‘…Khi nước mắt đã cạn, nàng lặng lẽ khóc.’”","Những sợi sáng đen giáng xuống đàn hộ vệ. Và những con quái vật bất tử, những thứ không còn biết đau, bắt đầu rên rỉ.","“…Nghh… …Nngh, uuughhh… Ughh… Aaaargh! Ugh!”","“Chuyện gì thế này? Sao hộ vệ của ta lại gào lên như đang khóc than?” Mephisto hét. “Arts của ta lẽ ra đã xóa sạch cảm xúc của chúng rồi, sao lại thế? Chuyện gì đang xảy ra?! Là ngươi sao?!! Chết tiệt ngươi!! Thỏ của Rhodes Island!!”","“Em tạm thời hạn chế được chuyển động của chúng, nhưng chỉ khoảng mười giây thôi!” Amiya hét.","“Thế là quá đủ để tôi tạo một vùng an toàn!” Blaze đáp.","“Làm thôi, Blaze!”","“Sẵn sàng dốc hết sức chưa?”","“Rồi, ngay!”","“Sắp tiếp đất rồi, mông cô có thể hơi ê ẩm đấy!”","“Đừng làm rơi em!”","“Đương nhiên!”","@cg:avg_5_boom","“Hiệu lệnh, bắn!” Faust hét.","“Đừng coi thường bọn ta!” Một luồng gió nóng bùng lên từ quanh Blaze. Những mũi nỏ chệch hướng, bay vèo qua đầu họ.","“…Mũi nỏ của ta bị gió làm lệch? Sao có thể…”","“Cắt mái nhà ngay dưới chân đám Reunion đó đi!” Amiya hét.","“Được thôi, nhưng nhớ bám chặt! Mấy tháng tôi mới làm được một lần đấy!”","Chiếc cưa máy rực lửa bổ xuống sân thượng. Một vết nứt khổng lồ xé toạc mặt bê tông, chạy dài dưới chân đàn hộ vệ.","“Uh… Urgh? …Aaaaaaaghh!!”","“Cô ta cắt một vết nứt khổng lồ xuyên qua mái tòa nhà!”","“Tôi biết. Cẩn thận đổ nát rơi xuống!” Ch’en hét.","“Chuyện gì vậy? Cô ta làm thế nào? Đã xảy ra chuyện gì?!”","“Woa, cả đống quân Reunion rơi xuống tầng này!”","“Kệ chúng, bám chặt vào!”","Bộ đàm của Ch’en rè rè.","“A lô, a lô? Cô không cần vội vàng tự giết mình thế đâu.”","“…Đang khủng hoảng đấy. Cô làm gì trên kênh này vậy?” Ch’en hỏi.","“Ồ, tôi chỉ muốn báo là tôi xong nhiệm vụ rồi,” Swire nói. “Rhodes Island có một thứ rất mạnh, và họ sắp mang nó đến đây.”","“Họ đến rồi. Rốt cuộc nhiệm vụ của cô là gì?”","“Phối hợp với Rhodes Island.”","“Tiếp đất an toàn!” Blaze đáp xuống, đặt Amiya đứng thẳng.","“Blaze, chị thả em xuống được rồi.”","“Các cô… các cô…” Ch’en nhìn họ, không nói nên lời.","“Cô Ch’en!” Amiya quay lại. Cô bé gầy đi, áo khoác rách tơi tả, nhưng đôi mắt xanh lục sáng rực. “Xin lỗi vì đến muộn thế này, cô Ch’en. Theo thỏa thuận, Rhodes Island giờ sẽ hỗ trợ cô.”","@bg:bg_aircraft","<i>Vài phút trước đó.</i>","<i>4:21 sáng. Nhiều mây.</i><br><i>Hô hiệu: “Bad Guy”, cách Trụ sở L.G.D. 40 m phía trên, Thượng Lungmen.</i>","Trong khoang của cỗ máy bay, Amiya nhìn xuống sân thượng qua ô cửa kính. Ch’en đang đứng một mình giữa đàn quái vật.","“Nhìn cô ấy thảm hại chưa kìa,” Doctor nói. “Cô ấy cần em giúp, Amiya.”","“Sao người hăng hái chuyện này thế?” Blaze khoanh tay. “Cô ta bỏ người chết ở thành phố hoang đó, chẳng phải để cô ta tự xoay xở trong bất lực mới là đúng sao?”","“Blaze, đừng thế,” Amiya nói. “Doctor nói đúng. Ta phải giải quyết vấn đề của Lungmen trước. Không thì mọi việc ta đã làm sẽ thành vô ích.”","“Được thôi, nếu là lệnh thì tôi làm. Tôi biết. Nhưng nói thật, tôi không muốn giúp người đàn bà đó lắm.”","“Blaze, ta không thể để công sức suốt ba tháng qua đổ sông đổ biển được.”","“Đem chi phí với lợi ích ra nói với tôi à? Kệ đi, cứ làm thôi.”","“Có những chuyện có thể chờ đến khi Lungmen an toàn.”","“Đến lúc đó thì ta phát tài to!” Blaze nhìn xuống đôi tay quấn băng của mình. “Ý tôi là, trông ta còn bị đánh tơi tả hơn cô ta, nhỉ? Phiền thật. Không ngờ người đàn bà ở thành phố hoang đó lại kiêu ngạo đến thế. Kal’tsit còn chẳng báo trước cho tôi một tiếng…”","“Về Rhodes Island em mời chị ăn cà ri nhé. Sau đó ta có thể nghỉ ngơi một thời gian. Nhưng ngay lúc này, ta phải kết thúc trận chiến này một lần cho mãi mãi.”","“Được, thỏa thuận thế nhé. Đi thôi!”","@bg:bg_rooftop","“Sao lũ các ngươi lại ở đây?” Mephisto rít lên.","“Bọn ta phải ở đây, Mephisto,” Amiya nói.","“FrostNova đang làm cái quái gì vậy? Cô ta bị sao? Lại ngất nữa à?! Con thỏ đáng nguyền rủa… Ngươi và cả lũ tạp nham của ngươi lẽ ra phải chết cóng ở Chernobog rồi!”","“Ta chưa thể chết được. Chừng nào Oripathy còn hoành hành trên mảnh đất này, cuộc chiến của bọn ta sẽ không bao giờ kết thúc. Bọn ta sẽ quét sạch những kẻ tâm thần như ngươi khỏi thế giới này, cùng với sự ngược đãi mà người Infected phải gánh chịu!”","“A ha… Ahaha…!” Mephisto cười như điên. “Đến đây, thỏ con, nếu ta là kẻ thù của ngươi, thì đến giết ta đi! Giết ta! Giết ta ngay bây giờ!”","“Không… Ngươi không phải kẻ thù của ta.”","“Vậy thì ta sẽ tàn sát ngươi!”","“Nếu ngươi tìm kiếm một cái chết vinh quang, ngươi sẽ không tìm thấy nó ở đây. Ta chỉ muốn phá hủy thù hận và ác ý của ngươi.” Amiya nhìn quanh, nhìn những hộ vệ đang quằn quại. “Chuyện gì xảy ra với ngươi chẳng liên quan đến ta. Nhưng hãy nhìn những người Infected quanh ngươi đi. Cái chết của ngươi sẽ chẳng mang lại gì cho họ.”","“Ngươi…!”","“Ta không còn chút cảm thông nào dành cho loại người như ngươi, ít nhất là lúc này.”","“Ngươi định biến Reunion, biến tất cả chúng ta thành kẻ thù sao? Ngươi muốn nếm thử cơn thịnh nộ của người Infected sâu đến mức nào sao?”","“Không phải người Infected nào cũng giống nhau. Ngươi và cô FrostNova chẳng có điểm chung nào. Không phải ai trong Reunion cũng là kẻ tâm thần như ngươi.”","“Cô ta đã nói gì với ngươi? Người đàn bà đó…!” Mephisto hét lên. “Ngươi đang hiểu lầm điều gì đó phải không? Ta mới là kẻ điều khiển được những thành phố này, bẻ cong mọi con tốt này theo ý ta! Không phải cô ta!”","“Chính vì thế… Nếu phải có ai đó đưa ngươi ra trước công lý, thì người đó sẽ là ta!”","“Đúng vậy,” Blaze nói. “Hơn nữa, chẳng phải ta là kẻ thù từ lâu rồi sao?”","“Đúng!” Amiya nói. “Chúng ta trở thành kẻ thù từ khoảnh khắc ngươi bắt đầu gieo rắc kinh hoàng và bi kịch!”","“…Amiya,” Ch’en gọi.","“Cô Ch’en, xin cố thêm một chút. Đội hỗ trợ của bọn em sắp đến rồi.”","“Xin lỗi.”","“Hả?” Amiya chớp mắt. Rồi cô bé quay mặt đi, giọng hơi lớn hơn bình thường. “…Ồn quá. Em không nghe rõ kế hoạch tác chiến của cô, cô Ch’en.”","Ch’en bật cười, rất khẽ. “Hah. Tôi biết.”","“Xin cô ra lệnh, cô Ch’en.”","“Yan có câu cổ: ‘Bắt giặc phải bắt kẻ cầm đầu.’ Nói cách khác, muốn tiêu diệt kẻ thù, phải bắt được chỉ huy của chúng trước. Cẩn thận. Đám tay sai mất trí của hắn sẽ đứng dậy hết lần này đến lần khác.” Ch’en ngừng lại. “Giải thoát chúng khỏi đau khổ nếu có thể.”","“…Em hiểu rồi.” Amiya quay sang. “Doctor.”","“Đã hiểu. Tôi sẽ chỉ huy từ phía sau.”","“Vâng! Blaze, em sẽ phá đội hình của chúng bằng Arts. Trông vào chị đẩy lùi các đợt tấn công! Ta phải giảm bớt áp lực cho cô Ch’en!”","“Cô ta mạnh thật, nhưng cô nghĩ cô ta mạnh đến mức đó à? Cô nghĩ cô ta một mình hạ được hai tên đó sao? Tôi nghi lắm.”","“Em tin sự chỉ huy của Doctor sẽ giúp cô ấy làm được.”","Ch’en im lặng một lúc. Rồi cô ta quay sang người khoác áo trùm đầu.","“Doctor của Rhodes Island. Tôi sẽ giao chiến với chỉ huy địch.”","“Tôi sẽ tạo cơ hội cho cô tiếp cận hắn.”","“Hừ.” Ch’en quay đi. “Dù trước đây tôi đã nói gì, lần này người có lòng tin của tôi.”","“Tôi cũng tin cô.”","Mephisto nhìn cảnh ấy, gương mặt thiên thần méo mó. “…Rhodes Island, giờ các ngươi cấu kết với Lungmen sao? Tận mắt thấy rồi, ta mới nhận ra chuyện này đáng xấu hổ thế nào với người Infected chúng ta.”","“Chỉ cần bốn người là dồn được ngươi vào góc,” Blaze nói. “Thứ đáng xấu hổ duy nhất ở đây là ngươi!”","“Mephisto, tội ác của ngươi kết thúc tại đây!” Amiya hét.","“Faust! Quét sạch chúng, từng đứa một! Đưa chúng khỏi tầm mắt ta!”","“Vâng…”","“Đến lúc kết thúc trận chiến này rồi,” Ch’en nói. “Chỉ khi đó… ta mới có thể chuẩn bị cho trận tiếp theo. Xin ra lệnh, Doctor.”","“Rhodes Island, theo lệnh tôi. Hỗ trợ cô Ch’en, giành lại Trụ sở L.G.D.!”","","“Ngươi không còn đường chạy nữa đâu,” Ch’en nói.","“…Chết tiệt… ngươi!” Mephisto lùi sát mép sân thượng.","“Định đi đâu đấy?” Blaze chặn ngang đường Faust. “Giơ tay lên cho tôi thấy! Tôi đã nhìn thấu hết mánh khóe của cậu rồi, nhóc có vảy! Đã bảo rồi, không có tác dụng đâu!”","“Blaze!” Amiya gọi.","“Hừ, đừng lo. Mấy đòn này đau chẳng hơn pháo nổ!”","“Chị chặn được phát bắn của tôi từ trước,” Faust nói. “Chị biết chúng đến từ đâu sao?”","“Đương nhiên rồi, tôi đã hiểu cậu rồi. Amiya, lùi lại. Tôi sẽ dùng ‘chiêu đó’!”","“Hiểu rồi! Em sẽ làm rối loạn hộ vệ của Mephisto lần nữa, nhanh lên nhé!”","@cg:avg_5_8_homura","Blaze rạch một đường trên cổ tay mình. Máu nhỏ xuống lưỡi cưa, và lập tức bốc cháy.","“Nhận lấy chút máu của tôi làm quà chia tay đi, ‘Nỏ Thủ Bóng Ma’ của Reunion! Sôi sục lên, và thổi tung lớp ngụy trang của chúng!”","Một làn sóng nhiệt quét khắp sân thượng. Và ở những nơi không khí bị đốt nóng, những bóng người hiện ra. Những sniper Reunion, mang nỏ trên tay, đứng rải rác ở các tòa nhà xung quanh, nãy giờ vô hình như không khí.","“Chị dùng máu của mình làm chất cháy?” Faust nói.","“Hah, trông tôi giống Caster lắm à? Chỉ có mấy tay mới vào nghề tự cao mới đi phóng hỏa lung tung thế. Xin lỗi, đây chỉ là một trong những kỹ thuật chiến đấu của tôi thôi. Hiện hình đi — các ngươi không còn chỗ trốn đâu!”","“…Faust, ngụy trang của tôi mất rồi,” một Nỏ Thủ Bóng Ma nói.","“Hiệu lệnh, rút lui.”","“Những thứ đó là gì vậy…?! Reunion giấu sniper ở đó từ khi nào?” Nhân viên L.G.D. hét. “Nhiều sniper Reunion vừa xuất hiện, chủ yếu ở tầng 2 tòa nhà phía đông và tầng 3 tòa nhà phía nam!”","“Tiến lên thận trọng. Chúng có thể đã đặt phục kích ở các tầng dưới!” Amiya nói.","“Hiện tượng lạ trong tòa nhà cũng do chúng gây ra sao?”","“Thông minh đấy, dùng khúc xạ để làm mình như vô hình,” Blaze nói. “Nhưng các cậu không thể hoàn toàn che giấu dấu vết, cũng không thể cử động đột ngột mà không làm hỏng hiệu ứng của Arts. Tôi nói đúng chứ?”","“…Chị thông minh đấy,” Faust nói.","“Tất cả là nhờ tin tình báo tốt. Giờ biết bị lộ rồi thì đầu hàng đi. Nếu muốn tiếp tục đánh, tôi sẽ bắt cậu trả giá cho cái chết của Ace và Scout.” Giọng Blaze bỗng lạnh hẳn. “Hừ, tôi chẳng quan tâm cậu có dính dáng hay không, nhóc.”","“Faust, ta vẫn còn đạn.”","“Rút lui. Ta đã mất lợi thế thông tin. Tôi sẽ cầm chân chúng. Những người còn lại, di chuyển ngay.”","“Đã hiểu.”","“Sao cậu không bắn cô ta? Faust!” Mephisto hét. “Tấn công, hộ vệ của ta! Nhanh! Chúng chỉ có bốn người, chỉ bốn thôi… và chỉ ba người trong số đó là đáng gờm! Chiến đấu! Xé xác lũ tội đồ đó ngay!”","“Với sự chỉ huy của Doctor, ba người bọn ta là quá đủ để đánh bại tất cả các ngươi!” Amiya nói. “Chưa kể những người Infected mà ngươi làm hại, những người ngươi cướp đi ý chí tự do đến mức không còn là người nữa… Ngay cả cậu bé có vảy bên cạnh ngươi cũng có thể không còn đứng về phía ngươi nữa. Suy nghĩ của cậu ấy đầy đau buồn và giằng xé… Mephisto, trên chiến trường này ngươi chỉ có một mình!”","Mephisto đứng im.","“Cô đọc được suy nghĩ của tôi sao?” Faust hỏi.","“Không, chị chỉ cảm nhận được thôi.”","“Vậy thì chị không biết tôi đang nghĩ gì.”","Một mũi nỏ lao thẳng về phía Amiya.","“…!”","“Amiya!” Blaze hét.","“Em không sao, em vừa kịp chặn được phát bắn…! Nhưng em không thể tiếp tục áp chế…”","“GRAAAAAAGHHH!! AAAARRRRGGHH!!”","“Em đang mất kiểm soát!”","“Mephisto, đi thôi,” Faust nói. “Viện binh của chúng đang quét sạch lực lượng ta. Có những kẻ ta chưa từng thấy bao giờ. Kế hoạch đã thay đổi. Nước đi của ta đã bị đọc.”","“…Tại sao lực lượng của ta không đến? Ta có hơn hai mươi đội và hai lữ đoàn lớn, sao không ai đến cả? Crownslayer đâu? FrostNova đâu?”","“Lần này không giống Chernobog. Ta không cắt được liên lạc của địch, nên chúng gọi được nhiều viện binh và kháng cự quyết liệt. Mephisto…”","“Sao bọn họ vẫn chưa đến?!”","“Không tận mắt thấy thì ta không biết lý do. Ra khỏi đây trước đã.”","“Blaze, em sắp đến giới hạn rồi. Chị kết thúc được không?” Amiya thở dốc.","“Chắc chắn rồi. Chỉ cần tôi với cô Ch’en kia là đủ!”","“Nhanh lên!” Faust kéo Mephisto chạy.","“Ta cho phép các ngươi đi chưa?” Ch’en chắn ngang đường.","“Ngươi… Hộ vệ! Giết ả! Giết ả!!”","“Grrr… Grooooar!!!”","“Chậc… Hơn chục con cùng lúc. Phiền đây.” Blaze giương cưa. “Chúng đang lao vào ta đấy, Ch’en!”","“Cảm ơn, operator Rhodes Island,” Ch’en nói. “Giờ không ai cản được ta nữa.”","“Hả?”","<i>Haah… vẫn chưa được sao? Mình không có cách hoàn toàn vô hiệu hóa ngụy trang của chúng… Thôi, thế này chắc là đủ.</i> Ch’en đặt tay lên chuôi Chi Xiao. <i>Chi Xiao, lần này…</i>","“‘Huyết đỏ tràn bờ—’”","Không ai thấy thanh kiếm rời vỏ. Chỉ có một vệt đỏ thẫm lóe lên trong bóng tối, như một tia chớp màu máu. Rồi tiếng kiếm tra vào vỏ, lách cách.","Hơn chục hộ vệ khổng lồ đứng im. Rồi đổ xuống, cùng một lúc.","“…Gah!”","“Uaaagh… Argh…”","Và một trong số chúng, trước khi tắt thở, thì thầm một tiếng rất khẽ.","“Cảm… ơn…”","Mephisto đứng chết lặng.","“Cô vừa rút kiếm ra sao? Chỉ một nhát? Mà hạ được hơn chục con quái vật đó?” Blaze nhìn Ch’en, rồi quay sang Amiya. “Amiya, tôi nghĩ tôi nên bắt đầu cẩn thận lời ăn tiếng nói hơn khi ở gần cô ta.”","“Hừ,” Ch’en nói.","“Ngươi… Ngươi đã làm gì…” Mephisto run rẩy.","“Chạy!” Faust hét.","“Ngươi cũng không thoát được đâu.” Một vệt đỏ nữa lóe lên.","“Gah…!” Faust lảo đảo, máu chảy ra từ vai.","“Faust… Faust! Cậu bị thương rồi! Cậu… không, không… Khôngggg!”","“Kết thúc rồi,” Ch’en nói.","“Chưa đâu,” Faust nói.","Một mũi nỏ bắn ra ở cự ly gần đến mức không thể né. Ch’en kịp đưa kiếm lên đỡ, nhưng vụ nổ hất cô ta lùi lại mấy bước.","“Khụ khụ… Hắn dụ ta lại gần để bắn thẳng mặt sao?”","“Chẳng phải cô chặn được rồi sao?” Blaze hỏi.","“Chúng dùng vụ nổ làm vỏ bọc để trốn thoát!”","Những vụ nổ nối tiếp nhau dọc mép sân thượng.","“Woa, một chuỗi nổ liên hoàn?” Blaze lùi lại. “Argh, cả tầng trên đang sụp! Không đuổi theo được rồi?”","“Một nửa là do cô làm đấy,” Ch’en nói.","“Đành chịu thôi.”","@bg:bg_uptown_2","Ở tầng dưới, giữa khói bụi, Faust kéo Mephisto chạy qua những hành lang đổ nát.","“Nhanh lên, ta phải đi.”","“Không, ta phải ở lại đây, cho đến khi họ đến…”","@cg:avg_5_8_ruins","“Bước này ta thất bại rồi. Anh phải đi.”","“Ta thất bại? Ta thất bại sao? Không thể nào!” Mephisto vùng vẫy. “Chẳng phải mọi thứ đều theo kế hoạch sao…? Chẳng phải ta đã gọi viện binh từ lâu rồi sao? Ta bị phản bội à? Thông tin bị rò rỉ? Ai? Tại sao L.G.D. lại biết sự bố trí và chiến lược của ta?”","“Đi đi!”","“Nếu không bị phản bội, thì ai đã làm chuyện này?! Talulah sẽ không bao giờ phạm sai lầm… Vậy thì cô ấy hẳn đã lên kế hoạch cho chuyện này…” Mephisto khựng lại. “Không, không thể nào… Sao cô ấy lại gài bẫy chúng ta như vậy? …Faust, ta không thể chấp nhận điều này… Ta không tin.”","“Nhảy! Tôi sẽ giữ anh!”","“…Được thôi…”","@bg:bg_rooftop","“Chà… chết thật, quý cô,” Blaze nhìn quanh sân thượng tan hoang. “Có vẻ tòa nhà này cần sửa sang ra trò đây. Tiếc là để hai thằng nhóc đó thoát. Đám tín đồ mất trí kia vẫn lao vào ta như thú bị dồn vào góc. Xử lý hết chúng vẫn là một cái gai lớn.”","“Ít nhất ta đã giành lại được trụ sở,” Amiya nói. “Đây là chiến thắng của chúng ta, dù chỉ là tạm thời.”","“Amiya…” Ch’en nhìn cô bé. Cô ta im lặng rất lâu. “…Rhodes Island đã thoát khỏi Chernobog bằng cách nào?”","“Chị Blaze đến cứu bọn em vừa kịp lúc. Ngoài thành phố hoang cũng có một sĩ quan L.G.D. to mồm…”","“Lẽ ra cô giúp bọn tôi ngay từ đầu thì dễ hơn nhiều, thay vì đứng nhìn từ bên lề,” Blaze nói. “Tôi còn tưởng cô sẽ nói kiểu ‘Tôi đâu cần Rhodes Island giúp,’ hay ‘Thà chết còn hơn làm việc với họ.’ Nhưng ít ra cô không cứng đầu đến thế. Còn gì muốn nói không? Không thì tôi về Rhodes Island đây.”","“Tôi không biết Rhodes Island có một cỗ máy bay như vậy.”","“Heh, bọn tôi có nhiều thứ có thể làm cô ngạc nhiên lắm.”","“Cũng như các cô, chúng tôi không muốn lật hết bài.”","“Cô không tính bọn tôi là một trong những quân bài của cô đấy chứ?”","Ch’en không trả lời.","“Ừm, cô Ch’en…” một nhân viên L.G.D. lên tiếng. “Có cuộc gọi đến trên đường dây riêng. Là cho cô.”","“A lô?”","“Làm tốt lắm, cô Ch’en,” Wei Yenwu nói. “Cô Swire có ở trên kênh này không?”","“Có ạ,” Swire đáp.","“Báo cáo tiến độ đi.”","“Tôi đã cứu Rhodes Island, và sắp xếp xong cho các lữ đoàn. Điều phối và quản lý mọi thứ mất trọn ba đêm. Còn cô thì sao, cô Ch’en?”","“Tôi đã giành lại—” Ch’en ngừng lại. Cô ta nhìn sang Amiya, sang Blaze, sang người khoác áo trùm đầu đứng phía sau. “—với sự hỗ trợ của Rhodes Island, chúng tôi đã giành lại Trụ sở L.G.D. Chỉ huy của chúng sẽ lan truyền tin thất bại trong hàng ngũ. Quân Reunion còn lại ở Lungmen đã bị dồn vào các điểm phục kích qua những lộ trình ta sắp xếp. Tiếp theo, chỉ cần chờ chúng phản công. Nhiệm vụ của tôi đã hoàn tất.”","“Ta cũng nhận được báo cáo từ vài đồng nghiệp khác của cô. Mọi nhiệm vụ ở giai đoạn trước đều hoàn thành hoàn hảo. Làm tốt lắm, tất cả.” Wei Yenwu ngừng lại. “Giờ ta chuyển sang giai đoạn tiếp theo.”"],"bg":"bg_rooftop","cast":[["Mephisto","npc:char_1507_Mephisto_1"],["Ch'en","op:char_010_chen"],["Blaze","npc:char_017_homura_3"],["Amiya","op:char_002_amiya"],["Faust","npc:char_1508_Faust_1"],["L.G.D. Agent","npc:char_015_lmg"],["Swire","op:char_308_swire"],["Wei Yenwu","npc:char_2005_weiyw_1"]]},{"c":"5-11","t":"Phản công quyết định","p":["<i>4:45 sáng. Trời quang.</i><br><i>Phế tích sân thượng Trụ sở L.G.D., Thượng Lungmen.</i>","“Cô Ch’en, ta tin là Amiya đang ở ngay cạnh cô. Cô có nghe ta không?”","“Vâng, Trưởng quan Wei,” Amiya đáp.","“Tốt lắm. Ta phải xin lỗi, thủ lĩnh của Rhodes Island. Dù ta có thể mạo hiểm gửi L.G.D. vào sâu lãnh thổ địch, ta không thể mạo hiểm đưa thêm người chơi vào ván cờ này.”","“Đưa thêm người chơi vào?” Doctor hỏi.","“Doctor… Bên dưới toàn bộ mảnh đất này là một tấm lưới vô hình, nhưng chằng chịt. Không thành phố nào thoát được tấm lưới âm mưu và mưu đồ ấy, càng không phải Lungmen, khi nó nằm giữa những gã khổng lồ. Có lẽ người đã biết điều này, có lẽ chưa. Dù sao, ta phải cân nhắc mọi yếu tố.”","“Trưởng quan Wei, lẽ ra ông nên chia sẻ thông tin này với bọn em nếu muốn nhiệm vụ suôn sẻ hơn,” Amiya nói. “Ít nhất, lẽ ra ông nên nói với em.”","“Ta lại phải xin lỗi, cô Amiya. Ở vị trí của ta, ta không thể tiết lộ hết thông tin. Nếu đứng ở vị trí của ta, cô cũng sẽ quyết định như vậy. Chuyện ở phế tích Chernobog thật đáng tiếc, nhưng ít ra các vị đã đạt được gì đó.”","“Ông dùng bọn tôi để thu hút sự chú ý của Reunion,” Blaze nói.","“Không, L.G.D. đã ở ngay đó cùng các vị.”","“Ông dùng tất cả chúng tôi làm mồi nhử,” Doctor nói.","“Hả?”","“Ông ta đã lên kế hoạch cho tất cả từ lâu rồi.” Giọng Kal’tsit chen vào kênh, lạnh lẽo. “Sự thâm nhập của Reunion chỉ ngày càng sâu, nên ông ta phải quyết định thật nhanh.”","“Vào thời khắc then chốt nhất, khi Reunion dễ bị tổn thương nhất…” Doctor nói, “Rhodes Island bị dùng để thu hút sự chú ý của chúng.”","“Ông ta khiến Reunion tin rằng L.G.D. đã bị chia cắt—” Kal’tsit tiếp.","“…và lừa chúng nghĩ rằng Lungmen không có phòng bị.”","“Hah, nói hay lắm, Doctor!” Blaze nói. “Trưởng quan, đương nhiên ông cần bọn tôi cầm chân Reunion. Càng nhiều càng tốt, đúng không? Khi Reunion ẩn nấp thấy Lungmen trong tình trạng đó, không đời nào chúng không lao vào nắm lấy cơ hội. Và ngay khi chúng bắt đầu chui ra khỏi hang, BÙM! Lực lượng tinh nhuệ của Lungmen đã chờ sẵn, như từ trên trời rơi xuống. Ông che giấu sức mạnh của Lungmen bao lâu rồi? Có phải ông đã bắt đầu chuẩn bị ngay sau sự kiện Chernobog không?”","“Lungmen đã giữ các vị an toàn, và giúp các vị trở về vị trí có thể phát huy tối đa giá trị.”","“Ông bỏ Amiya chết giữa ngần ấy kẻ thù. ‘Vị trí’ gì vậy hả?”","“Ta chỉ mong Rhodes Island hiểu rằng chúng ta đều phải cùng nhau đối mặt với tình thế khó khăn này.”","“Chị Blaze, Doctor, không sao đâu,” Amiya nói. “Chị Swire đã giúp bọn mình cùng nhau đánh bại lực lượng Reunion. Lungmen không bỏ rơi bọn mình.” Rồi cô bé hạ giọng, chỉ đủ cho hai người nghe. “(Chúng ta không có bằng chứng.)”","“Chậc…” Blaze quay mặt đi.","“Thỏa thuận của chúng ta vẫn còn hiệu lực,” Wei Yenwu nói. “Dù quá trình đã xảy ra chuyện gì, chỉ có kết quả cuối cùng mới khiến ta hài lòng. Dù đã xảy ra chuyện gì. Doctor của Rhodes Island, ta tin lần trước gặp nhau ta đã nói rõ. Người không có lựa chọn trong chuyện này. Nhưng ít nhất người có thể chọn cách tiêu diệt kẻ thù.”","“Bị lừa rồi thì chẳng ai vui vẻ mỉm cười mà đi tiếp đâu,” Doctor nói.","“Chẳng phải như vậy là tốt nhất sao? Tất cả chúng ta nên cảnh giác. Không ai nên lơ là khi đối mặt với kẻ thù chung. Sự cảnh giác của người có thể giúp người không sa vào bẫy. Nghe này, Doctor—” Ông ta ngừng lại. “…Chúng ta có thể chưa phải bạn, nhưng ít nhất chúng ta không phải kẻ thù.”","Doctor không nói gì.","“Vậy là im lặng là câu trả lời của người. Một sự phán đoán tốt. Người giấu đi điểm yếu trong khi tận dụng lợi thế. Rhodes Island quả thật là một đối tác mạnh. Các vị đã giành được sự công nhận của ta qua sự việc này. Nhưng điều đó đi kèm điều kiện mối quan hệ của chúng ta vẫn là đối tác, không phải một tuyên bố về địa vị giữa người Infected bất hợp pháp và chính quyền địa phương.”","“Ta không có ý định lừa ai. Dù, khách quan mà nói, ta có thể đã lừa Reunion. Nhưng không gì trong số đó có thể chứng minh được. Reunion cũng có thể tiếp cận được bí mật của chúng ta. Ta chỉ có thể hy vọng tiêu diệt chúng trước khi chúng nắm được chiến lược của ta. Vậy, mục tiêu này có thúc đẩy các vị chút nào không?”","“Cô Amiya, Doctor, sự hợp tác giữa chúng ta chưa kết thúc. Một cuộc phản công sắp diễn ra. Chúng ta sẽ cho chúng thấy tầm vóc, trí tuệ và sự đoàn kết của Lungmen. Nếu có thể, ta cũng muốn chứng kiến sự chuyên nghiệp, quyết tâm và lòng dũng cảm của Rhodes Island. Mười lăm phút nữa, cô Ch’en sẽ trở lại chiến đấu bên cạnh các vị.”","“Ông Wei, em mong ông không quên những gì ông vừa nói,” Amiya nói. “Vì Rhodes Island sẽ không quên đâu.”","“Đương nhiên.”","“Chị Blaze, Doctor, đi thôi.” Amiya quay lại. “A, nhân tiện, cô Ch’en, thanh tra Hoshiguma đâu ạ? Em không thấy chị ấy. Chị ấy… không sao chứ?”","“Bị vài vết thương nhẹ, không có gì nghiêm trọng.”","“Ồ, vậy ạ… Cô Ch’en, Rhodes Island cũng có thể kiểm tra sức khỏe và sơ cứu nhanh cho cô nếu cần.”","“Không cần, cảm ơn.”","“Cô không cần lo gì đâu, quy trình y tế của bọn em hoàn toàn bảo mật.”","“Chút dầu bóp là đủ rồi.”","“Ưm… Nếu cô nhất quyết, em sẽ không ép. Vậy hẹn gặp lại cô sau, cô Ch’en.”","Ch’en nhìn theo bóng ba người khuất sau cầu thang. Cô ta không nói gì.","","<i>5:00 sáng. Trời quang.</i><br><i>Văn phòng Trưởng quan, Thượng Lungmen.</i>","“Trưởng quan Wei, mọi việc bên ông thế nào?” Swire hỏi.","“Tốt, đương nhiên. Không thì ta đâu có thời gian ngồi đây nói chuyện với cô.”","“Họ đã đồng ý làm chậm chiến dịch chưa?”","“Đương nhiên, nhưng có giới hạn thời gian. Hôm nay và ngày mai. Nếu sau hai ngày Reunion vẫn chưa bị khống chế, cô biết chuyện gì sẽ xảy ra.”","“Chỉ hai ngày?! Không đủ thời gian! Tôi không thể—”","“Hai ngày hai đêm đã là quá hào phóng. So với đó, ta sẽ chỉ cho cô một ngày.”","“Một ngày?”","“Ta muốn cô xử lý mọi thứ trong một ngày.”","“Trưởng quan Wei, nếu họ giúp ta, ta có thể dọn sạch Reunion trong vài giờ. Như vậy chẳng phải giảm thiểu tổn thất sao?”","“Điều đó không quan trọng. Lungmen phải tự giải quyết được vấn đề của mình, một lần cho mãi mãi. Đó là nguyên tắc đầu tiên của chúng ta. Đó là điều ta cần cho họ thấy. Vậy nên, mọi người, hành động đi.” Ông ta quay sang. “Đi đi, cô Ch’en. Đến lúc cho Reunion nếm chút lòng hiếu khách của Lungmen rồi.”","“Đã hiểu.” Ch’en đứng dậy, rồi dừng lại ở cửa. “Trưởng quan Wei, tôi có một câu hỏi. Dù giờ ông không trả lời được, tôi mong sau khi mọi chuyện kết thúc, ông có thể cho tôi một suy đoán hợp lý.”","“Cô cứ hỏi.”","“Đây lẽ ra là đợt tổng tấn công của Reunion. Vậy tại sao thủ lĩnh của chúng, Talulah, lại không xuất hiện ở Lungmen?”","Wei Yenwu không trả lời. Ông ta chỉ nhìn ra ô cửa kính, nơi bình minh đang bắt đầu nhuộm hồng những ngọn tháp Lungmen.","@bg:bg_lungmen_o","Khi căn phòng đã vắng, một người phụ nữ bước ra từ sau tấm bình phong. Mái tóc dài, chiếc kimono thanh nhã, đôi mắt dịu dàng nhưng sắc sảo.","“Em tưởng mọi việc đang tiến triển thuận lợi,” Fumizuki nói. “Sao anh lại nhíu mày thế?”","“Đã có hồi âm nào từ Ursus chưa?”","“Vẫn chưa.”","“Vẫn chưa liên lạc được với Nghị trưởng Witte sao?”","“Tiếc là sứ giả của chúng ta còn chưa gặp được ông ta.”","“Nhìn thế này thì Đế quốc Ursus hoàn toàn mờ mịt.” Wei Yenwu tựa lưng vào ghế. “Fumizuki, anh có linh cảm. Rằng toàn bộ chuyện này chỉ là khởi đầu của một điều gì đó lớn hơn nhiều.”","“Lần cuối em nghe anh nói câu đó là từ nhiều năm trước rồi.”","“Anh nói câu đó khi nào nhỉ? Anh quên mất vì sao mình lại nói thế rồi.”","“Ngay sau khi chúng ta gặp nhau lần đầu. Anh định nói là anh quên hết mọi chuyện giữa hai ta sao?”","“K-không đời nào! Sao anh có thể! Chỉ là ngoài thời gian bên em ra, anh chẳng nhớ được mấy chuyện khác thôi.”","“Khéo nói thật đấy, đồ dẻo miệng. Tiếc là chuyện này anh không quên được đâu.” Fumizuki nhìn ra ô cửa, giọng trầm xuống. “Anh đã nói thẳng vào mặt em hai mươi năm trước… rằng nếu chúng ta thua, thành phố này sẽ mang một cái tên khác, và trở thành một bậc thang nữa trên con đường bá chủ của Ursus. Nếu chúng ta thua, người ngồi ở đây đã không phải là anh. Mà là hắn.”","Wei Yenwu im lặng rất lâu.","“…Công tước Kashchey.”","“Đáng thương thay cho Tal. Anh không thấy con bé khiến chúng ta nhớ đến hắn sao?”","“Nhưng hắn đã chết rồi.” Wei Yenwu nhắm mắt lại. “Bị chính Talulah giết chết.”"],"bg":"bg_rooftop","cast":[["Wei Yenwu","npc:char_2005_weiyw_1"],["Amiya","op:char_002_amiya"],["Fumizuki",null],["Blaze","npc:char_017_homura_3"],["Ch'en","op:char_010_chen"],["Swire","op:char_308_swire"],["Kal'tsit","op:char_003_kalts"]]}],"id":"main_5","no":"Chương 5","title":"Giải pháp cần thiết","en":"Necessary Solutions","sum":"Lungmen thất thủ chỉ sau một đêm, trụ sở L.G.D. rơi vào tay Reunion. Ch'en, Hoshiguma và Swire lao vào cuộc phản công giữa những bí mật của Wei Yenwu, quá khứ chưa lành và thanh kiếm Chi Xiao không chịu rời vỏ."},{"secs":[{"c":"6-1","t":"Bế tắc","p":["<i>Năm 937.</i>","<i>Công tước Erik và Giáo sư Lierland D. của Đại học Nghị viện Piesberg công bố một bài báo đồng tác giả trên Tạp chí Lịch sử Đô thị (số 44, “Chúng ta đến từ đâu?”). Bài báo trình bày kết quả phân tích chi tiết một tập hợp hài cốt đã phong hóa. Cuộc khảo sát Khu khai quật số 4 ở Sargon cho thấy việc cách ly và hành quyết người Infected có chung nguồn gốc với chính pháp luật.</i>","<i>…Nói cách khác, nỗi khổ của người Infected còn có trước cả khi luật pháp ra đời.</i>","","<i>Lungmen. Tầng kết cấu chống đỡ. Lối ra.</i>","@cg:avg_6_1","@cg:avg_6_2","“FrostNova!”","Người phụ nữ tóc trắng đứng giữa bóng tối, hơi thở bốc thành khói. Sau lưng cô ta là những cột thép khổng lồ đỡ lấy cả một thành phố.","@cg:avg_6_4","“Giờ thì, chúng ta phải chiến đấu,” FrostNova nói. “Nếu ngươi đánh bại được ta, nghĩa là sẽ có vài người được sống sót—”","“Ta sẵn sàng gia nhập Rhodes Island. Ta sẵn sàng cùng các ngươi chiến đấu chống lại kẻ thù của người Infected, theo cách của các ngươi.”","“Đây là gánh nặng ta phải mang.”","","<i>8:50 sáng. Bốn giờ sau khi giành lại Trụ sở L.G.D. Gần lối ra Commandery.</i><br><i>L.G.D. và Rhodes Island Pharmaceuticals.</i><br><i>Chiến dịch Truy quét Lungmen, giai đoạn cuối.</i><br><i>1. Kiểm soát động tĩnh của Reunion trong Lungmen. Hoàn thành dưới sự chỉ đạo của L.G.D.</i><br><i>2. Quét sạch lực lượng Reunion còn trong Lungmen. Hoàn thành dưới sự chỉ đạo của L.G.D.</i><br><i>3. Loại bỏ chỉ huy tác chiến của Reunion, hoặc ảnh hưởng chỉ huy của chúng. Hoàn thành dưới sự chỉ đạo của L.G.D.</i><br><i>4. Tiêu diệt Reunion Movement trước khi chúng rút vào khu ổ chuột. Hoàn thành trong chiến dịch chung giữa L.G.D. và Rhodes Island.</i>","“…Xin thông báo đến toàn thể công dân… đang diễn tập sơ tán… Những công dân chưa kịp sơ tán, xin khóa cửa, kéo rèm, và không ra khỏi nhà…”","“Có cần to thế không?”","“Bắn rơi cái drone đó đi!”","Mephisto chạy dọc một con hẻm hẹp, vạt áo choàng trắng lấm lem. “Giờ ta chỉ đang bị kẹt trong một cuộc diễn tập à? Sao chúng dám dùng trò rẻ tiền như vậy để che đậy nỗi kinh hoàng tinh tế mà ta đã dày công tạo ra? Lại còn lặp đi lặp lại bằng cả tiếng Lungmen lẫn tiếng Ursus! Ta chán mấy cái drone này rồi. Đi! Nhanh lên! Bám theo những con phố nhỏ!”","“Đội trinh sát 3 cũng không có tin gì!” một Nỏ Thủ Bóng Ma báo.","“Tín hiệu của đội đột kích đột nhiên m-mất…”","“Ta đang mất liên lạc với các đội quan sát từng đội một!”","“Tại sao! Bằng cách nào!” Mephisto gào lên. “Thật là sỉ nhục… nỗi nhục nhã giáng xuống phong trào của chúng ta! Nhưng bằng cách nào, và tại sao? Chết tiệt ngươi, Lungmen! Chết tiệt lũ người Lungmen! Chết tiệt lũ không nhiễm bệnh!”","Người Nỏ Thủ Bóng Ma liếc sang Faust. <i>(Tôi chưa bao giờ thấy anh ấy bất ổn đến vậy. Faust, ta còn cơ hội rút lui không?)</i>","Faust im lặng một lúc. <i>(Tôi sẽ mở đường cho các cậu. Nếu chỉ là đám cảnh sát bình thường của L.G.D. cộng thêm Rhodes Island, ta sẽ thoát được.)</i>","<i>(Ý anh là sao? Ngoài đó còn ai khác nữa?)</i>","“Agh…! Không thể tin được! Ta không liên lạc được!!” Mephisto đập tay lên bộ đàm. “Đến ra lệnh cho các đội còn không được, ta thắng bằng cách nào?”","<i>(Có kẻ đang theo dõi chúng ta,)</i> Faust nói. <i>(Thành phố này còn nhiều thứ hơn thế. Chuẩn bị đi. Để sống sót.)</i>","<i>(Rõ.)</i> Người Nỏ Thủ ngừng lại. <i>(…Faust.)</i>","<i>(Hửm?)</i>","@cg:avg_6_5","<i>(Bọn tôi tin anh.)</i>","Faust không trả lời.","@bg:bg_rooftop","<i>9:20 sáng. Tuyến tuần tra của Rhodes Island gần L.G.D.</i>","“Họ thật sự để việc này cho người Infected à?” Blaze lẩm bẩm, chiếc cưa máy vác trên vai. “Lần này Rhodes Island thiệt thòi thật. Mà lại ở Lungmen chứ! Hừ. Một thành phố lớn như Lungmen sao lại không tự đẩy lùi nổi một cuộc xâm lược? Giờ thì bắt người Infected đánh người Infected thay cho đám người thường… Thôi kệ. Đâu phải lần đầu.”","Ở cuối phố, một toán Reunion đang lao về phía một trạm chặn của L.G.D.","“Nhanh mở đường! Đừng ngoái lại, cứ phá phòng tuyến của chúng! Chỉ cần qua được con phố này là có cơ hội hội quân với lữ đoàn hai! Đừng cho chúng cơ hội bắn trả. Ta không còn bao nhiêu người nữa—”","“Và chỉ một lát nữa thôi, các ngươi sẽ chẳng còn ai.”","Blaze đáp xuống ngay giữa đường, mặt đất nứt toác dưới chân cô.","“Cái gì?! M… mày là ai? Mày vừa từ trên trời rơi xuống à?! Lùi lại, chạy đi! Ả… ả có thể biết bay!”","“…Không, tôi không biết bay thật mà!”","“Xưng danh đi!” một lính L.G.D. quát từ sau chiến lũy.","“Dùng máy quét đi!” Blaze hét lại, rồi quay sang đám Reunion. <i>(Xin lỗi, phải xử lý việc này trước!)</i> Cô lại quay về phía L.G.D. “Lực lượng thực thi pháp luật Lungmen, nghe đây! Tôi đến từ Rhodes Island. Ngừng bắn. Tôi thật sự không muốn phải né đạn lạc trong lúc đánh nhau. Tôi tự lo được. Các anh cứ đến trạm chặn tiếp theo đi.”","Cô quay lại, vươn vai. “Được rồi. Quay lại với các cậu.”","“Con nhỏ này bị làm sao vậy?”","“Để tôi giải thích. Chắc các cậu sẽ hiểu thôi. Có lẽ vậy.” Blaze hít một hơi thật sâu, rồi nói một mạch như đọc thuộc lòng. “Tôi là Blaze, một trong những operator tinh nhuệ của Rhodes Island. Mục tiêu hiện tại của tôi là làm tê liệt năng lực chiến đấu của các cậu. Bất kể các cậu tiến hành cuộc xâm lược thành bang ngoại quốc này với ý định gì, chúng tôi chủ yếu nhắm đến việc tước vũ khí. Gác lại những tổn thương và thiệt hại các cậu đã gây ra cho người khác cũng như hình phạt đi kèm, mọi kháng cự lúc này đều vô ích. Bỏ vũ khí xuống. Các cậu vẫn còn cơ hội.”","“Hả? Cái gì? Mày…”","“Các đồng bào Infected của tôi, tôi cho các cậu một lựa chọn: đầu hàng ngay, tôi sẽ hộ tống các cậu về Rhodes Island, rồi đưa các cậu đến một nơi chào đón người Infected.”","Một mũi tên bay tới. Blaze giơ tay bắt gọn.","“Ả đỡ bằng tay không?!”","“Thấy các cậu vẫn chống cự, tôi chẳng còn gì để nói nữa.”","“Bọn tao để mày nhốt lại chắc? Mày điên đến mức nào vậy?”","@cg:avg_6_6","“Tôi không điên! Có lúc để đánh, có lúc để chạy. Chỉ là khi các cậu chọn đánh, tôi chỉ có thể đánh lại.” Blaze đặt chiếc cưa xuống đất. “Dù sao thì, tôi không cần đến cưa. Xin lỗi, tôi thật sự không muốn đánh đồng bào Infected của mình.” Cô quạt quạt tay. “…Lungmen ẩm thật đấy.”","“Con mèo ngu này… đang dùng Arts! Người ả đang bốc hơi!”","“Người tôi? Đoán lại đi. Là không khí quanh tôi nóng lên, hay không khí quanh các cậu?” Blaze nhe răng cười. “Cùng tắm hơi kiểu Sami nhé. Tôi mời.”","@bg:bg_building_3","“Hah…” Blaze phủi tay. “May mà tôi đã khởi động ở Chernobog rồi. Mà thật ra, xử lý các cậu tôi còn chẳng đổ một giọt mồ hôi.”","Một tên Reunion nằm dưới đất vẫn cố ngóc đầu lên. “Mày! Đồ Rhodes Island, mày là nỗi ô nhục của người Infected. Sao mày có thể quay lưng với đồng loại chỉ để giúp Lungmen?! Vậy là mày giao bọn tao cho chúng, như thể thế thì tay mày sạch à? Láo toét! Mày sống với chính mình kiểu gì vậy?!”","“Hả?” Blaze ngồi xổm xuống. “Ăn hai cú đấm, đập đầu xuống vỉa hè mà vẫn còn sức nói nhảm? Không tệ. Nhưng cậu hiểu sai hết rồi.”","Tên Reunion bỗng ôm lấy cổ. “Mmf!”","“Khó thở à? Thấy phổi như đang cháy?” Blaze nói khẽ. “Nó bắt đầu từ xoang mũi, rồi bò xuống khí quản, cho đến khi tìm được chỗ trú ngay cơ hoành. Tôi chỉ cần ngoáy ngón út một cái là… một luồng khí siêu nóng sẽ phóng vào cơ thể cậu, nở ra, đốt cháy nội tạng, rồi phun ra qua lỗ chân lông. Buồn cười ở chỗ, Lungmen có thể tha cho cậu. Nhưng tôi và ngón út của tôi…?”","“Aah! Gaaah…!”","“…sẽ không để ai trong các cậu còn thở.”","“Khôngggg! T-tha cho tôi! Làm ơn!!!”","“Được thôi. Tôi sẽ nhân từ.” Blaze đứng dậy. “Sĩ quan! Đằng này. Các anh lo đám này đi. À, thêm một chuyện nữa, anh bạn Ursus mới của tôi. Lần sau cậu nghĩ có thể khiến tôi đổ mồ hôi thật không?”","Cô quay lại, mắt sáng lên. “Này, đến rồi kìa. Doctor, đằng này!”","“Cô giỏi thật!” Doctor nói.","“Hah. Chẳng có gì.” Blaze nhún vai. “Lần sau tôi chỉ người cách bẻ tay người ta chín mươi độ mà không gãy xương nhé? …Này, cái mặt đó là sao? Người ở Rhodes Island bao lâu rồi? Làm như chưa bao giờ thấy đánh nhau vậy. So với họ, tôi còn hiền chán. Mà đương nhiên rồi. Người nghĩ tôi là kiểu khiêm tốn à? Nếu tôi gieo được nỗi sợ Blaze vào đầu chúng, ai biết được bao nhiêu kẻ khác sẽ bỏ cuộc. Tôi phải làm lớn chuyện lên thì công sức mới đáng.”","“Đừng dạy hư Doctor chứ…” Amiya bước tới.","“Thỏ con!” Blaze bế xốc cô bé lên.","“Đừng bế em lên như đồ chơi!”","“Nhưng em mềm quá mà…! Này! Đừng giãy! Cứ để yên đi. Chị hứa không cắn đâu!”","“Blaze… Thả… Không thở… được!”","“Phù.” Blaze đặt cô bé xuống.","“Bọn mình mới xa nhau có một tiếng! Chị bị sao vậy! Nghiêm túc đi!”","“Chị rút lại. Em không dễ thương chút nào.”","Amiya nheo mắt. “…Đủ rồi đấy…!”","“Ấy, này, chị đùa thôi! Ra khỏi đầu chị đi! Chị không chịu nổi em vọc cảm xúc của chị nữa đâu!” Rồi Blaze khựng lại, nhìn qua vai Amiya. “Khoan. Cô ta đi cùng em à?”","Một cô gái tóc xám, tay cầm nỏ, đứng hơi lùi về phía sau. “Xin chào, tôi là…”","“Tôi biết cô là ai.” Giọng Blaze lạnh hẳn. “Nói với đồng bào Infected của tôi như thế thêm một lần nữa, tôi sẽ tự tay xé cổ họng cô.”","“Blaze!”","“Xin lỗi, Amiya. Nhưng đó là sự thật. Và cô ta đáng bị cảnh cáo.” Blaze quay lưng. “Tôi đi đây. Hội quân ở điểm mốc tiếp theo.”","","“GreyThroat, có lẽ Blaze đã hiểu lầm chị,” Amiya nói khẽ.","“Không sao. Tôi đã thật sự nói những lời đó,” GreyThroat đáp.","“Chị ấy không nên moi quá khứ của chị ra để công kích con người chị hôm nay.”","“Ai biết được? Tôi đã thật sự thay đổi chưa? Chính tôi cũng không biết.”","“Vậy cô phải làm gì đó để tìm ra câu trả lời thôi,” Doctor nói.","“Tôi ở đây vì tôi muốn làm gì đó,” GreyThroat nói. “Bất kể cô Blaze kia nói gì.”","Amiya thở dài. Cô bé kéo Doctor lại gần, hạ giọng. <i>(Phải rồi… GreyThroat không phải người Infected, nên có lẽ chị ấy chưa nắm được thực trạng của Rhodes Island lúc này. Chiến dịch này có thể buộc chị ấy phải quyết định một lần cho xong… ở lại hay rời đi. Nhưng chị ấy quen nghe lệnh rồi, ít khi lên tiếng. Dù đôi khi chị ấy cũng làm người ta bất ngờ… Trong lòng chị ấy không có ác ý. Chị ấy chỉ cần một cơ hội để tìm lại chính mình. Dù vậy, chị ấy mạnh và đáng tin. Doctor có thể tin chị ấy. Và dù bọn mình không giúp được chị ấy, em biết chị ấy có thể giúp Doctor.)</i>","Rồi cô bé nhìn quanh. “Ơ… Gavial đi đâu rồi?”","“Chắc hăng quá nên đi đập vài cái sọ rồi?”","“Chị ấy không được làm thế!” Amiya kêu lên. “Khoan, ai dạy Doctor nghĩ về chị ấy như thế? Ý em là, cũng đúng một phần, nhưng mà… Bọn mình không thể phạm sai lầm ở đây. Nhanh đến điểm mốc tiếp theo, thử phát tín hiệu cho chị ấy. Kể cả chị ấy làm đúng kế hoạch, không ai trông chừng thì cũng sẽ rắc rối…”","“Còn các đội khác?”","“Bọn mình có các operator tinh nhuệ làm trưởng nhóm. Họ sẽ báo cáo. Doctor đừng lo. Ta đang ở thời điểm then chốt của chiến dịch chung. Đây là trận quyết chiến cho Lungmen.”","“Còn Tổng Thanh tra Ch’en?”","@cg:avg_6_21","“Cô ấy có nhiệm vụ chỉ huy riêng. Là đội trưởng Đội Thanh tra Đặc biệt, cô Ch’en sẽ triển khai những lực lượng tốt nhất của L.G.D. chống lại Reunion theo kế hoạch chung. Đồng thời, cô ấy phải lùa chủ lực Reunion đến vị trí mục tiêu, trong khi ngăn không cho các toán nhỏ của chúng lọt vào khu ổ chuột. Còn bọn mình, Rhodes Island, sẽ tiếp tục đi qua các điểm mốc trên tuyến tuần tra, quét sạch các toán Reunion dọc đường, ép chúng bỏ cuộc. Cuối cùng, bọn mình sẽ đến vị trí mục tiêu ở khu ổ chuột, cùng L.G.D. giáng đòn quyết định vào chủ lực Reunion.”","Cô bé nhìn thẳng vào Doctor. “Xét về quy mô, Rhodes Island làm được tương đối ít. Nhưng bọn mình sẽ thực hiện kế hoạch tốt nhất có thể. Còn những vấn đề nảy sinh trong quá trình hợp tác với L.G.D.… Doctor, em hứa sẽ trả lời tất cả mọi người của chúng ta. Nhưng Doctor ơi, có một việc chỉ Doctor làm được.”","@cg:avg_6_22","“Cứ giao cho tôi!”","“Heh, tốt lắm. Nhưng không phải loại việc Doctor cần bỏ quá nhiều công sức đâu.” Amiya mỉm cười. “Em sẽ gọi Blaze, nhờ chị ấy trông chừng Doctor. Và trong khoảng thời gian ngắn trước khi bọn mình gặp lại, em cần Doctor trông chừng chị ấy nữa.”","“Tôi trông chừng cô ấy? Em nhìn tôi chưa?”","“Ugh… Em không nói trên chiến trường! Ý em là trông chừng tâm lý của chị ấy. Doctor biết đấy, Rhodes Island đôi khi phải đánh người Infected. Nhất là bây giờ. Sự hợp tác với Lungmen đã gây ra vài va chạm. Blaze là một trong những operator tinh nhuệ mà bọn mình dựa vào để sống sót, đúng vậy, nhưng trạng thái tâm lý ảnh hưởng đến phong độ của chị ấy. Chính vì chị ấy quyết tâm với sứ mệnh đến thế, mỗi lần đối mặt người Infected lại có thể làm cảm xúc chị ấy dao động. Đi đi, Doctor. Coi như cơ hội để hiểu chị ấy hơn. Thể hiện sự trân trọng với chị ấy. Cảm ơn chị ấy vì đã cứu Doctor lúc trước. Chị ấy sẽ thích lắm!”","“Ý hay đấy!”","“Em tin Doctor! Cố lên nhé!”","","Ở một con phố khác, L.G.D. đang dựng chiến lũy.","“Chủ lực của chúng đang giao chiến với các đội khác!” Swire báo. “Ta sẽ đến vị trí mục tiêu trước Reunion và vào đội hình!”","“Bảo họ phải tiêu diệt mọi thành phần Reunion chưa nhập vào chủ lực trước,” Ch’en nói.","“Rõ! Làm theo lời Tổng Thanh tra Ch’en vừa nói! Hết!” Swire hạ bộ đàm, quay sang. “Lâu lắm rồi mới lại chiến đấu cùng nhau thế này nhỉ?”","“Tôi không gọi đây là ‘chiến đấu cùng nhau’. Đúng hơn là ‘cùng tham chiến’. Mà cô quay lại đây bằng cách nào?”","“Tôi có đoàn xe riêng chứ sao. Cô nghĩ tôi cứu Rhodes Island bằng cách nào? Giờ thì cô đang bực gì đấy? Tôi biết cô đang khó chịu.”","“Hừm. Để tôi nghĩ.”","“Còn phải nghĩ nữa à! Nhìn cô đi tìm lý do để giận kìa…”","“À, đúng rồi. Cô lén sau lưng tôi đi cứu Rhodes Island. Lẽ ra cô có thể nói riêng với tôi.”","“Ngại à? Hay cô chỉ không thích bị giấu?”","“Cả hai.”","“Ồ… từ khi nào mà cô thẳng thắn thế? Sĩ quan Ch’en ngày xưa của tôi sẽ vòng vo hàng tiếng đồng hồ…”","“Nhìn phía trước!”","“Đội Defender L.G.D., nâng khiên! Cứ làm như cả triệu lần trước đây. Và đừng bao giờ quên, anh chị em của các cậu ở ngay sau lưng! Đứng vững!”","“Giữ!”","“Nỏ, lên dây!”","“Chúng chặn cả đường này rồi sao? Ôi không… chẳng còn đường nào! Ta bị kẹt rồi!”","“Bình tĩnh, ta phá được chúng! Theo tôi!”","“Giữ!” Ch’en quát.","“Guard, sẵn sàng!”","“Tràn qua chúng!”","“—Ngay!”","“Nỏ, loạt một, bắn!”","“Giáo lên!” Ch’en rút kiếm. “Đừng để một tên nào thoát khỏi thành phố của chúng ta!”","@bg:bg_lungmen_o","Trong văn phòng Trưởng quan, Wei Yenwu đang nói chuyện điện thoại, giọng thấp.","“Đã đến hiện trường chưa? Đúng vậy. Tôi biết. Nhưng L.G.D. có việc của họ, các vị có việc của các vị. Đừng quên vai trò của mình trong chuyện này. …Đúng vậy. Lin Kojui phản đối khá gay gắt. Nhưng việc này vượt quá tầm của ông ấy!” Ông ta im lặng một lúc. “Tôi đã nghe hết ý kiến của mọi bên liên quan. Nhưng ở đây không có chỗ để xoay xở. Tôi làm điều phải làm. Con gái của Kojui sẽ liên lạc với các vị. Trong ba tuần tới, không được liên lạc với tôi. Mọi thứ đều qua cô ấy. Tôi giao cho các vị. Đừng lo. Tôi đang theo dõi các vị.”","“…Không cần thế. Quá khứ là quá khứ. Và nó ở lại trong quá khứ.” Ông ta mỉm cười, không vui vẻ. “Phải. Vì một tương lai hòa bình và ổn định của Lungmen.”","Khi cuộc gọi kết thúc, ông ta ngồi im rất lâu. Và trong căn phòng vắng, có những giọng nói cũ vọng lại.","<i>“Wei, anh bạn già, chúng ta là anh em, theo một nghĩa nào đó, phải không…? Vậy nên tôi xin anh, vì con gái tôi và mẹ nó… Mà thật lòng, tôi có cần phải xin không? Anh thật sự từ chối giúp em gái ruột của mình sao?”</i>","<i>“Tôi đã chọn tên cho con gái rồi. Chúng tôi sẽ gọi nó là… Talulah.”</i>","<i>“Đừng để bụng. Tôi hiểu mà. Mọi chuyện đều rất rõ ràng với tôi.”</i>"],"bg":"bg_undergroud_f","cast":[["Blaze","npc:char_017_homura_3"],["Amiya","op:char_002_amiya"],["Swire","op:char_308_swire"],["Ch'en","op:char_010_chen"],["Wei Yenwu","npc:char_2005_weiyw_1"],["Mephisto","npc:char_1507_Mephisto_1"],["Faust","npc:char_1508_Faust_1"],["GreyThroat","op:char_367_swllow"]]},{"c":"6-2","t":"Hiểu lầm","p":["Có một ký ức, từ rất lâu trước kia, trên con tàu Rhodes Island.","<i>“Ồ… Rosmontis, em đang làm gì vậy?”</i>","Một cô bé nhỏ xíu, đôi tai mèo trắng muốt, đang ngồi bó gối trước một chiếc máy tính bảng đã tắt màn hình.","<i>“Em… em muốn sửa cái máy này. Ký ức sáu năm cho đến năm ngoái… em lưu hết vào đây… Sáng nay em định đọc nhật ký ngày 12 tháng 6, nhưng màn hình không bật lên. Lỡ… lỡ em không bao giờ đọc lại được nữa thì sao…? Nhật ký ngày 14 tháng 3, khi em đi vườn bách thảo với bố, hay đi leo núi hồi tháng 7, hay lần mà mẹ…”</i> Giọng cô bé run lên. <i>“…Mẹ…”</i>","<i>“Đ-đừng khóc! Nghe này, em không giỏi mấy thứ màn hình này, đúng không? Sao không chờ Scout giúp em sửa? Hay Closure? Chị sẽ mang nó đến cho Closure. Cô ấy sẽ sửa trong nháy mắt!”</i>","<i>“Scout… Có phải là anh operator lúc nào cũng đi lại lặng lẽ không ạ?”</i>","<i>“Đúng anh ta đấy! Em biết anh ta à?”</i>","<i>“Vâng. Cái vẻ ngoài bóng bẩy hoàn hảo… như búp bê sứ.”</i> Cô bé chỉ tay. <i>“Anh ấy kia kìa.”</i>","<i>“Hả…?”</i>","<i>“Tôi chưa được nghe đánh giá của em về tôi,”</i> Scout nói, từ chỗ bóng tối mà Blaze dám thề là vừa nãy còn trống không. <i>“Giờ tôi đã hiểu nó tệ đến mức nào.”</i>","<i>“Anh đến từ khi nào vậy?!”</i>","<i>“Cô có thể nói là tôi luôn ở đây. Tôi quen ẩn mình rồi.”</i>","<i>“Vậy là anh Scout ở đây từ nãy,”</i> Rosmontis nói. <i>“Sao chị Blaze không cảm nhận được ạ?”</i>","<i>“Chị… chị không để ý. Chị chỉ không nhận ra thôi!”</i> Blaze quay sang Scout. <i>“Này, nếu anh đứng đây suốt, sao không giúp con bé sửa?”</i>","<i>“Thứ lỗi. Chỉ ít phút nữa chúng tôi sẽ lên đường làm nhiệm vụ. Tôi phải tập trung hiệu chỉnh vũ khí. Cô có thể hỏi Closure, hoặc Mechanist tốt bụng giúp.”</i>","<i>“Các anh sắp đi cứu Doctor à?”</i>","<i>“Phải,”</i> một giọng trầm vang lên. Ace bước vào.","<i>“Ồ. Anh cũng đi.”</i>","<i>“Là tôi mà. Nếu tôi không đi, các operator tinh nhuệ của Rhodes Island còn ra cái thể thống gì?”</i>","<i>“Ascalon nói sao?”</i> Scout hỏi.","<i>“Như mọi khi. Cô ấy không đi. Lúc nào cũng ở bên Kal’tsit.”</i>","<i>“Anh có bao giờ nghĩ… có lẽ bây giờ không phải thời điểm tối ưu?”</i>","<i>“Nhưng có thể đây là cơ hội cuối cùng. Chernobog có lẽ sẽ quay ngược vào sâu trong Ursus để tránh Catastrophe kia. Và một chiến dịch giải cứu ở nội địa Ursus thì gần như không thể.”</i>","<i>“Tôi cứ nghe anh nói mãi, nhưng cái Doctor này thật sự đáng ngần ấy công sức sao?”</i> Blaze hỏi.","<i>“Đáng giá như Amiya và Kal’tsit.”</i>","<i>“Em đã gặp Doctor chưa ạ?”</i> Rosmontis hỏi.","<i>“Chưa. Nhưng em sẽ sớm gặp thôi.”</i>","<i>“Tốt quá. Em cũng muốn biết Doctor là người thế nào. Em muốn lắm, muốn lắm.”</i>","<i>“Em sẽ biết, mèo con,”</i> Scout nói.","<i>“Nhân tiện, Ace,”</i> Blaze nói, <i>“trong đội anh có một cô gái không nhiễm bệnh tên GreyThroat.”</i>","<i>“Tôi biết. Cô ấy đang huấn luyện riêng. Nghe này, Blaze. Tôi đã làm việc với cô ấy vài tháng rồi. Cô ấy khó bày tỏ bản thân, nhưng không phải người xấu.”</i>","<i>“Cô ta nhìn thẳng vào mắt đồng đội tôi và hỏi: ‘Là người Infected thì khó đến mức nào chứ?’”</i>","<i>“Tôi biết. Nhưng với cô ấy, đó có thể là một câu hỏi thật. Cô ấy có thể thật sự tò mò. Tôi không có quyền bắt một operator đổi ý kiến ngay lập tức. Và GreyThroat chưa bao giờ một lần nghi ngờ mệnh lệnh.”</i>","<i>“Tôi không quan tâm. Tôi sẽ không đứng nhìn cô ta sỉ nhục đồng đội tôi, và tôi chắc chắn sẽ không để cô ta bôi nhọ cuộc đấu tranh của người Infected.”</i>","<i>“Giờ không phải lúc. Tôi thấy cơn giận cô đang kìm nén. Nhưng thật đấy, không phải lúc này.”</i>","<i>“Cô ta nói ngay trước mặt tôi!”</i>","<i>“Hít thở đi, Mèo Lớn,”</i> Scout nói. <i>“Cô cũng có việc phải làm.”</i>","<i>“…Đúng vậy.”</i> Blaze thở ra. <i>“Được rồi. Đợi anh về rồi tính. Mà từ khi nào Ace lại thâm niên hơn tôi vậy?”</i>","<i>“Mỗi khi cô dùng giọng đó, tôi lại nghĩ có khi cô đang đùa.”</i>","<i>“Rất có thể cô ấy đang chế nhạo anh,”</i> Scout nói.","<i>“Chỉ cần anh ta hai ngày không cạo râu là trông thâm niên hơn hẳn.”</i>","<i>“Râu của anh Ace rất nam tính,”</i> Rosmontis nói nghiêm túc.","<i>“…Hừm.”</i>","<i>“Hahaha! Tôi phải đi chuyển ít đồ. Tôi cũng có việc của mình mà. Gặp sau nhé. Làm xong thì đi uống một chầu!”</i>","<i>“Lần này cố đừng nôn,”</i> Scout nói. <i>“Misery mất hai tiếng cọ sàn đấy. Tôi cá là nếu phải làm lại lần nữa, chính anh ta sẽ nôn.”</i>","<i>“Ai mà ngờ anh uống giỏi vậy!”</i> Blaze vẫy tay. <i>“Rosmontis, lát Mechanist sẽ trả máy cho em. Ngoan ngoãn chờ nhé. Nhưng đừng quên đấy!”</i>","<i>“Em nhất định sẽ nhớ! Tạm biệt!”</i>","<i>“Đừng tự làm bỏng mình!”</i> Scout nói với theo.","<i>“Yên tâm. Tôi kiểm soát được Arts của mình.”</i>","@bg:bg_building_3","Blaze ngồi trên một mái nhà, nhìn xuống Lungmen. Gió thổi tung mái tóc trắng.","“…Sao anh lại đi trước tôi chứ?” cô thì thầm. “Ace, một cô gái không nhiễm bệnh như GreyThroat thật sự đáng để huấn luyện sao? Chúng ta đã giành được bao nhiêu lòng tin? Và đã trao đi bao nhiêu lòng tin? Nếu Doctor…”","“Cô đang nói gì đằng đó vậy?!”","Blaze không quay lại. “Tôi đang nói xấu người. Ngay trước mặt người. Nếu có Doctor nào lảng vảng quanh đây thì mau ra đi. Người sẽ cần Arts hoành tráng lắm mới nấp sau bức tường đó mà không bị tôi tìm thấy. Rồi tôi sẽ treo người lên cột đèn làm mồi cho Reunion. Đừng lo! Người không chết đâu. Vài mũi tên với một hai nhát dao chưa từng giết ai cả.”","Cô thở dài. Rồi thở dài thêm lần nữa, to hơn.","“Amiya cử người đến à? Thôi kệ. Đó là việc con bé giỏi nhất. Và cũng là việc con bé dở nhất… Tôi cứ cố nhắc con bé, để con bé nghĩ rằng mình vẫn chỉ là một đứa trẻ… nhưng lần nào cũng có tác dụng ngược. Tôi đoán chừng nào còn là thủ lĩnh Rhodes Island, con bé sẽ không bao giờ bỏ được cái vẻ người lớn ấy.” Cô liếc sang Doctor. “Đương nhiên, nếu không phải Amiya cử người đến, nếu người tự quyết định đến bầu bạn với tôi, thì tôi cũng không phản đối.”","“Tôi chỉ sợ làm vướng chân cô.”","“…Vướng chân tôi? Haha! Tôi cõng ba người như người trên lưng còn chẳng biết. Một Doctor bé tí không làm vướng chân tôi được đâu.” Blaze bỗng nheo mắt. “Này, nhìn đằng kia.”","Dưới con phố, một toán Reunion đang đối mặt với vài lính L.G.D. lẻ loi.","“Đi đi! Ra khỏi đây! Bọn tôi không muốn đánh nhau!”","“Hừ… bọn ta sẽ không khuất phục người Infected!”","“Các anh đông không bằng! Có ích gì đâu?”","“Bổn phận!”","“Đừng trách bọn tôi những gì xảy ra! Các anh thấy lũ quái vật sau lưng bọn tôi không? Chạy đi!”","“Quái vật gì?!”","“Thấy toán Reunion đang len qua các con hẻm kia không?” Blaze đứng dậy. “Chúng đang tỉa dần các đơn vị tiên phong của Lungmen. Họ không trụ được lâu đâu… Cho tôi một đường đi.”","“Như mọi khi, hay…?”","“Nhanh nhất, đương nhiên!” Blaze nhe răng. “Đừng nhìn tôi như thế. Đâu phải tôi chưa từng cõng người. Đi thôi! Đập tan Reunion, cứu người Lungmen!”","","“Nnnng…” Tên Reunion cuối cùng gục xuống.","“Xin lỗi,” Blaze nói. “Đánh cậu không có nghĩa là ta không cùng phe. Haha! Ừ, không, nghiêm túc đấy. Có nghĩa là vậy. Ta không cùng phe.” Cô bấm bộ đàm. “Blaze đây. Gọi Đội Blaze-4. Bắt được chục tên Reunion. Rảnh thì đến nhận. Không thì cứ giao cho Lungmen.”","Cô quay sang người lính L.G.D. đang chĩa nỏ về phía mình. “Này, người Lungmen, giúp tôi hạ nỏ xuống đi. Chúng ta là bạn cả mà.”","Người lính không hạ nỏ.","“Anh vẫn không tin tôi à? Tôi vừa cứu mạng anh đấy.”","“Lùi lại…! Ý tôi là, c-cô… cô là người Infected…!”","“Ừ. Đúng vậy.” Blaze im lặng một lúc. “Ugh.” Cô quay đi. “Đi thôi, Doctor.”","Doctor không nhúc nhích.","“Đi!”","Rồi cô thở dài, giọng dịu xuống. “Haizz. Được rồi, Doctor. Lên đây. Đi thế này nhanh hơn.”","“Cô chắc chứ?”","“Hah. Quen được tôi cõng rồi à? Đừng nhìn tôi như thế. Bao nhiêu lần ta bị đối xử như vậy rồi? Chẳng có gì to tát.” Cô cõng Doctor lên lưng. “Ta đến Quảng trường Waang Saan ở Quận 16. Nếu Reunion muốn phá phòng tuyến, chúng phải phá ở đó. Muốn tiêu diệt chủ lực Reunion, ta không thể để tên nào lọt qua vùng kiểm soát của mình. Theo cách Amiya và bà cảnh sát già khó tính kia tính toán, ta sẽ bào mòn chúng từng chút một, cho đến khi xóa sổ chúng trong một đòn. Vậy là ta đi đuổi lũ xấu khỏi tháp Waang Saan, lùa chúng vào gọng kìm, rồi hội quân với Amiya đập tan Reunion một lần cho xong. Dễ ợt, nhỉ?”","Cô liếc lại. “…Người với cái mặt của người. Đã bảo là tôi không sao mà. Được rồi. Cứ nhìn tôi như thế nữa là tôi dừng xe đấy. Bám chặt vào.”","Rồi cô khựng lại trên một mép mái nhà.","“Hửm… Nhìn đằng kia. Chẳng phải đó là đàn chiên của Mephisto sao? Nhưng sao lại thế. Chúng cần có Mephisto ở gần, đúng không?” Cô nheo mắt. “Khoan đã. Chúng… chúng đang giết chính đồng bọn mình?”","","Ở trạm chỉ huy của L.G.D., Ch’en nhìn chằm chằm vào màn hình theo dõi.","“…Chuyện gì đang xảy ra vậy? Tôi nhận được sinh hiệu, nhưng không có báo cáo? Cũng không có tín hiệu cầu cứu nào. Có gì đó không ổn…”","“Cô không phải đang chỉ huy sao?” Swire hỏi. “Đứng đây nhìn gì vậy?”","“Không phải việc của cô, ‘cô gái nhỏ’.”","“Này, chẳng phải ta nên chia sẻ thông tin sao?”","“Lần này thì không.”","“Tôi đoán là cô mất liên lạc với một gián điệp.”","“Cô có thể đừng phí trực giác vào mấy chuyện này được không?”","“Ít ra khi tôi đoán đúng thì cô cũng thừa nhận. Người Infected à?”","“Phải.”","“Cô nghĩ anh ta phản bội à?”","“Không thể nào.”","“Cô nghĩ chuyện không thể đã xảy ra?”","“Nếu cô ấy phản bội… Thôi, tôi còn không muốn nghĩ đến. Nếu cô ấy phản bội chúng ta, thì ở Lungmen chẳng còn ai để tin nữa.”","Swire im lặng một lúc. “Tôi nghĩ tôi biết đó là ai. Khoan… Cô ấy thật sự sẵn lòng làm chuyện này sao? Cô ấy? Thật á?!”"],"bg":"bg_corridor","cast":[["Blaze","npc:char_017_homura_3"],["Rosmontis","npc:avg_npc_042"],["Ace","npc:char_014_riope"],["Scout","npc:avg_npc_026"],["Ch'en","op:char_010_chen"],["Swire","op:char_308_swire"]]},{"c":"6-3","t":"Mất tất cả trong một khắc","p":["“Mephisto?” Faust nhìn bầy quái vật đang gào thét quanh họ. “Anh vừa giải phóng thứ gì vậy? Đội của anh… còn hung hãn hơn trước. Chúng… chúng đang đau đớn.”","“Ồ, cậu nhận ra à? Những hạt giống ta gieo cuối cùng đã nở hoa,” Mephisto nói. “Không có gì phải lo đâu, Faust. Chúng sẽ không làm hại chúng ta.”","“Anh vẫn đang thúc đẩy sự lây nhiễm của chúng sao? Mephisto… dừng lại đi. Ta còn cơ hội sống sót.”","“Chỉ có ta mới thi triển được Arts như vậy! Và chỉ nhờ Arts của ta chúng ta mới thoát được! Cậu đã tận mắt thấy rồi. Nếu cứ thế xông lên, L.G.D. sẽ giết hết chúng ta trước khi ta đến được đường hầm thoát hiểm trong khu ổ chuột! Cậu từng thấy những vũ khí đó chưa? Ở Chernobog chẳng ai có vũ khí như thế! Đây là thành phố của chúng, chúng hiểu nó hơn ta nhiều! Chúng từ đâu ra? Chúng biến đi đâu?! Với chừng này người, ta không đời nào đối đầu nổi chúng! Bọn Ursus ở Chernobog quá yếu… Lungmen đối xử với ta như một đạo quân, nhưng ta đâu phải quân đội. Ta chỉ là một nhóm người cùng chí hướng đang cố sống sót!”","“Bình tĩnh lại. Sĩ khí đã đủ thấp rồi.”","“Nhưng đàn chiên của ta sẽ không bao giờ dao động trước thử thách!”","“…Chưa kể đến những thành viên Reunion vừa gia nhập. FrostNova chắc chắn sẽ giúp chúng ta.”","“FrostNova? Cái FrostNova đó?” Mephisto bật cười. “Hah! Hahah! Chẳng phải cô ta đã mang Yeti của mình đi phản bội chúng ta sao?”","“Mephisto!”","“Nếu không, ta đã có thể nghiền nát kẻ thù bằng sức mạnh đó rồi! Nhưng kể cả họ có quay lưng với ta, ta cũng không thể trách họ vì đã làm những gì cần để sống sót.”","“FrostNova không phải kẻ phản bội. Tôi đã nói rồi. Nhìn vào sự thật đi.”","“Đúng vậy… tất cả chúng ta đều làm những gì cần để sống sót.”","“Bình tĩnh lại, đừng mò vào bẫy của L.G.D.!”","“Ta kiểm soát được mà, Faust. Ta sẽ đảm bảo mọi người của ta được sống sót thoải mái.”","“Cái gì…? Anh định làm gì?”","“Ta sẽ cho L.G.D. thấy thứ gì đó kinh khủng hơn một đạo quân nhiều.” Mephisto mỉm cười. “Cứ đợi đến khi chúng thấy những bông hoa nở ra từ người của ta.”","“Mephisto?!”","“L.G.D. phải trả giá cho tội ác của chúng… Và ả Ch’en đó… Ả sẽ phải trả giá cho những gì ả đã làm với cậu!” Mephisto giơ cao cây trượng. “Các đồng chí của ta, người của ta, hãy nghe lời ta! Một sức sống huy hoàng đang nở rộ trong các ngươi… Hãy tiến lên, buông theo bản năng, gieo rắc hạt giống, và nắm lấy tương lai của các ngươi!”","“Không, Mephisto! Họ là những sinh mạng!”","Bầy quái vật rú lên, những tiếng gào hỗn loạn chói tai.","“Cả Lungmen là khu vườn của các ngươi! Đi đi, ngay, truyền sự sống trong các ngươi cho mọi người! Đi, đi, đi!”","Và bầy quái vật lao đi. Không phải về phía L.G.D.","“Hả? Cái gì?! Chuyện gì vậy?”","“C-các người làm gì vậy? Các người không thuộc đội bọn tôi!”","“…Tôi đã làm gì các người chứ?! Hay Mephisto…?”","“Đội trưởng? Đội trưởng?! Đội trưởnggggg!!”","@cg:avg_6_7","“Agh! C-các người… định… CẮN TÔI à?! Tại sao a-aaaaaaaaagh!”","“Cứu! Ai đó cứu tôi với!!”","Mephisto đứng giữa những tiếng thét, mỉm cười.","“Heh heh… Chúng mạnh hơn trước nhiều. Chúng không còn nghe thấy giọng ta nữa, nhưng chúng sẽ không tấn công chúng ta… Chúng sẽ mạnh hơn, bền hơn, và đông hơn. Và chúng sẽ nuốt chửng hoàn toàn Lungmen. Hah. Nếu người của ta không có được thành phố này, ta chắc chắn sẽ không để lại nó cho lũ người Lungmen!”","Cậu ta quay lại. “Faust, đến đây, đến lúc rồi… Faust?”","Faust đứng nhìn bầy quái vật đang xé xác những người từng là đồng đội của chúng.","“…Anh đã làm gì vậy?”","Một con quái vật ngẩng lên, máu chảy ròng ròng từ miệng. Nó rên lên, một tiếng rên đau đớn đến xé lòng.","“Faust? Cậu đi đâu vậy?!” Mephisto hét. “Faust!”","","“Tại sao người của Mephisto lại tấn công bọn ta?!”","“Tôi thấy rồi… Kinh khủng lắm… Chúng bắt Ivan… Rồi… Rồi Ivan cũng thành như chúng!”","“Suka! Mày là… quái vật gì vậy?! Chúng không biết đau. Tao đâm mà chúng không chết!”","“Chúng ngày càng mạnh! Không cản nổi!”","“Đi với tôi!”","“Faust?!” Một tên Reunion lùi lại. “Không! Có thể là bẫy của Mephisto!”","“…Anh ấy cứu mạng tôi,” một người khác nói.","“Mephisto là đồ cặn bã. Anh này chắc ổn.”","Faust nhìn họ, rồi chỉ về phía một con hẻm. “Ra khỏi đây. Nhanh lên. Nỏ Thủ Bóng Ma sẽ yểm trợ các cậu.”","“Được.”","“Cảm ơn… N-này!”","“Cẩn thận!!”","Một khối Originium bay vèo tới. Faust gạt nó đi, nhưng nó nổ tung sau lưng anh. “—Originium…? Chạy! Bầy quái vật đang đuổi theo các cậu!”","@bg:bg_uptown_2","“GreyThroat, chuyển động của địch thất thường,” Amiya nói qua bộ đàm. “Defender giữ phòng tuyến, Caster giảm quân số địch. Chị và các Sniper lo những người Infected có năng lực Arts.”","“Tôi được phép bắn chết người Infected sao?” GreyThroat hỏi.","“GreyThroat…” Amiya im lặng một lúc. “Về nguyên tắc, em không thể cho phép ai làm hại người Infected. Vì nếu em cho phép, chẳng phải người khác cũng sẽ cho phép người Infected làm hại người khác sao? Đó là một vòng luẩn quẩn. Nhưng nói thế cũng vô ích. Trên chiến trường không có chỗ cho triết học đạo đức. Lý tưởng nhất là không ai làm hại ai. Bất kể họ có nhiễm bệnh hay không.”","“…Đã hiểu.”","“Gavial đang hỗ trợ y tế nên… Chị nhớ cẩn thận. Đừng để bị thương.” Amiya nhìn về phía cuối phố, và khựng lại. “Cái gì vậy…? Trông như… đàn chiên của Mephisto…? Nhưng… em không cảm nhận được chút cảm xúc nào từ chúng?”","Một con quái vật thọc tay vào chính ngực mình, rút ra một khối Originium đen bóng.","“Không!” Amiya hét. “GreyThroat, nằm xuống! Có gì đó không ổn!”","“Chúng… đang rút Originium ra khỏi cơ thể mình?”","“GreyThroat!”","","“Doctor! Người có sao không?” Blaze đặt Doctor xuống sau một bức tường đổ.","“Tôi không sao! Cẩn thận!”","“Đàn chiên này bị làm sao vậy? Chúng hành xử khác hẳn!” Blaze giương cưa. “Không quan trọng. Ở đây người an toàn. Kiểu vậy. Đừng nhúc nhích! Tôi xử lý chúng rồi về ngay!”","","Ở một góc phố vắng, Faust quỳ bên cạnh một thành viên Reunion bị thương nặng. Người đàn ông thì thào bằng tiếng Ursus.","<i>Bao nhiêu người đã ngã xuống trước mặt ngươi?</i>","“Đương nhiên rồi. Tôi sẽ mang nó về cho anh,” Faust nói.","Người đàn ông lại thì thào gì đó, giọng như một câu hỏi.","“Không. Tôi sẽ không đến Chernobog.” Faust đặt tay lên vai anh ta. “Nghỉ đi. Ở đây anh sẽ an toàn. Nghỉ ngơi một chút.”","<i>Bao nhiêu người đã ngã xuống trước mặt ta?</i>","“Bỏ vũ khí xuống!”","Faust ngẩng lên. Ở đầu hẻm, một cô gái tóc xám đang chĩa nỏ về phía anh.","“Chỉ có anh…?” GreyThroat hỏi.","Faust không trả lời.","@cg:avg_6_8","“Cử động là tôi bắn!”","“Bắn trước. Rồi hỏi sau.”","Rồi anh biến mất.","“Cái gì? Anh ta… biến mất rồi?” GreyThroat đảo mắt khắp con hẻm. “Không… Tôi đã đọc hồ sơ của anh. Anh là Faust, một trong những thủ lĩnh của chúng. Arts của anh không lừa được tôi đâu! Tôi biết đây chỉ là trò quang học. Nếu tôi bắn, anh vẫn sẽ có một mũi tên trong đầu.”","“Sai rồi.”","Một mũi nỏ chạm vào gáy cô.","GreyThroat đứng im.","“Cô đoán được chuyển động của tôi không?” Faust hỏi. “Hai chúng ta, hai nỏ thủ đơn độc. Nếu cùng bóp cò một lúc, cả hai đều chết. Cô tên gì?”","“Mật danh GreyThroat. Anh ra sau lưng tôi từ khi nào?”","“Lần thứ ba cô chớp mắt.” Faust ngừng lại. “Cô khá thẳng thắn…”","“Anh đã bị tách khỏi đội. Tôi không ở đây để giết những người không muốn đánh nhau.”","“Chúng ta là kẻ thù.”","“Rhodes Island ở đây để cứu người Infected. Tôi đã thấy anh giúp họ.”","“Đó là đồng đội của tôi. Cô là kẻ thù của tôi.” Giọng anh không lên không xuống. “Rhodes Island thuê một người ngây thơ thế này từ khi nào vậy?”","“Đúng, tôi ngây thơ. Tôi chỉ biết làm theo lệnh. Mỗi khi phải tự quyết định, tôi đông cứng lại.”","“Cô cần cẩn thận.”","“Coi chừng ngón tay anh!” GreyThroat nói. “Đó là nỏ bắn một phát. Nếu tôi né được mũi tên của anh, anh chết. Đừng bóp cò.”","“Nếu cô chỉ biết làm theo lệnh, nếu cô dựa vào người khác bảo mình phải làm gì, kết cục sẽ chẳng tốt đẹp đâu.”","“Tại sao?”","“Phần lớn những con cừu mù quáng nghe lệnh thật ra không phụ thuộc vào ai. Chúng chỉ chưa bắt đầu tự suy nghĩ… Còn những kẻ không có phương hướng trong cuộc đời, chúng chỉ là những cỗ máy rỗng tìm kiếm cảm giác thành tựu và ý nghĩa. Cô được kích hoạt, rồi thực hiện chức năng. Cô nhập vào một mục tiêu, cô đạt được mục tiêu, cho đến khi cô nuốt chửng mọi thứ quanh mình, và nuốt chửng cả những người cô phục vụ.”","“Tôi sẽ không như vậy.”","“Cô còn non nớt.”","“Tôi đã thấy anh đối xử với người Infected lúc nãy. Anh đang làm đúng.”","“Ý kiến của cô chẳng có nghĩa lý gì với tôi.”","“Faust, anh đang tránh né L.G.D. Kể cả những người lẻ loi ngoài kia, anh cũng không bắn họ. Tôi đã quan sát anh.”","“Đừng nhầm sự kiên nhẫn của tôi là yếu đuối. Nếu tôi phục kích cô, cô đã chết rồi.”","“Nhưng anh không làm.” GreyThroat hít một hơi. “Anh kiệt sức rồi. Nghe một nỏ thủ nói đi, dây nỏ của anh căng quá rồi. Chắc chắn nó sẽ đứt.”","“Nghe một nỏ thủ nói đi, cô nói nhiều quá.”","“Anh cũng đã thấy những… người Infected đặc biệt kia. Chúng ta có thể cùng nhau tìm cách.”","“Có lẽ cô đúng.”","Mũi nỏ rời khỏi gáy cô.","“Khoan!”","“Nhưng tôi không làm được gì nữa.”","GreyThroat quay phắt lại. Con hẻm trống không. <i>Anh ta biến mất ngay khi cử động…? Mình không xác định được vị trí của anh ta!</i>","Một quãng lặng dài.","“…Hửm? Tại sao anh không giết tôi?”","Giọng Faust vang lên từ đâu đó, không rõ hướng nào. “Cô không bắn. Tôi cũng vậy. Nhưng lần sau? Nếu cô không giết tôi, tôi sẽ giết cô.”","“Tôi không muốn làm hại anh!”","“Tiếc thật. Tôi đoán cô cần ai đó trả lời mình. Không có câu trả lời, cô không thể hiểu. Đừng bận tâm. Giết chóc, cái chết, đó là những sự thật thường ngày của cuộc sống. Kể cả với Rhodes Island.”","“Tại sao chúng ta không thể cùng nhau cứu họ?”","“Tôi thật sự ước mình làm được. Nhưng tôi biết mình không thể. Đừng theo tôi. Cô vẫn chưa biết họ. Cô chưa có toàn cảnh. …Còn tôi? Tôi chẳng làm được gì nữa rồi.”","<i>Bao nhiêu người đã ngã xuống vì những điều ta đã làm? Bao nhiêu người đã ngã xuống vì những điều ta đã không làm?</i>"],"bg":"bg_outcity_1","cast":[["Faust","npc:char_1508_Faust_1"],["GreyThroat","op:char_367_swllow"],["Mephisto","npc:char_1507_Mephisto_1"],["Amiya","op:char_002_amiya"],["Blaze","npc:char_017_homura_3"]]},{"c":"6-4","t":"Vết sẹo mưng mủ","p":["“Nhanh! Lùi lại! Người Infected biến thành quái vật rồi!”","“Agh! Tôi bị cắn! Tôi bị cắn rồi!”","“Ung.”","“Aaaahh!”","Blaze đứng trên mép mái, nhìn xuống con phố nơi bầy quái vật đang tràn qua những chiến lũy của L.G.D.","“…Sao lại thành ra thế này…? Thằng nhóc khốn kiếp đó đã làm gì vậy?!” Cô quay lại. “Doctor, ta phải di chuyển! Phải hội quân với Amiya! Một tổ hỏa lực nhỏ không đối phó nổi bầy đông thế này. Phải cẩn thận! Giờ ta chẳng làm được gì cho L.G.D. nữa. Ta còn ở thế tệ hơn họ nhiều. Gác họ lại. Ưu tiên hàng đầu của tôi là đảm bảo an toàn cho người.”","","Ở một con phố khác, một đơn vị L.G.D. đang bị dồn vào chân tường.","“Bọn ta bị tràn qua rồi! Không rút là chết!”","“Đừng hoảng.”","Một người phụ nữ đứng sau lưng họ, khoác bộ y phục trang nghiêm, tay áo dài thượt, chiếc mũ cao trên đầu.","“Hả?! Ai…? Bộ y phục đó… Bà là…”","“Viện binh đến rồi. Đứng vững. Chia hai đội, đánh vào hai sườn chúng.”","“Nhưng thưa ngài…”","“Tin ta. Dù ta không thể tự mình ra tay, cách này sẽ thành công. Thực hiện gọng kìm, giữ chân địch, để những kẻ lẻ loi cho viện binh của các ngươi.”","“…Cảm ơn ngài! Nếu ngài không đến giúp…”","“…Đằng sau ngươi.”","“P-phản công!”","“Vô ích. Vào đội hình. Rồi rút lui.”","“Rõ, thưa ngài!” Người đội trưởng nhìn quanh. “Không, nếu làm vậy… Ta không giữ được ở đây. Phải tìm đường ra… Đúng rồi! Điểm cao! Ta lên cầu thang rồi đánh xuống hành lang! …Không. Ta chỉ có thể giữ. Nhưng ít ra sẽ không bị đám điên này dồn vào góc! Được. Quay lại, tập trung ở từng cửa, kéo các đội về, vào thế phòng thủ! Nhanh! Di chuyển!”","“Làm tốt lắm. Ta tán thành.”","“Thưa ngài, đi cùng bọn tôi!”","“Không cần. Đi đi. Ta sẽ di chuyển trên mặt đất.”","@bg:bg_indoor_n","“Không giữ được! Bọn ta chỉ có vũ khí đâm xuyên, mà chúng vô dụng với lũ này!”","“Giữ vững!” Người đội trưởng gào lên. “Ta là phòng tuyến cuối cùng của dân thường phía sau! Chiến đấu đến người cuối cùng! Cẩn thận Originium chúng ném. Nó ăn mòn trang bị, có khối còn phát nổ!”","“Ah…! Chúng trúng Ah Chung rồi!”","“Ah Chung, lùi lại! Cậu, lên! Đừng để chúng qua!”","“Guuhhh.”","“Aaaaaagh! C-chúng bắt được tôi! Chúng đang ăn tôi! Khôngg! Aaaaieeeee!!!”","“Ah Yee!!!”","“Thật đáng xấu hổ!” Một giọng nói vang như sấm.","Người phụ nữ mặc y phục trang nghiêm đã đứng giữa chiến lũy, một tay giơ cao.","“Tổng Quản Bạch Lôi Chính Pháp, phóng!”","Một tia chớp trắng xé toạc bầu trời. Rồi thêm một tia nữa, và thêm nữa, giáng thẳng xuống bầy quái vật.","“Nnng…!!”","“Arts sét?!” Người đội trưởng sững sờ. “S-sao… ngài quét sạch chúng chỉ trong một tia sáng?”","“Hộc… hộc…” Người phụ nữ hạ tay. “Ta vừa nói ta sẽ không ra tay. Nào ngờ các ngươi bất lực đến mức không bảo vệ nổi dân chúng. Đến nỗi ta bị buộc phải hành động, thật nhục nhã!”","“Thưa Ngự sử…”","“Ngự sử gì mà Ngự sử! Chẳng phải các ngươi được lệnh coi như ta không có mặt sao?” Bà ta khoanh tay. “Ta thấy tinh thần các ngươi đáng khen. Vậy mà thật đáng thất vọng khi thấy các ngươi nhảy loạn xạ không mục đích, để ta phải làm thay. Thật lòng, các ngươi đã làm cái gì vậy? Giờ thì! Về vị trí!”","“Nhưng ngài vừa nói…”","“Nhanh lên! Thấy ta làm rồi mà vẫn chưa học được cách hành động mau lẹ sao? À, nhưng đương nhiên rồi. Các ngươi không thấy ta. Ta chẳng làm gì cả. Rõ chưa?”","“Rõ như ban ngày!”","“Nhưng nếu một sợi tóc của một người dân nào bị tổn hại, tất cả các ngươi bị sa thải. Ngay cả ta cũng phải từ chức. Tất cả chúng ta thất nghiệp.”","“V-vâng, đương nhiên… Bọn tôi sẽ chiến đấu bằng tất cả sức lực.”","“Rất tốt. Giờ sao còn đứng đó? Đi!” Rồi bà ta ngừng lại, nhìn lên những mái nhà. “Nhân tiện…? Các ngươi có biết bọn Áo Choàng Đen kia không?”","“Áo Choàng Đen? Đó là gì ạ?”","“Đi khám mắt đi! Những người trên mái nhà, mặc áo choàng đen bay phần phật ấy.”","“Xin lỗi, thưa ngài. Ngài đang nói gì vậy?”","@bg:bg_outcity_1","“Defender, tản ra!” Swire hét.","“Đội trinh sát, lùi lại! Giữ vị trí bắn!” Ch’en ra lệnh. “Lũ người Infected đột biến này đang làm nhiễu sóng vô tuyến sao? Trinh sát của ta có thể gặp nguy.”","“Không giữ nổi…! Đông quá! Chẳng phải lúc nãy cô chém qua cả một đợt mấy thứ này sao? Sao giờ chưa làm vậy?!”","“Chuyện này khác!”","“Hah. Đúng là con Long puk gaai, lúc cần nhất lại vô dụng nhất!”","“Vậy sao cô không cho chúng tôi xem cô làm được gì!”","“Drone!” Swire giật lấy một chiếc drone phát thanh, ghé sát miệng. “TỔNG THANH TRA CH’EN NÓI: ĐỘI TRINH SÁT! LÙI LẠI! GIỮ VỊ TRÍ BẮN!”","Ch’en nhăn mặt, bịt tai. “Hả.”","“Thế nào?”","“Hả?”","“Tôi hỏi thế nào?! Tổ hỏa lực, bắn tên nổ!”","“Cô nói gì?!”","Swire nhìn cô ta.","“Giờ tôi điếc rồi nhờ cô đấy?!” Ch’en gắt. “Đi đi. Dùng tài năng của cô báo cho đội liên lạc ở Trạm Thu phát Originium Beta. Bảo họ thông báo cho mọi người: bầy quái vật rất lì, giữ vị trí, giảm thiểu thương vong, đừng tiết kiệm hỏa lực.”","“Cô đúng là đồ <i>[tiếng chửi Lungmen]</i>!”","“Tôi đọc được môi cô đấy!”","Swire mấp máy môi một chữ “diu”, rồi bỏ đi.","“Thưa sếp!”","“Tôi không nghe thấy!”","“THƯA SẾP!”","Tiếng gầm rú của bầy quái vật lấn át tất cả.","“Nói to lên!”","“THƯA SẾP!!!”","“Dùng tên phá công sự! Nhanh!”","Một loạt nổ lớn. Rồi, đột ngột, im lặng.","“…Yên tĩnh rồi,” Ch’en nói.","“Thưa sếp.”","“Được rồi. Tôi nghe được rồi. Nói đi.”","“Chúng ta có… khách.”","“Đã đến rồi à? Chúng nhân cơ hội trà trộn vào đơn vị ta, hả. Cũng đoán trước được. Chúng không bao giờ để ta tự do hành động. Dù sao, chuyện đó không thay đổi kế hoạch. Cứ để chúng thấy Lungmen mạnh thế nào.”","“Còn một chuyện nữa. Tôi… tôi không chắc báo cáo chính xác đến đâu.”","“Nói đi.”","“Một số đơn vị báo cáo thấy những người mặc áo mưa đen.”","“Reunion?”","“May là không phải. Bọn tôi thấy dấu vết họ giao chiến với Reunion. Và…”","“Và gì?”","“Và… những tên Reunion đụng độ với họ dường như đều chết theo kiểu, mô tả thế nào nhỉ…?”","“Nghe như truyện truyền thuyết đô thị. Những bóng người mờ ám chạy quanh Lungmen trong áo mưa đen giữa ban ngày nắng chang chang? Ai đó cần đi khám rồi…” Ch’en khựng lại. “…Áo mưa đen?”","","Trên một mái nhà, GreyThroat nằm sấp, mắt dán vào ống ngắm.","“…Cái gì… vậy?”","Ở con phố bên dưới, có những bóng người mặc áo mưa đen trùm kín đầu, di chuyển không một tiếng động. Họ nói chuyện với nhau bằng những câu ngắn, đều đều như máy.","“Khu 12 đã thanh tẩy. Không còn người Infected.”","“Đội 3 và 4 đang hoạt động.”","“Di chuyển sang khu tiếp theo.”","Dưới chân họ, những thân thể quái vật nằm la liệt. Một con còn rên rỉ, một tiếng khóc lạ lùng. Một bóng áo mưa cúi xuống, và tiếng khóc tắt.","Ở cuối phố, vài thành viên Reunion đang dìu nhau chạy.","“T-tại sao! Tại sao các người làm hại người của mình? Tỉnh lại đi! …K-không! Chạy! Nhanh!”","“Ra khỏi đây! Đừng để chúng bắt được! Chạy!”","“Đã xác định thêm mục tiêu,” một bóng áo mưa nói. “Nhóm người Infected bỏ trốn ở ranh giới Khu 13 và 6. 44 cá thể. Ước tính hoàn thành: trong vòng năm phút. Bắt đầu tác chiến.”","“Agh! C-cứu!”","“Bọn tôi đầu hàng! Bọn tôi—”","GreyThroat nhìn. Ngón tay cô cứng đờ trên cò nỏ.","“Ưm… K-không…”","@bg:bg_indoor_n","Trong một căn phòng tối ở rìa khu ổ chuột, vài thành viên Reunion ngồi tựa lưng vào tường. Một người lạ ngồi cùng họ, mũ trùm che kín mặt.","“Ngoài kia loạn hết cả rồi,” một người nói. “Người ta bảo Mephisto dùng Arts tạo ra lũ quái vật tấn công cả bọn ta. Chúng ăn cả người Infected như ăn bất kỳ ai.”","“Hah. Hết rồi. Ta thua rồi.”","“Có người tìm thấy một đội của Mephisto trong một căn hầm ở khu ổ chuột. Họ bảo các xác chết phủ đầy cây cỏ, cây vẫn đang mọc, đến mức không nhận ra được nữa. Có ai hiểu không?”","“Tôi không chắc,” người lạ nói.","“Kỳ lạ thật. Sao mọi thứ đều kỳ lạ thế? Ta hạ được Chernobog, nhưng không phá nổi Lungmen. Chắc là vì Talulah chưa xuất hiện. May mà ta không theo nhóm của Crownslayer. Không ai liên lạc được với họ cả. Chỉ còn bọn ta ở đây. Haizz.” Người đàn ông quay sang. “Còn anh thì sao, người Infected Lungmen? Haizz. Anh biết không, người Lungmen, có khi anh còn sống tốt hơn bọn tôi chỉ vì không gia nhập Reunion.”","“Bọn tôi sẽ không sống tốt hơn chỉ vì không gia nhập.”","“Có phải bài diễn văn của Talulah khiến anh gia nhập không?”","“Không. Lời lẽ hoa mỹ chẳng có tác dụng gì với tôi. Hỏi tôi câu đó… Tôi đoán anh không quan tâm lắm đến chuyện chính trị bản sắc của người Infected.”","“Ồ. Nghe như anh không thật sự tin vào mấy thứ đó.”","“Vậy sao anh ở lại với Reunion?”","“Vì tôi chẳng còn nơi nào khác để đi. Nhưng nếu bọn tôi không đến đây, các anh còn sống bình thường được không?”","“Cuộc thanh trừng người Infected vốn dĩ đã sắp đến. Reunion chỉ đẩy nhanh nó thôi.”","“Anh nhìn rõ thật.” Người đàn ông gật gù. “Và anh nói đúng. Quê tôi là một nơi nhỏ, xa các thành phố lớn. Họ cũng không quá tệ với người Infected. Gia tộc quý tộc cai quản ở đó có một cô con gái bị nhiễm bệnh. Họ để bọn tôi sống khá bình thường trong khu biệt lập. Việc ở mỏ không quá nặng. Người không nhiễm bệnh cũng đối xử với bọn tôi tạm ổn. Ít ra họ còn buôn bán với bọn tôi một chút, thỉnh thoảng còn ngồi xổm bên tường uống chung một ly.”","“Rồi vài năm sau, ông công tước thua trận hay sao đó, bị bắt đi. Họ cử đến cho bọn tôi một thị trưởng mới.”","“‘Cuộc Đại Nổi Dậy’?” người lạ hỏi. “Quý tộc bị tước tước vị khắp nơi.”","“Có lẽ. Tôi chưa bao giờ hiểu chính trị. Bọn tôi chỉ thỉnh thoảng nghe được vài lời thì thầm. Nghe nói ở đâu đó có những Infected Messenger, nhưng Ursus chưa bao giờ có. Bọn tôi chẳng biết gì cả. Lúc đầu, mọi người sống gần như trước. Nhưng không khí nặng nề hơn. Và mỗi ngày kho lương thực lại vơi đi một chút. Từ từ, mọi thứ trở nên tệ hại. Khi lương thực thật sự cạn kiệt, người không nhiễm bệnh bắt đầu ném đá vào bọn tôi. Rồi người của bọn tôi bắt đầu biến mất. Và sau vài chục bài diễn văn ở quảng trường thị trấn, chẳng ai nhắc đến chuyện ông thị trưởng biển thủ, hay chuyện ông ta sửa sang trung tâm thị trấn cho riêng mình. Ý tôi là, người Infected bọn tôi thấy rõ. Dân thị trấn bình thường hẳn phải biết. Từ bên kia bức tường khu biệt lập, bọn tôi nghe họ hô vang những câu như ‘thanh lọc thị trấn’ và ‘tiêu diệt người Infected’.”","“Các anh là vật tế thần của ông ta.”","“Đời cho ta quả chanh mà, nhỉ? Nhưng chẳng phải lúc nào bọn tôi cũng là vật tế thần sao? Tôi biết tôi nói thị trấn đối xử với bọn tôi khá tốt, nhưng đó chỉ là vài chục năm gần đây. Phần còn lại của câu chuyện đơn giản lắm. Họ xông vào giết phần lớn người Infected. Những người còn lại chạy vào hoang mạc, nơi khoảng một nửa chết đói. Giờ ở Lungmen này, thêm nhiều người nữa chết. Tất cả mọi người ở quê tôi đều đã chết.” Người đàn ông bật cười khẽ. “Vậy đấy, anh nói đúng. Mọi chuyện là như vậy. Thế giới này không có chỗ cho người Infected. Nguồn hy vọng duy nhất là bọn tôi không phải tận mắt thấy nó sụp đổ.”","“Sao anh kể cho tôi nghe chuyện này?”","“Tôi có cảm giác mình không còn nhiều thời gian. Anh có cách nào giết người nhẹ nhàng, không đau đớn không?”","“Anh đang nói gì vậy…?”","“Hả? Ồ… Xin lỗi? Có lẽ tôi đọc nhầm rồi.”","“Người Lungmen vẫn ghét các anh. Các anh đã tấn công thành phố của chúng tôi.”","“Chắc vậy. Nhưng thành phố của người Infected ở đâu?”","Người lạ không trả lời.","Một làn khói mỏng len qua khe cửa. Rồi ánh lửa bập bùng ở cuối hành lang.","“Hả? Cháy à?” Người đàn ông đứng dậy. “Này, đừng nóng nảy thế chứ… Muốn ngồi cạnh cửa sổ thì cứ nói. Không cần bạo lực.”","“Lửa lan nhanh quá,” người lạ nói, nhìn ngọn lửa. “Lạ thật. Đây không phải lửa tự nhiên. Nó không lan như ‘lửa thật’.”","“Vậy thì ra khỏi đây thôi. Ai ngờ chỗ này cũng thành địa ngục. Đi với bọn tôi. Người Lungmen các anh không thích rời nhà, đúng không? Thì rời nó cùng bọn tôi luôn cũng được.”","“Đi với các anh?”","“Ừ, sao không? Không muốn thì thôi.”","“…Tôi sẽ nghĩ về chuyện đó.” Người lạ đứng dậy, nhìn ngọn lửa đang liếm dần lên trần nhà. “Nhưng, nhà… Nhà ở đâu?”"],"bg":"bg_uptown_2","cast":[["Ch'en","op:char_010_chen"],["L. G. D. Captain","npc:char_015_lmg"],["Swire","op:char_308_swire"],["Censor","npc:avg_npc_039_1"],["Blaze","npc:char_017_homura_3"],["GreyThroat","op:char_367_swllow"]]},{"c":"6-5","t":"Giết ai?","p":["“Chúng đã mất hết nhân tính…” Amiya nói khẽ, nhìn những thân hình quái vật nằm la liệt quanh mình.","“Amiya…” một operator lo lắng gọi.","“Ừ. Em không sao. Còn liên lạc được với Blaze, Doctor và GreyThroat không?”","“Không vấn đề gì.”","“Tốt. Giữ liên lạc với họ. Giúp họ tìm đường.”","Một con quái vật còn sót lại lảo đảo đứng dậy, rú lên một tiếng như thèm khát.","Amiya nhìn nó. “Em không cảm nhận được… gì từ ngươi nữa. Cái đường viền mờ nhạt của một sợi thù hận, tất cả đều đến từ Mephisto… Em phải thanh tẩy nó… chất độc thù hận của Mephisto.” Cô bé giơ tay lên. “Em hứa. Em sẽ làm.”","@bg:bg_outcity_1","“Tôi đã quét xong tàn quân Reunion và đến điểm mốc,” Ch’en nói vào bộ đàm. “Nhưng tình hình ở khu ổ chuột không như ta dự đoán. Đơn vị L.G.D. canh giữ khu vực không thấy dấu vết Reunion. Tôi phải tự mình điều tra. Số người Infected đột biến đã giảm? Có phải các cô làm không? Không à? Cẩn thận… Không ai biết nguy hiểm nào có thể ẩn trong bóng tối. Đừng lơ là. Những người Infected này khó đối phó hơn nhiều so với Reunion bình thường. Xong việc ở đây, tôi sẽ cử một đội đến hỗ trợ. Giữ kênh mở. Hết.”","Cô ta quay phắt lại. “Ai đó?!”","“Là tôi! Báo cáo!”","“Không phải cậu…”","“Hả…?”","“Không có gì. Báo cáo đi.”","“Rõ, thưa sếp! Theo lệnh, bọn tôi đã càn quét khu vực!”","“Tìm thấy gì?”","“Không gì cả! Không một dấu chân Reunion nào!”","“Tôi đã bảo phải để ý mọi thứ bất thường!”","“Ồ… Úi. Bọn tôi thật sự không biết khu này chút nào. Ý tôi là, theo quy trình, bọn tôi không vào đây trừ khi có vấn đề nghiêm trọng đến mức phải phá cả một dãy nhà hay gì đó.”","“Tôi biết… Với các cậu, khu ổ chuột không tồn tại, chừng nào nó còn yên ắng.” Ch’en nhìn quanh con phố vắng tanh. “Khi ta cắt đứt Reunion, có một tiếng động chói tai phát ra từ nơi này, và một nửa cư dân ở đây biến mất. Nhìn những món đồ chơi vương vãi dưới chân ta đi… Nhìn cảnh này rồi nói tôi nghe là không có gì bất thường.”","Dưới chân cô ta, một con búp bê vải nằm lăn lóc trong vũng nước.","“Kế hoạch có nói gì về việc sơ tán toàn bộ cư dân khu ổ chuột không?”","“…Có vài điều bất thường. Phần lớn các tòa nhà trong quận bị bỏ hoang hoặc hư hại. Những con phố còn lại hoàn toàn trống. Có lẽ do giao tranh giữa Reunion và người địa phương. Có vài đám cháy. Bọn tôi đã dập tắt. Có vẻ do sinh hoạt như sưởi ấm và nấu nướng. Mọi tòa nhà đều có dấu hiệu bị phá cửa, nhưng không có dấu vết kháng cự nào từ cư dân. Còn về Reunion, thật sự không có dấu vết gì. Chỉ có… vài vết tẩy rửa.”","“Các cậu không quan tâm chút nào đến dân thường ở đây sao?”","“…Xin lỗi, thưa sếp!”","“Cậu xin lỗi vì cái gì?”","“Tôi không biết, thưa sếp!”","Ch’en thở ra. “Thôi… Sao cậu phải quan tâm đến ai ở một nơi như thế này chứ? Mau cử vài đội phong tỏa khu vực! Không ai ra vào. Xe cộ cũng không. Reunion hay không cũng vậy! Còn cậu… Đi với tôi. Ta đi về phía bắc.”","“Rõ, thưa sếp!”","Họ đi được vài chục bước thì Ch’en đột ngột dừng lại, giơ tay. <i>(Suỵt. Đừng phát ra tiếng! Lối này. Nhanh.)</i>","“Rất tinh ý,” một giọng nói vang lên từ trên mái nhà.","Một bóng áo mưa đen đứng ở mép mái, nhìn xuống.","“Cậu làm gì vậy?!” Ch’en quát người lính đang giương nỏ.","“Chuẩn bị bắn!”","“Ngươi không nên đi theo,” bóng áo mưa nói. “Kiểm soát cấp dưới của ngươi đi, Ch’en.”","Ch’en im lặng một lúc. “…Đi tìm Swire.”","“Nhưng thưa sếp…”","“Đi!”","Khi người lính đã chạy đi, Ch’en ngẩng lên. “Ai cử ngươi đến?”","“Ta không trả lời ngươi.”","“Ngươi nghĩ ngươi chạy được sao? Thử đi, ta sẽ bắt ngươi ngay tại chỗ. Ngươi là một thành phần vũ trang không rõ danh tính, không rõ nguồn gốc. Ngươi nghĩ L.G.D. sẽ đối xử với ngươi thế nào? Bọn ta có thể bắn chết ngươi đấy.”","“Đào tạo một đơn vị L.G.D. mới sẽ lãng phí thời gian, tiền bạc và nhân tài của Lungmen. Còn xóa sổ toàn bộ L.G.D. sẽ là một đòn chí mạng vào trái tim cộng đồng Lungmen. Ngươi không nên mạo hiểm.”","“Hah! Lời đe dọa đó là để dọa ta à? Hay ta nên cảm ơn ngươi vì lo lắng cho tương lai của Lungmen?”","“Ch’en, L.G.D. là bộ mặt của Lungmen, cũng là trụ cột của cộng đồng, và là minh chứng mẫu mực cho sức mạnh của nó. Và L.G.D. nên ở đúng làn đường của mình. Đừng để nó chõ mũi vào những chỗ không thuộc về nó.”","“Những lời đe dọa của ngươi thật sự không làm ta ấn tượng. Mau trả lời câu hỏi: cư dân ở đây đi đâu hết rồi?”","Bóng áo mưa im lặng.","“Ngươi chỉ cách một lần bấm nút ‘báo động mọi đơn vị’ này là biến cả L.G.D. thành kẻ thù.” Ch’en giơ thiết bị liên lạc lên. “Hoặc ta đoán ngươi có thể dành một phần giây để hất kiếm của ta, chém đứt tay ta, và giật lấy cái máy này. Cư dân khu ổ chuột đi đâu hết rồi?”","“Bọn ta sẽ rút khỏi đây. Ch’en, cả ngươi và ta cùng rút. Tạm thời, đừng can thiệp vào nhau.”","“Và ngươi nghĩ ngươi đi đâu?”","“Những người Infected kiểu mới mà Reunion đang điều khiển có thể cản trở những kế hoạch đã được sắp đặt cẩn thận của bọn ta. Bọn ta sẽ nhanh chóng loại bỏ chúng giúp L.G.D. Xin hãy làm phần của ngươi, tiêu diệt chủ lực Reunion. Nếu L.G.D. muốn đạt được mục tiêu chiến lược, nó nên tập trung vào bổn phận của mình. Ngươi phải làm điều ngươi phải làm.”","“Khoan! Ngươi nghĩ ngươi cứ thế mà đi được sao? Đến rồi đi tùy ý?!”","“Tổng Thanh tra Ch’en, cho phép ta đưa ra một lời khuyên. Đừng tìm cách điều tra những gì đã xảy ra ở đây. Ta tuân lệnh Ngài Wei, và sẽ không đôi co với ngươi nữa.”","“—!”","“Nhân tiện, chém đứt tay ngươi khá đơn giản. Khi ngươi kiên định, ngươi mạnh hơn bây giờ gấp trăm lần.”","“Này—!” Swire chạy tới, nỏ trong tay.","“Lùi lại, Swire!”","“…Ta xin phép.”","Bóng áo mưa biến mất.","“Quay lại đây!” Ch’en hét theo, rồi đấm mạnh vào bức tường. “Chết tiệt!”","“Chuyện gì vậy? Đó là ai?”","“Lực lượng đặc nhiệm của Lungmen đang hành động. Và tôi không biết cư dân quận này có đang nằm chồng chất trong một nấm mồ tập thể nào đó không.”","“Hả? Cô đang nói gì vậy…?”","“Đừng giả ngu. Cô biết. Hoặc ít nhất cô đã nghe nói.”","“Biết gì…? Khoan, cô biết à?”","“Tôi không biết. Nhưng ông nội cô chắc chắn biết.”","“Hả? Nghiêm túc đấy, rốt cuộc ta đang nói chuyện gì vậy? Diu ah! Nói thẳng ra đi! Ông nội tôi nằm liệt giường rồi. Tôi còn không moi được hai chữ từ ông!”","“Ốm liệt giường thì không điều hành Lungmen được nữa à? Cô biết rõ hơn tôi ông nội cô là người thế nào mà!”","“Không đời nào!” Swire khựng lại. “…Nhưng mà…”","“Cô đang nghĩ đến ai?”","“‘Lin Gray’.”","“Hừ. Giờ đến lượt tôi nói ‘không đời nào’! Lin điều hành khu ổ chuột như thái ấp riêng. Không đời nào ông ta để chuyện như thế này xảy ra.”","“Gọi vài cuộc hỏi thử đi. Biết đâu sẽ tìm ra. Cô gọi? Hay để tôi?”","@bg:bg_indoor_n","<i>Trong khi đó, ở phía bên kia khu ổ chuột…</i>","“Bình tĩnh! Nói lại từ từ!” Crownslayer nắm lấy vai một thành viên Reunion đang run lẩy bẩy.","“N-nhưng… tất cả họ… họ chết hết rồi!”","“Chuyện gì vậy? Đã xảy ra chuyện gì? Tôi không thấy gì cả! Tôi không thấy gì hết!”","“Gah!”","“Nói lại!”","Không có tiếng trả lời.","Crownslayer đứng giữa màn sương dày đặc. Xung quanh cô ta, từng người một đang biến mất.","“Báo cáo!”","…Một tiếng thở ra, rất khẽ, ở đâu đó trong sương.","“Ai đó?!” Crownslayer xoay người. “…Mùi đó. Đừng hoảng! Mọi người vẫn ở đây! Nghe đây!”","“Aaah! Màu đỏ! Tôi thấy rồi! Tôi thấy màu đỏ!”","“Làm cậu ta bình tĩnh lại!”","Một tiếng cười vang lên trong sương mù. Không phải tiếng cười của người.","“Tôi… tôi muốn về nhà… Tôi muốn về Ursus…”","“Ở đây có ma! Và quái vật! Tôi thấy những cái bóng… của hai người phụ nữ!”","“Aaaaaagh! Tôi muốn về nhà! Lẽ ra ta không nên đến, Crownslayer!”","“Nghe rõ không? Trả lời tôi!” Crownslayer hét vào bộ đàm. “Bố cục khu ổ chuột này rối rắm, nhưng đừng để kẻ thù làm các cậu rối trí. Chúng ta hoàn toàn an toàn!” <i>(Sao vị trí của ta vẫn bị lộ dù sương mù dày thế này?)</i>","Và trong bộ đàm, có một giọng nói khác. Lạnh lẽo. Quen thuộc.","“Vẫn còn vị trí của kẻ phản bội. Ta biết. Cô ta đang ở Lungmen. Giết cô ta. Hãy tạo cho mình một cái tên mà kẻ thù phải sợ hãi.”","Crownslayer đứng sững. “…!”","Rồi một giọng nói thứ ba, rất gần, từ ngay trong màn sương.","“Sau khi giết được đối thủ rồi, thì sao? Đừng quên kẻ thù thật sự của ngươi.”","“—Ai?!”","@bg:bg_lungmen_d","“Đưa cô ta đến đây cho tôi!” Swire hét.","“Xin lỗi, cô Swire, đưa ai đến ạ?”","“Đưa cô ta đến đây!!!”","“Ờ?” Người lính quay sang đồng nghiệp. <i>(Cô ấy đang nói ai vậy?)</i>","<i>(Không biết, có lẽ là…)</i>","“Con chuột cống tóc hồng đó! Gọi số 100800-00200-rct211-93001! Đó là số của nó!”","<i>(Sao cô ấy thuộc được một dãy số dài thế?)</i>","<i>(Số đó quen quen… Có phải là cô gái đó không…?)</i>","“Hai người thì thầm cái gì vậy?!”","Đầu dây bên kia nhấc máy. “A lô.”","“Mày định làm gì vậy, con chuột bẩn thỉu?! Mày đã làm gì?!”","“Sao cô lại nghi ngờ tôi?” Một giọng nữ điềm tĩnh.","“Mừng là không phải mày. Phù. Mày làm tao lo đấy…” Swire khựng lại. “…Nghi ngờ mày cái gì cơ?”","“Nếu cô đang nói về lực lượng đặc nhiệm, thì đó là tôi.”","Swire đứng im rất lâu.","“Lin Yühsia, tôi nghĩ tôi nghe nhầm. Tôi nghe nhầm cô rồi, phải không?”","“L.G.D. có việc của L.G.D., bọn tôi có việc của bọn tôi,” Lin Yühsia nói. “Wei Yenwu có cô để giữ trật tự Lungmen, còn bọn tôi ở đây để loại bỏ những thứ Lungmen không cần.”","“Cô có biết đội đó đã làm gì trong khu ổ chuột không?”","“Họ đã giúp các cô xử lý Reunion khá hiệu quả.”","“Vùng đệm đó là máu, mồ hôi và nước mắt của bố cô! Nhờ ông ấy và công sức của ông ấy ở khu ổ chuột mà Lungmen mới được như ngày hôm nay!”","“Cô có biết mục tiêu của họ không?”","“Cô đã nói rõ quá rồi. Khu ổ chuột đầy chỗ để Reunion ẩn nấp, chưa kể còn là tuyến xâm nhập của chúng. Các cô sẽ san phẳng nó! Đúng không? Chúng tôi đang hợp tác với Rhodes Island. Reunion không phải đối thủ của chúng tôi! Các cô không cần làm thế này!”","“Vội kết luận trước cả khi tôi kịp giải thích… Dù Reunion chắc chắn không phải đối thủ của chúng ta, chúng vẫn không phải vấn đề mà lực lượng dân sự nên giải quyết. Chúng ta phải dùng sức mạnh thật sự của thành phố để xóa bỏ mối đe dọa này. Đó là cách tôi đối mặt với quân xâm lược.”","“Tại sao cô không thể đặt niềm tin vào Rhodes Island và L.G.D. của chính chúng ta?”","“Tại sao chúng ta phải tin Rhodes Island? Và tại sao phải làm bẩn tay L.G.D.?”","“Ý cô là làm bẩn…?” Giọng Swire run lên. “Đừng nói với tôi là cô không có lựa chọn nào khác. Đó là đất của bố cô. Xây dựng tốn công hơn phá hủy nhiều lắm! Phá vỡ một tấm kính chỉ cần một người, một giây… Cô có biết làm ra một tấm kính mất bao lâu không? Cần bao nhiêu người không?”","“Swire.”","“Hửm?”","“Cô có biết người dân sợ điều gì không? Cô có biết các phòng thương mại sợ điều gì không?”","“Cô bị sao vậy? Chẳng phải ta đang đối đầu với Reunion sao?”","“Cô thật sự chẳng hiểu gì cả.”","“Được thôi. Chuột bẩn thỉu… Tôi không hiểu. Tôi có thể hạ mình xin cô ban cho tôi một lời giải thích không?”","“Người Infected… đang ngày càng đông. Người dân sợ người Infected, và họ không quan tâm đó có phải Reunion hay không.” Lin Yühsia ngừng lại. “Tóm lại, đừng đi lục lọi trong cống ngầm.”","“Hả? A lô? Cô còn đó không?! Con chuột thối tha ăn cứt!!” Swire hét vào máy. “Mày dám cúp máy tao! Sei puk gaai syu ah! Sao mày dám cúp máy tao?!!”","@bg:bg_indoor_n","Ở đầu dây bên kia, Lin Yühsia hạ máy. Cô gái tóc hồng ngồi một mình trong căn phòng tối, nhìn ra ô cửa sổ.","“Ch’en đuổi được bọn Áo Choàng Đen à?” Cô thì thầm. “Phải làm sao đây… Chúng sẽ vượt qua cô ta, và đẩy nhanh tốc độ. Hừm, vậy cũng được.”","Cô nhắm mắt lại.","“Bố, nếu bố là con, nếu bố của ngày trẻ là con, bố cũng sẽ làm thế này, phải không?” Một quãng lặng. “…Mình đang làm gì vậy…?”","","“Ý ngươi là sao? Không thể nào,” Mephisto nói.","“Đàn chiên của anh đang co lại,” một Nỏ Thủ Bóng Ma báo. “Đợt tấn công đầu tiên rất dữ dội và kinh hoàng, nhưng… Bọn tôi không rõ tại sao, trinh sát báo số lượng chúng không tăng nữa. Tiếc là nhóm chịu thiệt hại nặng nhất từ chiến thuật này lại là toán Reunion hứng đợt tấn công đầu tiên.”","“Ai? Ai làm chuyện này? L.G.D.? L.G.D. không bao giờ áp chế được đàn chiên của ta!”","“Nhưng người của chúng ta…”","“Ta đã tính đến chiến thuật và trang bị của L.G.D. Đối mặt đàn chiên của ta, lẽ ra chúng phải bị cầm chân ít nhất hai ngày. Vậy ai đã làm chuyện này?!”","“Những người mặc áo mưa đen.”","Faust bước ra từ bóng tối, áo choàng rách tả tơi, máu khô trên má.","“Đội trưởng!”","“Faust!”","“Nỏ thủ, tổ chức lại đội!” Faust nói. “Đội của tôi và vài đội khác đã gom được nhiều người của Mephisto.”","“…Tại sao?”","“Cùng nhau, ta có thể cầm chân L.G.D.”","“Faust, Faust… cậu bị thương à?” Mephisto chạy đến. <i>(Sao lúc nãy cậu bỏ đi?)</i>","“…Vì tôi phải đi.”","“Và ta mừng khi thấy cậu mang về nhiều người của chúng ta đến vậy. Cậu sẽ dùng họ hiệu quả để đánh L.G.D., ta chắc chắn thế, phải không?” Mephisto nhìn quanh. “Chúng sẽ không tấn công ta, nhưng ta không điều khiển được chúng. Ta đã vắt óc mãi. Mà cũng chẳng còn bao nhiêu. Ta sẽ cần thêm người của chúng ta để bảo vệ mình. Phải đánh bại lũ L.G.D. đó nếu muốn trốn thoát. Hừm…”","“Mephisto, đừng dùng Arts đó nữa.”","“Nhưng chẳng phải cậu nói chúng ta phải sống sót sao, Faust? Chẳng phải đó là điều quan trọng nhất sao?”","“…Vậy tại sao anh lại…?” Faust im lặng một lúc. “Tại sao anh nói anh sẽ chết vì con quái vật đó, ở Trụ sở L.G.D.?”","Mephisto không trả lời được.","Faust quay đi. “Nỏ thủ.”","“Sẵn sàng.”","“Bắt anh ta lại.”"],"bg":"bg_indoor_n","cast":[["Ch'en","op:char_010_chen"],["Swire","op:char_308_swire"],["Lin Yühsia","npc:avg_npc_036"],["Crownslayer","npc:char_1502_crowns"],["Mephisto","npc:char_1507_Mephisto_1"],["Faust","npc:char_1508_Faust_1"],["Amiya","op:char_002_amiya"]]},{"c":"6-6","t":"Bỏ lại sau lưng","p":["<i>“Eno, cuốn sách này nói về gì vậy?”</i>","<i>“À, mình đọc rồi. Nên mang đến cho cậu. Mình nghĩ cậu sẽ thích đấy, Sasha! Đây là một cuốn sách về lý tưởng.”</i>","<i>“Lý tưởng?”</i>","<i>“Ừ.”</i>","<i>“Lý tưởng của cậu là gì, Eno?”</i>","<i>“…Lý tưởng à. Mình không biết. Mình có được có lý tưởng không?”</i>","<i>“Đương nhiên là được! Sao lại không?”</i>","<i>“A, chết, đến giờ về rồi…”</i>","<i>“Cậu không muốn về à?”</i>","<i>“…Mình không muốn về nhà.”</i>","<i>“Nhưng Eno, cậu bảo nếu không về, bố cậu sẽ đánh cậu… Nhưng mai mình lại gặp cậu, đúng không? Mai mình vẫn gặp được cậu mà.”</i>","<i>“Mình biết. Mình để sách với ít bánh mì ở đây.”</i> Một quãng lặng. <i>“…Sasha, mình không muốn đi. Kinh khủng lắm. Giờ về cũng sẽ bị đánh thôi.”</i>","<i>“…Vậy mai cậu ra đây. Nếu cậu bị đánh, cậu có thể đánh mình.”</i>","<i>“Hả…? Hahaha, Sasha, cậu lại đánh nhau à? Bị đánh vào đầu rồi à? Cậu có vết bầm kìa, nhiều vết thương quá.”</i>","<i>“Như vậy người ta sẽ biết cậu đang đau. Ít ra cũng có người biết.”</i>","<i>“Ừ, mình biết cậu đang nghĩ gì. Nhưng mình sẽ không làm vậy đâu.”</i>","<i>“Nếu mấy đứa đó còn bắt nạt cậu, cứ báo mình! Mình sẽ hạ hết chúng!”</i>","<i>“Mình biết mà! Mai gặp nhé! Mình sẽ lại đến hát cho cậu nghe!”</i>","","Tôi thậm chí không biết chuyện gì đã xảy ra với cậu ấy.","Tôi chỉ biết cậu ấy cho tôi đồ ăn.","Tôi chỉ biết cậu ấy biết đọc, còn tôi muốn đọc, và cậu ấy đã dạy tôi.","Tôi chỉ biết những đứa trẻ khác thích bắt nạt cậu ấy vì cậu ấy cho tôi bánh mì, còn tôi khỏe hơn, nên tôi đánh chúng và chúng đánh tôi.","Nhưng tôi không biết chuyện gì đã xảy ra với cậu ấy.","@bg:bg_indoor_u","<i>“Mình sợ. Sasha, mình sợ lắm. Mình nghĩ… mình không thuộc về ngôi nhà đó. Mình nghe lỏm được là mẹ mình… mẹ mình còn không ở trong nhà. Cách họ nhìn mình, tất cả đều đáng sợ, và mình không muốn về. Mình không muốn về…”</i>","<i>“Nhưng ở đây chẳng có đồ ăn, chẳng có chỗ ở, chỉ… chỉ có cống ngầm thôi.”</i>","<i>“Mình không quan tâm.”</i>","<i>“Nhưng mà…”</i>","<i>“…Cậu cũng ghét mình à?”</i>","<i>“Cái gì…? Tại sao?”</i>","<i>“Vì mình thích cười?”</i>","<i>“Không… Không. Sao mình lại ghét chứ?”</i>","<i>“Vì mình không nên cười.”</i>","<i>“Nhảm nhí! Eno, cậu nên tiếp tục cười.”</i>","<i>“Thật không?”</i>","<i>“Thật.”</i>","","Nếu hôm đó cậu ấy không về, mọi chuyện có khác không?","Chỉ vì tôi nghĩ chỗ của tôi quá lạnh lẽo, quá bẩn thỉu, mà tôi đã bảo cậu ấy về nhà?","Nếu cậu ấy không về, có phải mọi thứ đã thay đổi?","","<i>“Cậu bị thương! Vết thương trên bụng… Chuyện gì vậy, chuyện gì đã xảy ra?!”</i>","<i>“Sasha… Mình vẫn cười đấy. Cậu thấy không, cậu bảo mình có thể cười, nên mình cứ cười. Mình chưa bao giờ ngừng cười…”</i> Cậu bé mỉm cười, máu rỉ ra nơi khóe miệng. <i>“Sasha, cậu còn muốn nghe mình hát không?”</i>","@bg:bg_cherbefore_1","Sau đó, thỉnh thoảng cậu ấy lại đến thăm tôi.","Và mỗi lần, trên người cậu ấy lại thêm nhiều vết sẹo…","Nhiều thêm nữa.","Tôi nhận ra những lời tôi nói ảnh hưởng đến cậu ấy nhiều thế nào. Nên tôi bắt đầu nói ít đi.","Liệu như vậy có làm mọi chuyện tốt hơn không?","","<i>“Lưng cậu! Lưng cậu…”</i>","Cậu bé không trả lời.","<i>“…Có đau không?”</i>","Không có tiếng trả lời.","<i>“Chuyện này không thể tiếp diễn được. Kẻ khốn nào đã làm chuyện này?! Tại sao họ lại làm thế với cậu?! Dù là ai… họ cũng phải bị trừng phạt! Dù là thứ gì, nó cũng phải bị phá hủy! Eno, đưa mình đi cùng!”</i>","<i>“…Được thôi.”</i>","<i>“Hả?”</i>","<i>“Mình sẽ làm.”</i>","","Tôi không biết mình đã nói gì.","Tôi không biết mình còn có thể nói gì nữa không.","Tôi đã làm gì? Tôi đã làm cái quái gì vậy?","Tôi cũng đã đọc nhiều sách, nhưng không cuốn sách nào nói cho tôi biết.","Không có gì nói cho tôi biết cả.","","<i>“Nhìn này. Nhìn đi, Sasha… Cậu bảo cậu muốn phá hủy mọi thứ làm tổn thương mình, đúng không?”</i>","Sasha nhìn. Và cậu bé không nói nổi một lời.","<i>“Đi thôi… Vết thương của cậu…”</i>","<i>“Chúng không quan trọng. Không sao cả. Cậu thấy không, chỉ cần một hơi thở nhẹ… là lành hết. Ổn cả rồi. Ông đó cắt chân mình… rồi chỉ một hơi thở, là lành. Một lão già chém lưng mình. Một cái chạm nhẹ, là ổn. Và tất cả là nhờ cục đá Originium mà mụ đàn bà béo đó tọng vào họng mình!”</i>","<i>“Đủ rồi, Eno. Thật đấy…”</i>","<i>“Mình không hát được nữa, nhưng cậu thấy không, tất cả là nhờ Originium! Mình làm được mọi thứ!”</i>","<i>“Eno!”</i>","<i>“…Cậu không vui. Tại sao? Mình chỉ làm theo lời cậu. Tại sao cậu không vui? Rõ ràng họ đều vui mà. Cứ làm theo lời họ là họ sẽ vui…”</i>","<i>“…Vì cả nhà cậu đều là lũ khốn nạn. Tất cả bọn họ.”</i>","<i>“Đúng vậy! Nên lũ trẻ đã giết họ.”</i>","<i>“…Cái gì?”</i>","<i>“Lũ trẻ Infected chưa bị đuổi khỏi thị trấn… Chúng cũng đánh mình. Chúng cũng làm tổn thương cậu. Giờ, chúng như những quân cờ trên bàn cờ. Những con tốt thật sự của mình. Chỉ cần mình chữa lành vết thương cho chúng, chúng làm theo mọi lệnh của mình. Mình sẽ lấy cả lũ người xấu xí, ghê tởm đó, tất cả bọn họ… Tất cả bọn họ!”</i> Cậu bé dang tay, cười rạng rỡ. <i>“Cậu thấy không, Sasha? Cậu thấy mình đã làm gì không? Ta sẽ thiêu rụi nó trong một ngọn lửa huy hoàng! Tất cả!”</i>","Sasha im lặng rất lâu.","<i>“Sasha, cậu bị sao vậy?”</i>","<i>“Đừng bao giờ làm chuyện như thế nữa.”</i>","<i>“Nhưng mình tưởng cậu nói…”</i>","<i>“Mình không nghĩ mọi chuyện lại thành ra thế này. Eno, hãy làm điều cậu thật sự muốn làm. Không phải thế này. Mình có thể giúp cậu. Cậu không cần làm thế này.”</i>","<i>“Nhưng mình…”</i>","<i>“Đủ rồi! Hãy làm điều cậu thật sự muốn, Eno! Không phải điều cậu bị ép làm. Không phải đổ máu, không phải đau lòng, không phải trả thù! Cậu thậm chí còn không thích mấy thứ này…!”</i>","<i>“…Sasha… Mình… Mình muốn… Hát…”</i> Cậu bé bật khóc. <i>“Ugh…”</i>","","Tôi không làm được gì cả.","Tôi thật vô dụng.","","<i>“Eno…”</i>","<i>“Mình không hát được nữa.”</i>","<i>“Chúng ta sẽ đi cùng nhau. Chúng ta sẽ sống sót.”</i>","<i>“Sống sót? Có gì hay ho đâu?”</i>","<i>“…Chẳng có gì cả. Nhưng ta có thể cùng nhau làm điều đó.”</i>","<i>“Cậu định làm gì?”</i>","<i>“Đây là cục Originium mình lấy trộm từ mỏ, định đem bán lấy ít đồ ăn.”</i>","<i>“Sasha!”</i>","Cậu bé nuốt nó xuống.","<i>“Như vậy, cả hai ta đều là người Infected. Cùng nhau sống sót nhé.”</i>","@bg:bg_indoor_u","Có một giọng nói khác, từ rất lâu về sau. Một người phụ nữ khoác áo choàng, quỳ trước một cậu bé tóc trắng giữa đống tro tàn của một thị trấn.","<i>“Những chuyện như vậy? Ta không quan tâm. Không có lý do nào cho mọi việc ngươi làm. Cuộc sống của ngươi trên hành tinh này không có ý nghĩa gì. Không, ngươi không cần ai cứu cả…”</i>","<i>“Chọn một cái tên ngươi thích đi. …Cái này à? Tốt. Mephisto… Mephisto. Từ giờ, ngươi là Mephisto. Ngươi không còn là thứ ngươi từng là nữa.”</i>","<i>“Ta không tin ngươi. Ta không có quyền tin ngươi. Người duy nhất ngươi có thể tin là chính mình. Những gì ngươi đã làm không thể xóa bỏ. Ngươi sẽ luôn mang quá khứ của mình, dù ngươi có quên, dù ngươi không hiểu mình đã làm gì. Mọi điều ngươi làm, mọi điều ngươi trải qua, sẽ trở thành củi đốt của ngươi. Chúng thúc ép ngươi, giữ cho ngọn lửa trong ngươi cháy mãi… Cho đến khi cả mặt đất được tự do, cho đến khi ngươi vứt bỏ mọi thứ người khác đã trao cho ngươi, cho đến khi ngươi cuối cùng hiểu được chính mình. Đến lúc đó, ngươi thậm chí có thể vứt bỏ cái tên. Ở hay đi, sống hay chết là lựa chọn của ngươi.”</i>","<i>“Mephisto, ta không thể thay đổi lý tưởng của ngươi. Nếu ngươi không có, hãy đi tìm. Chúng ta sẽ tự giúp mình.”</i>","<i>“Ta là ai? Điều đó không quan trọng. Ngươi nên gọi ta là gì?”</i> Người phụ nữ mỉm cười. <i>“…Talulah. Ta là một kẻ nổi loạn, một người phụ nữ bình thường. Ta chẳng là ai cả. Nhưng giờ, ngươi có thể gọi ta là Talulah.”</i>","","Và Talulah không nói nhiều với tôi.","Cô ấy ôm chặt tôi và vỗ ba lần lên lưng tôi.","Talulah tin tôi. Yelena, Buldrokkas’tee, Lyudmila. Tất cả họ đều tin tôi.","Tôi đã nghĩ mình có thể bỏ lại tuổi thơ ở thành phố đó sau lưng.","Chỉ có điều, mọi thứ thay đổi rất nhanh. Bắt đầu từ chuyện xảy ra ở ngôi làng đó.","Đó là một bi kịch. Nhưng tại sao bi kịch đó lại khiến cô ấy thành ra như vậy?","Tại sao mọi chuyện lại thành ra thế này?","","<i>“Tôi sẽ làm bất cứ điều gì cô muốn…”</i>","<i>“Không cần,”</i> Talulah nói. <i>“Cứ làm tùy ý ngươi. Ta cho phép. Dù sao ngươi cũng là Mephisto.”</i>","<i>“Nhưng trước đây cô đã nói…”</i>","<i>“Đó là chuyện nhiều năm trước rồi. Một vài điều thay đổi trong suốt một sự nghiệp là lẽ đương nhiên. Nếu không theo kịp thời thế, chúng ta sẽ diệt vong. Vì vậy chúng ta, và các đồng bào Infected của chúng ta, phải chiến đấu vì tương lai chung. Bất kỳ ai cũng có thể bị hy sinh vì lý tưởng ấy.”</i>","<i>“Tôi có thể tin cô, phải không?”</i>","<i>“Phải. Vì ta là Talulah.”</i>","<i>“Vậy thì tôi sẽ tin!”</i>","<i>“Ngươi sẽ làm được, ta chắc chắn ngươi sẽ làm được. Chúng ta không thể làm được nếu thiếu ngươi. Ngươi có thể làm mọi thứ, và đạt được mọi thứ.”</i>","@bg:bg_windows","<i>“Vào đi.”</i>","Faust bước vào căn lều. Talulah ngồi sau chiếc bàn, ánh đèn dầu hắt lên gương mặt cô ta.","<i>“Ngươi hẳn đã thấy hết rồi.”</i>","<i>“Cô là ai?”</i>","<i>“Ta là Talulah, đương nhiên.”</i>","<i>“Talulah mà tôi biết… không phải là cô.”</i>","<i>“Talulah chỉ là một cái tên. Talulah chỉ là Talulah. Giúp cậu ta. Mephisto cần sự giúp đỡ của ngươi. Mephisto cần ngươi cho cậu ta giá trị. Cậu ta chỉ tin ngươi và ta.”</i>","<i>“Talulah sẽ không bao giờ làm vậy. Cô đang lợi dụng lòng tin của anh ấy dành cho cô!”</i>","<i>“Không ai trong chúng ta có quyền lựa chọn. Ngươi sẽ làm vì cậu ta. Mọi thứ. Hay ngươi muốn nhìn cậu ta chết?”</i>","","<i>“Anh không nhận ra chuyện gì đã xảy ra sao?”</i> Faust nói. <i>“Sau khi đi qua ngôi làng đó, Talulah đã thay đổi hoàn toàn! Cô ấy không còn là người trước kia nữa!”</i>","<i>“Tôi biết,”</i> Mephisto nói.","<i>“Vậy tại sao anh còn làm thế?”</i>","<i>“Tôi không tin ai ngoài cậu và cô ấy. Và tôi không muốn lựa chọn.”</i>","Faust im lặng.","<i>“Faust, chúng ta đang đi đâu?”</i>","<i>“…Tôi…”</i>","<i>“Faust, nói cho tôi biết. Chúng ta nên làm gì?”</i>","<i>“…Chúng ta sống sót.”</i>","<i>“Sống chẳng phải đau đớn lắm sao?”</i>","<i>“Đau đớn. Nhưng ta có thể cùng nhau làm điều đó.”</i>","","Cuốn sách này, là một cuốn sách về lý tưởng.","Lý tưởng của tôi là…"],"bg":"bg_cherbefore_1","cast":[["Eno","npc:avg_npc_084"],["Sasha","npc:avg_npc_085"],["Talulah","npc:avg_npc_078"],["Faust","npc:char_1508_Faust_1"],["Mephisto","npc:char_1507_Mephisto_1"]]},{"c":"6-7","t":"Dây cung đứt","p":["“GreyThroat! Vị trí của chị?”","“Amiya, tôi đang hỗ trợ một đội L.G.D.”","“Bọn mình sắp giao chiến!” Amiya hít một hơi, rồi nói vào kênh chung, giọng vang và rõ. “Tất cả operator tinh nhuệ chú ý: đây có thể là trận chiến quy mô lớn đầu tiên, cuối cùng và duy nhất của chúng ta ở Lungmen. Mọi người lấy mục tiêu một làm nhiệm vụ chính. Em và đội của em sẽ tập trung giao chiến với chỉ huy địch. Em muốn mọi người nhớ: ưu tiên hàng đầu là hoàn thành các điều khoản trong hợp đồng, tức là cùng L.G.D. đảm bảo an ninh cho Lungmen. Nhưng sứ mệnh của Rhodes Island trong trận chiến này là giảm bớt va chạm giữa người Infected và người không nhiễm bệnh, ngăn chặn xung đột!”","“Chúng ta là Rhodes Island! Bất kể ta mang gì theo vào trận chiến! Bất kể khi nào, bất kể ở đâu! Và đương nhiên, nếu bất cứ lúc nào hành động của chúng ta vượt ra ngoài chuẩn mực, chúng ta sẽ dừng lại ngay lập tức! Vì vậy, chúng ta bước vào trận chiến với gánh nặng trách nhiệm trên vai.”","Trên một mái nhà, Blaze nghe hết bài diễn văn, rồi bật cười khẽ. “Câu đó là nói cho tôi nghe đấy, nhỉ? Con bé lo xa quá…”","“Ta nên nhanh lên, không thì không kịp mất.”","“Người thấy lũ Infected lúc nãy lì thế nào rồi đấy. Một operator, thậm chí một đội cũng khó lòng đối phó. Lẽ ra tôi nên cho thằng nhóc đó ngủ luôn trên sân thượng.”","Bộ đàm của Blaze rè rè. “Nếu chị không đến điểm phục kích ngay, em sẽ lấy hết biên bản kỷ luật năm ngoái nộp cho bác sĩ Kal’tsit đấy!”","Blaze đứng hình. “…Bình tĩnh! Tôi sẽ đến đúng giờ!”","“Amiya! Cô ấy đang cào áo tôi!” Doctor kêu lên.","“Blaze!”","“Tôi phải làm sao? Ta phải nhanh lên mà…” Blaze lườm Doctor. <i>(Người sẽ phải trả giá cho câu đó!)</i>","“Sao Doctor im lặng vậy?” Amiya hỏi. “…Blaze!”","“Tôi có làm gì đâu! Là Doctor tự im đấy! Nói với con bé đi! Nào, nói gì đó đi…!”","“Hả…? Xin lỗi, Doctor. Em quên mất Doctor với Blaze chắc chắn sẽ thế này…”","“Tôi làm những gì phải làm.”","“Sao chị lại có vẻ đắc ý thế?” Amiya thở dài. “Dù sao, em chỉ cần vị trí và nhiệm vụ hiện tại của hai người thôi. Có vẻ hai người hợp nhau nhỉ.”","“Hợp lắm!”","“…Thật không?”","Blaze im lặng. <i>(Khoan, chuyện gì đang xảy ra vậy? Tôi nên nói gì với con bé?)</i>","Doctor nhún vai. <i>(Tôi không biết.)</i>","<i>(Không xong rồi! Báo động đỏ! Tôi đang chịu sát thương tinh thần! Tôi cần chỉ dẫn!)</i>","“Cứ tiếp tục nhé,” Amiya nói.","Tút.","“Con bé cúp máy rồi!” Blaze kêu lên. “Ôi không. Ta gặp rắc rối rồi. Nhưng ít ra ta cũng đến nơi rồi. Nghỉ chân chút đi.”","“Nhưng đây là điểm cao nhất của quận mà?”","“Ờ… chết thật.” Blaze nhìn xuống. “Người biết người ta hay nói đấy, khoảng cách ngắn nhất giữa hai điểm là đường thẳng. Nhảy xuống thôi.”","“Nhảy? Từ cao thế này?”","“Ừ. Ngáp.” Rồi cô khựng lại, nheo mắt. “Khoan… Nếu tôi không nhầm… Kia là đội của Mephisto ở phía đông, đang tiến vào khu phục kích. Còn đằng kia… thằng nhóc có vảy? Nó đang dẫn đội đi đánh thứ gì đó. Cái mảng đen kia là gì vậy? Là đàn chiên sao…? Với số lượng đó?!”","Cô quay lại. “Có vẻ ta không nghỉ được rồi, Doctor. Đi thôi. Đến lúc quyết chiến rồi! Này, Amiya. Này! Tôi đưa Doctor vào trận đây!”","","“Cô đang nghĩ gì vậy?” Swire hỏi.","Ch’en im lặng một lúc. “Ta thả một toán Reunion nhỏ đi, rồi theo dấu chúng vào khu ổ chuột.”","“Chẳng phải cô định để việc đó cho lực lượng đặc nhiệm sao?”","“Chẳng có lý do gì ta không nhân cơ hội. Tôi đã tìm hiểu tình hình một lần rồi, có một điều rõ ràng: chừng nào ta còn ở đó, lực lượng đặc nhiệm không thể hành động công khai. Một khi giao tranh dừng lại, họ sẽ không làm được gì nhiều.”","“Cô không lo lệnh từ cấp trên à?”","“Ai sẽ đứng ra chịu trách nhiệm cho đội?”","“Được rồi, vậy cô tính hết rồi. Khu ổ chuột đang có chuyện gì?”","“Người cung cấp tin của tôi đã làm việc. Có vài khu tôi chưa liên lạc được, nhưng ta có nhiều thông tin hơn bất kỳ ai.”","“Đây là một canh bạc lớn. Nhưng tôi đoán ta không có lựa chọn.”","“L.G.D. là nhóm duy nhất đủ sức đối mặt lực lượng đặc nhiệm.” Ch’en bấm bộ đàm. “Amiya, nghe rõ không?”","“Sĩ quan Ch’en, bọn em đã vào vị trí!”","“…Ừm.” Ch’en ngừng lại một nhịp. “Tôi cần xin lỗi về toàn bộ chuyện Reunion gom người Infected. Chuyện đó đã không xảy ra nếu chúng tôi chu đáo hơn.”","“…Nhờ L.G.D. hành động nhanh ở khu ổ chuột mà Lungmen mới lên được kế hoạch chống Reunion,” Amiya nói. “Về mặt chiến lược, em nghĩ cô không có lỗi, sĩ quan Ch’en. Nhưng về mặt cá nhân…” Giọng cô bé chậm lại. “Sĩ quan Ch’en, chị Misha đã chết.”","Ch’en im lặng.","“Và em không thể chấp nhận quan điểm của cô về người Infected. Ngay cả cô cũng biết… Những người Lungmen yêu thành phố của mình sẽ chiến đấu vì nó, bất kể họ là ai.”","“Ồ, cô thỏ con này đỉnh thật,” Swire nói.","“Em vừa nghe thấy chị Swire à?”","“Đừng để ý cô ta,” Ch’en nói.","“Này!”","“Tôi đồng ý với em, Amiya. Chiến đấu vì Lungmen có thể đoàn kết người dân… trừ những kẻ dính líu đến Reunion. Nhưng thật sự sống ở Lungmen lại là chuyện khác. Thời gian không giải quyết được mọi thứ.”","“Đương nhiên. Chúng ta phải tự giải quyết mọi thứ.”","“Mơ mộng hão huyền. Người Infected và người không nhiễm bệnh sống ở hai thế giới khác nhau.”","“Không phải mơ mộng hão huyền, sĩ quan Ch’en. Mà là nghĩ về chị Misha, và vô số người Infected khác đã chết giống như chị ấy. Chính khoảng cách giữa hai thế giới đó đã giết họ. Chúng ta sẽ để sự chia rẽ đó định nghĩa chúng ta sao? Chúng ta sẽ không chiến đấu để thu hẹp nó sao?”","Ch’en không trả lời.","“Em mong cô có thể hiểu, sĩ quan Ch’en, vì sao người Infected và người không nhiễm bệnh của Rhodes Island cùng nhau chiến đấu vì Lungmen.” Amiya ngừng lại. “Chúng đến rồi, sĩ quan Ch’en.”","“Chuẩn bị chiến đấu.”","@bg:bg_indoor_n","“Phục kích! L.G.D. đang dồn ta vào!” một Nỏ Thủ Bóng Ma hét.","“Đẩy vào khu ổ chuột,” Faust nói. “Dù chưa có tin từ Crownslayer… khu ổ chuột là lối thoát duy nhất. Đưa anh ta đi.”","“Còn anh định làm gì?”","“Tôi và vài đội đã dụ ‘đàn chiên’ tập trung ở đây. Chúng sẽ không tấn công tôi, nên tôi có thể chiến đấu cùng chúng.”","“Bắn!” L.G.D. hét.","“Ta không trụ được lâu!”","“Ugh… Guhhh!!”","“Là lũ người Infected đặc biệt! Cẩn thận!”","“Anh sẽ đi đoạn hậu?” Người Nỏ Thủ nhìn Faust. Rồi giọng anh ta trầm xuống. “Anh sẽ không quay lại.”","Faust không trả lời.","Giữa hai người Nỏ Thủ, Mephisto bị trói chặt, miệng bị bịt kín, vùng vẫy điên cuồng. “Mmm! Mmhhh!!”","“Để anh ta nói,” Faust nói. “Như vậy anh ta không dùng Arts được.”","Miếng vải được kéo ra. “Cậu làm gì vậy?!” Mephisto hét. “Cậu làm gì vậy?! Cậu không được làm thế này! Quay lại! Làm ơn! Quay lại đây!”","“Mephisto…” Faust nhìn cậu ta. “Anh từng nói với tôi anh sẽ làm bất cứ điều gì tôi bảo.”","“Sasha!”","“Anh nói anh không muốn tự mình quyết định. Chỉ là, nếu giờ anh đã có ý tưởng riêng và mục tiêu riêng… tôi không thể trách anh vì những lựa chọn của mình. Nếu là vậy, Mephisto… Thế cũng tốt.” Anh ngừng lại. “Nhưng… Tôi hết lựa chọn rồi. Nên để tôi nói điều ước cuối cùng của tôi.”","“Sasha…? Cậu nói gì vậy? Tôi không hiểu!”","“Đừng để chúng thoát! Hạ chỉ huy của chúng!” L.G.D. hét.","Ở một mái nhà gần đó, GreyThroat giương nỏ, rồi khựng lại khi nhận ra bóng người trong ống ngắm. “Ah…!”","Faust ngẩng lên. Ánh mắt anh gặp ánh mắt cô qua khoảng cách hàng chục mét. <i>…Con én của Rhodes Island?</i>","Anh mấp máy môi, không thành tiếng. <i>Bóp cò đi.</i>","“Nằm xuống! Cẩn thận đạn lạc! Ta đã bao vây chúng!”","GreyThroat đứng im, ngón tay run trên cò.","“Lùi lại, nỏ thủ Rhodes Island! Hành lang này là của chúng tôi!”","“Faust! Chạy đi!” Người Nỏ Thủ hét.","“Không.” Faust quay lại. “Các nỏ thủ, tôi biết FrostNova đang trên đường đến. Và dù Crownslayer mất tích, người của cô ta vẫn ở đâu đó trong khu ổ chuột. Khi FrostNova đến, các cậu chịu sự chỉ huy của cô ấy. Tôi tin cô ấy. Một khi cô ấy đến, các cậu sẽ ổn thôi. Và với Originium Arts của tôi, các cậu sẽ trở nên vô hình.”","“Anh không được, Faust! Như vậy nội tạng của anh sẽ vỡ nát!”","“Không sao. Chẳng còn lý do gì để không làm nữa. Rút lui. Đó là mệnh lệnh. Và đưa anh ta đi cùng. Nhưng không phải về Chernobog.”","“…Faust…”","“Cậu không được làm thế này!” Mephisto gào lên.","Faust bước đến trước mặt cậu ta. Anh nhìn gương mặt ấy rất lâu, gương mặt mà anh đã nhìn từ khi cả hai còn là những đứa trẻ trong cống ngầm.","“…Tôi mong anh sống sót. Kể cả khi chỉ có một mình. Đừng chết.” Anh mỉm cười, lần đầu tiên sau rất nhiều năm. “—Đó là điều ước cuối cùng của tôi.”","“Sasha! Sashaaaaa!!!”","Những Nỏ Thủ Bóng Ma kéo Mephisto đi. Và theo từng bước chân của họ, bóng dáng họ mờ dần, mờ dần, cho đến khi tan hẳn vào không khí.","Faust đứng một mình giữa con hẻm, máu bắt đầu rỉ ra từ khóe miệng.","“Tôi không muốn làm hại ai. Tôi không muốn khiến ai bị tổn thương. Giá mà hồi đó chúng ta cứ chạy trốn đi. Chúng ta đã có thể… chỉ cần chạy trốn đi.”","Từ rất xa, giọng Mephisto vẫn vọng lại, vỡ vụn.","“Sasha, cậu đã hứa! Chúng ta đã hứa với nhau! Chúng ta đã thề sẽ cùng nhau sống sót!”","“Muộn rồi… với tôi…” Faust nhắm mắt lại. “…Tôi mệt quá rồi.”","“Sashaaaaaa!!!”","“Tạm biệt, Eno.”","Anh lắp một mũi tên vào nỏ, và lên dây.","Anh ngắm, lần cuối cùng.","","@cg:avg_6_13","“…Anh ta ngừng khóc rồi,” một Nỏ Thủ Bóng Ma nói khẽ.","Mephisto ngồi bất động giữa họ, đôi mắt trống rỗng nhìn vào khoảng không.","“Mắt anh ta… như người chết não vậy.”","“Tôi chẳng quan tâm đến anh ta,” một thành viên Reunion nói. “Tôi nhớ Faust. Anh ấy đã cứu mạng tôi. Anh ấy là một chỉ huy tốt.”","“Faust giao Mephisto cho bọn tôi… Đó là mệnh lệnh cuối cùng của anh ấy. Bọn tôi sẽ thực hiện nó.”","“Không phải việc của tôi.”","“Ra khỏi thành phố cùng bọn tôi, cậu sẽ có cơ hội sống sót cao hơn.”","“…Được. Đi thôi. Các cậu đưa anh ta đi đâu?”","“Faust nói anh ấy không muốn bọn tôi đưa anh ta về Chernobog… Vậy anh ta có thể đi đâu?”","“Các cậu ở với Faust bao lâu rồi?”","“Ừm… Lúc đầu thì phải nói là anh ấy ở với bọn tôi. Bốn năm năm trước, Faust chẳng biết dùng chiến thuật gì, bắn nỏ cũng không ra hồn. Bọn tôi dạy anh ấy tất cả. Anh ấy học chăm chỉ, tập luyện còn chăm hơn, so tài với Yeti, đấu tập với người của Patriot, và ngày càng mạnh hơn… Cả Patriot và FrostNova đều dạy anh ấy. Anh ấy trở thành thủ lĩnh của bọn tôi, dù bọn tôi chẳng mấy khi gọi anh ấy như thế, nhưng anh ấy là vậy.”","“Các cậu may mắn đấy.”","“Dù Mephisto có trở nên thế nào, Faust chưa bao giờ bắt bọn tôi làm gì cả.” Người Nỏ Thủ quay lại, nhìn về phía con hẻm xa xa nơi họ đã bỏ lại người chỉ huy của mình. “Các nỏ thủ, đừng tiết kiệm tên nổ.”","“Những mũi tên đó chẳng phải sẽ có ích khi đánh L.G.D. sao?”","“Faust luôn nhất quyết phải tôn vinh người chết như thế này. ‘Thể hiện sự tôn trọng không bao giờ là lãng phí.’”","Họ giương nỏ lên trời. Và những mũi tên nổ bay vút lên, nở tung thành những đóa hoa lửa trên nền trời Lungmen.","@bg:bg_outcity_1","“GreyThroat?” Amiya bước tới.","GreyThroat đứng trước một thân hình nằm bất động giữa con hẻm, cây nỏ khổng lồ vẫn nằm cạnh tay anh.","“Anh ta…”","“Nếu em nhớ không nhầm, anh ta là nỏ thủ đi cùng Mephisto, và là một trong những chỉ huy của Reunion.” Amiya nhìn cô gái. “…Chị biết anh ta à?”","“Tôi không biết. Tôi không chắc có thể nói là chúng tôi… quen nhau không.”","“Có vẻ Rhodes Island chẳng làm được gì nhiều,” Doctor nói khẽ.","“Vâng,” Amiya nói. “Rhodes Island là như vậy đấy… phần lớn thời gian. Nhưng dù chỉ làm được một chút xíu thôi, bọn mình cũng sẽ làm. Bọn mình phải làm.” Cô bé nhìn Doctor. “Doctor đang nghĩ gì vậy? Đang nghĩ về… tất cả những cái chết bọn mình đã thấy sao? Em không đoán được. Và em không muốn lấy nó từ tâm trí Doctor. Vì… em nghĩ một ngày nào đó Doctor sẽ tự kể với em.”","Cô bé quay lại nhìn thân hình nằm đó. “Các operator đã cố gắng hết sức. Nhưng cái chết để lại ấn tượng nặng nề, nặng hơn việc cứu được ai đó. Mỗi lần chứng kiến cái chết như thế, nó lại đánh rất mạnh. Chỉ cần nhớ rằng nếu không có nỗ lực của các operator, chúng ta sẽ thấy nhiều cái chết hơn thế này rất nhiều. Nhiều hơn rất nhiều…”","“Tôi từng nghĩ Rhodes Island chiến đấu vì người Infected,” GreyThroat nói. “Nhưng giờ tôi thấy tất cả những người chết dưới chân chúng ta, họ đều là người Infected. Amiya… Rhodes Island chiến đấu vì điều gì?”","“Giờ mới hỏi à?” Blaze bước tới.","“Blaze.”","“…Trả lời cô ấy đi.”","Amiya im lặng một lúc. “Thật lòng, em cũng tự hỏi mình câu đó suốt. Ngày nào bọn mình cũng thấy người chết, cả người Infected lẫn người không nhiễm bệnh. Bọn mình không, và không nên chiến đấu để ngăn mọi cái chết. Điều đó vô nghĩa trong bức tranh lớn. Như bây giờ… như trong trận chiến trước mắt. Không phải một mũi tên, một Arts, một vụ nổ hay một vết thương gây ra tất cả những cái chết này. Thứ bọn mình chiến đấu để đánh bại là cội nguồn của tất cả… lòng căm ghét mà người không nhiễm bệnh dành cho người Infected, và ngược lại, là lý do họ giết nhau. Bọn mình phải xới tung mảnh đất nuôi dưỡng thù hận. Bằng thuốc men của chúng ta, và bằng các chiến dịch của chúng ta.”","Trên bầu trời, những đóa hoa lửa vẫn đang nở.","“A—” Blaze ngẩng lên. “Reunion bắn đấy à?”","“Đó là tên nỏ được tăng cường Originium,” Amiya nói.","“Pháo hoa tệ thật.” Blaze nhìn xuống thân hình nằm dưới đất. “Nearl nói, hồi ở Chernobog, thằng nhóc có vảy này mạnh lắm. Cô ấy bảo hai tay suýt gãy. Và nói từ kinh nghiệm của tôi, tôi thì không bẻ gãy được tay cô ấy đâu. Nhưng lúc nãy, tôi biết dây nỏ của nó gần như đã đứt rồi, và vũ khí của nó cũng chẳng còn bao nhiêu Arts.” Giọng cô trầm xuống. “Mày bị sao vậy, thằng nhóc chết tiệt?”","“Em nghĩ… có lẽ… anh ấy không còn lý do gì để chiến đấu nữa.”","“Này, Amiya, liệu có khả năng nó đã dùng Arts gì đó để sống sót khỏi đòn tấn công không?”","“…Em xin lỗi.”","“Em xin lỗi cái gì? Chị chỉ thấy tội cho thằng nhóc. Nhìn nó là chị biết nó không phải người xấu.”","“Giờ thì đã quá muộn cho những chuyện đó rồi,” GreyThroat nói.","“Không, chưa đâu,” Amiya nói. “Bi kịch của quá khứ kéo dài đến hiện tại… Và chúng ta vẫn còn cơ hội ngăn chặn bi kịch của tương lai.”","GreyThroat im lặng một lúc. Rồi cô cúi xuống. “…Tôi sẽ lấy cây nỏ của anh ấy.”","“Cô ta vừa ngộ ra điều gì à?” Blaze thì thầm.","“Chị không biết chị ấy đã trải qua những gì sao?” Amiya hỏi.","“Cô ta chưa bao giờ kể. Bọn tôi không thân.”","“Bố mẹ chị ấy là nhà nghiên cứu Oripathy, làm việc vì người Infected. Họ chết trong một cuộc xung đột giữa người Infected và cảnh sát. Chị ấy chỉ nghĩ rằng nỗi đau của chị ấy và của bọn mình là như nhau. GreyThroat nhạy cảm hơn chị nghĩ đấy. Chỉ là chị ấy không bày tỏ thôi.”","“Cô ta không nói thì sao tôi biết được?”","","GreyThroat quỳ bên cạnh Faust, nhặt cây nỏ lên. Nó nặng hơn cô tưởng.","“Anh ta là bạn cô à?” Một giọng nói vang lên sau lưng cô.","“…Tôi không biết.” GreyThroat không quay lại. “Cô là ai?”","“Có cần tôi tự giới thiệu không?”","“Không, cảm ơn.”","“Kết bạn với người Infected nguy hiểm lắm.”","“Tôi không quan tâm bạn mình có bệnh hay không.”","“Ồ…? Tôi xin chia buồn.”","“Tại sao cô hỏi tôi câu đó?”","“Vì tôi lo cô đang kết bạn với người Infected.”","Khi GreyThroat quay lại, con hẻm đã trống không.","","“Có cuộc gọi cho em, Amiya,” Blaze nói.","“Amiya đây. Gavial? Chị đang ở đâu? Dưới khu ổ chuột? Có một đường hầm? Bằng cách nào?” Amiya im lặng nghe. “…Áo mưa đen, và… Biệt đội Yeti? Họ đang hội quân với Reunion trong khu ổ chuột sao?”","Blaze nhìn về phía khu ổ chuột, nơi khói đen đang bốc lên từ nhiều chỗ.","“…Điều tồi tệ nhất vẫn còn ở phía trước.”"],"bg":"bg_outcity_1","cast":[["Amiya","op:char_002_amiya"],["Blaze","npc:char_017_homura_3"],["Faust","npc:char_1508_Faust_1"],["GreyThroat","op:char_367_swllow"],["Ch'en","op:char_010_chen"],["Mephisto","npc:char_1507_Mephisto_1"],["Swire","op:char_308_swire"]]},{"c":"6-8","t":"Từ trên trời rơi xuống","p":["<i>9:00 sáng. Nhiều mây.</i><br><i>14 giờ trước cuộc tấn công Trụ sở L.G.D.</i><br><i>“Bad Guy”, cách “Quận 14” của Chernobog 300 m phía trên.</i><br><i>Mục tiêu nhiệm vụ: Hội quân với Rhodes Island, giải cứu đội trinh sát.</i><br><i>Lực lượng được giao: “Bad Guy” và phi công; operator tinh nhuệ Blaze của Rhodes Island và đội của cô. 14 người.</i>","@cg:avg_6_14","“Đến trạm của cô rồi đấy. Amiya và người của cô ấy ở ngay gần đây!” Viên phi công hét qua tiếng cánh quạt. “Thả cả đội bên ngoài thành phố thật sự ổn chứ? Cô định một mình xuống đó à?!”","“Thôi nào, để họ ở ngoài mở đường và đẩy lùi quân truy đuổi của Reunion tốt hơn nhiều so với đánh nhau ở đây,” Blaze nói, đứng ở cửa khoang, gió thổi tung mái tóc trắng.","“Được thôi. Địa hình dưới đó khá hiểm. Tôi chỉ đưa cô đến được đây thôi.”","“Không sao.”","“…Ít nhất để tôi thả dây xuống cho cô chứ?”","“Anh từng thấy tôi dùng dây bao giờ chưa?”","“Cô lại định làm thế nữa à?”","“Làm gì? Anh nói gì vậy?”","“Mỗi lần làm nhiệm vụ cùng nhau, cô lại đi làm mấy trò điên rồ, còn tôi ngồi trong buồng lái thấp thỏm nhìn. Tôi cũng quen rồi, nhưng chuyện đó không thay đổi được việc cô quá liều lĩnh ngoài kia.”","“Thế chỉ chứng tỏ anh, tôi và đội của tôi ăn ý thế nào thôi!”","“Ăn ý cái con khỉ! Lần trước cô san phẳng một thị trấn, cho nổ một hồ chứa nước, và làm sập một khu mỏ! Giữ hỗn loạn dưới mặt đất giùm, đừng mang lên cục cưng của tôi!”","“Rồi, rồi. Tôi hiểu rồi. Mà ‘Bad Guy’ á, thật à? Lần sau đặt tên nghĩ kỹ hơn chút đi.”","“Nhảy đi cho rồi.” Viên phi công nhìn xuống màn hình. “Có vẻ ban tiếp đón đã phát hiện ta. Đến lúc chia tay rồi, Blaze. Tôi sẽ chờ cô ở lối vào phế tích. Nhanh lên!” Rồi bộ đàm rè rè. “Hả? Liên lạc à.”","“A LÔ?!”","“Tôi nghe thấy rồi! Không cần hét!”","“Ồ. Chào các người Rhodes Island. Tôi là người của L.G.D. Tôi đã gặp đội của các anh ở gần phế tích!”","“Chẳng phải L.G.D. rút rồi sao?” Blaze nhíu mày. “Định giở trò gì vậy?”","“Tôi không như con mụ Ch’en đó! Tin tôi đi, tôi giúp được các anh.”","“Vậy chúng tôi nên gọi cô là gì?” phi công hỏi.","“Dùng mật danh của tôi. Gọi tôi là Sĩ quan Swire!”","Một quãng lặng.","“…Chẳng phải Swire chính là tên cô sao?” Viên phi công quay lại. “Blaze, cô lo vụ này được không? Tôi không giỏi đối phó với mấy người quan chức… Blaze?”","“Đừng nhìn tôi.”","“Quay lại đây! Đừng nhảy!”","“Chẳng phải vừa nãy anh bảo tôi nhảy sao? Anh lo được mà. Tôi tin anh! Moa!”","“Moa cái con khỉ!”","","Dưới mặt đất, giữa phế tích thành phố bỏ hoang, đội của Amiya đang co cụm sau một tòa nhà sập.","“Hộc… hộc…” Frostleaf tựa lưng vào tường, môi tím tái.","“…Cô ấy ổn chứ?” Meteorite hỏi.","“Vâng, không nghiêm trọng đâu. Chỉ là thân nhiệt hơi thấp,” Amiya nói.","“Lúc nào nó cũng… thấp. Tôi không sao. Tôi chỉ…”","“Frostleaf, chậm lại. Thân nhiệt chị còn thấp hơn bình thường. Doctor, đưa em cuộn băng.”","“Đây.”","“Đã bảo là tôi không sao mà. Meteorite bị thương nặng hơn nhiều.”","“Không sao. Tôi là Sarkaz. Tôi lo cho cô hơn.”","“Jessica, Biệt đội Yeti đang làm gì?”","“H-họ đang tiến về vị trí ta! Còn khoảng 500 mét!”","“Còn dọn đống đổ nát?”","“Cần thêm khoảng mười lăm phút,” một operator nói. “Tòa nhà sập có kết cấu khá phức tạp, không dám dùng chất nổ ở đây.”","“Meteorite, chuẩn bị chiến đấu. Ta phải giữ phòng tuyến này.”","“Rõ. Còn tên dự trữ không?”","“Còn. Hậu cần có thể lấy cho chị…”","“Amiya, em có đó không?”","Mọi người đứng hình.","“…Ai để bộ đàm mở vậy?” Amiya hỏi.","“Đây là kênh của các operator tinh nhuệ, tôi mở được từ phía tôi.”","“Giọng đó…?” Jessica chớp mắt.","“Ôi không,” Frostleaf rên lên. “Họ cử chị ta đến.”","“Ừm… là ai vậy ạ?”","“Phải, ai vậy? Sao cô ấy hào hứng thế?” Doctor hỏi.","“Người ta gọi chị ta là Blaze,” Frostleaf nói. “Chị ta chắc chắn có thể san phẳng cả khu vực và khiến tất cả mọi người tè ra quần.”","“Chuẩn là tôi đây! Nhưng vế sau hơi sai một chút.”","“Làm ơn… nghiêm túc đi ạ,” Amiya thở dài. “Chị ở đâu vậy, Blaze? Bọn em cần chị hỗ trợ.”","“Tôi đang ở ngay trên đầu em.”","“Cái gì?”","“Còn khoảng 200 mét nữa là tôi đến nơi!”","@bg:bg_cher_11","“Không bắn trúng cỗ máy được, ngoài tầm rồi!” một thành viên Yeti hét.","“Máy bay… chúng có trang bị như vậy sao?”","“Đảm bảo chúng không xuống được,” FrostNova nói. “Tiêu diệt đội Rhodes Island trước khi viện binh của chúng đến. Không được để chúng hội quân.” Rồi cô ta khựng lại, ngẩng lên. “Khoan. —Lùi lại!”","Một bóng người rơi thẳng từ trên trời xuống, đáp xuống giữa quảng trường như một quả bom.","","“Cô ta lại nhảy à?” Meteorite hỏi.","“Cô ta lại nhảy,” Frostleaf đáp.","Amiya im lặng.","“Lần sau mình nhảy cùng nhau nhé, Amiya! Nếu em muốn,” Blaze nói qua bộ đàm.","“Em nghĩ em xin khất. Đội của chị đâu?”","“Tôi để họ ngoài thành phố. Lát nữa họ đến.”","@cg:avg_6_11","“Em không nghe được gì vì tiếng gió cả. Tắt bộ đàm đi!” Amiya quay sang mọi người. “Mọi người… di chuyển hỗ trợ Blaze.” Rồi cô bé quay sang Doctor, hạ giọng. “Doctor, dù chị ấy nói gì… cứ gật đầu là được.”","","“Nó thả thứ gì đó xuống…”","“…Một người?”","“Chỉ có một. Nhưng giữ cảnh giác,” FrostNova nói. “Ta cảm nhận được hơi nóng. Ả đang dùng một loại Arts nhiệt độ.”","“Chào các bạn Reunion,” Blaze nói, đứng dậy giữa hố đất nứt toác, phủi bụi trên áo. “Tôi không thích đánh người Infected khác. Nhưng tôi nghe nói các cậu đã làm hại vài đồng nghiệp Rhodes Island của tôi… Và các cậu vẫn đang đuổi theo bạn bè tôi. Nên tôi buộc phải chấm dứt chuyện đó.”","“Nhiều mồm thật đấy…” FrostNova nói.","“Chào. Khỏe không, cô Băng Giá?” Blaze nổ máy cưa. “Tôi muốn xem chuyện gì xảy ra khi cái nóng của tôi gặp cái lạnh của cô.”","","“Hộc… hộc…” Blaze chống cưa xuống đất, hơi thở bốc khói.","“Blaze!”","“Tôi không sao! Họ… có nghề đấy.” Blaze liếc lại. “Các cậu không bị đông cứng chứ?”","“Nhờ chị mà bọn em ổn. Chị giữ không khí đủ ấm để chặn cái lạnh của cô ấy.”","“Không có gì.” Blaze quay sang FrostNova, người đang đứng cách đó vài chục mét. “Này cô Băng Giá, sao cô không dùng Arts sát thương?”","FrostNova ho một tràng dài, máu nhỏ xuống tuyết.","Blaze nhìn cảnh ấy, và vẻ cợt nhả tắt hẳn. “…Ra là vậy.”","“…FrostNova, chị ấy…” Amiya nói khẽ.","“FrostNova là tên à?”","“Khụ… Giúp ta… yểm hộ…”","“Chị…” một thành viên Yeti lo lắng gọi.","“Ra khỏi đây đi, Amiya,” Blaze nói. “Có thể còn nhiều Reunion đang đến. Có ai bị thương không? Tôi giúp được.”","“Vậy là các ngươi rút lui?” FrostNova hỏi.","“Tôi xin lịch sự đề nghị cô đừng đánh nữa, thỏ tuyết,” Blaze nói. “Cứ dùng Arts như thế, cô sẽ chết đấy. Cô đang đốt mạng sống của mình thành sức mạnh. Hoặc cô có thể đến Rhodes Island. Bọn tôi có cách kéo dài tuổi thọ cho cô.”","“…Đừng nhìn ta như thế… Ta không cần ngươi thương hại.”","“Trông tôi giống đang thương hại cô lắm à? Cô mạnh. Tôi tôn trọng cô.”","FrostNova nhìn cô một lúc lâu. Rồi cô ta lại ho. “Sao các ngươi lại chạy?”","“Doctor, chạy đi. Đừng nhìn cô ta!” Blaze hét.","“Quân Reunion đang áp sát vị trí ta!” Meteorite báo.","“Các ngươi không đi được đâu.” FrostNova giơ tay lên.","“Chị ơi, đừng dùng chiêu đó bây giờ, không phải ở chỗ chị đang đứng!” một thành viên Yeti hét.","“Ta không thể để chúng thoát! Ai biết Rhodes Island sẽ làm gì với người của ta ở Lungmen! Chênh lệch nhiệt độ… đang làm kết cấu… yếu đi! Khụ khụ… đóng băng!”","Cô ta bắt đầu hát. Và đất bắt đầu rung chuyển.","“Có hiệu quả rồi…” một thành viên Yeti thì thào. “Khối Originium ta chôn đã thay đổi kết cấu các tầng dưới, các tấm đế đang nghiêng! Chị, nguy hiểm quá! Bám vào em!”","FrostNova không trả lời.","“Chị?!”","","“…Blaze. Chị nghe thấy không?” Meteorite hỏi.","“Hửm?”","“Có phải tiếng kết cấu đang vỡ không?”","“Ồ…”","“Originium chôn dưới đất… hút nhiệt… chênh lệch nhiệt độ…” Amiya nhìn xuống chân mình. “Nó đang sụp… Arts của FrostNova thật sự làm được chuyện đó sao…?”","“Không!” Blaze hét. “Tấm đế đang cong vênh!”","“Reunion có thể làm được chuyện như thế này sao?”","@cg:avg_6_16","“Tôi chỉ biết là… cả quận đang lún xuống!”","“Chạy! Đến chỗ ổn định! Mặt đất ở đây đang sụp!” Amiya hét.","“…Doctor?” Jessica nhìn xuống. “Doctor, mặt đất dưới chân Doctor… nó đang… nứt ra?”","“Ôi không.” Blaze quay phắt lại. “Doctor, chạy đi!”","“Chạy đâu…?”","“Doctor!” Amiya lao tới.","“Amiya, đứng yên đó! Doctor, bám vào cột đèn kia!”","“Cứu Doctor!”","“Mặt đất nứt nhanh quá! Tôi không với tới được!”","“Vậy để em!”","“Không!”","Một vết nứt khổng lồ mở ra dưới chân Doctor. Mặt đất nghiêng đi, sụp xuống, như miệng một con thú đang há ra.","“Tôi không sao,” Doctor nói, trước khi rơi.","“Doctor!!”","“Các tòa nhà không chịu nổi sức nặng của chính chúng nữa, chúng đang sụp hết!” Meteorite hét.","“Meteorite, giữ con bé!”","“Được, tôi giữ được Amiya rồi!”","“Thả em xuống!” Amiya vùng vẫy.","“Amiya, đi đi. Tôi sẽ đi lấy Doctor! Tôi là operator tinh nhuệ, tôi làm được!”","Amiya ngừng vùng vẫy.","Blaze đứng ở mép vực, nhìn xuống bóng tối sâu hun hút bên dưới. “Ồ, có vẻ chưa xong hẳn nhỉ.” Cô hít một hơi. “Doctor, tôi sẽ dùng luồng khí và áp suất làm chậm cú rơi của người, đẩy tòa nhà bên cạnh ra xa. Đừng lo, nó sẽ không đè lên người đâu! Chỉ cần đừng hoảng! Tôi bắt được người mà!” Cô giơ tay lên, không khí quanh cô bắt đầu cuộn xoáy. “…Hẹn gặp lại!”","Từ trong bóng tối bên dưới, một giọng nói rất khẽ vọng lên.","“Hẹn gặp lại.”","","Khi bụi lắng xuống, Blaze đứng giữa đống đổ nát. Trước mặt cô, một nhóm thành viên Yeti cũng đang đứng nhìn xuống vực.","“Sao? FrostNova đâu?” Blaze hỏi. “Chỉ huy của các cậu cũng rơi xuống đó rồi à?”","“…Phải,” một người đáp. Rồi anh ta quay sang Amiya. “Ta có thể không đánh nhau không? Thỏ của Rhodes Island, ta có thể đình chiến tạm thời không? Thật lòng mà nói, bọn tôi chưa bao giờ muốn đánh các cô lắm.”","“Nhưng…”","“Mephisto nói với chị bọn tôi rằng cô đã giết Alex, và chị ấy rất lo cô sẽ làm gì tiếp theo.”","“…Alex là ai?”","“Skullshatterer.”","Amiya im lặng một lúc. “Em xin lỗi. Em đã giết Skullshatterer.”","“…Ồ.”","“Người Infected thật sự không nên đánh nhau. Em xin lỗi.”","“Xin lỗi gì chứ? Đó là một trận đánh, phải không?”","“Đúng vậy.”","“Vậy thì đình chiến nhé. Nesti, cậu thấy sao?” Một thành viên Yeti to lớn bên cạnh lẩm bẩm gì đó bằng tiếng Ursus, nghe rất giống một câu chửi thề. “Nesti bảo cậu ấy đồng ý.”","“Tôi không nghĩ đó là điều anh ta nói,” Frostleaf nói.","“Chừng nào không đang trong trận đánh, thì chẳng có lý do gì phải giết ai, đúng không?”","“Tại sao… các anh muốn đình chiến?” Amiya hỏi.","“Cô có bao giờ để ý là cả hai phe chúng ta đều do thỏ lãnh đạo không?”","Một quãng lặng dài.","“…Hả?” Blaze nói.","“Tôi nghĩ có gì đó trong não tôi vừa hỏng,” Frostleaf nói.","“Hửm?” Jessica chớp mắt.","“Đây là những yeti của vùng băng giá sao?” Frostleaf lẩm bẩm. “Chẳng phải họ là những sát thủ lạnh lùng, tàn nhẫn sao? Chuyện này không đúng.”","“Đó là định kiến,” một thành viên Yeti nói. “Nghe đây, thỏ con. Ai thắng trận, hay các cô đi đâu, chẳng quan trọng với bọn tôi. Bọn tôi chỉ quan tâm đến mạng sống của chị mình. Và cô cũng đang lo cho bạn mình, đúng không?”","“…Đúng vậy. Bọn em không đến đây để làm hại ai.”","“Cô chắc chắn không đến đây để săn Reunion cho vui, phải không?”","“Đương nhiên là không!”","“Cô biết không… buồn cười thật… Nếu không phải Patriot khăng khăng đòi đoàn kết trong Reunion Movement, bọn tôi đã xử lý Mephisto và người của hắn từ lâu rồi. Như thế cũng hơi giống săn Reunion cho vui nhỉ?”","“Hả…”","“Đào thôi nào, được chứ?”"],"bg":"bg_aircraft","cast":[["Blaze","npc:char_017_homura_3"],["Amiya","op:char_002_amiya"],["FrostNova","npc:char_1505_frstar_1"],["Frostleaf","op:char_193_frostl"],["Meteorite","op:char_219_meteo"],["Jessica","npc:char_259_Jessica_1"]]},{"c":"6-9","t":"Góc nhìn khác","p":["“Xuất phát,” Ch’en nói.","“Nhưng bọn tôi thật sự không quen bố cục ở đây,” một operator L.G.D. ngập ngừng. “Tôi lo… lỡ người Infected chống lại chiến dịch thì sao?”","“Bình tĩnh. Tôi biết khu này. Cứ làm theo lệnh tôi.”","“Rõ, thưa sếp! …Thưa sếp, tin xấu: tình báo báo Reunion lại đang di chuyển có tổ chức. Có vẻ chúng đã tìm được chỉ huy mới. Và… chúng đã mã hóa lại kênh liên lạc. Ta không chặn được nữa!”","“Lẽ nào chúng đã hội quân với các đơn vị trong khu ổ chuột? Không thể. Rhodes Island lẽ ra đã xử lý tình hình ở đó rồi. Không có nguy cơ ta bị kẹp. Lạ thật…”","“Ah Ch’en, tôi sẵn sàng—” Swire chạy tới.","“Có liên lạc?” Ch’en nhìn thiết bị. “‘Cô gái nhỏ’, cô có phiền cho tôi chút riêng tư không?”","“Sao lần nào tôi có việc cho cô là cô lại bận thế?” Swire nheo mắt. “Gián điệp của cô liên lạc lại rồi à?”","“Tôi bảo cho tôi chút riêng tư. Tiện thì mua giùm tôi ít cá viên.”","“Tôi đâu phải trẻ con.” Swire bỏ đi, lầm bầm.","“…Ch’en đây.”","“Lại có thêm một nhóm Reunion lên từ các tầng dưới của khu ổ chuột,” một giọng nói trầm, khàn. “Người Infected gọi là Biệt đội Yeti. Có vẻ họ có khả năng làm sập nhà cửa và phá hủy cơ sở hạ tầng. Cẩn thận.”","“…Đã hiểu. Only-1, lực lượng đặc nhiệm Lungmen đang hoạt động trong khu ổ chuột. Lúc này chúng tôi không thể ngăn họ. Cẩn thận.”","“Rõ.”","“…Only-1, tại sao anh mất liên lạc?”","“Tôi có vài chuyện phải suy nghĩ. Giờ tôi đã rõ rồi. Tôi giao Lungmen lại cho cô.”","“Cái gì? Tôi không hiểu.”","“Tôi, bây giờ ấy à? Tôi không thuộc về nơi này nữa.”","“Only-1!”","“Tôi sẽ đưa một số người Infected của Lungmen đi. L.G.D. không bảo vệ được họ. Thành phố này không quan tâm đến họ. Nói cách khác, thành phố này hoàn toàn không phải như cô nghĩ.”","“Nine! Cô đang chịu mệnh lệnh!”","“Tôi đã không ở L.G.D. hơn ba năm rồi. Và thật ra trước kia chính tôi là người ra lệnh cho cô.”","“Nine…!”","“Lực lượng đặc nhiệm cô nói ấy à? Tôi nghĩ tôi đã thấy họ quanh đây. Tôi đã đánh giá thành phố này quá cao. Tạm biệt, Ch’en.” Một quãng lặng. “À, phải rồi. Đừng đi lục lọi cống ngầm.”","Tút.","Ch’en đứng im rất lâu.","","“Tôi nói to quá à?”","“Cô khá to đấy,” Swire nói, ngồi xổm ở một góc phố bẩn thỉu. “Tôi nghĩ cả dãy phố nghe thấy. Này, Ah Ch’en, lại đây. Ngồi đi.”","“Ồ, cô Swire ngồi xổm ở góc phố bẩn thỉu. Không sợ bẩn quần áo à?”","“Đương nhiên là không! Sao cô nghĩ tôi lo chuyện đó chứ? Tôi vừa định gọi con chuột cống thối tha kia thêm lần nữa. Tôi có thể không hay đến đây, nhưng tôi khá chắc lực lượng đặc nhiệm kia đang làm chuyện mờ ám.”","“Cô gặp Lin chưa? Ở khu ổ chuột ấy?”","“Gặp rồi. Một ông già tốt bụng. Tốt hơn ông nội tôi.”","“Người ta gọi ông ta là ‘Vua Chuột’.”","“Những người đứng sau bức màn không phải ai cũng như vậy. Nhưng ông ấy thật sự là người tốt.” Swire nhìn xuống đôi giày. “Tôi không ngờ Yühsia lại thành ra thế này. Hồi xưa cô ấy nhút nhát rụt rè lắm, kiểu lúc nào cũng nấp sau lưng mình.”","“Tôi không nghĩ cô ấy thay đổi. Cô ấy chỉ… gánh lấy trách nhiệm. Có lẽ là loại trách nhiệm cô ấy không gánh nổi.”","“Nói với cô ấy thế cũng chẳng ích gì. Ta đang kẹt giữa hai làn đạn.”","“Tôi không thể nói là hiểu chuyện giữa cô ấy và bố cô ấy, nhưng tôi biết cô ấy không máu lạnh đến vậy.”","“Nên tôi sẽ gọi cho cô ấy.”","Ch’en im lặng một lúc. “Báo cáo tôi vừa nhận có thể có ích cho ta.”","“Ý cô là sao?”","“Một nhóm Reunion có năng lực đặc biệt đã vào khu ổ chuột, và họ có thể chỉ huy các thành phần Reunion khác. Và chỉ mình tôi biết. Mà giờ thì là hai chúng ta.”","“Cô đang nghĩ gì vậy?”","“Ta lái bọn áo mưa đâm vào họ. Ngoài nhóm ở lại giúp L.G.D. dọn dẹp người Infected kiểu mới, còn khá nhiều lực lượng đặc nhiệm ở cùng ta trong khu ổ chuột. Và tình hình là: ta không biết sự phân bố của họ, không có cách đề phòng, không biết họ sẽ làm gì. Nhưng với sự giúp đỡ của Lin Yühsia, ta có thể dẫn họ vào toán Reunion đó.”","“Ép họ lộ diện? Cho cả L.G.D. thấy?”","“L.G.D., đúng, nhưng cả Rhodes Island nữa.”","“Cô tin họ đến thế à?”","“Họ theo đuổi mục tiêu quyết liệt hơn bất kỳ nhóm nào tôi từng thấy. Còn tận tụy hơn cả L.G.D. Mà ta còn tin ai khác được nữa?”","“Cô gan thật đấy.”","“Người Lungmen bình thường không biết Lin, không biết ông nội cô, thậm chí không thật sự biết Wei Yenwu, chứ đừng nói đến phòng thương mại hay bất cứ ai đứng sau màn. Họ chỉ tin L.G.D. Không ai trong số những người chơi đó dám giải tán L.G.D. và để lại cho ta lực lượng cảnh sát thông thường. Rồi thêm người ngoài vào… Không đời nào họ muốn tiếp quản.”","“Nhưng họ sẽ sa thải cô.”","“Ôi, sợ quá.”","“Vậy làm xong việc cuối cùng này thôi!” Swire đứng dậy. “Lần tới, tuyến tuần tra của họ đi thẳng vào khu ổ chuột.”","“Cô thuyết phục được Lin không?”","“Chừng nào ta còn chăm lo nơi này, Lin sẽ hợp tác với ta.”","“Còn một chuyện nữa…” Ch’en không quay đầu. “Cô có biết ta có ba vị khách không?”","","“…Gì vậy?” Lin Yühsia nhấc máy.","“Nghe đây, chuột thối, tôi có tin cho cô,” Swire nói. “Có một đơn vị Reunion ta không giữ nổi. Ta cần đội của cô giúp.”","“Không thể nào. Cô định giở trò gì?”","“Tôi đã bao giờ nói dối cô chưa?”","“Cô bảo ta sẽ học cùng trường cấp hai, rồi chạy sang Victoria.”","Swire im lặng. “…Tôi xin lỗi. Thật lòng, thật sự xin lỗi.”","“Thôi bỏ đi. Tôi không quan tâm.”","“Yühsia, bố cô đã làm rất nhiều cho Lungmen. Ta không muốn mất nơi này, và người dân ở đây cũng không thể mất ta.”","“Đồ dối trá. Cô sẽ đến đây sao? Cô sẽ đến khu ổ chuột sao?”","Swire ngập ngừng. “…Ch’en sẽ đến.”","“Cô đúng là nói dối dở tệ. Tôi có việc gì với cô ta?”","“Vì lý do nào đó, bố cô chưa giải quyết được mâu thuẫn giữa người Infected và người bình thường, nhưng Ch’en có thể. Ch’en và bố cô sẽ cùng nhau xây lại khu ổ chuột. Họ đang biến nó thành nơi mà đủ loại người đều có thể sống, đến mức ta còn chẳng gọi nó là khu ổ chuột nữa. Nghĩ mà xem… Dù phần lớn người Lungmen không sống ở đây, mấy năm gần đây họ đến đây nhiều lắm, đúng không? Chẳng bao lâu nữa, ta sẽ không cần khu ổ chuột nào cả.”","“Cái gì?”","“Ta chưa giải quyết được khủng hoảng người Infected, nhưng tôi biết… ta có thể biến nơi này tốt đẹp hơn. Chúng sẽ thành các Quận 22 đến 29 của trung tâm Lungmen. Không còn là ‘khu ổ chuột’ nữa. Thành phố này được xây nên từ rất, rất nhiều loại người khác nhau cùng nhau làm nên nó như ngày hôm nay. Lungmen không thể đánh mất ai cả.”","“Ngáp. Chán thật. Cô trở nên nhạt nhẽo như Ch’en rồi.”","“Yühsia…”","“Nghe này, tôi không cố dựng phim truyền hình ở đây đâu.”","Một quãng lặng dài.","“Toán Reunion đó ở đâu?” Lin Yühsia hỏi.","“Ồ?”","“Tôi sẽ không hỏi lại.”","","“Amiya, em vào khu ổ chuột chưa?” Ch’en bấm bộ đàm. “Bên này có chút tình hình. Để tôi kể cho em nghe.”"],"bg":"bg_indoor_n","cast":[["Ch'en","op:char_010_chen"],["Swire","op:char_308_swire"],["Lin Yühsia","npc:avg_npc_036"],["Nine","npc:avg_npc_043_1"]]},{"c":"6-10","t":"Chuông giải phóng","p":["“Hộc… hộc… Ấn tượng thật!” một thành viên Yeti thở dốc.","“Bọn áo mưa đen đang rút! Chạy khi còn kịp!”","“Cảm ơn!” một thành viên Reunion hét.","“Đừng cảm ơn bọn tôi. Nếu còn sức thì chiến đấu cùng bọn tôi đi!”","“Cậu thấy hắn đu từ tầng bốn xuống, sượt qua đầu tôi chưa? Nếu tôi không kịp dùng khối Originium chị FrostNova để trong ba lô đóng băng vũ khí của hắn, tôi đã không đứng đây rồi! Ấn tượng thật. Họ giống y đám kiếm sĩ đeo mặt nạ phòng độc ở Ursus. Thậm chí còn mạnh hơn!”","“Suýt chết mà còn hào hứng gì chứ? Đám kiếm sĩ đeo mặt nạ cậu nói là Cận vệ Hoàng gia Ursus! Lần đó bọn ta chỉ gặp có năm tên thôi! Cậu đếm xem có bao nhiêu áo mưa không?”","“Vậy nghĩa là bọn ta còn đỉnh hơn trước à?”","“Không phải lúc đùa. Kỹ thuật và trang bị của họ có nghĩa là họ phải có cả một thành phố… Thậm chí thợ thủ công của nhiều thành phố cung cấp cho họ. Bọn ta không đời nào tự đẩy lùi họ được. Đừng hòng nghĩ đến chuyện giết họ!”","“Tôi chỉ… tôi chỉ nghĩ là mình làm khá tốt thôi.”","“Vấn đề là tình hình này vượt xa khả năng của bọn ta… Không trụ được lâu đâu!”","“Im lặng!” một người khác ra hiệu.","Từ bóng tối, vài bóng người mang nỏ bước ra. “Báo cáo.”","“Chị, đây là… người của Faust.”","FrostNova ngồi tựa lưng vào tường, áo choàng phủ kín. “Khụ khụ… Ta nhận ra họ.”","@cg:avg_6_17","“FrostNova, bọn tôi nhận được tin nhắn của chị, và…”","“Sao Mephisto lại đi cùng các ngươi? Hắn bị làm sao vậy?”","“Mephisto đã chịu vài… tổn thương tâm lý.”","“Hắn? Bị chấn động tâm lý?” FrostNova nhíu mày. “Khoan, Faust đâu?”","“Faust ở lại để cho bọn tôi, và những người khác, cơ hội trốn thoát. Bọn tôi đã để anh ấy lại bên ngoài khu ổ chuột.”","FrostNova im lặng một lúc lâu. “…Khó mà trở về từ đó. Faust là một chiến binh dũng cảm.”","“FrostNova, nếu được, bọn tôi muốn chiến đấu cùng Yeti.”","“Được. Ta phải đưa những người còn lại ra an toàn. Tìm vị trí bắn tỉa và chờ lệnh. Ta sẽ cần các ngươi yểm trợ trong trận sắp tới. Không biết khi nào địch tấn công lại.” Cô ta quay sang. “Báo vị trí của ta cho mọi đội: Ta sẽ đảm bảo một lối thoát an toàn cho họ từ đây! Tiếp tục sơ tán.”","“Đã hiểu!”","","“Họ có giống lính Ursus, chẳng màng thiệt hại phụ không?” một thành viên Reunion hỏi.","“Tôi không nghĩ vậy. Bọn Ursus sẵn sàng dùng pháo bắn thẳng vào thượng thành!”","“Tôi biết họ tàn bạo. Nhưng tàn bạo đến thế sao?”","“Bọn tôi tận mắt thấy. Đám áo mưa khác hẳn. Họ coi dân thường là mục tiêu, vì họ không phân biệt được người Infected với người không nhiễm bệnh. Họ không biết liệu có phải bọn ta đang cải trang thành dân thường hay không. Bọn Ursus chỉ đơn giản là không quan tâm, nhưng đám này thì không để sót một ai.”","“Người chạy trốn đông quá, gần như không thể giữ trật tự! FrostNova đang khó khăn lắm!”","“Chị sẽ không để ai chết. Reunion hay không cũng vậy. Bọn ta đến Lungmen để chiến đấu. Sao lại thành đi cứu người? Buồn cười thật.”","“Giao tranh gần xong rồi. Nếu các anh không đến, bọn tôi chết hết rồi!”","“Ôi điên thật. Các cậu thật sự trông cậy vào bọn tôi à?”","“Đừng nói kiểu đó được không…? Trước kia tôi nghĩ các anh đáng sợ lắm, giờ thì trông như một đám hề.”","“Cậu hiểu lầm hết rồi. Bọn tôi chỉ ít nói thôi. Đâu có đáng sợ.”","“Dù sao, chẳng phải ta nên cùng nhau giữ chỗ này sao?”","“Cậu hoàn toàn đúng! Người anh em, cùng nhau giữ chỗ này nào!”","","“Chuyện gì vậy?” FrostNova hỏi.","“Bọn em… tìm thấy vài người dân địa phương bị nhốt trong này. Một người mẹ và con gái. Bọn em định dùng chỗ này làm vị trí bắn, nhưng không biết giao tiếp với họ thế nào… Họ có vẻ rất sợ bọn em.”","Trong góc phòng, một người phụ nữ ôm chặt đứa con nhỏ, nói gì đó bằng tiếng Lungmen, giọng run rẩy. Đứa bé khóc thét.","FrostNova bước tới. Cô ta quỳ xuống, giữ một khoảng cách nhỏ.","“Đây là con của cô, phải không?”","“Oaaa!”","“Một đứa trẻ khỏe mạnh quá.” Giọng FrostNova dịu đi, dịu đến mức các thành viên Yeti nhìn nhau. “Đừng sợ. Đừng khóc. Mẹ con đang ở ngay đây. Mẹ ở đây.”","“Oaaa… Mm… Ưm… Mm.” Đứa bé ngừng khóc. Nó nhìn người phụ nữ tóc trắng một lúc, rồi bật cười. “Hehe.”","“Ồ, đứa bé cười rồi…” một thành viên Yeti thì thào.","“Đưa họ ra khỏi đây,” FrostNova nói.","Người mẹ ngập ngừng hỏi gì đó.","“Các ngươi… khụ… hộ tống cô ấy. Đưa cô ấy đến chỗ an toàn.”","“Họ là người không nhiễm bệnh,” một thành viên Yeti nói. “Còn biết bao người của ta cần sơ tán. Ta không có thời gian.”","“Ồ?”","“…Đúng rồi. Giờ ai còn quan tâm là người Infected hay người không nhiễm bệnh nữa chứ. Đã hiểu.” Anh ta quay sang người mẹ, gãi đầu. “Ờ, ừm, thưa cô, ờ… Đi lối nài?”","“Neidei, neidei… hou,” người mẹ nói khẽ.","“FrostNova, chị, chờ bọn em quay lại. Đừng cố gắng giữ một mình.”","“Tin chị của các em một chút đi,” FrostNova nói. Rồi cô ta quay phắt lại. “Nhanh lên! Chúng đến rồi! Chúng đang triển khai vài đơn vị mặc đồng phục khác… Có thể là L.G.D. của Lungmen! Khụ khụ… Đi!”","","“Nhiệt độ đã thấp hết mức có thể!”","“Đám mặc đồng phục không phải đối thủ của ta, nhưng cẩn thận bọn áo mưa!”","“Nesti đâu? Cần thêm hỏa lực. Cần bắn áp chế!”","“Cậu ấy bảo được!”","“Tôi không nghĩ cơ thể chị chịu được lâu nữa. Chị không giữ nhiệt độ thấp được nữa!”","“Ta không phá mặt đường được sao?”","“Không đời nào! Làm vậy thì người của ta và dân địa phương ra lối thoát bằng cách nào?”","“Chắc đây là lối ra duy nhất chứ?”","“Chắc. Các lối khác đều bị phá rồi. Chỉ còn lại lối ta tự đào.”","“Ta còn bao nhiêu thời gian? Hay chị còn bao nhiêu thời gian? Sao lại phải hành hạ chị ấy như thế này?”","“Sắp xong rồi!” một người hét. “Tôi đi đón chị!”","Anh ta chạy về phía FrostNova. “Chị ơi, nhóm này sắp sơ tán xong rồi!”","“Còn trận đánh… thế nào?”","“Bọn em đã áp chế hoàn toàn L.G.D. Địa hình có lợi cho ta, chúng không tận dụng được quân số. Nhưng…”","“Em không cần giấu gì cả.”","“Đội áo mưa của Lungmen chẳng quan tâm địa hình, hay người dân. Họ… họ sẽ san phẳng mọi thứ. Họ đang thanh trừng khu ổ chuột.”","“Còn những người Lungmen không nhiễm bệnh ta thấy lúc nãy…?”","“Em sợ là do họ làm.”","FrostNova im lặng. Rồi cô ta đứng dậy, chậm rãi, như phải dùng hết sức lực mới đứng nổi.","“Chị ơi, dừng Arts lại! Bọn em tự xử lý được đám này. Chị nghỉ chút đi!”","“Khụ khụ…”","“Chị!”","“Nhiệt độ vừa phá vỡ giới hạn dưới!” một thành viên Yeti hét. “Chị ấy làm được rồi…! Kết cấu bên trên đang yếu đi! Đập vỡ chỗ đứng của chúng, đẩy chúng lùi lại! Bắn!”","Những bóng áo mưa bắt đầu rút lui.","“Chúng đang lùi! Tiếp tục!”","“Nhanh hơn! Nữa! Nhanh hơn!”","“R-rõ!”","“Đó là chị của bọn ta! Chị ấy làm được thật rồi!”","Một người phụ nữ trong đội Yeti đứng im, không reo hò cùng mọi người.","“Petrova, sao vậy? Sao trông cậu u ám thế?” Rồi anh ta nhìn theo ánh mắt cô. “…Chị?”","“Young, lại đây,” Petrova nói.","“Không.”","“Lại đây!”","“Tôi không làm được!”","“Cậu phải làm,” Petrova nói, giọng không run. “Chị không còn nhiều thời gian nữa.”"],"bg":"bg_indoor_n","cast":[["FrostNova","npc:char_1505_frstar_1"],["Lungmenite",null],["Child",null],["Petrova","npc:avg_npc_037"]]},{"c":"6-11","t":"“Những lúc như thế này”","p":["Trong một căn nhà đổ nát ở khu ổ chuột, có tiếng một đứa bé khóc.","“Oaaa… Con đói! Bố đâu? Bố đi đâu rồi? Con muốn bố…! Bố ơi! Bố ơiii! Bố sẽ đến đón con!”","GreyThroat dừng lại ở ngưỡng cửa. “…! Một đứa trẻ?” Cô bấm bộ đàm. “Blaze-4, Amiya-1, nghe rõ không. Tôi đang ở khu ổ chuột. Phố 4, nhà số 10. Có một đứa trẻ sống sót, người Infected.”","Cô bước vào, hạ nỏ xuống. “…Chào em.”","“C-chị là ai? Chị là người Lungmen à?”","“Chị sẽ không làm hại em. Chị không nói giỏi tiếng Ursus. Chị không phải kẻ thù.”","“Chị nói gì cơ?”","“Đi với chị. Ở đây nguy hiểm.”","“Em không đi được… Chú bảo em ở yên đây.”","“Nhưng chị sẽ đưa em đi tìm bố.”","“Chị làm được à?”","“Chị làm được.” GreyThroat không quay đầu, nhưng giọng cô thay đổi. “Ngươi, đang nấp sau lưng ta, ra đây.”","Từ sau một tấm ván, vài thành viên Reunion bước ra, vũ khí trong tay.","“Cô… cô không phải người của chúng. Cô… đến từ Rhodes Island à?”","“Em bé, lùi lại. Đừng lại gần.” GreyThroat giương nỏ. “Bỏ vũ khí xuống, giơ tay lên mà ra đây.”","“Cái gì? Cô không đến để cứu bọn tôi à? Người Rhodes Island các cô không biết thứ gì đang ẩn ở đây sao? Bọn tôi đã khó khăn lắm mới dựng được cái bẫy này… Nếu không dụ được chúng vào, nếu không hạ được chúng, chúng sẽ giết hết bọn tôi!”","“Các người dùng trẻ con làm mồi nhử. Các người đáng bị giết.”","“Cô nghĩ bọn tôi chết rồi thì mọi chuyện kết thúc sao? Kể cả chúng giết bọn tôi, chúng cũng sẽ không tha cho lũ trẻ. Chúng sẽ không tha cho ai cả! Nếu chỉ cần thế, bọn tôi sẵn lòng chết để cứu lũ trẻ! Bọn tôi còn chưa tấn công cô!”","“Ai đang giết trẻ con…? Những người mặc áo mưa đen?”","“Cô đã thấy họ rồi, cô hiểu mà! Họ đang tàn sát tất cả mọi người!”","“Đó không phải lý do. Sau khi đưa các người về, tôi sẽ xin cho các người được bảo vệ.”","“Và bọn tôi phải tin cô à? Cái nỏ của cô là công cụ giết người, cô bảo vệ cái gì chứ?”","“Lúc này, tôi đang bảo vệ mạng sống của các người.”","“Thôi đi. Bọn tôi sẽ xử lý cô, rồi dựng lại cái bẫy! Bọn tôi đã nhận lệnh tập hợp và rút lui rồi. Nếu chết ở đây, bọn tôi sẽ làm ô nhục những đồng chí đã chết để cứu con mình!”","“…Em bé, nấp đi!”","Một tiếng nổ. Rồi bóng tối.","","“Hừm…” GreyThroat mở mắt. “Mình vẫn còn sống à?”","“Cô nghĩ chết thì tốt hơn à?”","Blaze ngồi xổm bên cạnh cô, tay đang quấn băng quanh vai cô.","“Operator Blaze?”","“Cô chết thì cũng chẳng giải quyết được gì. Tốt nhất cứ tiếp tục sống đi.”","“Còn… những người Reunion? Và lũ trẻ?”","Blaze im lặng một lúc. “Operator GreyThroat, tôi đã hiểu lầm cô hoàn toàn. Và tôi xin lỗi.”","“Lũ trẻ!”","“Tôi xử lý đám Reunion rồi! Tôi giấu lũ trẻ rồi! Nghe tôi nói đã!”","“Không cần… miễn là lũ trẻ an toàn.”","“Cô có thể đừng phiền phức trong năm phút được không?”","“Cô hiểu lầm tôi điều gì?”","“Tôi thấy cô đứng lên chiến đấu vì lũ trẻ Infected. Ngầu vãi leng noi.”","“Tiếng địa phương Lungmen của cô dở tệ.”","“Này, đó là tôi buột miệng thôi! Nhưng thật đấy, tôi cứ nghĩ cô chỉ là một cô gái không nhiễm bệnh vô tâm, gia nhập Rhodes Island để do thám bọn tôi hay gì đó. Tôi đã hiểu lầm cô hoàn toàn.”","“Nếu tôi là gián điệp, thì đây là cách tôi khiến cô tin tôi. Miễn là cô không ngu đến mức để tôi chảy máu đến chết…” GreyThroat nhìn xuống vai mình. “Cô băng bó cho tôi à?”","“Tôi vẫn là operator tinh nhuệ. Đó là việc của tôi. Mà, cô nói đúng. Nhưng kể cả cô là gián điệp, cô vẫn làm đúng. Nên tôi sẽ cứu mạng con gián điệp này, rồi đưa cô ta sang phòng Pháp chế.”","“Tôi có thể chạy mà.”","“Đừng ngốc thế. Cô chạy nhanh hơn tôi kiểu gì?” Blaze ngồi phịch xuống bên cạnh cô. “Tin tưởng không có nghĩa là mất cảnh giác. Tin tưởng là biết cô sẽ làm gì và không làm gì. Nếu cô làm đúng, tôi sẽ ủng hộ cô. Nếu cô làm sai, tôi sẽ sửa, hoặc ngăn lại nếu cần. Đó là tin tưởng. Cảm ơn, GreyThroat. Cô đã tin tôi, và đã sửa những suy nghĩ sai của tôi bằng những hành động đúng của cô. Và tôi xin lỗi.”","GreyThroat không nói gì.","“Nhưng cô thật sự cần cải thiện kỹ năng giao tiếp đấy. Họ đâu có muốn gây khó dễ, đó là màn kịch để sống sót thôi. Nếu cô làm hỏng chuyện, vẫn phải sang phòng Pháp chế.”","“Tùy cô.”","","“Làm tốt lắm!” Doctor nói qua bộ đàm.","“Em nghĩ vậy… ít nhất Blaze đang cố gắng,” Amiya nói. “Chỉ có chị ấy mới gạt bỏ định kiến nhanh đến thế. Các operator tinh nhuệ của Rhodes Island không chỉ có kỹ năng chiến đấu phi thường. Blaze còn có tính cách cởi mở và sự khéo léo. Cùng với những quan điểm riêng. Nếu Doctor muốn dẫn dắt chị ấy, muốn chị ấy ủng hộ, Doctor phải giành được lòng tin của chị ấy. Và trước hết, Doctor phải học cách làm điều đó. Em đã chiến đấu cùng Blaze lâu lắm rồi. Và em nghĩ… em nghĩ Doctor cũng làm được.”","“Tôi đang làm khá ổn.”","“Nhưng khá ổn… vẫn chưa đủ, phải không? Chị ấy tỏ ra vô tư, nhưng Blaze có tính cách phức tạp lắm. Cho thời gian, mở to mắt, em biết Doctor làm được. Nhưng Doctor cần cố gắng hơn nữa! Học cách tin nhau không dễ, nhưng phải làm. Bọn mình cần sức mạnh của Doctor, và Doctor cần chinh phục các operator để biến chiến thuật của Doctor thành hiện thực. Đó là một quá trình dài, nhưng Doctor cần trải qua nó.”","“Blaze là operator tinh nhuệ giỏi tấn công. Chị ấy không có nhiều đóng góp về tư duy chiến lược. Chị ấy thật sự cần sự hỗ trợ của Doctor. Hoặc Doctor có thể nghĩ là chị ấy sẽ biến chiến lược của Doctor thành hiện thực trên chiến trường. Chị ấy là dân chuyên nghiệp.” Amiya ngừng lại. “Các operator của bọn mình làm theo lệnh vì ý thức trách nhiệm, không phải lòng tin. Lòng tin thật sự được xây trên sự thấu hiểu. Kiểu mà Blaze đang xây với GreyThroat ấy.”","Rồi cô bé khựng lại. “Ồ… Có vẻ có khách rồi. Thêm Reunion. Cho Blaze thêm chút không gian để xin lỗi nhé. Chị ấy còn cần lỡ lời thêm vài lần nữa.”","“Vậy ta câu thêm thời gian cho họ!”","“Vâng. Chị ấy nói chuyện giỏi, nhưng không giỏi bày tỏ cảm xúc lắm. Thứ thật sự đang diễn ra ở đây là chị ấy đang đối mặt với những định kiến sâu thẳm của mình, hơn là chỉ một lời xin lỗi với GreyThroat. Định kiến của người bình thường với người Infected không phải đường một chiều… bọn mình cũng có vấn đề của mình với người không nhiễm bệnh. Kẻ thù bên trong cũng là kẻ thù như kẻ thù bên ngoài.”","“Ta sẽ đánh bại cả hai.”","“…Bọn mình sẽ làm.” Amiya nhìn về phía những bóng Reunion đang tiến tới. “Nghe này. Đám Reunion lúc nãy sợ đến mất hồn. Cả bọn mình lẫn L.G.D. đều không thể gieo nỗi sợ như thế vào ai. Họ đã sẵn sàng làm trái mọi thứ họ tin tưởng. Họ đã gặp thứ gì khác… Nhưng thứ gì ngoài kia có thể khiến họ như vậy? Và… bọn mình có phải đánh cả chúng nữa không?”","","Ở một góc khác của khu ổ chuột, Crownslayer đang chạy.","<i>(Hộc, hộc…! …Bẫy à?! Đợt tấn công lúc nãy chỉ là nghi binh sao? Nếu ả cứ tiếp tục chia cắt đội của ta, cả đơn vị sẽ vô dụng… Ta phải liên lạc với họ ngay! Grrr, sao ngón tay không cử động được? Sao ta lại run thế này?! Ta… ta không thể để ả bắt được!)</i>","Một bóng đỏ vụt qua. Crownslayer ngã sấp xuống, một bàn tay đè chặt sau gáy.","“Nggah!”","Một tiếng gầm gừ trầm thấp vang lên ngay bên tai cô ta.","@cg:avg_6_18","“Projekt Red, đừng giết cô ta,” một giọng nói điềm tĩnh vang lên.","“Khụ khụ…! Gah!”","“Là cô ta à?”","“Phải, chắc chắn. Là mùi của cô ta.” Cô gái đè lên Crownslayer, đôi tai sói dựng lên, mũ trùm đỏ che nửa khuôn mặt, khịt khịt mũi. “Ghê. Đồ giả. Cô ta không phải sói. Nhưng mùi thì là thật. Mùi của một con sói thật. Con sói thật đầu tiên.”","“Sói thật?” Kal’tsit bước ra từ bóng tối.","“Mày… con sói con bẩn thỉu!” Crownslayer gầm lên.","“Đừng cử động.”","“Mmf, sao ta lại…? Cơ bắp ta còn không phản ứng. Mày… mày điều khiển được ta à?”","“Cô ta định dùng kỹ thuật của sói, một cú cắn học từ sói. Cô ta muốn phản kháng. Tôi có thể cắt đứt tủy sống, làm cô ta tê liệt.”","“Không cần,” Kal’tsit nói.","“Ok.”","Crownslayer ngẩng lên, và nhìn thấy Kal’tsit. Mắt cô ta mở to.","“Khoan, mày… Tao biết mày… Cuối cùng tao cũng tìm thấy mày…! Đồ phản bội… mày là đồ phản bội! Tao đã tìm thấy kẻ phản bội!”","“Còn cô là…?” Kal’tsit nhìn cô ta một lúc. “Con gái của Ilia, Lyudmila?”","“Câm mồm! Mày không có quyền nhắc tên bố tao! Ursus đã phá hủy toàn bộ phòng thí nghiệm, và tất cả các nhà khoa học.”","“Cô nghĩ vậy sao?”","“Sao mày dám?! Chính là mày! Mày là con đàn bà phản bội ghê tởm đã cùng Sergei bán đứng bố tao, bán đứng tất cả các nhà khoa học!”","Kal’tsit im lặng. “…Tóc cô cùng màu với anh ấy.”","“…Mày nói gì vậy? Sao mày lại…?”","“Đừng cử động,” Projekt Red ấn mạnh tay.","“Agh!”","“Cô đang thắc mắc tại sao tôi không phản ứng gì trước lời buộc tội của cô?” Kal’tsit hỏi.","“Vì mày là đồ cặn bã!”","“Cặn bã. Vậy tôi nên là loại cặn bã nào? Tôi nên là kẻ hèn nhát, chạy theo của cải và xa hoa…? Hay tôi nên tàn nhẫn và mưu mô, làm mọi thứ để đạt mục đích? Tôi, đang đứng trước mặt cô, có khớp với hình ảnh của cô không?”","“Tao chưa bao giờ nghĩ… Tao chưa bao giờ nghĩ mày là con đàn bà máu lạnh vô tâm!”","“Sergei có thú tội thật lòng với cô trước khi cô giết ông ta không?”","“…Mày nói gì…?”","“Cô có biết ông ta là cha của Alex và Misha không?”","Crownslayer bật cười, tiếng cười khàn đặc. “Hah… Hahaha…! Alex đã giúp tao tìm ra ông ta!”","“…Reunion nhận nuôi Alex, giết cha cậu ấy, và săn lùng chị gái cậu ấy.” Kal’tsit thở ra. “Hah… Projekt Red, cho cô ta cử động.”","“Ok.”","Crownslayer bật dậy, lùi lại. “…Mày muốn gì?”","“Cho cô một cơ hội giết tôi.”","“Cơ hội? Mày có biết mày đang nói gì không? Mày từ bỏ mạng sống à? Mày muốn sám hối, như Sergei, kẻ ngồi trên đỉnh Chernobog sau khi bán đứng đồng nghiệp sao? …Ồ, mày sẽ hối hận. Mày sẽ hối hận vì tất cả những gì mày đã làm!”","“‘Không hối tiếc’, tôi luôn nói vậy… Nhưng thật ra, có một nỗi hối tiếc rất lớn tôi sẽ chia sẻ với cô hôm nay. —Nhưng tôi e là nó chẳng liên quan gì đến cha cô.”","“Tao sẽ giết mày. Tao sẽ giết mày!” Crownslayer hít một hơi thật sâu. “Xì… Haah… ‘Nuốt lấy vị đắng của người chết’…”","Một làn khói dày đặc tràn ra từ miệng cô ta, phủ kín con hẻm.","“Sương mù?” Kal’tsit hỏi.","“Là Arts,” Projekt Red nói.","“Không, không phải sương. Đây là khói. Hệ thần kinh kích thích một cơ quan phát khói trong khoang miệng. Đúng là một loại Originium Arts dựa vào cơ quan nhiễm bệnh này.”","Giọng Crownslayer vang lên từ khắp nơi trong làn khói. “Mày đứng đó nói nhảm… Mày hết cứu rồi. Mày sợ đến mức không thể hiện ra được à? Tại sao mày phản bội bố tao? Tại sao mày phản bội các nhà khoa học? Tại sao?! Nói cho tao biết tại sao— ‘Giám đốc Kal’tsit’?!”","“Lyudmila, chính tôi cũng chỉ vừa kịp thoát chết.”","“Mày nghĩ tao tin mấy lời nhảm nhí đó à?”","“Hah. Cha cô đã đọc ‘Sự thật và Công lý’ cho cô nghe, phải không?”","“—!”","“Đưa cho một đứa trẻ năm tuổi cuốn sách như thế… Ilia đúng là chẳng biết nghĩ gì. Nhưng anh ấy yêu cuốn sách đó. Một ngày hè, anh ấy bế cô, cùng cuốn sách, đi ngang qua cửa sổ, những bụi cây cam rực dưới ánh nắng. Anh ấy bắt cô vẫy tay chào tôi. Cô bĩu môi rồi quay mặt đi.”","“Đủ rồi!”","“Tối hôm đó, anh ấy hỏi tôi: nếu ta cứ niêm phong cỗ quan tài đó lại, và không bao giờ nói với người Ursus về những cỗ máy bên trong thì sao? Liệu ta có cứu được nhiều người hơn không? Liệu ta có ngăn được người Ursus dùng những cỗ máy đó trong chiến tranh không?”","“Mày nói tất cả những thứ này để… để làm tao rối trí à?!”","“Ilia là một trong những nhà khoa học đưa ra kế hoạch niêm phong cỗ quan tài. Và niềm tin của anh ấy đã ảnh hưởng cả cuộc đời anh ấy. Cô có tinh thần chiến đấu của anh ấy. Nhưng anh ấy còn nhiều hơn thế… Lyudmila, cô gọi tôi là kẻ phản bội, cô muốn giết tôi. Cô có thể làm vậy, nhưng— Khi cô chọn bạo lực, cô định sẵn sẽ có ngày gặp thứ mạnh hơn mình.”","“Hah hah… Mày còn kiêu ngạo hơn được nữa không? Không ai, không Caster nào xuyên được màn khói của tao. Mày không biết tao ở đâu cả. Mày sẽ chết trong tiếng thét. Tao cần mày chết trong tiếng thét.”","Projekt Red lè lưỡi ra, như chế giễu.","“Vì các nhà khoa học, vì người Infected, tao phải giết mày. Đồ con rối của Ursus! Đồ rác rưởi!”","“Trông tôi giống Caster lắm sao?” Kal’tsit nói. “Tôi là người Infected thật, điều đó cô nói đúng… Đến đây, Mon3tr.”","Một thứ gì đó trồi lên từ sau lưng Kal’tsit. Một sinh vật dài, đen bóng, như được tạc từ đá và xương, với những móng vuốt sáng lóa và đôi mắt xanh lục rực cháy. Nó trườn ra, như thể vẫn luôn ở đó, nối liền với cột sống của cô ta.","“…Hả? C-cái gì… đó là gì?” Giọng Crownslayer run lên. “L-làm sao? Cột sống của mày?!”","“Có vẻ cô nhìn xuyên được màn khói nhỉ?”","“Làm sao…? Ack…! M-mày là cái gì vậy?! Cái gì vậy?!!!”","“Tôi không phải Caster. Tôi chưa bao giờ dựa vào Originium Arts.” Kal’tsit giơ tay. “Đi đi, Mon3tr.”","Sinh vật rít lên một tiếng vui vẻ, rồi lao vào màn khói.","“Nnng… Gaaaagh! Cái gì vậy?! Thứ đó là gì?! Aaaaaah! Đừng chạm vào tao! Thả tao ra! Thả tao raaaa! Sao tao không xuyên được vỏ của nó? Aiee! Đừng chạm vào tao! Tránh ra!”","“Tiêu diệt…” Kal’tsit nói.","“Aaaaaahh!!”","“…vật đang rơi trên đầu cô ta.”","Một mảng tường khổng lồ đổ xuống. Mon3tr vung móng vuốt, nghiền nát nó thành bụi ngay trên đầu Crownslayer. Rồi nó rít lên một tiếng bất mãn.","“Ngươi hăng quá rồi. Tòa nhà sắp sập. Đừng để cô ta bị đè.”","Khói tan dần. Crownslayer nằm sóng soài trên mặt đất, cơ thể run lẩy bẩy, mặt nạ vỡ một nửa.","“Mmmg… …Không…”","Mon3tr cúi xuống, ngâm nga một âm thanh trầm thấp.","“Giết tao đi,” Crownslayer nói.","“Cái gì?”","“…Mày rõ ràng có thể giết tao dễ dàng! Đừng nói với tao mày là loại thích vờn con mồi! Nếu không giết được mày, tao còn sống để làm gì? Chỉ cần nhớ, kể cả khi tao chết, tao vẫn nguyền rủa mày mãi mãi!”","“…Cô thật sự sẵn sàng chết sao?”","Crownslayer không trả lời.","“Cô muốn chết sao?”","“…Hộc…”","“Nếu tôi là kẻ phản bội của cô, giết tôi rồi cô sẽ thấy khá hơn sao?”","“…Đừng… nói nữa! Tao sẽ giết mày! Tao sẽ làm!”","“Ilia là học trò của tôi, và là bạn tôi,” Kal’tsit nói. “Cha cô là một trong những nhà nghiên cứu giỏi nhất của tôi. Sự tận tụy và vị tha của anh ấy có thể đã đẩy Ursus tiến lên ít nhất năm năm.”","“Tao không muốn nghe nữa! Sao mày cứ khăng khăng kể cho tao những thứ này?!”","“Cô muốn nghe. Vì cô luôn nghi ngờ chính mình. Cô chưa bao giờ để Sergei giải thích. Nên tôi sẽ giải thích thay ông ta.” Kal’tsit nhìn thẳng vào cô ta. “—Tôi không phản bội ai cả. Kể cả Sergei. Ông ta thiếu quyết đoán, nhưng không tham lam. Chính quyền Ursus đã giữ con trai và con gái mới sinh của ông ta. Ông ta khai ra vị trí của cha cô để cứu mạng chúng. Và giờ, Alex và Misha đều đã chết. Cuối cùng, ông ta chẳng cứu được ai.”","Crownslayer sững sờ. “Nếu… Nếu tao đi cứu Misha, có lẽ cô ấy và Skullshatterer… vẫn còn sống.” Rồi cô ta lắc đầu điên cuồng. “K-không! Không đời nào! Nhìn xem mày mạnh thế nào đi! Sao mày không cứu bố tao?!”","Mon3tr gầm gừ đe dọa.","Kal’tsit im lặng một lúc. “…Vì tôi không làm được. Tôi không thể thuyết phục cha cô rời khỏi viện nghiên cứu. Lyudmila, tôi đã gửi cô đến Siracusa trước khi rời Chernobog. Vậy mà cô vẫn quay về. Ôi, cô giống cha cô quá. Đôi khi, ý chí còn mạnh hơn cả thời gian. Cô sẽ luôn quay về Chernobog, cũng như cô sẽ gặp tôi ở đây.”","Crownslayer im lặng rất lâu. “…Vậy là tất cả đều vô nghĩa sao? Mọi điều bố tao đã làm, mọi điều tao đã làm… đều vô ích sao?”","“Không. Các nhà nghiên cứu đã chết để bảo vệ bí mật của chúng tôi. Cho đến hôm nay, Ursus vẫn không có cách nào phân tích những thứ bên trong cỗ quan tài. Họ đã bỏ cuộc, và niêm phong cơ sở lại. Giờ, chỉ còn chút năng lượng sót lại để khai thác, cung cấp cho lõi của Chernobog. Nếu tôi phản bội ai, thì đó là Đế quốc Ursus. Những nỗ lực của cha cô có ý nghĩa. Dù Ursus đã che đậy tất cả từ lâu, cô vẫn có thể ghi nhớ. Tôi sẽ ghi nhớ.”","Projekt Red ngáp dài.","“…Nhưng tất cả những gì cô đã làm? Chúng là vì cái gì?” Kal’tsit hỏi. “Ursus đã thanh trừng toàn bộ viện nghiên cứu và tàn sát từng mảnh lòng trắc ẩn trong các nhà khoa học của họ. Kẻ phản bội thật sự là chính Đế quốc. Nhìn cô đi. Cô đã giết Sergei, cô đã giết một người không bảo vệ nổi con mình. Giờ cô ở Lungmen. Nếu cô và những người bạn Infected của cô thật sự chiếm được thành phố, cô sẽ làm gì với người không nhiễm bệnh?”","“Tàn sát hết họ? Nô dịch họ? Lưu đày họ ra hoang mạc để họ chết vì giá rét? Hay cắt họ bằng Originium, biến họ thành người Infected, truyền nỗi đau của cô cho họ? …Hay cô sẽ chung sống hòa bình với họ?”","“Cô làm được điều đó không, Lyudmila? Reunion, như hiện tại, có làm được không? Đó có phải là cách cô muốn xây dựng quốc gia của người Infected không? Hay đó là cách cô muốn chiến đấu với Ursus? Nếu là vế sau, sao lại đến Lungmen? Nếu cô muốn khiến kẻ thù khiếp sợ, cô có thể làm gì để đáng sợ hơn Ursus?”","<i>(Kal’tsit, cô ta đang bối rối,)</i> Projekt Red thì thầm. <i>(Cô ta sợ. Cô ta muốn chạy.)</i>","Kal’tsit im lặng một lúc. “Mon3tr, quay về.”","Sinh vật rít lên lần cuối, rồi tan vào cột sống của cô ta như chưa từng tồn tại.","“Như vậy có ổn không?” Projekt Red hỏi.","“Cô ta nghe được tôi.” Kal’tsit quay về phía Crownslayer. “‘Crownslayer’, lòng căm thù của cô cũng như của phong trào của cô đã bị lợi dụng, bị đùa giỡn. Hãy nghĩ về cha cô. Nhớ lại những gì Ilia đã dạy cô. Hãy nghĩ xem, cô muốn trả thù ai? Kẻ đang dẫn cô vào con đường khủng bố và ám sát này… Thủ lĩnh của cô không phải người tỉnh táo. Thủ lĩnh của cô không có trái tim. Một thủ lĩnh trung thành với lý tưởng của mình sẽ không để người khác chết vì họ, càng không để ai đó giết người thay họ.”","“Chạy đi. Rời khỏi nơi này. Đi một con đường khác. Một con đường có thể thật sự thay đổi thế giới này… Nếu đó là điều cô muốn.”","Khi Kal’tsit quay lại, con hẻm chỉ còn lại hai người.","“Mùi của cô ta mất rồi,” Projekt Red nói. “Cô luôn muốn gặp cô ta à? Sao không giết cô ta?”","“Ta có nên giết một con linh cẩu vô gia cư không, kể cả khi ngôi nhà không có thật?”","“Câu hỏi khó. Tôi không biết.”","“Projekt Red, cô nghĩ giết tôi sẽ khiến cô ta hạnh phúc sao?”","“Không. Cô ta đang đau đớn.”","“Chúng ta không phải luật pháp. Chúng ta không thể phán xét con người. Chúng ta có sức mạnh giết người khác, nhưng không có quyền tuyên bố việc đó là đúng. Nếu cô ta tận hưởng việc giết người, tôi đã giết cô ta ngay tại chỗ. Không chút do dự.”","“Tôi biết. Cô ta không vui. Hơi thở của cô ta loạn nhịp.”","“Giờ cô ta đã trở thành một loại virus. Một chủng đặc biệt lây lan ‘sự bất an’ giữa những tín đồ Infected cuồng tín của Chernobog.” Kal’tsit nhìn lên bầu trời xám. “…Một người sống được bao nhiêu năm? Và có thể đi bao nhiêu con đường? Chúng ta dành nhiều thời gian mù quáng hơn là nhìn thấy sự thật. Nhưng rồi, nhìn thấy sự thật và đưa ra lựa chọn là hai chuyện khác nhau. Khi cô ta tỉnh khỏi giấc mơ báo thù tập thể này, cô ta sẽ rời Reunion. Nhưng dù vậy, máu của Sergei, và của người dân Chernobog, sẽ luôn vấy trên tay cô ta.” Cô ta quay sang. “Projekt Red… Khi cô đưa ra một lựa chọn, sẽ không có đường quay lại.”","“Tôi hiểu. Tôi sẽ cố hết sức. Tôi chỉ giết sói thôi.”","“Ngoan lắm. Cô còn nhớ mùi đó không?”","“Tôi nhớ.”","“Nó thế nào?”","“…Không tệ. Đó là mùi máu, nhưng không giống như cô vừa nói, kiểu có trái tim gì đó.”","“Ngớ ngẩn thật. Talulah là Draco, sao có thể là sói được?”","“Hừm.” Projekt Red nghiêng đầu. “Đến lúc đi rồi à?”","“Ừ, đi thôi.” Kal’tsit dừng lại, rùng mình. “…Nhiệt độ đang giảm. Ta sắp hết thời gian rồi. Tăng hiệu suất lên.”"],"bg":"bg_indoor_n","cast":[["Kal'tsit","op:char_003_kalts"],["Crownslayer","npc:char_1502_crowns"],["Amiya","op:char_002_amiya"],["GreyThroat","op:char_367_swllow"],["Projekt Red","op:char_144_red"],["Blaze","npc:char_017_homura_3"],["Child",null],["Mon3tr",null]]},{"c":"6-12","t":"Tuyết rơi trên lãnh nguyên","p":["“Mọi đội Reunion tôi liên lạc được đều đã rút,” một thành viên Yeti nói.","“Đông người thật.”","“Không thể tin được… như một dòng sông.”","“Sẽ là một dòng sông ngoài hoang mạc kia,” Nesti nói, giọng trầm và chậm. “Một dòng sông người tị nạn. Ngoài đó có người Ursus và người Lungmen. Người Infected và người bình thường như nhau. Dù đến đây với cái gì, họ cũng ra đi tay trắng. Họ tưởng có một nơi sẽ đón nhận họ. Giờ họ biết chưa bao giờ có nơi nào họ có thể đến cả. Dòng sông này sẽ không chảy mãi.”","Mọi người im lặng.","<i>(Nghe anh ấy buồn quá,)</i> một người thì thầm.","<i>(Anh ấy học được từ Bố Lớn đấy.)</i>","<i>(Thảo nào. Lúc này ai mà chẳng đa cảm.)</i>","“Nếu Bố Lớn ở đây, ta đã thắng trận rồi, và mọi chuyện đã không đến nước này, nhỉ?”","“May rủi thôi. Nghĩ xem mọi chuyện có thể khác thế nào cũng chẳng ích gì.” Một người đứng dậy. “…Chuẩn bị đi. Tôi đi bàn với Nỏ Thủ Bóng Ma.”","“Đừng giục. Đâu phải tôi không biết.”","“Nhanh lên đi. Đừng đùa nữa.”","“Tôi cũng nghẹn ngào lắm đấy!”","@bg:bg_indoor_n","“Chị chắc chứ?” Blaze hỏi qua bộ đàm.","“Là Biệt đội Yeti,” một operator Rhodes Island báo.","“Còn Amiya và người của con bé?”","“Họ đang trên đường. Amiya bảo nhắn với chị là ‘bình tĩnh’.”","Blaze im lặng một lúc. “…Con bé biết rõ hơn là không nên bảo tôi câu đó. Tôi là Blaze mà. Tôi bình tĩnh bao giờ chứ?”","“Blaze! Chị đi đâu vậy?!”","“Đi cứu người!”","@bg:bg_undergroud_n","“Nỏ Thủ! Chờ đã!”","“Yeti… các anh làm gì vậy?”","“Là chị FrostNova… Chị ấy đang yếu dần. Chị ấy không trụ được lâu nữa. Chị ấy đã dốc cạn sức đẩy lùi quân Lungmen. Có thể chị ấy sẽ không tỉnh lại trong một thời gian.”","“Ý anh là anh muốn bọn tôi mang chị ấy theo?” Người Nỏ Thủ ngập ngừng. “Nhưng bọn tôi không về Chernobog. Faust không muốn Mephisto quay về…”","“Bọn tôi cầu xin các anh!” Thành viên Yeti quỳ xuống. “Bọn tôi muốn chị được ở bên Patriot, đến cuối cùng! Bọn tôi biết, hiện giờ họ không hòa hợp lắm, nhưng… mối liên kết giữa họ còn sâu hơn cả máu mủ. Nên làm ơn… bọn tôi cầu xin các anh.”","Người Nỏ Thủ im lặng rất lâu. “…Còn các anh sẽ làm gì?”","“Bọn tôi sẽ yểm trợ các anh. Nếu không cầm chân chúng, người Lungmen sẽ đuổi kịp các anh ngay. Một khi các anh đi đủ xa khỏi Lungmen để không còn là mối đe dọa, chúng sẽ thôi truy đuổi.”","“Nhưng như vậy nghĩa là các anh sẽ…”","“Sống bằng gươm thì chết bằng gươm. Bọn tôi chấp nhận chết trong trận chiến. Tương lai mà chị FrostNova nói đến vẫn còn xa lắm. Nhưng bọn tôi không cần tận mắt thấy nó.”","“Bọn tôi nợ các anh mạng sống.”","“Có gì đâu. Các anh đang cứu chị của bọn tôi.”","“…Bọn tôi sẽ làm điều các anh nhờ. Tôi thề.”","“Cầm lấy găng tay này. Và mặc bộ đồ bảo hộ này vào.”","“Để làm gì?”","“Chị của bọn tôi quá lạnh với các anh.”","Người Nỏ Thủ đỡ FrostNova lên tay. Rồi anh ta khựng lại. “…Chị ấy… Chị ấy nhẹ quá…”","“Arts đã rút cạn cơ thể chị ấy. Nhẹ thôi, nhẹ thôi… Đừng đánh thức chị ấy.” Thành viên Yeti nhìn gương mặt đang ngủ yên của FrostNova. “Nhìn chị ấy xem… nhìn chị ấy ngủ ngon chưa kìa. Tạm biệt, chị… Bọn em sẽ chờ chị.”","“…Được rồi. Ta… đi tiếp thôi.”","“Là bọn tôi đi tiếp mới đúng.”","“Ta sẽ gặp lại nhau, Yeti.”","“Mong là đừng sớm quá.”","@bg:bg_indoor_f","“…Ta sắp chết à?” thành viên trẻ nhất của đội Yeti hỏi.","“<i>[tiếng chửi Ursus]</i>, cậu khóc cái gì vậy?” một người quát. “Cậu có phải Yeti không hả?!”","“Anh không khóc à?!”","“Tôi khóc cái gì…?! Cậu quên chị nói gì rồi à?!”","“Chị nói đừng khóc,” Petrova nói.","“Đúng! Chị nói đừng khóc… Hơn chục năm trước, chị nói đừng khóc! Nên tôi không muốn thấy giọt nước mắt nào! Ta không được khóc… vì ta chưa thắng!”","“Khi nào ta thắng, khi nào ta được tự do…”","“Khi nào được tự do, ta sẽ khóc cạn nước mắt, ngoài hoang mạc, trong tuyết, giữa những đống lúa mì chất cao, ta sẽ khóc như mưa!”","“Chị cũng khóc khi nói câu đó đấy, các cậu biết không,” Petrova nói.","“Hồi đó chị mới chín tuổi. Bọn ta đều lớn hơn chị một chút…”","“Không có chị, ta đã chết trong cái mỏ đó rồi.” Petrova quay sang. “Có mang nước chấm không?”","“Mang cái gì…? Khoan, chẳng phải không được mang theo sao?”","“Hành quân thì không được uống, nhưng cậu có mang theo, tôi biết.”","“Em cũng muốn uống…” cậu trẻ nhất nói.","“Cậu chưa đủ tuổi mà, đúng không?”","“N-nhưng em chưa thử bao giờ. Em không muốn chết mà chưa từng nếm…”","“Cho cậu ấy một ít,” Petrova nói.","“Petrova…” Người kia thở dài, rồi rút ra một chai rượu nhỏ. “Được rồi, làm một ngụm. Nhưng đừng nhiều quá, ai cũng cần một phần.”","Chai rượu được chuyền tay nhau.","“Na zdorovye, anh em! Cho ấm người!”","“Vì Chị! Và vì Bố Lớn!” Petrova nâng chai.","“Vì FrostNova! Và vì Patriot!” cả đội đồng thanh.","","Trên một mái nhà cao nhìn xuống chiến trường, Ch’en đứng cạnh Amiya.","“Em có biết những người Infected này không?”","“Em biết, sĩ quan Ch’en.”","“Nhưng trận đánh cuối cùng này phải diễn ra.”","“Ta có lựa chọn không?”","“Có lẽ là không. Nhìn ra sau lưng em đi. Họ còn chẳng thèm che giấu nữa.”","Ở những mái nhà phía sau, những bóng áo mưa đen đứng thành hàng, im lặng như những con quạ.","“…Áo mưa đen,” Amiya nói.","“Vậy là ta phải đánh họ. Đây là điều ta phải làm. Nếu không, ta sẽ thất bại. Và việc ép lực lượng đặc nhiệm đối đầu với Yeti sẽ trở nên rất thiếu thuyết phục. Trừ khi em thuyết phục được họ đầu hàng?”","“Chừng nào sau lưng họ còn người Infected… họ sẽ không bỏ cuộc.”","“…Amiya. Tôi sẽ không ép em chiến đấu.”","“Em xin lỗi, sĩ quan Ch’en. Nhưng… nhưng bọn em sẽ chứng kiến. L.G.D. đã chiến đấu dũng cảm, không ai phủ nhận được. Cô đã chiến đấu vì Lungmen, chống lại quân xâm lược. Đây là cách bọn em sẽ giúp cô chống lại lực lượng đặc nhiệm. Và vì chính bọn em… Bọn em phải ghi nhớ mọi trận chiến vì người Infected. Từng trận một.”","“Amiya.”","“Sĩ quan Ch’en?”","“Khi trận này kết thúc, cùng đi ăn nhé.”","“N-nhưng em là người Infected…”","“Tôi không quan tâm. Cô to mồm và cô cao lớn kia? Họ cũng không bận tâm đâu.” Ch’en nhìn xuống chiến trường. “Trận này… sẽ phải trả giá đắt.”","“Với bọn em, đó là một trận đánh. Với Lungmen, đó là một cuộc chiến. Và chiến tranh là như vậy.”","“Nhưng kẻ đã lên kế hoạch cho tất cả chuyện này, họ không có mặt ở đây.”","Amiya không trả lời.","“Này, có chuyện tôi phải nói với em—” Ch’en ngừng lại. “—Nhưng không phải lúc này.”","“Vâng. Không phải lúc này, sĩ quan Ch’en.” Amiya im lặng một lúc, rồi quay sang. “Doctor…”","“Không muốn nhìn à?”","“…Vâng. Em…”","“Nhưng giống như ở phế tích Chernobog…”","Amiya nhìn Doctor. “Doctor nói đúng. Em đã quyết định rồi. Em cần nhìn thấy nó… bằng chính đôi mắt mình.”","“Cùng nhau.”","“Cùng nhau.”","","“Vậy là ta không gọi chị là Chị vì chị lớn tuổi hơn sao…?” cậu trẻ nhất hỏi. “Sao giờ em mới biết?”","“Thì hợp với cậu mà. Hồi đó cậu mới ba tuổi.”","“Phì!”","“Này, thái độ gì đấy? Hai ngụm đã say rồi à? Hồi cậu khóc đòi ăn, tôi có cho cậu ăn không?”","“Đó là hồi đó, giờ là… bây giờ!”","“Các cậu biết không, buồn cười thật,” Petrova nói. “Tự nhiên tôi lại nghĩ đến mấy người Rhodes Island. Con mèo ấy, dáng nóng bỏng, cái người bảo muốn uống với bọn mình. Tiếc thật. Trông cô ta có vẻ uống giỏi. Trông vui tính lắm.”","“Còn cô thỏ con, chắc chưa đủ tuổi đâu nhỉ? Bao nhiêu tuổi? Mười sáu? Mười bảy?”","“Chắc mười bốn thôi. Trông lớn hơn vì cô bé nói năng chững chạc.”","“Bằng tuổi chị… hồi đó.” Anh ta nâng chai. “Nâng ly cho họ thêm lần nữa. Nói là làm!”","“Nói là làm!” Nesti nói.","“Ừm, ờ… nói là làm!” cậu trẻ nhất nói.","@bg:bg_indoor_n","Ở rìa khu ổ chuột, giữa dòng người Infected đang lặng lẽ rời đi, Nine đứng nhìn về phía chiến trường.","“…Người Lungmen nên phối hợp tốt hơn.”","“Đi khỏi đây đi,” một thành viên Reunion nói. “Yeti chỉ cầm chân được một lúc thôi.”","“Cậu không thấy những gì họ đang làm thật phi thường sao?”","“Nếu ta chết, thì họ làm tất cả vô ích. Nỏ Thủ Bóng Ma nói ta không thể về Chernobog. Nên ta sẽ đến một nơi mới. Cô không quan tâm căn cứ mới của bọn tôi ở đâu à?”","“Dù ở đâu, tôi cũng sẽ đi cùng các cậu.”","“Heh. Người Lungmen các cô cũng chẳng khác gì bọn tôi. Tôi cứ mong họ đối xử với các cô tốt hơn ở đây. Hóa ra cũng y như ở Ursus.”","“Người Infected ở đâu cũng khổ như nhau.”","“Đó không phải điều cô nói hồi mới đến.”","“Người ta thay đổi.”","@bg:bg_indoor_f","Blaze lao qua những mái nhà, nhảy từ tòa nhà này sang tòa nhà khác. Rồi cô thấy họ.","“Yeti? Có phải Yeti không? Là Yeti! Đ-đúng không…? Chắc chắn rồi!” Cô hét lên, giọng vỡ ra. “Yetiiiii… Yetiiii! Sao các cậu lại như thế này?! Chết tiệt! Đừng chết! Tôi không cho các cậu chết! Cứ cố lên, tôi cứu được các cậu! Tôi sẽ đưa các cậu đến chỗ an toàn…! Sao những người Infected các cậu lại muốn chết ở đây chứ?!”","@bg:bg_indoor_n","“Lực lượng đặc nhiệm ngừng tấn công rồi? Không, có vẻ họ đang rút…?” một sĩ quan L.G.D. nói. “Có vẻ… họ đang nhường thế chủ động cho ta. Ta đang thể hiện sức mạnh của lực lượng thực thi pháp luật Lungmen à? <i>[tiếng chửi Lungmen]</i> Chúng xem thường ta! …Thôi kệ. Nghe đây, đây là đợt cuối cùng! Đừng làm người dân thất vọng, hay sĩ quan Ch’en. Ta sẽ cho Reunion thấy Lungmen mạnh thế nào! Người Infected sẽ không dám tấn công thành phố của ta nữa!”","","“Hah…” Petrova đứng dậy, nhìn về phía những hàng khiên của L.G.D. đang tiến tới. “Nỏ Thủ Bóng Ma, đừng làm bọn tôi thất vọng. Các anh phải đưa chị của bọn tôi về với ông già. …Chị ấy sắp hết thời gian rồi. Chị ấy nên dành nó bên ông.”","“Chính ta cũng chẳng còn nhiều thời gian, nhỉ?”","“Sẵn sàng chưa?”","“Sẵn sàng. Trả lại mạng sống của mình thôi.” Người đồng đội cười. “Hãy cho chúng thấy đội quân được huấn luyện bởi Buldrokkas’tee, người lính vĩ đại nhất của Ursus, và được dẫn dắt bởi cơn ác mộng lạnh lẽo nhất của nó, làm được gì!”","Petrova rút ra một khối Originium đen bóng, lạnh buốt đến mức tay cô bốc khói. “Những Originium Arts cuối cùng của Chị… Originium Băng, sẵn sàng phóng!” Cô ngẩng lên trời. “Nesti! Bọn tôi đến đây!”","Ở xa xa, trên một mái nhà, Blaze gào lên một tiếng xé lòng.","“Yetiiiiiiiiiiiii!!!”"],"bg":"bg_indoor_f","cast":[["Amiya","op:char_002_amiya"],["Petrova","npc:avg_npc_037"],["Ch'en","op:char_010_chen"],["Blaze","npc:char_017_homura_3"],["Nine","npc:avg_npc_043_1"],["Nesti","npc:avg_npc_037"]]},{"c":"6-13","t":"Không có ánh sáng nếu không có lửa","p":["“Tỉnh dậy!”","…?","“Tỉnh dậy!!! Tỉnh dậy… Tỉnh dậy đi!”","Có một giọng nói. Rồi một giọng khác, gấp gáp. <i>“Lại đây, Adam! Mang nước ấm đến!”</i>","<i>Bố…</i>","<i>“Hả…? Con bé còn sống! Tuyệt quá, con bé còn sống! Tạ ơn tổ tiên! Adam! Nhanh lên!”</i>","<i>Bố…? Bố ơi…?</i>","<i>“Bố?”</i> Một khoảng lặng ngập ngừng. <i>“…Ta… Phải! Ta là Bố đây! Phải, phải! Ta là Bố, chắc chắn rồi! Đừng ngủ. Đừng ngủ! Nắm tay Bố, đừng buông ra!”</i>","<i>Bố… Con… lạnh quá…?</i>","<i>“Đừng ngủ, con gái của ta! Ở lại với chúng ta! Thân nhiệt con bé cứ giảm mãi! Mishka, làm gì đi! Không có cách nào nghiêng dòng chảy sao?”</i>","<i>Lạnh quá…! Bố ơi! Con lạnh!</i>","<i>“…Con gái… Con gái của ta! Cố lên!”</i>","<i>Bố ơi, đừng… Đừng bao giờ bỏ con nữa…</i>","@bg:bg_undergroud_u_2","<i>10:48 sáng.</i><br><i>Phế tích “Quận 14” của Chernobog. Tầng kết cấu trên.</i>","Trong bóng tối của một khoảng trống giữa những khối bê tông đổ sập, FrostNova mở mắt.","“Tỉnh rồi à!” Doctor nói.","“Ta tỉnh rồi.” Cô ta nhìn người khoác áo trùm đầu đang ngồi cách mình vài bước. “Ngươi không giết ta trong lúc ta bất tỉnh. Đó là tự tin, hay là gì khác?”","“Chuyện này từng xảy ra rồi… Tôi không có lựa chọn.”","“Dù sao, ngươi đã không làm.”","“Có lẽ vì cô nói mê.”","FrostNova im lặng một lúc. “Ta coi đó là dấu hiệu ngươi đã nương tay. Giờ nếu ta không giết ngươi, ta gọi đó là trả ơn.” Cô ta nheo mắt. “Sao mặt ngươi lại lo âu thế? Có phải vì…? Ngươi đã nghe hết những gì ta thấy trong mơ? Có vẻ ta thật sự đã để lộ điều gì đó rất khó chịu trong lúc mê man. Ký ức là thứ ngươi không thể mất dù có muốn.”","“Ngươi đã thám thính xung quanh chưa? Không tìm được lối ra, phải không? Có vẻ ta sẽ không rời được nơi này một thời gian.”","Một quãng lặng dài. Rồi FrostNova lên tiếng, như đang nói với bóng tối.","“Người ta gọi là cha, tên là Buldrokkas’tee, từng là một sĩ quan trong quân đội Ursus. Nhưng cha ruột của ta đã chết từ lâu. Hồi bé, ta mơ hồ nhớ một người đàn ông hứng một mũi tên nỏ để bảo vệ một người phụ nữ; và người phụ nữ ấy ôm ta vào lòng, chặn loạt tên thứ hai bằng tấm lưng của mình.”","“Cô tận mắt chứng kiến…”","“Hồi đó ta còn không hiểu chuyện gì đang xảy ra, và ký ức này cứ thế không bao giờ phai. Còn sự thật thế nào, sau này bà ta mới kể cho ta nghe. Khi ta gặng hỏi bà về ý nghĩa của hình ảnh ấy, và bà không còn cớ thoái thác nữa, bà nói: ‘Họ là cha mẹ ruột của con… và họ đã chết để bảo vệ con.’”","“Buồn cười là, ta hoàn toàn không biết họ. Trong đầu ta không có ký ức nào về họ ngoài hình ảnh đó. Cha mẹ ruột của ta cứ thế bị lãng quên. Ta khó mà nói là mình có tình cảm gì với họ.”","“Vậy là bà cô nuôi cô lớn.”","“Một nửa thôi. Nửa kia là máu của người Infected Ursus.”","“…Cái gì?”","“Ugh…” FrostNova nhắm mắt lại. “Ta sinh ra trong một khu mỏ ở lãnh nguyên tây bắc. Khu mỏ nhỏ và hẻo lánh, không thuộc thành phố nào, xung quanh không có làng mạc. Quanh năm chỉ có tuyết. Khu mỏ ấy là địa ngục, được xây chỉ để gieo rắc cái chết và nô lệ. Trên những cánh đồng tuyết có vô số khu mỏ như vậy. Cha mẹ ruột của ta là thợ mỏ trong cái hố địa ngục ấy.”","“Bà ở với ta những năm đầu tập nói, nhưng chưa bao giờ nói cha mẹ ta phạm tội gì mà bị kết án lao động trong mỏ. Sau này, khi lớn hơn một chút, ta hỏi quanh trong mỏ và biết được cả cha lẫn mẹ đều phản đối kế hoạch thời chiến của Hoàng đế. Việc họ bị bắt cũng là ngẫu nhiên. Hai dòng cuối của lệnh bắt bị bỏ trống, nên viên trung sĩ phụ trách khám xét chép bừa cái tên trên biển cửa.”","@cg:avg_6_20","“Không qua xét xử, cha mẹ ta mất đi tên tuổi, rời thị trấn nhỏ ấm áp đến vùng Bắc lạnh giá thụ án hàng trăm năm. Đương nhiên, chẳng ai sống được đến lúc đó, chứ đừng nói đến chuyện sống sót rời đi. Bà ta bị kết án vào mỏ cùng họ với tội ‘chứa chấp’ tội phạm. Thật ra, mọi thợ mỏ ở đó đều có hoàn cảnh rất giống nhau.”","“Đương nhiên, cả cha lẫn mẹ ta đều nhiễm Oripathy dưới đó. Mọi thợ mỏ đều vậy. Giờ, kể cả ngươi có thoát khỏi mỏ này, cũng chẳng ai tin lời ngươi nói. Ngươi chỉ là một người Infected, kẻ khủng khiếp, độc ác và cực đoan nhất trong số những bệnh nhân Oripathy.”","“Tuy nhiên, kẻ cai quản khu mỏ, một đơn vị đồn trú quân đội Ursus, cho rằng tốc độ chết tự nhiên của người Infected vẫn quá chậm. Họ bốc thăm để quyết định số phận của những người mắc Oripathy, giết họ cho vui, như một môn thể thao. Có lẽ chính những người thợ mỏ đã khiến họ phát điên, chứ không phải tuyết. Và có lẽ trong mắt họ, người Infected không được tính là người.”","“Năm ta năm tuổi, cha mẹ ta bốc phải thăm đen. Năm ta mười tuổi, bà ta bốc phải thăm đen. Năm ta mười một tuổi, chính ta bốc phải thăm đen, nhưng chẳng quan trọng nữa, họ không quan tâm đến bốc thăm nữa. Họ chỉ muốn bỏ hoang cả khu mỏ. Đến lúc đó, mọi người Infected trưởng thành trong mỏ đều đã chết, và chính sách mới của Hoàng đế khiến các mỏ thiếu người trầm trọng. Theo lệnh, đám cai ngục Ursus chuẩn bị hành quyết những người Infected cuối cùng… Vài đứa trẻ bệnh tật. Sau đó họ sẽ làm sập mỏ để làm mồ chôn tập thể cho người Infected, che giấu tội ác của mình. Sau này, trong những chuyến đi, ta mới biết họ làm thế suốt.”","“Ta buồn. Ta đau đớn. Ta đã đập vỡ rất nhiều quặng. Ta sống cùng những đứa trẻ khác trong mỏ, chúng ta yêu thương nhau, và tất cả sắp chết vô ích. Những cảm xúc mãnh liệt nở ra trong ngực ta, cái chết của cha mẹ và bà hiện lên sống động trong đầu ta. Khi cuộc hành quyết bắt đầu, Arts của ta bùng nổ từ bên trong, giết chết bốn tên lính đang thi hành án.”","“Đương nhiên, ta không có sức xoay chuyển tình thế. Với bọn cai ngục, bọn trẻ chỉ là gia súc. Họ là lính, mang lưỡi kiếm sắc và áo giáp chắc, còn bọn ta như lũ côn trùng vừa kịp chích họ một cái. Tiếng khóc của anh chị em ta vọng đến tai đúng lúc họ hạ gục ta xuống đất và đợt tàn sát cuối cùng sắp bắt đầu…”","“Một đội du kích đến.”","“Đó là đội của Buldrokkas’tee. Mọi tên lính Ursus canh giữ người Infected trên lãnh nguyên phía bắc đều có những giấc mơ, và đội này là cơn ác mộng tồi tệ nhất của chúng.”","“Cô có vẻ… tự hào về họ.”","“Nếu được, ta sẽ tự hào.” Giọng FrostNova trầm xuống. “Họ giết sạch đám đao phủ ngay trước mặt bọn ta, và những đứa trẻ Infected trong mỏ thoát được. Chỉ là… Máu của những người bạn kém may mắn hơn ta và máu của những tên lính đã chết chảy hòa vào nhau, kết tinh thành băng trên mặt đất trắng xóa đến phi nhân tính. Và trong khoảnh khắc ấy, ta nhận ra một điều… Những tên lính Ursus đó, ban đầu chỉ là làm theo lệnh. Họ đổ cùng một thứ máu như ta. Lời lẽ, câu chuyện và thù hận bịa đặt đã gieo rễ tàn nhẫn và thờ ơ vào cơ thể họ. Chính Ursus đã biến họ thành như vậy.”","Cô ta nhăn mặt. “Xì, hừm… Làm ơn… Giúp ta một việc. Trong túi trái áo khoác của ta có vài viên kẹo. Lấy một viên. …Ngươi cũng có thể lấy một viên cho mình nếu muốn thử.”","Doctor lấy hai viên kẹo.","“Ồ? Có vẻ ngươi thích đồ ngọt nhỉ. Chỉ cảnh báo trước, đường này có thể hoàn toàn khác bất cứ thứ gì ngươi từng ăn. Nhưng đời ngắn lắm. Nên thử thứ gì đó mới, đúng không?”","“Rồi sao nữa?”","“Làm ơn bỏ viên kẹo vào miệng ta. Cẩn thận, đừng chạm vào da ta. Từ đầu ngón tay đến cổ, ta bị tê liệt rồi. Ta chỉ cử động được từ cổ trở lên. Nhưng ta vẫn có thể đóng băng ngươi ngay lập tức chỉ bằng một cử động nhỏ nhất của lưỡi. Nên đừng lo. Nếu ngươi xúc phạm ta, ngươi sẽ chết rất nhanh.”","Doctor đặt viên kẹo vào miệng cô ta, thật cẩn thận.","“Cảm ơn.”","Rồi Doctor ăn viên kẹo của mình.","Nó cay. Cay khủng khiếp. Cay đến mức như có ai vừa đốt một ngọn lửa trong miệng.","FrostNova nhìn gương mặt méo xệch dưới mũ trùm. Rồi cô ta bật cười, khe khẽ.","“Cái mặt của ngươi… Hehehe… Xin lỗi, ta không nhịn được trêu ngươi một chút. Ta đã đùa trò này nhiều lần đến mức chẳng còn ai mắc bẫy nữa. Và giờ cuối cùng… Ta thấy một cơ hội. Xin lỗi, ta chỉ là… không nhịn được.”","“Sao cô lại ăn thứ này?”","FrostNova im lặng một lúc. “Vì ta lạnh. Ta đã bảo ngươi cẩn thận, vì kể cả ngươi chỉ chạm vào một chút xíu da của ta, ngươi cũng sẽ bị tê cóng nặng. Nếu trước đó ngươi đã chạm vào ta, ta có thể biết qua phản ứng của ngươi. Ngươi không chạm. Ngươi không cố giết ta.”","“Hiện tượng này vượt ngoài những ghi chép học thuật hiện có.”","“Cái lạnh của ta còn vượt xa cả mùa đông. Hơi ấm từ thế giới bên ngoài không thể xuyên qua cái lạnh buốt bao quanh cơ thể ta. Ta thích đồ uống nóng vì ta cảm nhận được hơi ấm khi dòng nước nóng trôi xuống thực quản, vào dạ dày… Tiếc là đồ uống nóng làm bỏng nội tạng ta. Niềm vui duy nhất còn lại của ta là hỗn hợp rượu và gia vị cay nồng này, với một chút đường, nếu có thể gọi nó là kẹo. Cảm giác ấm áp này, dù chỉ là ảo ảnh ngắn ngủi, cũng mang lại cho ta chút an ủi.” Cô ta khẽ cười. “Xin lỗi vì đã trêu ngươi lúc nãy.”","“Vậy, cô nói là lạnh vì…”","“Oripathy đã tạo ra cơ thể khủng khiếp này của ta. Thế nhưng, vào khoảnh khắc ấy, Buldrokkas’tee đã ôm thân thể lạnh buốt chưa từng biết đến hơi ấm của ta sát vào ngực ông. Ông chẳng hề bận tâm khi ta đông cứng đôi cánh tay không mặc giáp của ông đến mức hoại tử cục bộ. Ta không chắc có phải những cảm xúc ông cảm thấy khi ấy đã lây sang ta hay không… Nhưng cuối cùng ta đã tỉnh táo và sống sót.”","“Vậy là Buldrokkas’tee trở thành cha cô…”","“Ông là cả gia đình ta. Khi còn nhỏ, ông là tất cả những gì ta có. Như ta đã nói, ta không nhớ nhiều về cha ruột… Trong tiềm thức, ta đúng là đã coi con quái thú khổng lồ ấy là gia đình thật sự của mình. Khó nói lắm. Chỉ là, dù bề ngoài như vậy, ông lại đa cảm và cứng đầu ở nhiều chỗ, và chẳng phải buồn cười sao khi một người như thế từng là cỗ máy giết người của Ursus?” Cô ta ngừng lại. “Không buồn cười, phải không? Ta cũng không cười được.”","“Ông từng là anh hùng chiến tranh của Ursus, về hưu ở một thành bang nào đó khi về già.”","“Một người lính Ursus, nhưng chiến đấu vì người Infected?”","“Nếu ngươi không tin lời Ursus, ngươi sẽ thấy ông không cô đơn đâu. Dù vậy, chỉ có một người mà người Infected gọi là ‘Patriot’. Vợ ông mất sớm, ông còn lại một đứa con trai. Nhân tiện, ông là Sarkaz. Thuộc dòng tộc Sarkaz hung dữ nhất. Vậy mà con trai ông lại trở thành học giả, một học giả Wendigo… Có lẽ là người đầu tiên trong lịch sử Ursus.”","“Buldrokkas’tee nhiễm Oripathy trong trận chiến cuối cùng của ông. Thuộc hạ giúp ông che giấu bệnh tình, ông thậm chí giấu cả con trai mình. Ông không muốn kéo con trai xuống cùng, chỉ muốn chết vì bệnh ở một góc tối nào đó của thế giới. Tuy nhiên, trong ‘Cuộc Đại Nổi Dậy’, con trai ông đang vận động vì quyền lợi của người Infected. Đã lâu không liên lạc với cha, người con vẫn coi ông là con rối của Ursus. Và ông đúng là vậy. Họ ra lệnh cho ông giữ trật tự trong hàng ngũ của chính mình bằng mọi giá. Ông cho phép binh lính dùng vũ khí, xung đột nổ ra, và xác người chất đống trong những đống tuyết.”","“Ông là người như vậy đấy.”","“Rồi ông thấy con trai mình trên đường phố, thân thể khi ấy đã hoàn toàn lạnh ngắt.”","“Ta tự hỏi, khi ôm ta, ông có nghĩ đến con trai mình không? Con trai ông đã chiến đấu vì người Infected theo cách riêng của mình, và Buldrokkas’tee tin rằng chính ông đã giết con trai mình. Đội của ông đi theo ông. Từ đó, Lãnh nguyên Tây Bắc có một lực lượng du kích khiến bất kỳ kẻ Ursus nào dám ngược đãi người Infected phải khiếp sợ.”","Một quãng lặng dài.","“Lão quái thú chưa bao giờ nói với ta một lời nào về những chuyện này. Có lẽ ông thật sự coi ta là con gái. Nhưng ta cũng muốn ông kể cho ta những chuyện này, bằng chính lời của ông, với ta. Ta biết hết từ thuộc hạ của ông. Nhưng chính Buldrokkas’tee không chịu nói với ai cả. Lão già cứng đầu như quái vật ấy, với trái tim mong manh đầy những lỗ hổng.”","“Đội của ông đã đi qua bốn khu mỏ trước khi cứu bọn ta. Những đứa trẻ ở bốn trại ấy không may mắn như bọn ta. Họ tìm thấy xác chúng bị chôn vùi trong những khu mỏ sụp đổ, và đại đội lính thi hành án thì không thấy đâu nữa. Ông tìm thấy gì ở ta? Tình thương? Sự cứu chuộc? Hay chút an ủi tâm lý? Ta không chắc.”","Cô ta ho, máu rỉ ra nơi khóe môi.","“Ho và chảy máu trong cũng là triệu chứng của… bệnh của cô sao?”","“Có lẽ, có thể. Có lẽ chỉ là hậu quả của việc ta dùng Arts quá mức thôi. Hôm nay khá căng thẳng. Chuyện như thế này mới chỉ xảy ra một lần trước đây. Bất tỉnh, tê liệt toàn thân, không cử động được kể cả khi tỉnh, đều đã từng xảy ra. Ta hiểu cơ thể mình.”","“Cô không được dùng Arts nữa.”","“Ồ, giờ ngươi định chiến đấu thay ta à?” FrostNova nghiêng đầu. “Người Rhodes Island… Ta nên gọi ngươi là gì?”","“Cô có thể gọi tôi như các operator Rhodes Island gọi.”","“Doctor?” Cô ta lặp lại cái tên, như thử nó trên lưỡi. “Doctor. …Ta thừa nhận người Rhodes Island các ngươi biết đánh. Nhưng ta vẫn không tin các ngươi. Chưa kể các ngươi lẽ ra là một công ty dược phẩm.”","“Rhodes Island làm nhiều việc lắm.”","“Những gì xảy ra ngoài chiến trường không phải việc của ta. Ta đã xem ngươi chiến đấu ở Chernobog. Ngươi có lập trường vững vàng, điều ta đã tận mắt xác nhận, nhưng ta không đánh giá được tính cách của ngươi. …Ta nghe nói Alex chết dưới tay các ngươi. Điều đó khiến ta nghi ngờ con đường của các ngươi. Giờ, ta không thể để ngươi rời Chernobog mà gây thêm tổn hại cho người Infected của Reunion. Nhưng ngươi lại sẵn lòng nghe ta nói nhảm ngần ấy… Ta sẽ giả định ngươi không hoàn toàn giống như những người Infected khác mô tả.”","“Họ chỉ sợ thôi.”","“Ai mà không sợ kẻ mang đến cái chết chứ? Doctor, ngươi có sợ không, ngay lúc này?”","“Tôi không chắc.”","“Thú vị. Ngươi không sợ sao? Ta đoán những kẻ không sợ chết thì chẳng còn mấy tình yêu với thế giới.” FrostNova nhìn lên trần đá. “Một câu hỏi ta nghĩ đến suốt… ‘Ta có sợ chết không?’ Ta nghe nói đám đồn trú Ursus gọi ta là Công chúa Yeti, là Cái Chết Mùa Đông… Sự thật là, bọn ta chỉ là vài đội lèo tèo lang thang trên lãnh nguyên, sống lay lắt qua ngày.”","“Arts của ta mạnh, ta đã chứng minh điều đó với cả kẻ thù lẫn đồng đội. Đương nhiên, cơ thể ta, như ngươi thấy, chỉ là cơ thể của một bệnh nhân Oripathy. Ta thấy mình đặc biệt, không phải vì bệnh tật, mà vì những cảm xúc mà băng giá gieo vào ta. Ta coi năng lực của mình là một phước lành, nhưng Buldrokkas’tee, lão già khó tính ấy, lại coi nó như một lời nguyền.”","“Ta không cảm thấy lạnh khi lội qua bùn sâu trong đầm lầy, nước băng ngấm vào chân. Lão già không cho ta ra trận, kể cả khi binh lính của ông chịu thương vong nặng nề. Ông thắp đèn dầu và ngồi lặng lẽ một mình bên bàn. Ta nghĩ ông đang khóc, nhưng không chắc, và ta không biết có nên an ủi ông không.”","“Năm thứ năm, ta lần đầu triệu hồi một dòng khí lạnh trước mặt kẻ thù. Một tên lính bị đóng băng thành một khối, một tên khác vô tình ngã lên khối băng, và cả hai vỡ thành từng mảnh. Ta tham chiến, binh lính nhìn ta với ánh mắt kính sợ, anh chị em ta tự hào về ta, và những người Infected khác nói— ‘Đó là chị của chúng ta. Chị ấy đã cứu mạng tất cả chúng ta.’”","“Arts của ta có thật sự cứu được ai không? Những đứa trẻ từ khu mỏ mang theo những tinh thể Originium ta tạo ra, và chúng ta trở thành ‘Biệt đội Yeti’. Những tinh thể ấy tỏa ra cái lạnh của ta, và chúng ta mang băng giá và báo thù đến với kẻ thù của người Infected. Nhưng đó thật ra… chỉ là cái lạnh. Cái lạnh của mùa đông không sinh ra sự sống mới. Dù vậy, ta thấy mình rất may mắn. Vì anh chị em ta có thể sống sót. Chúng ta có thể sống trên thế giới này.”","“Cô từng muốn chung sống với người bình thường chưa?”","“Người bình thường…” FrostNova lặp lại. “Ngươi nói người bình thường là ai? Những công dân Chernobog không vũ trang nhưng ánh mắt lạnh lùng nhìn người Infected bị xử tử? Hay đám lính nghĩa vụ Ursus trong mỏ tận hưởng việc bắn bọn ta? Mỗi lần nghĩ đến những gương mặt của đám cai ngục, ta nghiến răng và mơ tưởng cắt cổ họ rồi uống máu họ…”","Cô ta im lặng một lúc.","“Nhưng ta không ghét người Ursus. Khi đội du kích của bọn ta lê bước qua tuyết, rút khỏi thung lũng, thậm chí bị quân đội Ursus truy đuổi… Chính người Ursus đã đặt vài cốc bia lúa mạch bên cửa sổ. Người Ursus chưa bao giờ là những sinh vật máu lạnh. Kẻ thù duy nhất của ta là Đế quốc Ursus đã hành hạ người Infected như vậy. Ta không coi người bình thường là kẻ thù. Những người Ursus được dạy phải căm ghét người Infected chỉ là những người bình thường cho đến khi họ bị thù hận làm mù quáng. Chỉ vì ‘kẻ thù giết lẫn nhau’ nên chúng ta mới chiến đấu như vậy. Chỉ thế thôi. Ta là người Infected, đúng vậy… Nhưng trước đó, ta là một người bình thường.”","“Còn những gì Reunion đang làm bây giờ thì sao?”","“…Mâu thuẫn chính của ta với Buldrokkas’tee nằm ở công việc bảo vệ cộng đồng người Infected của ông.” FrostNova hạ giọng, nói chậm rãi, ngắt quãng từng chữ, như bắt chước một người khác. “‘Reunion, cái tên đầu tiên. Đó. Người Infected, có thể dựa vào. Dù ở đâu, Reunion đi. Dù gì, nó làm. Chúng ta không thể, bỏ rơi nó. Mất Reunion, là mất, niềm tin của người Infected. Chiến đấu vì: niềm tin.’ Đó là điều lão già nói. Đó là điều lão già tin.”","“Sao cô cứ ngắt quãng như vậy?”","“Vì giờ ông nói chuyện như thế. Ta chỉ đang, e hèm, giữ nguyên nhịp điệu của ông thôi.” Cô ta quay sang. “Doctor, ngươi có biết vì sao Rhodes Island là một công ty dược phẩm vô danh không? Vì các ngươi không thể đứng ra lập trường trên vũ đài thế giới. Ngay khi bước bước đó, các ngươi sẽ trở thành như Reunion bây giờ. Các ngươi sẽ đi con đường này.”","“Có lẽ.”","“Hừm.” FrostNova nhắm mắt lại. “Sau hơn chục năm lăn lộn trên lãnh nguyên, một người phụ nữ Infected tìm đến bọn ta. Cô ấy nói: ‘Đi với tôi, và chúng ta hãy phá bỏ mọi xiềng xích.’ Hãy tưởng tượng: chúng ta gặp nhau trong phế tích một thành phố cũ đã thành chiến trường. Cô ấy chỉ có một mình, chẳng mang theo gì ngoài danh sách và một cuốn sổ sách. Ngay cả những điều cô ấy nói, ta cũng thấy viển vông đến mức nực cười. Nhưng cô ấy nói với bọn ta: ‘Đi với tôi.’”","“Cô ấy chiến đấu cùng bọn ta, và bằng sức mạnh cùng lý tưởng của mình, cô ấy trở thành bạn của bọn ta. Cùng nhau, chúng ta rời những cánh đồng tuyết, tiến về các thành phố của Ursus. Dù là những lời cô ấy thốt ra sau khi dừng lại suy nghĩ, hay nhát chém của thanh đại kiếm khi cô ấy vung cùng ta, sức mạnh của cô ấy là thật, và rất ấn tượng. Khi người bị thương cần chữa trị, cô ấy ở đó. Khi bàn về chiến lược và triết lý với người Infected, cô ấy ở đó. Và khi chiến đấu chống lại các đội tử thần Ursus, cô ấy cũng ở đó.”","“…Bọn ta thậm chí còn được ăn cùng vài người bình thường. Cô ấy không bận tâm. Trong mắt cô ấy chẳng có gì ngoài sự chân thành thuần khiết nhất. Đội của bọn ta lớn dần, và tình bạn cũng vậy. Những người được đưa vào đều giỏi chiến đấu, và đều là người tốt. Khi ấy, ta coi cô ấy là bạn. Cô ấy lặng lẽ giúp ta làm những viên kẹo này, dù cô ấy làm dở tệ và chúng còn tệ hơn. Cô ấy làm một khuôn mặt buồn cười khi ăn chúng. Rồi cô ấy gượng cười với ta. Thật là… Cô ấy cố gắng tỏ ra dũng cảm đến thế. Khiến ta bật cười.”","“Giờ mọi thứ đã khác. Chernobog bị Catastrophe phá hủy, như ngươi thấy rõ. Mọi người bình thường ở đây đều đã chết hoặc trở thành người Infected mới. Ánh mắt họ đã chết. Không còn chút khát khao sống nào nữa. Nếu đây là điều cô ấy muốn, thì lẽ ra chúng ta không bao giờ nên theo cô ấy.”","“Và nếu ngươi chưa biết, đây là một bí mật… Cô ấy đang lên kế hoạch chiếm Lungmen. Cô ấy nói sẽ không như Chernobog, rằng người Infected sẽ có thành phố của riêng mình thay vì một phế tích khổng lồ như nơi này. Ngươi có tin người như thế không? Nếu cô ấy đang diễn, thì cô ấy là nữ diễn viên vĩ đại nhất thế giới từng thấy.”","“Nhưng có một ý nghĩ cứ mắc kẹt trong đầu ta. ‘Nếu ta đối đầu với cô ấy, cơ hội thắng của ta là bao nhiêu?’ Một khi chúng ta chia tay, một khi ta phát hiện cô ấy đã lừa dối người Infected, hay đang âm mưu chống lại họ… Ta sẽ chiến đấu với cô ấy. Cô ấy phải biết cái giá của sự phản bội. Vô số trận chiến sinh tử với Ursus đã gột rửa tâm trí và mài giũa kỹ năng của ta. Ta nói với niềm tin tuyệt đối: kể cả không đánh bại được cô ấy, ta cũng có thể để cái chết mang cô ấy đi khỏi thế giới này cùng ta.”","“Lão già cứng đầu sẽ không đồng ý với ta. Ông đã chiến đấu quá lâu, và tuổi già đang đẩy ông vào con đường chỉ dẫn đến hy sinh.”","“Cô không đồng ý với cách của cha cô.”","“Ông mạnh mẽ trước kẻ thù và trung thành với bạn bè. Nhưng khi cần đứng lên vì họ, ông sẽ đối mặt với sự thật rằng bạn bè khiến ông yếu đuối. Lão già đã tin người cả đời… Lão già khó tính ấy chưa bao giờ nghĩ sẽ làm gì sau khi bị phản bội. Có lẽ ông đã nuốt viên thuốc đắng ấy rồi. Ông chịu đựng nỗi đau bị phản bội hết lần này đến lần khác suốt cuộc đời, và ông chẳng nói gì cả. Dù là người Infected nghe nói về Reunion rồi quyết định gia nhập, hay người Infected nghĩ mình có thể làm gì cũng được. Reunion đang chia bè phái, và các thủ lĩnh của chúng ta chẳng làm gì để ngăn chặn.”","“Ta chắc chắn sẽ quay về Chernobog sau khi chuyện ở Lungmen kết thúc. Lần này, ta phải đối mặt với cô ấy. Vì… ta không còn sống được bao lâu nữa.” Giọng cô ta nhỏ dần. “…Ta đã hứa với các em ta sẽ tìm một mái nhà cho mọi người. Trước khi ngã xuống, ta phải giữ lời hứa…”","“Tại sao cô kể cho tôi nghe tất cả những chuyện này?”","“Vì ánh mắt của ngươi cho ta biết ngươi không chỉ là một kẻ hành quyết khác.”","“Tôi không chắc mình có phải không.”","“Tốt nhất là nên nghi ngờ bản thân. Đó là cách duy nhất để ngươi không sống cả đời trong niềm tin cuồng tín vào điều gì đó.” FrostNova ngẩng đầu, lắng nghe. “…Ngươi có nghe thấy tiếng người bên ngoài không? Nghe như họ đang đào phía trên chúng ta. Và cơ thể ta…” Cô ta nhìn xuống bàn tay mình. Những ngón tay khẽ co lại. “Chà… Ta đã cử động được ngón tay rồi. Cảm ơn.”","“Vì cái gì?”","“Cảm ơn vì đã giúp ta giết thời gian.” Một nụ cười mờ nhạt. “Doctor, ta muốn đánh cược với ngươi. Nếu người của ngươi đào chúng ta ra trước… Ta sẽ giết tất cả các ngươi trong chớp mắt. Nếu anh chị em của ta phá được vào trước, mạng sống của ngươi kết thúc ở đây.”","“Cược không?”"],"bg":"bg_indoor_f","cast":[["FrostNova","npc:char_1505_frstar_1"]]},{"c":"6-14","t":"Sương giá trên lãnh nguyên","p":["“Những… những người Yeti…” một thành viên Reunion lẩm bẩm, nhìn về phía chiến trường giờ đã im lặng. “…Tôi thấy thương họ quá, chết hết ở Lungmen như vậy. Lại thêm một niềm hy vọng, một huyền thoại của người Infected mất đi.”","“Đi thôi. L.G.D. đang đến.”","“Tôi biết,” Nine nói.","“…Mắt cô có gì đó không ổn. Nói thật, tôi luôn nghĩ cô là gián điệp của Lungmen.”","“Còn bây giờ?”","“Đằng nào cũng chẳng ai tin.”","“Một gián điệp thật sẽ giết cậu để bịt miệng.”","“Tôi không lo cô giết tôi. Nhìn Lungmen bây giờ đi. Kể cả cô là người Lungmen, cô cũng không quay về được nữa. Cô sẽ còn khổ hơn bọn tôi.”","“…Vậy thì tôi không phải. Tôi chẳng còn là gì nữa.” Nine cúi xuống. Từ đầu ngón tay cô, một bông hoa nhỏ màu trắng nở ra, rơi xuống mặt đường loang lổ máu.","“Cô làm gì vậy? Ồ, đó là hoa à? Ồ, đây là Arts của cô à? Đẹp thật.”","“Phải có ai đó để lại cho họ một chút tôn kính.”","@bg:bg_indoor_f","Trên một mái nhà khác, vị Ngự sử mặc y phục trang nghiêm đứng nhìn xuống, cùng vài người khác.","“Thật lề mề… thật lãng phí thời gian,” Ngự sử nói.","“Tôi nghĩ làm vậy là tốt,” một người đàn ông nói. “Tôi có thể cho điểm tuyệt đối vì đã quét sạch toàn bộ Reunion Movement trong thành phố Lungmen chỉ trong một ngày. Wei Yenwu thật ấn tượng. Taihe, bà đã nghe lời đồn đó chưa?”","“Ông nói về quá khứ của Wei Yenwu?” Ngự sử hỏi.","“Đừng đào sâu vào những chuyện đó,” Taihe nói.","“Thứ lỗi. Nhưng kỹ năng của đám Áo Choàng Đen so với Cận vệ Hoàng gia thì thế nào?”","“Hừ. Ông đánh giá chúng quá cao. Nhưng chúng đúng là có vài kỹ năng đặc biệt…”","“Cẩn thận!” Taihe hét.","“Lũ khốn!!!”","Một bóng người lao tới, chiếc cưa máy rực lửa.","“—Infected?” Ngự sử nhíu mày.","Một sợi dây mảnh như tơ quấn quanh lưỡi cưa, giữ nó lại ngay trước mặt họ.","“—Dây?!” Blaze nghiến răng.","“Cô không thật sự muốn giết tôi, phải không?” người đàn ông cầm sợi dây nói, giọng điềm đạm. “Cô có thể dùng Arts mà.”","“Tôi luôn nghe nói đàn ông dùng dây làm vũ khí đều là, thật sự là tất cả, lũ tâm thần.”","“Quả thật, người ta nói vậy…”","“Người Infected, đừng can thiệp vào công vụ,” Ngự sử nói. “Cẩn thận ta gộp ngươi chung với những kẻ khác.”","“Những đơn vị vũ trang không rõ danh tính bị giết trên chiến trường thì cũng chẳng làm gì được, phải không?” Blaze gằn giọng.","“Chúng tôi cũng có thể làm chứng rằng cô đang phối hợp với Reunion.”","“Các người không có thẩm quyền điều tra cộng sự của tôi.”","Ch’en bước ra từ sau một ống khói, thanh kiếm chưa rút nhưng tay đã đặt lên chuôi.","“Chúng tôi biết rõ có một con tàu thuộc về một ‘Chuyên gia Đối phó Người Infected’ đang neo ở bến Lungmen, Tổng Thanh tra Ch’en,” người đàn ông nói. “Đó là lý do duy nhất cô Blaze chưa bị tổn hại.”","“Vậy các người còn cần thấy bao nhiêu nữa? Còn phải thử thách người dân thành phố này bằng chính mạng sống của họ bao nhiêu nữa?”","“Nói năng cho đàng hoàng,” Ngự sử nói. “Chúng ta đang đánh giá năng lực kiểm soát rủi ro của Lungmen vì chúng ta coi trọng các ngươi.”","“Vậy thì thứ lỗi. Để tôi nói lại.” Ch’en nhìn thẳng vào họ. “Các vị có thích màn kịch này không?”","“Phì,” Ngự sử nói.","“Lùi lại, Blaze. Chúng ta không phục vụ những vị cao quý đáng kính này, và họ cũng không cùng phe với bọn áo mưa.”","Sợi dây buông lỏng. Blaze lùi lại một bước.","“Xin lỗi, cô Blaze,” người đàn ông nói. “Mong tôi không làm cô phật lòng.”","“…Ông lịch sự thật đấy. Nhưng giọng điệu của ông làm tôi phát bực.”","“Cô nghe giỏi tiếng Yan đấy. Cô thừa hưởng nhiều từ cha mình. Tiếc thay, giờ cô chỉ là một người Infected. Con đường của cô gập ghềnh. Và ngắn ngủi.”","Blaze sững người. “…Ông……?”","“Đi thôi,” Taihe nói.","“Vậy tạm biệt, cô Blaze, Tổng Thanh tra Ch’en.”","“Khoan! Ông vừa nói gì về bố tôi?!” Blaze lao theo. “Đứng lại!”","“Blaze!” Amiya chạy tới.","Blaze đứng im.","“Nhớ nhiệm vụ!”","“…Đúng vậy.”","","“Sĩ quan Ch’en,” Amiya nói.","“Chúng tôi không tìm thấy dấu vết của chỉ huy địch.”","“Người nào?”","“Chúng tôi chỉ biết Mephisto.”","“Để Rhodes Island lo phần còn lại.”","“Không cần vội. Chiến dịch này gần như đã kết thúc.”","“Nhưng hắn phải trả giá… cho những tội ác hắn đã gây ra.”","“Vậy giao cho các cô.” Ch’en quay đi. “Tạm chia tay ở đây. Tôi còn một việc cần tận mắt xem.”","“Khoan đã, cô L.G.D.,” Blaze gọi.","“Gì vậy?”","“…Cảm ơn vì chuyện lúc nãy. Thế thôi.”","“Ừ. Cô cũng vậy.”","","“Sao chị lại hành động đúng lúc đó?” Amiya hỏi khi chỉ còn hai người. “Blaze… Chị không phải loại người phạm sai lầm vào lúc như thế này.”","“Một là, tôi thật sự rất giận… Hai là, tôi thấy cô L.G.D. kia, Ch’en, cũng đang giận.”","“Bọn mình cũng không biết bên nào có quyền lên tiếng.”","“Nên tôi chọn bên tôi thích.” Blaze cúi đầu. “Xin lỗi. Sẽ không có lần sau.”","“…Không, Blaze. Đến lượt em nói sẽ không có lần sau mới đúng.” Amiya nhìn về phía chiến trường im lặng. “Nhưng em không thể nói vậy. Em không thể hứa điều đó. Những người Yeti…”","Blaze im lặng một lúc. Rồi cô đặt tay lên đầu Amiya. “Thỏ ngốc.”","“Này, đừng xoa đầu em. Em còn cần cao lên…” Amiya ngập ngừng. “…Ít nhất, đừng xoa lâu quá.”","“Biết rồi, biết rồi.”","","“Người thấy thế nào?”","Doctor quay lại. “Cô.”","“Tôi đi ngang qua,” Kal’tsit nói. “Trạng thái cảm xúc của người đang dao động. Có vẻ người đã có một cuộc tương tác sâu sắc hơn với đơn vị Reunion này ở phế tích Chernobog. Theo những gì tôi biết, đội trưởng của đơn vị này không tham gia trận đánh.”","“Nghĩa là…”","“Lungmen sẽ không tiếp tục truy đuổi những người Infected này. Nhưng Rhodes Island phải làm nhiều hơn. Lungmen sẽ không can thiệp vào những gì xảy ra tiếp theo. Và người có thể chọn không tham gia.” Cô ta ngừng lại. “…Nhưng người sẽ tham gia. Dù người Infected đó có mật danh là ‘Mephisto’ hay ‘FrostNova’.”","“Cô đi đâu vậy?”","“Tôi còn nhiều việc phải làm.” Kal’tsit quay đi, rồi dừng lại. “À, còn nữa, Doctor… Đừng nhìn tôi như thế.”","“Amiya nói Rhodes Island cần lòng tin.”","“Nhưng người và tôi không cần lòng tin. Người cần lòng tin của các operator Rhodes Island, không phải của tôi. —Tôi biết người quá rõ để có thể tin người. Cũng như người chưa bao giờ tin tôi, ngày xưa.”","“Ngày xưa?”","Kal’tsit đứng im rất lâu.","“…Đúng vậy.” Một quãng lặng. “Tôi lỡ lời. Quên đi.”","“Cẩn thận trong chiến dịch tiếp theo. Chỉ có những chỉ huy nguy hiểm nhất mới huấn luyện được một đội người Infected chiến đấu đến chết mà không chùn bước. Đương nhiên, có muốn đi đến cùng hay không là do người. Và nhớ giữ sức. Có thể ta sẽ không có thời gian nghỉ.”","“Trận chiến Lungmen đã kết thúc rồi.”","“Không đơn giản như vậy. Ít nhất, tôi nghĩ vậy.” Kal’tsit quay lại lần cuối. “Doctor, từ giờ trở đi, người phải tự quyết định có gánh vác trách nhiệm cho Rhodes Island hay không… ‘Có trở thành người xứng đáng với lòng tin của một operator Rhodes Island hay không.’”","@bg:bg_undergroud_n","Ở một nơi xa, ngoài rìa thành phố, FrostNova mở mắt.","“A, FrostNova, chị tỉnh rồi…” một Nỏ Thủ Bóng Ma vội chạy đến. “…Từ từ thôi! Để tôi đỡ chị.”","“Ta không sao. Ta không… yếu đuối đến thế.” FrostNova chống tay đứng dậy, nhìn quanh. Rồi cô ta khựng lại.","“Chị đi đâu vậy? Chị không thể quay lại.”","FrostNova im lặng. “…Vậy, các em của ta…”","“…Chị không thể quay lại! Chính vì chị mà họ…”","“Đừng xúc phạm đội của ta!” FrostNova quát.","Người Nỏ Thủ lùi lại.","“Họ đã… khụ… chăm sóc ta. Nhưng chính vì người Infected mà họ đã dũng cảm hy sinh! Họ chiến đấu trận cuối cùng để nhiều người hơn được sống, không phải vì bất kỳ một ai! Khụ khụ… khụ… Guh… Mmg…”","“FrostNova, thưa chị…”","“Thôi ‘thưa chị’ đi. Ngươi gọi ta như vậy vì trông ta yếu ớt sao?”","“…! Xin lỗi! Chỉ là, họ đã giao chị cho bọn tôi như vậy.”","“Và giờ họ đã đi rồi, mà ta chưa kịp giữ lời hứa với họ. Ta thậm chí không có cơ hội chuộc lỗi.” FrostNova nhìn về phía Lungmen, nơi khói vẫn bốc lên. Rồi ánh mắt cô ta dừng lại ở một góc tường. “…Kẻ đang ngồi gục bên tường kia. Mephisto. Hắn vẫn bất tỉnh à?”","“Bọn tôi không biết. Anh ta cứ như vậy suốt. Không nói gì. Không làm gì.”","FrostNova nhìn thiếu niên tóc trắng đang ngồi bất động, đôi mắt trống rỗng nhìn vào khoảng không.","“Đưa hắn về đi. Thế là đủ rồi.”","“Đã hiểu. Phù, tôi tưởng chị sẽ…”","“Ta sẽ gì?”","“Tôi tưởng chị sẽ giết anh ta.”","“Không cần nữa rồi. Ta nghĩ ta biết chuyện gì đã xảy ra bên ngoài khu ổ chuột. Ánh mắt thất thần đó của hắn… Và, thỉnh thoảng… Ta nhớ lại một ngày, ba bốn năm trước, khi hắn cố hết sức để hát.”","“Anh ta biết hát à? Nhưng Faust nói, cổ họng anh ta…”","“Hắn đã thật sự cố gắng. Giống như tất cả người Infected chúng ta. Dù tất cả chúng ta rồi sẽ có ngày gục ngã vì Oripathy… Chúng ta vẫn cố hết sức để sống.” FrostNova quay đi. “Hãy để phần đời còn lại tiếp tục trừng phạt hắn.” Rồi cô ta hỏi. “Nói ta nghe, Nỏ Thủ Bóng Ma, Rhodes Island có tham gia trận đánh đó không?”","“Ý chị là…? …Không, theo tôi biết, họ không đánh Yeti.”","“…Thật trẻ con,” FrostNova nói khẽ.","“Chị chắc là muốn ở lại chứ? Có thể họ sẽ không đuổi theo ta, FrostNova. Chị không cần chết ở đây.”","“Ta đã gặp vài người trong phế tích. Ta muốn gặp lại họ. Thật ra, ta đã hứa với họ. Và ta biết họ sẽ đến.”","“FrostNova…”","“Đi đi, em trai. Reunion thua trận này. Và có lẽ, Reunion đã làm sai. Nhưng em thì chưa. Em vẫn còn lựa chọn, em có thể làm tốt hơn. Đi đi. Và đừng ngoái lại.”"],"bg":"bg_indoor_n","cast":[["FrostNova","npc:char_1505_frstar_1"],["Kal'tsit","op:char_003_kalts"],["Blaze","npc:char_017_homura_3"],["Amiya","op:char_002_amiya"],["Ch'en","op:char_010_chen"],["Censor","npc:avg_npc_039_1"],["Nine","npc:avg_npc_043_1"],["Taihe","npc:avg_npc_040"]]},{"c":"6-15","t":"Hoài niệm","p":["<i>12:21 trưa.</i><br><i>Phế tích “Quận 14” của Chernobog. Bề mặt khu vực.</i>","“Cái quái gì vậy?” một Caster Reunion quát. “Biệt đội Yeti, sao các ngươi ngừng bắn? Đang chờ gì vậy?”","“…Đào phế tích đó lên, hả?” thành viên Yeti mà sau này Rhodes Island gọi là Yeti Số 1 đáp.","“Chẳng phải các ngươi đã cài Originium sao? Sao không làm sập cả tấm đế, xóa sổ Rhodes Island một lần cho xong?”","“Ngươi đùa à? FrostNova vẫn còn ở dưới đó!”","“Vậy bọn ta sẽ xử lý Rhodes Island. Các ngươi cứ đào tiếp. Bọn ta đến ngay.”","“Không phải ở dãy nhà này! Kết cấu khu này đã nát bét rồi. Một đội không qua huấn luyện đánh nhau ở đây có thể gây sập hoàn toàn!”","“Tiêu diệt Rhodes Island là ưu tiên hàng đầu. Các ngươi lo việc đó.”","“Tôi không cãi với các anh. Bọn tôi sẽ đánh những gì phải đánh. Mà ai quyết định cái ưu tiên này vậy?”","“Rõ ràng đó là mục tiêu chiến lược quan trọng nhất của chúng ta.”","“Lúc các anh trút giận lên người Ursus, các anh có nghĩ đến mục tiêu chiến lược không? Bọn tôi sẽ làm những gì có thể. Cho bọn tôi chút không gian.”","“Các ngươi… đã liên lạc với Rhodes Island sao? Các ngươi đang phản bội Phong trào!”","<i>(Bên đó có chuyện gì vậy?)</i> Blaze thì thầm qua kênh mà hai bên vừa bắt được.","<i>(Tôi nghĩ ta phải đánh rồi.)</i>","“Nếu ngươi nghĩ liên lạc đồng nghĩa với phản bội thì tùy ngươi,” Yeti Số 1 nói. “Với lối tư duy chiến thuật đó, chẳng lạ gì các ngươi bị dắt mũi.”","“…Biệt đội Yeti! Các ngươi định làm gì?! Bọn ta đông gấp trăm lần, đừng ngu ngốc!”","“…Thôi nào, bọn tôi đã đánh Quân đội Thường trực Ursus cả triệu lần rồi, ai lại phấn khích vì một đám đông giận dữ chứ?”","“Cứ chờ đấy!”","Tiếng rè rè. Rồi Yeti Số 1 quay sang kênh bên kia. “Này, Rhodes Island. Có lẽ bọn tôi phải dạy cho lũ khốn vô kỷ luật kia một bài học. Các cô nên đứng ngoài thì hơn. Bọn tôi không muốn bị buộc tội cấu kết với kẻ thù.”","“Hả? Cấu kết? Anh nói gì vậy?” Blaze quay sang. “Amiya, chuyện gì đã xảy ra ở phế tích, và phiên bản chính thức là gì?”","“…Không có gì xảy ra cả,” Amiya nói. “Bọn mình đánh với Biệt đội Yeti, và không có đơn vị Reunion nào khác tham chiến.”","“Diễn à? Tôi là diễn viên xuất sắc lắm đấy. Ta diễn một màn rồi xử lý đám kia trong lúc hỗn loạn thì sao?”","“Nghe được đấy. Đội trưởng của các cô nghĩ sao?”","Amiya im lặng một lúc. “Xin lỗi, thưa anh. Em nên gọi anh là gì?”","“…Ờ, cô là một cô bé rất dễ thương, nhưng tôi không chắc mình đã sẵn sàng cho chuyện như thế…”","“Sẵn sàng cho chuyện gì? Anh đang nghĩ gì vậy?!” một đồng đội quát.","“Ờ, xin lỗi. Tôi đùa thôi. Cô cứ gọi tôi là Yeti Số 1.”","“Được rồi, anh Yeti Số 1… Chúng ta có người cần cứu, phải không? Vậy hãy khống chế những đơn vị Reunion có thể cản trở nhiệm vụ giải cứu.”","“Ừ. Giờ thì tôi đầy động lực rồi.”","“…Và anh lấy động lực đó từ đâu vậy?” Blaze hỏi.","","<i>(Blaze. Em cần chị dẫn đội giành thế chủ động.)</i> Amiya thì thầm.","<i>(Em muốn tổ chức một cuộc đột kích à?)</i>","<i>(Em rất lo về tình hình hiện tại. Cả bọn mình và Yeti đều đã dùng kỹ năng của mình để xác định vị trí Doctor và FrostNova. Nhờ Arts của chị, họ hiện đang an toàn. Và… hai người ở rất gần nhau. Cứu được một người là cứu được người kia. Lúc này có hai điều bọn mình chưa chắc. Thứ nhất, ai sẽ đến chỗ họ trước…?)</i>","<i>(Thứ hai, thái độ của FrostNova.)</i>","<i>(Chính xác. Nếu bọn mình giành thế chủ động, bọn mình phải khống chế FrostNova ngay. Nhưng cũng phải đổi cô ấy lấy sự hợp tác của Biệt đội Yeti. Như vậy, ta tránh được giao tranh, và còn mở rộng cơ hội giao tiếp. Nhưng nếu họ đến trước…)</i>","“Ừm, Amiya,” Jessica gọi, “máy dò nhịp tim tìm thấy gì đó. Có vị trí rồi, nhưng chưa biết độ sâu…”","“Đúng rồi!” Amiya lao đi ngay.","“Này… Chờ đã! Vội gì thế? Ôi.” Blaze nhìn theo.","“Hễ cứ Doctor xuất hiện là con bé hoảng lên quên hết cả,” Meteorite nói. “Tôi không chắc đây là lỗi của Amiya hay là đặc tính nữa…”","“Cô biết không, mấy điều con bé vừa nói, chẳng giống con bé chút nào. Con bé nghĩ ra nhanh quá.”","“Ít ra con bé không đi đến chuyện đánh lén. Lần này là lỗi của ta.”","“Không hẳn. Nếu ta phục kích họ, Yeti sẽ chiến đấu đến chết. Tôi đến đây để cứu tất cả mọi người, không phải gây thêm thương vong. Con bé không từ bỏ kết cục mà mình có thể thắng.”","“…Tôi đoán tôi nên xin lỗi. Là thói lính đánh thuê trong tôi.”","“Cô đâu có làm, đúng không? Giữ được cái đầu lạnh sau chiến thắng và bám sát mục tiêu chiến thuật là điều khiến tôi tin Amiya làm chỉ huy chiến trường.” Blaze đứng dậy. “Tôi đi xem Yeti thế nào.”","","“Kết cấu này… Phức tạp quá. Làm tôi đau đầu,” Yeti Số 1 lẩm bẩm.","“Mô tả đi, tôi vẽ ra cho,” một đồng đội nói.","“Hả? Hồi cấp hai tôi còn chưa học xong sách lớp tám. Tha cho tôi đi.”","“Thay vì đi học thì anh làm gì?”","“Đi tập luyện. Sao không để Nesti thử? Cậu ấy có chút Arts mà.”","“Cậu ấy chỉ giỏi ngâm thơ viết văn. Mấy việc dò kết cấu không phải chuyện của cậu ấy. Thử diễn đạt bằng con số xem?”","“Ý hay. Tôi cũng tạm giỏi toán. Thử xem.” Rồi anh ta khựng lại. “Có thấy nóng không? Không, tôi đang mặc thứ đồ dày cộp này mà vẫn thấy Originium của Chị làm da tôi đóng băng…” Anh ta quay lại. “Ồ. Chào con mèo Rhodes Island.”","“Xin lỗi, khi tôi đổ mồ hôi, không khí quanh tôi nóng lên, rồi tôi lại đổ mồ hôi tiếp,” Blaze nói. “Nhờ các cậu mà tôi thấy mát hơn bình thường nhiều.”","“Cô lo lắng à?”","“Một chút. Tôi chưa bao giờ nghĩ sẽ làm việc với kẻ thù.”","“Ít nhất bây giờ thì ta không phải kẻ thù. Sau khi đào được Chị ra, bọn tôi sẽ làm theo lời Chị. Nhưng đến đâu hay đến đó.”","“…Các cậu thật sự chẳng giống những người Reunion khác chút nào.”","“Cô nghĩ phần còn lại của Reunion đều giống nhau sao? Cô và cô thỏ có giống nhau không?”","“Này, đúng rồi. Ý hay. Bên tôi cũng đủ loại người.”","“Ai cũng có đủ loại người cả.”","“Ít ra cô còn chịu nghe bọn tôi nói. Lính Ursus thì cứ thấy là bắn. Tên bắt đầu bay, và chúng không dừng lại cho đến khi một bên chết hết.”","“May mà bọn tôi là công ty dược chứ không phải lính Ursus.”","“Công ty dược nào cũng có trang bị như các cô à?”","“Thế giới nguy hiểm lắm, phải tự bảo vệ mình chứ, đúng không?”","“Giá mà các cô dành thời gian làm ruộng thay vì đánh nhau,” Yeti Số 1 nói, giọng bỗng trầm xuống. “Nếu trồng được một vụ lúa mì đỏ, các cô sẽ nuôi được nửa thị trấn người Infected đang chết đói. Nếu họ không đói, họ đã không đi vào thị trấn nhỏ đó. Rồi họ đã không bị bắn. Giá mà.”","“Thôi đủ rồi,” đồng đội anh ta nói.","“Anh ta đa cảm thật,” Blaze nói. “Cô biết không, tôi nghĩ người Ursus ai cũng khá đa cảm.”","“Đừng có lười!” một người khác quát.","“Úi, xin lỗi. Quay lại làm việc thôi.”","“Không sao đâu. Làm tiếp đi.” Blaze khịt khịt mũi. “Nhưng thứ anh đang mang theo kia, mùi nồng thật đấy.”","“Ồ? Cái này…? Tôi…”","“Cô ta nói gì vậy?” đồng đội anh ta hỏi.","“Không có gì. Đừng lo.” Blaze cười. “Này, hơi đói bụng rồi.”","“Ồ…?”","“Nhìn tôi làm gì vậy?” Yeti Số 1 hỏi.","","<i>3:22 chiều.</i><br><i>Phế tích “Quận 14” của Chernobog. Bề mặt khu vực.</i><br><i>Ba giờ sau khi bắt đầu chiến dịch đào bới.</i>","“Amiya, dừng lại!” Meteorite nắm lấy tay cô bé. “Ngón tay cô chảy máu rồi! Đừng đào bằng tay nữa!”","“Nhưng… Em cảm nhận được gì đó dưới đó… Ngay dưới đây!” Amiya vùng ra, tiếp tục cào vào đống gạch vụn. “Dùng dụng cụ thì em không cảm nhận được… Em phải dùng ngón tay để nhận ra cái cảm giác thì thầm nhỏ xíu đó…”","“Amiya!”","“Gần lắm rồi!”","<i>(Meteorite…)</i> Blaze thì thầm.","<i>(Nhưng…)</i>","<i>(Để con bé làm đi.)</i>","“Nếu để họ đến trước…” Amiya lẩm bẩm.","Ở phía bên kia đống đổ nát, Biệt đội Yeti cũng đang đào.","“Không sao đâu, cậu làm được mà!”","“Dùng Arts! T-tôi không làm được. Tôi thật sự không làm được!”","“Kể cả không có Chị, ta vẫn làm được, đúng không? Nhanh làm nhiệt độ chênh lệch đi. Chênh càng lớn càng tốt!”","“Tôi sẽ thử… Nhưng không được thì đừng trách tôi!”","“Ngoài cậu ra thì còn trách ai được…?”","“Đừng trêu cậu ấy. Cậu ấy phải tập trung.”","“Đây! Ngay đây!” Amiya hét lên. Rồi ngón tay cô bé chạm vào một bức tường bê tông. “…Một bức tường? Mình nhầm sao? Cứ đập vỡ nó! Phá xuyên qua…! Nhưng nếu nó sập, mình sẽ…” Giọng cô bé lạc đi. “Mình… nhầm rồi.”","“Mở rồi!” Yeti Số 1 hét lên từ phía bên kia.","Amiya đứng sững. “…!”","“Blaze! Meteorite!”","“Đang đến,” Meteorite nói.","“Chuẩn bị,” Blaze nói.","","Trong khoảng trống tối tăm bên dưới, ánh sáng tràn vào từ một lỗ hổng phía trên. Không phải phía Rhodes Island đang đào.","“Cô thắng rồi,” Doctor nói.","“Đã bảo ta sẽ không thua mà,” FrostNova đáp.","“Cô có cho tôi lựa chọn nào để thắng đâu.”","“Chị!” Yeti Số 1 nhảy xuống. Rồi anh ta nhìn thấy người khoác áo trùm đầu. “……Người này…… Đây là người mà họ gọi là Doctor.”","“Vậy tôi bị bắn hay bị treo cổ đây?” Doctor hỏi.","Không ai trả lời. Vì Amiya đã nhảy xuống từ lỗ hổng phía sau, đứng chắn giữa Doctor và FrostNova.","“Thủ lĩnh của Rhodes Island,” FrostNova nói.","“Là em. Chị có thể gọi em là Amiya.”","<i>(Nhẫn của con bé… đang chuyển đỏ?)</i> Meteorite thì thào.","Blaze không nói gì.","<i>(Chị không định ngăn con bé à?)</i>","<i>(Sao tôi phải ngăn cơ hội chiến thắng duy nhất của ta?)</i>","“Blaze!”","“Tôi tôn trọng quyết định của Amiya.”","“Amiya, đừng,” Doctor nói.","“Doctor!”","FrostNova nhìn cô bé, rồi quay sang. “Nesti, Rhodes Island không đánh các em sao?”","“Họ không đánh.”","“Vậy thì trên chiến trường này, chúng ta không phải kẻ thù.”","“FrostNova…” Amiya nói.","“Không có lý do để chiến đấu nếu chúng ta không phải kẻ thù. Về đi, Doctor, về với người của ngươi.”","“…Chị của bọn ta thật quảng đại,” Yeti Số 1 nói.","“Như thể Chị cần anh tán thành,” đồng đội anh ta đáp.","“Im lặng nào,” FrostNova nói. Rồi cô ta quay sang Amiya. “Thỏ con.”","“Ờ, tên em là Amiya…”","“Ngươi cũng sẽ đến Lungmen, phải không?”","“…Đúng vậy.”","“Vậy chẳng bao lâu nữa chúng ta sẽ là kẻ thù, thỏ con. Chỉ là, chưa phải lúc này.”","“FrostNova, chị và đội của chị không tàn phá như những đơn vị Reunion khác.”","“Đừng trách người của ta. Ngươi không biết họ đã trải qua những gì.”","“Nhưng chị không muốn họ tiếp tục như thế này!”","“…Ồ?” FrostNova nheo mắt. “Có vẻ ngươi đọc được suy nghĩ của ta?”","“Em không đọc được. Nhưng em cảm nhận được nỗi bất an và sự giằng xé của chị.”","“Tất cả những điều này sẽ bị quét sạch sau khi Lungmen sụp đổ.”","“Rhodes Island, bọn em thật lòng hiểu được chị và đội của chị. Chị có thể nghĩ em sai, nghĩ bọn em chẳng hiểu gì cả… Nhưng chị FrostNova, em biết chính xác chị đã trải qua những gì.”","“……Thật trẻ con.”","“FrostNova, bộ áo đó không phải của cô, phải không?” Doctor hỏi.","FrostNova im lặng. Rồi cô ta nhìn xuống chiếc áo khoác lớn quá cỡ trên người mình. “…Không phải. Đây từng là áo choàng của ‘Patriot’. Ta đã may nó thành áo khoác.”","“…Ồ…” Amiya thì thào.","“Sao ngươi biết?” Rồi FrostNova lắc đầu. “Thôi bỏ đi… Ai cũng có vài điều không thể nói, ta đoán vậy.”","“FrostNova, Rhodes Island không tìm kiếm xung đột,” Amiya nói. “Bọn em muốn tránh đổ máu không cần thiết.”","“Vậy đổ máu nào là cần thiết?”","“Ít nhất, bọn em không muốn đánh với đội của chị! Họ đều là những người tốt, tử tế. Bọn em tuyệt đối không thể làm hại họ, hay để họ làm hại người vô tội!”","“…Vậy thì ngươi phải cầu nguyện chúng ta đừng gặp lại nhau.”","“FrostNova!”","“Ta nghĩ ta cũng không muốn làm hại ngươi lắm. Nhưng nếu buộc phải làm, ta sẽ giết tất cả các ngươi.”","“Cô có thể đến Rhodes Island. Chúng ta không cần phải đánh nhau,” Doctor nói.","“Vậy ngươi có thể thử đánh bại ta. Đánh bại ta trong trận chiến, ta sẽ cân nhắc. Nhưng đương nhiên, một khi gặp nhau trên chiến trường, chúng ta là kẻ thù. Và là kẻ thù, chúng ta sẽ chiến đấu đến chết.”","Amiya không nói gì.","“À phải.” FrostNova rút ra một lọ nhỏ, ném về phía Frostleaf. “Cái này, cho con cáo.”","“…Cái gì?”","“Một phương thuốc đặc biệt chữa tê cóng. Công thức độc nhất. Nó làm dịu cảm giác bỏng rát và đau đớn. Ta đã nghiên cứu mấy thứ này lâu lắm rồi. Và lúc nãy ngươi đã chiến đấu rất tốt. Trong mắt ta, những chiến binh sẵn sàng hy sinh bản thân là mạnh nhất.”","Frostleaf nhìn lọ thuốc trong tay, rồi cúi đầu. “…Cảm ơn.”","“FrostNova…”","“Này, khoan đã. Tôi cũng có điều muốn nói,” Blaze lên tiếng. “Yeti Số 1!”","“Ồ… hả?”","“…?” FrostNova nhìn quanh. “Chuyện gì vậy?”","“Lần sau đi uống một chầu nhé! Vodka của anh thơm lắm!”","“Đừng nói to thế!” Yeti Số 1 kêu lên.","FrostNova nhìn anh ta. Rồi nhìn Blaze. Rồi cô ta bật cười, một tiếng cười rất khẽ, như tuyết tan.","“Hừm. Haha… Tạm biệt, Rhodes Island. Mong là chúng ta không bao giờ gặp lại.”","","<i>Tầng kết cấu dưới của Lungmen.</i>","Giữa những cột thép khổng lồ, trong bóng tối lạnh buốt, có một người phụ nữ tóc trắng đang đứng chờ.","“……Chị ở đây thật,” Amiya nói.","“Chào cô, FrostNova,” Doctor nói.","FrostNova nhìn họ rất lâu. Hơi thở cô ta không còn bốc khói nữa. Vì không khí quanh cô ta đã lạnh đến mức không còn hơi nước nào để ngưng tụ.","“……Chào, Rhodes Island.”"],"bg":"bg_cher_11","cast":[["Amiya","op:char_002_amiya"],["FrostNova","npc:char_1505_frstar_1"],["Blaze","npc:char_017_homura_3"],["Yeti #1","npc:avg_npc_037"],["Meteorite","op:char_219_meteo"],["Frostleaf","op:char_193_frostl"]]},{"c":"6-16","t":"Thỏ đen, thỏ trắng","p":["“Trông cô ta… không ổn…” Blaze lẩm bẩm. “Những tinh thể Originium lơ lửng quanh cô ta… Sao có thể?”","“Là phân ly đẩy…!” Amiya nói.","“Những tinh thể Originium thấm qua da cô ta, kết hợp với phân tử nước trong không khí tạo thành băng đen sao?” Blaze nhìn những mảnh tinh thể đen nhô ra từ cánh tay, từ cổ, từ gò má FrostNova, như những chiếc gai mọc từ bên trong. “Thấm qua…? Thấm qua da?! ……Chết tiệt…… Chết tiệt!”","“Blaze!”","“Không đau sao! Như thế không đau sao?!!” Blaze gào lên. “Cô không thấy đau à, thỏ trắng? Đủ rồi… Thế là đủ rồi… Sao cô lại làm thế này? Dừng lại đi!”","“Mmmng….. Nnnng!” Amiya ôm lấy đầu.","“Amiya? Tôi không thích vẻ mặt của em… Khoan! Amiya, đừng làm thế! Đừng chạm vào tâm trí cô ta!”","“Em không làm! Em không dùng Arts! Nhưng cảm xúc của chị ấy… Cảm xúc của chị ấy đang tràn vào ý thức của em…!”","FrostNova nhìn họ.","“Ta đã chờ các ngươi. Các ngươi muốn giết chỉ huy của Reunion, phải không? Giờ cô ta đang đứng ngay trước mặt các ngươi. Mục tiêu của các ngươi đây. Nóng lên đi, nóng bỏng lên.”","“Nóng…?” Blaze nhíu mày.","“Đó là… cảm xúc của chị ấy…!” Amiya thở hổn hển.","“Đội, chờ lệnh!” Blaze hét. “FrostNova, ta không cần phí lời ở đây!”","“Lungmen đã lưu đày người Infected mà chẳng hề bận tâm họ có thể đi đâu. Họ sẽ không đến. Dù trong thành phố vẫn còn hàng nghìn người Infected… Lungmen đã phó mặc họ cho số phận. Sẽ không ai can thiệp vào trận chiến của chúng ta.”","“Ngần ấy người chúng ta… chống lại một mình cô?” GreyThroat hỏi.","“Còn gì nữa?”","“Thật lòng mà nói, bọn tôi hơi ít người,” Blaze nói. “Không ai đủ ngu để đối đầu trực diện với một trận tuyết lở. Nhưng thật ra, đối đầu trực diện với tuyết lở, tôi nghĩ tôi sẽ thắng? Nhưng cô là một trong những thứ… như kiểu toàn bộ cái lạnh trên thế giới tụ lại thành một tiêu điểm duy nhất. Tôi cứ nghĩ Biệt đội Yeti của cô đang đẩy năng lực của cô đến giới hạn, khiến Arts của cô mạnh và hiệu quả hơn. Tôi sai rồi. Họ không làm cô mạnh hơn. Chính Arts của cô làm họ mạnh hơn.”","“Chừng nào các em ta còn ở bên, ta không thể mạo hiểm làm họ bị thương bằng cách giải phóng toàn bộ sức mạnh,” FrostNova nói. “Nhưng giờ. Họ chết hết rồi. Quanh ta không còn sinh vật sống nào nữa.”","“Hừm!” GreyThroat nhìn xuống thiết bị trên cổ tay. “Nhiệt độ đã giảm đột ngột… Không ổn! Nhiệt độ thấp quá… làm hỏng cả thiết bị của tôi!”","“Ta không còn lý do gì để kìm giữ mùa đông bên trong ta nữa.”","“Cái quái gì vậy? Reunion có cả Catastrophe biết đi riêng à?” Blaze nghiến răng. “Nhiệt độ thấp nhất mà Originium Arts từng đạt được là bao nhiêu? Tôi có cảm giác cô ta đang phá kỷ lục này đến kỷ lục khác ngay lúc này… FrostNova, tôi hỏi lại lần nữa, cô nghiêm túc đấy à?”","“Còn gì muốn nói không?”","“Có.” Blaze hạ cưa xuống. “—Thôi đi, thỏ trắng, cô sẽ tự giết mình mất. Cô sẽ chết thật đấy! Cô đã đủ mạnh rồi! Cô không cần ép mình đến mức này! Cô không cần làm vậy để có một trận đánh! Nếu muốn đánh, đánh bao nhiêu cũng được sau chuyện này! Tôi không muốn thấy người Infected giết nhau! Chẳng có lý do gì để ta phải đánh nhau đến chết ở đây!”","“Không,” FrostNova nói.","“Blaze!”","“Chuẩn bị!” Blaze nghiến răng, rồi nhìn xuống tay mình. “Phì! Cô ta đóng băng móng tay tôi. Chúng đang nứt ra. Cô thật sự muốn giết bọn tôi sao?”","“Ta có lý do. Là chỉ huy, ta đã thua. —Nhưng là chiến binh, ta vẫn còn đang chiến đấu.”","@bg:bg_undergroud_f","Amiya bấm bộ đàm, giọng run lên. “…Amiya-1, Blaze-4, tất cả đơn vị, nghe rõ không? Rời khỏi khu vực. Ngay. Cả chị nữa, Gavial! Vì nếu không ra ngay, mọi người sẽ không thể quay lại cứu bọn mình!”","“Ai là sniper giỏi nhất đội ta?” Blaze hỏi.","“……Tôi,” GreyThroat đáp.","“Cô có thể chết đấy. Chắc là muốn tình nguyện chứ?”","“Chắc. Lúc này tôi là giỏi nhất.”","“Được, GreyThroat, cô ở lại. Những người khác, biến hết đi. Nhanh lên!”","“Sao lại rút đội vào trận quyết chiến?” Doctor hỏi.","“Đối đầu với FrostNova, số đội chẳng tạo ra khác biệt gì. Họ không có cách nào tự bảo vệ. Và cô ta có thể giết người ngay lập tức. Kể cả người giỏi như Rangers cũng chẳng làm được gì nhiều. Không phải vì tài bắn cung, mà vì vật liệu.”","“Nỏ của tôi có vẻ đã vô dụng rồi,” GreyThroat nói.","“Nó còn dùng được một lúc. Nhưng dùng được hay không là do cô quyết định… Nếu tùy tôi, tôi sẽ bắn cô ta vài phát bằng pháo chính của Rhodes Island. Như thế sẽ khá có ích. Hoặc gọi chục tổ hỏa lực trút đạn và Arts vào cô ta xem cô ta chịu được bao nhiêu. Rồi cô ta cũng sẽ cạn sức. Nhưng… có lẽ không trước ta.”","“Chị có mang băng garô không?” Amiya hỏi.","“Em nên hỏi chị có mang thuốc chống đông không, loại không gây rối loạn ấy.”","“Blaze…” Amiya nhìn FrostNova. “…Lúc nãy chị hỏi tại sao FrostNova chịu được nỗi đau khi tinh thể Originium đâm xuyên da chị ấy? Em biết tại sao. Em cảm nhận được… Chị ấy chịu được vì nỗi đau bên trong chị ấy còn tệ hơn. Tệ hơn nhiều lần.”","Blaze không nói gì.","Amiya quay sang Doctor. “Giờ, Doctor cũng cần đi.”","“Không.”","“Doctor!”","<i>…Người có muốn đi đến cùng không…?</i>","<i>…Để trở thành một Doctor đáng tin…?</i>","“Tôi muốn đi đến cùng.”","“…Amiya,” Blaze gọi.","“Em… Doctor đã… quyết tâm rồi.”","FrostNova nhìn người khoác áo trùm đầu. “Doctor của Rhodes Island. Quyết định của ngươi sẽ không giúp gì cho họ. Vậy tại sao ngươi làm vậy?”","“Tôi đã nói rồi, cô có thể đến Rhodes Island. Và tôi sẽ chiến đấu sát cánh với các operator của mình.”","“Em hiểu rồi,” Amiya nói. “Blaze, GreyThroat, Doctor. Đây sẽ là một trận chiến cam go.”","“Hừ. Heh heh.” Blaze nhe răng cười. “Thấy chưa, thỏ trắng, đó là Doctor và Amiya của bọn tôi đấy!”","“Ồ…” FrostNova nói khẽ. “…Đừng làm vậy… Thôi kệ. Các ngươi sẵn sàng chưa?”","“Bắt đầu thôi!”","","“Tiến lên! Nổ!” Blaze lao tới, chiếc cưa rực lửa bổ thẳng xuống.","“Một đòn tấn công tốt,” FrostNova nói. Một lưỡi băng đen hiện ra trong tay cô ta, chặn đứng chiếc cưa giữa không trung.","“—Lưỡi băng?” Blaze bị hất văng. “Phì!”","“Mèo con, ngươi nghĩ ta là Caster… yếu ớt đến vậy sao?”","“Cô nghiêm túc đấy à?”","“Những dòng nhiệt quằn quại trên lưỡi cưa của ngươi không phải đối thủ của cái lạnh của ta. Ngươi không thể ngăn được băng giá của ta.”","“Tôi không đánh giá thấp cô, nhưng tôi không nghĩ là… Cưa của tôi cắt được cả tường thành, vậy mà cô chặn được?”","“Với ta, chuyển động của ngươi, sức mạnh của ngươi, chẳng đáng kể gì. Tiếp theo, ta nhắm vào cổ họng.”","“Không khí! Nén! Phá hủy!” Blaze hét lên, một luồng khí nóng bùng nổ quanh cô, hất bay lưỡi băng ngay trước khi nó chạm vào cổ. “Khụ, hahahahaha, khụ… Phì! Suýt nữa! Suýt chút nữa là bị lưỡi băng đâm xuyên tĩnh mạch cổ rồi! Hah, đúng vậy. Cô là chiến binh giống như tôi.” Cô liếc sang. “Làm sao đây, Amiya? Tôi hết ý tưởng rồi. Đến lượt em.”","“Amiya… Ngón tay tôi lạnh quá, sắp không bóp được cò nữa rồi,” GreyThroat nói. “Ta phải kết thúc thật nhanh.”","Amiya nhìn FrostNova. <i>Originium Arts của chị ấy mạnh gấp trăm lần lúc ở phế tích…!</i>","<i>(Và cô ta vẫn chưa hết chiêu đâu!)</i> Blaze thì thầm.","<i>Sẽ không đủ… Nếu mình không nới lỏng nhẫn, mọi người sẽ chết cóng hết!</i> “FrostNova—”","“Đừng hòng nghĩ đến chuyện đó.”","“Hả?” Amiya nhìn xuống tay mình. “Ngón tay em? Ugh… Gah!”","“Ta đã xem toàn bộ trận chiến của ngươi với Talulah,” FrostNova nói. “Điều chỉnh những chiếc nhẫn này sẽ tăng cường Arts của ngươi.”","“Mười chiếc nhẫn, tất cả… Đông cứng rồi?” Amiya nhìn những chiếc nhẫn trên tay mình, giờ đã bị bọc trong một lớp băng đen bóng.","“Ngươi quá trẻ con để làm chiến binh.”","“Vậy là cô làm lạnh vài chiếc nhẫn? Cô mạnh mồm thật đấy nhỉ?” Blaze giơ tay, một luồng nhiệt phả vào tay Amiya. <i>(Hả? Cái gì…? Tôi tăng nhiệt cao thế này mà chúng không chảy chút nào?)</i>","“Blaze… Dừng lại, đừng phí máu. Đây là… Đây là một Originium Art rất mạnh, và rất tinh vi…! Dòng khí lạnh quét theo những tinh thể Originium, quấn quanh bọn mình ngay khi bọn mình bước vào khu vực. Chị ấy đã đánh trúng bọn mình trước khi nó bị dòng nhiệt của chị cắt đứt, mà bọn mình còn không nhận ra! Mmmf… Arts của em không xuyên qua được!”","“Trận chiến bắt đầu ngay khi các ngươi đặt chân vào căn phòng này,” FrostNova nói. “Mười chiếc nhẫn băng này sẽ hút thân nhiệt của ngươi và siết chặt Originium Arts của ngươi. Ngươi càng dồn sức vào chúng, tinh thể băng càng mạnh và lạnh hơn.”","Cô ta nhìn Amiya một lúc.","“Thảm hại. Bùng nổ? Tích trữ năng lượng? Dự trữ? Định đánh bại ta bằng vài mánh khóe… Ngươi có biết mình đang đối mặt với thứ gì không?”","“GreyThroat, tên xuyên giáp!” Blaze hét.","“Rõ! Sáu phát, sẵn sàng!”","“Talulah mà ta biết sẽ sắp đặt cái chết của các ngươi từ lâu trước khi mọi chuyện bắt đầu.”","“Nén khí! Bắn!”","“Bắn!”","Sáu mũi tên lao vút đi, được đẩy bởi một luồng khí nóng của Blaze.","“Và giờ Rhodes Island chỉ như những mũi tên này…” FrostNova nói.","Những mũi tên dừng lại giữa không trung. Rồi đông cứng. Rồi rơi xuống, vỡ vụn như thủy tinh.","“Cái…” Blaze sững sờ.","“Cái gì…? Cái gì vậy? Sao mũi tên lại…? Đông cứng giữa không trung?” GreyThroat lùi lại.","“Thật sự thảm hại.”","<i>(Cô ta làm chệch hướng bằng luồng khí, rồi phá vỡ bằng cái lạnh?!)</i> Blaze nghiến răng. <i>(GreyThroat, tên của cô làm bằng gì?)</i>","<i>(Hàng tiêu chuẩn của Rhodes Island, nhôm lai sợi carbon.)</i>","<i>(Ôi không. Ugh, ta gặp rắc rối to rồi.)</i>","“Thậm chí, có phần đáng xấu hổ,” FrostNova nói.","<i>(Dù cô ta có biết hay không, Arts của cô ta đã đạt đến mức vượt xa mọi thứ mà đám học giả chết tiệt đang bàn luận dạo này.)</i>","“Chỉ cần véo nhẹ… là các ngươi vỡ tan.” FrostNova nhìn họ. “Hãy nghĩ đi. Ta chỉ là thủ lĩnh của Biệt đội Yeti. Reunion được điều khiển bởi người phụ nữ tên Talulah, kẻ đã chặn đường các ngươi ở Chernobog và giết bạn bè các ngươi. Các ngươi nghĩ Talulah là gì…? Thủ lĩnh của Reunion, đấng cứu thế của người Infected?”","“Cô ta không xứng với danh hiệu đấng cứu thế!” Doctor nói.","“Hừ. Dù trong đầu các ngươi hình dung cô ta thế nào, nếu cô ta là một ‘đấng cứu thế’ nào đó, lão già và ta đã không dẫn dắt ‘Reunion’ chút nào. Ban đầu cô ta là một sĩ quan quân đội, rồi là một chiến binh, và cuối cùng là một thủ lĩnh. Nhưng cô ta đã phản bội chúng ta. Chiến binh quyết tâm và tận tụy nhất ta từng biết hóa ra là một kẻ mạo danh… Và những kẻ thù cuối cùng còn lại của cô ta là những kẻ như các ngươi, không có quyết tâm và chưa bao giờ phải nhìn thẳng vào cái chết.”","“Cẩn thận lời nói, thỏ trắng,” Blaze gằn giọng. “Cô không phải người duy nhất đặt mạng sống của mình lên bàn cân.”","“Mắt ngươi cũng có sự hối hận.”","“Cô không cần nói với tôi!”","“Ngươi chưa sẵn sàng chấp nhận cái chết của họ.”","“Đủ rồi!”","“Khụ, haha, khụ…” FrostNova ho. “Ta đã sẵn sàng chưa?”","“Khụ… Khụ!” Blaze cũng ho, máu nhỏ xuống nền thép.","“Ta đã nghĩ về nó biết bao lần, đã thấy họ chết biết bao lần trong những cơn ác mộng, ta chỉ không bao giờ nghĩ… Ngươi cũng vậy, mèo con. Ta thấy được.” Cô ta ngừng lại. “—‘Ta đã tưởng tượng cái chết bi thảm của mình, nhưng không bao giờ nghĩ nó lại cô đơn đến thế.’”","Blaze im lặng một lúc lâu. “……Cô có anh em. Tôi cũng vậy.”","“Những operator Rhodes Island chiến đấu với Talulah ở Chernobog, ai cũng anh dũng. Người mà họ gọi là Ace là một chiến binh kiên cường đến mức hiếm thấy trong đời ta. Anh ta chiến đấu với một cảm xúc mà ít chiến binh nào có… ‘Nỗi buồn’.”","“Ta chưa đủ thân để tôi thoải mái nói chuyện về những chiến hữu cũ với cô đâu.”","“Chỉ một chiến binh không ngừng suy ngẫm về những trận chiến của mình mới lo lắng như vậy. Anh ta là một chiến binh tốt. Ngươi cũng vậy.”","“Phì.”","“Anh ta chết một mình. Ngươi có tiếc vì đã mất anh ta không?”","“Đương nhiên.”","“Ngươi có hối hận vì không có cơ hội cứu anh ta không?”","“Tuyệt đối!”","“Ngươi không định hỏi ai sao? Hỏi đi. Hỏi câu hỏi mà ngươi không biết phải diễn đạt thế nào, không biết phải hỏi ai.”","“Cô…”","“‘Tại sao?’”","Blaze đứng im.","<i>(…Cảm xúc mạnh quá… FrostNova!)</i> Amiya ôm lấy ngực.","“Tại sao?” FrostNova nói, và giọng cô ta không còn bình thản nữa. “Tại sao ta không ở đó? Tại sao ta không mạnh hơn? Tại sao ta không ngăn được nó?”","“Ugh… Nhiệt độ vẫn đang giảm!” GreyThroat hét.","“Đứng cạnh tôi! Cái lạnh của cô ta áp đảo quá, tôi chỉ đủ sức giữ không khí quanh mình ấm!”","“…Tại sao?” FrostNova lặp lại. “Tại sao ta lại ngã xuống đúng lúc các em ta cần ta nhất? Họ đều là lũ ngốc. Toàn là lũ ngốc chỉ biết giúp đỡ nhau, chỉ muốn sống sót, chỉ muốn có một nơi để sống. …Tại sao ta không thể thực hiện nổi mong ước của một lũ ngốc?”","“Tại sao Ursus lại tàn nhẫn với người của ta đến thế, và lạnh lùng với chính người Ursus bình thường đến thế? Tại sao ngọn lửa nhỏ có thể thắp sáng thế giới lại phải bị dập tắt ở vùng đất xa lạ này? Tại sao trong cuộc chiến chúng ta tiến hành để chấm dứt cái ác, ta lại lãng phí thêm nhiều mạng sống?”","“Khụ, khụ… Unf, khụ, khụ…!”","“Unf… Ugh…” Amiya quỳ sụp xuống.","“Tại sao chúng ta đã hiến dâng mạng sống, khụ, chỉ để đạt được một lời dối trá? Tại sao…? Tại sao thế giới này không cho ta thêm chút thời gian?”","“‘Người Infected nên tự hào về con người mình, và dùng những phương tiện đơn giản nhất để giành lấy công lý từ thế giới’… Ban đầu, ta chỉ coi đó là một phần của lý tưởng Reunion. Quả thật, nó mang lại sức mạnh cho người Infected. Họ thôi coi mình là bia đỡ đạn của Đế quốc… Nhưng giờ ta nhận ra những niềm tin mà Talulah từng dạy chúng ta, những tư tưởng đòi hỏi sự ủng hộ từ cơ sở, và những mục tiêu phải liên tục được củng cố và điều chỉnh, đều đã biến mất. Chỉ còn sự xúi giục. Chỉ còn sự dung túng. Chúng ta bị ném vào những trận chiến khốc liệt nhất, không có tiếng nói trong hàng ngũ, và tất cả đến quá sớm… Nếu tất cả là do Talulah làm, thì cô ta đã lừa dối tất cả mọi người ngay từ đầu.”","“Có thể cô ta đã lừa cô!” Doctor nói.","“Nếu cô ta sẽ đưa người Infected đến tương lai đen tối nhất đó… Để hoàn thành kế hoạch độc ác nhất của mình… Thì cái ác của cô ta phải bị tiêu diệt. Nhưng các em ta, vô số người Infected và người không nhiễm bệnh đã chết… Không gì có thể mang họ trở lại.” Giọng FrostNova vỡ ra. “…Điều gì đã khiến cô ta thành ra như vậy? Lẽ ra không phải thế này, lẽ ra không bao giờ phải thế này! Người của ta… Các em của ta!”","Cô ta ngẩng lên.","“—Amiya. Ngươi có nghe thấy không, Amiya?”","“FrostNova…!”","“Dòng khí lạnh quá mạnh… Cô ta còn có thể ngưng tụ nó thành hình dạng!” Blaze hét. “Nó đang thổi bay dòng nhiệt của tôi!”","“Cái lạnh có đủ để làm nguội thân nhiệt của ngươi không? Cái chết có đủ khiến ngươi chùn bước không? Ngươi sẽ không, Amiya, và ngươi không thể! Ngươi đọc được tâm trí, đúng không, thỏ con? Vậy đọc đi, đọc cơn thịnh nộ của ta, trái tim đã bị cay đắng bóp nghẹt và sôi sục trong ngực ta hơn chục năm trời, vậy mà chưa bao giờ ngừng đập! Đọc đi, Amiya! Đọc cho kỹ! Trong trái tim này có bao nhiêu cơn giận, vì những người thân yêu đã chết, vì Ursus mục nát, vì người Infected, vì người dân Ursus, trong trái tim không chịu dừng lại, không chịu chết này!”","Amiya ngẩng lên, nước mắt chảy dài.","“Chị có bao giờ căm ghét cô ấy không, chị FrostNova?”","FrostNova khựng lại. “…Khụ.” Rồi cô ta khẽ cười. “Heh.” Một quãng lặng. “Ta chưa bao giờ căm ghét cô ấy. Kể cả cô ấy là nguyên nhân của tất cả nỗi đau hôm nay, ta chưa bao giờ căm ghét cô ấy. Căm ghét mang lại gì cho ngươi và ta chứ? Ta chẳng có gì ngoài cơn thịnh nộ bất tận, sôi sục dành cho hành tinh đáng khinh này.”","Amiya im lặng.","“Còn ngươi thì sao? Ngươi không có cơn giận như vậy trong lòng sao? Ngươi không có người thân chết vì Oripathy sao? Một người bạn chết vì sự thờ ơ của thế giới này? Ngươi chưa mất đi những người ngươi dựa vào để sống, những người cho ngươi lý do để sống sao?”","Amiya không trả lời.","“Chỉ tuyên bố một triết lý nào đó, chỉ nắm lấy một loại Arts nào đó, chỉ tổ chức vài đội… Như thế có đủ để đánh bại Talulah không? Đến lúc tỉnh khỏi những giấc mơ viển vông của ngươi rồi.”","“—” Amiya đứng dậy, rất chậm. “Em hiểu rồi, chị FrostNova. Mọi thứ vừa tràn vào tâm trí em, em biết chúng là gì.”","“Điều gì đang thúc đẩy Rhodes Island tiến lên? Điều gì khiến các ngươi tiếp tục chiến đấu?”","“Ngay phía trước! Một dòng khí lạnh khổng lồ!” Blaze hét. “Nó có hình… gần như… hình một con dao găm! Cứ thế này, tôi sẽ phải bỏ hở lưng và gom dòng nhiệt ra phía trước làm khiên… Nhưng dòng khí lạnh của cô ta đang cướp đi dao động phân tử của không khí. Kể cả tôi tạo được khiên, cũng không giữ được lâu! Doctor, nào, người phải có ý tưởng gì chứ!”","“Không phá được thì ta chỉ có thể cầm cự!”","“Thế chẳng khác gì không nói gì cả!”","“Không… Doctor nói đúng,” GreyThroat nói. “FrostNova không còn nhiều sinh lực. Nếu ta trụ được, ta thắng.”","“Cô nói gì vậy? Nếu làm thế, cô ta sẽ chết!”","“Đó là lựa chọn của cô ấy, và là cơ hội duy nhất cô ấy để lại cho ta!” Doctor nói.","“Còn lựa chọn của các ngươi thì sao?” FrostNova hỏi. “Trước cái ác phải bị tiêu diệt, trước kẻ phản bội đã cướp lấy lý tưởng của người Infected, trong tim các ngươi có gì? Tại sao nó đập? Khụ, khụ… Nếu các ngươi còn không đánh bại được ta, các ngươi sẽ đối mặt với cô ta thế nào? Các ngươi sẽ dẫn dắt vô số người Infected thế nào? Các ngươi sẽ chiến đấu chống lại thế giới ác độc này thế nào!!!”","“FrostNova…” Amiya nói. “Cảm ơn chị. Nhưng em không thể giận chị.”","“Ngươi… Đang lãng phí thời gian của ta.”","“Không, FrostNova… Em biết em sẽ làm gì. Em không thật sự đọc được tâm trí. Và đọc được lòng người không có nghĩa là em hiểu người khác hơn những người không có năng lực này. Em chỉ không thể từ chối… Em không thể ngăn những cảm xúc tuôn ra từ chị. Tràn ngập tâm trí em bằng đau đớn và lo âu, và… Giận dữ. Chị tỉnh táo và điềm tĩnh, nhưng cơn giận cháy nóng đến mức em muốn lùi lại… Nhưng em không thể. FrostNova, em biết chính xác mình phải làm gì. Em sẽ không từ chối chị.”","FrostNova im lặng.","“Chị FrostNova, em đã cảm nhận được.”","“Tại sao ngươi khóc?”","“Em… FrostNova… Chị…”","“Không. Lau nước mắt đi! Ngươi không được khóc trước kẻ thù. Amiya, cho ta biết câu trả lời của ngươi.”","Amiya nhìn sang Doctor.","“…Nói đi, Amiya,” Doctor nói.","“Doctor…” Amiya lau nước mắt. “…Vâng.” Cô bé quay lại, và giọng cô bé không còn run nữa. “‘Nếu phải chiến đấu, thì chiến đấu đến cùng.’ Doctor, chúng ta sẽ chiến đấu với FrostNova. Chỉ một bên bước ra khỏi đây.”","“Đúng vậy,” FrostNova nói. “Giờ ngươi sẽ… chiến đấu với ta. Chỉ một trong hai ta rời đi. Nếu ngươi đánh bại được ta, nghĩa là sẽ có vài người được sống sót— Ta sẵn sàng gia nhập Rhodes Island. Ta sẵn sàng cùng các ngươi chiến đấu chống lại kẻ thù của người Infected, theo cách của các ngươi. Đây là gánh nặng ta phải mang.”","“Tôi mong cô giữ lời,” Doctor nói.","@cg:avg_6_1","“Khi ta hứa, ta giữ lời.”","@cg:avg_6_2","“Và… Chị FrostNova,” Amiya nói. “Người Infected không cần ai dẫn dắt họ cả. Chúng ta chỉ chiến đấu vì cùng một niềm tin, không phải vì bất kỳ một người nào. Không bao giờ vì một người nào cả.”","“—Đúng vậy. Sự mục nát phải bị xóa bỏ. Hãy đánh bại ta, và đánh bại Talulah.” FrostNova nhìn cô bé. “Ngươi là gì?”","“Em có thể là bất kỳ ai.”","“Ngươi chiến đấu vì ai?”","“Vì tất cả mọi người.”","“Tốt. Amiya…” FrostNova mỉm cười, lần đầu tiên, một nụ cười thật sự. “Khụ… Cảm ơn ngươi.”","Cô ta bắt đầu hát. Giai điệu ấy, bài hát ru ấy.","<i>“Ngay cả thời gian cũng sẽ đông cứng nơi đây…”</i>","“Cái lạnh đang ép sát ta! GreyThroat!” Blaze hét.","“Sẵn sàng!”","“Doctor, ở bên em. Em sẽ cố bảo vệ Doctor.”","“FrostNova!”","“Các ngươi sẽ chết ở đây trong trận chiến, và ta sẽ dập tắt những ảo tưởng ngớ ngẩn của các ngươi,” FrostNova nói. “Hoặc, đánh bại ta.” Một quãng lặng. “…Đánh bại ta. Và cho ta thấy hy vọng.”"],"bg":"bg_undergroud_n","cast":[["FrostNova","npc:char_1505_frstar_1"],["Blaze","npc:char_017_homura_3"],["Amiya","op:char_002_amiya"],["GreyThroat","op:char_367_swllow"]]},{"c":"6-17","t":"Mùa đông tàn","p":["Có một tiếng vỡ, rất khẽ.","@cg:avg_6_9","“Nó… vỡ rồi sao?” FrostNova nhìn xuống một chiếc vòng nhỏ trên cổ tay mình, giờ đã nứt làm đôi. “Lão già lấy thứ này từ một pháp sư nào đó… Bảo nó sẽ giữ ta sống. Còn không qua nổi một trận đánh, hả. Ta đoán nó là đồ giả. Giống như ta là đứa con gái giả của ông, có lẽ vậy…? Và giờ, giống như Reunion… Cũng vậy.”","“Mmm!” Blaze rên lên, chống tay ngồi dậy. “Ừm… Cái lạnh… biến mất rồi.”","“Khụ khụ… Blaze!” Amiya bò tới.","“Tôi không sao! Amiya, nhanh, đi xem thỏ trắng đi!”","FrostNova nằm giữa nền thép lạnh, mái tóc trắng xõa ra như tuyết. Những tinh thể Originium trên người cô ta đã ngừng phát sáng.","“Thắng đẹp lắm, Rhodes Island,” cô ta nói khẽ. “Các em của ta… Ta đã để họ chết vô ích. Chúng ta chẳng đạt được gì cả. Cuộc đời ta… chẳng đáng giá gì cả.”","“Họ đi theo cô vì lý tưởng của cô,” Doctor nói.","Blaze quay mặt đi.","“Cái chết của ta… không đáng để ai phải bận tâm,” FrostNova nói. “Đi cứu những người các ngươi có thể cứu đi. Nhanh lên. Đi đi. Dù là ngăn bọn áo mưa, đi giết Mephisto, hay che chở những người Infected không còn nơi nào để đi… Đi đi. Đi làm điều gì đó có ý nghĩa.”","Amiya im lặng. Rồi cô bé quay sang. “Doctor…”","“Tôi sẽ ở lại. Em đi đi.”","@cg:avg_6_10","“Vâng.” Amiya đứng dậy. “Doctor, xin hãy nói với chị ấy. Làm ơn.”","Khi tiếng bước chân của Amiya đã xa, FrostNova khẽ cười.","“Một con thỏ… ngây thơ thật. Giống Talulah hồi đó. Rất giống. Được thấy một người như thế trước khi chết, một người quyết tâm thực hiện lý tưởng của mình đến thế…”","“Còn gánh nặng cô phải mang thì sao?” Doctor hỏi. “Chẳng phải cô đã hứa sẽ gia nhập Rhodes Island sao?”","“Ta đoán điều đó cứ quanh quẩn trong đầu ngươi, hả? Kẻ ác là kẻ ác. Ta không có gì phàn nàn về kết cục mình xứng đáng nhận. Ta đã làm hại các ngươi. Reunion, và ta, đã nhắm vào những người Lungmen vô tội và tự tay dẫn người Infected Ursus vào cơn ác mộng này. Những người như vậy không có chỗ ở Rhodes Island.”","“Các em ta… Lũ ngốc đó chắc đã cố giữ ta sống, hả? Ta đã nghĩ kể cả ta chết ở đây, lũ ngốc đó cũng sẽ có một nơi để sống yên ổn. Sai và sai. Họ chết rồi. Để bảo vệ ta, một người phụ nữ vốn dĩ đã chẳng còn nhiều thời gian. Ta không vui. Chúng ta bị lợi dụng và chà đạp. Mạng sống của chúng ta bị vứt bỏ. Ta không vui… Khoảnh khắc cuối cùng của cuộc đời này, nó không thuộc về ta. Họ đã mua nó bằng máu của mình! Chút sự sống ít ỏi này… Ta phải trao nó cho một người đáng tin.” Cô ta nhìn Doctor. “Cảm ơn ngươi.”","Rồi cô ta nhìn lên trần thép tối om, như nhìn qua nó, đến một bầu trời rất xa.","“…Ah… Kể cả sống sót, thì có nơi nào để đi chứ? Chúng ta chẳng có nơi nào. Thứ duy nhất chúng ta từng biết là tuyết. Lungmen không phải Ursus. Chúng ta đến đây, tuyệt vọng muốn cứu người của mình, và người Infected, tìm kiếm một nơi ấm áp, có thức ăn, có mái che… Đó không phải Lungmen. Ngay từ đầu, lẽ ra không phải Lungmen. Người dân Lungmen cũng đang vật lộn để kiếm sống. Lẽ ra chúng ta nên quay về Ursus… Quê hương của chúng ta…”","“Tuyết… một dòng sông yên bình… những rừng thông khẽ đung đưa… thảm rêu màu ngọc lam… Thế giới này, nó đẹp quá…”","“Vậy, cô nghĩ Talulah là người đã sắp đặt tất cả,” Doctor nói.","“…Nếu ta đúng… Âm mưu đã sẵn sàng để khai màn. Kể cả lão già Buldrokkas’tee có cầm chân được một thời gian, Talulah cũng sẽ có cách đối phó ông. Lungmen chẳng làm được gì… Còn Ursus chỉ có thể đứng nhìn. Nhưng các ngươi vẫn còn ở đây, và người Infected vẫn còn cơ hội. Dù chỉ là một cơ hội nhỏ…” Cô ta nắm lấy vạt áo Doctor. “—Đi chấm dứt Talulah đi. Ngăn sự điên loạn của cô ta lại, đừng để Reunion nuốt chửng thêm người Infected nào nữa. Reunion không cần Talulah, bất kỳ Talulah nào…”","“Hoặc…” Giọng cô ta nhỏ dần. “Ta có thể đưa ra một yêu cầu ích kỷ. Đi cứu cô ấy. Không. Đi giúp cô ấy. Cùng với vô số đồng bào Infected của chúng ta… Cô ấy thật sự… Người bước đi trên mặt đất lầy lội… Talulah…”","“FrostNova?”","“Đi… đi.”","“Tôi nghĩ cha cô thật sự rất yêu cô,” Doctor nói. “Giống như cô nhớ cha mẹ ruột đã chết vì cô. Cô nhớ rõ tất cả những gì cha cô đã làm cho cô.”","FrostNova im lặng rất lâu.","“…Sao ta lại không biết chứ? Chỉ là, ông sẽ sống lâu hơn ta. Giá mà ông chưa bao giờ nhận nuôi ta thì tốt biết bao. Như vậy, ông đã không phải chịu tất cả nỗi đau ta mang đến cho ông. Ông đã chịu khổ nhiều quá…”","“Chính vì ông đã chịu khổ nhiều nên ông mới trân trọng cô.”","“Hehehe…” FrostNova cười khẽ. “…Doctor. Ta có thể gọi ngươi như vậy, phải không? Doctor của Rhodes Island, lựa chọn có lẽ vô nghĩa, trong thế giới này. Dù vậy, dù kết quả chẳng tạo ra khác biệt gì… Ta vẫn muốn tự mình lựa chọn. Ta đã lựa chọn. Bằng chính đôi tay mình… Để nhận lấy quả của những hạt giống ta đã gieo.”","Những ngón tay FrostNova lần tìm trên mặt Doctor.","Doctor khựng lại. “Ngón tay cô… ấm?”","“Lạ thật. Mặt ngươi… lạnh quá. Thân nhiệt của ta… không còn thấp nữa sao?”","“Phải. Triệu chứng của cô đã biến mất. Cô ấm lắm, FrostNova.”","“Cuối cùng ta cũng có thể chạm vào một người… trước khi chết.”","“FrostNova, Amiya và tôi muốn cô gia nhập Rhodes Island.”","“Ta có thật sự xứng đáng không?”","“Nếu cô cứ thế chết đi, ở đây và bây giờ, cô sẽ không có cơ hội sửa chữa những sai lầm của mình.”","“…Thật bất lịch sự nếu không trả lời.” FrostNova mỉm cười. “Nói với Amiya, Doctor… Trên thế giới này, một người đơn độc chẳng có giá trị gì. Nhưng cô ấy tuyệt đối không đơn độc. Từ giờ trở đi, ta ở bên các ngươi. Cả hai người.”","@cg:avg_6_10_2","“Ta…… muốn gia nhập Rhodes Island.”","“Cảm ơn cô.”","“Không… Cảm ơn ngươi.” Cô ta nhìn sâu vào đôi mắt dưới mũ trùm. “Đôi mắt ngươi… khiến ta nhớ đến một người ta từng quen. Ta đã gặp một cậu bé, cậu ta nói anh trai mình thà lên giá treo cổ còn hơn cầu xin lòng thương xót của kẻ thù… Nên cậu ta định đi bộ băng qua những cánh đồng tuyết, đi khắp cả Ursus… Và cậu ta đã không đi cùng chúng ta. Ta từng nghĩ cậu ta là người lý tưởng nhất ta từng gặp. Nhưng giờ, ngươi và Amiya đã khiến ta đổi ý… Có lẽ lý tưởng cũng có thể là một loại đức tin.”","“Rhodes Island là nơi chiến đấu vì những niềm tin chung.”","“Reunion ban đầu… cũng vậy. Hoàn toàn giống vậy.” Ngón tay cô ta trượt khỏi gò má Doctor. “Đôi mắt ngươi, và của cậu bé ấy, thật sự giống nhau. Chỉ là, ngươi không quyết liệt như cậu ta. Ngươi… dịu dàng hơn nhiều lắm.”","“Để ta đi. Các em ta đang chờ ta.”","Cô ta nhắm mắt lại.","“……Cha…… Con đã thật ngốc nghếch. Xin hãy tha thứ cho con.”","Cô ta lặng lẽ trượt xuống.","Khóe môi cô ta cong lên, kiêu hãnh như khi cô ta còn sống."],"bg":"bg_undergroud_f","cast":[["FrostNova","npc:char_1505_frstar_1"],["Amiya","op:char_002_amiya"],["Blaze","npc:char_017_homura_3"]]},{"c":"6-18","t":"Chỉ mình ngươi biết","p":["<i>Chiến dịch Bảo vệ Lungmen đã hoàn tất. Tôi nhắc lại. Chiến dịch Bảo vệ Lungmen đã hoàn tất.</i>","<i>Yêu cầu các sĩ quan cảnh sát kiểm kê trang bị, báo cáo về đồn và trở về đội trong vòng một ngày làm việc. Yêu cầu các thành viên L.G.D. hội quân với đội của mình và trở về L.G.D. chờ lệnh tiếp theo.</i>","<i>Tôi nhắc lại…</i>","","“Cô làm gì ở đây?” Ch’en dừng lại trước một cửa cống ngầm. “…Còn cái mặt đó là sao?”","Swire đứng chắn trước cửa cống. Gương mặt cô tái nhợt.","“……Không có gì. Không có gì cả.”","“…Ồ.” Ch’en bước tới.","“Dừng lại. Cô đi đâu vậy?”","“Đi xem.”","“Không cần xem đâu, tôi kiểm tra rồi, chẳng có gì ở đó cả.”","“Vậy sao.”","“Ch’en, không sao đâu. Trận chiến kết thúc rồi.”","“Tránh đường cho tôi, cô Swire nhỏ.”","“Cô đã ngăn được Reunion, cả lực lượng đặc nhiệm nữa! Cô đã phơi bày tất cả họ trước L.G.D., Rhodes Island, thậm chí cả Ngự sử cùng một lúc! Cô đã ngăn được họ!”","“Tránh ra!”","“Cô đã làm đủ tốt rồi, xứng đáng với danh hiệu đội trưởng Đội Thanh tra Đặc biệt. Cô có thể thôi điều tra rồi! Cô còn muốn biết gì nữa? Chẳng còn gì để biết nữa cả!”","“Tôi cần biết chuyện gì đang xảy ra.”","“Chuyện cống ngầm này à? Đó là điều cô cần biết sao? Cô đã làm hết những gì có thể, bước thêm một bước nữa là cô sẽ sang phía bên kia của Lungmen! Ta hoàn toàn có thể cải thiện thành phố. Ta có thể xây dựng lại, ta có thể đi dọn sạch mọi thứ từ những ngày đen tối cũ! Nhưng Ch’en, đừng xuống đó. Đừng nhìn! Công lý, trách nhiệm, sự gắn bó, cô đều đạt được hết rồi! Và trông cô thật tuyệt khi làm điều đó! Ah Ch’en!”","Ch’en im lặng một lúc.","“Tránh đường cho tôi.”","“Chính vì cô là người như vậy nên cô không thể nhìn!”","“Có người bảo cô đừng điều tra cống ngầm, phải không?”","Swire không trả lời.","“Có người cũng nói với tôi y như vậy.”","“Vậy sao cô cứ điều tra mãi? Không ai muốn cô thấy chuyện này, không ai cả!”","“Không đúng. Lungmen muốn tôi thấy nó. Đây là con người tôi. Tôi phải thấy nó.” Ch’en đặt tay lên chuôi kiếm. “Swire, đừng bắt tôi phải rút kiếm.”","Swire nhìn cô ta rất lâu. Rồi cô bước sang một bên.","“……Ugh…”","Ch’en bước xuống những bậc thang tối om. Một mùi hôi nồng nặc xộc lên.","“Mùi gì vậy…? Đây là…”","Cô ta đứng im ở bậc cuối cùng.","Rất lâu.","Rất, rất lâu.","@bg:bg_indoor_f","“A, người về rồi,” một sĩ quan L.G.D. nói, khi Doctor bước ra từ tầng kết cấu dưới. “Đã bắt được chỉ huy địch chưa? Người Infected tên Mephisto ấy?”","“Đã chết rồi.”","“Hả… Người nói gì? Đó có phải thái độ hợp tác không…? Chuyện gì vậy? Chẳng phải người Rhodes Island các anh đi truy đuổi hắn sao? …Người có thể cho một lời khai chính xác không? Chúng tôi cần báo cáo, và nếu chỉ huy địch chưa chết… Chết rồi? Hắn chết thế nào? Người chắc chứ? Chỉ có xác định tử vong tinh thể và khám nghiệm tử thi mới nhận dạng được người Infected, Oripathy xóa bỏ những dấu hiệu sinh học chính… Người không hiểu gì về chuyện này, phải không?”","Rồi anh ta nhìn kỹ hơn. Doctor đang bế một người trên tay. Một người phụ nữ tóc trắng, quấn trong chiếc áo khoác lớn quá cỡ.","“Hả? Khoan, người đi đâu vậy? Người đang bế ai vậy? …Chuyện quái gì đã xảy ra dưới đó?”","“Một người Infected đã chết.”","","“Tàn quân của Reunion chắc đã rút lui thành công rồi,” Blaze nói, ngồi tựa lưng vào một cột thép. “Tôi không biết đây có được tính là trận chiến mà thỏ trắng muốn không… Dù tôi không chắc cuối cùng cô ấy còn quan tâm nhiều đến chuyện đó không. Dù sao, cô ấy đã làm được.” Cô nhắm mắt lại. “Thỏ trắng… cô cứng đầu thật đấy. ‘Thắng đẹp lắm’? Thắng cái con khỉ… Nếu cô không sắp chết, giờ này tất cả chúng tôi đã thành những bức tượng băng duyên dáng rồi.”","“Cô sống sót, đúng không? Cô còn có thêm kinh nghiệm chiến đấu quý giá nữa,” GreyThroat nói.","“Kinh nghiệm kiểu đó chỉ có ích về sau. Nhưng khi ai đó chết trước mặt cô, họ không bao giờ quay lại nữa. Tôi đã có thể cứu cô ấy.”","GreyThroat im lặng một lúc. “Amiya đi gặp người đứng đầu Lungmen rồi à?”","“Ừ, chắc vậy. Cứ để họ lo, tôi không quan tâm.” Blaze giơ tay lên. “GreyThroat, giúp tôi một tay.”","“Hả? Để làm gì?”","“Cô đùa tôi à? Không thấy tôi đang thế nào sao?”","“Cô không đứng dậy được à? Trông cô vẫn ổn mà.”","“…Operator GreyThroat, tôi xin trân trọng đề nghị cô đỡ tôi dậy. Tôi đã mất nhiều máu và đang hạ thân nhiệt. Trông tôi nguyên vẹn nhưng thực ra tôi đang hấp hối. Xin hãy giúp tôi trở về tàu!” Blaze thở dài. “Thôi, biết gì không? Bỏ đi. Tôi không muốn làm phiền.”","“Tại sao?”","“Chẳng phải cô sắp rời Rhodes Island sao? Không cần ép mình làm việc cho Rhodes Island nữa.”","“…Tại sao?”","“Hả?”","“Trong trận chiến đó, tôi đã cảm nhận được nỗi đau của người Infected,” GreyThroat nói. “Nó còn bế tắc và tuyệt vọng hơn những gì đang diễn ra quanh ta. Tôi hiểu nỗi đau của người Infected và tôi nghĩ chúng ta có thể ngăn những chuyện này xảy ra.”","“Tôi nghĩ cô chưa thấy đủ bi kịch đâu. GreyThroat, để tôi hỏi cô: tôi và cô khác nhau ở điểm nào?”","“Cô là người Infected?”","“Nếu ta chết trong trận chiến lúc nãy, cô bình thường và tôi Infected khác nhau ở chỗ nào? Chỉ là vài người chết thôi. Có người quan tâm mình là Elder hay Ancient, có người quan tâm mình đến từ nước nào, có người nhìn vào chủng tộc, có người coi trọng của cải… Tôi là người Infected, nhưng tôi chưa bao giờ than vãn kiểu ‘ôi khổ thân tôi’, ‘người Infected bị áp bức quá’. Chẳng ai muốn nghe cả. Chọn bất kỳ ai ở khu ổ chuột này, Infected hay không, chẳng ai muốn nghe.”","“Mức độ đau khổ không quan trọng, tôi chỉ mong ta có thể nhìn vào nỗi đau của người Infected. ‘Người Infected cũng là người’, đơn giản vậy thôi. Và tôi không muốn người ta nhìn tôi như một con vật nhỏ đáng thương, tôi muốn một cái nhìn ngang hàng, thẳng thắn. Thảm sát, phân biệt, giam cầm, lao động khổ sai, tôi đã thấy hết, nhưng tôi có thể làm gì để thấy chúng chấm dứt?”","“Thỏ trắng đã làm được điều tôi không bao giờ làm được. Cô ấy cho tôi thấy một cuộc vật lộn sinh tử thật sự… Thứ kinh hoàng cô ấy sẽ cho ta thấy kể cả khi chỉ còn một phần giây. Sự kiên cường đó đủ để vượt qua mọi thân phận. Nếu bây giờ tôi đi đánh lũ áo mưa đen vô hồn của Lungmen, thì dễ như đi dạo. So với thỏ trắng, chúng chẳng là gì.”","“Thật không?”","“Không. Tôi đã bảo rồi. Tôi đang hấp hối mà, GreyThroat. Nhưng chiến đấu đến chết vì điều mình tin tưởng? Đó là một kết thúc vững vàng. Đứng cuối danh sách những điều muốn làm trước khi chết của tôi.” Blaze nheo mắt nhìn ra xa. “…Nhìn hai người đó kìa.”","“Ai?”","“Doctor và Amiya.”","Ở phía xa, hai bóng người đang đi về hai hướng khác nhau.","“Doctor đi đâu vậy?”","“Về Rhodes Island chôn cất thỏ trắng. Nói là chôn cất, nhưng thật ra là xử lý thi thể để ngăn cô ấy kết tinh, hóa bụi, và gây lây nhiễm thứ phát. Người Infected bọn tôi đối mặt với chuyện đó suốt.” Blaze nhìn theo bóng Doctor. “Ít nhất, là một operator Rhodes Island, tôi đã bắt đầu tin Doctor. GreyThroat, cô có thấy ánh mắt của Doctor không? Chính đôi mắt đó, đó là thứ khiến tôi tin một người như vậy.”","“Tôi thấy rồi. …Tôi nghĩ đôi mắt của Amiya vẫn đáng sợ hơn.”","“Vì hai người đó đang đi theo hai hướng khác nhau. Doctor đến lò hỏa táng cho người Infected, còn Amiya đến Lungmen, đến nghĩa địa mới của người Infected. Cuối cùng tôi cũng hiểu vì sao Ace nói Doctor đáng giá như Amiya và Kal’tsit.”","“Vậy Kal’tsit ở đâu?”","“Kal’tsit ở nơi bà ấy cần ở.” Blaze lại giơ tay lên. “Được rồi, đi thôi. Vì cô không rời Rhodes Island, tôi hỏi lại lần nữa: làm ơn đỡ tôi dậy.”","“Sao cô không chờ đội y tế đến?”","“Vì tôi đang rất tệ. Operator tinh nhuệ… phải trông cứng rắn hơn thế này.”","“…Cô thà chết còn hơn trông mất ngầu một phút.”","“Sao cô cứ nói những câu biết là sẽ làm tôi đau thế…? Mà cô có biết y tế hỗ trợ trong chiến dịch này là ai không? Là Gavial. Gavial đó đấy. Cô ta bảo rửa tay xong sẽ đến ngay! Cô thấy sao nếu máu tôi bắn đầy mặt cô?”","“Đưa tay đây.” GreyThroat kéo cô đứng dậy. “Tôi không thích máu.”","“Vậy tôi đề nghị ta đi nhanh hơn chút…”","“Được.” GreyThroat đỡ cô bước đi. “Nếu tôi không cứu những đứa trẻ Infected đó, cô đã không cứu tôi, và tôi đã không có cơ hội thay đổi suy nghĩ về người Infected… Đó là một cách nữa người Infected đã truyền cảm hứng cho tôi.”","“Hả?” Blaze nhìn cô. “…Cô lại nói hỏng rồi. Chuyện đó thì liên quan gì đến việc tôi cứu cô?”","","<i>Thượng Lungmen. Văn phòng Trưởng quan.</i>","“Xin chào. Em có hẹn với ông Wei. Chị đưa em vào được không ạ?”","“A, cuộc họp cuối cùng của Trưởng quan Wei vừa kết thúc, mời cô đi lối này,” cô lễ tân nói. “Ừm… Cô là…?”","“Amiya. Amiya, người Infected.”","Ở hành lang, một nhóm người vừa bước ra từ văn phòng. Vị Ngự sử, người đàn ông dùng dây, và vài người khác.","“Vậy chúng tôi xin cáo từ,” Taihe nói.","“Hẹn lần sau,” một giọng nam già nua vang lên từ trong phòng.","“Bà nghĩ sao?” một người hỏi.","“Ta đã thấy những thủ đoạn tàn bạo của hắn,” Taihe nói.","“Bề ngoài thì vẫn như mọi khi,” Ngự sử nói. “Thực chất, ai cũng biết.”","“Loại người như hắn lúc nào cũng vậy. Ta hiểu vì sao hắn là người canh giữ Lungmen.”","Rồi họ nhìn thấy Amiya.","“Người Infected? Ngươi làm gì ở đây?”","“A, không có ý mạo phạm đâu ạ. Đây cũng là khách của ông Wei…” cô lễ tân vội nói.","“Em không đến đây để xin ông Wei điều gì cả,” Amiya nói.","<i>(Cô Amiya, ít nhất cũng tránh mặt một chút đi…!)</i> cô lễ tân thì thầm.","“Y phục của ngươi… cho thấy ngươi thuộc Rhodes Island, đang làm việc với Lungmen,” một người nói. “Người Infected không nên ở lại lâu. Lungmen nổi tiếng là nuốt chửng con người.”","“Cảm ơn lời khuyên. Nhưng thế giới này không kén chọn người để nuốt đâu.”","“Ồ… Vậy ta nên cảm ơn ngươi vì lời cảnh báo.”","Khi họ đã đi khuất, một người quay lại hỏi Ngự sử. “Bà có biết cô bé đó là ai không?”","“Ông đang âm mưu gì vậy?”","@bg:bg_lungmen_o","“Ông Wei.”","“Ồ… Cô Amiya, ta đoán cô sẽ đến,” Wei Yenwu nói, đứng dậy từ sau bàn làm việc. “Cuộc chiến đã thành công, và Rhodes Island có công rất lớn. Tiếp theo, Lungmen sẽ thực hiện nghĩa vụ hợp đồng, cung cấp cho Rhodes Island sự hỗ trợ thương mại cần thiết, cùng những thứ khác…”","“Không cần đâu, ông Wei. Em chỉ đến để hủy hợp đồng.”","Wei Yenwu khựng lại. “Xin lỗi?” Ông ta mỉm cười. “Rhodes Island ghét trò mồi nhử đến vậy sao? Nếu ta có điều gì không phải, xin cứ nói thẳng. Ta xin thành thật xin lỗi, cô Amiya.”","Amiya im lặng một lúc. “Ông Wei, ông lúc nào cũng lịch sự đến mức khiến em hơi choáng ngợp. Nhưng em đã thấy lực lượng vũ trang và kế hoạch của ông.”","“Đừng đọc quá nhiều vào cuộc chiến, cô Amiya. Đây không phải một lời buộc tội, phải không?”","“Không, ông Wei. Em không có quyền buộc tội ông. Em chỉ đến để làm thủ tục sau sự việc.”","“Tại sao cô muốn chấm dứt thỏa thuận của chúng ta?”","“Vì em đã xác định rằng hợp tác với Lungmen không phù hợp với Rhodes Island.”","“Cùng có lợi, chẳng phải thế là đủ với một doanh nghiệp sao?”","“Kể cả doanh nghiệp cũng có kế hoạch phát triển riêng.”","“Cô đang ám chỉ Lungmen nợ gì đó với bộ phận Infected trong doanh nghiệp của cô sao?”","“Không. Rhodes Island chưa bao giờ có ‘bộ phận Infected’ nào cả.” Amiya đứng thẳng lưng. “Rhodes Island không chỉ chiến đấu vì người Infected. Em không chỉ là một người Infected… Em còn là một phần của cộng đồng thế giới. Rhodes Island có chuyên môn đối phó với người Infected là vì nhiều operator của bọn em chính là người Infected, và hiểu được những trải nghiệm và hoàn cảnh của họ. Nhưng cố gắng xóa bỏ bóng ma Oripathy khỏi mảnh đất này chưa bao giờ có nghĩa là bọn em chỉ chiến đấu vì người Infected. Ông Wei, nếu ông nghĩ bọn em chỉ là một tổ chức đấu tranh cho quyền lợi người Infected đơn giản và ngây thơ có một đội vũ trang… em sẽ rất thất vọng. Một sự hiểu lầm nghiêm trọng. Rhodes Island chiến đấu vì tất cả mọi người trên thế giới này. Ông, bọn em, và họ.”","Wei Yenwu im lặng.","“Lungmen không cần sự giúp đỡ của bọn em. Cùng với việc chấm dứt hợp đồng, Rhodes Island cũng sẽ rời Lungmen. Rhodes Island đã làm tròn bổn phận. Mọi thứ đều đã giấy trắng mực đen. Khi bọn em chấm dứt thỏa thuận, mọi điều khoản phụ đều mất hiệu lực theo.”","“Rhodes Island có thể nhận lấy sự hào phóng của Lungmen như một món quà.”","“Không cần đâu, ông Wei. Ở Rhodes Island, bọn em quan tâm đến cách đối tác làm ăn hơn là ‘sự hào phóng’ của họ. Ông Wei, ngay từ đầu ông đã coi bọn em là một quân cờ trong ván cờ của ông. Giờ quân cờ đã chứng tỏ giá trị, việc bọn em rời đi hẳn cũng nằm trong kế hoạch của ông. Tuy nhiên, ông Wei…” Cô bé ngừng lại.","“Cứ nói tiếp.”","“Nếu chỉ có Rhodes Island bị lợi dụng, em sẽ không chấm dứt hợp đồng này. Nghe có vẻ lạ, nhưng em có thể hiểu sự nghi kỵ lẫn nhau giữa các đối tác. Chỉ là, bọn em không phải những người duy nhất Lungmen đang giấu sự thật. L.G.D., người dân Lungmen, người Infected trong khu ổ chuột… Không ai trong số họ biết những thủ đoạn mờ ám ẩn sau bức màn.”","“Ta nghe nói cô đọc được tâm trí, cô Amiya.”","“Ông có thể cho là em không đọc được, hoặc là em đọc được.”","“Ta có thể coi suy đoán của cô là một lời cảnh báo, chứ không phải một cuộc thẩm vấn không?”","“Em sẽ không quyết định chiến lược hay kế hoạch tương lai của Lungmen, ông Wei. Nhưng em có quyền ngăn các operator của mình tham gia vào chúng. Ông Wei, dù là operator Rhodes Island, thành viên Reunion Movement, người lưu vong từ Chernobog, hay công dân Lungmen… Họ đều là những con người đang sống, đang thở. Em không nghĩ việc để cuộc đời họ bị dẫn dắt bởi những mưu đồ bí mật là chấp nhận được.”","“Ta, ngược lại, tin rằng đóng vai trò của mình quan trọng hơn nhiều so với việc có nhận ra vai trò đó hay không.”","“…Không. Ông sai rồi.” Amiya nói chậm rãi. “Có những điều… với ông Wei, có lẽ quá đỗi bình thường. Giống như với người bình thường, cách ly một người Infected là chuyện thường tình, chẳng đáng bàn. Nhưng, dù có ‘bình thường’ đến đâu, nó cũng không nên bị coi là chuyện ‘bình thường’. Chỉ vì một điều đã xảy ra với chúng ta đủ nhiều lần, chúng ta quen với nó, và điều đó khiến nó trở nên chấp nhận được…? Thật vô lý. Nếu không, kể cả có xóa bỏ được Oripathy, xung đột của chúng ta cũng sẽ không giảm đi hay lắng xuống. Chúng chỉ đơn giản bị chuyển sang giam cầm và hành hạ một nhóm người khác… Chỉ là không còn được gọi là ‘người Infected’ nữa.”","“Đây là một yêu cầu… Hay chỉ đơn giản là một lý tưởng?”","“Đây là chuẩn mực của em. Ông Wei, còn một điều nữa em phải nói. —Người sống không phải quân cờ. Con người là con người.”","Wei Yenwu nhìn cô bé một lúc lâu. “Cô có chơi cờ không, cô Amiya?”","“Ông Wei… Ông cầm quân đen, hay quân trắng?”","","Cánh cửa bật tung.","“Wei Yenwu, ông đã làm gì?!”","“Sĩ quan Ch’en, ta đang có khách.”","“Sĩ quan Ch’en?” Amiya quay lại.","Ch’en đứng ở cửa, gương mặt trắng bệch, đôi mắt đỏ rực. Áo khoác lấm bùn, ống quần ướt sũng thứ nước đen sẫm.","“Ông đã làm gì?! Là ông sao? Không, chỉ có thể là ông… Chỉ có thể là ông. Con chuột và người cha xảo quyệt của cô ta cùng lắm chỉ là một trò nghi binh nhỏ. Chỉ có ông mới dám ra lệnh này. Tôi đã nghĩ bằng cách đánh bại Reunion, bằng cách đoàn kết mọi người dân Lungmen, cuối cùng chúng ta sẽ vượt qua được. Chúng ta thậm chí có thể xóa bỏ hiểu lầm giữa những người Lungmen… Tôi chưa bao giờ tưởng tượng… nhưng lẽ ra tôi phải nghĩ đến.”","“Một lần nữa ông lại khẳng định mình là chủ nhân của Lungmen. Như ông vẫn luôn là. Nhưng dù vậy… Sao ông có thể…? Sao ông có thể làm chuyện như vậy? Ông san bằng mọi chướng ngại? Ông thiêu rụi mọi thứ trên đường đi? Rốt cuộc ông cúi đầu trước điều gì? Tôi biết các người nghĩ gì về người Infected. Nhưng tại sao?! Tại sao…? Nó không chỉ là…” Ch’en nghẹn lại. “Ông thậm chí không dám chịu trách nhiệm cho nó. Xóa tên, xóa dấu vết, xóa mệnh lệnh, che đậy mọi dấu chân. Wei Yenwu, ông và Lin nên đổi chủng tộc cho nhau đi.”","“Cô nói mà không suy nghĩ,” Wei Yenwu nói, giọng lạnh đi. “Tổng Thanh tra Ch’en, ta không biết cô đang nói đến chuyện gì. Ta mong lời giải thích của cô đủ thuyết phục.”","Ch’en im lặng một lúc. “Được thôi, vậy tôi vào thẳng vấn đề. Có phải ông đã giết cha của Talulah không?”","“…Sĩ quan Ch’en?”","“Có phải ông đã ép mẹ chúng tôi lấy người đàn ông hèn nhát đó không?”","“Ai đã gieo những ý nghĩ đó vào đầu cô?”","“Ông đoán thử xem?”","“Hãy chú ý giọng điệu của cô.”","“Ngài Wei, người kiểm soát mọi thứ ở Lungmen, đột nhiên nhận ra bí mật ông giấu suốt bao năm từ lâu đã chẳng còn là bí mật?”","“Sĩ quan Ch’en, biết vị trí của mình đi. Vệ binh!”","“Chính Talulah đã nói với tôi.”","Wei Yenwu đứng sững.","“Đương nhiên, những gì Talulah biết, vốn dĩ chẳng có mấy người biết. Ông giận, vì ông biết điều này có thể đe dọa sự cai trị của ông… Lão già đó, Công tước Kashchey, đã ở trong những cơn ác mộng của ông ngay từ đầu. Và ông chưa bao giờ cảm thấy dù chỉ một chút có lỗi với Talulah, phải không?”","“Sĩ quan Ch’en, đừng suy đoán về những sự thật cô không có thẩm quyền biết, và đừng tin thông tin từ những nguồn không rõ ràng. Cô mệt rồi.”","“Tôi chắc chắn không tin lão công tước đó! Lão suýt hủy diệt toàn bộ Lungmen, và lão là kẻ đã bắt cóc Talulah!”","“Vậy thì…”","“Nhưng tôi nhớ rất rõ… Đó là một ngày nắng. Đêm hôm đó không có trăng, chỉ có vài vì sao. Lão già nắm lấy Talulah và đứng ở phía bên kia của một cây cầu gãy. Và sau lưng ông…” Ch’en nhìn thẳng vào mắt ông ta. “Sau lưng ông là một đám đông người mặc áo mưa đen.”","Wei Yenwu không nói gì.","“Tôi tin Talulah. Tôi luôn tin cô ấy. Đương nhiên tôi biết cô ấy cũng có thể bị lừa. Nhưng nhìn xem ông là loại người gì! Ông sẽ hy sinh bất cứ thứ gì để có được điều mình muốn!”","“Ch’en Hui-chieh!”","“Ông muốn dọn dẹp khu ổ chuột, thậm chí hủy diệt nó! Biết bao người Lungmen, biết bao người Lungmen đã tin chúng ta, biết bao người Lungmen đã luôn đứng sau lưng chúng ta… Có phải vì người Infected không được tính là công dân Lungmen? Vì họ không đủ tiền sống trong những tòa cao ốc của ông? Hay vì một ngày nào đó người dân khu ổ chuột sẽ chung sống hòa bình với người Infected? Ông có thật sự đang bảo vệ Lungmen không? Chẳng phải chính ông mới là mối đe dọa cho thành phố này và người dân của nó sao? Đừng nghĩ ông có thể ném vài con chuột ra phía trước rồi thoát tội! Nhà họ Lin sẽ không dám làm chuyện này nếu không có sự cho phép của ông!”","“Cô Ch’en,” Wei Yenwu nói, rất chậm. “Cô chẳng biết gì cả… Về những gì ta đã làm cho Lungmen.”","Ch’en im lặng. Rồi cô ta nói, giọng khàn đặc. “Điều luôn khiến tôi khó chịu nhất ở ông là cái thái độ này của ông, lúc nào cũng phải nắm mọi thứ trong đôi bàn tay bẩn thỉu của mình.”","","“Nếu hai người có thể dành ra chút thời gian rảnh, tôi muốn hai người nghe một tin nhắn.”","Kal’tsit đứng ở cửa, mặt không biểu cảm.","“Bác sĩ Kal’tsit?” Amiya quay lại.","“Xem thiết bị của em đi. Tôi đã gửi chi tiết rồi.”","“A… vâng.” Amiya nhìn màn hình. Rồi mắt cô bé mở to. “…Cái gì?”","“Ta không nhớ đã cho phép cô vào phòng khách của ta, bác sĩ Rhodes Island,” Wei Yenwu nói.","“Em cho cô ấy vào,” Fumizuki nói, bước ra từ sau tấm bình phong. “Đã bao nhiêu năm rồi, sao anh vẫn như vậy…? Anh không mệt mỏi vì phải giấu con bé mọi thứ và tự mình làm tất cả sao? Nghe khách của chúng ta nói đi. Chúng ta cũng nhận được cùng một tin nhắn. Lẽ ra anh đã biết sớm hơn ba phút.”","Wei Yenwu im lặng một lúc. “Được rồi, bác sĩ Kal’tsit. Mời cô.”","“Chỉ huy tối cao của địch không có mặt khi chúng ta quét sạch Reunion ở Lungmen,” Kal’tsit nói. “Đơn giản là vì cô ta đang ở Chernobog. Cô ta đã theo dõi chúng ta, hoặc bình thản, hoặc vô cùng lo lắng… Nhưng chúng ta chẳng hề để ý đến cô ta. Và giờ, một phần của Chernobog, chính xác là phần lõi của nó… đang tiến về phía Lungmen. Ba mươi sáu giờ nữa, lõi đô thị của Chernobog sẽ va chạm với Lungmen.”","“Chuyện vặt thôi,” Wei Yenwu nói. “Lungmen có cách phòng thủ trước nomadic city và chiến hạm. Một cái lõi đô thị cỏn con chẳng có gì đáng lo. Thậm chí chúng ta còn không cần phải…”","@cg:avg_6_12","Ông ta khựng lại.","“Chúng ta đã hiểu nhau chưa, Trưởng quan Wei?” Kal’tsit hỏi.","“…Đã bắt đầu rồi sao…”","“Phát tràn ngập mã nhận dạng đô thị?”","“Không.”","“Đúng vậy, trực giác của ông, hay sự giả định của ông, là chính xác. Lõi đô thị đó đang phát mã liên tục không ngừng. Mọi thành phố phụ của Lungmen đều đã nhận được. Những mã đó tuyên bố—”","Kal’tsit nhìn ra ô cửa kính, về phía chân trời mờ mịt nơi một bóng đen khổng lồ đang hiện dần.","“‘Thành phố này thuộc về Ursus.’”"],"bg":"bg_indoor_n","cast":[["Ch'en","op:char_010_chen"],["Amiya","op:char_002_amiya"],["Blaze","npc:char_017_homura_3"],["Wei Yenwu","npc:char_2005_weiyw_1"],["GreyThroat","op:char_367_swllow"],["Swire","op:char_308_swire"],["Kal'tsit","op:char_003_kalts"],["Fumizuki",null]]}],"id":"main_6","no":"Chương 6","title":"Hoại tử cục bộ","en":"Partial Necrosis","sum":"Trận quyết chiến ở Lungmen. Mephisto biến đồng đội thành bầy quái vật, những bóng áo mưa đen của Lungmen lặng lẽ thanh trừng khu ổ chuột, Faust chọn con đường cuối cùng, còn Doctor rơi xuống tầng sâu nhất của thành phố cùng FrostNova."},{"secs":[{"c":"7-1","t":"Ba mươi hai giờ","p":["<i>Một con quái vật già từng nói với tôi… Thứ gì không giết được mày sẽ khiến mày mạnh hơn.</i>","@cg:avg_7_1","<i>Tôi luôn thấy câu đó thật ngu ngốc. Nhưng gã là quái vật, nên có lẽ tôi cũng phải nghĩ lại một chút.</i>","<i>Con sâu lao vào lửa thì có mạnh hơn không? Ngu thật. Con sâu lao vào lửa chỉ chứng minh rằng hơi nóng đã nấu chín bộ não của nó, nếu nó có não. Còn nếu tôi lao vào lửa thì sao? Ngoài việc chứng minh rằng tôi điên, nó còn chứng minh được gì nữa? Tôi sẽ cháy sém một chút, nhưng điều đó làm tôi mạnh hơn kiểu gì?</i>","<i>Mà chúng ta đang nói về cái chết đấy. Một con quái vật không bao giờ chết thì biết gì về cái chết chứ?</i>","","“Cô vẫn chịu nói chuyện với tôi à? Bất ngờ đấy,” W nói. “Tôi tưởng cô đang mải mê với kế hoạch san bằng Lungmen cơ, Talulah.”","“W. Cô đến mà không báo trước.”","“Ha. Ối, lỗi của tôi. Làm lính đánh thuê lâu quá nên quên mất vụ phải báo cáo từng chi tiết đời mình cho sếp. Xin lỗi nhé, Thủ lĩnh. Nhưng cô biết đấy, tôi không lên được tận đỉnh tháp chỉ huy, nên đành phiền cô hạ mình xuống tầm của tôi vậy.”","“Lời mỉa mai của cô chẳng giúp ích gì cho chúng ta,” Talulah nói. “Reunion cần sức mạnh của người Sarkaz. Chúng ta nên cố đừng tạo thêm mâu thuẫn cá nhân.”","“Cứ gọi bọn tôi là quỷ đi. Chỉ đám tốt bụng giả tạo mới gọi bọn tôi là Sarkaz. Lính đánh thuê như bọn tôi biết rõ mình là cái gì.” W nhún vai. “Người của cô gọi bọn tôi là quỷ đâu phải vì ghét, hay vì nghe cho kêu. ‘Quỷ’ là chữ dành cho nỗi sợ. Các người gọi bọn tôi như thế vì các người sợ bọn tôi. Và bọn tôi luôn đảm bảo rằng bất kỳ kẻ nào còn sống sót đều thấm thía cái ẩn ý đó.” Cô ta cười khẩy. “À, xin lỗi. Tôi lải nhải chuyện này trước mặt cô chẳng khác gì múa rìu qua mắt thợ. Xét về khoản dọa người, chẳng ai qua được cô đâu, Thủ lĩnh.”","“‘Gieo nỗi kinh hoàng cho kẻ thù, mang hơi ấm đến cho bạn bè,’” Talulah nói. “Đó là cách Reunion luôn làm.”","“Vậy việc lái lõi đô thị của Ursus đâm vào Lungmen cũng là theo ước nguyện tha thiết của đồng chí nào đó hả?”","“Các chiến binh của chúng ta vẫn đang anh dũng chiến đấu trong Lungmen. Họ cần chúng ta hỗ trợ. Người Infected ở Lungmen cần hy vọng.” Talulah ngừng lại. “Điều này cũng có lợi cho người Sarkaz, ta đảm bảo. Thứ các cô tìm kiếm không phải là hy vọng, nên ta sẽ cho các cô lợi ích. Sau Lungmen, sẽ chẳng còn nomadic city nào an toàn. Đồng loại của cô sẽ có thêm chỗ để bành trướng.”","“Nghe được đấy. Chỉ xét về lợi nhuận thôi là tôi đồng ý cả hai tay.” W nghiêng đầu. “Giờ nói về nhiệm vụ của tôi nhé. Tin xấu là tôi thất bại. Không mang được mục tiêu về, mà cô bé cũng chẳng chịu đưa tôi món đồ.”","“Không phải lỗi của cô. Quan hệ máu mủ giữa Misha và Skullshatterer chắc chắn sẽ sinh ra những bất trắc.”","“Vậy sao cô lại bắt tôi đi tóm con gái của tay nhà khoa học đó? Có vẻ cô chẳng cần đến cô bé hay bí mật của cô bé cho kế hoạch lớn của mình.”","“Chiếc Chìa khóa cần được xác minh,” Talulah nói. “Ta có thể tự xác nhận việc khởi động lõi đô thị. Nhưng Reunion cần toàn quyền kiểm soát cách nó dừng lại. Chiếc Chìa khóa thật đã mất cùng cái chết của Misha. Thứ mà Patriot tìm chỉ là phương án dự phòng.”","“Tôi muốn biết có bao nhiêu chiếc Chìa khóa. Tôi hứa sau đó sẽ không hỏi gì nữa, được chứ?”","“Hai. Sergei, nhà khoa học hoàng gia của Chernobog, giữ một chiếc và đã gửi nó cho Misha bằng cách đặc biệt. Chiếc kia thuộc về Bá tước Boris, cựu thị trưởng Chernobog. Trong cuộc tấn công của chúng ta, ông ta đã tách một mảng thành phố để trốn đi. Nhưng ông ta không thoát được Catastrophe.”","“Thành phố vệ tinh đổ nát.”","“Người của chúng ta cài trong đó đã giữ lại mọi thứ ta cần.”","“Cô giỏi giải thích thật đấy, Thủ lĩnh. Tôi hết câu hỏi rồi.”","“Nếu sự cởi mở có thể hóa giải hiểu lầm giữa chúng ta, ta sẽ không tiếc thời gian,” Talulah nói. “Chúng ta cần hỗ trợ nhau để vượt qua những rắc rối sắp tới.”","“Thật sao? Cảm động ghê.”","“Tất nhiên.”","<i>Tôi chưa bao giờ ưa người phụ nữ này.</i>","<i>Tôi nói dối rất nhiều. Chẳng có gì mạnh hơn một lời nói dối đặt đúng chỗ, trừ mấy quả bom. Sự thật giống một cốc nước. Nhà đang cháy thì một cốc nước giúp được gì? Nhưng khi tôi nói dối, tôi biết mình đang nói dối. Còn ả rồng cái này, ả nói dối tự nhiên đến mức như thể lời nói ấy thoát ra từ miệng kẻ khác. Ả không chỉ chỉnh vài chi tiết để che giấu kế hoạch. Ả biến thành hẳn một hình dạng khác, thành thứ người đối diện tin tưởng hơn, nói những điều họ muốn nghe. Đứng với tôi, ả là một thương nhân. Đứng với Patriot, ả hóa thành một nữ chiến binh.</i>","<i>Ả có khuôn mặt thật không nhỉ? Hay ả là củ hành, bóc hết lớp này đến lớp khác rồi mới nhận ra bên trong chẳng có gì?</i>","“Ta thật lòng mà,” Talulah nói.","Cô ta khẽ nâng tay lên.","<i>Ha. Tôi biết trò đó.</i>","<i>Có thứ gì đó hút hết không khí trước mặt tôi. Chỉ một tích tắc nữa thôi là toàn bộ cơ thể tôi sẽ tan chảy. Chưa ai hiểu nổi những thứ vô hình mà Talulah ném ra. Nhưng tôi biết rõ chúng làm gì. Phế tích. Tro vụn. Mọi thứ mất cả cấu trúc cơ bản nhất của nó. Giống như một ngọn lửa không có ánh sáng.</i>","“Đừng bảo là cô định giết tôi chỉ vì bị trêu vài câu nhé,” W nói. “Lộ quá rồi, rồng cái. Talulah ngày xưa sẽ không lật bài sớm thế này đâu.”","Thiết bị nhỏ mà W đã thả xuống đất từ lúc nói chuyện nổ bùng thành một quả cầu lửa trước mặt cô ta. Một luồng nhiệt ập tới. May thay, hơi ấm dễ chịu ấy không phải của Talulah.","<i>Tôi chẳng phải chuyên gia Arts gì. Nhưng theo kinh nghiệm của tôi, chín mươi chín phần trăm Arts trên đời không chống lại nổi một vụ nổ thuần túy. Nhiệt, mảnh vỡ, sóng xung kích. Một sức mạnh công bằng xé nát mọi kẻ thù, kể cả tôi.</i>","“Mánh vặt của cô lại vô hiệu hóa được Originium Arts của ta,” Talulah nói. “Có lẽ ta đã đánh giá thấp cô. Cô đã chuẩn bị từ trước. Cô định tấn công ta ngay từ đầu.”","“Cô ra tay trước mà, rồng cái. Cô định thiêu tôi vì tôi phiền, hay muốn bịt miệng tôi vì tôi đã nhìn thấu cô?”","Một luồng nhiệt lao ra từ đầu ngón tay Talulah. W gập người lăn đi một vòng khoa trương như thể đang cúi xuống buộc dây giày.","“Ối. Lần sau ngắm cho chuẩn vào.”","“W, những thủ đoạn bẩn thỉu của cô đã bị phơi bày. Giờ cô là kẻ thù của Reunion,” Talulah nói. “Cô… muốn ngăn ta dùng lõi đô thị tấn công Lungmen.”","“…Ồ?”","“Nếu chỉ muốn trả thù, cô sẽ không chọn lúc này. Nếu muốn giết ta, cô hoàn toàn có thể đợi đến khi cả Lungmen lẫn ta đều kiệt sức. Một thủ lĩnh lính đánh thuê chẳng quan tâm Reunion đi về đâu sẽ không hỏi ta về kế hoạch.” Giọng Talulah trở nên dịu dàng. “Ta quý cô, W. Cô là một tên hề vui tính. Ta không muốn xử tử một tên hề vô hại. Cô thật sự hung tợn và điên loạn như những màn diễn của cô sao? Không. Cô muốn ngăn Reunion. Cô muốn ngăn cuộc tấn công vào Lungmen. W ơi W… cô dễ đọc quá. Ta thậm chí chẳng cần lên kế hoạch điều tra cô.”","“Nói nhảm. Tôi sẽ biến cô thành một vũng máu thịt rồi bảo người đổ xuống ống rác, nếu còn sót lại gì.”","W ấn nút trên thiết bị trong tay. Một kíp nổ Originium đơn giản, điều khiển từ xa, kích nổ dây chuyền.","<i>Ánh sáng hủy diệt chói lòa, sóng nhiệt mang theo mảnh vụn, lật tung mọi thứ trước mặt tôi. Đúng như kế hoạch, mọi thứ hóa thành tro, kể cả tên Sarkaz da dày nhất…</i>","<i>Khoan…</i>","<i>Khoan đã, chẳng phải tôi đã cài kíp nổ cho đống thuốc nổ sao?</i>","Talulah đã cắm thanh kiếm xuống nền.","“Đây là cái bẫy của cô à? Thử lại đi, W của người Sarkaz.”","<i>Không có lửa. Không có cháy. Hàng trăm khối thuốc nổ Originium tôi kỳ công quấn vào móng thép của thành phố… biến mất cả rồi. Chỗ tôi cài thuốc nổ đã méo mó, chảy ra, cong vênh. Những giọt sắt và lớp sơn dầu cháy khét bốc mùi hôi. Chỉ vậy thôi. Ả rồng cái xảo quyệt đã truyền Arts vào thanh kiếm, dẫn sâu xuống lớp thép dưới chân. Hơi nóng lan đến từng cái bẫy của tôi, làm chúng chảy ra.</i>","<i>Vụ nổ tận thế lẽ ra phải thổi ả thành hàng tỷ mảnh… chỉ còn là một tiếng xì hơi ướt át.</i>","<i>Được rồi. Tôi bị chơi một vố đau thật.</i>","“Khụ, khụ…” W loạng choạng. “Rồng cái, cô… cũng không tệ đâu…”","“Để ta đoán nhé. Phương án dự phòng của cô là một màn đánh bom tự sát ngẫu hứng, đúng không?” Talulah nói. “Đừng phí thời gian của nhau nữa. Chọn cách chết đi. Chết trong lửa của ta, bị ném khỏi tường thành, hay bị kiếm của ta xuyên qua.”","“Cô thật sự… kết liễu được tôi sao?”","“Thép phải trải qua ngàn lần tôi luyện trong lò mới thành kiếm. Một thanh kiếm sinh ra đã là vũ khí. Còn cô… chỉ là một cái vỏ phàm trần chưa chết mà thôi.”","“Bị thanh kiếm này đâm xuyên… Tôi sẽ là… người đầu tiên chứ?”","“Tiếc thay, cô phải chấp nhận vị trí thứ hai.”","“Còn nếu nói về những người tôi từng cho nổ tung… Cô thì…” W cười khục khặc. “…còn chẳng có nổi một con số.”","<i>Tôi sắp chết sao? Chắc vậy. Nhưng chết thì có gì tệ? Có nhiều thứ còn tệ hơn cái chết. Nên khi thấy mình tiêu đời rồi… chỉ cần mày đã chuẩn bị cho những thứ tệ hơn cái chết, mày sẽ tự làm chính mình bất ngờ.</i>","<i>Giờ thì… đến lúc tôi cũng chuồn khỏi đây rồi.</i>","Một tiếng nổ. Talulah ho khan, tay áo bốc khói.","“Cô tự nổ tung ngay trong tay ta…? Ta tưởng cô sợ chết hơn thế chứ.” Cô ta nhìn xuống khoảng trống trước mặt. “Việc cô phản bội không làm ta bất ngờ. Nhưng bản thân cô thì… có làm ta bất ngờ một chút. Cô có chút tiềm năng… làm màn mở đầu cho một vở hài kịch. Mong cái chết của cô đủ đau đớn, W của Victoria.”","","<i>Sau trận chiến. Ba mươi mốt giờ trước va chạm. 6:30 tối.</i>","Patriot bước vào, dáng người khổng lồ che lấp cả khung cửa.","“Thủ lĩnh.”","“Thưa ngài. Ngài trở về khiến ta yên tâm hơn nhiều.”","“Không cần nghi thức. Ở đây, có trận chiến. Vừa xong.”","“Là giữa ta và W, kẻ định ám sát ta. Đừng lo, ta không sao.” Talulah nói tiếp. “Theo báo cáo, cô ta đã có dấu hiệu nổi loạn từ khi chiếm đóng Chernobog. Tự ý để kẻ thù trốn thoát, xúi giục lính đánh thuê Sarkaz làm phản, giết cấp trên của mình. Có lẽ đằng sau là thế lực chính trị bên ngoài. Cô ta đã kích nổ chỗ thuốc nổ giấu quanh người và rơi xuống khu vực lõi. Ta sẽ cử người tìm xác.”","“Lẽ ra cô ta, phải ra tòa.” Patriot im lặng một lúc. “Thủ lĩnh. Lõi đô thị này… đã được khởi động. Mà ta không biết. Tại sao? Ngay cả liên lạc. Cũng bị cắt.”","“Chúng ta hết lựa chọn rồi. Ursus có thể tấn công Chernobog bất cứ lúc nào và tàn sát đồng bào của chúng ta. Vì họ, chúng ta phải hạ Lungmen trước. Toàn bộ năng lượng phải dùng để vận hành lõi đô thị, không còn dư để duy trì các kênh liên lạc. Lệnh triệu hồi ngài đã dùng hết nguồn dự trữ cuối cùng. Giờ chỉ còn một nơi có đủ Originium tinh luyện cho chúng ta.”","“Dù vậy, nếu thời gian gấp. Xin hãy bàn với chúng tôi.”","“Ngài nói đúng. Ta xin lỗi. Lẽ ra ta nên suy nghĩ kỹ hơn.”","“Nhưng… việc đã rồi.” Patriot nhìn vật trong tay Talulah. “Chìa khóa này. Cô sẽ dùng thế nào?”","“Nó có thể dừng thành phố. Ta giao nó cho ngài. Ngài sẽ quyết định khi nào chúng ta dừng lại.”","“Nhiều thứ, một khi bắt đầu. Sẽ không dừng lại.” Ông cầm lấy chiếc Chìa khóa. “Ta sẽ đi. Canh giữ lõi đô thị. Sẽ có kẻ tấn công. Chúng sẽ thử. Và ta sẽ chặn chúng.”","“Crownslayer, FrostNova, Mephisto và Faust vẫn đang chờ chúng ta cứu viện. Không được để kẻ ngoài can thiệp vào kế hoạch.”","“…Talulah.”","“Có chuyện gì vậy, chiến binh của ta?”","“Thủ lĩnh. Bất kỳ cái ác nào, dù lớn đến đâu. Rồi cũng sẽ, đến hồi kết. Điều này, ta tin chắc.”","“Vâng, ta cũng có chung niềm tin ấy.”","“…Tạm biệt, Thủ lĩnh.”","“Đi đi, Patriot. Để kết thúc cuộc chiến này và giành lại vị thế cho người Infected, Reunion sẽ nghiền nát mọi kẻ thù cản đường.”","","<i>Một giọng nói lạnh buốt: “Cái gì đây?”</i>","<i>Một giọng khàn khàn: “Một loại, bùa hộ mệnh của Sarkaz. Hai mảnh. Mảnh này, cho con. Mảnh kia, ta giữ. Nó có thể, chịu đựng sự giày vò. Vết thương chí mạng, nội tạng nát, thì không. Nhưng sự hao mòn sinh mạng, nó chịu được. Đến khi nó vỡ. Nếu mảnh của con vỡ… mảnh của ta sẽ rung lên. Và ta sẽ đi. Cứu con.”</i>","<i>“Nếu cả hai mảnh đều vỡ thì sao? …Sao cha không nói gì? Thôi được, con sẽ giữ nó. Đằng nào con cũng sống lâu hơn cha, nên cha cứ lo việc của mình đi.”</i>","","Patriot đứng một mình trong hành lang. Bàn tay ông siết chặt một mảnh đá nhỏ.","“Cứu, ai? Kết thúc, cuộc chiến nào?” Ông thì thầm. “Bùa của ta. Nó cũng, đã vỡ rồi.”","","Những chiến binh Sarkaz đứng thành hàng trước Talulah.","“Cô giết W,” một tên nói. “Giờ cô định làm gì?”","“Giải phóng các ngươi. Các ngươi sẽ không bao giờ phải cúi đầu trước một người Sarkaz nữa. Mọi thứ các ngươi khao khát, ta sẽ ban cho.”","“Đó là gì?”","“Chiến tranh,” Talulah nói. “Các ngươi sẽ không còn phải nếm vị chua chát của việc tàn sát kẻ yếu. Không còn phí sức như hòn sỏi ném vào đá. Ta sẽ cho các ngươi một cuộc chiến thực sự cân sức. Người Sarkaz, lũ quỷ lang thang. Thứ ta ban cho các ngươi… không chỉ là nỗi sợ của nạn nhân. Ta sẽ rèn lại máu, thịt, thép, và nỗi nhục của bao thế hệ tổ tiên các ngươi. Ta ban cho các ngươi sự tàn sát, và ta ban cho các ngươi cái chết. Một kỷ nguyên mới đã đến, chiến tranh sẽ ngự trị. Những người Sarkaz nào muốn nếm trải kỷ nguyên mới này, hãy bước lên.”","Im lặng. Rồi một giọng hỏi:","“Cô muốn chúng tôi giết ai?”"],"bg":"bg_cenbri","cast":[["Talulah","npc:avg_npc_078"],["W","npc:avg_npc_046"],["Patriot","npc:avg_npc_025_1"]]},{"c":"7-2","t":"Đêm chia ly","p":["<i>6:30 tối. Rhodes Island.</i>","“Số hiệu 00000-00002, cấp độ truy cập 8,” PRTS nói. “Doctor, cảm ơn đã ghé thăm Đơn vị Xử lý Sinh học Tích hợp của Rhodes Island. Hệ thống phát hiện tâm trạng của bạn đang tệ.”","“Để tôi yên.”","“Xin cứ tự nhiên. Hệ thống đối xử bình đẳng với tất cả. PRTS được trang bị chức năng trấn áp phi sát thương. Nếu bạn hành động thiếu lý trí, bạn sẽ mất ý thức trong 3,55 giờ làm việc.” Một nhịp ngừng. “Chào mừng về nhà, Doctor.”","“Đây có thể gọi là nhà được sao?”","Doctor đứng giữa căn phòng trắng toát lạnh lẽo, trên tay là thi thể FrostNova. Cô gái tóc trắng giờ nhẹ bẫng, như thể cái lạnh đã mang đi mọi sức nặng của cô.","“Ngài là Doctor phải không?”","Một cô bé đứng ở cửa. Nhỏ nhắn, đôi tai mèo hơi cụp xuống, giọng nói nhẹ đến mức gần như tan vào tiếng máy chạy.","“Là ngài. Em chắc chắn. Em cảm nhận được… ngài hơi khác.” Cô bé nhìn FrostNova. “Nhưng… người ngài đang bế, bộ đồng phục đó… Em hỏi được không, đó là ai vậy?”","“Một người bạn.”","“Bạn ạ? Nhưng… ngài gần như không biết gì về chị ấy.” Cô bé ngập ngừng. “Ngài có vẻ như đã đánh mất thứ gì đó.”","“Em… cảm thấy gì?”","“Dấu vết của những người từng trò chuyện với nhau. Mùi hương, hơi ấm, hình dáng. Em không chắc, nhưng chị ấy…”","Cô bé đưa tay về phía FrostNova. Doctor khẽ lắc đầu.","“Ngài không muốn em làm vậy ạ? Không. Em là người ngoài. Em không quen chị ấy. Em xin lỗi.”","“Em đọc được suy nghĩ, như Amiya sao?”","“Không, em không thể… Amiya đặc biệt lắm. Em biết Arts của Amiya… và em nghĩ chị ấy chịu đựng nhiều lắm. Em không chạm được vào chị ấy, cũng không cảm nhận được chị ấy.” Cô bé cúi đầu. “Các operator khác cũng nói vậy. Ở Rhodes Island có nhiều người tính cách lớn lắm… Nhưng có lẽ ngay cả với họ, em cũng kỳ lạ.”","“Xin lỗi, cô bé.”","“Không sao đâu ạ. Em quen rồi. Em thà người ta thẳng thắn với em còn hơn là sợ em.” Cô bé nhìn cỗ máy. “Ngài… muốn dùng cái máy này ạ?”","“Nếu đây thật sự là nơi yên nghỉ cuối cùng của người Infected.”","“…Đúng vậy ạ. Chờ em xem nhật ký đã. Họ dọn ngăn này rồi. Đặt chị ấy lên tấm phiến này. Nhẹ thôi. Rồi tấm phiến sẽ trượt vào đó, đợi nó đóng lại, cuối cùng ấn nút này.”","“Em rành nó quá.”","“Vì em dùng nó nhiều lần rồi. Đây là nơi tất cả người Infected của Rhodes Island kết thúc. Nếu em quen họ, nếu em cảm nhận được họ, nếu họ là đồng đội của em, em luôn tự tay lo cho họ.” Cô bé nói nhỏ. “Nó giống như một sợi xích. Hay nói đúng hơn, như nhìn thấy những sợi dây nối giữa người với người. Tiễn những người gắn bó với mình nghĩa là tháo gỡ những sợi dây quanh họ. Đầu kia của sợi dây vẫn buộc vào chúng ta, nhưng dù một đầu đã mất, sợi dây vẫn không rủ xuống. Cảm giác như ngài đánh mất thứ gì đó bên trong mình. Thứ ngài không biết là có ở đó, nhưng biết rằng nó sẽ không trở lại.”","“Sao em lại muốn cảm nhận điều đó?”","“Vì nếu biết trước cảm giác ấy, nó sẽ không bất ngờ đâm vào mình, phải không ạ?”","“Xin lỗi đã làm phiền,” PRTS chen vào. “Mã nhận dạng của Rosmontis, elite operator, sẽ hết hạn sau mười lăm phút. Ngoài ra, đang có giao tranh ở mạn phải. Nếu có thể, xin hỗ trợ sau khi cập nhật mã.”","“À, vâng. Em sẽ đi. Em ghi vào thiết bị rồi.”","“Nhắc lần thứ sáu, nếu bạn cho phép hệ thống truy cập, nó có thể gửi thông tin trực tiếp đến…”","“Không. Chỉ mình em được dùng nó.”","“Đã hiểu.”","“Elite operator…?” Doctor hỏi.","“PRTS đang nói về em.”","“Tôi gọi em là Rosmontis nhé?”","“Vâng… Rosmontis.” Cô bé nhìn tấm phiến. “Còn… chị ấy? Em nghĩ ít nhất em nên biết tên chị ấy.”","“FrostNova.”","“FrostNova… Một cái tên đẹp.” Rosmontis khẽ cúi đầu. “Xin chào, FrostNova. …Tạm biệt.”","","<i>Văn phòng của Wei Yenwu. 6:30 tối.</i>","“Chính xác, ngài Wei. Ba mươi hai giờ nữa, lõi đô thị sẽ va vào Lungmen,” Kal’tsit nói. “Mã nhận dạng đô thị của nó không thay đổi. Nghĩa là lõi của nomadic city Chernobog vẫn là lãnh thổ Ursus.”","“Vậy tấn công nó là hành động chiến tranh…?” Ch’en hỏi.","“Reunion bắt Ursus làm con tin như thế này thật vô lý hết mức,” Wei Yenwu nói. “Chủ nghĩa bành trướng của Ursus được thúc đẩy bởi lòng tham. Nếu có lợi, Đế quốc đã phát động thế chiến từ mấy chục năm trước. Nhưng gây chiến với Yan ư? Yan không gây chiến suốt nhiều thế kỷ không có nghĩa là Yan mất khả năng chiến đấu. Một cuộc thế chiến sẽ khiến cả hai bên kiệt quệ, và Ursus với vô số mâu thuẫn nội bộ sẽ chịu đòn nặng hơn. Chỉ kẻ ngốc và kẻ điên mới gây ra một cuộc chiến tốn kém, không lợi lộc và chắc chắn thất bại.”","“Theo tôi biết, kẻ ngốc và kẻ điên ở các nomadic city nhiều như rươi,” Kal’tsit nói.","“Loại bỏ những kẻ như vậy là một trong những nhiệm vụ quan trọng nhất của ta, và của Hội đồng Nhà nước Ursus. Khi Hội đồng phản hồi, chúng ta sẽ có biện pháp dừng lõi Chernobog. Phần còn lại để các nhà ngoại giao lo.”","“Ông tin Đế quốc đến thế sao?”","“Không. Ta tin vào lợi ích chung. Đế quốc Ursus là một cái xác đang thối rữa, cố làm ra vẻ mạnh mẽ. Ta và Chủ tịch Hội đồng không có thỏa thuận nào, nhưng hai bọn ta còn sót lại chừng ấy lý trí như nhau.” Ông quay sang. “Fumizuki, gửi tin giúp ta…”","“Ừm.” Fumizuki không nhúc nhích. “Có một tin nhắn khác. Cho anh. Bác sĩ Kal’tsit, Amiya, Ch’en… mọi người cũng nên nghe. Nếu anh lại từ chối sự giúp đỡ của họ, chúng ta sẽ thật sự bị cô lập.”","Một đoạn ghi âm vang lên.","<i>“Trưởng quan Wei, ngài phải hành động ngay khi nhận được tin này. Nhóm Ba và Nhóm Bốn đã rút lui. Chúng tôi không thể chạm đến gốc rễ vấn đề. Tôi thậm chí không thể đoán được kẻ đứng sau là ai. Chúng thì thầm từ hàng ghế quan sát của nghị viện, cười nhạo màn trình diễn thảm hại, bất lực của tôi. Nhưng tôi không tìm được bằng chứng nào để buộc tội chúng. Nếu có chuyện xảy ra ở Chernobog, ngài phải làm mọi cách để ngăn nó lại. Điều chúng tôi không làm được, ngài phải làm thay.”</i>","<i>“Tôi không gặp được Chủ tịch Witte. Sứ giả ông ấy cử đến bị những thế lực vô danh chặn đường. Tôi tin rằng trong lòng Ursus có những phe phái đang tranh giành quyền lực. Tôi đã đến Khe nứt Ural và chiếm một trạm liên lạc. Chuyện gì sẽ xảy ra tiếp, chính tôi cũng không biết. Mong được trở về Lungmen, nếm lại hương vị quê nhà.”</i>","“Giờ cậu ấy thế nào?” Wei Yenwu hỏi.","“Không rõ sống chết,” Fumizuki nói.","“Có vẻ Chủ tịch Hội đồng định đứng ngoài xem chuyện diễn biến ra sao,” Kal’tsit nói. “Hội đồng ở trung tâm Đế quốc… nhưng Chernobog giờ ở vùng ngoại vi. Vùng biên phần lớn thuộc về Quân đội và tàn dư giới quý tộc cũ. Phần lớn người Infected của Reunion không được huấn luyện, chẳng có cửa chống lại Vệ binh Ursus và cảnh sát chống bạo động Chernobog… nhưng Catastrophe thì có. Chernobog không kịp tách mảng thành phố. Reunion phải thâm nhập từ sớm để chặn lực lượng an ninh, còn Quân đội thì làm ngơ.” Bà dừng lại. “Đến tận hôm nay, Chernobog và triều đình Ursus vẫn chưa nói một lời. Giờ chúng ta biết vì sao rồi. Ursus đã giao Chernobog cho Reunion. Viết tên cả thành phố và mọi cư dân của nó vào sổ tổn thất.”","“Họ chẳng cần làm gì cả,” Fumizuki thì thào. “Họ chỉ… tránh đường.”","“Nhưng sau Catastrophe, Chernobog chỉ là một thành phố chết, chẳng còn gì giá trị…” Amiya nói.","“Thế nên người Infected mới kéo về Lungmen! Bất kể ai cầm đầu Reunion, mọi yếu tố đều đã xếp hàng hoàn hảo…!”","Wei Yenwu im lặng rất lâu.","“Ra lệnh. Đội Ngự sử phải rút lui, dùng vũ lực nếu cần. Chúng ta chuẩn bị chiến tranh. Phải chắc chắn vô hiệu hóa được cái lõi đó trước khi quá muộn. Và không ai được biết chuyện này cho đến khi lõi Chernobog dừng lại.”","“Ngài Wei?!” Amiya kêu lên.","“Anh định tự mình khơi mào chiến tranh sao?” Fumizuki hỏi.","“Anh trai ta sẽ không đời nào chấp nhận việc ta gây chiến với Ursus. Nhưng ta phải giành thế chủ động, kiểm soát tình hình, kể cả khi phải trả giá bằng cả Lungmen.”","“Kẻ nổ súng trước sẽ bị coi là kẻ xâm lược,” Kal’tsit nói. “Họ sẽ khó tìm được đồng minh. Ngài Wei, tôi tin chúng ta có thể đạt được hòa bình bằng con đường ngoại giao.”","“Cảm ơn lời khuyên, bà Kal’tsit. Nhưng ta e rằng Witte và ta là hy vọng cuối cùng cho hòa bình giữa hai nước. Nếu Witte quá nhu nhược để dùng kênh chính thức ngăn chặn chuyện này, nghĩa là ông ta sẽ gặp quá nhiều sự phản kháng. Nếu lõi không dừng lại, va chạm sẽ hủy diệt Lungmen. Và xung đột tiếp theo sẽ là thảm họa không thể lường được. Giờ chỉ còn Lungmen. Chỉ chúng ta mới dừng được lõi Chernobog.”","Amiya hít một hơi. “Ngài Wei. Rhodes Island…”","“Tôi sẽ đi.”","Tất cả quay lại. Ch’en đứng thẳng, tay đặt lên chuôi kiếm.","“Cô là người Lungmen,” Wei Yenwu nói.","“Tôi có thể rời Lungmen.”","“Thanh tra trưởng Ch’en, đừng làm anh hùng. Đây không phải trách nhiệm của cô.”","“Nếu Lungmen cần một kẻ phản bội, hãy để đó là tôi,” Ch’en nói. “Tôi chán ông lắm rồi, Wei Yenwu. Ông và cái thành phố quý báu của ông. Tôi đã thôi là người Lungmen từ trước khi ông thò móng vuốt vào khu ổ chuột.”","“Giờ không phải lúc tranh luận đạo đức.”","“Họ đã làm gì? Tại sao ông phải làm thế với họ?”","“‘Họ đã làm gì?’” Wei Yenwu lặp lại. “Cô nói ta nghe xem, cô Ch’en. Reunion ẩn náu ở đâu? Chúng lẻn vào thành phố qua đâu? Cô tin người khu ổ chuột, nhưng họ có tin cô không? Ngoài chỉ điểm của cô và tai mắt của Lin Kojui, có ai báo cáo việc người Infected xâm nhập nhà họ không? Cô nhận được dù chỉ một tin báo chưa?”","Ch’en im lặng.","“Có hay không?”","“…Không.”","“Không một ai. Không một người nào đứng ra. Họ thà tin những kẻ khiêu khích ngoại bang còn hơn tin Vua Chuột hay Thanh tra trưởng L.G.D. Ta không trách họ đùm bọc lẫn nhau. Nhưng lẽ ra họ có thể chống lại Reunion. Lẽ ra họ có thể nhờ cô giúp…” Giọng ông lạnh dần. “Chính người dân ở đó không muốn L.G.D. vào khu ổ chuột. Lungmen đã từ chối họ sao? Trả lời ta đi, cô Ch’en. Nhìn vào mắt ta mà trả lời!”","“Không phải lỗi của họ.”","“Vậy thì lỗi của ai? Khu ổ chuột mà cô dốc sức vì nó đã trở thành điểm yếu có thể khiến Lungmen bị hủy diệt. Reunion lợi dụng người Infected ở đó để đánh lạc hướng chúng ta. Và những người Infected đó chỉ đứng nhìn. Nếu Lungmen sụp đổ ở đây, xét cho cùng là do tay họ. Không phải Lungmen từ chối họ. Mà là họ từ chối Lungmen.”","“Vậy nên ông sẽ xử lý họ?”","“Sự thờ ơ và thiển cận đã hủy hoại họ rồi. Ch’en. Ai trong chúng ta cũng nhuốm đầy sai lầm. Ai cũng mắc sai lầm. Tất cả những gì ta làm được là sửa chúng, hoặc che giấu chúng một thời gian.”","“Ai cũng mắc sai lầm sao? Tôi hiểu ông đang nói gì,” Ch’en nói. “Người Infected là một sai lầm, chừng nào họ còn tồn tại trong thành phố này?”","“…Con bé cứng đầu.”","“Vậy thì được.” Ch’en hít một hơi. “Wei Yenwu, việc tôi phải làm, việc L.G.D. phải làm, là gọi tên kẻ có lỗi và sửa chữa sai lầm. Theo định nghĩa của ông, có vẻ tôi chính là kẻ có lỗi. Cũng có thể nói tôi chính là sai lầm. Vì tôi là người Infected.”","“Cô—”","“Ch’en?!” Fumizuki thốt lên.","“Không cần giấu nữa. Suốt ba năm ông đã giấu chuyện tôi nhiễm bệnh. Giờ người Infected không còn chỗ trong thành phố này, thì tôi cũng vậy. Cô ấy và tôi đều là người Infected. Chỉ tôi mới ngăn được cô ấy.”","<i>“Đừng buồn. Tôi hiểu mà. Chúng ta là huynh đệ kết nghĩa, phải không? Huynh đệ… hãy nhớ chúng ta đến từ đâu.”</i>","<i>Nghĩa huynh đệ tan vỡ.</i>","<i>“Tôi hận anh. Và tôi hận họ. Lẽ ra tôi phải yêu anh, nhưng lúc này tôi hận từng người một trong các người.”</i>","<i>Tình máu mủ tan vỡ.</i>","<i>“Tại sao lại là tôi? Tại sao phải là tôi? Ai có thể thấy an toàn khi ngồi ở đây chứ?”</i>","<i>Tình thân tan vỡ.</i>","“Không,” Wei Yenwu nói. “Nếu hôm nay cô bước ra khỏi văn phòng này, Ch’en Hui-chieh… cô sẽ là kẻ thù của Lungmen. Cô sẽ không bao giờ được đặt chân vào thành phố này nữa. Và mọi thứ chúng ta cùng gây dựng suốt mười năm qua… sẽ thành hư không.”","“Mọi thứ tôi gây dựng đã thành hư không ngay khi ông làm điều ông đã làm,” Ch’en nói. “Khác biệt duy nhất là tôi không giống ông. Tôi không nghĩ có ai là ‘sai lầm’.”","“Quyền lực rốt cuộc chỉ là công cụ. Nếu muốn dùng nó để sửa đổi thế giới, cô phải tuân theo những kỳ vọng của thế giới. Đừng tự biến mình thành trò cười, Thanh tra Ch’en. Ta nuôi dạy cô để thay đổi điều đó. Ta mong cô sẽ khiến thế giới này muốn nhiều hơn là sự thịnh vượng và phát triển.”","“Vậy nó đã thay đổi chưa? Có thể thay đổi được không? Những gì tôi đã làm có ý nghĩa gì không?”","“Dù bây giờ không thể, một ngày nào đó cũng phải thay đổi. Cô sẽ là người đảm bảo điều đó.”","Bên ngoài, tiếng lễ tân hét lên: “Đứng lại! Các người là ai?! Bảo vệ đâu?! Có kẻ đột nhập!”","Những bóng áo choàng đen tràn vào phòng.","“Ngài Wei, chúng thần sẽ hành động.”","“Cút ra ngoài,” Wei Yenwu nói. “Các ngươi không nên đến đây.”","“Ha… haha, ahahahaha…” Ch’en bật cười. “Wei Yenwu, chỉ cần thế thôi là ông lộ bản chất rồi à? Đội quân riêng của ông xuất hiện ngay trong văn phòng ông?”","“Ngài Wei… chúng thần có thể thâm nhập thành phố kia, giết kẻ cầm đầu và ngăn va chạm! Chúng thần nguyện hy sinh vì thành phố, gỡ gánh nặng này khỏi vai ngài!”","“Cút ra!”","“Sao nào, Wei Yenwu? Ông sẽ cử họ đi, hay cử tôi? Lựa chọn khó khăn lắm à?” Ch’en nói. “Sao ông luôn quyết đoán khi giết người mà lại do dự khi phải cứu người? Bây giờ là vậy. Hồi đó cũng vậy.” Cô quay sang Fumizuki. “Tôi không ngờ có dịp nói lời tạm biệt đàng hoàng. Cô Fumizuki, xin lỗi vì mẹ tôi đã đối xử với cô như thế. Cảm ơn cô đã chăm sóc tôi suốt những năm qua. Tôi luôn coi cô là người nhà.”","“…Ch’en?!”","“Thanh tra trưởng Ch’en!” Wei Yenwu quát.","@cg:avg_7_2","“Không còn nữa. Tấm huy hiệu này? Trả lại ông.”","“Bắt cô ta lại!”","“Muốn đánh nhau ở đây trước sao? Để xem ai mới là kẻ phản bội thật sự?”","“Thanh tra trưởng, kẻ thù đã đến trước cổng!”","“Tôi là người Infected. Tôi là kẻ thù lớn nhất của các người.”","“Dừng tay! Nếu không ta sẽ không nương tay!”","“Các người đã từng nương tay với ai chưa?!” Ch’en rút kiếm. “Chi Xiao – Khởi khí!”","<i>“Anh à, nếu thanh kiếm này dùng để chém rồng, vậy nó có chém được Draco không?”</i>","<i>“Có thể lắm. Xem ra anh phải cẩn thận với em hơn rồi, haha…”</i>","“Arts của cô ấy… đang tràn ra?” Kal’tsit nheo mắt.","“Doctor, ra sau em! Em sẽ chặn Arts!” Amiya kêu.","“Không. Trước sức mạnh ấy, nó sẽ bị xé toạc thôi. Cô ấy không nhắm vào chúng ta. Ra khỏi tầm của cô ấy ngay. Lùi lại!”","“——Phóng!”","Lưỡi kiếm đỏ rực chém xuống. Một bóng áo đen đưa cổ tay ra đỡ.","“Thanh kiếm chém rồng… đã rút khỏi vỏ?!”","“Anh đỡ được bằng cổ tay thôi sao?” Ch’en nói.","“Tinh tường lắm! Kiếm thuật của Thanh tra trưởng sắc bén hơn bao giờ hết!”","“…Originium tôi luyện. Chi Xiao à?” Kal’tsit lẩm bẩm. “Không ngờ người ta vẫn còn rèn những vũ khí như thế…”","“Doctor, thanh kiếm đó được rèn đặc biệt để chống lại Arts dạng năng lượng sao?” Amiya thì thầm. “…Lúc đầu, cô Ch’en thậm chí không cho em nhìn thanh kiếm ấy. Phải chăng cô ấy đã hình dung đến lúc em trở thành kẻ thù…?”","“Tránh đường!”","“Ngài Wei, Thanh tra trưởng đã chọn con đường của mình. Thần e không đỡ nổi nhát thứ hai. Thần có nên liều mạng không? Bằng cái chết của mình, thần đảm bảo cô ấy sẽ ở lại Lungmen. Dù không chắc tay chân cô ấy còn nguyên vẹn, nhưng cô ấy sẽ sống.”","“Không được phép,” Wei Yenwu nói. “Lùi lại. Đừng giao chiến trực tiếp với nó!”","“Định gọi viện binh à? Chi Xiao—!”","“Dừng lại!!”","Một áp lực vô hình đè xuống khiến Ch’en khựng lại.","“Hui-chieh, cô định dùng thanh kiếm xẻ mây sao?” Wei Yenwu nói. “Đừng quên ai đã dạy cô kiếm thuật và Arts. Ta chưa bao giờ nghĩ sẽ tước đi kiếm thuật của cô, nhưng đến nước này ta sẽ không nhân nhượng nữa. Đừng ép ta, Ch’en Hui-chieh.”","“Vậy thì làm đi, sư phụ Wei. Chi Xiao nghe lệnh tôi. Cái ngày ông trao Chi Xiao cho tôi, ông có nghĩ tôi sẽ chém ông không? Tôi sẽ không dùng nó để đổ máu ông.” Ch’en hạ giọng. “Ông nghĩ ông đang bảo vệ tôi, phải không? Mẹ tôi chết vì trầm uất. Talulah bị bắt đi. Tôi nhiễm Oripathy khi làm nhiệm vụ. Ông nghĩ mọi việc ông làm đều để bảo vệ tôi. Vì lương tâm cắn rứt, hay vì tự tin vào mưu lược của mình?”","“Ta không muốn chứng kiến thêm một bi kịch nào nữa.”","“Nói dối!” Ch’en lùi về phía ô cửa kính. “Có những kẻ thanh kiếm này muốn giết… và những người nó muốn bảo vệ. Nếu cô ấy thật sự muốn hủy diệt Lungmen…! Tôi chưa từng nghĩ sẽ thắng được ông và đám Áo choàng đen ở đây. Nhưng lối ra khỏi đây không chỉ có một, Wei Yenwu.”","“Cửa sổ?!”","“Ch’en Hui-chieh! Dừng trò điên rồ này lại! Chúng ta đang cách mặt đất hàng trăm mét!”","“Đây không phải lần đầu tôi đi đường cửa sổ. Cũng không phải lần thứ hai.”","“Ch’en Hui-chieh, cô không được đến chỗ con bé! Cô không được lặp lại sai lầm! Cô không được đi lại con đường chúng ta đã đi! Nếu có ai phải chết vì thành phố này, người đó phải là—”","Ch’en thở dài.","“Chú…” Cô khựng lại. “Không… Wei Yenwu. Từ hôm nay, chúng ta là người dưng.”","Tiếng kính vỡ vang khắp căn phòng. Ch’en ngửa mặt rơi khỏi tòa nhà cao vút. Chúa tể Lungmen gầm lên, và gã áo choàng đen lao về phía cửa sổ như mũi tên bật khỏi dây cung.","Nhưng Ch’en đã quyết rồi."],"bg":"bg_corridor","cast":[["Wei Yenwu","npc:char_2005_weiyw_1"],["Ch'en","op:char_010_chen"],["Kal'tsit","op:char_003_kalts"],["Fumizuki",null],["Amiya","op:char_002_amiya"],["Rosmontis","npc:avg_npc_042"]]},{"c":"7-3","t":"Lưỡi kiếm phản nghịch","p":["<i>Khu thượng thành Lungmen. 7:00 tối, hoàng hôn.</i>","“Lệnh bắt giữ bí mật? Thanh tra trưởng Ch’en?!” Một sĩ quan L.G.D. siết tờ lệnh. “Chắc chắn có nhầm lẫn… Này! Quay lại đây! Tôi hỏi có nhầm lẫn hay không cơ mà! Chết tiệt, Thanh tra trưởng, chuyện quái gì thế này… Ai đứng sau chuyện này?! Tôi phải tìm cô ấy. Tôi phải nghe cô ấy nói!”","@bg:bg_lungmen_d","“…Vâng. Ta hiểu rồi,” Vua Chuột nói. “Greytail, đi làm những gì ta dặn. Xong việc thì tìm chỗ trốn một thời gian. Đi đi. Nhanh lên.”","Khi chỉ còn một mình, ông lão thở dài.","“Hóa ra thật sự có kẻ chơi lại được Wei Yenwu. Talulah, Talulah… đây thật sự chỉ là số phận thôi sao? Ôi, thiếu gia, nếu ngài nhìn thấy chúng ta từ trên đó, hẳn ngài cũng chẳng muốn thấy cảnh này. Hui-chieh… Hui-chieh! Cẩn thận, Hui-chieh… Con không được chết đấy!”","@bg:bg_lungmenbridge","<i>Bến cảng Lungmen. 7:20 tối.</i>","Những bóng người méo mó, nửa người nửa đá, lảo đảo tiến về phía rào chắn. Bầy chiên của Mephisto. Dù chủ nhân của chúng đã không còn, chúng vẫn bước.","“Chết tiệt, vẫn còn nhiều thế này… Tưởng L.G.D. đã kiểm soát khu này rồi chứ?” Một operator Rhodes Island lùi lại. “Lưới polyfiber và cáp thép bị chúng xé như giấy. Mà trong thành phố thì không được dùng vũ khí hạng nặng… Quét không thấy chút hoạt động não nào. Về cơ bản, chúng đã chết rồi. Chỉ là những cái vỏ rỗng được Arts chống đỡ. Tàn nhẫn không tưởng…”","“Xin chào các operator.” Rosmontis bước ra. “Hôm nay chúng ta đánh với họ sao?”","“Rosmontis! Ơn trời, được cứu rồi.”","“Họ là người Infected bị Arts làm biến dạng…? Kẻ làm chuyện này phải trả giá.” Cô bé nhìn quanh. “Nhưng quan trọng hơn, ít nhất mọi người đều an toàn. Em sẽ… làm họ bình tĩnh lại.”","“Em định chiến đấu sao?” Doctor hỏi.","“Vâng.”","“Nhưng trông em…”","“Doctor… ngài chưa từng thấy Rosmontis chiến đấu à?” Operator nói. “Vậy thì lùi lại đi. Tôi đảm bảo ngài chưa từng thấy thứ gì như thế này đâu.”","Trên đầu họ, một khối kim loại khổng lồ từ landship lơ lửng bay tới, lặng lẽ như một đám mây.","@cg:avg_7_3","“Đó là thiết bị của em sao?”","“Là của em.” Rosmontis ngẩng đầu. “Operator, xin mô tả ấn tượng của anh về mục tiêu.”","“Chờ chút, để tôi xem sổ tay… Mục tiêu là một nhóm lớn cá thể hoạt động, bồn chồn. Di chuyển theo nhóm, không có mục tiêu rõ ràng. Thế được chưa?”","“Đã nhận. Em sẽ xử lý. Bác sĩ Kal’tsit dặn rất rõ: xong việc này, Rhodes Island phải rời Lungmen ngay.”","@bg:bg_turf","<i>Cùng lúc ấy, ở một góc khuất của khu thượng thành.</i>","“Chào buổi tối, bạn già.”","Ch’en đang đẩy chiếc xe địa hình thì khựng lại. Hoshiguma tựa vào tường, khoanh tay.","“Hoshiguma…? Cô làm gì ở đây? Vết thương thì sao?”","“Tôi là Oni. Mấy vết xước đó lành từ lâu rồi.” Hoshiguma liếc chiếc xe. “Chiếc buggy cô đang đẩy là mẫu mới của Rim Billiton phải không? ‘Vượt địa hình tuyệt vời. Chống bụi, leo dốc nhẹ nhàng, tầm hoạt động xa, tiết kiệm nhiên liệu.’ Ừ, xin lỗi. Tôi xem quảng cáo đó trên terminal cả triệu lần rồi.”","“Cô muốn nói gì?”","“Trông cô tệ lắm, Ch’en. Cô định đi đâu?”","“Sao cô biết tôi ở đây…?”","“Lần nào muốn lẻn khỏi thành phố cô cũng đến đây. Tôi cũng thuộc từng ngóc ngách chỗ này mà. L.G.D. đã ra lệnh bắt.”","“Nhưng cô không đến vì chuyện đó.”","“Tất nhiên rồi. Tôi biết rõ cô là người thế nào.”","“Đây là đường duy nhất để tôi rời Lungmen.”","“Vậy thì cô sẽ không bao giờ ra khỏi Lungmen được,” Hoshiguma nói. “Họ cũng giống tôi. Họ không muốn cô đi.”","“Hoshiguma… cô định cản tôi sao? Tại sao lại là cô?!”","“Tất nhiên là tôi, Ch’en. Tôi là thanh tra L.G.D., và quan trọng hơn, là bạn cô. Cô thật sự định lang thang đi đóng vai anh hùng đơn độc trong một cuộc phiêu lưu vĩ đại à? Chính vì vậy tôi không thể để cô đi.”","“Cô là người Lungmen, Hoshiguma! Đây là cơ hội cuối cùng. Nếu để Wei Yenwu làm theo cách của ông ta, sẽ có thêm nhiều người chết!”","“Cách của cô thì tốt hơn sao?” Hoshiguma hỏi. “Họ thật sự yêu Lungmen à, Ch’en? Tôi thì cổ hủ lắm. Truyện tranh, phim, rượu, những con phố mưa, một gã chạy qua không có ô. Người ta bảo có những thứ lỗi thời nhanh lắm. Ch’en, chúng ta có chạy thắng được thời gian không? Tôi thì không. Cuộc rượt đuổi đó đã nghiền nát quá nhiều thứ tôi trân trọng. Những người đó chết thảm thương, hy sinh bản thân để tìm một chỗ đứng trên thế giới. Còn tôi? Tôi chỉ nhìn họ tan thành tro bụi. Có những người, chính đôi tay này đã đập vỡ giấc mơ của họ. Họ không yêu Lungmen. Họ chỉ không còn nơi nào khác để đi. Và rốt cuộc, đó là lỗi của tôi.”","“Ah Faat đã chết, bao nhiêu người đã chết vì Lungmen… Cô định giả vờ như chưa từng thấy sao?”","“Đừng làm như cô quen họ. Họ ở bên tôi lâu hơn cô nhiều.” Hoshiguma nhìn thẳng vào Ch’en. “Cô còn là Thanh tra trưởng Ch’en à? Ai giao trách nhiệm đó cho cô?”","“Chính tôi.”","“…Đó chỉ là thứ cô muốn tự nghe mình nói thôi phải không? Nhìn cô xem. Định một mình cứu Lungmen? Một người phụ nữ chống lại cả Reunion? Cơn giận dỗi của cô không đưa cô đi xa thế đâu.” Hoshiguma cười nhạt. “Buồn cười thật. Cô luôn là người thi hành mệnh lệnh của ngài Wei, vì cô hiểu ông ấy. Giờ tôi lại là người hiểu ông ấy hơn một chút. Tôi đã xem qua kế hoạch của ngài Wei. Nếu phải có người chết, ngài ấy nghĩ đó phải là chính ngài ấy. Ngài Wei thà mình chết còn hơn để cô chết.”","“Cô đánh giá ông ta quá cao.”","“Có lẽ cô đánh giá ông ấy quá thấp, Ch’en. Nếu ngài ấy chết, Lungmen sẽ được gột bớt tội. Ngài ấy muốn cô điều hành L.G.D. Sớm muộn cô sẽ thay ngài ấy, rồi trở thành người đứng đầu cả thành phố. Có rất nhiều thứ mục ruỗng bị bỏ lại, và cô nên là người dọn sạch chúng. Lungmen vẫn cần cô.”","“Tôi phải nói với cô một chuyện, Hoshiguma. Đó là lý do tôi không thuộc về nơi này.” Ch’en ngừng lại. “Tôi là người Infected.”","“…Cái gì?” Hoshiguma lặng đi. “…Từ khi nào…?”","“Ba năm trước.”","“Cô giấu tôi? Ngay cả tôi cũng không nói…?”","“Wei Yenwu không muốn ai biết. L.G.D. không thể có người Infected. Nên tôi không thể là người Infected.”","“Không. Tôi hiểu rồi.” Hoshiguma khẽ nói. “Cuối cùng tôi cũng thật sự hiểu, Ch’en. Tôi hiểu chính xác vì sao cô không thể rời Lungmen. Nếu cô đến lõi đô thị, ngài Wei sẽ phải gắn mác kẻ thù cho cô. Không chỉ kẻ thù, mà là kẻ thù Infected nguy hiểm chống lại Lungmen. Cả thành phố sẽ biết cô là người Infected. Họ có thể còn nghĩ cô cấu kết với Reunion. Và thế là hết. Cô sẽ không bao giờ quay về được.”","“Tôi không quan tâm.”","“Đó là câu của tôi mới đúng. ‘Cô là người Infected? Tôi không quan tâm.’ Tôi không quan tâm. Tiểu thư không quan tâm. Nine không quan tâm. L.G.D. không quan tâm. Ngay cả ngài Wei cũng không quan tâm.”","“Nine đã đi rồi. Cô ấy rời L.G.D. vì cũng là người Infected. Có lẽ chúng tôi nhiễm bệnh trong cùng một nhiệm vụ. Cô ấy làm nội gián cho tôi trong Reunion… rồi vì Reunion mà rời bỏ Lungmen. Vì cô ấy đã thấy sự thật của thành phố này.” Ch’en nhìn Hoshiguma. “Cô có biết ai đang cầm đầu Reunion không?”","“Tôi quên tên rồi.”","“Talulah. Tiểu thư chưa nói với cô sao? Talulah là chị gái tôi.”","“Ồ. Ồồ… Ha. Tôi hiểu rồi.” Hoshiguma đứng thẳng dậy. “Ch’en, hôm nay cô không đi đâu cả.”","“…Tại sao…? Chị tôi, gia đình tôi… không đủ quan trọng sao?!”","“Chính vì thế,” Hoshiguma nói. “Chính vì thế tôi không thể để cô đi. Kể cả khi tôi phải chết ở đây.”","“Không phải cô quyết định chuyện đó, Hoshiguma.”","“Hannya có thể quyết định.” Hoshiguma nhấc tấm khiên lên. “Người thợ rèn tấm khiên này có cả gia đình bị một đám Oni lang thang giết sạch. Cơn thịnh nộ của ông ta độc hơn bất kỳ Catastrophe nào. Ch’en, ngài Wei không phải người tốt. Chúng ta có thể cùng nhau đá đít ông ấy. Cô muốn làm gì, tôi làm cùng cô. Cô muốn chiếc Columbian Big Single 70 vv của tôi à? Nó là của cô. Nhưng giờ không phải lúc. Đừng đi. Đừng ép tôi làm thế này. Tôi chỉ xin cô vậy thôi.”","“Ép cô? Sao cô lại nói giống Wei Yenwu…? Tôi không thích thế. Khi ông ta phản bội anh trai mình, phụ lòng mẹ tôi, và ru cả thành phố ngủ dưới bóng mây đen độc ác, đó là lúc tôi quyết định làm điều này.”","“Cô nghĩ những chuyện đó liên quan đến cô, nhưng tôi thì không,” Hoshiguma nói. “Những gì ông ấy đã làm, những gì ông ấy làm vì cô, và những gì cô nên làm, chẳng có gì nối với nhau cả. Đó là điều ngài Wei mong. Ông ấy không muốn đóng vai kẻ ác. Ông ấy trao cho cô thanh kiếm.” Giọng cô trầm xuống. “Không chỉ một lần. Nó xảy ra hết lần này đến lần khác… Tôi đã phá hủy nhà mình, phá hủy gia đình mình. Mỗi lần, tôi lại đẫm máu từ sừng đến chân, chiến đấu đến cùng, cho đến khi chỉ còn mình tôi đứng vững. Vì tôi nghĩ mình đúng, còn họ sai. Tôi đã tự hỏi rất nhiều lần liệu mình có đáng sống không. Tôi không đáng. Nhưng tôi vẫn sống. Chỉ là tôi không thể sống cho bản thân nữa. Liều mạng vì một khái niệm đúng sai nào đó… là điều ngu ngốc nhất một người có thể làm. Và tôi đã sống cả đời với nỗi hối hận ấy. Cô nghĩ chỉ mình cô mang gánh nặng sao, cô Ch’en?”","“Đừng nói như thế!”","“Tôi đã thấy quá nhiều người chết vô ích. Tôi không quan tâm cô là ai. Tôi chỉ quan tâm cô đi đâu. Đây là chuyện của thủ lĩnh Reunion. Cô không thay đổi được tình hình. Cô cũng sẽ chết vô ích thôi.”","“—Cảm ơn cô, Hoshiguma,” Ch’en nói. “Nhưng tôi vẫn sẽ đi.”","“Thật sao? Cô thấy trái tim mình đang cứng như sắt à?” Hoshiguma thở dài. “Được thôi. Xem ra cô phải ăn đòn mới học được, như Hoshiguma hồi trẻ, rằng ương bướng chỉ là một sự bốc đồng ngu xuẩn. Muốn đánh thì đánh, Ch’en. Cho tôi xem cô học được gì trong hai năm qua.”","“Đừng. Nói. Như. Thế.”","","“Thiết bị Điều khiển Originium Arts Tầm xa EX-42, operator Rosmontis, xin phê duyệt.”","“Phê duyệt sử dụng trong tác chiến phòng thủ. Người dùng: Chuyên gia Hủy diệt, elite operator Rosmontis. Cho phép kích hoạt.”","@cg:avg_7_5_2","“Được rồi. Em đi đây,” Rosmontis nói. “Nhờ anh báo với Closure giúp em, về việc khởi động landship Rhodes Island.”","“Nhanh lên, Doctor, vào cabin đi. Đừng nhìn,” operator kéo tay Doctor. “Nếu dính mảnh vỡ của Rosmontis thì coi như tiêu đời.”","@cg:avg_7_6","","<i>Khu thượng thành Lungmen. 7:20 tối.</i>","Ch’en thở dốc, mũi kiếm chống xuống nền.","“…Cô nghiêm túc thật đấy,” Hoshiguma nói. “Không ngờ đấy. Chưa bao giờ nghĩ cô có thể khiến tôi đổ máu.”","“Chúng ta… chưa bao giờ… thoát được… quá khứ của mình,” Ch’en nói. “Hoshiguma, cô luôn là một phần của thành phố này. Nhưng tôi thì không. Tôi luôn chạy trốn. Tôi nghĩ tôi sẽ không bao giờ chịu nổi nơi này.”","“Rốt cuộc lại thành ra thế này.” Hoshiguma hạ khiên. “Tôi không cản được cô. Đi đi.”","“Xin lỗi, Hoshiguma. Sau khi tôi đi, xin cô đến khu ổ chuột giúp tôi. Người dân ở đó đang hoảng loạn. L.G.D. phải có người bảo vệ họ.” Ch’en ngừng lại. “Nếu có mấy đứa trẻ Infected tặng cô một con gấu bông… hãy giữ lấy. Một cô bé Ursus tên Misha đã dạy chúng làm những con gấu đó. Cô bé chết rồi, vì chúng ta đã phụ cô bé.”","“Được. Tôi sẽ giữ.”","“Tôi xin lỗi. Tôi nợ cô.”","“Tôi không cần cô xin lỗi. Thật lòng mà nói, cô xin lỗi dở lắm.” Hoshiguma quay đi. “…Xong rồi. Đi đi! Và đừng quay lại.”","“…Bảo trọng.”","Tiếng động cơ xa dần. Hoshiguma đứng lại một mình.","“‘Không chịu nổi nơi này’ à?” cô lẩm bẩm. “…Có bao nhiêu người quan tâm đến thành phố này nhiều như cô chứ? Nói nhảm…”","“Thanh tra Hoshiguma!” Một nhóm sĩ quan L.G.D. chạy tới. “…Hả? Thanh tra, ch-chị bị thương? Ai có thể… À, vâng, bọn em vừa thấy, ừm, cô Ch’en——”","“À, chuyện đó, xin lỗi nhé. Các cậu có rảnh nói chuyện một lát không?”","“Thanh tra… chị cũng định trái lệnh sao?”","“…Tôi sẽ không gọi nó như thế.”","@bg:bg_lungmen_o","“Ra ngoài,” Wei Yenwu nói.","“Vâng, ngài Wei.”","“Ta đã bảo… đừng gọi ta như thế.”","Khi những bóng áo đen đã đi hết, Fumizuki quay sang hai vị khách. “Bà Kal’tsit, Amiya, trước khi hai người nói, cho tôi nói với anh ấy vài lời được không?”","“Vâng, chị cứ nói ạ.”","“Chúng ta đã ở bên nhau bao năm rồi, Wei Yenwu,” Fumizuki nói. “Chỉ cần nhìn vào mắt anh là em biết anh đang nghĩ gì. Em biết Lungmen có ý nghĩa thế nào với anh. Em biết anh đã hy sinh những gì cho nó. Nhưng hôm nay, đây không phải điều anh muốn, đúng không? Ý em là… sự thịnh vượng mà anh đã đánh đổi tất cả. Anh đã mất hai người thân. Không, anh từng nói là ba. Hay hàng chục người? Chắc chắn anh không chịu nổi việc mất cả cháu gái mình.”","“Con bé ghét Ảnh vệ. Nếu ta cử họ đi đưa nó về, nó sẽ chiến đấu với họ đến chết.”","“Không, Wei Yenwu… Ý em không phải vậy. Anh không hối hận sao? Nếu để cả hai đứa chết ở một thành phố xa lạ? Chúng là người Infected thì sao? Chúng không phải cháu anh sao? Nếu chúng ta có con, anh cũng sẽ đối xử với chúng như thế sao…?”","“Mọi thứ ta làm đều vì mảnh đất này. Ta chưa bao giờ muốn Ch’en Hui-chieh làm thay việc của ta.”","“Nhưng con bé là như thế đấy! Giấu sự thật chỉ khiến vết cắt sâu hơn. Chỉ khiến nó cảm thấy mình không thuộc về nơi này…”","“Nhưng đến lúc này, ta có thể dừng lại được sao? Lungmen có cho phép ta dừng lại không? Đó là điều con bé muốn. Nó muốn biến thành phố này thành một nơi hoàn toàn khác với thành phố dưới sự cai trị của ta. Ta chỉ dạy nó cách đến được đó, nó phải làm gì, và phải từ bỏ những gì.”","“Thôi đủ rồi, đừng biện minh nữa. Anh làm em nhức đầu đấy,” Fumizuki nói. “Em sẽ tự đi đưa con bé về. Em sẽ làm điều anh không thể làm.”","“Vô lý! Ta không cho phép! Fumizuki, cô không được bước chân ra khỏi tòa nhà này.”","“Ồ? Anh định cản em à?” Fumizuki nheo mắt. “Damare, kono yarou!”","“Ừm? Doctor, chị Fumizuki vừa nói gì vậy ạ?” Amiya thì thầm.","“Lâu lắm rồi tôi mới nghe tiếng Higashi giận dữ đến thế,” Kal’tsit nói.","“Anh quên tôi là ai rồi sao, Wei Yenwu? Anh quên chính anh là ai rồi sao?” Fumizuki quay sang. “Nào, các bạn Rhodes Island. Giúp Lungmen, và giúp Ch’en của chúng tôi, tốn bao nhiêu? Tôi sẽ tự trả. Nói ra thì không phải phép, nhưng hôm nay chồng tôi không được minh mẫn lắm. Hay nói đúng hơn, kế hoạch của đối thủ đã vượt quá mọi dự đoán của chúng tôi, và bao gồm cả những gì anh ấy trân quý nhất. Chúng hiểu thấu cả Lungmen lẫn Wei Yenwu.”","“Tôi hiểu mọi điều cô nói, cô Fumizuki. Tiền không cần thiết. Nhưng tôi cần hai người nghe tôi nói,” Kal’tsit nói. “Rhodes Island chỉ là một công ty dược. Nhưng thế giới này khắc nghiệt. Một công ty dược như chúng tôi gây thù chuốc oán rất nhiều, trong làm ăn, trong địa chính trị, hay ở đâu đó khác. Chúng tôi lang thang giữa những kẽ nứt giữa các quốc gia vì không còn lựa chọn nào khác. Ngài Wei, với sức mạnh của Lungmen và tài năng của ngài, ngài có thể xóa sổ Rhodes Island chỉ bằng một cái búng tay. Nếu chúng tôi chống lại ngài, Rhodes Island coi như chết.”","“Nói tiếp. Bác sĩ Kal’tsit, cô Amiya, yên tâm. Ta chẳng còn sức đâu mà nhắm vào Rhodes Island nữa.”","“Một đồng nghiệp của tôi từng thấy Công tước Kashchey tại một buổi tiệc gây quỹ cùng con gái nuôi của ông ta,” Kal’tsit nói. “Đó không phải chợ nô lệ hay một cuộc truy hoan của quý tộc, mà là một sự kiện dành cho những kẻ có quyền định đoạt thế giới. Đêm ấy nhiều người trẻ đã chứng tỏ giá trị bằng tư tưởng và lý luận của mình. Nhưng Talulah thì không. Cả tôi lẫn đồng nghiệp đều không ngờ cô ấy sẽ trở thành thủ lĩnh Reunion. Lẽ ra chúng tôi phải nhận ra rằng Công tước Kashchey chỉ lộ diện khi cần thiết, để làm điều cần thiết. Ông ta chưa bao giờ biến cô ấy thành nô lệ hay con tin.”","“Con bé là người kế thừa của hắn,” Wei Yenwu nói.","“Ồ?” Fumizuki khựng lại.","“Quan sát của cô xác nhận mối nghi ngờ của ta. Talulah là người kế thừa của Kashchey.”","“Chính xác. Công tước Kashchey biết ngài có gì và làm được gì. Talulah có lẽ cũng biết,” Kal’tsit nói. “Ngài có thể giao việc này cho chúng tôi. Như Amiya đã nói, thỏa thuận chính thức giữa Lungmen và Rhodes Island đã kết thúc. Lúc này landship Rhodes Island đã rời cảng Lungmen. Những gì chúng tôi làm từ đây không liên quan gì đến Lungmen. Được chứ, Amiya?”","“…Vâng.” Amiya bước lên. “Ngài Wei. Chúng tôi… sẽ không can thiệp vào tương lai của Lungmen hay chuyện riêng của ngài. Nhưng tất cả những chuyện này là âm mưu lợi dụng người Infected, và chúng tôi sẽ dốc toàn lực chống lại nó. Nếu ngài cho phép chúng tôi hành động, và hứa sẽ không chống lại chúng tôi bằng bất kỳ cách nào—thì trận chiến sắp tới là trận chiến của chúng tôi. Của Rhodes Island.”","“Ta sẽ không dựa vào người Infected. Ta không tin người Infected. Khác biệt duy nhất giữa các người và Reunion là các người chưa quay lưng với Lungmen… chưa thôi,” Wei Yenwu nói. “Reunion trước kia thế nào? Dù chúng ta không nhớ, vẫn có người nhớ. Chúng không giống bây giờ. Các người có thể khoác lên mưu đồ của mình những lời hoa mỹ, cũng như Reunion có thể hô hào rằng chúng sẽ giải thoát người Infected khỏi số phận. Rốt cuộc chúng vẫn thành bia đỡ đạn cho Ursus. Các người sẽ là Reunion tiếp theo sao? Hơn nữa, ta nghi các người không đủ sức đối phó với người kế thừa của Kashchey. Suốt bao năm qua, chỉ Lungmen là chống lại hắn thành công.”","“Ngài Wei, ngài định đích thân dẫn quân tấn công lõi đô thị Chernobog, đúng không?” Kal’tsit hỏi. “Ngài nghĩ chỉ mình ngài xử lý được tình hình này. Và lần này, ngài định hy sinh bản thân để vô hiệu hóa lời tuyên chiến với Ursus. Như cô Fumizuki nói, ngài cảm thấy mình đã phản bội nguyên tắc của mình, và muốn kết thúc tất cả bằng cái chết.”","“Ta đã phạm quá nhiều sai lầm. Cái chết của ta không trả hết được. Ta còn chẳng biết mình phải trả cho ai.”","“Dù vậy, ngài chắc chắn rằng sau khi ngài chết, không ai còn mang ác ý với ngài sao?”","“Lungmen có vị trí chiến lược với Yan. Nhờ sự bảo hộ của ta, nó sẽ tiếp tục thịnh vượng.”","“Tôi đang nói về phu nhân Fumizuki.”","<i>(Bác sĩ Kal’tsit… tế nhị một chút đi mà!)</i> Amiya nghĩ thầm.","“Bác sĩ Kal’tsit?! Cô nói gì vậy?!” Fumizuki kêu lên.","“Tôi nói thật lòng. Tôi e vợ ngài sẽ phải chịu khổ vì hành động của ngài. Dù ngài đã chết, bà ấy vẫn là quả phụ của ngài. Bà ấy vẫn biết mọi thứ ngài biết. Tôi có cảm giác kẻ đang ép ngài sẽ không rộng lượng đến thế. Và có lẽ không chỉ dừng lại ở cô Fumizuki.”","“Nói đi, bác sĩ Kal’tsit,” Wei Yenwu nói.","“Vì thành phố ngài yêu… Vì những người ngài yêu… Tôi cầu xin ngài, ngài Wei. Hãy để việc này cho người trong nghề. Chúng tôi có thể bất lực trước một đội quân chính quy, nhưng chúng tôi hiểu người Infected. Chúng tôi biết họ muốn gì, và không muốn gì. Chỉ người Infected mới đối mặt được với người Infected.”","Một khoảng lặng dài.","“Vậy cô muốn gì? Người lãnh đạo Rhodes Island, bác sĩ Kal’tsit? Các người không phải tổ chức từ thiện. Tấn công lõi đô thị chẳng khác gì ném trứng vào đá.”","“Hơn cả sự đồng ý với kế hoạch tác chiến, ngài Wei, chúng tôi cần lời đảm bảo của ngài,” Amiya nói. “Vì có thể ngài sẽ đổi ý về sau… Chúng tôi cần ngài hứa, ngay bây giờ. Vì em tin rằng Lungmen, gia đình ngài, và cô Ch’en, đáng giá lời hứa ấy. Chúng tôi không cần tiền của chị, chị Fumizuki. Lòng tốt và thái độ của chị với người Infected đã đủ để chúng tôi thực hiện chiến dịch này miễn phí.”","Fumizuki khẽ giơ ngón cái về phía cô bé. Amiya chớp mắt, không hiểu.","“Ta đồng ý,” Wei Yenwu nói. “Cho đến khi xung đột Lungmen – Chernobog kết thúc, Lungmen sẽ không can thiệp vào việc của Rhodes Island dưới bất kỳ hình thức nào. Và ta thấy bác sĩ Kal’tsit vẫn còn điều muốn nói. Cứ nói đi. Ta còn chịu được, lúc này. Vì ta cần Rhodes Island cứu một người Infected rất cụ thể.”","“…Vậy tôi có một đề nghị nữa.”","“Ra giá đi.”","“Hai mươi năm trước, Edward Artorius, cha của Talulah Artorius, đã chết tại Lungmen,” Kal’tsit nói. “Tôi muốn ngài Wei cho chúng tôi mượn di hài của ông ấy.”"],"bg":"bg_lungmenbridge","cast":[["Hoshiguma","op:char_136_hsguma"],["Ch'en","op:char_010_chen"],["Kal'tsit","op:char_003_kalts"],["Wei Yenwu","npc:char_2005_weiyw_1"],["Fumizuki",null],["Amiya","op:char_002_amiya"],["Rosmontis","npc:avg_npc_042"],["Rat King","npc:avg_npc_034"]]},{"c":"7-4","t":"Kề vai sát cánh","p":["<i>Đài chỉ huy Rhodes Island. 6:00 sáng.</i>","@cg:avg_7_7","“Gửi các operator xuất sắc của chúng ta, em có một thông tin quan trọng cần báo với mọi người ở Rhodes Island. Em là Amiya.”","Giọng cô bé vang khắp các hành lang landship.","“Từ đêm qua, Rhodes Island đã chính thức rời Lungmen. Do diễn biến gần đây, thỏa thuận thương mại giữa chúng ta và Lungmen đã bị hủy. Thật không may… một số operator của chúng ta sẽ sớm tiến sâu vào lõi đô thị Chernobog. Một trận chiến cực kỳ khó khăn đang chờ ở đó.”","“Nhiều người có thể nghĩ chiến tranh là chuyện xa vời với chúng ta. Rằng chiến tranh là xung đột giữa hai quốc gia, chẳng liên quan gì đến một công ty dược. Nhưng chiến tranh… em nghĩ chiến tranh chưa bao giờ rời xa chúng ta. Chúng ta luôn ở trong một cuộc chiến. Cuộc chiến dai dẳng chống lại sự bất công với người Infected, cuộc chiến khiến con người căm ghét nhau. Kẻ thù của người Infected sẽ không để họ được chữa trị. Và mỗi tội ác chúng gây ra với người Infected lại khiến căng thẳng thêm trầm trọng. Hãy tưởng tượng… nếu chúng ta bào chế được thuốc chữa căn bệnh này, nhưng không bao giờ có cơ hội đưa nó đến tay người Infected. Khi đó thì sao? Kẻ thù của chúng ta không chỉ là ‘Oripathy’.”","“Hai tuần trước, Reunion và Rhodes Island đã giao tranh dữ dội. Nhiều operator của chúng ta đã hy sinh ở Chernobog. Nhưng nếu mỗi sự hy sinh đều đòi chúng ta báo thù, chúng ta sẽ bị khóa trong vòng luẩn quẩn báo thù bất tận. Cuộc đấu tranh của chúng ta với Reunion không thể dựa trên hận thù. Nhưng Reunion vẫn chìm trong cơn điên của chúng. Chúng đã chiếm lõi đô thị Chernobog và đang lái nó lao vào Lungmen. Lạ hơn nữa, Ursus vẫn chưa từ bỏ quyền kiểm soát lãnh thổ với lõi đô thị đó, dù Ursus chưa từng hành động suốt cả sự kiện này. Đế quốc Ursus làm ngơ trước những tội ác ở Chernobog. Họ đã bỏ rơi chính công dân của mình.”","“Điều này khiến em kết luận rằng Ursus đã âm mưu tạo ra những sự kiện này. Va chạm với lõi đô thị sẽ châm ngòi một cuộc chiến giữa Ursus và Yan. Và bất kể ai đứng sau Reunion, bất kể kẻ chủ mưu thật sự là ai, chỉ còn một sự thật duy nhất bày ra trước mắt chúng ta: ‘Người Infected đã gây ra cuộc chiến này.’ Bất kể kết cục ra sao, người Infected sẽ luôn là vật tế thần. Họ sẽ phải đối mặt với sự áp bức tàn bạo hơn, cuộc sống khốn khổ hơn, và một mối hận thù rực lửa vĩnh viễn. Nếu chuyện đó xảy ra, mọi thứ Rhodes Island đã làm sẽ thành vô nghĩa.”","“Nhưng dù vậy, chúng ta sẽ không bao giờ bỏ cuộc. Chúng ta sẽ dùng lý trí chống lại kẻ cuồng tín, dùng mưu lược chống lại hận thù. Nên chúng ta sẽ ngăn Reunion. Chúng ta sẽ ngăn lõi đô thị Chernobog va vào Lungmen. Mong những ai ở lại landship sẽ chăm lo cho Rhodes Island. Dù chúng ta có trở về hay không, Rhodes Island vẫn sẽ tiếp tục chiến đấu.”","Cô bé tắt micro, thở ra một hơi dài.","“Phù…”","“Bài phát biểu hay lắm,” Doctor nói.","“A, ừm, cảm ơn Doctor! …Hả? Trên mặt em có gì sao? Em không để dính vụn bánh đấy chứ?”","“Có phải hơi u ám quá không?”","“…Vâng, các operator khác cũng nghĩ vậy. Họ bảo những lúc thế này nên khích lệ tinh thần. Nhưng em nghĩ chúng ta không phải đội như thế. Với chúng ta, không phải chuyện tinh thần tốt hay xấu. Chúng ta cần hiểu mình đang làm gì. Càng khó khăn, càng phải nói sự thật cho mọi người. Còn gì nguy hiểm hơn việc bịt mắt bước đi trên thế giới này…?”","“Tôi nghe nói cô Ch’en đã rời Lungmen.”","“…Đúng vậy. Em nghĩ cô Ch’en có lẽ sẽ một mình lẻn vào lõi đô thị. Lungmen, người Infected, dòng máu của cô ấy… Cô Ch’en là người phức tạp, mang trong mình rất nhiều mâu thuẫn. Nhưng dù vậy, cô ấy không bỏ cuộc, không bỏ chạy. Cô ấy không sợ bị phản bội, bị lưu đày hay cái chết.” Amiya nhìn lên. “Doctor, cô Ch’en là người Infected.”","“Tôi đoán được từ lâu rồi.”","“Vâng. Khi đến lõi đô thị, chúng ta cũng sẽ làm hết sức để cứu cô ấy. Không chỉ vì cô ấy là bạn chúng ta, cũng không hoàn toàn vì có người thuê chúng ta làm vậy. Cô Ch’en sẽ không phải một mình đối mặt với Reunion. Chúng ta sẽ đứng cùng cô ấy.” Amiya mỉm cười. “Em từng nghi ngờ cô Ch’en. Em tưởng cô ấy là kiểu người không thể thay đổi. Nhưng khi cô ấy đưa tay ra giúp người Infected, em đã thấy. Em đã thấy màu sắc trái tim cô ấy.”","“Còn một người nữa đã nhờ tôi ngăn Reunion,” Doctor nói.","“…Doctor, ngài đang nói về…” Amiya cúi đầu. “…Chị FrostNova… Vâng. Và… Misha. Nếu có điều gì chúng ta làm được để ngăn bi kịch của Misha lặp lại, để an ủi FrostNova và người của chị ấy, để giúp thêm nhiều người, để ngăn những nỗi đau mới ra đời trên mảnh đất này, chúng ta sẽ làm.”","“Ta đã gửi thông tin cho cả hai người rồi,” Kal’tsit bước vào. “Đây sẽ là lần đầu tiên ba chúng ta cùng chỉ huy.”","“Bà định làm việc với tôi sao?”","“Ngài có thể ở lại đây. Tùy ngài. Ta không ép được.”","“…Bác sĩ Kal’tsit,” Amiya nói. “Em mong bác sĩ gác lại mọi định kiến về Doctor. Và Doctor, em mong ngài gác lại mọi thành kiến với bác sĩ Kal’tsit, từ những điều bác sĩ từng nói. Ít nhất là trong lúc này. Doctor bị mất trí nhớ. Rhodes Island không có cách điều trị đáng tin cậy nào để khôi phục trí nhớ chỉ trong hai tuần. Nên mọi thứ Doctor bây giờ đều là sản phẩm của hiểu biết mới. Bác sĩ Kal’tsit, em mong bác sĩ nhìn Doctor này bằng con mắt mới. Còn Doctor, em không muốn ngài nghi ngờ ý định của bác sĩ Kal’tsit chỉ vì những gì bác sĩ đã nói. Bác sĩ là người… ngài có thể dựa vào nhất. Dù ngài có tin bác sĩ hay không. Xin cả hai người hãy hứa với em.”","“Tôi còn làm gì khác được đâu,” Doctor nói.","“Doctor,” Kal’tsit nói. “Chuyện cũ không thể cho qua. Đạo đức sẽ không biến chúng ta thành người tốt hơn. Ta không từ chối đề nghị của em, Amiya. Chỉ là, tha thứ như một hình thức tử tế, như từ bỏ quyền được giận dữ, sẽ chỉ khiến chúng ta yếu đi vô cùng. Ta sẽ không từ bỏ quyền đó. Nhưng lúc này, ta sẽ cất định kiến đi. Giải quyết lõi đô thị trước đã.”","“Amiya, tôi đang đứng cạnh em,” Doctor nói.","“Vâng… được ạ.” Amiya hơi ngập ngừng. “Em tin ngài sẽ ở bên em khi cần, Doctor. Nhưng trước kia, điều em muốn là ngài dẫn dắt em, lo liệu mọi thứ em không làm được trong những lúc khó khăn… Em từng nghĩ có Doctor bên cạnh, em có thể dũng cảm.” Cô bé ngẩng lên. “Giờ thì, Doctor, chúng ta kề vai sát cánh. Từ khi ngài trở lại, em đã đợi dịp để nói với ngài… Em đã lớn rồi. Em không cần ngài, hay bác sĩ Kal’tsit, hay… ừm… em không cần ai bảo vệ em nữa. Em sẽ chứng minh ngài đã đúng khi tin em. Em hứa.”","Một nhịp ngừng.","“Này! Kề vai chỉ là cách nói thôi. Đừng chê em lùn! Em vẫn đang lớn mà…! Hừ! Rồi em sẽ cao bằng ngài cho xem, Doctor!” Giọng cô bé dịu xuống. “…Em chỉ vui thôi, Doctor. Vâng… chỉ là… rất vui.”","Không ai nói gì.","“Tôi phát hiện một sự im lặng lạnh lẽo,” PRTS nói. “Bạn có muốn tăng nhiệt độ phòng điều khiển lên một chút không?”","Kal’tsit nhìn Doctor. “Ta đã không nghĩ chuyện này lại dễ đến thế. Thành thật mà nói, ta còn chờ ngài cài vài cái bẫy giữa những lời nói của mình. …Nhưng thì đã sao? Rất mong được hợp tác với ngài, Doctor.”","“Kế hoạch là gì?”","“Rhodes Island có cách làm riêng,” Kal’tsit nói. “Bốn tiếng nữa, chúng ta sẽ tạo ra một trận bão cát nhỏ trên đường đi của lõi đô thị Chernobog.”","","<i>10:00 sáng. Hoang mạc.</i>","“Số một!” Nearl hô.","“Máy nén số một đã có điện!”","“Số hai!”","“Kho đạn số hai sẵn sàng,” Firewatch nói.","“Số ba.”","“Bơm gió số ba, ngụy trang… ngụy trang xong!”","“Tháp chỉ huy của lõi đô thị có tầm nhìn rất rộng. Không ngụy trang thì không được,” Firewatch nói. “Họ thậm chí chẳng buồn che giấu việc lõi đô thị về cơ bản được thiết kế như một chiến hạm. Đế quốc sống nhờ bạo lực và chinh phạt. Ursus đã gây bao tội ác với quê hương tôi? Chúng sẽ không bao giờ rửa sạch máu trên tay. Chúng đốt ruộng, lấp giếng bằng tro. Chúng san bằng cả làng mạc, chỉ để lại những xác cháy đen… Đó là những ‘thường dân Ursus’ tôi biết. Nếu họ không ủng hộ chiến tranh, những chuyện đó đã không xảy ra.”","“Tôi tin đó không phải ý chí chung của người dân Ursus, mà là biểu hiện của những tư tưởng xấu xa,” Nearl nói. “Chúng ta không chiến đấu với người dân Ursus, mà với chính cái ác. Firewatch, đây có thể không phải đất Kazimierz. Nhưng chúng ta sẽ không để những tội ác ấy lặp lại. Chúng ta không đến đây để làm hại người. Chúng ta đến để ngăn người khác bị hại.”","“…Các hiệp sĩ chưa bao giờ giúp đội du kích chúng tôi,” Firewatch nói. “Lãnh đạo của chúng tôi chờ nhiều năm, nhưng cuối cùng chẳng có ai đến. Chúng tôi chiến đấu đến cùng, đơn độc, cho đến khi bị Ursus nuốt chửng. Tôi không trách các hiệp sĩ. Nhất là cô, Nearl. Nhưng tôi cứ nghĩ mãi về quãng thời gian chiến đấu với Ursus. Tôi không tin chúng, và tôi cũng không tin Kazimierz.”","“Đó là sai lầm nghiêm trọng của các hiệp sĩ Kazimierz. Một sai lầm họ không thể sửa chữa,” Nearl nói. “Nhưng ít nhất hôm nay, chúng ta có thể chiến đấu bên nhau, Firewatch. Hồi đó tôi không có cơ hội giúp cô. Nhưng lần này chúng ta chiến đấu, không phải vì quê nhà, mà để chấm dứt tội ác của Ursus. Tôi đã sẵn sàng. Chiến đấu vì điều mình tin, và chết vì cô.”","“Chết vì người khác…” Firewatch lặp lại. “Không phải hiệp sĩ nào cũng như cô.”","“Nhưng tôi tin hiệp sĩ là phải như thế. Chết vì người khác là có ý nghĩa. Cô Firewatch, hãy để trận này là lời xin lỗi của tôi.”","“…Operator Nearl. Cô cần tôi làm gì?”","“Canh giữ khu vực, cho đến khi các thiết bị hoạt động hoàn toàn.”","","<i>Bốn giờ trước.</i>","“Đây là ngụy trang của chúng ta à?” Doctor hỏi.","“Sau bao nhiêu trận đánh lớn, xâm nhập về cơ bản là môn bắt buộc với operator của chúng ta,” Kal’tsit nói. “Bão cát chỉ để xóa dấu vết. Xâm nhập thành công là tổng hòa của rất nhiều mảnh ghép. Thông tin từ Phòng khám Azazel đã xác thực bản thiết kế Chernobog mà ta có. Chúng ta có hình dung khá chắc về các tầng dưới của lõi đô thị. Đến lúc đó, ta sẽ vào qua hệ thống thoát nước ở móng. Nhưng chúng ta cần mồi nhử. Không có mồi thì không câu được cá.”","“Thợ săn cũng vậy.”","“Hừ… Ừ. Ngài nói đúng. Nhưng cho đủ thời gian, ngay cả thợ săn tồi nhất cũng phân biệt được con mồi và mồi nhử. Chúng ta phải ẩn mình đủ lâu để ngăn điều đó.”","@bg:bg_laccolith","<i>10:00 sáng. Trên không.</i>","“Chuyến này không cần hạ cánh đúng không, Huấn luyện viên?” viên phi công hỏi.","“Không cần,” Dobermann nói. “Cứ làm như sắp hạ cánh, nhưng liên tục bay vòng quanh thành phố. Giữ được nửa tiếng không?”","“Không vấn đề! Cô yên tâm, cô đang ngồi trên ‘Good Boy’, nó còn ồn hơn ‘Bad Guy’ nhiều! Cả nửa tiếng mọi con mắt sẽ dồn vào chúng ta!”","“Cẩn thận đấy. Đừng để bị bắn rơi.”","“Cô cứ ngồi thư giãn. Tôi chở Blaze với Ascalon cả trăm lần mà chưa bị bắn rơi lần nào khi bay thấp.”","“…Bị bắn rơi thì chỉ cần một lần thôi…”","Dưới mặt đất, đám Reunion ngoài rìa lõi đô thị chỉ trỏ lên trời. “Cái gì kia? Chúng bay?! Kẻ thù có vũ khí mới! Bắn hạ nó đi! Không được để nó hạ cánh!”","“Thứ này có tính năng an toàn gì không?” Dobermann hỏi.","“Cô sợ độ cao à, Huấn luyện viên?”","“…Một chút.”","“Đừng lo! Nếu có sự cố, chúng ta sẽ không kịp phản ứng đâu. Cú rơi sẽ nghiền nát chúng ta. Không ai nhận dạng được xác luôn. Công bằng tuyệt đối!”","“Thế thì làm sao mà không lo được?!” Dobermann bấm liên lạc. “Amiya, đã đánh lạc hướng được địch. Chúng tin rằng chúng ta sắp hạ cánh. Bắt đầu chiến dịch!”","“Các operator chiến đấu, chú ý! Một nhóm nhỏ địch đang tiến đến vị trí của ta, có lẽ là đội trinh sát từ lõi đô thị!” Nearl hô. “Thiết bị đã hoạt động. Chúng ta sẽ không để chúng phá hỏng kế hoạch. Cô Firewatch, yểm trợ tôi!”","@bg:bg_aircraft","“Hạ được đội trinh sát đó rồi chúng ta cũng chẳng còn nhiều thời gian,” Doctor nói.","“Đúng. Lịch trình rất gấp,” Kal’tsit nói. “Lõi đô thị đang di chuyển. Năm đội của chúng ta sẽ dùng xe, nương theo bão cát tiếp cận thành phố, rồi dùng thiết bị chuyên dụng leo lên phần khung bên dưới.”","“Chỉ có năm đội?”","“Chúng ta không vội gây sự chú ý của giới chóp bu Ursus ở đây. Cũng không muốn họ phái chiến hạm đến nghiền nát Rhodes Island giữa hoang mạc. Dù họ có làm thế, ngài cũng sẽ không thấy một dòng tin nào trên báo. Đám ngân hàng và bảo hiểm sẽ lặng lẽ gạch tên ngài và nhét hết tiền vào túi. Không ai muốn chọc giận Ursus. Sự trung lập cho chúng ta chút tự do di chuyển giữa các thế lực, nghĩa là chúng ta không thể được thế lực nào chống lưng. Chúng ta sống sót nhờ hành động trong bóng tối. Giống như khi chúng ta cử đội đi cứu ngài. Năm đội. Để lại dấu vết, xóa dấu vết; mục tiêu hoàn thành, mục tiêu thất bại. Dù thế nào, Rhodes Island chỉ bao giờ triển khai năm đội.”","“Vậy sao họ cần chúng ta?”","“Vì đây là chuyện của người Infected.” Kal’tsit ngừng lại. “Nhưng như vậy vẫn chưa đủ. Chúng ta cần thứ gì đó khác để nghiêng cán cân.”","“Hai người u ám thật đấy,” Amiya xen vào. “Em biết chuyện nghiêm trọng, nhưng đâu cần phải… cười như thế chứ?”","“Amiya… ta có cười sao?”","“Em biết là có. Môi bác sĩ có thể không động đậy, nhưng em cảm nhận được.”","“Không, ta phải nói rõ điều này: ta không có ý định xây dựng lại bất kỳ mối quan hệ nào với người này.”","“Ha. Tôi cũng vậy.”","“Haizz…” Amiya thở dài.","“Ta, Amiya và ba elite operator sẽ dẫn năm đội: ba đội chiến đấu, một đội trinh sát, một đội tác chiến đặc biệt,” Kal’tsit nói. “Ngài có lẽ muốn gặp đội trưởng của một trong số đó.”","@bg:bg_laccolith","“Rosmontis! Đợi đã!”","Blaze khập khiễng chạy tới, băng trắng quấn quanh người.","“A… Blaze. Chị bị thương nặng lắm. Sao chị lại ở đây? Chị nên quay về đi.”","“Lần này em xuất kích à? Chị sẽ kiếm người thay em. Misery thì sao? Cậu ta giỏi tác chiến tấn công hơn em. Vẫy tay một cái là xong. Để cậu ta đi đi.”","“Chị không muốn em đi?”","“Ừ. Em không nên đi. Lần này không giống những nhiệm vụ trước của em!”","“Vì em có thể chết?”","“Coi chừng cái miệng! Em không thể… cứ thế nói thẳng ra như vậy được! Em còn quá nhỏ cho nhiệm vụ nguy hiểm thế này. Không đúng chút nào!”","“Nhưng Amiya cũng đi mà.”","“Đó là vì con bé…! Con bé là…” Blaze nghẹn lời. “Amiya…”","“Chị ấy cũng như em. Chị ấy là người Infected. Chị ấy là operator,” Rosmontis nói. “Em đã xem nhật ký. Ace và Scout đều ở Chernobog. Họ không trở về. Nghĩa là họ đã mất rồi. Em muốn thấy. Em muốn biết chuyện gì đã xảy ra. Em muốn thấy ai đang điều khiển Reunion. Em muốn biết chuyện gì đã xảy ra với Ace và Scout.”","“Rosmontis? Em không cần phải ghi lại… những chuyện như thế.” Blaze cắn môi. “Chết tiệt. Mình đang nói cái quái gì thế này…? Không, xin lỗi, chị không nên nói vậy. Cái miệng chết tiệt của chị! Chúng ta có những kỷ niệm vui, và cả những kỷ niệm đau. Em phải nhớ cả hai. Nhưng… chị không muốn thấy em đau đớn như vậy. Sao em phải ngoảnh lại nhìn họ? Em có thể buông những ký ức đó xuống. Đặt chúng ở đó, để chúng ở đó, và đừng ngoảnh lại.”","“Nếu em không nhìn… thì ghi lại chúng để làm gì?” Rosmontis nói. “Nếu em không nhìn… chúng sẽ bị lãng quên. Em sẽ không quên. Em nhất định sẽ không quên một cái chết nào.”","“Ha. Phải rồi. Em cũng như chị. Em là elite operator của Rhodes Island. Chị không thể đi thay em. Thật ra, chị…” Blaze ôm sườn, máu thấm qua lớp băng.","“Chị lại chảy máu rồi?”","“Không sao.”","“Em đưa chị về.”","“Ối.” Blaze bị nhấc bổng lên. “Rosmontis… Em và Amiya nhớ giữ mình nhé.”","“Vâng. Em sẽ nhớ.”","@bg:bg_bridge","“Các elite operator của Rhodes Island, vì lý do riêng, cống hiến tài năng và sức lực cho Rhodes Island,” Amiya nói. “Đội của họ hỗ trợ họ hết mình. Vì ở một mức độ nào đó, elite operator có thể trực tiếp quyết định cách chúng ta áp dụng một chiến thuật. Nhưng không phải ai trong số họ cũng… đúng như chúng ta tưởng tượng.”","“Nhìn phản ứng của ngài, có lẽ ngài đã gặp người chúng ta đang nói đến,” Kal’tsit nói. “Đó là kế hoạch cơ bản. Kế hoạch là kế hoạch, chiến dịch là chiến dịch. Một sai sót trong chiến dịch có thể đập vỡ cả kế hoạch.”","“Mong là ở đây không có chuyên gia báo điềm gở nào.”","","“Ối… không ổn rồi! Có vấn đề!” Một kỹ sư kêu lên. “Mật độ bụi vẫn quá thấp. Với góc sáng này thì không được. Chúng ta đang lộ hết! Nếu họ nhìn xuống từ đài chỉ huy, họ có thể phát hiện ra chúng ta trước khi mọi thứ vận hành xong!”","“…Để tôi lo,” Nearl nói. “Firewatch, để ý giúp tôi, bảo tôi cần chỉnh hướng nào.”","“Cô… định làm gì?”","“Chỉnh góc của ánh sáng.” Nearl bước lên đỉnh đụn cát. “Để giảm bớt khổ đau của thế gian… Tôi tin ngay cả mặt trời cũng sẽ cúi đầu trước tôi.”","Từ xa, Elysium nheo mắt. “Ai trên đụn cát kia? Nearl à? Không lên ngựa, cũng không rút lui? Cô ấy làm gì thế? Thiền à? Tạo dáng… cô ấy đang tạo dáng ở đây à? Không, khoan, ánh sáng gì kia? Cả người cô ấy đang phát sáng… Không ổn! Chói quá!” Một bàn tay bịt lên mắt anh ta. “Ừm, cảm ơn Đội trưởng… Cảm ơn đã che mắt cho tôi, nhưng sẽ tuyệt hơn nếu anh đừng bóp như muốn bóp nát hộp sọ tôi.” Anh ta hé nhìn. “Cô ấy đang kéo hết ánh sáng xung quanh về phía mình? Chà. Đội trưởng, ánh sáng đang tụ lại. Ngoài Hiệp sĩ Rạng rỡ ra, còn ai làm được chuyện này chứ? Nhìn bóng của các đụn cát mà xem. Anh còn đoán được bây giờ là mấy giờ không?”","Trên trời, chiếc trực thăng lắc lư. “Đưa chúng ta lên cao! Có mấy quả cầu màu mè gì đó sượt qua!” Dobermann quát.","“Đừng sợ, Huấn luyện viên. Caster của Reunion không đủ trình bắn hạ chúng ta đâu. Diễn đủ hay thì có khi Reunion đầu hàng luôn, đó chẳng phải là phô trương lực lượng sao?”","“Nhào lộn trên không không phải phô trương lực lượng!”","“Bám chắc nhé, Huấn luyện viên!”","“—Tôi cần túi nôn!”","“Thiết bị đã vận hành hoàn toàn!” Nearl hô. “Amiya, chúng ta sẵn sàng rồi!”","“Rõ!”","“Lái xe, giữ tốc độ đều! Kiểm tra bản đồ. Dùng bão cát che giấu đường tiếp cận cho đến khi vào tầm triển khai thiết bị leo! Xuất phát!” Kal’tsit ra lệnh.","“Cát sẽ xóa dấu vết của chúng ta. Nhớ đồ bảo hộ, đừng để cát lọt vào thiết bị nhạy cảm!” Amiya nói. “Nhưng… em thấy mặt trời. Sao ánh nắng lại xuyên qua được bão cát? Mặt dưới lõi đô thị rõ như ban ngày, như thể… Arts vậy. Đây đâu có trong kế hoạch. Đó là ánh sáng tự nhiên sao?”","“…Đừng bận tâm!” Nearl đáp. <i>(Mình làm hơi quá tay nên phải chĩa xuống đất, nhưng đừng nói với con bé phần đó…)</i>","“Rõ! Móc leo, chuẩn bị bắn! Đảm bảo cáp được cố định chắc vào mặt dưới thành phố!” Amiya nói. “Khi tất cả operator đã lên, xe sẽ rời đi ngay! Bình thường em không hay nói thế này, nhưng em khá chắc ánh sáng vừa rồi là điềm lành cho chúng ta!”","“…Chắc chắn rồi!”","“Khoan, lõi đô thị đang tăng tốc?” Nearl nhìn lên. “Máy của chúng ta chạy bằng sức gió, chỉ duy trì được bão cát trong phạm vi một cây số! Nếu họ vượt quá phạm vi đó, chắc chắn sẽ bị phát hiện!”","“Mọi người nhanh lên!”","“Hết giờ rồi! Phải giảm tốc!” người lái xe kêu. “Nếu ra khỏi bão cát, hệ thống quan sát quang học của Chernobog sẽ thấy chúng ta ngay! Còn bao nhiêu người nữa? Nhanh lên…”","“Không còn ai nữa,” Doctor nói, rồi đeo khẩu trang chống bụi. “Đưa tôi móc khóa. Tôi tự đi.”","@cg:avg_7_9","“Nguy hiểm lắm, Doctor! Ngài chưa từng được huấn luyện operator! Không thể để ngài lên một mình! Bác sĩ Kal’tsit không phân ai hỗ trợ ngài sao?”","“Có đấy.”","Kal’tsit xuất hiện từ trong bão cát.","“Ta.”","Bà ta vòng một tay ôm ngang eo Doctor, tay kia kéo cả hai lên dây cáp.","“Lần sau hãy tự nắm lấy số phận của mình, Doctor.”","Bão cát dữ dội, và “cánh tay” đang giữ chặt Doctor cứng đến lạ. Doctor không chắc nó có thật sự thuộc về Kal’tsit hay không.","“Tất cả các đội, vào vị trí!” Amiya hô. “Chiến dịch sắp tới không có chỗ cho sai sót!”","@bg:bg_laccolith","<i>10:30 sáng. Móng lõi đô thị.</i>","@cg:avg_7_8","“Đúng là có dấu hiệu đột nhập,” một operator nói. “Xác nhận một kẻ xâm nhập.”","“Không chắc vết máu kia là của Reunion hay ai khác. Nó chưa khô,” Amiya nói. “Rất có thể là của cô Ch’en! Chúng ta phải nhanh lên.” Rồi cô bé quay lại. “A, Doctor! May quá ngài đến nơi an toàn.”","“Em gọi thế là an toàn à…! Suýt nữa là em mất tôi rồi đấy.”","“…Ơ? Hả?! N-nguy hiểm đến thế ạ? Ngài có bị thương không?!”","“Tôi ổn. Đi thôi. Chỉ hơi chấn thương tâm lý chút thôi.”"],"bg":"bg_bridge","cast":[["Amiya","op:char_002_amiya"],["Kal'tsit","op:char_003_kalts"],["Nearl","op:char_148_nearl"],["Blaze","npc:char_017_homura_3"],["Rosmontis","npc:avg_npc_042"],["Firewatch","op:char_158_milu"],["Dobermann","npc:char_130_doberm_ex"],["Elysium","op:char_401_elysm"]]},{"c":"7-6","t":"Vùng đất bị lãng quên","p":["<i>Căn cứ ngầm Chernobog. 10:30 sáng.</i>","“Bà đợi tôi ở đây à?”","“Đúng vậy,” Kal’tsit nói. “Trước khi bắt đầu, ngài nên nghe chính xác những gì đang diễn ra trong lõi đô thị. Ngài đã đọc bản tóm tắt nhiệm vụ, nhưng loại thông tin đó không đủ với một bộ óc như ngài.”","“Cuối cùng bà cũng nhận ra mình cần tôi sao?”","“Nếu điều tồi tệ nhất xảy ra, ta không muốn ngài hy sinh mà vẫn chẳng biết gì. Mà nếu ngài hứng thú với phần nào đó của ta, cứ nói thẳng ra. Không cần nhìn chằm chằm như thế. Ngài có thể không nhớ, nhưng ta thì nhớ. Ta nhớ ngài từng có tài hâm nóng khẩu phần ăn bằng cách đổ thẳng nước sôi vào miệng lúc bốn giờ sáng.” Kal’tsit quay đi. “Bỏ qua chuyện phiếm. Chúng ta không có nhiều thời gian. Amiya báo với ta rằng ngài đã có một trận chiến khó khăn với FrostNova dưới đáy Lungmen. Trận chiến kết thúc bằng chiến thắng của ngài.”","“Không có ai thắng cả.”","“Ta hiểu. Theo dữ liệu từ PRTS, ngài đã đưa thi thể của kẻ thù về Rhodes Island.”","“Tôi không coi cô ấy là kẻ thù.”","“Doctor, ‘phân biệt bạn và thù’.” Kal’tsit ngừng lại. “…Không. Ngài có thể hiểu lầm, nhưng hãy nghe ta nói. Ta không trách ngài. Chỉ những người có mặt lúc đó mới có đủ thông tin để quyết định. Ngài đã cố hiểu động cơ của người Infected đó. Ngài sẵn sàng gánh hậu quả cho những gì FrostNova đã làm. Nếu ngài định dùng cách này để hiểu nỗi khổ của thế gian, ta không có lý do gì để trách ngài. Ta thậm chí sẵn sàng bảo lãnh cho ngài trước các operator. Hãy tự đưa ra quyết định, ta sẽ cố không can thiệp. ‘Phân biệt bạn và thù.’ Đó là lời của ngài, không phải của ta.”","Rồi bà ta thì thầm, khẽ đến mức gần như không nghe thấy: “Nếu ngài thật sự muốn cùng chung một hơi thở…”","“Bà đang… đứng về phía tôi sao?”","“Ta chưa bao giờ nói vậy.” Giọng Kal’tsit trở lại bình thường. “Nói chính xác, FrostNova và Đội Yeti là một đội du kích tinh nhuệ của người Infected. Hiện Reunion vẫn còn hai lực lượng tinh nhuệ có thể huy động. Những chiến binh du kích này là một. Lực lượng kia là lính đánh thuê Sarkaz, W, cùng đám lính của cô ta. W đã dùng thủ đoạn để nắm quyền chỉ huy lính đánh thuê Sarkaz làm việc cho Reunion. Lính đánh thuê Sarkaz không đáng tin. Họ không giống lính đánh thuê thông thường. Họ là phần quân lực dư thừa của Kazdel, tràn ra khắp đại địa. Cố điều khiển họ là điều ngu xuẩn.”","“Bà có vẻ hiểu người Sarkaz rất sâu.”","“Ta còn chưa đến phần quan trọng. Du kích Yeti hoàn toàn khác lính đánh thuê Sarkaz. Trước khi gia nhập Reunion, họ là một lực lượng du kích Infected độc lập, uy tín của họ trong một số nhóm người Infected còn lớn hơn cả Reunion. Và trước khi thành lập đội du kích, họ từng là một phần của quân đội Ursus hùng mạnh.”","“Đội du kích Lãnh nguyên Tây Bắc?”","“…Ta không biết ngài lấy thông tin đó ở đâu, Doctor, nhưng ta khá ấn tượng. Dù đó là thông tin khá cơ bản, ta mừng vì ngài biết tự thu thập tình báo.”","“Bà nhất định phải thêm câu cuối đó vào à…”","“Ta chỉ cho ngài những gì ngài xứng đáng.” Kal’tsit chỉ vào bản đồ. “Chúng ta đang ở móng của khu công nghiệp lõi đô thị Chernobog. Tiếp theo, ta sẽ dẫn ba đội qua các đường hầm ngầm, theo ống cống vào tầng công nghiệp và lên đến trái tim lõi đô thị. Lưu ý, địch tuần tra ở những khu vực này không phải đám côn đồ Reunion thông thường. Chúng ta sẽ gặp những ‘người lính’ được đội du kích huấn luyện theo chiến thuật của chính quân đội Ursus. Đội trinh sát phát hiện mạng lưới liên lạc trong lõi đô thị đã bị cắt bỏ. Hoặc Reunion có cách liên lạc đặc biệt, hoặc chúng không hề chuẩn bị chiến đấu. Dựa trên những gì ta thấy ở Chernobog một tháng trước, đừng mong là khả năng thứ hai. Nhưng nếu liên lạc bị cắt, thành viên cấp thấp của Reunion sẽ không nhận được lệnh trực tiếp. Phần lớn thời gian, chúng sẽ tự hành động.” Bà nhìn lên trần thép. “Một cơn bão khủng khiếp đang hình thành trong thành phố này. Hỗn loạn, dù vô tình hay cố ý, sẽ lan khắp nơi như khói đặc. Chúng đi trước ta một bước, và hạt giống của sự diệt vong đã được gieo rồi.”","“Kết luận của bà là gì?”","“Nội bộ Reunion đang có xung đột.”","“Sao bà chắc chắn vậy?”","“Ta đã thấy chuyện này lặp lại không biết bao nhiêu lần trên mảnh đất này.” Kal’tsit đưa cho Doctor một chiếc hộp. “Nhờ ngài báo cho thành viên Đội R-4, bảo họ mang những thiết bị này.”","“Khoan… Chẳng phải đây là đồ của Rosmontis sao?”","“Đúng. Có vẻ ngài biết về Rosmontis nhiều hơn những gì cuộc trò chuyện ở đơn vị xử lý sinh học cho thấy.” Kal’tsit nói. “Mỗi elite operator đều có sức mạnh đáng kể. Nhưng có những thứ họ không nên một mình gánh vác. Là chỉ huy chiến trường, giúp giảm áp lực cho họ là một phần công việc của ngài. Trong trận chiến sắp tới, ngài có thể sẽ phát hiện ra vài điều gây sốc. Rất ít người không bị sốc sau khi xem Rosmontis chiến đấu. Hãy chuẩn bị tinh thần.”","","“Doctor, ngài đến rồi! Chúng tôi chặn được một đội tuần tra của địch, đang xử lý dần,” một operator nói. “Doctor, vị trí của ngài hơi nguy hiểm đấy… Ngay đó… Sau lưng ngài… Đứng cạnh cô bé nguy hiểm lắm!”","“…Kẻ thù.”","Doctor quay lại. Rosmontis đứng đó, đôi mắt mở to, những khối kim loại khổng lồ lơ lửng sau lưng.","“Rosmontis?”","“Kẻ thù. Doctor, chúng là những kẻ đã giết gia đình em… Kẻ thù!”","“Rosmontis, chuyện gì thế…”","“Doctor, tránh ra. Tránh đường cho em. Em không giống Amiya. Arts của Amiya có thể vòng qua bạn bè để đánh vào kẻ thù… Nhưng em thì không. Em không làm được. Nên đừng đứng giữa em và trận chiến của em.”","“Áaaa!!” Một thành viên Reunion gào lên. “Con bé đó, con bé mang cái hộp… C-chuyện gì thế này… Mắt tôi sao vậy? Tôi không thấy gì cả! Mắt tôi! Mặt tôi! Đau quá! Đau quá!!! Có thứ gì đang nghiền nát đầu tôi!”","“Không,” Rosmontis nói khẽ. “Lâu lắm rồi em mới nghiền chết ai đó.”","“Những thanh kiếm đó… Những thanh kiếm đó!”","“Rosmontis?!”","“…Reunion. Em không muốn các người ở trong ký ức của em. Không một ai.”","","<i>Máu me. Rách nát. Xuyên thủng.</i>","<i>Chúng ta. Kẻ thù. Con người.</i>","<i>Gào khóc, la hét, rên rỉ.</i>","“Thế này không đúng,” Doctor nói. “Thế này không đúng!”","“Ngài có câu hỏi. Hỏi đi,” Kal’tsit nói, rồi quay sang một operator. “Để ta lo. Cậu đi chăm sóc những kẻ địch bị thương không còn chiến đấu được. Trong số chúng có người truyền tin. Nếu để chúng trốn thoát, cả chiến dịch sẽ gặp nguy.”","“…Rõ.”","“Con bé bao nhiêu tuổi?” Doctor hỏi.","“Mười bốn.”","“Vậy mà bà để con bé…?!”","“Mọi người, làm ơn… cho em qua!” Amiya chen vào. “Chuyện gì xảy ra ở đây vậy? Em vừa xử lý xong… Doctor?”","“Ai cử em ra chiến trường?” Doctor hỏi Rosmontis. “Ai cử em đến đây?! Thế này quá tàn nhẫn! Sao họ lại để em làm chuyện này? Kal’tsit!”","“Là em,” Rosmontis nói. “Em chọn chiến đấu. Em muốn chiến đấu. Có những cảm giác em chỉ trải qua được trên chiến trường. Bảo vệ bạn bè và gia đình là cách duy nhất để em thấy mình trọn vẹn. Rhodes Island cần em. Thế giới đang gọi tên em, để ngăn thêm những người như em ra đời.”","“Dù vậy, em không thể…”","“…Cái chết có quan tâm em là trẻ con không?” Rosmontis hỏi. “Chiến tranh hay bệnh tật có tha cho ai vì họ là trẻ con không? Khi Amiya hay em đứng trên chiến trường… ai nhìn chúng em mà nghĩ ‘trẻ con’? Chúng em là ‘quái vật’, đúng không, Doctor?”","“Không! Đó chỉ là cách em nhìn bản thân thôi.”","“Không đâu, Doctor. Em là gì không quan trọng. Em chỉ muốn tạo ra khác biệt, cùng gia đình em.” Cô bé ngẩng lên. “Ngài có biết Scout không? …Ngài có biết Ace không?”","“Có.”","“Đã mấy ngày rồi em không xem lại tư liệu về họ. Em quên nhiều lắm. Nhưng em chỉ quên thôi. Em không giống ngài, Doctor, người đã vứt bỏ tất cả.”","“Rosmontis,” Amiya nói khẽ.","“Không, em không có ý đó. Nhưng chị hiểu mà, Amiya.”","“…Chị hiểu. Nhưng đừng… nói như thế.”","“Ưm… Vâng.” Rosmontis nhìn xuống đôi tay mình. “Em đã đánh mất từng mảnh. Rất nhiều hình ảnh và lời nói. Những cảm xúc… những cảm xúc em không nói ra được, chỉ Amiya hiểu… Nhưng chúng chưa bao giờ thật sự rời bỏ em. Doctor… em thấy ngài phức tạp lắm. Còn phức tạp hơn những gì họ nói. Họ cũng bảo em phức tạp. Có người sợ em. Có người bảo em không nên như thế này. Nhưng họ không biết vì sao em như thế này. Họ không biết em đã trải qua những gì.”","“Sao tim em bỗng nhói đau? Sao em lại muốn khóc, ngay lúc này? Dù em chẳng nhớ gì… sao mắt em vẫn cay? Sao môi em khô khốc? Ai để lại vết bẩn trong hành lang, sao nó vẫn chưa được lau? Sao em thấy lo khi làm vỡ một chiếc bình, mà cũng thấy vui lạ lùng? Sao em thấy ghê sợ khi nhìn hoa, mà lại thấy kỳ diệu khi nhìn côn trùng? Chuyện gì đã xảy ra trong quãng thời gian em không còn nhớ? Sao những cảm xúc này cứ trào lên trong em? Mỗi operator em cảm nhận đều có điểm khác biệt riêng. Và khi em mất họ, những cảm xúc ấy cũng biến mất. Nhưng tại sao…? Tại sao chúng ta lại có cảm xúc? Sao nước mắt em vẫn chảy dù em không còn cảm thấy gì? Chẳng phải em đã quên hết rồi sao?”","“Rosmontis chưa bao giờ muốn em lấy đi cảm xúc của em ấy,” Amiya nói. “Những cơn xúc động đột ngột đó là của em ấy, dù chúng là gì. Chỉ thuộc về Rosmontis. Em không thể can thiệp. Chừng nào Rosmontis vẫn còn hy vọng ở đâu đó bên trong… em sẽ không làm vậy. Vì chọn làm gì là quyền của em ấy. Em ấy cũng có thể chọn quên. Quên thật sự.”","“Chuyện gì đã xảy ra với Rosmontis?”","“Doctor… Rhodes Island có quy trình sàng lọc operator rất nghiêm ngặt. Rất nhiều người xin vào vị trí chiến đấu, và chúng em từ chối phần lớn. Năng lực chiến đấu, khả năng chiến thuật, kỷ luật, thể lực… chỉ là bề nổi. Rosmontis ở đây vì em ấy tin vào mệnh lệnh và mục tiêu của chúng ta, và chúng ta tin vào năng lực và phán đoán của em ấy. Xin hãy tin em, Doctor. Không, hãy tin chúng em… Dần dần ngài sẽ thấy… màu sắc cảm xúc của em ấy.”","Rosmontis bước lại gần. “Doctor. Cảm ơn ngài đã chiến đấu cùng Blaze. Blaze cần thêm người chiến đấu bên chị ấy. Và em muốn thấy chị ấy cười. Em cũng muốn gặp ngài. Em muốn gặp người mà Ace và Scout luôn nhắc đến.”","","“Ngài đây rồi,” Kal’tsit nói. “Rosmontis dùng máy móc hạng nặng để tiêu diệt kẻ thù nhanh và hiệu quả, đồng thời thể hiện khả năng tự chủ và thích ứng đáng kinh ngạc. Em ấy là một trong những chuyên gia hủy diệt giỏi nhất của Rhodes Island. Cách em ấy đối xử với người khác, cách em ấy nói chuyện, có thể khiến ngài lo lắng. Cách em ấy chiến đấu, đặt cạnh vẻ ngoài của em ấy, quả thật rất tàn nhẫn. Nếu điều này giúp ngài ngủ ngon hơn, ta có thể hứa với ngài: Rosmontis gần như không bao giờ giết người. Dù chiến thuật của em ấy có vẻ chỉ nhắm đến điều đó, nhưng thật ra em ấy tập trung vào việc vô hiệu hóa khả năng chiến đấu của địch. Trận vừa rồi, tất cả kẻ địch đều bị tước vũ khí, không một ai chết dưới đòn tấn công của Rosmontis.”","“Tôi không chấp nhận được chuyện này.”","“Có lẽ ngài cũng không chấp nhận được sự thật. Originium Arts đáng sợ và khả năng cảm nhận phi thường không phải lý do duy nhất khiến Rosmontis trở thành elite operator. Mà ngược lại, Rosmontis thể hiện những phẩm chất đó vì em ấy đã trở thành elite operator. Chúng ta không phán xét có nên đưa em ấy ra chiến trường hay không, mà là hậu quả sẽ thảm khốc thế nào nếu chúng ta không để em ấy trở thành một chiến binh như vậy.”","“Hậu quả kiểu gì?”","“Tệ nhất, Arts của em ấy rò rỉ khỏi cơ thể và đẩy em ấy đi giết người, dù có ý thức hay không,” Kal’tsit nói. “‘Khi tước đi tri giác của một con người, còn lại gì? Thứ gì được tạo ra? Khi thứ được tạo ra ấy tước đi mạng sống của chúng ta, ai có lỗi? Kẻ tạo ra vũ khí, kẻ dùng vũ khí, hay kẻ bị chúng ta đối xử như vũ khí?’ Về chuyện tuổi tác… Amiya khoác lên mình vẻ trưởng thành có thể khiến ngài lầm tưởng. Một sinh vật nhỏ bé được biết đến như vũ khí chết người sẽ không được coi là đứa trẻ bình thường chỉ vì trông còn nhỏ. —Chưa kể tất cả những gì chúng đã trải qua.”","“Còn Amiya? Con bé cũng là vũ khí sao?”","“Ngài có thể tự hỏi em ấy. Đây là điều ngài nên nghe từ chính em ấy.”","","“Kal’tsit! Đứng lại đó!”","Warfarin chặn đường, đôi mắt đỏ nhíu lại.","“Warfarin, ta đang đi. Có gì thì nói nhanh.”","“Cô biết lời tiên tri, đúng không? Phải rồi, chẳng có gì cô không biết. Chẳng phải vì thế cô mới để Amiya đi sao? Amiya còn nhỏ như thế, làm sao chỉ huy—”","“Warfarin, chúng ta rời Kazdel bao lâu rồi?”","“…Hai tháng?”","“Đừng đùa nữa.”","“Tôi hiểu ý cô. Con bé đã lớn rồi.”","“Phải, Warfarin. Thời gian trôi nhanh lắm. Tốc độ lớn lên của Cautus và Vampire khác nhau hoàn toàn. Đã ba năm kể từ khi chúng ta rời Kazdel. Với cô có thể ngắn, nhưng Amiya đã trưởng thành rất nhiều.”","“Trả lời câu hỏi đầu tiên của tôi đi. Lời tiên tri.”","“…‘Wendigo cuối cùng sẽ chết dưới tay Chúa tể của Quỷ’?” Kal’tsit nói. “Nguyên văn lời tiên tri là ‘Con trai của Hor-Tekrz, kẻ phản bội Sarkaz và kẻ cuối cùng tai tiếng của dòng máu, sẽ bị Chúa tể Sarkaz xử tử.’ Tiên tri gì chứ. Dù dòng máu của họ có còn tiếp nối hay không, vẫn còn nhiều Wendigo sống ở Columbia và Ursus. Nếu vài chục người có thể gọi là ‘nhiều’. Xét bối cảnh thời đó, cô nên coi nó là một lời đe dọa. Rất nhiều người không muốn thấy người Wendigo rời Kazdel. Cô già rồi sao? Từ khi nào cô tin vào ‘tiên tri’ và bùa phép Sarkaz?”","“—Già? T-tôi á?!”","“Ta nhiễm Oripathy. Cái chết luôn ở bên ta, chờ đúng lúc ra tay. Warfarin, mạng sống của ta chắc chắn ngắn hơn cô nghĩ nhiều.”","“Này! Có cần u ám thế không? Tôi không phải cô bé Closure của cô. Tôi không để cô lảng tránh mãi đâu.” Warfarin hạ giọng. “Nghe này, Kal’tsit, người khác có thể không nói với cô, nhưng tôi sẽ nói. Ông ấy là một trong số rất ít người còn lại của chúng ta. Tôi không phải người mềm lòng hay hay xen vào chuyện người khác, nhưng… chúng ta là Sarkaz. Tôi là Vampire, ông già là Wendigo, nhưng chúng ta như nhau. Thế giới này khắc nghiệt với người Sarkaz. Tôi mong ông ấy có thể về Kazdel, nếu được. Hoặc đi cùng chúng ta.”","“Ta không phải, Warfarin. Ta không phải Sarkaz.”","“Vậy là cô từ chối?”","“Không… Ta sẽ làm những gì có thể.” Kal’tsit ngừng lại. “…Ngay cả ta cũng nhớ ông ấy, Warfarin. Nhưng đừng hy vọng chuyện này sẽ dễ dàng. Có lẽ cô chưa nghe, nhưng đề nghị của cô đến quá muộn. Có những chuyện đã xảy ra rồi, khá đáng tiếc. Cách đây ít lâu, một phòng khám Infected ở Chernobog tên ‘Azazel’ đã trao đổi thông tin với chúng ta. Ta biết thêm về người Wendigo phục vụ Reunion. Và cô hẳn biết rõ, bất kỳ ai chống lại lưỡi dao tàn bạo nhất của Ursus sẽ sớm biết nó có vị muối hay vị gỉ sắt. Không ai được cố tình đẩy operator của chúng ta vào nguy hiểm.”","“Có những bệnh nhân chỉ còn đếm ngày, nhưng con số đó phụ thuộc vào bác sĩ điều trị. Tất cả tùy vào chúng ta.”","“…Tất cả tùy vào chúng ta.” Kal’tsit bước đi, rồi dừng lại. “Và ta đã nói với cô rồi… có lẽ cô quên. Cô không được nói ta đáng sợ, Warfarin. Chúng ta đã bàn chuyện này rồi. Không được, dưới bất kỳ hoàn cảnh nào, kể cả ở Rhodes Island, nhắc đến ‘Chúa tể của Quỷ’. Không bao giờ.”","@bg:bg_corridor","“Khoan đã. Tất cả, nghỉ!” Amiya giơ tay. “Rosmontis… em cảm nhận đúng chứ?”","“Ừm. Vâng. Em cũng cảm thấy.”","“Doctor, có chuyện ngoài dự tính.”","“Chuyện gì?”","“Em không chắc lắm, nhưng…” Amiya nhìn lên trần thép đang rung khe khẽ. “Lõi đô thị có thể đang… giảm tốc?”"],"bg":"bg_cherunder","cast":[["Kal'tsit","op:char_003_kalts"],["Rosmontis","npc:avg_npc_042"],["Amiya","op:char_002_amiya"],["Warfarin",null]]},{"c":"7-7","t":"Hai mươi sáu giờ","p":["<i>Không rõ thời gian. Văn phòng của Wei Yenwu.</i>","“Anh không kéo rèm sao?” Fumizuki hỏi.","“Kính đã vỡ rồi. Kéo rèm chỉ là tự lừa mình thôi.”","“Kính không quan trọng. Ch’en có an toàn không… mới quan trọng.”","“Con bé giỏi. Không giống cha nó, cũng không giống mẹ nó.”","“Phải, chẳng giống chút nào.”","Wei Yenwu nhìn xuống. “Dưới chân ta lại là một dòng sông ánh sáng. Lungmen đã trở lại bình thường, nhưng họ vẫn chưa biết chuyện gì sẽ xảy ra. Một mình, Ch’en Hui-chieh không thể ngăn thảm họa này.”","“Rhodes Island ở cùng con bé. Họ sẽ tìm thấy nó.” Fumizuki thở dài. “Witte không còn kìm được phe bảo thủ nữa. Bao năm nay ông ấy cố đè nén các đại quý tộc, nhưng chỉ làm họ yếu đi chứ chưa đánh bại hoàn toàn.”","“Nhưng ta sợ rằng… nếu Witte nói dối thì sao? Nếu toàn bộ chuyện này do Witte và Hoàng đế bày ra? Nếu chính vị hoàng đế trẻ lên kế hoạch tất cả? Kẻ thù của chúng ta luôn ẩn trong bóng tối. Còn chúng ta luôn phải đứng dưới ánh đèn chói lóa nhất.”","“Anh đã ở sâu trong bóng tối hơn phần lớn người khác rồi.”","“…Chưa đủ. Như hồi đó. Nếu là Kashchey… nếu hắn ở trong tình cảnh này, hắn sẽ đào sâu hơn nữa.”","“Nhưng anh không phải Kashchey. Kashchey không thể biến Lungmen thành như hôm nay.” Fumizuki cúi đầu. “Chỉ là… nếu Tal… nếu Tal thật sự được Kashchey dạy dỗ… Vị bác sĩ Rhodes Island đó, anh nghĩ bà ta có nói dối không?”","“Ta không chắc. Rhodes Island giỏi che giấu bản thân. Họ giả vờ yếu đuối trước chúng ta và không để lộ bí mật nào. Nhưng ta thà tin rằng Kashchey đã nhào nặn nên Talulah hiện tại. Chúng ta không thể gánh nổi hậu quả của việc đánh giá thấp kẻ thù. Vì vậy, ta không thể để Ch’en Hui-chieh làm việc này một mình. Kashchey… nắm hết quân bài trong tay. Dù hắn đã chết, tầm nhìn của hắn vẫn có thể thành hiện thực qua người kế thừa.” Ông ngừng lại. “Đội trinh sát báo một số người Infected rời Lungmen đang di chuyển về phía lõi đô thị. Lõi đô thị phải dừng lại một thời gian để đón những người tị nạn Infected đó. Dù Talulah có nhe nanh với Ursus, cô ta cũng không phản bội Reunion trước mặt tất cả mọi người. Đây là cơ hội tốt nhất. Ta sẽ dẫn Ảnh vệ đi.”","“Anh?!”","“Họ đã làm quá nhiều cho ta. Ta từng hứa sẽ không bao giờ bắt họ nhúng tay vào việc bẩn, rồi lại thất hứa hết lần này đến lần khác. Giờ ta lại bảo họ chết vì Lungmen sao? …Nếu vậy, ta sẽ đi cùng họ.”","“Em không cho phép,” Fumizuki nói. “Anh làm vậy là rơi đúng vào tay Kashchey. Đó chẳng phải chiến thắng gì cả. Nói rằng mọi điều chúng ta làm từ khi giành lại Lungmen đều nằm trong tay Kashchey, có phải là quá lời không?”","“Chúng ta đã từng thắng,” Wei Yenwu nói. “Lúc đầu đó là chiến thắng của chúng ta. Dù đau đớn, em và ta, Edward, và Kojui… Không có chúng ta, hắn đã xóa sổ thành phố này. Ta sẽ không coi cái chết của Edward là do tay Kashchey. Cơn ác mộng lẽ ra đã kết thúc khi Kashchey chết.”","“Hắn thật sự đã chết chưa?”","@cg:avg_7_10","“Có lẽ hắn sống tiếp trong Talulah. Một người kế thừa xứng đáng sẽ giúp hắn tiếp tục cuộc đời hỗn loạn của mình. Talulah giống hắn quá. Với một kẻ không con cái, Kashchey đã nhận được hạt giống phù hợp nhất. Dù ta có thể coi lời của Kal’tsit là bịa đặt, ta không thể phủ nhận sự thật. Có một âm mưu nhắm vào Lungmen, và nó mang quá nhiều nét chữ của Kashchey.”","“Em không tin. Tal chưa bao giờ là người như thế. Sao con bé lại làm vậy?”","“Chúng ta không còn cách nào khác ngoài tin. Talulah đã lên kế hoạch tất cả. Nhưng nếu cô ta nghĩ Lungmen sẽ ngoan ngoãn nằm xuống chịu chết, cô ta sẽ phải thất vọng. Lungmen sẽ không sụp đổ.”","“Nhưng anh cũng không ngăn được cuộc chiến này.” Fumizuki nhìn ông. “…Anh muốn em chết cùng anh sao?”","“Fumizuki?! …Em đang đe dọa ta sao?”","“A, không. Em không có ý đó. Chỉ là…”","“Không! Em không được!” Wei Yenwu nói. “Chỉ kẻ hèn nhát mới đứng trên xác người khác để nâng mình lên. Mà không có em… ta sẽ không thể…! Có lẽ trước kia ta từng hèn nhát, nhưng giờ thì không, Fumizuki. Ta sẽ không để ai động vào em. Ta sẽ tìm chỗ cho em trốn. Leithanien, Sargon, hay Sami… Em không thể về Higashi. Ta sẽ gửi em đến một đất nước xa xôi, một thị trấn nhỏ yên bình không ai biết. Anh trai ta… dù hận ta đến đâu, cũng sẽ không đuổi theo em đến tận cùng trời đất… Ta biết anh ấy sẽ không làm vậy.”","“Nhưng em không thể sống như thế,” Fumizuki nói. “Anh muốn em sống cả đời một mình sao, Yenwu? Anh muốn dùng cái chết của anh để hành hạ em suốt phần đời còn lại sao? Anh không nhớ vì sao em gái anh chết sao?”","“Không, không… Fumizuki, ta muốn em sống. Ta…”","“Wei Yenwu, em đã nói rồi… em không sao. Được chết cùng anh đã là kết cục tồi tệ tốt đẹp nhất mà em có thể tưởng tượng. Hay đúng hơn, dù tồi tệ đến đâu, với em đó vẫn là một cái kết tốt.” Bà mỉm cười buồn bã. “Nhưng anh biết đấy, anh không cản được em. Anh chưa bao giờ cản được em làm điều em muốn. Yenwu, anh luôn thẳng thắn với em. Có lúc anh không nói gì cả, nhưng khi anh nói ra, em luôn biết đó là sự thật. Em không muốn anh chết. Nhưng em cũng không muốn Tal chết. Em không muốn ai trong chúng ta chết cả.”","“Em nhớ Tal. Em luôn nhớ con bé giống em gái anh đến thế nào. Nhưng nó có đôi mắt của Edward, còn cái tính nóng nảy hồi nhỏ thì em chẳng biết nó thừa hưởng từ ai. Đã bao nhiêu năm rồi em không gặp con bé. Chúng ta nợ con bé tất cả những điều này.”","“…Và Hui-chieh.”","“Phải, cả Ch’en bé nhỏ nữa. Ch’en bé nhỏ đã đi rồi, em sẽ không bao giờ gặp lại con bé… Em sẽ không bao giờ được mua cho nó những bộ đồ đẹp và chải tóc nó thành một tác phẩm nghệ thuật nữa.”","“Con bé… không thích trang phục truyền thống lắm.”","“Nhưng em thích. Con bé sẽ đẹp biết bao.” Fumizuki lau khóe mắt. “Dù vậy, dù chúng ta đã nói lời từ biệt cuối cùng, em vẫn mong Ch’en bé nhỏ tìm được một nơi khác để yên ổn. Em biết anh không muốn dựa vào Rhodes Island, và anh sẽ không đặt hết cược vào họ. Nhưng em muốn anh đợi một thời gian. Hãy để họ làm, Yenwu. Nếu họ thất bại, chúng ta sẽ cùng đi. Anh không muốn tay mình lại nhuốm máu người thân, đúng không? Nếu chuyện đó xảy ra, em sẽ giúp anh lấy mạng Tal. Rồi chúng ta sẽ chết cùng nhau.”","“Fumizuki…!”","“Anh cũng muốn con bé sống, phải không? Lungmen này là nơi muốn tất cả chúng ta phải chết sao? Em thà không bao giờ gặp lại chúng nữa… thà không bao giờ gặp lại Ch’en bé nhỏ và Tal rồi quên chúng đi… nhưng em cũng muốn chúng sống tiếp. Giống như anh. Giống như anh muốn em đưa ra quyết định này.”","“Fumizuki. Nếu mọi chuyện vượt quá giới hạn, em phải nghe theo sắp xếp của ta. Mạng sống của chúng ta… không phải là không thể tách rời.”","“Tất nhiên rồi, Yenwu. Em không chỉ tồn tại vì anh. Mọi điều em làm, từ đầu đến cuối, không chỉ vì anh. Anh phải thấy em đang chiến đấu vì điều gì. Đừng né tránh nữa. Nhìn em đi.” Bà nghiêng đầu. “Anh muốn khóc sao? Khóc cũng không sao đâu, Yenwu.”","“Không, Fumizuki. Không… Ta ổn.”","“Thành thật đi.”","Wei Yenwu không trả lời.","<i>Có những người chỉ muốn được nghỉ ngơi, được tìm chốn nương thân trong một thành phố. Sao họ phải chịu những cái chết vô nghĩa? Chẳng phải chúng ta chỉ muốn cho họ một mái nhà sao? Chẳng phải chúng ta muốn mọi người như chúng ta, những người không còn nơi nào để đi, đều có một chỗ ấm áp để nghỉ ngơi sao? Chẳng phải ta chỉ muốn xây một thành phố nhỏ nơi mọi người được sống yên lòng sao?</i>","<i>Lungmen như bây giờ, rốt cuộc được xây cho ai?</i>","“Ta không phải nhà đạo đức, Fumizuki,” Wei Yenwu nói. “Nhưng càng nhìn kỹ, ta càng nhận ra chỉ cần một cái chết. …Của chính ta.”","“…Đừng như vậy! Anh không được!”","“Ta sẽ bảo Ảnh vệ hộ tống em đến Sargon.”","<i>Lungmen đã trở thành thế này từ bao giờ?</i>","<i>Và… ta đã trở thành thế này từ bao giờ?</i>"],"bg":"bg_lungmen_o","cast":[["Wei Yenwu","npc:char_2005_weiyw_1"],["Fumizuki",null]]},{"c":"7-8","t":"Cơn thịnh nộ của kẻ lặng câm","p":["<i>11:30 sáng. Lõi đô thị Chernobog.</i>","“Thủ lĩnh.”","“Đội Nỏ thủ U linh, ta mừng vì các ngươi trở về an toàn,” Talulah nói. “Các ngươi mang về nhiều người quá. Tất cả đều là người của chúng ta từ Lungmen sao?”","“Có rất nhiều người Infected… đã theo chúng tôi về,” tên nỏ thủ nói. “Tôi không nghĩ sẽ gặp ngài ở đây. Nhưng thưa Thủ lĩnh… tại sao Lungmen lại khác xa kế hoạch như vậy? Bao nhiêu đồng chí của chúng tôi đã chết vô ích ở đó!”","“Ngươi dám nói với Thủ lĩnh như thế à…?” một thành viên Reunion quát.","“Không, cậu ấy nói đúng,” Talulah giơ tay. “Nhiều người bạn thân yêu của chúng ta đã chịu khổ quá nhiều. Kẻ thù đã giăng nhiều cạm bẫy hiểm độc làm rối loạn kế hoạch của chúng ta. Đó là một thất bại lớn. Nhưng dù những người tiên phong gặp trở ngại, Reunion sẽ báo thù cho họ. Ta sẽ khiến vết thương và sự hy sinh của các ngươi được bù đắp. Đừng lo. Chúng ta sẽ luôn ở bên các ngươi.”","“…Mong là vậy, Thủ lĩnh.”","Ánh mắt Talulah dừng lại trên người tên nỏ thủ đang cõng. “Người ngươi đang cõng… Mephisto? Cậu ấy…” Cô ta im lặng một lúc. “Faust đã hy sinh để cứu cậu ấy, đúng không?”","“…Vâng, Thủ lĩnh. Không màng đến mạng sống của mình, Faust đã dùng Arts che giấu dấu vết để chúng tôi có cơ hội thoát thân.”","“Ồ?” Talulah khựng lại. “Đội Nỏ thủ U linh, những người Reunion của ta… Faust sẽ sống mãi trong tim chúng ta. Đỡ cậu ấy xuống đi. Mephisto cần nghỉ ngơi một thời gian.”","“Còn một chuyện nữa… Chúng tôi mất liên lạc với Crownslayer từ sớm. Không biết cô ấy đã đi đâu. Còn… Đội Yeti, và FrostNova, họ… họ đều…”","“——Thật là một tin bi thảm khôn tả,” Talulah nói khẽ. “Xin hãy cho ta… một chút thời gian một mình.”","Khi những người tị nạn đã được dẫn đi, Talulah quay sang những bóng Sarkaz đứng trong góc tối.","“Không được để chúng đến gần bất kỳ đơn vị Reunion nào trong thành phố.”","“Đến mức nào?”","“Đến cùng. Đảm bảo chúng không bao giờ đặt chân đến đây.” Talulah lẩm bẩm. “Chúng có giấu gì không, hay đã đào bới được gì? Đội của chúng hẳn biết điều gì đó mà ta không biết. Có lẽ… trận chiến ấy đã thay đổi cậu ta phần nào. Arts của cậu ta vốn đã phi thường, mà cậu ta lại ít nói. Cậu ta khoác lên mình sự im lặng. Ta đã tưởng Faust mới là người sống sót. Nhưng thôi, chuyện này cũng chẳng có gì lạ.”","<i>“…Ngươi là ai?”</i>","<i>Ta là ai?</i>","<i>“Ngươi muốn gì?”</i>","<i>Ta muốn gì…?</i>","<i>“Gia nhập… các người? Chiến đấu cho chính mình?”</i>","<i>Chiến đấu…?</i>","“À, vì Ursus cao quý,” Talulah thì thầm. “Ở đây lẽ ra ngươi phải là kẻ cuối cùng còn đứng vững.”","@bg:bg_cherunder","“Có vẻ lõi đô thị đã trở lại tốc độ cũ. Nó không dừng lâu,” Amiya nói. “Nhìn mặt tích cực, đó hẳn là lúc Reunion đón một nhóm người Infected di cư từ Lungmen. Em hy vọng…”","“Nhưng có lẽ chúng ta phải đổi chiến lược,” Kal’tsit nói. “Thành phố sẽ còn dừng vài lần nữa cho đến khi chỉ huy địch công bố kế hoạch của mình. Khi đó, cô ta sẽ thôi nhận người tị nạn. Nếu lúc đó Wei Yenwu quyết định tấn công, địch sẽ điều động lại lực lượng phòng thủ. Chúng ta có thể bị lộ trong quá trình đó.”","“Em mong thỏa thuận với chị Fumizuki sẽ giữ chân Trưởng quan Wei thêm một thời gian…” Amiya nhìn quanh. “Chúng ta đã rất gần trung tâm lõi đô thị rồi. Trên và dưới có rất nhiều lối đi, hình như từng là hệ thống giao thông của thành phố. Sau Catastrophe, mọi thứ đều ngừng hoạt động. Những lối đi này là chỗ ẩn nấp tốt. Số lính gác ở khu kho gần trung tâm đã tăng gần gấp đôi.”","“Đội trinh sát và đội tác chiến đặc biệt đã vào vị trí. Mọi thứ vẫn ổn.”","“Sao chỉ có ba đội phối hợp với nhau?” Doctor hỏi.","“Hai đội kia có nhiệm vụ riêng,” Kal’tsit nói. “Raidian dẫn đội trinh sát trong chiến dịch này. Cô ấy là một trong những chuyên gia liên lạc của Rhodes Island. Nhờ Raidian, ngay cả ở lõi đô thị này chúng ta vẫn liên lạc được với các đội khác. Đội trinh sát luôn làm việc một mình. Outcast, Raidian, và Scout, người đã anh dũng hy sinh trong nhiệm vụ cứu hộ ở Chernobog… Các elite operator dẫn đội trinh sát phải một mình chỉ huy đội, xác định và báo cáo mối đe dọa, và cố tự giải quyết chúng. Còn đội tác chiến đặc biệt, nhiệm vụ của họ cũng tránh giao tranh trực tiếp.”","“Bà không định nói cho tôi biết đó là gì à?”","“Chỉ cần biết họ cần thiết là đủ. Ngài sẽ sớm biết chi tiết.” Kal’tsit nói. “Mỗi đội là một mắt xích trong chuỗi chiến lược của chúng ta. Một cấu trúc ổn định sinh ra một kết quả ổn định. Ngược lại, một đối thủ đáng gờm có bộ rễ rối rắm. Chúng hút chất dinh dưỡng từ mọi tầng. Chặt cành chẳng làm chúng tổn hại gì. Chúng ta phải đốt rễ chúng trước khi chúng biết chúng ta ở đây.”","“Tôi nghĩ tôi hiểu.”","“Hừ. Ta khá chắc ngài hiểu hết…” Kal’tsit liếc Doctor. “‘Doctor.’”","“Khoan đã,” Rosmontis nói. “Có những cảm giác mơ hồ, xa xôi đang đến với em. Một dòng chảy trật tự, không thay đổi, không xung đột. …Cứng như thép. Và chúng đang di chuyển.”","“Đội lính gác của Reunion. Tránh họ và tìm đường khác…” Amiya nói.","“—Amiya. Cẩn thận. Em không cảm thấy sao?” Kal’tsit nói. “Các operator, chú ý… đeo đồ bảo hộ vào.”","“…Không thể nào… Rosmontis? Em có cảm thấy gì bất thường không?”","“Hử…? Không. Em không nghĩ vậy.”","“Chuyện này vượt quá Arts của Rosmontis,” Kal’tsit nói. “Em không thể chỉ dựa vào cảm xúc, Amiya. Có nhiều thứ để cảm nhận hơn là cảm xúc. Khi em lùa ngón tay qua mái tóc, điều đầu tiên em cảm thấy không phải nỗi nhớ hay niềm vui. Mà là thứ gì đó nguyên sơ hơn.”","“Nguyên sơ…?” Amiya nhắm mắt. “Có một chút… năng lượng. Và một mùi nồng trong không khí, như… xác chết? Không, đây không phải xác thật. Lẽ nào…? Là Sarkaz. Arts của Sarkaz. Đậm đặc mùi chết chóc… Một nghi lễ…?”","“Một nghi lễ cổ xưa tự vận hành sau khi thành hình,” Kal’tsit nói. “Không phải Arts hiện đại. Kẻ địch ở đây có thể là Sarkaz ‘thuần chủng’ nhất. Đây là những kỹ thuật mà không quốc gia hiện đại nào biết, chỉ được truyền lại giữa người Sarkaz cổ và dân du mục Sargon.”","“Nghi lễ dựa vào sự lây nhiễm Oripathy, và cách hiểu đặc biệt của kẻ thi triển về Originium,” Amiya nói. “Năng lượng hỗn loạn rỉ ra từ lõi Originium, tràn ra và bao trùm cả dãy phố. Nó không phân biệt bạn thù… mọi sinh vật sẽ bị những đợt sóng năng lượng từ từ xé nát.”","“‘Ăn thịt đồng loại’,” Kal’tsit nói. “Cách gọi nghe có vẻ hù dọa, nhưng nghi lễ này tên là vậy. Thiết bị ở trung tâm nghi lễ được gọi là tế đàn. Kẻ ngoài cuộc gọi nó là ‘phù thủy’. Nghi lễ này chỉ hoàn thành được ở một thành phố đã mất vào tay Catastrophe. Đồ bảo hộ của chúng ta sẽ không triệt tiêu được nó. Sức mạnh của nó bắt nguồn từ thời cổ xưa. Chúng ta chỉ có thể giảm sát thương, rồi phá hủy nó sau khi dọn sạch khu vực. Một nghi lễ Sarkaz không chỉ là thách thức với công nghệ hiện đại. Nó gần như đứng dậy để thách thức một lần nữa các nền văn minh khác trên thế giới, như người Sarkaz đã mưu tính suốt chiều dài lịch sử.”","“Đó là ẩn dụ.”","“Phải. Nhưng lịch sử Sarkaz không chỉ là ẩn dụ.”","Amiya suy nghĩ một lúc. “Doctor, bác sĩ Kal’tsit. Những nơi địch thực hiện nghi lễ Sarkaz chắc chắn là vị trí quan trọng, hoặc nút giao thông then chốt. Chúng thông thuộc địa hình hơn chúng ta nhiều. Lợi thế duy nhất của chúng ta là thông tin. Chúng ta biết chúng bố trí thế nào, còn chúng chẳng biết gì về chúng ta. Nên chúng ta phải nhanh chóng quét sạch địch canh giữ khu này. Càng nhanh càng an toàn. Đừng để chúng báo động những lính gác khác.”","“Được. Ta sẽ hỗ trợ tấn công.”","“Ừm, vâng… em nghĩ… bác sĩ Kal’tsit, em nghĩ, nếu…”","“—Được thôi,” Kal’tsit nói. “Nếu ngài không cần ta giúp, Doctor. Hãy giúp Amiya chỉ huy chiến dịch.”","“Rõ! Rosmontis, xuất phát thôi! Đánh xong trận này chúng ta sẽ lên bề mặt lõi đô thị. Rosmontis… ít nhất ở đó sẽ có nắng.”","“Nắng~”","<i>(Hừ. Nhìn chúng kìa.)</i> Kal’tsit nghĩ. <i>(Phần còn lại là ở ngài, Doctor. Ta biết ngài sẽ không làm chúng ta thất vọng.)</i>","<i>Kal’tsit, chúng ta sẽ không thấy lại nỗi thất vọng ấy nữa đâu. Không ai tắm hai lần trên cùng một dòng sông. Sẽ không có lần thứ hai. Dù cùng một người, cùng một chuyện… ở một thời điểm khác, kết quả sẽ khác. Thế giới này… sẽ thay đổi. Cô tin điều đó mà, phải không? Phải rồi… Cô không tin cũng là điều dễ hiểu. Nhưng tôi tin. Kal’tsit… Kal’tsit. Nếu… chúng ta có thêm chút thời gian… cô và tôi…</i>","<i>(Ngài có thể chứng minh ngài không phải Doctor mắc kẹt trong quá khứ,)</i> Kal’tsit nghĩ. <i>(Ở thời điểm này… Dù bằng cách nào, Doctor, ngài phải làm được.)</i>","","<i>Nhà kho Chernobog. 12:40.</i>","“Nhiều nhà kho và thiết bị lưu trữ thế này… đây hẳn là khu kho,” Amiya nói. “Cứ theo đường này sẽ đến khu trung tâm.”","@cg:avg_7_11","“Amiya! Lại đây xem! Trong nhà kho.” Một operator gọi. “Dấu vết giao chiến bằng Arts dạng lưỡi sắc. Ba tên Reunion bị hạ gọn rồi ném vào đây.”","“…vẫn còn thở.” Amiya cúi xuống. “Bác sĩ Kal’tsit! Nhờ bác sĩ và các operator y tế lo cho mấy người Reunion này. Họ có thể có thông tin quan trọng. Và chúng ta đã tìm thấy dấu vết của cô Ch’en ở đây… Vết máu. Cô ấy bị thương. Vệt máu dừng ở đằng kia, cô ấy đã cầm được máu. Chỉ một người rời khỏi hiện trường. Chắc chắn là cô Ch’en. …Cố lên, cô Ch’en. Chúng em đang đến…”","“Cảm giác như đã từng thấy cảnh này,” Doctor nói.","“Ha… Vâng, ở Chernobog cũng y như vậy. Nhưng lần này khác hẳn. Hồi đó chúng ta chỉ có một thỏa thuận hợp tác. Em mới bắt đầu biết cô Ch’en là người thế nào… Còn giờ, chúng ta đã…” Amiya khựng lại. “Đó là… dân thường sao?”","Một người phụ nữ gầy gò đứng giữa lối đi, tay cầm một thanh sắt.","“Đây là nghĩa địa của Ursus!”","<i>(Cảnh giác… nhưng đừng nổ súng!)</i> Amiya ra hiệu. “Chúng tôi là một nhóm trung lập nghiên cứu người Infected! Thưa chị, chúng tôi đến để giúp chị! Chúng tôi không có ý hại chị, chị là một người Infected bình thường—”","“Infected? Phì! Tôi là người Ursus!” Người phụ nữ gào lên. “Các người muốn giúp người Infected…?! Ha, nói nhảm… Các người không biết người Infected các người đã làm gì với chúng tôi sao? Không, không, tôi cũng là người Infected. Nên tôi không được nói với các người như thế, phải không? Các người sẽ cứu người Infected? Ahaha, hahaha… Người Infected nên chết hết đi! Tôi cũng nên chết đi. Tôi cũng nên chết! Nếu không có người Infected, tôi đã không bị nhiễm bệnh! Tất cả những gì họ nghĩ đến là trả thù và làm hại người khác… ĐÓ là việc người Infected làm sao? Đó là việc tôi nên làm sao?!”","<i>(Amiya, an ủi chị ấy đi?)</i> Rosmontis thì thầm.","<i>(Không. Chưa phải lúc,)</i> Amiya đáp. <i>(Để chị ấy trút ra. Mọi ký ức đau đớn tích tụ suốt một tháng qua đang đâm vào ý thức chị ấy. Đã đến lúc chị ấy… đối mặt với chúng.)</i>","“Cô có biết chúng tôi ở đây là ai không, đồ Infected?” người phụ nữ nói. “Người Infected, giống như cô. Cả sống lẫn chết. Những người Infected vừa đủ sống sót nhờ Reunion, và vô số người Infected chết ở đây cũng nhờ Reunion… Nhưng trước kia chúng tôi đâu phải người Infected. Chúng xua người Chernobog chạy tán loạn, rồi săn lùng chúng tôi. Ban đầu là tàn sát, rồi đến tra tấn, cuối cùng chúng vứt những người sống sót như rác! Tôi không biết bao nhiêu người đã chết đói hay chết cóng… Nhưng những người còn sống đều nhiễm bệnh vì tiếp xúc liên tục với Originium! Không sót một ai! Các người, lũ Infected… Lũ Infected chết tiệt…!!”","“Hãy tin chúng tôi… Chị không cần đưa chúng tôi đến chỗ những bệnh nhân khác. Chúng tôi sẽ để lại những thứ chị cần để cấp cứu. Rồi chúng tôi sẽ đi.”","“Tôi không tin các người. Ursus cử các người đến à? Hay Lungmen?”","“Nếu thật là họ, chúng ta đã chết rồi.”","Một giọng nam vang lên từ sau đống thùng. Một người đàn ông mặc đồ Reunion bước ra.","“Là anh…!” Amiya thốt lên.","“Amiya, quét mã nhận dạng của cậu ta,” Kal’tsit nói lạnh lùng. “Guard, giải thích đi.”","@cg:avg_7_12","“Lâu rồi không gặp, Amiya, bác sĩ Kal’tsit.” Người đàn ông nhìn sang. “Và, Doctor.”"],"bg":"bg_perimeter","cast":[["Amiya","op:char_002_amiya"],["Kal'tsit","op:char_003_kalts"],["Talulah","npc:avg_npc_078"],["Rosmontis","npc:avg_npc_042"]]},{"c":"7-10","t":"Ngọn lửa của kẻ yếu ớt","p":["“Trông tôi chắc giống hệt một thành viên Reunion… nhỉ?” Guard cười gượng.","“Vậy là các người quen nhau,” người phụ nữ nói. “Phải rồi, nên mọi lời con bé Cautus này nói đều là dối trá. Các người và Reunion vốn cùng một phe! Đúng không?!”","“…Tati… Cô có tìm được đồ ăn không? Những người ở chỗ trú ẩn không cầm cự được lâu nữa,” Guard nói. “Đưa cô đến chỗ an toàn trước đã.”","“Tránh xa chị ấy ra, Guard!” Amiya nói.","“Tôi đứng xa rồi đây. Tôi biết có những chuyện khó giải thích. Nhưng chúng ta phải cẩn thận. Tất cả người Ursus ở đây nhiễm bệnh mà không phải lỗi của họ… và họ đã trải qua nhiều chuyện kinh khủng. Phần lớn đã trên bờ vực suy sụp tinh thần… Chỉ cần ai đó đẩy nhẹ là ngã.”","“Kinh khủng? Các người là lũ giết người tâm thần! Lũ bệnh hoạn!” Tatiana hét. “Vì các người… nhìn xem tôi thành ra thế nào!”","“Nhưng nếu cô không đi ngay, bọn quỷ sẽ tìm thấy cô. Cô sẽ bị giao cho Reunion,” Guard nói. “Quân của Patriot đã rút hoàn toàn khỏi khu vực này. Nếu cô bị bắt, tôi không cứu được nữa.”","“Thế thì để tôi chết! Tôi thà chết còn hơn nhìn lũ quái vật các người hoành hành! Còn đội du kích, cái gọi là ‘Lá chắn của người Infected’ thì sao? Họ có khác gì phần còn lại của Reunion không?!”","“Có. Không có họ, chúng ta đã chết từ lâu rồi.”","“Vậy nói đi! Ngay bây giờ! Nếu họ chỉ muốn làm điều đúng, sao họ vẫn ở với Reunion? Sao họ làm thế với nhà chúng tôi? Sao họ không nổi dậy? Sao họ không bỏ đi?! Sao đội du kích vĩ đại của anh không đánh lại lũ quỷ đi tuần? Tại sao?! Tôi đã thấy chúng… chúng dùng chính tay mình… xé… toạc…”","Guard im lặng một lúc. “Patriot không thể có mặt ở mọi nơi cùng lúc. Khi Patriot phải chỉ huy quân để bảo vệ sự thiêng liêng của sự sống, nghĩa là có điều gì đó đã sai khủng khiếp. Nhưng… chừng nào đội du kích còn đi qua khu này, tôi đảm bảo những kẻ thật sự độc ác trong Reunion sẽ không đặt chân đến đây. Đó là khác biệt giữa đám côn đồ Reunion và chiến binh du kích của Patriot. Tôi đã tận mắt thấy. Tôi thấy người lính bảo những người khác gọi các cô bằng tên, chứ không phải bằng số. Đúng không?”","Tatiana không trả lời.","“Lý do họ để chúng tôi lại là để chúng tôi giúp các cô khi họ vắng mặt,” Guard nói. “Chernobog đã bị chia cắt thành nhiều mảnh. Có những nơi đội du kích đóng quân, nhưng cũng có nhiều nơi không… Nếu không ai giữ được kỷ luật, muốn sống sót… các cô chỉ có thể dựa vào chúng tôi. Mà đó còn là giả sử chúng tôi sống sót. Amiya, em có tin những gì tôi vừa nói không?”","“Không!” Tatiana chen vào. “Cô bé Cautus, nhìn đi… Nhìn đi! Hắn là Reunion! Sao cô tin được bất cứ điều gì từ Reunion? Còn tôi thì sao? Giờ tôi là người Infected thì tôi phải tin mấy lời nhảm nhí của chúng à? Làm sao tôi biết được ai là ai, và ai trong các người sẽ giết tôi?”","<i>(Amiya,)</i> Kal’tsit nói khẽ. <i>(Đừng kích động.)</i>","“Kal’tsit? Chúng ta nên đi tiếp,” Rosmontis nói.","Guard quay phắt lại, mặt tái đi. “…Cô… Sao cô lại ở đây…?! Lại là cô! Các người… định diệt sạch Reunion sao?! Rhodes Island, các người thật sự chẳng khá hơn…” Anh ta lắc đầu. “…Gác chuyện đó lại! Đội tuần tra lính đánh thuê Sarkaz sắp đi qua nhà kho này! Nếu không xử lý chúng, hay ít nhất là trốn đi, chúng sẽ tìm thấy và bắt chúng ta đi… Đó là lý do nhiều người chết đói, thiếu thuốc. Amiya, bác sĩ Kal’tsit! Và… Doctor, tôi thật sự mong các người tin tôi. Hoặc ít nhất tìm chỗ trốn đi!”","“Người phụ nữ Ursus nhiễm bệnh,” Kal’tsit nói. “Ta có vài câu hỏi thành thật.”","“G-giọng của bà… bà đến từ thủ đô Đế quốc phải không? Nhưng cách bà nói chuyện cổ quá…”","“Cô có học.”","“…Trước kia tôi là người chép sách ở trường đại học. Giờ thì mất hết rồi, nhờ lũ Infected các người.”","“Được. Cô có tin người đàn ông sau lưng cô không? Cựu nhân viên Infected của chúng ta, giờ đi theo Reunion?”","“Hả? Anh ta… là nhân viên của bà?”","“Một trong những chức năng của Rhodes Island là giúp người Infected vô tội sống sót trong môi trường chiến tranh. Cô có vô tội hay không thì còn phải xem… Tuy nhiên.”","Một bóng đen lóe lên. Mon3tr xuất hiện sau lưng Guard, móng vuốt kề sát cổ anh ta.","“Áaaa!” Tatiana hét lên.","“Bác sĩ Kal’tsit!” Amiya kêu.","“Bà làm gì vậy?!” Doctor nói.","“…không ngờ có ngày Mon3tr lại nhắm vào mình,” Guard lẩm bẩm.","“Lưỡi dao kề cổ cậu có góc cắt chỉ tám độ. Sâu thêm sáu milimet là đứt động mạch,” Kal’tsit nói. “Cô gái. Cậu ta có thật sự cố gắng để cô sống sót như cậu ta nói không? Cậu ta và nhóm Reunion của cậu ta, hay bất kỳ ai trong số họ, có đe dọa tính mạng cô hay làm gì hại cô không? Ta sẽ xử lý cậu ta theo câu trả lời của cô.”","“Bà đang đe dọa tôi bằng mạng anh ta sao?! Tôi… chúng tôi… chẳng liên quan gì đến nhau!”","“Còn cá nhân cậu ta thì sao? Cậu ta có tiếp tay cho Reunion và tội ác chống lại loài người của chúng không?”","“Bác sĩ… Kal’tsit… Tôi thấy bị xúc phạm đấy!” Guard nói.","“Ta chỉ có thể dựa vào lời của nhân chứng và nạn nhân. Cậu chỉ kể phần của cậu,” Kal’tsit nói. “Cô ấy ở vị trí khác. Cậu có sức mạnh. Cậu có thể dùng bạo lực. Cậu đã làm gì với bạo lực đó không quan trọng.”","“Em cảm thấy rồi,” Rosmontis nói. “Amiya, là bọn Sarkaz. Mục tiêu đang đến gần.”","“Không thể… nhưng anh ta…” Tatiana lắp bắp.","“Cậu ta có bảo vệ cô khỏi Reunion hay không? Có giữ cô an toàn trước sự hung hãn của chúng hay không?”","“Bác sĩ Kal’tsit…! Đội tuần tra đến rồi! Không phải đội du kích! Bà không thể… Đừng để chúng…”","“Bà nói vô lý quá!”","“Ta tin hành động của chúng ta nằm trong khuôn khổ đạo đức của Ursus. Chính cô là người buộc tội cậu ta.”","“Anh ta… anh ta thường ra ngoài vào giờ này…”","“Ta cần câu trả lời. Nói đi. Nếu không chúng ta sẽ không bao giờ biết sự thật.”","“Hai mươi bốn mét, đường thẳng. Rất gần,” Rosmontis nói. “Hai mươi hai mét.”","“Mon3tr.”","“Bác sĩ Kal’tsit!”","“Không! Anh ta không làm! Anh ta không làm gì sai cả!” Tatiana hét lên. “Ít nhất… ít nhất là những gì tôi thấy!”","Mon3tr rút móng vuốt về.","“Amiya, Doctor,” Kal’tsit nói. “Cảm ơn đã dành thời gian.”","“Chết tiệt… Bác sĩ Kal’tsit! Em biết ngay mà…!” Amiya thở hắt ra. “Đi thôi, Doctor! Mục tiêu tiếp theo là đội tuần tra Sarkaz của Reunion!”","“Em cũng đi.” Rosmontis nhìn Guard. “Anh là Guard phải không? Anh hiểu lầm em rồi. Nhưng em sẽ bảo vệ anh. Em sẽ trả thù cho anh. Chúng sẽ phải trả giá cho những gì chúng làm với anh, với gia đình em, với dân thường. Chúng sẽ trả giá, cho tất cả.”","","“Nghi lễ không ảnh hưởng gì đến đám Sarkaz này… Nhưng operator Sarkaz của chúng ta thì không miễn nhiễm? Tại sao?” Amiya lẩm bẩm. “Mà trông họ không giống người của đội du kích. Lạ thật…”","“Rosmontis… Cảm ơn em,” Guard nói.","“Em đi tuần đây. Đừng cảm ơn em. Như Amiya hay nói, không cần cảm ơn người ta vì đã làm đúng việc của mình.”","Amiya đưa cho Tatiana một ống thuốc. “Tác dụng của thuốc ức chế Oripathy cần thời gian mới thấy. Nhưng giờ chị sẽ đỡ đau hơn nhiều. Mang thuốc về cho những người khác. Không nhiều đâu, chắc chỉ đủ một liều, nhưng sẽ giúp với các triệu chứng cấp tính. Xin lỗi, chúng tôi không giúp được nhiều hơn. Chúng tôi phải đánh bại thủ lĩnh Reunion trước đã.”","“Những lời tôi nói với cô… tôi… trước kia tôi đâu như thế này,” Tatiana nói. “Tôi từng ghét những người như cô. Giờ tôi giống các cô rồi. Ai cũng ghét tôi. Suýt nữa tôi đã giết anh ta. Nhưng không có anh ta giúp… có lẽ chúng tôi đã chết. Mỗi lần anh ta để chúng tôi đi tìm đồ tiếp tế, lại có người chết. Tôi đã tưởng đó là bằng chứng anh ta cấu kết với Reunion để đùa giỡn với chúng tôi. Dù chúng tôi đã là người Infected rồi? Reunion… thật sự căm ghét người Ursus đến thế sao?”","“Con người không cần nhiều để buông thả theo mặt xấu xa nhất của bản tính,” Kal’tsit nói. “Chỉ cần thả lỏng cho họ là đủ để nhiễm độc mọi ngóc ngách của một thành phố.”","“Bác sĩ Kal’tsit… bác sĩ làm em sợ đấy!” Amiya nói.","“Amiya, em không nên để những trò này ảnh hưởng đến mình.”","“Vậy… bác sĩ Kal’tsit, nếu cô ấy nói dối, bà có thật sự giết tôi không?” Guard hỏi.","“Tất nhiên là không. Cậu là operator của Rhodes Island. Ta tin cậu hơn bất kỳ ai. Cứ coi đó là một liệu pháp tâm lý cho cô ấy. Tất nhiên, cách cậu và cô ấy phản ứng đã chứng minh cậu vô tội.”","“Nhưng vẻ mặt bà lúc đó u ám và đáng sợ lắm. Tôi đã tưởng bà làm thật… bà diễn đạt quá.”","“Thế cũng được. Ta sẽ không làm, nhưng ta muốn người ta nghĩ là ta sẽ làm.”","“Bác sĩ Kal’tsit, bác sĩ quá tay rồi… không được dọa Guard nữa,” Amiya nói. “Đừng lo, Guard. Nếu bác sĩ quá đà, em đã ngăn lại rồi. Anh có cần em giúp ổn định cảm xúc không?”","“À, không cần. Chỉ thế này mà cần đến liệu pháp Amiya thì tôi yếu quá.” Guard liếc ra cửa. “Người tôi thật sự lo là cô bé đứng ở cửa kia. Tôi và cô bé đã nói chuyện rõ ràng, và tôi nghĩ tôi hiểu… nhưng tôi vẫn không quên được lần cô bé chém đôi một người chỉ bằng một nhát kiếm lớn. Chuyện đó sẽ theo tôi suốt đời.”","“À… em biết vụ anh nói,” Amiya nói. “Guard, anh có biết trong chiến dịch đó cô bé đã cứu bốn dân thường không? Rằng quân đội đang thử vũ khí trên họ? Cô bé đã giết một caster thử nghiệm cấp vũ khí bị bỏ rơi mà họ mua từ một tên buôn nô lệ Sargon. Cả lô caster đó đều bị cắt bỏ tuyến yên bằng phẫu thuật, thay bằng một thiết bị Originium giữ cho họ cử động mà không cần hệ thần kinh. Họ đã chết từ trước rồi. Chỉ Rosmontis, với cách chiến đấu đặc biệt của mình, mới phá hủy được những cơ quan nhiễm bệnh thử nghiệm đó. Cô bé không làm gì sai.”","“…Hóa ra là vậy sao?”","“Guard, em nghĩ anh đã đánh giá sai Rosmontis, giống như chị kia đánh giá sai anh. Vẻ ngoài và tin đồn là ô cửa đầu tiên để người ta nhìn vào tính cách của mình. Dù anh làm gì, họ vẫn sẽ nhìn anh như một người Reunion trước tiên. Nhưng nếu chúng ta không bao giờ vượt qua bề ngoài… chúng ta sẽ chẳng bao giờ biết gì, chứ đừng nói đến học cách tin nhau. Mà Rosmontis ở ngay trước mặt anh. Sao anh không… hỏi cô bé?”","“H-hỏi á?”","“Anh muốn hỏi gì?” Rosmontis quay lại.","Guard nuốt nước bọt. “…Rosmontis, em đến đây làm gì?”","“Nhiệm vụ của em. …Và, như em đã nói, trả thù. Cho gia đình em.”","“Tôi hỏi xong rồi. Nhưng… tôi còn chẳng biết mình vừa hỏi gì.” Guard cười khổ. “Trước thì giận Azazel, giờ lại thô lỗ với Rosmontis. Ha, tôi thật là một mớ hỗn độn.”","“Nhưng cậu tin Patriot,” Kal’tsit nói. “Kể cho chúng ta nghe về Patriot, đội du kích của ông ấy, và về Reunion.”","“Lý do duy nhất còn có người sống sót, lý do nhiều người Ursus vượt qua được Chernobog… là nhờ Patriot và đội du kích của ông ấy. Và những người tôn trọng họ,” Guard nói. “Khi chiến binh du kích ở đây, mọi thứ yên bình. Không ai dám động tay vào ai. Họ không chỉ phân phát đồ tiếp tế, mà còn cố làm cuộc sống của người dân khá hơn một chút. Patriot định để tôi rời thành phố. Nhưng tôi quyết định ở lại… để xem mọi chuyện ra sao. Tôi tình cờ nghe ông ấy nói chuyện với người đứng đầu Azazel. Tôi nghĩ dù tất cả chỉ là diễn, ít nhất ông ấy cũng đang cố hết sức để diễn cho tròn.” Anh ta ngập ngừng. “Còn nữa… anh Scout đã chết ở đó để bảo vệ tôi. Patriot kính trọng anh Scout. Tôi…”","“Scout… là operator đã hy sinh ở Chernobog,” Doctor nói.","“Scout!” Rosmontis kêu lên.","“Rosmontis…?”","“Chuyện gì đã xảy ra với Scout? Em… sao em không nhớ được? Anh ấy chết rồi? Anh ấy… Khoảng trống này… là anh ấy sao? Scout… em lại quên nữa sao? Nhưng em vừa mới… thiết bị… sao em lại quên được nữa?”","<i>Ngày 3 tháng 1.</i>","<i>Một ông già tóc trắng mang đến một vật cháy đen. Mechanist nhìn thấy nó thì không đứng vững được nữa. Ông già gật đầu rồi đi. Bác sĩ Kal’tsit không nói gì, chỉ xoa đầu em.</i>","<i>Đó là đồ của Scout.</i>","<i>Scout. Scout cũng mất rồi.</i>","<i>Chẳng phải Scout là người còn không có cả cái bóng sao? Chẳng phải anh ấy là người sẽ trở về dù mọi người khác đã chết sao? Chẳng phải anh ấy là người có câu chuyện không bao giờ kết thúc sao?</i>","<i>Scout……</i>","<i>Em đã tra nhật ký. Scout từng làm cho em một cây cung. Nhưng đó là đồ chơi của con gái nhỏ. Em không chơi đồ chơi nữa.</i>","<i>Tại sao Scout chết?</i>","<i>Tại sao? Tại sao? Tại sao?</i>","<i>Tại sao?</i>","Rosmontis khóc nấc.","“Rosmontis…” Amiya nắm lấy tay cô bé. “Đưa tay cho chị. Nhắm mắt lại, Rosmontis…”","“Hóa ra elite operator… cũng không khác gì… đồng đội của tôi,” Guard nói khẽ. Rồi anh ta quay sang Doctor. “Doctor, tôi có điều muốn nói. Trong chiến dịch giải cứu ngài, Scout dẫn đội trinh sát. Anh ấy chưa từng biết ngài như bây giờ… Nhưng anh ấy nói anh ấy từng biết ngài trước kia, giống Ace. Anh ấy chặn đám lính đánh thuê Sarkaz để cứu mạng tôi. Với Scout, nếu muốn, anh ấy hoàn toàn có thể thoát ra. Anh ấy dặn tôi nhắn với ngài một điều… Phải, tôi nhớ rồi. Anh ấy nói anh ấy sẽ không bao giờ quên những ngày chiến đấu bên ngài.”","Doctor im lặng.","“Anh ấy cũng muốn ngài thôi làm chỉ huy. Nhưng tình hình thế này, tôi nghĩ có lẽ ngài không thể ngồi yên mà nhìn,” Guard nói. “Đội trưởng của tôi cũng hy sinh để cứu tôi. Nghĩa là tôi đang mang trên vai mạng sống của hai elite operator. Nhưng anh Scout nói họ không chết vì một người nào. Họ chết vì một lý tưởng. Đội của anh ấy cũng vậy, đội của tôi cũng vậy. Nên tôi quyết định tìm hiểu Reunion. Tôi phải xem mọi chuyện đi về đâu, và tôi có thể giúp Rhodes Island thế nào. —Tôi thấy đội du kích có lý tưởng riêng. Một niềm tin vững chắc, thuần khiết mà họ chiến đấu vì nó. Họ hơi tàn bạo một chút, tất nhiên, nhưng họ chưa bao giờ thấy vui trong bạo lực. Nếu Reunion là để giải phóng người Infected, thì đội du kích… ở đó để tiêu diệt những kẻ áp bức. Họ sẽ tiêu diệt những kẻ nô dịch người Infected, những kẻ đe dọa dân thường. Tất cả. Không sót một tên. Đó là nhờ Patriot. Patriot dạy dỗ họ, dẫn dắt họ, bảo vệ họ. Trước khi Patriot rời Chernobog làm nhiệm vụ, tôi đã… nói chuyện với ông ấy. Haizz. Chiến binh ấy rốt cuộc bao nhiêu tuổi chứ? Vậy mà ông ấy vẫn chia rượu với tôi. Đó là lần đầu tiên… có người đối xử với tôi như thế.”","“Ông ấy có lẽ già hơn cậu nghĩ nhiều,” Kal’tsit nói.","“Bà có nghe truyền thuyết không? Về việc ông ấy rời Ursus?”","“Có. Ông ấy dẫn cả một sư đoàn tinh nhuệ rời khỏi Ursus. Cuộc Đại Nổi loạn là mảnh đất màu mỡ cho đủ thứ chuyện mà thường ngày sẽ là vô lý.”","“Sự thật là những người lính ông ấy dẫn ra khỏi Ursus giờ chẳng còn mấy người. Phần lớn đội du kích là tân binh, những người tình nguyện gia nhập khi họ chiến đấu ở lãnh nguyên tây bắc. Họ từng hợp tác tốt với thủ lĩnh Reunion. Nhưng vì lý do nào đó, có lẽ liên quan đến mối hận thù rực cháy của người Infected với người Ursus… mọi chuyện thành ra thế này.” Guard quay sang người phụ nữ. “Tatiana… Tôi nhớ tên cô là Tatiana. Đầu gối cô còn đau không? Ba ngày trước cô ngã khi đang chạy trốn.”","“Nó khỏi lâu rồi…! Tôi là người Ursus! Tôi không giống… cái chủng tộc gì của anh. Người Ursus chúng tôi khỏe hơn nhiều.”","“Tôi mừng… trông nó lúc đó khá tệ.” Guard cười. “Ha, tôi lại đi làm việc của operator y tế mà chẳng được huấn luyện gì. Tôi có nhiều việc phải lo lắm, bác sĩ Kal’tsit. Medic không đi cùng mọi người sao?”","“Sao lại nhắc đến chị ấy?” Rosmontis hỏi.","“Đừng bận tâm. Nhìn mặt Rosmontis là tôi biết chuyện gì rồi. Chúng ta đã mất nhiều người, nhưng Rhodes Island vẫn chiến đấu.”","“Ta có cảm giác cậu không biết lõi đô thị đang trên đường đâm vào Lungmen,” Kal’tsit nói. “Lõi đô thị đang phát mã nhận dạng của Ursus.”","“Hả? …Cái gì?! Khoan đã! …Không thể nào… Chuyện này vô lý quá!”","“Giờ cậu biết vì sao chúng ta ở đây rồi.”","“Có chuyện gì vậy?” Tatiana hỏi. Kal’tsit ra ký hiệu “im lặng” của Rhodes Island.","“Không có gì…”","“…Các người nói lâu quá. Nếu Patriot và người của ông ta tốt như anh nói, sao Reunion vẫn hoành hành ở Ursus?”","“Vì Reunion ‘lẽ ra không’ làm thế,” Kal’tsit nói.","“Guard,” Amiya nói. “Em nghĩ anh sẽ giúp ích rất nhiều cho chiến dịch, vì anh hiểu cả người Infected ở đây lẫn Reunion. Anh có muốn trở lại đội không? …À, nhưng anh chưa thể đi được, đúng không?”","“…Phải. Nhìn tôi là em biết rồi, nhỉ, Amiya? Xin lỗi, tôi biết tôi hơn em cả chục tuổi, nhưng đôi khi em làm tôi thấy mình như đứa trẻ.”","“Không cần tự trách,” Kal’tsit nói. “Ta còn có thể nói Rhodes Island sẽ ghi nhận công việc của cậu. Nhưng cậu đang ở vị trí rất nguy hiểm. Nếu Reunion sụp đổ ở đây, công việc cứu người Infected và duy trì điều kiện sống cơ bản của cậu sẽ khó khăn hơn nhiều. Cậu có lo chuyện đó sẽ xảy ra không?”","“Không. Vì Reunion có Patriot. Chừng nào ông ấy còn ở đây, Reunion sẽ không sụp đổ. Nhiều chiến binh du kích đã rời trại tập hợp lại. Tôi nghĩ có lẽ vì ông ấy đã trở về. Và nếu ông ấy ở đây, tôi tin Reunion vẫn có thể thay đổi. Có những chuyện… Rhodes Island không xử lý được. Đây là một trong số đó! Rhodes Island là một công ty. Bác sĩ Kal’tsit đã nói rõ điều đó bao nhiêu lần rồi. Tôi tin Đội trưởng, và anh Scout… Và tôi tin Patriot.”","“…Em biết,” Amiya nói.","“…Em không giận sao, Amiya?”","“Sao em phải giận anh… vì những điều chúng ta không làm được, và những điều chúng ta chưa làm? Hai tuần qua có quá nhiều chuyện. Tất cả chúng ta đã thay đổi nhiều. Nhưng chúng ta sẽ không quay lưng với nhau vì người Infected. Em nghĩ mọi chuyện đã xảy ra ở Chernobog, và những gì em và Guard thấy, là như nhau.”","“Đúng. Tôi vẫn không chịu nổi việc làm hại người khác như thế. Dù ai làm với ai, tôi cũng không chấp nhận. Nếu Patriot muốn dọn dẹp Reunion, tôi phải đứng về phía ông ấy, về phía người của ông ấy, và tất cả những thành viên Reunion tin vào Patriot.”","“Chúng ta không coi lối suy nghĩ mới của cậu là mối đe dọa,” Kal’tsit nói. “Thực ra, chúng ta khuyến khích mọi operator tìm hiểu thế giới bên ngoài, theo đuổi mục tiêu riêng và xây dựng sự tự tin. Ta hy vọng cậu tìm được chỗ đứng giữa những người Ursus này như cậu muốn. Ta hy vọng cậu bảo vệ được những người xứng đáng được bảo vệ.” Bà ngừng lại. “À phải. Về lương, e là công việc ở đây không được tính lương. Xin lỗi. Và Guard, cho ta hỏi— Nếu Patriot phản bội Talulah, chuyện gì sẽ xảy ra?”","“…Không có chuyện đó. Patriot tin Talulah sâu sắc.”","“Vậy còn chiều ngược lại? Nếu Talulah phản bội Patriot thì sao?” Kal’tsit nói. “Hoặc, nếu ta nói rằng chúng ta đã chạm trán chỉ huy Reunion FrostNova, và xét một cách khách quan, chúng ta phải chịu trách nhiệm cho cái chết của cô ấy thì sao?”","“Bác sĩ Kal’tsit?! Bà đang nói gì vậy?!” Guard tái mặt. “Đó… đ-đó là con gái của Patriot…!”","“Nếu chúng ta đánh nhau với Patriot…” Amiya nói khẽ. “Đó sẽ là trường hợp tồi tệ nhất. Và là điều những kẻ giật dây mong muốn. Nếu Talulah thật sự làm ngơ, thậm chí để mặc người Infected làm hại dân thường bất chấp lập trường của Patriot… em tin đó không còn chỉ là làm ngơ nữa. Rất nhiều người Infected sẽ biến Patriot thành mục tiêu. Những kẻ không biết sự thật, những kẻ để hận thù chế ngự. Và những kẻ muốn làm vậy.”","“Tôi… tôi phải đi,” Guard nói. “Tôi phải báo cho Patriot! Nhưng… Rhodes Island… Ông ấy sẽ… trở thành kẻ thù của các người sao?”","Anh ta chạy biến vào bóng tối.","“Tôi không nghĩ mọi chuyện lại thành ra thế này,” Doctor nói.","“Đây không phải bước đi hiển nhiên của Reunion,” Amiya nói. “Dù là Misha hay FrostNova… Chúng ta, Reunion, cả Lungmen nữa… Không thể để thêm ai rơi vào kẽ nứt. Doctor, chúng ta còn nhiều việc lắm… chỉ nghĩ đến những gì sắp tới đã thấy mệt. Nhưng trước đó… phải tìm cô Ch’en. Và quan trọng nhất… thủ lĩnh Reunion. Cô ta là nguyên nhân của tất cả.”","@bg:bg_chercen_1","“Đội Mantra-2, nghe rõ không?” Kal’tsit gọi.","“Đội trưởng đã xác định được phương thức liên lạc của Reunion,” Elysium đáp. “Nó thô sơ, thậm chí trông như cố tình. Về nhân sự, cô ấy sắp dọn xong khu vực rồi. Không phải đội du kích thì. Họ cứng lắm. Có cần loại bỏ họ không?”","“Không cần. Chúng ta không đến để tiêu diệt họ, hay để họ tàn sát lẫn nhau. Chúng ta không đến để khuấy động nội chiến. Họ nên chống lại kẻ đã lừa dối họ,” Kal’tsit nói. “Tinh thần của họ đã mục rữa, nhưng cái xương sống giả tạo của họ vẫn còn. Rút nó ra hay bẻ gãy nó, họ sẽ sụp đổ. Đó là điều lúc đầu chúng ta có thể đã làm. Nhưng Talulah đi trước chúng ta một bước. Cô ta khuấy động xung đột và thổi bùng nó lên. Lúc đầu ta tưởng cô ta đã điên. Nhưng đây là thuốc độc, không phải sự điên loạn. Ta tin chắc cô ta muốn hủy diệt Reunion, bằng cách đê hèn nhất có thể. …Và đây là thứ độc chúng ta phải hóa giải. Nhưng tất cả phụ thuộc vào quyết định của Buldrokkas’tee…”","“Có vẻ chúng ta đã xâm nhập lõi đô thị thành công,” Doctor nói.","“Vì những gì chúng ta làm tiếp theo khó mà gọi là xâm nhập được nữa, Doctor. Như ta nói từ đầu, xâm nhập chỉ chiếm khoảng hai mươi phần trăm kế hoạch. Để đến tháp chỉ huy và khu máy phát điện mà dừng Chernobog lại, chúng ta phải đi qua khu trung tâm. Những kẻ thù trên đường không phải đám Reunion tầm thường, cũng không phải lính đánh thuê Sarkaz thô bạo. Đội du kích Infected Bình nguyên phương Bắc, cái gai trong vùng hậu phương của Tập đoàn quân số Bốn Ursus ở tây bắc… Từ khi thành lập, nó chỉ có một người lãnh đạo. Những người kháng chiến bình thường bị tàn sát, nhưng đội du kích này lại khiến đồ tể trở thành con mồi. Cuộc chiến kéo dài đến mức những người Infected trốn trong tuyết gọi đội du kích là ‘Lá chắn’ của họ. Lá chắn của người Infected. Đội Yeti là một nhánh của nó, và thành viên không chỉ có người Infected. Kẻ lưu đày, kẻ cuồng tín, người tàn phế, Elf, Durin, Sarkaz. Đội du kích không chỉ chiến đấu vì người Infected.”","“—Nghe quen quá.”","“Giống hệt Rhodes Island, phải không?” Kal’tsit nói. “Như trước kia, Rhodes Island sẽ được lợi từ trực giác của ngài, Doctor.”","“Bà không giận sao?”","“Sao ngài nhìn vào mắt ta khi nói điều đó? Đôi mắt này chẳng có gì để nhìn đâu. Không, ta không nghĩ những gì ngài nói có gì sai. Đội du kích cũng chỉ tin một chỉ huy duy nhất, và chỉ đi theo một chỉ huy duy nhất. Phải, Doctor, đội du kích này là một kiểu ‘Rhodes Island’ khác. Nhưng người lãnh đạo của họ? Không.” Giọng bà trầm xuống. “Doctor, hãy chuẩn bị kỹ. Nếu không ngài sẽ hối hận. Vì an toàn của ngài, ta vẫn mong ngài và Amiya sẽ không phải đối mặt với ông ấy. Nhưng nếu mọi chuyện là không tránh khỏi, ta chỉ có thể nhắc lại. Hãy chuẩn bị kỹ. Và trước khi đối mặt với ông ấy, ngài phải chuẩn bị đối mặt với đội du kích của ông ấy. Ta hiếm khi khuyên ai, Doctor. Nhưng đó là ‘Patriot’, Buldrokkas’tee.”","","Guard thở hổn hển chạy qua những dãy phố đổ nát.","“Còn… một dãy nữa… sao? Không… Không! Mình phải… phải báo cho Patriot… Nếu Talulah… nếu Talulah để những kẻ này… tấn công đội du kích… Thì… đội du kích sẽ… sẽ bị chính người mình giết…! Patriot… Patriot là người tỉnh táo cuối cùng trong Reunion…!”","“Ngươi định đi đâu?”","Một bóng người to lớn chặn đường.","“Ngươi… Sarkaz.”","“Ngươi thuộc lữ đoàn nào? Có việc gì ở khu trung tâm? Giải thích đi,” tên lính đánh thuê nói. “À, hay ngươi là người của lão Wendigo. Con mồi tự chạy đến chỗ ta. Ngươi đã biết được gì, tên Infected ngoại lai yếu ớt?”"],"bg":"bg_warehouse","cast":[["Guard","npc:avg_npc_059"],["Kal'tsit","op:char_003_kalts"],["Amiya","op:char_002_amiya"],["Rosmontis","npc:avg_npc_042"],["Tatiana","npc:avg_npc_057"],["Elysium","op:char_401_elysm"]]},{"c":"7-13","t":"Lá chắn của người Infected","p":["<i>Khu trung tâm Chernobog. 1:20 chiều.</i>","“Raidian, Kal’tsit đây. Chúng ta đang ở rìa khu trung tâm, cách nhà kho bốn trăm mười mét về phía tây nam. Cô vào vị trí chưa? Chiến dịch có theo kế hoạch không? ‘Thông suốt’? Tốt.” Kal’tsit nói. “Reunion bố trí chiến binh du kích ở các nút giao khắp lõi đô thị, còn Reunion thường hoặc lính đánh thuê Sarkaz đóng ở những chỗ khác. Chúng sẽ tập trung tinh nhuệ ở vài địa điểm then chốt. Nếu ta lãnh đạo Reunion, ta cũng sẽ làm vậy.”","“Bác sĩ Kal’tsit!” Amiya kêu.","“Ta biết em muốn nói chuyện với Raidian, Amiya. Kiên nhẫn.”","“Em… em cũng muốn…” Rosmontis nói.","“…Chúng ta đang làm nhiệm vụ. Lần sau nhé?”","<i>(Raidian là operator thế nào vậy?)</i> Doctor thì thầm.","<i>(Ngài thấy Amiya và Rosmontis phản ứng rồi đấy,)</i> Kal’tsit đáp. <i>(Nhân viên trẻ tuổi của chúng ta rất yêu quý Raidian. Nhưng với người lớn, cô ấy có lẽ hơi quá ấm áp và thân thiện. Tuổi mới lớn là gặp khó khăn nhất. Nhu cầu tự khẳng định bản thân của chúng hay xung đột với sự quan tâm như mẹ không ngừng của Raidian. Ta thường tránh xếp họ chung một đội.)</i>","“Vâng… em thấy rồi, Raidian,” Amiya nói vào liên lạc. “Đúng vậy. Đó không phải chiến thuật thông thường của du kích. Nó giống… ừm…”","“Giống quân đội?” Doctor gợi ý.","“Vâng! Như Doctor nói, Raidian, Reunion có pha trộn một chút, nhưng vẫn thấy bóng dáng quân đội Ursus. Mạng lưới nòng cốt của Reunion có thể là những người Infected đã được huấn luyện quân sự Ursus. Rõ ràng trận này sẽ không dễ dàng. Hử? Không, em ổn. Em, Rosmontis, tất cả operator Rhodes Island… đều muốn có mặt ở đây. Vâng, không sao đâu Raidian, em có Doctor và bác sĩ Kal’tsit bên cạnh.”","“Được rồi, Amiya, đến lúc bắt đầu,” Kal’tsit nói. “Đội R-4, kích hoạt thiết bị. Raidian, Rosmontis cần mười phút để thi triển Arts. Trong thời gian đó, chúng ta không được mất liên lạc dù chỉ một khắc. Dùng Originium Arts liên tục sẽ khiến cô khó chịu. Nếu buồn nôn không chịu nổi, lập tức uống chất bổ sung ta pha cho cô. Đừng quá liều. Chúng ta đang đòi hỏi cô rất nhiều, Raidian. Rosmontis, mọi tín hiệu của địch sẽ được Raidian gửi đến thiết bị cầm tay của em. Cảm nhận chúng, và ghi lại. Nếu vị trí của chúng thay đổi, em không được để mất dấu. Hãy vươn ra bằng cơ thể mình, Rosmontis, và tưởng tượng em đang dạo khắp thành phố.”","“Em hiểu, bác sĩ Kal’tsit.”","“Amiya…”","“Em biết.”","“Việc của em nặng nhất. Nếu có gì bất thường, ta sẽ dừng việc thi triển của em. Ngay khi em thấy đau, báo cho ta.”","“Rosmontis… chị đến gần em nhé.”","“Vâng, em cũng sẵn sàng rồi. Em không sợ. Amiya, chị đừng sợ em nhé.”","“Chị sẽ không sợ. Chị không sợ Rosmontis. Chúng ta sẽ không sợ.”","Hai cô bé chạm trán vào nhau.","“Amiya đang ổn định cảm xúc của Rosmontis,” Kal’tsit nói. “Ngài có lẽ không nên nhìn thẳng vào họ, Doctor. Ngoài những chiến binh bất hạnh nhất, nhìn thẳng vào sự bành trướng bản chất Arts của Rosmontis là không khôn ngoan.”","“Ý bà là… cô thỏ nhỏ của chúng ta…?”","“Ta tưởng ngài sẽ nhận ra sớm hơn. Hoặc ngài đã biết nhưng chưa thể hiện ra với ta. Nhưng đúng vậy, Doctor. Những trận chiến của Amiya, cả thể xác lẫn tinh thần, đã vượt xa những gì một con người nên phải chịu đựng. Nếu ngài muốn, ngài có thể nắm tay Amiya để chia sẻ gánh nặng đó.”","Doctor đưa tay ra.","“Không, ít nhất không phải hôm nay. Ngài và ta có một việc gấp khác. Chúng ta cần mua cho chúng thời gian quý giá.” Kal’tsit nói. “Một công ty dược điều tra nguyên nhân gốc rễ của vấn đề, thích nghi với môi trường, phân bổ chức năng hợp lý, và tìm điểm đột phá. Mục tiêu của chúng ta nhỏ và chính xác hơn một trận đánh thông thường. Công việc của một đội tấn công chiến thuật nhỏ giống một ca phẫu thuật hơn là một trận đọ súng. Nhưng dù cắt bỏ được khối u, nếu nguyên nhân vẫn chưa rõ, vấn đề sẽ không được giải quyết tận gốc. Doctor, ta mong ngài cân nhắc kỹ. —Ai là bệnh nhân của chúng ta? Người Infected bình thường? Người Ursus bị nhiễm bệnh? Reunion? Hay thành phố này? Và nguyên nhân căn bệnh nằm ở đâu?”","Bà tiếp tục. “Rõ ràng Talulah cố tình giữ các cụm Originium từ Catastrophe trong thành phố để duy trì sự hỗn loạn. Nó làm nhiễu loạn liên lạc nghiêm trọng. Nhưng nhờ Raidian, chúng ta tận dụng được sóng vô tuyến hỗn loạn ấy. Đó là lợi thế chiến thuật thứ nhất. Ngài đã thấy những người đưa tin cầm loa. Đội du kích dùng cách cổ lỗ này để truyền tình báo và mệnh lệnh mã hóa. Đó là cách ổn định và kỷ luật nhất trong môi trường thù địch. Ngài đoán xem cách này có vấn đề gì?”","“Đội không sống được nếu mất đầu.”","“Chính xác. Vị trí của chỉ huy thật sự được giấu kín. Ở vị trí đó, ngài sẽ làm gì?”","“Dùng mồi nhử.”","“Chính xác. Đó là lợi thế chiến thuật thứ hai. Arts mà Rosmontis đang thả ra sẽ cho chúng ta biết vị trí của mọi người đưa tin và lộ trình tuần tra của họ. Đội du kích hoàn toàn không biết chúng ta nhắm vào liên lạc của họ, hay chúng ta chống lại được phép phù thủy Sarkaz cổ đại. Sau khi đánh vào người đưa tin, đội du kích sẽ phản ứng. Trong nửa tiếng, họ sẽ có người đưa tin mới và cảnh giác cao độ. Nhưng chúng ta chỉ cần một đòn phẫu thuật duy nhất. Với một đòn đó, chúng ta sẽ buộc đơn vị chỉ huy của họ lộ diện. Đội du kích sẽ không ngờ đến một đội đặc nhiệm Infected khác. Đó là lợi thế thứ ba.”","“Có thành công không?”","“—Ta sẽ không phóng đại. Doctor, dù có ba lợi thế chiến thuật, khả năng thất bại của chúng ta vẫn cao hơn thành công.”","“Vậy sao lại làm thế?”","“Vì mọi cách khác còn ít khả năng thành công hơn.” Kal’tsit nhìn sang hai cô bé. “Rosmontis hẳn đã bắt đầu tìm kiếm. Nín thở, và đừng nhìn.”","“—Thứ nhất— Em… tìm thấy ba.”","“Rosmontis… em ổn. Lại đây, gần thêm chút nữa,” Amiya thì thầm.","“…Bốn.”","“Tai em. Chị đang vuốt ngón tay qua tai em như thế này… em nghe thấy mà. Đây chỉ là những mảnh vụn trong trí tưởng tượng của em, em đã thấy tất cả trước đây rồi.”","“Ưm… Năm.”","“Doctor, ngài có sợ bị thương không?” Kal’tsit hỏi. “Ba đội sẽ tách ra chiến đấu. Mỗi đội phụ trách một khu, hạ đội địch và vô hiệu hóa người đưa tin. Không được cho chúng cơ hội báo tin. Còn ngài, ngài đi với ta. Ngài không từ chối được đâu. Trang bị của đội du kích chất lượng rất cao, tương đương quân đội Ursus, và họ giữ kỷ luật còn khắt khe hơn. Sarkaz, Ursus, Liberi và nhiều chủng tộc khác cùng đứng dưới một lá cờ. Ngài chỉ an toàn dưới sự bảo vệ của ta.” Bà khựng lại. “…Khoan. —Rosmontis?”","“A… Ưm…”","“Raidian, ngắt kết nối của Rosmontis. Ngay!” Kal’tsit quát. “Amiya, trạng thái tinh thần của em ấy?”","“Nhưng… Rosmontis… Khung cảnh em vươn tới rất ổn định, không có gì lạ… Lẽ ra không… Em ấy đang… rơi? Em ấy… đang nhìn lên trời? …Lạc rồi. Em ấy lạc rồi. Em ấy đang rơi.”","“Thân nhiệt giảm, thở gấp… Nồng độ endorphin giảm mạnh.”","“Có cần tiêm không?”","Kal’tsit lắc đầu. “Đây không giống Raidian dùng chất bổ sung để hồi sức. Arts của Rosmontis làm mất cân bằng trong cơ thể em ấy, nhưng không hoàn toàn là cân bằng sinh học. Tiêm steroid có thể phá vỡ hệ nội tiết của em ấy, dẫn đến suy giảm chức năng ức chế.”","“Em… em… Các người bỏ em sao? Tại sao… Em phải… —Tại sao các người lại bỏ em…?”","“Tệ thật,” Doctor nói.","“Tệ không phải là cớ để ta dung túng sự bất tài của mình,” Kal’tsit nói. “Doctor, ta sẽ không dùng biện pháp khẩn cấp gây tổn hại vĩnh viễn cho cơ thể… dù chúng hiệu quả đến đâu. Vấn đề của Rosmontis không phải sinh học. Chỉ em ấy mới giải quyết được.” Bà quỳ xuống. “Rosmontis. Rosmontis, nhìn tay ta.”","“Bác… sĩ… Kal… tsit…”","“Nhìn tay bác sĩ Kal’tsit. Tay ta đang vuốt mặt em. Nhìn này, bác sĩ Kal’tsit ở đây. Nhìn ta. Rosmontis, Kal’tsit không có nhiều thời gian ở bên em. Amiya cũng vậy… Outcast, Misery, Blaze, hay bất kỳ ai. Nhưng lúc này, Amiya và ta đang ở đây. Cố lên, Rosmontis. Bước tới.”","“Vâng, Rosmontis… lối này. Đi lối này. Trên boong tàu,” Amiya nói. “Chị biết khó lắm… Nhưng Rosmontis, đây là boong tàu, em có thể bước lên. Em sẽ không rơi xuống. Đây là Rhodes Island.”","“Chúng ta ở đây với em.”","“Chị ở đây với em.”","“—Em biết.” Hơi thở của Rosmontis dần ổn định. “…Bác sĩ… Kal’tsit… đưa em… dữ liệu.”","“—Được. Raidian, kết nối lại thiết bị của Rosmontis. Em ấy ổn rồi. Ta chắc chắn. Làm đi.”","“—Thứ hai. Bảy.”","“Em thấy rồi…” Amiya mỉm cười. “Rosmontis đang đứng vững. Ý thức của em ấy yên bình và hài hòa. Ôi… giống như một chiếc giỏ bông mềm đựng những giấc mơ của em ấy. Chúng ta ổn rồi, bác sĩ Kal’tsit.”","“Giỏ bông mềm… mèo con à?” Doctor nói. “Hợp với em đấy.”","“Phì,” Rosmontis bật cười. “Amiya đỏ mặt rồi kìa, Doctor.”","“…Chị không muốn em thấy đâu!”","“Không sao. Ưm. Không sao.” Rosmontis nhắm mắt. “Nữa… nữa. Amiya, đi tiếp một chút nữa. Em cảm thấy rồi. Thứ ba. …Bác sĩ Kal’tsit, em tìm thấy rồi. Tất cả.”","“Chúng ta sẵn sàng.”","“Vâng, cảm ơn bác sĩ. Và cảm ơn chị, Amiya.”","“Đừng cảm ơn chị vì đã làm việc của mình, Rosmontis… không cần đâu. Em biết chị thích nói câu đó mà?”","“Vâng. Nhưng chị đã đưa em lên cầu, lên núi… và mây đẹp lắm. Đường còn dài. Đi thôi, Amiya. Chúng ta có thể xuống rồi.”","","“Có vẻ ngài đang có điều suy nghĩ,” Kal’tsit nói.","“Tôi muốn nói về cô bé tóc bạc.”","“Lúc nãy ngài rất may mắn. Có lẽ Rosmontis quý ngài. Em ấy đã kiềm chế được cơn bộc phát. Nếu không, ngài đã cắn đứt lưỡi mình khi nhìn ta và Amiya dẫn dắt em ấy, và thấy Arts của em ấy hiện hình.” Kal’tsit ngừng lại. “…Rosmontis sinh ra trong phòng thí nghiệm. Em ấy không chịu chung bi kịch với phần lớn người Infected thí nghiệm. Em ấy không chết vì những thí nghiệm ngày càng tàn nhẫn. Khi dự án tiến triển, em ấy dần nghiền nát cả cơ sở. Phòng thí nghiệm không hủy diệt được em ấy, em ấy đã hủy diệt nó. Arts của em ấy gắn liền với trạng thái tinh thần. Nhóm tìm thấy em ấy và đưa lậu về Rhodes Island đã nói rõ: ‘Rosmontis không tồn tại.’ Ta biết ngài đang nghĩ gì. Không, dù bằng vũ lực hay ép buộc, ta sẽ không bao giờ cho phép một cá nhân từng trải qua chuyện đó trở thành operator. Nhưng chính Rosmontis đã chọn trách nhiệm, huấn luyện, và có bạn đồng hành. Chúng ta không muốn bỏ em ấy giữa hoang mạc. Không muốn tiêm thuốc ức chế cho em ấy. Và chắc chắn không muốn Rhodes Island thành một đống mảnh vụn. Giải pháp này là cuối cùng. Chúng ta phải dạy em ấy dùng Arts, thay vì nuông chiều hay giam cầm em ấy.”","“Em ấy giống Amiya ở vài điểm, và khác ở vài điểm,” bà nói tiếp. “Giống ở chỗ cả hai sẽ chiến đấu đến cùng vì người khác. Còn khác— Ngài biết Amiya chưa bao giờ muốn có kẻ thù. Kể cả khi bị ép, em ấy cũng cố nén nước mắt, miễn cưỡng tiêu diệt kẻ thù. Còn Rosmontis… em ấy chưa bao giờ bỏ dở một nhiệm vụ nào. Trước mọi tình huống, em ấy xử lý thích đáng và chiến thắng. Đó là Chuyên gia Hủy diệt vừa hợp lý vừa khó hiểu của chúng ta. Những operator từng sợ em ấy dần hiểu em ấy thật sự là người thế nào, và cuối cùng giao tính mạng mình vào tay em ấy. Vì em ấy bảo vệ họ bằng tất cả sức mạnh. Nếu Blaze giành được sự tôn trọng nhờ dẫn dắt đội mình, thì Rosmontis đã chiến đấu để giành lấy nó. Arts của em ấy cũng đủ để giúp Amiya và ta đối mặt với thủ lĩnh đội du kích… ‘Patriot của Reunion’.”","“Cha của Yelena…” Doctor nói.","“Bác sĩ Kal’tsit!” Rosmontis gọi. “Ga xe điện bỏ hoang, sau tấm biển nhà hàng đổ, cổng Trường Trung học số 4, tầng ba tháp đồng hồ tòa thị chính!”","“Đã nhận.”","“Rõ! Em sẽ đến tòa thị chính!” Amiya nói.","“Vậy chúng ta đến Trường Trung học số 4, Doctor. Đi,” Kal’tsit nói. “Rosmontis, Amiya và ta sẽ lo người đưa tin. Còn ngài, Doctor, sẽ chỉ huy các đơn vị tự do làm chậm chiến binh du kích. Nhớ rằng, chúng ta chỉ nhắm vào những kẻ thù có thể nhắm. Khi đội du kích tập hợp lại, chúng ta rút. Đây sẽ là một trận kéo dài. Chúng ta có thể chịu thương vong, thậm chí thua hoàn toàn. Nếu chuyện đó xảy ra, người Infected có thể phải đối mặt với một thời kỳ đen tối mới. Kết quả tốt nhất là đội chỉ huy không xuất hiện. Nhưng ông ấy sẽ không như vậy, vị chỉ huy du kích này. Ông ấy sẽ không mất kiểm soát trận đánh và nhìn đội mình tan rã. Không chỉ niềm tin giữ người của ông ấy lại với nhau. Ông ấy có sức mạnh xứng với danh tiếng của mình. Sau trận này, nếu mọi chuyện thuận lợi… chúng ta sẽ dốc toàn lực vào cuộc đối đầu với đội chỉ huy của họ. Chúng ta sẽ đối mặt với Buldrokkas’tee.”","","“Người đưa tin số Ba, đã hạ!” Amiya hô.","“Người đưa tin số Bảy, đã phá hủy!” Rosmontis đáp.","“Người đưa tin số Tám, đã chặn,” Kal’tsit nói. “Raidian, thực hiện đòn nghi binh! Kéo hết địch đi!”","“Hộc, hộc… gian nan quá. Mọi người ổn chứ?” Amiya hỏi.","“Vẫn ổn… Nhưng… dữ dội thật. Tôi chưa từng thấy trận nào quy mô thế này… Sống sót về được là tôi phải xin nghỉ phép đấy.”","“Được. Em duyệt. Nhưng trước tiên… hạ đội này đã! Rồi muốn tăng lương, nghỉ phép hay nhiệm vụ gì, em đều chấp nhận!”","Phía bên kia chiến tuyến, các chiến binh du kích giữ vững đội hình.","“Đừng phân tâm! Về đội hình! Giao tranh lớn ở lối ra phía đông? Bình tĩnh, tiến chậm. Đừng cho chúng sơ hở!”","“Đây không giống chiến thuật của Ursus hay Yan. Chuyện gì thế này? Chúng là ai?”","“Bắn tỉa lính Ursus bao năm, giờ lại bị phục kích?”","“Cẩn thận tế đàn! Bùa hộ mệnh Đội trưởng cho chỉ giảm được tác dụng của nó thôi. Ông ấy dặn cả triệu lần là không được lại gần trừ khi bắt buộc!”","“Người đưa tin, liên lạc các đội khác. …Không có phản hồi? Súng cối đâu? Bọn quỷ đâu? …Khoan. Có gì đó không ổn.”","“Người đưa tin số Mười hai, đã phá hủy!”","“Đội du kích đang khép đội hình! Đây là cơ hội tốt nhất để đột phá!” một operator kêu.","“Không! Có thể là bẫy!” Doctor nói.","“…Ừm. Rõ.” Amiya gật đầu. “Rosmontis, quét khu vực bằng Arts đi.”","“Em không vươn tới được. Địch… đang chặn em bằng cách nào đó.”","“Caster Sarkaz. Chỉ họ mới gây nhiễu được Arts như của Rosmontis,” Kal’tsit nói.","“Vậy thì để em…!” Amiya nhắm mắt. “Em… em tìm thấy rồi. Vâng. Họ giấu rất nhiều lính bắn tỉa và caster trong những tòa nhà kia. Họ bình tĩnh… vài người bồn chồn. Nhưng họ không cuồng tín. Họ… đang cố thủ điểm đó. …Bổn phận. Doctor nói đúng. Là bẫy.”","“Em ở gần đó. Em đến đây,” Rosmontis nói. “Em sẽ không đập cả tòa nhà. Em chỉ phá tầng họ đang ở thôi, để họ không làm phiền chúng ta. Amiya, em làm được.”","“Ừ, Rosmontis… chị biết em làm được. Chắc chắn.”","“…Amiya, vậy chị sẽ bội phục em chứ?”","“Hả? Gì cơ?”","“Em nghe Blaze nói chẳng có mấy người khiến chị bội phục.”","“Bội phục? À… nghĩa là ‘kính phục’ phải không? Xin lỗi, chị không giỏi tiếng Yan lắm.” Amiya cười. “…Không quan trọng. Vì chị luôn bội phục Rosmontis. Em giỏi lắm, thật đấy. Chị không làm được những gì em làm… Chị không chịu nổi sự mất mát và cô đơn ấy. Chị không thể sống với nó như em, chịu đựng nó như em.”","“Chị nói dối,” Rosmontis nói. “Nhưng em không quan tâm. Dù chị nói dối, với em chị vẫn là Amiya. Có người… bội phục… một người như em sao?”","“Như em vừa nói đấy, Rosmontis. Em là Rosmontis, nên chị kính trọng em. Cả với tư cách elite operator lẫn bạn bè. Cố lên, Rosmontis.”","“Vâng. Chúng ta cùng cố lên.”","","“Chúng ở đâu? Chúng đang đợi gì?” một chiến binh du kích hỏi. “Không được rời khu vực! Chúng ló mặt là đánh ngay! Không ai được mất liên lạc nữa! Này, có phải kẻ địch trên nóc tòa nhà đằng kia không? …Một con mèo? Chỉ một cô bé Feline…?! Người đưa tin! Báo caster! Địch triển khai caster trên tòa nhà đối diện! Phải hạ cô ta! —Một thanh kiếm? Vũ khí? Cô ta rút chúng ra từ không khí… Hả? Vũ khí bay lơ lửng?”","“Cắt từ đây, đến đây,” Rosmontis nói khẽ. “Cầm nó… bằng tay em. Cắt, bằng kiếm. …Như cắt một củ khoai tây.”","<i>Như cắt một củ khoai tây.</i>","“Doctor! Lại đây!” Kal’tsit kêu.","“Cả tòa nhà… bị cắt làm đôi?”","“Rosmontis đang phá điểm phục kích của đội du kích. Coi chừng mảnh vỡ rơi!” Kal’tsit kéo Doctor nấp. “Nếu ngài muốn hỏi về Arts của Rosmontis, có lẽ đã đến lúc giải thích. Đó là một trạng thái tinh thần do chính em ấy định hình. Ngài có thể hình dung như Rosmontis có một cơ thể thứ hai khổng lồ, vô hình, không thể bị tác động. Một sự kéo dài vô hình của xúc giác. Em ấy có thể nắm, bóp, nhấc lên, và ném đi. Nó tác động lên chúng ta bằng lực, nhưng chúng ta không tác động được lên nó. Trước khi chúng ta đặt vũ khí vào tay, Rosmontis còn phá hoại hơn nhiều. Giống như bị bánh xích của một nomadic city nghiền qua. Tất cả những gì còn lại là một cô bé ngồi khóc một mình giữa đống đổ nát. Không bao giờ được để chuyện đó xảy ra lần nữa.” Bà ngẩng lên. “…Doctor, đi. Ta thấy rồi. Đội chỉ huy đang đến… Dưới đài phun nước đổ nát trong công viên hẳn có một đường thủy. Họ giấu mình ở một nơi thật khó ngờ. Câu chuyện về trận phục kích ở đỉnh Graymane, phục suốt bảy ngày liền và lừa được hiệp sĩ mạnh nhất, có lẽ là thật. Raidian, ngừng bắn. Tìm chỗ nấp tốt. Ta cần cô tập trung giữ liên lạc. Mantra-2, ghi lại mọi cuộc trò chuyện. Từng chữ một.”","“Nhóm người đưa tin số Mười bốn, đã chặn thành công,” Rosmontis nói. “Amiya, bác sĩ Kal’tsit, em sẵn sàng.”","","Một chiến binh du kích lấy thân che cho người đưa tin bị thương.","“Này! Các ngươi nhìn gì?! Sợ đánh với chúng ta à? Sợ dòng máu của Patriot? Sợ phép phù thủy của ông ấy? Các ngươi không phá được khiên chúng ta, không xuyên được giáp chúng ta! Các ngươi chẳng là gì trước Patriot bất tử! Chiến binh mạnh nhất Ursus… không cần giáo hay khiên. Ông ấy sẽ giẫm các ngươi thành từng mảnh! Chiến binh của chúng ta sắp tập hợp ở đây! Các ngươi không chạy được đâu. Reunion sẽ cho các ngươi nếm địa ngục! Lũ áp bức nô dịch người Infected như chúng ta! Các ngươi sẽ bị phong trào Reunion nuốt chửng! Reunion—”","“…Reunion đã phản bội các chú rồi,” Amiya nói.","“—Cô bé?” Người chiến binh sững lại. “…Hai… cô bé Infected?”","“Tránh ra,” Rosmontis nói. “Có một người sau lưng chú, và em sẽ phá cái thiết bị sau lưng người đó.”","“Ngươi nghĩ ta sẽ nương tay chỉ vì ngươi trông như trẻ con à? Đừng coi thường Hộ vệ của Patriot! Chúng ta là Lá chắn của người Infected… Ta ở đây để chặn đòn tấn công của ngươi. Nếu ngươi tấn công người Infected, ta sẽ bóp cổ ngươi bằng chính đôi tay này!”","“Vậy vũ khí của em sẽ nói thay em.”","“Ngươi… Ngươi là con mèo lúc nãy. Thanh kiếm của ngươi…”","<i>(Chạy đi, hộ vệ! Báo cho mọi người! Tôi không sao đâu!)</i> người đưa tin thì thầm.","<i>(Đó là việc của cậu, không phải của tôi! Cậu phải sống!)</i>","“Lại đây, thử xuyên khiên ta! Thử phá giáp ta!”","“Amiya. Em hết cách rồi,” Rosmontis nói. “Chú ấy sẽ không chết. Nhưng có lẽ chú ấy sẽ không bao giờ đi lại được nữa.”","“Khoan—” Doctor kêu.","“Đi. Đâm…”","“Ngươi, không được.”","Thanh kiếm khổng lồ dừng lại giữa không trung. Một bàn tay đeo găng sắt đã chặn nó lại.","“Sao… chú chặn được kiếm của em bằng tay không?” Rosmontis lùi lại. “Ưm… Tay em… tê rồi. Chú đến từ lúc nào? Em không hề cảm thấy… Không. À… em nghĩ… em tưởng đó là tiếng tòa nhà sụp đổ, hóa ra là chú? Chú, không, chú và đội của chú… Các chú giống như… một ngọn núi.”","“Rosmontis, lùi lại,” Kal’tsit nói.","“Nhưng em…”","“Đó là mệnh lệnh, Rosmontis. Mệnh lệnh.”","“Đội trưởng…!” người chiến binh du kích thốt lên.","Patriot đứng sừng sững giữa khói bụi, cao gấp đôi một người thường, bộ giáp đen sạm vì vô số trận chiến.","“Ngươi đã làm, tốt. Đi đi, tập hợp lại.” Ông quay về phía Rhodes Island. “Còn các ngươi… Rhodes Island. Ta không quan tâm, các ngươi, là ai. Các ngươi tấn công, người của ta. Các ngươi, phải chết.”","“Ông chắc là không quan tâm chứ?” Kal’tsit hỏi.","“Rất, chắc—” Patriot khựng lại. “Khoan… khoan đã. Ngươi… Ngươi… sao lại…?”","“…Buldrokkas’tee.”","“Ngươi…”","“Lâu rồi không gặp.”","“Ngươi… Phu nhân Kal’tsit?”"],"bg":"bg_chercen_1","cast":[["Kal'tsit","op:char_003_kalts"],["Rosmontis","npc:avg_npc_042"],["Amiya","op:char_002_amiya"],["Patriot","npc:avg_npc_025_1"]]},{"c":"7-18","t":"Cái chết của người ái quốc","p":["“Đã lâu lắm rồi, Buldrokkas’tee,” Kal’tsit nói.","“Phu nhân, Kal’tsit? Sao bà… không già đi?” Patriot quay về phía đội của mình. “Hộ vệ khiên. Du kích. Chờ lệnh. Giữ vị trí.”","“Rõ.”","“Thưa Ngài.”","“Cách ông nói chuyện… là vì cơ quan bị nhiễm bệnh ở thanh quản sao?”","“Không. Chỉ là, lâu dần, thành như vậy. Ta không thể, nói trôi chảy, nữa.” Patriot cúi đầu. “Phu nhân… Ta không nghĩ, sẽ gặp lại bà. Ta còn nhớ, mờ mờ. Khi người của ta, rời đi. Bà và, Bệ hạ, không ngăn chúng ta.”","“Chuyện đó đã lâu lắm, lâu lắm rồi.”","“Khi ấy ta, đang độ sung sức. Giờ ta biết, quá đột ngột. Ta đã sai, về Đức Vua.”","“…Ông vẫn gọi bà ấy là ‘Bệ hạ’ và ‘Đức Vua’.”","“Vua, là vua. Khi ta đi, bà ấy chưa là vua. Giờ, bà ấy đã mất.”","Amiya im lặng.","“Ông vẫn phân biệt Vua của Kazdel và Hoàng đế của Ursus,” Kal’tsit nói.","“Lễ nghĩa. Chiến tranh không, làm rối, suy nghĩ của ta. Những người ta từng phụng sự? Đều đã mất. Ursus giờ, cũng là quê hương ta. Chủ nhân của ta, chôn ở Ursus. Vùng đất rộng lớn.” Ông nhìn bà. “Đã lâu quá, Phu nhân. Khi chúng ta đi… người của ta, chưa tàn lụi. Nhưng bà… không thay đổi. Năm tháng, không thay đổi bà.”","“Không đúng. Năm tháng đã thay đổi tất cả chúng ta, Buldrokkas’tee. Ta không còn là người phụ nữ ngày trước. Buldrokkas’tee… vì sao ông rời Kazdel?”","“Vì sao ta đi, ta nghĩ, bà sẽ cười. Ta đi, vì ta ghét, giết chóc. …Nhưng cả đời ta, đã giết chóc.”","“Những gì ông trải qua chỉ tôi luyện ý chí của ông. Máu ông vẫn chảy trong huyết quản. Ta sẽ không cười ông. Ông xứng đáng được tôn trọng.”","“Quá khen, Phu nhân. Ta không tránh được, giết chóc. Ta đã giết, rất nhiều. Phu nhân, cái tên này… Bà có biết, ta có nó, thế nào không?”","“Những người theo ông coi ông là một chiến binh thực thụ, chiến đấu vì Ursus. Ông chống lại bất công, nô lệ, đổ máu và áp bức vì tương lai của Ursus. Ông có đồng ý không?”","Patriot lắc đầu.","“Dù chiến tranh, là cần thiết, danh hiệu ấy, là phiền phức. Vì nhiều người, chúng ta gây chiến. Nhưng chiến tranh, là giết người. Chiến tranh kết thúc. Nếu nó, thật sự, kết thúc. Chúng ta nên, chết hết.”","“Nhưng chiến tranh không bao giờ kết thúc.”","“Nhưng ta sẽ chết. Nhưng cái chết của ta, ta muốn, có ý nghĩa. Ta muốn thấy, cho Ursus, cho người Infected, một tương lai khác.” Ông nhìn Kal’tsit. “Ta đã hỏi, nhiều lần, người của ta, Kazdel. Bà và, Bệ hạ, đã làm việc cùng nhau, nhiều năm. Bệ hạ tin bà. Nên ta, cũng tin bà. Bà dẫn, Rhodes Island, đến đây. Không vì máu.” Giọng ông lạnh đi. “…Nhưng chúng, hai kẻ đó. Chúng mang mùi, con gái ta. Cái chết của nó.”","“——!” Kal’tsit sững lại.","“Tôi? Và… Amiya…” Doctor nói.","“Ông Patriot…” Amiya bước lên.","“FrostNova đã chết để thử thách chúng tôi—”","“Không. Đủ rồi.”","“Ông muốn báo thù Rhodes Island sao, Patriot?” Kal’tsit hỏi.","“Không, Phu nhân. Không phải báo thù. Sao phải báo thù, vì những việc, nó làm? Đó là, con đường của nó. Nó chọn. Dù nó, kết thúc ở đâu.”","“Con gái ông đã dốc hết sức chiến đấu với chúng tôi!” Doctor nói. “Và cô ấy cũng đã công nhận chúng tôi.”","“Im lặng.”","“…Gì cơ?”","“Nó còn, quá trẻ. Chỉ biết, tin mù quáng,” Patriot nói. “Sự thật, chúng ta tin, cuối cùng, cũng lộ ra. Chỉ là vài, con sói, đội lốt cừu.”","“Ông Patriot! Chị FrostNova đã cho đi mạng sống, Arts của chị ấy… tất cả…” Amiya nói. “Chị FrostNova đã buông bỏ mọi thứ chỉ để chứng minh bản thân, cơn giận, lý tưởng của chị ấy… Cuộc đời chị ấy có ý nghĩa!”","“Đủ rồi. Không phải chỗ, của ngươi, nói điều này.”","<i>(Amiya, đừng. Đừng nói nữa,)</i> Kal’tsit thì thầm.","“Các ngươi, biết gì?” Patriot nói. “Nếu con gái ta, không phải, sắp chết… Giết các ngươi, dễ như, cắt lúa, bằng liềm. Những gì các ngươi, chịu đựng, ta không quan tâm. Nó chẳng, nghĩa lý gì. Nó chẳng, chứng minh gì.”","“Talulah đang lái lõi đô thị đâm vào Lungmen!” Doctor nói.","“Và cô ta, tuyên bố nó, là lãnh thổ Ursus?”","“Ông biết rồi sao?!”","“Patriot… sao… vậy tại sao…?” Amiya lắp bắp.","“Kẻ giật dây, có nhiều công cụ. Những kẻ giật dây, nghĩ giống nhau,” Patriot nói. “Nhưng ta không thể, để các ngươi qua. Reunion, không thể, tự hủy diệt. Ta sẽ không, phản bội nữa. Nếu không họ, những người Infected, cuộc đấu tranh, đều vô nghĩa. Họ chết. Dù Talulah, đã điên… Làm sao ta nói, với người Infected, thủ lĩnh của họ, đã điên? Là kẻ phản bội? Làm sao ta nói, cô ta giờ sai, nhưng từng đúng? Làm sao ta nói, người các ngươi theo, giờ phải chết? Ta sẽ không để, Reunion, thành ‘người Infected, nội chiến, rồi chẳng còn gì’. Ta không cho phép.”","“Nhưng Reunion sẽ không tự đứng vững được. Hơn nữa, Talulah đã ngấm ngầm phá hủy Reunion từ bên trong,” Kal’tsit nói.","“Bà nói đúng, Phu nhân Kal’tsit. Và vì vậy, bà ở đây. Ta đã chuẩn bị, đối mặt, nhiều loại kẻ thù. Nhưng ta không, ngờ, cuối cùng, phải đánh với người Infected.”","“…Đây thật sự là lựa chọn của ông sao? Buldrokkas’tee… Ông không cần phải chết.”","“Lựa chọn? Ta chỉ có, một lựa chọn. Giết các ngươi.”","“Patriot, chúng ta không cần vứt bỏ thêm mạng sống nào nữa!” Amiya kêu lên. “Chuyện này không giống với chị FrostNova! Dù ai thắng, trận này cũng chỉ có lợi cho kẻ thù!”","“Sai. Cautus, đây, là chiến tranh. Ngươi muốn ta, dừng lại. Tại sao, ta phải dừng?” Patriot nói. “Ta đã đánh quá, nhiều cuộc chiến. Là Wendigo, của Ursus… Lũ man rợ. Lũ lột da, tách thịt khỏi xương, bầy đàn hung tợn, chúng ta quét sạch. Quái vật. Tay chân vặn vẹo, hôi thối, mắt hàng trăm. Ngón tay, hàng nghìn. Chúng ta tàn sát. Chiến binh. Victoria, với giáp hơi nước. Kazimierz, với Pegasi Thương bạc. Laterano, với Hiệp sĩ Súng Tông đồ. Tất cả, chúng ta đánh bại, hoàn toàn. Nhưng chúng ta không thể, đánh bại chính mình. Không thể đánh bại, lòng tham của Đế quốc. Không thể đánh bại, cái chết của người mình. Chúng ta, những Wendigo, là người Sarkaz, gần cái chết, nhất.”","“Các ngươi vấy, cái chết của con gái ta. Trên thế giới này, có những số phận, tệ hơn cái chết. Tại sao ta phải dừng? Ai dám, thử thách ta? Đức hạnh của ta? Họ gọi ta, chính nghĩa. Ta có nên, chấp nhận? Số phận nghĩ ta yếu. Ta có cam chịu? Họ gọi ta mạnh. Ta có nên gánh? Kẻ phản bội, kẻ nổi loạn, đồ tể, người bảo hộ… Tất cả, giống như ‘Patriot’. Trên chiến trường, chúng chẳng là gì, ngoài những mảnh vụn.”","“Rhodes Island… Các ngươi giết nó. Ta giết các ngươi. Không phải, báo thù. Ta không có lòng, báo thù. Con gái ta chỉ, đã từ bỏ cuộc chiến.”","“Không phải như vậy, thưa ông,” Doctor nói.","“Nếu không, thì sao? Nó đã cho đi mạng sống, mà các ngươi vẫn sống?!” Patriot gầm lên. “Ta, sẽ không, từ bỏ. Ta chỉ biết, những gì ta thấy. Ta chỉ biết, những gì ta nắm giữ. Ta không đánh các ngươi, vì con gái ta. …Nhưng ta căm ghét số phận. Ta sẽ chặt nó, nghiền nó, tán nó thành bụi. Nếu số phận, để các ngươi, khiến ta quay đầu. Ta thà, không bao giờ quay, lại.”","“…Đội trưởng! Ngài thật sự định…?” một hộ vệ khiên hỏi.","“Ai nghĩ ta, mất danh dự. Đứng ra, thách đấu ta. Nhưng nếu các ngươi, quý mạng sống… Chúng ta chia tay, ở đây. Ta không muốn, các ngươi, chết ngu. Ta đã thắng nhiều lần. Ta biết điều này, quá rõ.”","“Ông không thể…” Amiya thì thào.","“Buldrokkas’tee, đừng ngốc thế, ông có thể sống tiếp,” Kal’tsit nói.","“Phu nhân, bà cũng, đã nếm mất mát. Vậy bà, có thể, đứng nhìn không?”","“—Ông—”","“Máu ta, không còn, phụng sự bà ấy. Phải. Quê hương ta… là Ursus. Nhưng khi bà ấy, chết. Chúng ta nghe thấy… tiếng thở dài, dài, rất dài ấy.”","Kal’tsit im lặng một lúc. “…Vậy ra ông cảm nhận được… Đó là khoảnh khắc nhịp đập mang theo Arts của bà ấy lan qua cơ thể của mọi người Sarkaz trên thế giới. Chỉ một khoảnh khắc. Nhưng ông cảm nhận được. Nghĩa là dòng máu của ông… đủ cổ xưa.”","“Cổ xưa đến mức, ta chỉ còn một mình. Ta không nghĩ, sinh ra ở Kazdel, chưa từng nhiễm bệnh… Rồi, già rồi, ta nếm, Oripathy. Như thế có đúng không? Chúng ta đều biết, Phu nhân. Chúng ta đều biết. Mọi chuyện trên đời, không xảy ra, vì chúng, đúng. Thực ra, phần lớn mọi chuyện, đều là sai lầm, lặp lại. Người của ta nói, ta có thể sửa chúng. Thực ra, chúng quá nhiều. Không còn, đường lui.” Ông nhìn bà. “Đến hôm nay bà chiến đấu, vì những gì, bà đã mất sao, Phu nhân? Ta nghĩ, không. Ta nghĩ, bà đã mất, và bà không chịu, mất thêm.”","Kal’tsit không trả lời.","“Con gái ta, đã mất. —Ta không chiến đấu, vì cái chết của nó. Ta chiến đấu, vì người sống, vì mọi người Infected, đến cùng. Reunion, không được thất bại. Reunion phải, giải phóng. Mọi người Infected.”","","<i>Cùng lúc ấy, ở khu kho.</i>","“Ngươi đang đưa tin cho lão và người của lão à?” tên lính đánh thuê Sarkaz hỏi. “Ngươi định nói gì với lão?”","“…Các ngươi định gài bẫy đội du kích,” Guard nói, máu chảy từ khóe miệng. “Các ngươi… định kích động người Infected Ursus chống lại họ, để giết họ. Các ngươi biết họ sẽ không động tay vào dân thường.”","“Hận thù là vũ khí mạnh nhất. Nó giết người.”","“Nhưng ông ấy sẽ không chết. Ông ấy là Patriot… ông ấy là tất cả những huyền thoại vĩ đại nhất gộp lại trong một người. Tôi đã thấy giáp của ông ấy. Tôi đã thấy ông ấy vung vũ khí. Ông ấy không thể chết! Ông ấy và người của ông ấy là những chiến binh mạnh nhất Reunion! Các ngươi muốn giết người Infected. Lũ quỷ các ngươi chưa bao giờ quan tâm đến sự sống, nhưng ông ấy thì có! Ông ấy là người Ursus… là Sarkaz, và là người Infected! Nhưng không điều nào trong số đó đẩy ông ấy làm điều sai! Ông ấy không chỉ là người Ursus, không chỉ là Sarkaz, không chỉ là người Infected. Ông ấy là Patriot, chỉ là Patriot. Ông ấy sẽ đánh bại các ngươi, chặn đòn của các ngươi, nhổ vào lời lăng mạ của các ngươi, tập hợp lại người Infected, và gột rửa hận thù của họ… Ông ấy là Patriot, và ông ấy sẽ không chết. Còn các ngươi chỉ là lũ giòi bọ, nhảy múa trên dây của những kẻ mưu mô ghê tởm đang giật dây vở kịch này.”","Tên Sarkaz im lặng một lúc.","“Ngươi nói thế vì ngươi biết mình sắp chết. Và ngươi nói đúng. Patriot rất cứng. Nhưng ngươi thì không. Ngươi sẽ chết.”","","“Vậy các ngươi, sẽ không qua được. Ta không cho phép,” Patriot nói. “Muốn đi qua, khu trung tâm, các ngươi phải, giết ta. Nếu không, du kích của ta, sẽ săn đuổi. Và ta, sẽ ở đây, bóp cổ các ngươi, đến chết. Chỉ khi, các ngươi giết ta, giá trị của các ngươi, mới được biết. Nếu không, các ngươi chỉ là, kẻ xâm nhập. Tất nhiên, ta không tin, các ngươi có, giá trị gì. Ta không biết, làm sao các ngươi, chống lại được, phép phù thủy của người ta. Nhưng các ngươi sẽ không, sống sót qua, chiến thuật Ursus.”","“Ông ghét chúng tôi đến thế sao?”","“Ta không ghét, ai cả. Ta chỉ không, tin các ngươi. Ta không thể, tin. Ngay cả bà, thưa Ngài. Bà mang…”","“Ông sẽ không chấp nhận chúng ta,” Kal’tsit nói.","“Ta không tin, sự trùng hợp. Chiến tranh. Chiến tranh, không quan tâm. Không quan tâm đúng, hay sai. Nó không, quan tâm, kẻ khổ đau, kẻ bị áp bức, hay kẻ bị nô dịch. Ngoài chiến trường, họ tồn tại. Trên chiến trường, không. Các ngươi phải chuẩn bị, cho chiến trường. Kẻ nào chết, là kẻ sai.”","“Em không… em không hiểu nổi chú ấy…!” Rosmontis nói.","“Ông ta nói gì vậy… sao chúng ta phải đánh nhau?” một operator lẩm bẩm.","“Chiến đấu, hoặc bị nghiền nát. Kháng cự, và bị nghiền nát,” Patriot nói. “Trừ khi, các ngươi đánh bại, ta. Nếu số phận, đứng về phía ta, ta giết các ngươi. Rồi ta, sẽ giết nó. Để nó không thể, chế giễu ai, nữa. Nếu số phận, đứng về phía các ngươi. Ta chỉ có thể, tiến lên. Tiến bước.”","“Tất cả operator, lùi lại ngay!” Kal’tsit hô.","“Ta bước tới.”","“Mục tiêu của chúng ta là chỉ huy Infected của Reunion, mật danh ‘Patriot’,” Kal’tsit nói nhanh. “Bộ giáp, sức mạnh, vóc dáng của ông ta vượt xa mọi thứ các người có thể mong đợi ở một chiến binh. Originium có lẽ đã thay thế nhiều chức năng sinh lý của ông ta. Originium ở chỗ từng là thanh quản… là sản phẩm của tốc độ kết tinh cao trong cơ thể ông ta. Ta có lý do để tin rằng một vết thương bình thường gây tử vong sẽ không gây tổn hại đáng kể cho ông ta, vì Originium sẽ mọc ra thay thế mô bị tổn thương! Wendigo vốn có khả năng trao đổi chất và hồi phục cực cao. Nhưng dù ông ta bền bỉ đến đâu, chúng ta phải giết ông ta. Chỉ khi giết ông ta, chúng ta mới qua được khu trung tâm, đến được đài chỉ huy, và ngăn kẻ thù lợi dụng Reunion! Hộ vệ của ông ta đang bối rối vì hành động của ông ta. Đây là cơ hội cuối cùng.”","“Bác sĩ Kal’tsit…”","“Sao lại thành ra thế này?” Doctor hỏi.","“…Chúng ta chỉ là một ngã rẽ trên con đường của ông ta. Mọi thứ chúng ta xây dựng chẳng có ý nghĩa gì với ông ta,” Kal’tsit nói. “Nói thẳng ra, ông ta đang coi thường chúng ta. Ngay cả Hoàng đế Ursus cũng không bắt được ông ta cúi đầu, huống chi là ta. Chúng ta sẽ phải dùng cái chết của ông ta… để mở mắt ông ta, khiến ông ta thấy tất cả những gì chúng ta đã làm, và nhận ra chúng ta mạnh hơn ông ta. Nhưng không đời nào ông ta tự… thay đổi. Mọi thứ khác, mọi thứ ngài trân trọng, quá mong manh với ông ta. Chúng không chịu nổi sức nặng của ông ta. Hellagur của Azazel đã đánh giá sai tính cách người Sarkaz này. Dù Buldrokkas’tee cao thượng đến đâu, dù ông ta gánh bao nhiêu trên vai, trước hết và trên hết, ông ta là một chiến binh bất khuất. FrostNova tin ngài, nên cô ấy trao cho ngài chút sự sống cuối cùng… Nhưng Patriot thì không. Ông ta không tin ai. Ông ta chỉ tin chính mình.” Bà thì thầm: <i>(…Ít nhất là bề ngoài.)</i> “Chuẩn bị chiến đấu. Giờ mọi thứ chỉ còn trông vào chiến đấu. —Chỉ chiến tranh mới giết được ông ta.”","“Lựa chọn sáng suốt, thưa Ngài,” Patriot nói. “Du kích, tập hợp. Các ngươi chỉ còn, vài phút. Ta không nói, thêm nữa. Ta không cần, thấu hiểu. Ta chỉ, thắng chiến tranh.”","Vượt ngoài mọi sự thấu hiểu, chiến binh khủng khiếp như quái vật đứng sừng sững trước mặt Doctor.","Nhưng Doctor nhớ ra, còn một chiến binh như quái vật khác, kẻ thấu hiểu mọi thứ, đang đứng ngay bên cạnh…","Amiya nắm chặt tay Doctor.","“Rhodes Island, ta tiến bước.”","","“Mon3tr, giữ lại!” Kal’tsit hô. “Lính bắn tỉa, tập trung hỏa lực vào thân. Giáp của ông ta đã hư hại nặng. Caster, kiềm chế những chiến binh du kích khác. Đừng để họ can thiệp. Lùi lại, Mon3tr. Cận chiến ngươi không có lợi thế! Giờ ngươi không cản nổi ông ta!”","“Thanh kiếm đang trượt! Dù… em cố giữ ông ấy, em cũng không đẩy ông ấy được. Cảm giác như một trận lở đất…” Rosmontis rên lên.","“Dồn năng lượng thành một tia… dồn… dồn nữa… rồi nhắm vào tim ông ta!” Kal’tsit nói. “Bắn! Ngay!”","Một tia sáng xuyên qua lồng ngực người khổng lồ. Patriot loạng choạng. Rồi đứng thẳng lại.","“Ngay cả thế cũng không đủ để hạ ông ta…”","“Sao ông ta dai dẳng đến vậy…?!” Doctor thốt lên.","“‘Mỗi trận chiến đều là đến chết. Đặt sinh mạng vào mỗi trận chiến, vì sinh mạng sẽ trở về với máu, và sống mãi trong một cơ thể khác…’” Kal’tsit đọc khẽ. “Tiên phong, giữ áp lực… lùi lại. Chính cơ thể ông ta sẽ giải phóng nghi lễ ‘ăn thịt đồng loại’, như thể bản thân ông ta là một thiết bị phù thủy khổng lồ… Buldrokkas’tee, có rất nhiều người Sarkaz không muốn thấy một Wendigo như ông hy sinh vô ích.”","“Không. Sao ta, có thể bị hy sinh? Ta vẫn còn, cử động được. Ta vẫn còn, giết được các ngươi. Cơ thể ta, vẫn nghe, lệnh ta. Ta chưa cảm thấy, nỗi đau… khốn khổ, và hối hận. Đủ chưa? Đã đủ chưa? Đủ chưa?”","“Ông Buldrokkas’tee… làm ơn, dừng lại… dừng lại đi!” Amiya kêu. “Chiến đấu thêm chỉ khiến ông đau đớn hơn thôi!”","“Chiến binh. Một chiến binh, phải mang theo, tất cả người chết. Ta mang, nỗi đau, hận thù, sự im lặng của họ. Nếu ta, dừng lại… họ chết vô ích. Đau đớn? Các ngươi mới, phải đau đớn. Các ngươi không thể, đánh bại ta.”","Amiya rên lên, Arts của cô bé chạm vào ông. Và những ký ức tràn vào.","@bg:bg_chercen_2","<i>“Đừng buồn, anh yêu… Anh sẽ không tái hôn sao? Đừng như vậy mà… Haizz, nhưng anh sẽ chẳng nghe em lải nhải đâu. Anh cứng đầu như đá. Em đã bao giờ thuyết phục được anh điều gì chưa? Anh sẽ tiếp tục chiến đấu, phải không? Hứa với em đi, Buldrokkas’tee, hứa với em là anh sẽ không chết trên chiến trường.”</i>","<i>“Em chỉ mong anh đừng phải đau khổ thêm nữa. Hãy nghĩ xem, sau khi em đi, anh vẫn còn gia đình mình. Nhìn này, bé Gro của chúng ta. Nó ngủ dễ thương quá. Với hai cái sừng đỏ nhỏ xíu, vẫn còn chưa cứng… Đây là sự sống. Là sự tiếp nối sự sống của em. Em biết anh sẽ không ăn em. Em biết anh ghét những truyền thống của Wendigo thế nào. Nhưng em ước biết bao được chảy mãi trong sự sống của anh. Mà sự sống… vốn bất tử.”</i>","<i>“Không, Buldrokkas’tee. Anh không phải con quái vật máu lạnh. Tình yêu của anh dành cho em là thật. Ngay cả một người phụ nữ ghét đời như em cũng đã đáp lại được tình yêu của anh. Buldrokkas’tee, anh yêu… gia đình anh sẽ có, cũng là gia đình em. Đó là cách em yêu anh.”</i>","“Helen, ta không xứng, với tình yêu của em,” Patriot thì thầm. “Ta không bảo vệ được em. Ta không thể, giữ lời. Gia đình ta, ta không bảo vệ được… ai cả. Ta không xứng… được yêu. Ta thất hứa, nhưng ta sống. Và vì vậy lời hứa, vẫn còn. Vì lời hứa, mang hận thù, và hối tiếc.” Ông nhìn Rosmontis. “Không chỉ, người chết. Mèo con, nó ở đâu? Hận thù của ngươi? Hối tiếc của ngươi? Ngươi, mang nó, khi ngươi đi. Người dân, của thành phố này. Người Infected Ursus. Thế giới. Những người mất, cha mẹ. Những người có cha mẹ, làm điều sai. Họ đều được mang theo.”","@bg:bg_indoor_u","<i>“Cha, con xin cha! Đừng đứng về phía Đế quốc! Lệnh? Lệnh của Đế quốc thật lố bịch! Không, con xin lỗi, Cha… Con không chế giễu cha. Con không bao giờ dám. Nhưng chiếu chỉ của hoàng đế là một trò đùa tàn nhẫn với tất cả chúng ta. Bạn con, Hector, bị đánh roi đến chết trên cầu, chỉ vì họ phát hiện cậu ấy mắc Oripathy! Chẳng phải cha cũng thích thơ của cậu ấy sao? Chẳng phải cha từng đọc to chúng vào ban đêm và rơi nước mắt vì vui sướng sao? Cậu ấy chết rồi! Cậu ấy là một nhà thơ. Chỉ chữ nghĩa mới có quyền đưa cậu ấy đến cái chết!”</i>","<i>“Cha sinh ra ở Kazdel, lớn lên cùng những người Sarkaz Infected… Con biết cha hiểu được người Infected Ursus! Sao cha lại thờ ơ như vậy? Tim cha cũng làm bằng sắt sao? Hay vì cha, một Sarkaz chưa nhiễm bệnh, không có lòng thương xót? Có lẽ khi một người trong chúng ta nhiễm bệnh, cha mới biết những tội ác này lố bịch đến thế nào! Được thôi, được thôi, Cha…! Cha là Buldrokkas’tee độc nhất vô nhị! Nếu Oripathy không ám được một người lính cứng cỏi như cha, thì nó sẽ phải bò đến con vậy! Khi nó lơ lửng trên xác con mà cười nhạo cha, cha sẽ nhận ra sai lầm của mình! Đừng để bản thân phải hối hận, Cha!”</i>","“…Grrovae’zeeal, con vô tội. Vô tội đến thế,” Patriot nói. “Người Infected, là ta. Ta đã giấu, con. Cha, đến cuối cùng, có mắt, mà mù. Cha không thể đi, con đường đúng. Ta… hối hận. Ta thật sự, hối hận. Con trai ta… Cha đã giết con. Cha đã để con, chết vô ích. Cha… không xứng, làm cha con. Nếu ta ngừng chiến đấu, ta phản bội họ.”","“Nhiều quá… em thấy… càng lúc càng nhiều…” Amiya thì thào. “Ông Patriot… Ông có nhiều hối hận đến thế… Ông chưa từng nói ra sao? Chưa từng tâm sự với ai sao?”","“Ta chỉ có thể gánh, những hối hận của mình.”","“Mon3tr, lùi khỏi ông ta!” Kal’tsit hô.","“Ta từng nghĩ, tại sao, Đức Vua, như bà ấy, lại kết thúc như thế?” Patriot nói. “Bà sẽ không trả lời. Cái chết của Bệ hạ, đến nay, vẫn là bí ẩn. Nhưng ta biết, bà ấy không bao giờ chạy trốn. Từ đầu đến cuối, bà ấy chỉ mỉm cười. Nếu ta ngừng chiến đấu, mọi sự kháng cự, đều vô nghĩa. Nếu ta ngừng chiến đấu, là ta bỏ chạy. Ta không thể dừng.”","@bg:bg_chercen_2","<i>“Mình đâu có họ hàng gì? Gọi chú là bố thì kỳ lắm. …Trông chú không ổn lắm? Không đời nào! Đâu phải vì… các anh chị em sợ con! Này, chú có cách gì không? Làm sao để họ thôi trốn con vì chú? Nếu có, con sẽ gọi chú là bố luôn!”</i>","<i>“Hả?! Sao tự nhiên chú ôm con? Chú sẽ bị đông cứng đấy! …Chú đang khóc à? Con thấy có gì nhỏ xuống vai con… Không à? Mọi người bảo chú không có máu, cũng không có nước mắt. Nghĩa là chú không khóc à? Nhưng bố chắc chắn đang khóc mà, bố ơi… Con không biết con vừa nói gì! Con xin lỗi! Bố ơi, bố khóc vì bị lạnh đau lắm hả? Bố ơi! Bố ơi! Con sẽ không nói thế nữa! Và, và khi con lớn… con sẽ làm thuốc cho bố để bố không bị đông cứng nữa! Thế thì bố sẽ không khóc nữa, đúng không? Con sẽ lớn thật nhanh!”</i>","<i>“Gia đình ạ? À, ý bố là các anh chị em, con, và bố, tất cả là một gia đình? Cả anh trai con không ở đây nữa? Ừm… vậy thì, bố là bố của tất cả mọi người! Vậy con sẽ học theo bố, và báo thù cho bà! Con sẽ giết hết lũ người xấu bắt nạt chúng ta! Con không được nói thế à? Tại sao?! Ngày nào bố cũng giết người xấu mà! …Bố không muốn con giống bố là sao? Bố không phải người tốt à? Sao bố con lại là người xấu được?! Vô lý quá! Nói đi! Bố là người xấu kiểu gì?! Con ghét bố!”</i>","<i>“Nếu con không được giống bố, con được vào thành phố không? Ừm… Bố ơi… mình thật sự vào thành phố được ạ? Mấy cái kẹo ngón tay bố kể… có ngon thật không? Vậy nếu con giống bố thì con không được ăn à…? Ồ…! Con không hiểu. Bố ơi…? Con nghĩ, không quan trọng, con có thể là người tốt hay người xấu. Miễn là con được ở bên bố, và các anh chị em… mãi mãi. Bố là gia đình của con, con biết mà. Người thân nhất của con. Tất nhiên, người thứ hai là… người thứ ba là…”</i>","“Yelena… Yelena… Con gái ta,” Patriot thì thầm. “Con gái ta… Cha không thể, làm gì, cho con. Cha không thể, làm gì cả. Ta nợ con, quá nhiều. Quá nhiều.”","“Quá nhiều, quá nhiều…” Amiya lặp lại.","“Cô bé Cautus. Ngươi là, người lãnh đạo Rhodes Island,” Patriot nói. “Ngươi có gì, đặc biệt? Một người của ngươi, đã kể với ta về ngươi. Chiến binh của ngươi, rất xuất sắc. Nhưng chỉ xuất sắc, họ vẫn chết. Nó ở đâu? Cho ta thấy, giá trị của ngươi. Ngươi muốn dừng, lõi đô thị. Nhưng ngươi không thể, đánh bại ta?”","“Không được chạm vào Amiya!” Rosmontis hét lên. “Một, hai, ba… bốn!”","<i>Khiên, vỡ nát.</i>","<i>Giáo, gãy đôi.</i>","Con quái vật khổng lồ không hề nao núng. Ông tiếp tục tiến lên.","“Hừ. Ngươi có thể, xuyên giáp ta. Bộ giáp này, cuối cùng, đã đến giới hạn,” Patriot nói. “Mèo con, ngươi mạnh. Một mối đe dọa, với ta.”","“Khoan đã, ông Patriot,” Amiya nói.","“Chỉ mười, bước nữa. Không cần đợi.”","“Ông đã đến giới hạn rồi, em biết. Vì ông không phải caster như chị FrostNova… Thế này là đủ rồi. Em đã thấy tất cả… trong những Arts này. Tất cả về ông.” Amiya giơ tay lên. “…Đủ rồi, ông Patriot.”","<i>Đủ rồi.</i>","Một luồng sáng đen đánh trúng ông.","“Cái gì… thế này? Đòn này, thật chính xác. Ta không thể, cử động, nữa.”","“…Những vết thương cuối cùng cũng đuổi kịp ông ta,” Kal’tsit nói. “Buldrokkas’tee…”","<i>(Ta định, tiêu diệt các ngươi, rồi đội du kích, nhân danh các ngươi, giết Talulah,)</i> giọng Patriot vang lên khe khẽ, chỉ đủ cho họ nghe. <i>(Giờ, không cần nữa. Các ngươi đã giành, quyền, giết, Talulah. Sao ta có thể, để người Infected, bị nô dịch, bị lợi dụng? Mạng sống của ta, lấy đi. Dùng nó. Đó là phần thưởng, của kẻ chiến thắng.)</i>","“Các ngươi, đã thắng,” Patriot nói. “Phu nhân. Xin bà. Hãy cầm lấy.”","“—Đây là gì?”","“Chìa khóa, để dừng, Chernobog. Nếu các ngươi lên, đài chỉ huy… các ngươi cần nó.”","“Ông Patriot, ông… chỉ để…” Amiya nghẹn lời.","“Không. Ta đã, thật sự, định giết các ngươi. Nhưng giờ, các ngươi đánh bại ta. Các ngươi xứng đáng.”","“Sao ông phải làm đến mức này?” Doctor hỏi.","“Vì ta không tin các ngươi. Ta chỉ tin, chiến tranh. Con gái ta, ngây thơ. Nó mềm lòng, nó đã giả định, một kết quả. Ta thì không. Ta chờ kết quả. Và đây… là kết quả… tốt nhất. Người của ta, bất ngờ, đã không dùng, sức mạnh của mình. Họ sống. Chỉ mình ta… sẽ chết. Một cái chết xứng đáng.”","@bg:bg_snow_2","<i>Rhodes Island, đơn vị xử lý sinh học.</i>","“…Chuyện gì xảy ra vậy?!” một operator kêu. “Closure, tôi cần sơ đồ Đơn vị Xử lý Sinh học số Mười ba! Nhiệt độ cabin đang tăng nhanh! Rò rỉ năng lượng! Khoan, nó đang biến đổi hình dạng! Sao sau mười bốn tiếng mà nó vẫn tiến triển thế này? PRTS, ai vào cabin này cuối cùng? Doctor? Chúng ta mất ai trong trận Lungmen sao? Ai đang được xử lý? …Cái gì? Khoan, chậm lại. Cậu nói Doctor đặt ai vào đó?”","@bg:bg_chercen_2","“Phu nhân!”","“Ta đang nghe, Buldrokkas’tee.”","“Những Wendigo, tự lưu đày, mất tất cả. Nhưng chúng ta mang, truyền thống Sarkaz. Tổ tiên, đã nhào nặn ta, nuôi dưỡng ta, dõi theo ta. Giờ, hãy làm chứng.”","“Buldrokkas’tee… Ta không biết ta có đủ tư cách không.”","“Ta nghĩ bà, là lựa chọn, tốt nhất.”","Kal’tsit im lặng một lúc, rồi cất giọng trang nghiêm.","“‘…Ta xin làm chứng cho một người Sarkaz. Buldrokkas’tee, Wendigo của Kazdel, không phản bội máu thịt, không làm nhục bộ tộc. Ông rời bỏ thân xác, cùng sinh mạng, dưới ánh sáng… và linh hồn ông trở về với dòng máu ấm của Wendigo.’” Bà ngừng lại. “Đây là một lời nguyền.”","“Với ta, thì không. Ồ… Ta thấy… ta thấy… Mắt ta, bắt đầu mờ đi. Cảm ơn bà, Phu nhân.”","“Ta tưởng ông ghét những thứ này.”","“Nhưng ta, già rồi.”","","<i>Ở một góc khác của lõi đô thị.</i>","Những nỏ thủ U linh bị dồn vào chân tường, trước mặt là đám chiến binh Sarkaz.","“Không… Đây là đâu?” một nỏ thủ nói. “Ha. Ra là vậy. Ha. Talulah thật sự đã phản bội chúng ta. Các ngươi nghĩ chúng ta sẽ đứng yên cho các ngươi giết sao?!”","“Các ngươi không đánh được. Nếu có kiếp sau, hãy báo thù ở đó.”","“Đừng giết họ.”","Mephisto bước ra, gầy guộc, đôi mắt trống rỗng.","“Mephisto…?”","“Thả họ đi. Lũ quỷ, ta sẽ cho các ngươi những cơ thể không biết đau. Thả họ đi. Ta sẽ chia sẻ sự sống của ta với các ngươi. Và các ngươi sẽ thật sự chiến đấu mãi mãi, một cuộc chiến không mệt mỏi.”","“…Được,” tên Sarkaz nói. “Nhưng nếu thả họ, người của ta phải theo dõi họ. Bọn ta không định trái lệnh Talulah lúc này. Các ngươi, nỏ thủ. Đi đi.”","“Mephisto?!” <i>(Sao hắn lại cứu chúng ta…? Đây là một phần âm mưu của Talulah sao?)</i>","“Nhưng sao ngươi đến đây?” tên Sarkaz hỏi.","“…Vì ta muốn vào trong đó. Ta muốn biết có bí mật gì. Ta muốn biết vì sao Rhodes Island đưa một người ra khỏi đây. Vì ta thấy trong nhật ký có người đã ra khỏi đây.”","“Mephisto…? Tại sao?”","“Các ngươi có muốn nghe một bài hát không?”","“Nhưng Đội trưởng Faust nói… Anh ấy nói…”","“Phải, phải. Ta không hát được nữa. À, nhưng ta có thể thử. Nó phải là một bài hát ru, phải không? Ta không nhớ ai đã dạy nó cho ta… Ta quên rồi. Chỉ là, có ai đó trong giấc mơ của ta từng ngân nga nó.”","<i>Ngủ đi, ngủ đi♪</i>","<i>Búp bê nhím và gấu con…</i>","","“Người Infected, Ursus, họ sẽ, đi đâu?” Patriot thì thầm. “Đêm tối, giấu… bao nhiêu vì sao?”","“…Đội trưởng, Đội trưởng!” Một hộ vệ khiên quỳ xuống bên ông.","“Mệnh lệnh cuối cùng. Chiến đấu tiếp. Sống tiếp. Chỉ các ngươi, mới đi… con đường của chính mình. Muốn có đường, các ngươi phải đi. Ta sẽ chết. Nhưng ta không biết, ta có nên chết, lúc này không. Cái chết của ta, có thể thay đổi, điều gì? Có lẽ các ngươi, sẽ cho ta biết, câu trả lời.”","<i>Chìm vào bóng tối tĩnh lặng…</i>","<i>Anh chị em, già và trẻ. Giấc mơ, ôi giấc mơ, bao bọc lấy thân họ…♪</i>","@bg:bg_perimeter","<i>Lungmen. Trước cổng Trụ sở L.G.D.</i>","“Tiểu thư? Cô khóc nhè gì thế…?” Hoshiguma hỏi.","“Tôi không khóc nhè!” Swire quát.","“Được, được. Nhưng cô đang đứng ngay trước cổng Trụ sở L.G.D. Chắc không muốn người khác thấy cô khóc đâu nhỉ? Thế này đi. Tôi ngồi trên bậc thềm trước mặt cô. Tôi to con mà. Có tôi chắn, không ai thấy cô khóc đâu.” Hoshiguma ngồi xuống. “À. Chúng ta làm hỏng chuyện, nên thấy tệ, phải không? Ý tôi là cả hai chúng ta, tiểu thư. Cả hai đều thất bại, đúng không?”","“Tôi quan tâm gì chứ…? Tôi chẳng quan tâm cô ta đi đâu!”","“Ừm, phải. Tôi biết.”","Swire đấm vào lưng cô.","“Này, đừng đánh. Dù tôi nói gì cô cũng sẽ đánh tôi đúng không?”","@bg:bg_chercen_2","“Cuối cùng…” Patriot thì thầm. “Cuộc đời… ta… có thể kết thúc. Helen… Grrovae’zeeal… Yelena… Là các người… Cuối cùng ta… được về nhà…”","<i>Không.</i>","<i>—Không.</i>","“…Không,” Patriot nói. “Ảo ảnh. Sao… ta không cần ảo ảnh, không cần, an ủi! Ai…? Ai cho ta thấy… ảo ảnh?!”","“Ơ… Sao…? Sao ông Patriot… thoát ra được?” Amiya lùi lại.","“Giờ, ta hiểu rồi. —Ngươi. Cautus. Là ngươi,” Patriot nói. “Ngươi, là… người kế vị của bà ấy. Theresis, đã nói dối. Đức Vua… có… người kế vị. Ngươi là… Chúa tể của Quỷ.”","“A…!” Kal’tsit thốt lên.","“Chết, dưới tay, của… Vua Sarkaz. Ta… sao lại thế? Cuối cùng, ta vẫn không thể, thoát khỏi số phận. Không. Không… Không.”","“Amiya?! Em không thể…?!” Kal’tsit kêu.","“X-xin lỗi! N-nhưng bác sĩ Kal’tsit…”","“Ta từng nghe, ngày xưa, Chúa tể Sarkaz, ban cho ảo ảnh an ủi, như ân huệ,” Patriot nói. “Những chiến binh của họ, có thể thấy những bức tường thành vĩ đại, hay những người thân yêu đã khuất— Vô số binh sĩ, vì những ảo ảnh ấy, đã chiến đấu không ngừng.”","“Em chỉ, em chỉ… Ông Patriot, em không cố ý… em không muốn…” Amiya nghẹn ngào. “…Kết thúc cuộc đời ông… không nên bi thảm đến thế! Em đã thấy… em đã thấy hai trăm năm cuộc đời ông… Chiến đấu không ngừng… và mất mát nhiều đến thế… ông đã mất tất cả… Em không… em không muốn đó là kết cục của ông!”","“Kết cục, của ta? …Không.”","“Em muốn cho ông… một kết cục tốt hơn…”","“Không!” Patriot gầm lên. “Kết cục của ta, không phải, thứ người khác, ban cho! Ảo ảnh? Không! Đó không phải kết cục của ta! Nếu nó bi thảm, thì nó bi thảm. Nếu ngu ngốc, thì ngu ngốc! Đây là, kết cục của ta. Kết cục… ta xứng đáng. Ta đã sống. Ta đã chiến đấu. Ta đã thất bại. Thế là, đủ.”","“Tại sao? Tại sao…? Sao lại đủ?” Amiya khóc. “Không ai phải mất tất cả như thế này!”","“…Ngươi vẫn còn, là trẻ con.”","“Em không phải trẻ con! Em đã trải qua không biết bao nhiêu trận chiến!”","“…Một cái kết tốt đẹp, không bao giờ, giành được. Chỉ trẻ con, mới tin vào, hạnh phúc mãi mãi về sau. Ngươi, và con gái ta, chỉ là những đứa trẻ, tin vào, truyện cổ tích. Ta đã nói với FrostNova, quá nặng… quá nặng. Ta không đồng ý, với nó. Nó là… một cô bé. Chỉ là đứa trẻ. Oripathy, bọn buôn nô lệ, thế giới của chúng ta… không tha, cả một đứa trẻ. Talulah, đã đưa nó, đến chỗ chết.”","“Vậy sao ông không cùng chúng em chống lại Talulah—”","“Ngươi có thể, cho ta gì? Ngươi còn không thể, cho ta, những gì Talulah, từng cho ta. Sau này, ngươi sẽ, trở thành gì?” Patriot nói. “Đây là số phận. Ta đã nếm, quá nhiều. Ta sẽ không bao giờ, cúi đầu trước số phận. Dù, mỗi lần, số phận đưa ta, đến cùng một… kết cục… Ta thà, vật lộn với nó, cho đến khi, mặt trời lại mọc. Nhưng… có lẽ, ngươi có thể thay đổi. Ta đã chống lại số phận, bao nhiêu năm… cuối cùng, ta không thắng được. Nhưng ngươi… có lẽ ngươi, khác…”","“Ngươi có, đủ phẩm chất, để kế vị Đức Vua không? Ngươi có, sức mạnh, để rời đi, còn sống không? Ngươi có, lòng can đảm, và sự sáng suốt, để bước vào, vùng hoang mạc, vô tận không?”","“Em không thể làm một mình,” Amiya nói. “Nhưng em không một mình.”","“Có lẽ… Mọi thứ… là của ngươi. Chỉ ngươi… mới làm được. Thứ đó… Reunion, bạo chúa, số phận… Ngươi sẽ… lật đổ chúng.”","","<i>Khoan.</i>","<i>Không.</i>","Kal’tsit ngước nhìn bầu trời đang tối sầm lại.","<i>Mình đã thấy cảnh này ở đâu rồi? Không thể nào…</i>","“Amiya… Amiya…?” Kal’tsit thì thầm. “Lời tiên tri Sarkaz sinh ra từ ký ức tập thể của chủng tộc họ. Những đợt bùng phát năng lượng Originium ở những khu có mật độ cao… lõi đô thị đang hứng chịu một Catastrophe. Tế đàn… Amiya… Wendigo… Chúa tể của Quỷ?! Khoan, nếu điều này tác động trực tiếp… Không thể nào! Kẻ cuối cùng của dòng máu Wendigo cổ đại kết nối trực tiếp với toàn bộ chủng tộc Sarkaz?! Lời tiên tri… lời tiên tri này?! Tuyết? Nghi lễ ăn thịt đồng loại của Buldrokkas’tee cộng hưởng với tất cả tế đàn?! Và những gì ta vừa thêm vào… sự hồi sinh của Wendigo…!” Bà quay phắt lại. “Tất cả operator! Bất cứ điều gì ông ấy nói… Bất cứ điều gì Buldrokkas’tee nói…! Không được tin một lời nào!”","Người Wendigo bỗng cất tiếng. Giọng khàn khàn của ông như vang vọng khắp cả khu trung tâm.","<i>Ta thấy những thành phố, hoang tàn.</i>","<i>Ta thấy Originium, phủ kín mặt đất.</i>","<i>Ta thấy ngươi, đầu đội vương miện đen, nung chảy hàng triệu sinh mạng, thành những ký ức.</i>","<i>Ta thấy, Vua của Sarkaz, nô dịch muôn dân, khắp mọi nơi.</i>","“Hả…?!” một hộ vệ khiên thốt lên.","“…Cái… gì?” Patriot run rẩy. “Không thể nào… Không…”","“Patriot! Đừng tin lời tiên tri! Nó chỉ là tác dụng phụ sinh lý của Originium Arts!” Kal’tsit hét lên.","“Nhưng… Nhưng ta biết… mọi lời tiên tri… đều thành sự thật. Và ta đã chết, dưới tay, Vua Sarkaz. …Phu nhân. Không. Phu nhân.”","“Buldrokkas’tee! Chẳng phải cả đời ông đã chống lại số phận sao?!”","“Vua Sarkaz, trẻ tuổi… …Ngươi, ngươi…”","<i>Sẽ là thảm họa khủng khiếp nhất giáng xuống thế giới này.</i>","<i>Nó phải chết!</i>","<i>Nếu không, thế giới sẽ chết!</i>","“Ta không thể, để ngươi sống,” Patriot nói. “Ngươi có thể hận ta.”","Tiếng giáp sắt va vào nhau vang lên. Con quái vật tơi tả bỗng đưa tay về phía Amiya.","“—Amiya!” Kal’tsit hét.","“C-coi chừng!” Rosmontis kêu.","Cô bé Cautus không hề nao núng. Bóng tối của cái chết phủ lên khuôn mặt đen nhẻm khói của cô. Cô không cử động. Không hét lên. Cô chỉ nhìn thẳng vào mắt Patriot.","Như thể nhìn thẳng vào linh hồn ông.","Cùng lúc đó, những lưỡi kiếm đen nặng trịch và những tia năng lượng chói lòa đầy điềm gở xuyên nhanh vào cơ thể bất tử của người khổng lồ. Ông vẫn không lay động.","Ngay khi Patriot sắp bóp nát hộp sọ của cô bé áo đen…","Người Wendigo khựng lại.","Có thứ gì đó dường như đang nhỏ xuống buồn bã từ trong chiếc mũ giáp của ông.","@cg:avg_7_13","@cg:avg_7_14","@cg:avg_7_15","……","Một phút trôi qua.","@cg:avg_7_16","Trong một phút dài như vĩnh cửu ấy, không còn âm thanh nào khác ngoài tiếng gầm trầm của thành phố đang di chuyển.","Rồi, mọi người nhận ra. Con quái vật đứng trước mặt họ đã chết.","@cg:avg_7_17","Chưa từng lùi một bước, chưa từng dao động dù chỉ một giây, cuối cùng, cái chết đã dừng bước tiến cả đời của Patriot."],"bg":"bg_chercen_1","cast":[["Patriot","npc:avg_npc_025_1"],["Kal'tsit","op:char_003_kalts"],["Amiya","op:char_002_amiya"],["Daughter",null],["Son",null],["Wife",null],["Guard","npc:avg_npc_059"],["Mephisto","npc:char_1507_Mephisto_1"]]},{"c":"7-19","t":"Mười một giờ","p":["<i>Lungmen.</i>","“Cô bị thương?!” Swire kêu lên.","“Đừng lo. Chỉ là vết xước thôi,” Hoshiguma nói.","“Thế này mà là vết xước à? Lại đây, tôi có khăn sát trùng. Quay mặt sang đây!” Swire lau vết thương. “…Vết thương sâu, nhưng không rộng lắm. Như thể… có dấu vết của Arts. Ch’en đã làm thế này với cô à? Con mụ chết tiệt đó…”","“Ha… Không sao. Con gái tầm tuổi đó hay làm mấy chuyện như thế.”","“…Hoshiguma, tôi sợ lắm. Tôi sợ cô ta sẽ…”","“Sẽ gia nhập Reunion?”","“Ừ…” Swire cúi đầu. “Hồi nhỏ tôi cũng từng chơi với Talulah. Dù tôi không nhớ rõ lắm, nhưng tôi biết… tôi rất thích làm bạn với chị ấy. Dù chị ấy hống hách và nóng tính, chị ấy luôn bênh vực chúng tôi. Chị ấy chẳng bao giờ nói gì, nhưng cũng chẳng bao giờ lùi bước. Chị ấy luôn là người lao lên đầu tiên, chẳng bao giờ nhờ chúng tôi giúp… Chị ấy đánh cả những đứa lớn hơn mình. Chỉ chị ấy mới kéo được Ch’en ra khỏi những cơn ủ rũ. Tôi sợ là…”","“Cô ấy sẽ không đâu,” Hoshiguma nói. “Ch’en hiếm khi nói đúng điều trong lòng. Nhưng cô ấy sẽ luôn là Ch’en của Lungmen. Dù cô ấy nói gì, mọi giấc mơ, mọi mục tiêu, cả cuộc đời cô ấy… luôn ở ngay đây.”","“Vậy sao cô còn cản cô ta?”","“…Tôi sợ cô ấy tự làm mình chết. Tất nhiên rồi.” Hoshiguma nhìn cô. “Swire, sau chuyện này cô sẽ có vai trò quan trọng ở L.G.D.”","“Như thể tôi làm được vậy. Tôi không phải cô ta…”","“Ồ, vậy là cô thừa nhận cô ấy giỏi hơn cô?”","“Tôi chỉ nghĩ mình không hợp với L.G.D.!”","“Không, tiểu thư, cô hoàn toàn hợp. Tôi không hợp. Ch’en cũng không. Nine cũng không. Người thật sự làm L.G.D. tỏa sáng… là cô. Cô phải gánh vác trách nhiệm. Chỉ cô mới làm được. Tôi giờ chai sạn rồi, có nhiều thứ tôi không thấy nữa. Tôi chỉ muốn thành phố này trở thành nơi chấp nhận tất cả mọi người.”","“Tôi cũng vậy.”","Một bóng người bước ra từ màn đêm.","“Cô—” Swire thốt lên.","“Lâu rồi không gặp, cô Swire,” Lin Yühsia nói. “Chào Thanh tra Hoshiguma.”","“Con gái quý báu của Vua Chuột đến cái chỗ tồi tàn này làm gì?” Hoshiguma đứng dậy. “Cô định làm gì cô ấy? Nói trước nhé, nếu cô định động đến dù chỉ một sợi tóc của tiểu thư…”","“Tôi không có ý đó.”","“Cô… đã làm hỏng chuyện,” Swire nói.","“Có lẽ. Đôi khi chúng ta không có lựa chọn.”","“Tôi không nghĩ có lúc nào… chúng ta không có lựa chọn.”","“Nhìn lên trời đi,” Lin Yühsia nói. “Trời sắp có tuyết. Cô có chọn được cho nó ngừng không?”","Swire ngẩng lên.","“Sao… lại có tuyết?”","@bg:bg_corridor","<i>Ngủ đi, ngủ đi♪</i>","<i>Tóc bạc của bố, kim khâu của mẹ♪</i>","@bg:bg_perimeter","<i>Rhodes Island, đơn vị xử lý sinh học.</i>","“Chết tiệt, vượt ngưỡng hòa tan rồi! Mở van xả bằng tay, ngay!” một operator kêu. “Đợt biến động vừa rồi gây hiệu ứng hút nhiệt dữ dội. Không tăng lượng xả thì cả cabin sẽ hỏng! Mây mưa cũng chẳng di chuyển mấy… Cứ thế này thì tuyết sẽ rơi dày lắm.” Anh ta nhìn qua lớp kính đóng băng. “FrostNova này… là người thế nào vậy?”","@bg:bg_chercen_2","<i>Mọi giấc mơ chìm xuống đáy hồ~♪</i>","<i>…đó là hiện thực mà ngay cả thời gian cũng chẳng lay chuyển nổi~♪</i>","“Khụ, khụ…” Mephisto ngừng hát. “Chết tiệt… Bài hát gì mà xấu thế. Chết tiệt!! Sao FrostNova lại hát hay đến vậy? Ta thật sự… không hát hay được…”","","“Tuyết rơi…” Rosmontis nói, ngước nhìn bầu trời xám. “Ông lão này…”","“Tốc độ kết tinh của ông ấy giờ đã trên sáu mươi phần trăm. Ngay cả người Sarkaz cũng không thể cử động được,” Kal’tsit nói. “Ý thức của ông ấy đã tan biến… Tuy vậy, ý chí sắt đá của ông ấy vẫn lan tỏa từ cơ thể. …Buldrokkas’tee.”","“Oán hận. Thù ghét. Hối tiếc,” Amiya nói khẽ. “Tất cả đều tan biến rồi. Thứ duy nhất còn lại là cơn thịnh nộ. Sự không chấp nhận số phận của FrostNova. Sự thù địch với hành động của Talulah. Nỗi nhớ khôn nguôi về Ursus và Kazdel… Một cơn thịnh nộ rực lửa không thể dập tắt. Vì mọi bất công trên thế giới. Vì những người đã ngã xuống quanh ông. Với những kẻ đùa giỡn với số phận của người khác.”","“Chống lại số phận là chống lại tất cả. Mọi thứ góp phần tạo nên ý niệm ‘định mệnh’,” Kal’tsit nói. “Cơn thịnh nộ của Buldrokkas’tee… đã thiêu đốt cả thế giới này.”","“…Cả thế giới đầy bất công này,” Amiya nói. “…Ông Patriot…”","“Bỏ tay ra.” Một hộ vệ khiên tiến lại, giọng run lên. “Ngươi, cô bé Cautus Infected. …Chúng ta sẽ hoàn thành việc còn dang dở của Đội trưởng.”","“…Đủ rồi,” Rosmontis chắn trước Amiya. “Các chú muốn ông ấy chết vô ích sao? Ông ấy không muốn ai trong các chú chết. Ông ấy muốn tất cả các chú tìm một con đường khác. Ông ấy chọn chết một mình để tất cả các chú được sống…!”","“Ai nói chúng ta sẽ là người chết? Chúng ta cũng nghe ông ấy nói rồi. …Cautus. Ngươi là nguồn gốc của mọi sự đổ nát sắp tới. Những lời tiên tri cổ xưa đều đã ứng nghiệm.”","“Nhưng FrostNova đã tin chúng tôi!” Doctor nói.","“…Dù vậy… FrostNova… giờ đến cả Đội trưởng…”","“Ông ấy dĩ nhiên không mua chuộc được bằng đánh giá của FrostNova! Ông ấy chỉ tình cờ bỏ qua ý kiến của con gái… Ông ấy không bước vào chuyện này bằng niềm tin mù quáng. Quyết định ông ấy đưa ra… thật sự chính đáng! Vậy mà các anh lại chọn tin một lời tiên tri?”","“…Không, không phải chúng ta tin lời tiên tri. Chúng ta tin Đội trưởng.”","“…Kẹo của FrostNova cay lắm,” Doctor nói.","“…Cái gì?!” Người hộ vệ sững lại. “Yelena… cho ngươi ăn kẹo của nó sao?”","“Tôi tin cô ấy, và cô ấy tin tôi. Nếu các anh thật sự muốn lấy mạng ai đó… ít nhất hãy tự mình nhìn cho rõ! Đừng mù quáng đi theo người khác!”","Người hộ vệ im lặng rất lâu.","“Không. Rhodes Island, chúng ta hiểu phần nào những gì các ngươi nói. Nhưng chúng ta sẽ không bao giờ cùng quan điểm. Chúng ta theo Đội trưởng cả đời, nhưng không phải mù quáng. Nếu… một ngày nào đó, cô bé Cautus kia biến thành bạo chúa như Talulah… chúng ta sẽ kết liễu các ngươi. Đội trưởng đã chiến đấu với tất cả những kẻ đó… bọn buôn nô lệ, kẻ áp bức, kẻ thống trị thối nát, kẻ mang đến diệt vong. Không ai thoát được. Đội trưởng biết. Về tất cả những người ở Chernobog đã chết trong Catastrophe. Về tất cả huynh đệ của chúng ta đã chết vô ích. Ông ấy có những hối tiếc, nhưng biết mình không thể trốn chạy. Giờ ông ấy đã giải phóng chúng ta. Chúng ta chỉ thuộc về Đội trưởng và lý tưởng ông ấy chiến đấu vì nó, không thuộc về Reunion. Từ giờ chúng ta sẽ tiếp nhận ‘Lá chắn’ của ông ấy. Không phải Lá chắn của người Infected, mà là người bảo vệ tất cả những kẻ bị nô dịch. Chúng ta sẽ để mắt đến ngươi, Cautus. Nếu ngươi bước dù chỉ một bước sai đường, chúng ta thề sẽ săn lùng ngươi. Chúng ta sẽ coi những lời tiên tri này… là bí mật của mình. Vì trước đó, có một bạo chúa đang chờ chúng ta ở tháp chỉ huy.”","“…Kẻ đã đẩy các anh vào cuộc chiến với chúng ta và gây ra chuỗi bi kịch này là thủ lĩnh Reunion, Talulah,” Kal’tsit nói.","“Chúng ta sẽ tập hợp lại. Phải báo tin cho đội du kích. Còn các ngươi… tiếp tục làm nhiệm vụ của mình, nếu đó là điều các ngươi muốn.” Người hộ vệ ngẩng lên. “Tuyết… rơi…? Trận tuyết dày thế này… Có phải Yelena đến đón Đội trưởng không…?”","","“Amiya, đừng quá bận tâm,” Kal’tsit nói. “Người Sarkaz có lịch sử lâu đời với Originium. Ký ức của họ hòa vào Originium và trở thành một với đất đai, rồi quay về chính cơ thể họ. Đôi khi, những bộ tộc lưu truyền các tinh thể Originium này từ lâu sẽ gom thông tin về một chỗ. Qua việc dùng Arts liên tục, những thông tin ấy, trộn lẫn ngoài dự tính, hiện ra dưới nhiều hình thức. Phần lớn đã bị thời gian xóa nhòa, nội dung lộn xộn hoặc lỗi thời. Những lời tiên tri này không có cơ sở.”","“Nhưng chúng tác động trực tiếp đến người khác,” Amiya nói. “Như… có người nghe được những lời tiên tri này rồi bắt đầu cố biến chúng thành sự thật, đúng không? Em không biết những ý niệm này chỉ là tiếng thì thầm mơ hồ… hay là hạt giống có thể nở thành hiện thực. Em thật sự không biết, nhưng… Ông ấy có thể đã giết em. Nhưng… ông ấy đã nghĩ…”","","<i>“Ta sẽ giết nó ngay bây giờ.”</i>","<i>“Dừng lại. Sao cha chắc nó là kẻ thù của chúng ta?”</i>","<i>“Nó là người kế thừa của Kashchey! Nó sẽ đầu độc tất cả chúng ta, như con rắn già đó!”</i>","<i>“Không, ông già cứng đầu… Cha sai rồi. Dù cuối cùng nó có thành ra như vậy, chúng ta cũng không thể giết nó bây giờ. Vì bây giờ nó không phải Kashchey. Ơ, mà đó là ai chứ? Con không hiểu cha. Con chỉ biết, nó chỉ là Talulah.”</i>","<i>“…Ai nhét những ý nghĩ này vào đầu con? Nó sẽ làm cong vênh ý chí chiến đấu của con.”</i>","<i>“Cong vênh? …Làm như thật ấy, ông già. Cái gọi là tinh thần chiến binh thuần khiết ấy à? Nếu cha thật sự có nó, con đã chẳng bao giờ gặp cha. Nếu cha thật sự có nó, chúng ta đã chẳng thể ngồi quanh đống lửa ăn súp như bây giờ.”</i>","<i>“Con… mới mười sáu tuổi. Súp của con nguội chưa?”</i>","<i>“Lúc nào chả nguội. Thế lại hay.”</i>","<i>“…Lần này ta sẽ nghe con.”</i>","<i>“Không, Cha. Không phải thế. Nếu cha tin mình đúng, thì… dù chuyện gì xảy ra, cha nên tiếp tục tin như vậy. Vì nếu có chuyện gì xảy ra với Talulah, đó là chuyện giữa nó và người của nó. Nhưng hiện thực chỉ là những gì trước mắt chúng ta. Đúng không, Cha? Dù tương lai có gì, ngay lúc này, con là con, và cha là cha. Dù cha có nghĩ ngợi bao nhiêu, chúng ta là chúng ta của hôm nay. Những người duy nhất chúng ta có thể thay đổi là chính mình, và chúng ta là người đưa ra quyết định đó. Hãy thử đi con đường của nó xem sao.”</i>","<i>“…Sau này con sẽ là một lãnh đạo giỏi.”</i>","<i>“Con không muốn làm lãnh đạo. Con chỉ muốn một cuộc sống thoải mái với các anh chị em, các chú các bác, và cha.”</i>","<i>“Ta sẽ nhớ điều đó.”</i>","<i>“Cha chắc chứ?”</i>","<i>“Ta sẽ không quên.”</i>","@bg:bg_snow_2","“Rosmontis… bác sĩ Kal’tsit… Doctor…” Amiya nói. “Ông ấy có thể đã giết em… Ông Buldrokkas’tee… có thể đã giết em. Nhưng em đã thấy… em đã thấy ông ấy nghĩ gì. Ông ấy đã không làm. Ông ấy tự dừng lại, vào giây phút cuối. Em vẫn còn… nghe thấy ông ấy…”","“Amiya. Nói cho ta điều quan trọng nhất. Điều cuối cùng ông ấy nói là gì?”","<i>‘Ta đã thấy. Khổ đau và bi kịch.’</i>","<i>‘Ta đã thấy. Chết chóc và tàn sát.’</i>","<i>‘Ta đã thấy. Lãng quên và báng bổ.’</i>","<i>‘Nhưng có người từng nói với ta. Tất cả nằm trong tay chúng ta. Nếu trong tương lai, đây là tất cả những gì đang chờ chúng ta…’</i>","<i>‘Hỡi Vua Sarkaz nhỏ bé. Tất cả nằm trong tay chúng ta. Nếu đây là số phận…’</i>","<i>‘Thì ta khước từ nó.’</i>","“Ông ấy nói… Ông ấy hỏi…” Amiya thì thầm. “Ông ấy thở dài… <i>‘Thưa Ngài… Ngài sẽ đi về đâu?’</i> …Rồi không còn gì nữa. Doctor… em đã đọc hết rồi. Em đã thấy tất cả. Em đã đọc cả cuộc đời ông ấy.”","“Amiya… Buldrokkas’tee… Ông ấy thừa nhận cả đời đã phản bội niềm tin của mình hai lần,” Kal’tsit nói. “Lần đầu, khi rời Kazdel và từ bỏ cuộc đời chiến binh Sarkaz. Lần thứ hai, khi đứng lên chống lại Ursus và từ bỏ cuộc đời chiến binh của Đế quốc Ursus. Và vừa rồi… ta cho rằng ông ấy đã thực hiện lần phản bội cuối cùng. Ông ấy phản bội Reunion và những người Infected ông ấy phụng sự, thôi làm chiến binh của phong trào Reunion. Cái chết của ông ấy khép lại lần phản bội cuối cùng.”","“Ông ấy phản bội mọi thứ ông ấy quan tâm, vì ông ấy luôn đứng lên vì niềm tin của mình,” Amiya nói.","“Nhưng như thế… là không đúng, phải không?” Rosmontis hỏi.","“Thứ ‘phản bội cao thượng’ này là sự giải thoát cho những kẻ lừa dối thế giới. Đó là cách dễ dàng để đẩy mọi chuyện về phía kết quả tốt nhất,” Kal’tsit nói. “Nhưng không phải với Buldrokkas’tee. Nói đi, Amiya.”","“…Kazdel là quê nhà của ông Buldrokkas’tee,” Amiya nói. “Dù đã đi xa đến thế, ông ấy vẫn luôn muốn trở về Kazdel… Không phải ông ấy không muốn về nhà, mà là không thể. Ông ấy phải trả giá trước đã… cho sự phản bội của mình. Ursus là tổ quốc của ông ấy. Ông ấy chiến đấu vì Ursus cả đời… và tự trách mình vì cái chết của con trai. Ông ấy tin Ursus là cái ác, nhưng vì mảnh đất này, ông ấy đã dâng hiến cuộc đời… chiến đấu đến tận cùng. Ông ấy cũng đã trả giá cho lần phản bội thứ hai. Lần này… ông ấy phải đứng lên chống lại Talulah. Nhưng ông ấy thấy trước rằng một số người ông ấy cố bảo vệ sẽ chết vì hành động của mình. Dù quyết định của ông ấy giữ lại một tương lai cho người Infected, ông ấy… chỉ cảm thấy đau đớn… vì những người đã khuất. Đây là lần phản bội thứ ba, và là lý do ông ấy quyết tâm chuộc lỗi đến thế. Từ đầu đến cuối, trận chiến này là để bù đắp hậu quả của sự phản bội.”","“Qua ba lần ấy, số phận cứ đẩy ông ấy đi xa hơn mỗi khi ông ấy chỉ muốn quay lại. Ông ấy căm ghét sự tàn nhẫn và chế giễu của số phận. Ông ấy chưa bao giờ muốn đi theo nó, nhưng vẫn gánh chịu mọi hậu quả. Mười năm, hai mươi năm… em còn có thể hiểu. Nhưng… đã quá lâu rồi. Sau khi đối mặt với tất cả những hối tiếc ấy suốt bao nhiêu năm, đã quá lâu rồi. Đến cuối cùng, ngay cả em cũng không hiểu nổi. Ông ấy có thể đã lấy mạng em, nhưng ông ấy dừng lại vào phút cuối.”","“…Ông ấy đã chiến thắng nỗi khổ cả đời, hệ tư tưởng hàng thế kỷ, và tình yêu của mình với cả thế giới này,” Kal’tsit nói. “Ông ấy không còn tuân theo những nguyên tắc đã giữ suốt bao năm. Ông ấy… khuất phục trước số phận. Không, nói thế là làm ô danh ông ấy. Đúng hơn, ông ấy chọn gạt bỏ mọi thứ mình đã chống lại, và vượt qua chướng ngại cuối cùng trong lòng mình. Ông ấy giao phó tương lai cho em. Lần này, ông ấy vui lòng chọn làm điều mình cho là đúng, thay vì tự hành hạ mình để giữ một lý tưởng nào đó. Tất nhiên, sâu trong lòng ông ấy, phần này đúng như em mô tả… Nó từng thuộc về Talulah, và giờ thuộc về em. Nhưng nó luôn thuộc về FrostNova.”","“Patriot… FrostNova…” Amiya nói. “Bác sĩ Kal’tsit. Rosmontis… và Doctor. Em sẽ chấm dứt cuộc chiến này. Ngay tại đây. Ngay bây giờ.”","“Vâng,” Rosmontis nói. “Em sẽ ở bên chị, Amiya. Mãi mãi.”","Kal’tsit im lặng.","<i>Dù ngươi có thể cứu rất nhiều người, ngươi cũng sẽ gây ra khổ đau vô hạn.</i>","<i>Phẫn nộ. Cơn phẫn nộ của ta đến từ sự bất công mà số phận đã giáng xuống thế giới này.</i>","“Sau vô số năm… cuối cùng mọi chuyện cũng đến hồi quyết định sao?” Kal’tsit lẩm bẩm. “Sao chuyện đó có thể xảy ra? Lời tiên tri này… chẳng phải chỉ là một mảnh vụn khác của lịch sử Sarkaz sao?”","@bg:bg_chercen_2","<i>Khu kho lõi đô thị.</i>","“…Hử? Sao người của Patriot lại ở đây? Đây không phải khu tuần tra của ngươi,” tên lính đánh thuê Sarkaz nói.","“Ngươi, thả cậu ta ra,” một chiến binh du kích nói.","“Hự…!” Guard rên lên.","“Lần này ta bỏ qua. Cảnh cáo nhẹ thôi, lần sau đừng chõ mũi vào chuyện không phải của mình.”","“Ta vừa nhận được tin,” người chiến binh du kích nói. “…Patriot đã qua đời.”","“Cái gì?!” Guard thốt lên.","“…Tin lớn đấy,” tên Sarkaz nói.","“Nên lúc này… chúng ta không còn lý do gì để tiếp tục vở kịch này nữa. Lũ quỷ các ngươi hôi hám hơn bất kỳ người Sarkaz nào của chúng ta.”","“Chuyện gì đã xảy ra? Patriot chết thế nào?!”","“Xử lý lũ cặn bã Reunion này trước đã!”","“Ngươi gây sự với lõi đô thị à?”","“Thì sao?”","“…Ngay cả Patriot cũng chết rồi. Lũ khốn các ngươi… Ta không chịu đựng các ngươi thêm nữa!” Guard đứng dậy. “Nếu Patriot đã chết, Reunion còn giá trị gì chứ?! Đội du kích! Nếu có gì tôi giúp được… cứ nói!”","“Trước hết, chúng ta sẽ ném tất cả những kẻ đùa giỡn với mạng sống người Infected… xuống khỏi tường thành này!”","@bg:bg_chercen_1","“Mantra-2, mặc đồng phục vào,” Kal’tsit nói. “Closure đã hack được mã nhận dạng, nhớ đừng để lộ vũ khí giấu kín. Tin tức hẳn đã lan ra rồi. Thứ chúng ta cần bây giờ là…”","“Hỗn loạn?” Elysium hỏi.","“Không, trật tự. Đi giúp đội du kích. Để người Infected, những thành viên Reunion có thiện chí, và những người chống lại bất công tập hợp dưới một lá cờ. Như thể Talulah không thể dàn dựng được cái chết của Patriot.”","","“Gì cơ…? Hắn nói gì?” một thành viên Reunion hỏi.","“Patriot đã chết!” Guard hét lên. “Người thật sự lo cho Reunion! Người đã chiến đấu vì tất cả chúng ta! Patriot đã chết!”","“Talulah đã dàn dựng âm mưu chống lại Patriot! …Cô ta là tay sai của Ursus!” một chiến binh du kích nói.","“Ai tin lời nhảm nhí của các ngươi?!”","“Khoan… Talulah gần đây hành xử lạ lắm. Cô ta ra lệnh cấm duy trì liên lạc trong thành phố,” một caster Reunion nói.","“Thế thì chứng minh được gì?!”","“Chứng minh rằng… đám lính đánh thuê sắp phục kích đội du kích! Tôi hiểu kế hoạch của chúng rồi… lũ điên đó!”","“Dừng lại! Đừng đánh với chúng ta, nếu các ngươi quý mạng sống. Nếu không, chúng ta sẽ tiêu diệt các ngươi!” người chiến binh du kích hô. “Chúng ta là Lá chắn của người Infected, và chúng ta sẽ chiến đấu với mọi kẻ thù vì đồng bào mình! Kể cả khi phải chống lại Talulah! Vì Patriot!”","“Vì Patriot!”","@bg:bg_chercen_2","“Mọi chuyện hơi rối rồi. Các ngươi nên đi sớm đi,” một chiến binh Sarkaz nói với đám nỏ thủ.","“Còn các anh?”","“Lính đánh thuê bọn ta có ưu tiên riêng. Bọn ta không quan tâm âm mưu của Talulah. Cố gắng lên, và sống tiếp đi.”","“Vì tương lai của người Infected!” tiếng hô vọng lại từ xa.","“Vì…” một nỏ thủ nói, rồi siết chặt cây nỏ. “…Đội trưởng Faust! Vì tất cả đồng chí đã bị Talulah phản bội! Vì Faust!”","<i>Patriot chết rồi! Patriot chết rồi! Talulah đã phản bội Patriot! Talulah đã phản bội tất cả chúng ta!</i>","<i>Các người chắc không phải kẻ ngoài giết ông ta chứ? Tôi thấy người khác giết ông ta, không phải Talulah!</i>","<i>Patriot đã cấu kết với quân đội Ursus để giết Thủ lĩnh! Mở mắt ra mà nhìn sự thật! Patriot mới là kẻ phản bội!</i>","","“Patriot hẳn đã đoán trước điều này,” Kal’tsit nói. “Nhưng cuộc đấu tranh của ông ấy với cơn bão là vô ích. Ngay cả ‘Lá chắn’ cũng tiếp nhận những ý tưởng cấp tiến nhất của ông ấy, chứ không phải cách tiếp cận thực tế. Sau tất cả chuyện này, lõi đô thị sẽ chìm vào hỗn loạn. Phong trào Reunion không còn tồn tại nữa.” Bà quay sang. “Rosmontis, đây có phải sự báo thù em muốn không?”","“…Không, chưa. Không phải thế này. Em chưa thấy mục tiêu. Không…”","“Dù em đối mặt với ai, kết quả vẫn như nhau. Reunion chỉ là một biểu tượng. Dù ai bị cuốn vào nó hay làm gì… họ không phải là cá nhân. Họ hành động như một phần của Reunion. Báo thù… chỉ đưa em đến đây thôi. Chúng ta không phân biệt được khuôn mặt họ. Chúng ta chỉ có thể xóa bỏ chính biểu tượng ấy. Rosmontis, em có thể tiếp tục thực hiện mong muốn của mình. Nhưng… kiểu báo thù này có làm em thỏa mãn không?”","“Kal’tsit… Em sai sao? Em… em chỉ…”","“Ta mà đưa ra câu trả lời cho em thì thật vô trách nhiệm,” Kal’tsit nói. “Chỉ em mới có khả năng theo đuổi những điều em tin là đúng. Sự phẫn nộ đã ăn sâu vào cơ thể chúng ta. Chúng ta muốn buông thả bản thân, để nó chảy tràn và đông đặc thành hận thù? Hay chúng ta có thể biến nó thành một vị thẩm phán cao hơn, cân đo mọi hành động tương lai và soi sáng lý trí của chúng ta? Em muốn phân biệt đúng sai, hay em muốn hiểu lý do mọi chuyện xảy ra? Sự sống và cái chết của các operator, những cảnh tượng làm em chấn động… và lý do chúng ta có những cảm xúc này. Dù có những thứ tâm trí em xóa đi, Rosmontis, chúng vẫn sẽ luôn ở trong em… Có lẽ trong đời có rất ít chuyện thật sự chỉ là đúng hay sai. Gạt bỏ hết những biểu tượng ấy, chỉ khi đó cuộc đời chúng ta mới có giá trị.”","“…Kal’tsit.”","“Ta đang nghe.”","“Em muốn biết lý do.”","","“Doctor. Phần tiếp theo chúng ta sẽ tách ra,” Amiya nói. “Em và Rosmontis sẽ đến tháp chỉ huy. Bác sĩ Kal’tsit sẽ đưa ngài đến khu máy phát điện.”","“Một thời gian tôi sẽ không gặp em sao?”","“Chỉ vài tiếng thôi mà, đúng không?” Amiya mỉm cười. “Mà Doctor này… Dù không ở bên ngài, em sẽ luôn biết rằng Doctor ở ngoài kia… đang chiến đấu cùng em. Dù không nhìn thấy nhau, chúng ta vẫn chiến đấu vì cùng một mục tiêu. Em thấy thế là vui lắm rồi.”","“Hẹn gặp sau nhiệm vụ!”","“Vâng. Cô Ch’en có lẽ đã ở gần tháp chỉ huy. Cô ấy luôn nhanh, nên chúng em phải nhanh lên. Doctor… Hứa với em là ngài sẽ an toàn. Công việc của chúng ta ở đây chỉ có ý nghĩa nếu chúng ta trở về Rhodes Island an toàn. Cẩn thận nhé?”","“Em cũng vậy.”","","<i>Lõi đô thị Chernobog, khu cấp điện. 3:00 chiều.</i>","“Sao bà chọn tôi vào đội của bà?” Doctor hỏi.","“Đội tấn công chặt đầu sẽ bị Reunion tấn công từ mọi phía khi tiến về tháp chỉ huy. Ta không thể thả ngài vào chiến trường như thế,” Kal’tsit nói. “Khi đánh với đội du kích, chúng ta còn có thể rút lui để tập hợp lại. Đội của họ sẽ không có cơ hội đó. Họ thậm chí không có lấy một khe hở để thở. Trận này có mục tiêu rõ ràng, và đội của Amiya và Rosmontis không thể phân tâm thêm nữa. Ngài sẽ an toàn khi ở với ta.”","“Ở cạnh bà tôi không thấy an toàn chút nào.”","“Chúng ta chỉ nên nhận những trách nhiệm mình làm được. Sau khi vào khu lõi, liên lạc sẽ còn tệ hơn. Khi đó, chúng ta thật sự chiến đấu một mình.” Kal’tsit khựng lại. “Khoan… Doctor, ẩn mình một lát.”","Một tiếng ho khan vang lên từ đống đổ nát.","“Á… khụ, khụ…” W bò ra, người đầy máu và bụi. “Đây là đâu? Sao mình lại nổ tung đến tận đây… Hết rồi à? Hả? Các người là… Rhodes Island? Hôm nay đúng là xui tận mạng…” Rồi cô ta nheo mắt. “Hử?! …Đúng là cuộc hội ngộ bất ngờ, Kal’tsit.”","“…Cô bị thương nặng,” Kal’tsit nói. “Giờ cô tên gì, W?”","“Vẫn là W. Chưa kịp đổi.” W nhìn quanh. “Khoan, sao bà lại thong dong dạo quanh chỗ này? Đừng bảo… Lão già đi rồi à?”","“Phải.”","“Lão chết rồi? Sao có thể? Nhưng… mà cũng phải. Lão đằng nào cũng không sống sót qua vụ này. Lão không bao giờ lùi bước, cũng không bao giờ để ai qua.”","“Cô có vẻ đau lòng.”","“Chắc vậy. Lão già đó là người duy nhất khiến tôi chịu nhìn Reunion thêm lần nữa. Xem ra hôm nay… là ngày cuối của tay lý tưởng đó.”","“Tôi đã thấy ông ấy trút hơi thở cuối cùng,” Doctor nói. “Ông ấy chết một cách vinh quang.”","W quay phắt lại. Đôi mắt cô ta nhìn Doctor theo cách chưa từng thấy bao giờ.","“——Kal’tsit, kể chuyện đi.”","“Ta có gì phải kể với cô?”","“Bà hỏi tôi? Đùa à? Sao bà có thể đứng đó bình thản như chưa từng có chuyện gì?” Dù nói với Kal’tsit, mắt W vẫn dán chặt vào Doctor. “Kal’tsit, bà đang làm việc với Doctor? Bà? Làm việc cùng Doctor?”","“Có vấn đề gì sao, W?”","“Tất nhiên rồi, trừ khi bà cũng như tên khốn này giả vờ không nhớ gì. Mà nếu đúng vậy thì cũng chẳng quan trọng… Không thì não bà bị nướng chín trong mấy cái thí nghiệm quái gở của bà rồi. Chết tiệt, hoặc tôi điên, hoặc bà điên. Kal’tsit, cuối cùng bà cũng phát rồ rồi. Định thuần hóa ác linh của Babel à?”","“Không chứng minh được trong đầu người này còn chút ký ức nào. Chúng ta chỉ tạm thời hợp tác.”","“Cái gọi là mất trí nhớ này… Sao bà chắc đó không phải một màn kịch công phu? Nó có thể lừa được tất cả mọi người. Phải, tất cả. Bà cũng bị lừa, dù bà có muốn thừa nhận hay không. Kal’tsit, bà là quái vật, đúng không? Một con quái vật thông minh đến mức có bộ não to, sáng, phát sáng. Và một con quái vật hẳn biết rõ hơn tôi chuyện gì xảy ra khi có một con quái vật khác bên cạnh.”","“Trên đời có quá nhiều sinh vật có thể gọi là ‘quái vật’. Dùng từ đó nhiều quá, nó sẽ mất hết ý nghĩa.”","“Rốt cuộc cô biết gì?” Doctor hỏi.","“Chỗ này không có phần cho ngươi chen vào đâu, bạn hiền. Xong với bà ta rồi sẽ đến lượt hai ta nói chuyện dài,” W nói. “Trút giận lên ngươi chẳng có ích gì. Hoặc ngươi mất trí nhớ, hoặc ngươi giả vờ mất trí nhớ… Nhưng người phụ nữ bên cạnh ngươi thì hoàn toàn mất trí rồi. Tôi muốn biết— Hồi đó, chỉ có một người vào Văn phòng Diễn giả và biết Theresa ở đâu. Kal’tsit, bà biết điều đó nghĩa là gì, đúng không?”","“Tất nhiên. Ta biết rõ hơn cô.”","“Đó là lời của bà!” W gằn giọng. “Vậy giờ là sao? Bà đang làm gì? À, tôi hiểu rồi. Bà định làm một cuộc trao đổi nữa. Có qua có lại. Nhưng ở đầu bên kia là Theresa đấy!”","“Những kẻ không biết sự thật đừng để suy đoán ảnh hưởng đến cảm xúc, W.”","“Tôi chỉ có một suy đoán thôi: Bà không phải con người. Như tôi đã nói, nếu bà mặc cả cái chết của Theresa với một kẻ giết người… bà chỉ là một con quái vật. Bà không phải con người, Kal’tsit. Tôi cần biết sự thật. Và trước khi biết, thứ đứng cạnh bà là một kẻ giết người; và tôi sẽ không bao giờ nương tay với kẻ giết người.” Cô ta cười khẩy. “À, giờ thì tôi hiểu rồi. Bà đang tràn trề tình mẫu tử, nhỉ.”","Kal’tsit im lặng một lúc. “W, cô từng nói… ‘Chúng ta là cùng một loại người.’”","“Tôi không biết bà nghe câu đó ở đâu, cứ coi như chưa từng nghe đi. Bà và tôi hoàn toàn không phải cùng một loại sinh vật.”","“Không, W. Ở một mức độ nào đó, chúng ta là vậy. Chẳng hạn, cô cũng muốn chấm dứt tội ác của Talulah, đúng không?”","“…Đúng vậy. Ả thật sự làm tôi điên lên. Tôi phải lấy lại lính đánh thuê của tôi từ tay ả. Con khốn đó chỉ biết phung phí người. Đúng là đồ hoang phí. Tôi sợ ả tiêu hết tiền tiết kiệm làm tôi trắng tay mất.”","“Vậy thì giải quyết vấn đề Reunion trước đã.”","“Được thôi. Tôi có danh sách mục tiêu rồi. Muốn nghe không? Đầu tiên là Talulah, ả rồng cái ghê tởm trên lầu. Tiếp theo là Theresis, kẻ mà vừa nhìn thấy đã muốn hắt hơi.”","“Kế hoạch dài hơi đấy.”","“Sau đó, thứ ba tôi muốn giết đang đứng ngay cạnh bà: Doctor.”","“Ngài chỉ đứng thứ ba thôi à?” Kal’tsit liếc Doctor.","“Tôi chỉ đứng thứ ba?”","“Ha. Đó là vì tôi có chuyện muốn hỏi ngươi trước, Doctor. Tôi có mấy lời giải thích dài dòng, kỹ lưỡng cần moi ra từ ngươi…”","“Ở giai đoạn này, chúng ta có chung mục tiêu,” Kal’tsit nói. “Nhân tiện, về những gì cô đã làm với nhân viên của chúng ta ở Chernobog… Trước hết, cảm ơn cô vì cuộc mặc cả đã cứu mạng Doctor và đội cứu hộ. ‘Cuộc mặc cả’ đó đã khiến chúng ta mất mười ba operator. Cân bằng hai chuyện này, vì tình xưa nghĩa cũ, ta sẵn lòng cho cô quá giang. Ta sẽ đưa cô đến tháp chỉ huy.”","“Kal’tsit… Bà đúng là biết cách làm người ta buồn nôn,” W nói. “Tôi luôn thấy bà ghê tởm. Phải sắp xếp lại khuôn mặt bà một chút trước đã, xem ai trong hai ta mới là kẻ thắng…”","“Mon3tr.”","Mon3tr rú lên, vồ lấy W như một con búp bê vải.","“Con khốn!”","“Mon3tr, phá xuyên qua đường ống thông gió, các bức tường, và lớp bảo vệ ngoài cùng lẫn lớp giữa của căn cứ, mang cô ta theo,” Kal’tsit nói.","“Mụ già kia!! L-l-l-lần sau, tôi thề sẽ cho bà một cái chết chậm rãi và đau đớn——”","Tiếng hét xa dần.","“Ta rất mong chờ,” Kal’tsit nói.","“Tôi ngạc nhiên là bà còn để cô ta nói hết câu đầu tiên,” Doctor nói.","“Đằng nào ngài cũng không hiểu được.”","“Vậy sao bà không giải thích cho tôi?”","“Chưa đến lúc. Khi ngài tự mình thấy, ngài sẽ hiểu. Bí mật giống như mạch nước ngầm. Đôi khi chúng sẽ tự trào ra, dù ngài có muốn hay không.”","@bg:bg_indoor_1","Mephisto nằm trên một tấm phiến lạnh, nhìn lên những cỗ máy lạ lẫm.","“Một thiết bị lạ thật. Ngươi đưa ta đi đâu? Ngươi sẽ lấp đầy những lỗ hổng trong cơ thể ta, hay vá lại những vết sẹo của ta? Ngươi sẽ khiến ta quên hết mọi thứ, như người kia đã làm cho ta trước kia sao? Nếu ta quên hết mọi thứ… Ta có muốn quên không? Ta muốn…”","<i>Ta có được chọn không?</i>","","<i>Lõi đô thị.</i>","“…Chuyện gì thế này? Mây đen? Tuyết rơi?” Ch’en nhìn lên. “Nhưng nó cũng che mặt trời giúp mình. Bước tiếp theo sẽ dễ hơn nhiều.” Cô nhăn mặt, ôm vết thương bên sườn. “Ư… Mình không thể chịu thêm đòn nào nữa. Chậc… Sợ đổ chút máu sao, Ch’en Hui-chieh? Quyết tâm của mày đâu rồi? Có vẻ nội bộ Reunion đang lục đục. Đây là thời điểm tốt nhất để hành động.” Cô nhìn xuống bàn tay mình. “Tay mình run vì cuối cùng cũng sắp gặp lại chị sao? …Mình phải làm điều đúng đắn. Chị bây giờ là gì không quan trọng, chị có còn là Talulah mà mình biết hay không cũng không quan trọng. Talulah… chúng ta có hẹn.”","","@cg:avg_7_18","<i>Lungmen.</i>","“Tuyết rơi dày thật…” Swire nói. “Giống như… Giáng sinh năm ấy.”","“Cô chưa bao giờ kể với tôi chuyện đó,” Lin Yühsia nói.","“Nhưng cô biết rồi mà.”","“Tôi biết và cô kể cho tôi là hai chuyện khác nhau.”","@cg:avg_7_20","“Công chúa, đừng làm tiểu thư ngượng nữa,” Hoshiguma nói.","“Phu nhân Oni.”","“…Bỏ cái danh hiệu đó đi, Công chúa.”","“Phu nhân Oni, nhà họ Lin sẽ không bao giờ quên những gì cô đã làm,” Lin Yühsia nói. “Nhưng lúc này, tôi không biết liệu có dịp đền đáp cô không.”","“Cô nói gì vậy? Tất nhiên là có chứ,” Swire nói. “Cô ta… tôi biết cô ta sẽ thành công. Ah Ch’en… Ư…”","@cg:avg_7_19","“Nhìn cô kìa, ý chí của cô đâu hết rồi?”","“À, biết làm sao được? Tiểu thư lúc nào chả vậy,” Hoshiguma cười. “Nào nào, tiểu thư, không cần khóc đâu. Đừng lo. Mọi chuyện sẽ ổn thôi.”","“Nhưng… đây là lần cuối chúng ta gặp nhau. Tôi chưa sẵn sàng… Lỡ… tôi không bao giờ gặp lại con rồng hôi hám đó nữa thì sao?”","“Sẽ không có chuyện đó đâu, tiểu thư. Có một câu tôi rất thích. Ừm, nó thế này: ‘Một ngày nào đó, ở một nơi nào đó, chúng ta sẽ gặp lại nhau.’”","“…Phải,” Lin Yühsia nói. “Và khi chúng ta nhìn lại nhau, chúng ta sẽ hỏi han về cuộc đời của nhau.”","","<i>Tháp chỉ huy lõi đô thị.</i>","“…Tại sao?” Talulah chạm lên má mình. “Chuyện gì thế này? Những giọt nước mắt này từ đâu ra? Như thể… có ai vừa báo cho ta về một cái chết. Là ai? Mọi thứ trong lõi đô thị đều diễn ra đúng kế hoạch. Patriot sẽ chết dưới tay người Infected, và lính đánh thuê Sarkaz sẽ bắt đầu đánh nhau với lực lượng Reunion thường.” Cô ta khựng lại. “À. Patriot chết rồi sao? Vậy là Patriot. Một chiến binh thực thụ. Cái tên ấy không đủ để mô tả ông. Chính Ursus cũng quá nhỏ bé so với sự vĩ đại của ông. Một người ái quốc đến tận cùng.”","“…Sao ta lại khóc? Vì hoài niệm, hay vì phép lịch sự với những kẻ muốn giết ta? ‘Mọi tội lỗi rồi sẽ đến hồi kết?’ Vậy thì cứ chờ xem. Nếu chúng ta là kẻ có tội, chúng ta tất sẽ gặp kết cục của mình…”","<i>Nhưng ta sẽ chờ ngươi ở nơi tận cùng ấy.</i>","<i>Nhưng ta sẽ chờ nó ở nơi tận cùng ấy.</i>","","<i>Lungmen.</i>","“Sao ông lại ở đây, Kojui?” Wei Yenwu hỏi.","“Giống như mấy chục năm trước thôi,” Vua Chuột nói. “Khi người ta lo lắng, họ đưa ra những quyết định ngu ngốc, rồi lại đi tới đi lui ở đây. Buồn cười nhỉ? Bao năm rồi vẫn chưa bỏ được thói quen cũ.”","“Ông có biết ta định làm gì không, Kojui?”","“Tình cờ ta lại biết. Tất cả là nhờ đứa cháu gái của ông đấy. Hai người đều cắt ra từ cùng một tấm vải ngu ngốc.”","“Kojui, ông không ra đây để dạo chơi. Mà kể cả có, ông cũng đừng phí thời gian của ta.”","“Nói chuyện với bạn cũ bao giờ là phí thời gian chứ? Ông không còn coi ta là bạn nữa sao, Wei Yenwu? Nếu còn, hãy hứa với ta…”","“Ta không thể. Ta sẽ không hứa gì với ông.”","“Vậy thì thôi. Hôm nay ông đừng hòng đi đâu.”","“…Đừng tự đánh giá mình quá cao.”","“Đó là câu ta nên nói với ông mới đúng. Wei Yenwu, ông ngồi trên cái tháp đó lâu quá rồi, không tốt cho tính nết đâu. Xuống đây xả bớt hơi nóng đi, tốt cho ông đấy.”","“Đừng chớp mắt đấy, lão già ba hoa.”","“Hai chúng ta là gì… ngoài một cặp lão già ba hoa chứ?”","@bg:bg_uptown_1","<i>Khó mà tưởng tượng được. Ngay cả lão Patriot cũng có thể chết.</i>","<i>Mình nên cười? Hay nên rơi vài giọt nước mắt?</i>","<i>Buồn cười ở chỗ, giờ lão chết rồi, mày lại leo lên tận đỉnh Reunion, chỉ đứng sau Thủ lĩnh. Ôi, mày đúng là vượt qua chính mình rồi. Tự vỗ vai mình đi, W.</i>","<i>Bộp, bộp.</i>","<i>Sao chúng ta khóc? Vì ngay cả lão cũng chết. Ôi, than ôi, Patriot đáng thương! Lão nghĩ gì khi chết, và cảm giác đó ra sao? Lão chết khi đang đứng hay đang quỳ? Nếu ngay cả lão cũng chết được, thì ai trong chúng ta sống nổi?</i>","<i>Có lẽ lão mới là người dễ chết nhất. Chẳng bao giờ biết khiêm tốn. Chỉ biết bám lấy một lý tưởng mơ hồ. Cứ đi mãi, đi mãi trên con đường ấy, cho đến khi mọi người quanh lão đều không còn. Rồi lão mới được yên nghỉ. Thật đáng buồn.</i>","<i>Khoan, nghe có hơi giống mày không, W?</i>","<i>Hả? Mình giống chỗ nào?</i>","<i>W, đừng tự lừa mình. Mày gần như y hệt.</i>","<i>Không đâu, mình chẳng bao giờ tự lừa mình. Mình sẽ không bao giờ thành Patriot, vì mình không thể. Mình không thể. Vả lại, cái chết… với lão là một sự giải thoát, đúng không?</i>","<i>Nhưng không phải với mày, W. Cái chết là trò chơi của đời mày.</i>","<i>Thứ gì không giết được mày, sẽ đẩy mày tiến gần thêm một bước đến cái chết. Càng gần cái chết… mày càng gần sự điên loạn.</i>","“Cảm ơn nhé, Kal’tsit,” W nói, phủi bụi trên người. “Không có bà, tôi chẳng biết làm sao thoát khỏi đống rác đó. À phải rồi, Talulah… Nghe thấy không, Talulah? Cốc cốc? Thôi, chẳng có gì to tát. Tôi chỉ muốn báo với cô…”","Cô ta nhe răng cười về phía đỉnh tháp.","“——Tôi về rồi đây.”"],"bg":"bg_building_3","cast":[["Kal'tsit","op:char_003_kalts"],["W","npc:avg_npc_046"],["Amiya","op:char_002_amiya"],["Swire","op:char_308_swire"],["Hoshiguma","op:char_136_hsguma"],["Rosmontis","npc:avg_npc_042"],["FrostNova","npc:char_1505_frstar_1"],["Lin Yühsia","npc:avg_npc_036"]]},{"c":"7-20","t":"??:??:??","p":["<i>Nhiều năm trước. Lungmen.</i>","@cg:avg_7_23","“Ta có thể trả con bé lại cho ngươi, Wei,” Kashchey nói.","“…Dừng lại!” Wei Yenwu gằn giọng. “…Đừng làm thế.”","“Ồ? Ngươi và đám đao phủ hùng mạnh của ngươi đã biến cuộc đời ta thành địa ngục. Tất nhiên ta sẵn lòng trả con bé lại cho ngươi… Nhưng chiếc còng trên người nó sẽ xé Lungmen làm đôi.”","“Đồ khốn…”","“Wei, đây là cách ngươi từng dùng để đối phó ta. Cách ngươi đuổi ta khỏi Lungmen. Nhưng giờ, vai trò của chúng ta đảo ngược rồi. Ta là khách, và cũng là kẻ đầu độc.”","“Kashchey. Ngươi đã giết anh trai ta.”","“Không, không, Wei. Chính ngươi đã giết anh trai mình,” Kashchey nói. “Vai trò của ta không quan trọng. Bi kịch của anh ngươi có thể đến từ mật lệnh của một Unicorn, hay từ cơn thịnh nộ của một Lung. Việc có phải ta tiết lộ tin tức hay không… rốt cuộc chẳng quan trọng. Điều quan trọng, Wei, điều ngươi không được quên… là Chi Xiao của ngươi đã uống máu anh ấy. Chính ngươi đã làm. Chi Xiao, thanh kiếm chém rồng. Và lưỡi kiếm này đã chém ai? Bạn bè ngươi. Gia đình ngươi. Đồng loại ngươi. Kiếm chém rồng? Thật trớ trêu khi đồng loại ngươi lại rèn ra một thứ vũ khí quay lại chém chính giống loài mình.”","“Ngươi đã đi quá xa rồi.”","“Được thôi. Ta cho ngươi một lựa chọn. Chọn đi. Giết ta, lấy lại cháu gái, nhưng mất thành phố. Hoặc để chúng ta đi.” Kashchey mỉm cười. “Đừng rút thanh kiếm đó. Ngươi biết hậu quả mà. Bình tĩnh nào, Wei. Ta để ngươi tự chọn số phận. Nếu ngươi không nhận lời đề nghị hào phóng của ta, thì cả ngươi lẫn ta, mọi công dân của ngươi, và hai chị em xinh xắn này… đều sẽ chết.”","“Ngươi đang mưu tính gì?”","“Wei, Wei già… Ta hiểu ngươi. Quá rõ. Ngươi luôn có lựa chọn, đúng không? Những công dân quý báu của ngươi sẽ nghĩ gì khi nghe rằng mạng sống của họ đã bị đặt lên bàn cân? Và ở đĩa cân bên kia… là một con rồng nhỏ mà họ chưa từng nghe tên. Còn ta, ta thậm chí chẳng có lý do gì để làm hại nó.”","“…Vì ta đã sơ suất để ngươi đặt chân vào thành phố này lần nữa, ta không có lý do gì để ngươi rời đi.”","“Tal!” một giọng trẻ con hét lên. Cô bé Ch’en nhỏ xíu.","“Thế à?” Kashchey nói.","“…Ta sẽ tự tay giết ngươi.”","“Nào, nào. Không cần thế đâu. Mạng ta không phải thứ ngươi lấy được. À nhân tiện, ngươi có thể cứu con bé trước khi ta đeo còng cho nó. Nhưng ngươi cũng phải nghĩ đến việc phòng thủ trước ta. Đánh bại ta. Hạ gục ta. Tiêu diệt ta… Và cả những gì ta sẽ làm tiếp theo.” Kashchey nghiêng đầu. “Wei, ngươi thật sự sợ ta, phải không?”","","<i>Hiện tại. Tháp chỉ huy lõi đô thị.</i>","“Nó đến rồi,” Talulah nói. “Cuối cùng. Ta sẽ tự tay giết nó.”","","<i>Một nơi rất xa.</i>","“Confessarius, trả lời ta,” một giọng nói vang lên trong bóng tối. “Thủ lĩnh của Reunion, liên minh với cô ta có giá trị gì không?”","“Sao Bệ hạ lại hỏi thần những điều Bệ hạ đã biết rất rõ?” Confessarius đáp. “Một kẻ trẻ tuổi không tài sản, không gốc gác, không vốn liếng không thể một mình chiếm một thành phố quan trọng của Ursus. Những kẻ thống trị chưa nhiễm bệnh không biết phải hiểu hành động của cô ta thế nào. Chúng sẽ hoảng loạn, phản ứng thái quá, và cố giải quyết hỗn loạn bằng thêm nhiều sự hủy diệt, rồi dùng sự hỗn loạn do người Infected gây ra làm bình phong. Nhưng người Sarkaz chúng ta hiểu rõ hơn.”","“Ngươi nghĩ gì về đội quân cô ta để lại đây?” Nhiếp chính hỏi.","“Chúng không xứng đáng, thưa Bệ hạ. Như Bệ hạ đã thấy trước, chúng không có hy vọng. Chúng không phải binh lính được huấn luyện, không thể gây ra thứ bạo lực mà chúng ta tìm kiếm.”","“Loại bỏ chúng sẽ không cắt đứt được sức mạnh của Talulah. Chúng ta chưa có cơ hội hạ cô ta.”","“Đúng vậy, thưa Bệ hạ. Tình thế cô ta khơi lên và sức mạnh cô ta dùng để ép buộc mọi chuyện… cho thấy cô ta không phải kẻ chột làm vua xứ mù, cũng không phải một hoàng tử được nuông chiều chờ ngai vàng. Cô ta là một kẻ mưu đồ.”","“Dù vậy, ta cần một lời đáp toàn diện từ người Sarkaz.”","“Vậy thần có hai tin tốt. Thứ nhất, chúng ta đã có manh mối trong việc tìm kiếm Chúa tể của Quỷ. Rhodes Island vẫn chưa bị các thế lực bên ngoài thao túng.”","“Đừng phí thời gian. Chúng ta cần nó bắt đầu ngay bây giờ.”","“Xin Bệ hạ đừng giận, hãy nghe thần nói hết.” Confessarius cúi đầu. “‘Nàng’ đã sẵn sàng.”","@cg:avg_7_21","@cg:avg_7_22","“Sức mạnh ấy vốn thuộc về chúng ta,” Nhiếp chính nói. “Vua Sarkaz thực sự mạnh hơn bất kỳ kẻ kế vị vô danh nào.”"],"bg":"bg_uptown_1","cast":[["Kashchey","npc:avg_npc_060"],["Confessarius","npc:avg_npc_055"],["Wei Yenwu","npc:char_2005_weiyw_1"],["Regent","npc:avg_npc_062"],["Talulah","npc:avg_npc_078"]]}],"id":"main_7","no":"Chương 7","title":"Sự ra đời của bi kịch","en":"The Birth of Tragedy","sum":"Lõi đô thị Chernobog lao về phía Lungmen. W phản bội Talulah, Ch’en cắt đứt với Wei Yenwu để một mình lên đường, còn Rhodes Island lặng lẽ xâm nhập lõi đô thị, nơi Patriot và những bí mật của Talulah đang chờ."}];
